# ---- temel ayarlar ----
# tam ekran (telefon): iPhone ekranı 16:9'dan geniş (19.5:9). Tuval telefonun
# oranında açılır (ör. 1560x720) - yanlarda siyah bant kalmaz.
SCREEN_W = 1280
SAFE_X = 0


def _mobile_screen_geometry():
    """(ekran genişliği, güvenli alan payı) - sanal piksel, yükseklik 720."""
    w = h = l = r = t = 0.0
    if IS_WEB:
        try:
            d = json.loads(str(web_call("layout", default="{}") or "{}"))
            w, h = float(d.get("w") or 0), float(d.get("h") or 0)
            l, r, t = float(d.get("l") or 0), float(d.get("r") or 0), float(d.get("t") or 0)
        except Exception:
            pass
    elif os.environ.get("EVO_SCREEN"):
        # Yalnız geliştirme: "844x390x47" gibi (genişlik x yükseklik x çentik)
        try:
            parts = [float(v) for v in os.environ["EVO_SCREEN"].split("x")]
            w, h = parts[0], parts[1]
            l = r = parts[2] if len(parts) > 2 else 0.0
        except Exception:
            pass
    if w <= 0 or h <= 0:
        return 1280, 0
    W, H = max(w, h), min(w, h)
    full = int(round(720.0 * W / H / 8.0)) * 8
    full = int(max(1280, min(1688, full)))
    inset = max(l, r, t if h > w else 0.0)       # dik açıldıysa çentik üstte
    safe = int(math.ceil(inset * 720.0 / H / 2.0)) * 2
    if full - 2 * safe < 1280:
        safe = max(0, (full - 1280) // 2)
    return full, safe


if MOBILE:
    SCREEN_W, SAFE_X = _mobile_screen_geometry()
VIRTUAL_W, VIRTUAL_H = SCREEN_W - 2 * SAFE_X, 720

