# Oyun beş dilde: Türkçe, İngilizce, İspanyolca, Almanca, Rusça.
LANGS = [
    ("tr", "Türkçe"),
    ("en", "English"),
    ("es", "Español"),
    ("de", "Deutsch"),
    ("ru", "Русский"),
]
LANG_CODES = [c for c, _ in LANGS]
LANG_NAMES = dict(LANGS)
DEFAULT_LANG = "tr"


def _T(tr, en, es, de, ru):
    """Tek bir metnin beş dildeki karşılığı."""
    return (tr, en, es, de, ru)


_LANG_IDX = {c: i for i, c in enumerate(LANG_CODES)}


def lang():
    """Seçili dil kodu."""
    c = CFG.get("lang", DEFAULT_LANG)
    return c if c in _LANG_IDX else DEFAULT_LANG


def set_lang(code):
    CFG["lang"] = code if code in _LANG_IDX else DEFAULT_LANG
    # Çizilmiş yazı önbelleğini boşalt: eski dildeki görüntüler kalmasın.
    try:
        _text_cache.clear()
    except NameError:
        pass
    return CFG["lang"]


def next_lang():
    i = _LANG_IDX.get(lang(), 0)
    return set_lang(LANG_CODES[(i + 1) % len(LANG_CODES)])


def fmt_pct(v):
    """Yüzdeyi dilin kendi yazım düzenine göre biçimler."""
    try:
        n = int(round(float(v)))
    except (TypeError, ValueError):
        return str(v)
    return f"%{n}" if lang() == "tr" else f"{n}%"


def L(key, *args, **kw):
    """Anahtardan metin."""
    row = STRINGS.get(key)
    if row is None:
        return key
    i = _LANG_IDX.get(lang(), 0)
    txt = row[i] if i < len(row) and row[i] else (row[1] if i > 1 and len(row) > 1 and row[1] else row[0])
    if args or kw:
        try:
            return txt.format(*args, **kw)
        except Exception:
            return txt
    return txt


def LX(key, fallback):
    """İçerik metni: çeviri varsa onu, yoksa tablodaki Türkçe değeri verir."""
    row = STRINGS.get(key)
    if row is None:
        return TRX(fallback)
    i = _LANG_IDX.get(lang(), 0)
    txt = row[i] if i < len(row) and row[i] else (row[1] if i > 1 and len(row) > 1 and row[1] else row[0])
    return txt or TRX(fallback)


# Türkçe metin -> (en, es, de, ru). Tablolardaki içerik metinleri ve birkaç
# sabit yazı için; dosyanın sonunda doldurulur.
TEXT_TR = {}


def TRX(text):
    """Türkçe metnin seçili dildeki karşılığı (yoksa olduğu gibi)."""
    if not text:
        return text
    i = _LANG_IDX.get(lang(), 0)
    if i == 0:
        return text
    try:
        row = TEXT_TR.get(text)
    except TypeError:
        return text
    if row is None:
        return text
    return row[i - 1] or row[0] or text


# ---- içerik okuyucuları ----
# Tablolardaki Türkçe metni, varsa çevirisiyle değiştirir.


def _pick(t):
    """(tr, en, es, de, ru) demetinden seçili dilin metni; boşsa İngilizce."""
    i = _LANG_IDX.get(lang(), 0)
    return (t[i] if i < len(t) and t[i] else "") or t[1] or t[0]


