def _base_dir():
    if getattr(sys, "frozen", False):
        return os.path.dirname(os.path.abspath(sys.executable))
    return os.path.dirname(os.path.abspath(__file__))


BASE_DIR = _base_dir()
# testler için: ARENA_SAVE_DIR verilirse kayıt (ve eski kayıt yolu) yalnızca o
# klasörde aranır - her işletim sisteminde.
_FORCED_SAVE_DIR = os.environ.get("ARENA_SAVE_DIR", "").strip()
LEGACY_SAVE = (os.path.join(_FORCED_SAVE_DIR, "legacy_kasma_arena_save.json") if _FORCED_SAVE_DIR
               else os.path.join(BASE_DIR, "kasma_arena_save.json"))


def get_save_dir():
    """Kayıt dosyası kullanıcı klasörüne yazılır (PyInstaller/Steam ile uyumlu)."""
    try:
        if _FORCED_SAVE_DIR:
            os.makedirs(_FORCED_SAVE_DIR, exist_ok=True)
            return _FORCED_SAVE_DIR
        if os.name == "nt":
            base = os.environ.get("APPDATA") or os.path.expanduser("~")
            d = os.path.join(base, "KasmaArena")
        elif sys.platform == "darwin":
            d = os.path.expanduser("~/Library/Application Support/KasmaArena")
        else:
            root = os.environ.get("XDG_DATA_HOME") or os.path.expanduser("~/.local/share")
            d = os.path.join(root, "KasmaArena")
        os.makedirs(d, exist_ok=True)
        return d
    except Exception:
        return BASE_DIR


SAVE_FILE = os.path.join(get_save_dir(), "kasma_arena_save.json")

