# ---- tuş atama ----
# Steam/Epic'te tuş ataması bir erişilebilirlik gerekliliğidir, süs değil. Her
# eylemin birden fazla tuşu olabilir (W ve yukarı OK gibi).
KEY_ACTIONS = ("up", "down", "left", "right", "bonk", "dash", "use",
               "stats", "map", "shop", "restart")
DEFAULT_KEYS = {
    "up":    ["w", "up"],
    "down":  ["s", "down"],
    "left":  ["a", "left"],
    "right": ["d", "right"],
    "bonk":  ["space"],
    "dash":  ["left shift", "right shift"],
    "use":   ["e"],
    "stats": ["tab"],
    "map":   ["m"],
    "shop":  ["b"],
    "restart": ["r"],     # basılı tut = yeni koşu (Megabonk usulü)
}
# ESC (duraklat), F11 (tam ekran) ve F3 (kare sayacı) bilerek sabittir: oyuncu
# kendini oyundan çıkamaz hâle getiremesin.
KEY_LOCKED = ("escape", "f11", "f3")
_KEYCODE_CACHE = {}


def key_codes(action):
    """Eylemin pygame tuş kodları."""
    names = (CFG.get("keys") or {}).get(action) or DEFAULT_KEYS.get(action, [])
    out = []
    for nm in names:
        c = _KEYCODE_CACHE.get(nm)
        if c is None:
            try:
                c = pygame.key.key_code(nm)
            except Exception:
                c = -1
            _KEYCODE_CACHE[nm] = c
        if c >= 0:
            out.append(c)
    return out


def key_hit(action, keycode):
    """Basılan tuş bu eylemin tuşu mu?"""
    return keycode in key_codes(action)

def key_held(action, pressed):
    """Eylemin tuşlarından biri basılı mı?"""
    for c in key_codes(action):
        try:
            if pressed[c]:
                return True
        except IndexError:
            pass
    return False


def key_label(action):
    """Ekranda gösterilecek tuş yazısı: "W / YUKARI" gibi."""
    if MOBILE and action in MOBILE_KEY_LABELS:
        return MOBILE_KEY_LABELS[action]
    names = (CFG.get("keys") or {}).get(action) or DEFAULT_KEYS.get(action, [])
    return " / ".join(n.upper() for n in names) if names else "-"


def key_label_short(action):
    """Dar yerler için yalnızca ilk tuş: "SHIFT / RIGHT" değil, "SHIFT"."""
    if MOBILE and action in MOBILE_KEY_LABELS:
        return MOBILE_KEY_LABELS[action]
    names = (CFG.get("keys") or {}).get(action) or DEFAULT_KEYS.get(action, [])
    if not names:
        return "-"
    ad = str(names[0])
    for on_ek in ("left ", "right "):
        if ad.startswith(on_ek) and ad[len(on_ek):] in ("shift", "ctrl", "alt"):
            ad = ad[len(on_ek):]
    return ad.upper()

random.seed()


# yardımcı fonksiyonlar

def clamp(v, lo, hi):
    return lo if v < lo else hi if v > hi else v


def lerp(a, b, t):
    return a + (b - a) * t


def dist(x1, y1, x2, y2):
    return math.hypot(x2 - x1, y2 - y1)


def norm_dir(x1, y1, x2, y2):
    dx, dy = x2 - x1, y2 - y1
    d = math.hypot(dx, dy)
    if d < 1e-6:
        return 0.0, 0.0
    return dx / d, dy / d


def ease_out_cubic(t):
    t = clamp(t, 0.0, 1.0)
    return 1 - (1 - t) ** 3


def fmt_time(seconds):
    m = int(seconds) // 60
    s = int(seconds) % 60
    return f"{m:02d}:{s:02d}"


def fmt_num(n):
    n = int(n)
    return f"{n:,}".replace(",", ".")


def scale_col(c, k):
    return (int(clamp(c[0] * k, 0, 255)), int(clamp(c[1] * k, 0, 255)), int(clamp(c[2] * k, 0, 255)))


def mix_col(a, b, t):
    return (int(clamp(lerp(a[0], b[0], t), 0, 255)),
            int(clamp(lerp(a[1], b[1], t), 0, 255)),
            int(clamp(lerp(a[2], b[2], t), 0, 255)))


def lighten(c, t):
    return mix_col(c, (255, 255, 255), t)


def hue_col(h, s=0.72, v=1.0, steps=24):
    """Renk döngüsü (önbellek dostu olması için adımlara bölünür)."""
    h = (int(h * steps) % steps) / steps
    r, g, b = colorsys.hsv_to_rgb(h, s, v)
    return (int(r * 255), int(g * 255), int(b * 255))


def rot(px, py, ang, ox, oy):
    c, s = math.cos(ang), math.sin(ang)
    return (ox + px * c - py * s, oy + px * s + py * c)


def rot_pts(pts, ang, ox, oy):
    return [rot(x, y, ang, ox, oy) for x, y in pts]


def zigzag(x1, y1, x2, y2, segs, amp, rnd=random):
    pts = [(x1, y1)]
    dx, dy = x2 - x1, y2 - y1
    L = math.hypot(dx, dy) or 1.0
    nx, ny = -dy / L, dx / L
    for i in range(1, segs):
        f = i / segs
        off = rnd.uniform(-amp, amp)
        pts.append((x1 + dx * f + nx * off, y1 + dy * f + ny * off))
    pts.append((x2, y2))
    return pts


# font / metin
_font_cache = {}
_text_cache = {}


# ---- okunabilirlik tabanı ----
# Oyuncu: "bazı yazılar okunmuyor, bunun gibi çok yazı var." Haklıydı: 407 yazı
# çağrısının 152'si 11 puntonun altındaydı, 84'ü 10 ve altı.
UI_MIN_FONT = 12


# mobil: 1280x720'lik tuval telefonda ~0.54 ölçekle görünür; 12 punto orada 6.5
# puntoya iner. Telefonda taban yükselir, küçük-orta yazılar biraz büyür.
MOBILE_MIN_FONT = 12
MOBILE_TINY_MIN = 12


def ui_font_size(size, tiny=False):
    """Yazı puntosunu okunabilirlik tabanına yükseltir."""
    size = int(size)
    if MOBILE:
        if tiny:
            return max(size, MOBILE_TINY_MIN)
        if size < 28:
            # 8 -> 11, 10 -> 13, 12 -> 15, 14 -> 17, 18 -> 22, 24 -> 28
            return max(MOBILE_MIN_FONT, int(round(size * 1.12 + 1.5)))
        return size
    if tiny or size >= UI_MIN_FONT:
        return size
    return UI_MIN_FONT


# Arayüz yazı tipinde bulunan harfler. Dışında kalan bir işaret (★, 🔑...)
# içeren yazı sistem yazı tipiyle çizilir, kare kutu çıkmasın.
_UI_FONT_RANGES = ((0x20, 0x7E), (0xA0, 0xAC), (0xAE, 0x17F), (0x400, 0x45F),
                   (0x2013, 0x2014), (0x2018, 0x201A), (0x201C, 0x201E),
                   (0x2020, 0x2022), (0x2026, 0x2026), (0x2030, 0x2030),
                   (0x2039, 0x203A), (0x2190, 0x2193), (0x2212, 0x2212))
_ui_font_raw = {}
_glyph_ok_cache = {}


def _ui_font_bytes(bold):
    raw = _ui_font_raw.get(bold)
    if raw is None:
        try:
            raw = zlib.decompress(base64.b64decode("".join(_UI_FONT_Z[bold].split())))
        except Exception:
            raw = b""
        _ui_font_raw[bold] = raw
    return raw


def _ui_glyphs_ok(text):
    ok = _glyph_ok_cache.get(text)
    if ok is None:
        ok = True
        for ch in text:
            o = ord(ch)
            if o < 0x7F and o >= 0x20:
                continue
            if not any(a <= o <= b for a, b in _UI_FONT_RANGES):
                ok = False
                break
        if len(_glyph_ok_cache) > 6000:
            _glyph_ok_cache.clear()
        _glyph_ok_cache[text] = ok
    return ok


def font_for(text, size, bold=False):
    """Yazıyı çizecek yazı tipi: arayüz yazı tipi, harf eksikse sistem yazı tipi."""
    if _ui_glyphs_ok(text):
        return get_font(size, bold)
    return get_font(size, bold, system=True)


def get_font(size, bold=False, system=False):
    size = int(size)
    key = (size, bold, system)
    f = _font_cache.get(key)
    if f is None:
        try:
            f = None
            if not system:
                raw = _ui_font_bytes(bool(bold))
                if raw:
                    f = pygame.font.Font(io.BytesIO(raw), size)
            if f is None and (IS_WEB or MOBILE):
                # Tarayıcıda sistem yazı tipi yok: oyunla gelen Liberation Sans
                # (Arial ile aynı ölçüler) kullanılır.
                fp = _ad_asset(os.path.join("fonts", "LiberationSans-%s.ttf"
                                            % ("Bold" if bold else "Regular")))
                if fp:
                    f = pygame.font.Font(fp, size)
            if f is None:
                f = pygame.font.SysFont("segoeui,arial,helvetica,sans", size, bold=bold)
        except Exception:
            f = pygame.font.Font(None, size)
        _font_cache[key] = f
    return f


_TL_RE = None


def _web_glyphs(text):
    """Yazı tipinde olmayan işaret: "₺59" -> "59 TL"."""
    global _TL_RE
    if "₺" not in text:
        return text
    if _TL_RE is None:
        import re
        _TL_RE = re.compile(r"₺\s*(\d[\d.,]*)")
    return _TL_RE.sub(r"\1 TL", text).replace("₺", "TL")


def _render(text, size, bold, color):
    text = _web_glyphs(text)
    key = (text, size, bold, color)
    img = _text_cache.get(key)
    if img is None:
        if len(_text_cache) > (3000 if MOBILE else 900):
            _text_cache.clear()
        img = font_for(text, size, bold).render(text, True, color)
        _text_cache[key] = img
    return img


_ink_cache = {}


def _render_inked(text, size, bold, color):
    """Kalın başlık yazısı: çevresi mürekkeple çizilmiş, altında sert gölge.
    Elle boyanmış tabela gibi dursun diye bulanık gölge yok."""
    key = (text, size, bold, color)
    img = _ink_cache.get(key)
    if img is None:
        if len(_ink_cache) > (1200 if MOBILE else 500):
            _ink_cache.clear()
        top = _render(text, size, bold, color)
        ink = _render(text, size, bold, INK)
        k = 2 if size < 30 else 3
        w, h = top.get_size()
        img = pygame.Surface((w + k * 2, h + k * 3), pygame.SRCALPHA)
        for dx in range(-k, k + 1):
            for dy in range(-k, k + 1):
                if dx * dx + dy * dy <= k * k + 1:
                    img.blit(ink, (k + dx, k + dy + k))
                    img.blit(ink, (k + dx, k + dy))
        img.blit(top, (k, k))
        _ink_cache[key] = img
    return img


def draw_text(surf, text, pos, size=20, color=TEXT, bold=False,
              center=False, shadow=True, alpha=255, right=False, tiny=False):
    text = TRX(text)
    size = ui_font_size(size, tiny)
    color = (int(color[0]), int(color[1]), int(color[2]))
    alpha = int(clamp(alpha, 0, 255))
    img = _render(text, size, bold, color)
    r = img.get_rect()
    px, py = int(pos[0]), int(pos[1])
    if center:
        r.center = (px, py)
    elif right:
        r.topright = (px, py)
    else:
        r.topleft = (px, py)
    if shadow and bold and size >= 18:
        ink = _render_inked(text, size, bold, color)
        ink.set_alpha(alpha)
        k = 2 if size < 30 else 3
        surf.blit(ink, (r.x - k, r.y - k))
        return r
    img.set_alpha(alpha)
    if shadow:
        sh = _render(text, size, bold, INK)
        sh.set_alpha(alpha * 3 // 4)
        surf.blit(sh, (r.x + 1, r.y + 2))
    surf.blit(img, r)
    return r


_TW_CACHE = {}
_WRAP_CACHE = {}


def text_width(text, size=20, bold=False, tiny=False):
    # Ölçüm saf bir işlem: aynı yazı/punto hep aynı genişliği verir.
    text = TRX(text)
    key = (text, size, bold, tiny)
    w = _TW_CACHE.get(key)
    if w is None:
        if len(_TW_CACHE) > 6000:
            _TW_CACHE.clear()
        t2 = _web_glyphs(text)
        w = _TW_CACHE[key] = font_for(t2, ui_font_size(size, tiny), bold).size(t2)[0]
    return w


def text_height(size, bold=False, tiny=False):
    """Bir satırın kapladığı yükseklik - satır aralığı hesapları için."""
    return get_font(ui_font_size(size, tiny), bold).get_height()


def wrap_text(text, size, max_w, bold=False):
    text = TRX(text)
    key = (text, size, max_w, bold)
    out = _WRAP_CACHE.get(key)
    if out is None:
        if len(_WRAP_CACHE) > 2000:
            _WRAP_CACHE.clear()
        out = _WRAP_CACHE[key] = _wrap_text(text, size, max_w, bold)
    return list(out)


def _wrap_text(text, size, max_w, bold=False):
    words = text.split(" ")
    lines, line = [], ""
    for w in words:
        test = (line + " " + w).strip()
        if text_width(test, size, bold) > max_w and line:
            lines.append(line)
            line = w
        else:
            line = test
    if line:
        lines.append(line)
    return lines


def wrap_clip(text, size, max_w, lines, bold=False):
    """Satırlara böler, en çok `lines` satır döndürür ve kesildiğini belli eder."""
    out = wrap_text(text, size, max_w, bold)
    if len(out) <= lines:
        return out
    out = out[:lines]
    son = out[-1]
    while son and text_width(son + "…", size, bold) > max_w:
        son = son[:-1]
    out[-1] = son.rstrip() + "…"
    return out


# glow / disk / gölge önbellekleri (performans için sprite kullanılır)
_glow_cache = {}
_disc_cache = {}
_shadow_cache = {}


def glow_sprite(r, color, level):
    key = (r, color, level)
    s = _glow_cache.get(key)
    if s is None:
        if len(_glow_cache) > (3000 if MOBILE else 1400):
            _glow_cache.clear()
        s = pygame.Surface((r * 2, r * 2))
        s.fill((0, 0, 0))
        steps = int(min(26, max(5, r // 2 + 3)))
        k = level / 8.0
        for i in range(steps):
            f = i / (steps - 1)
            rad = max(1, int(r * (1 - f * 0.94)))
            inten = (f ** 2.3) * k
            pygame.draw.circle(s, scale_col(color, inten), (r, r), rad)
        _glow_cache[key] = s
    return s


_glow_cache_a = {}


def glow_sprite_alpha(r, color, level):
    """Saydam yüzeye basılabilen parlama."""
    key = (r, color, level)
    s = _glow_cache_a.get(key)
    if s is None:
        if len(_glow_cache_a) > 900:
            _glow_cache_a.clear()
        s = pygame.Surface((r * 2, r * 2), pygame.SRCALPHA)
        steps = int(min(26, max(5, r // 2 + 3)))
        k = level / 8.0
        for i in range(steps):
            f = i / (steps - 1)
            rad = max(1, int(r * (1 - f * 0.94)))
            inten = (f ** 2.3) * k
            # dikkat: renk tam parlaklıkta, sönümleme yalnızca alfada.
            pygame.draw.circle(s, (color[0], color[1], color[2],
                                   int(clamp(255 * inten, 0, 255))), (r, r), rad)
        _glow_cache_a[key] = s
    return s


# Saydam bir ara yüzeye (simge / yaratık gövdesi önbelleği) çizerken açılır.
_GLOW_ON_ALPHA = False


def add_glow(surf, x, y, r, color, k=1.0):
    """Parlama."""
    level = int(clamp(k, 0.0, 1.0) * 8 + 0.5)
    if level <= 0:
        return
    if MOBILE and r < 40 and not _GLOW_ON_ALPHA:
        return          # telefon: küçük parlamalar (mermi, kıvılcım) atlanır
    r = max(2, int(r) // 2 * 2)
    c = (int(color[0]), int(color[1]), int(color[2]))
    pos = (int(x - r), int(y - r))
    if _GLOW_ON_ALPHA:
        # Saydam yüzeyde normal alfa karışımı kullanılır.
        surf.blit(glow_sprite_alpha(r, c, level), pos)
    else:
        surf.blit(glow_sprite(r, c, level), pos,
                  special_flags=pygame.BLEND_RGB_ADD)


def mob_rle(s):
    """telefon: saydam önbellek yüzeyini RLE ile hızlandırır."""
    if MOBILE and s is not None:
        try:
            s.set_alpha(255, pygame.RLEACCEL)
        except Exception:
            pass
    return s


def disc_sprite(r, color, alpha):
    a = int(clamp(alpha, 0, 255)) // 16 * 16
    key = (r, color, a)
    s = _disc_cache.get(key)
    if s is None:
        if len(_disc_cache) > (3000 if MOBILE else 1400):
            _disc_cache.clear()
        s = pygame.Surface((r * 2, r * 2), pygame.SRCALPHA)
        pygame.draw.circle(s, (color[0], color[1], color[2], a), (r, r), r)
        _disc_cache[key] = mob_rle(s)
    return s


def blit_disc(surf, x, y, r, color, alpha):
    r = max(1, int(r))
    if r > 14:
        r = r // 4 * 4
    if alpha < 8:
        return
    sp = disc_sprite(r, (int(color[0]), int(color[1]), int(color[2])), alpha)
    surf.blit(sp, (int(x - r), int(y - r)))


def shadow_sprite(w):
    w = max(6, int(w) // 2 * 2)
    s = _shadow_cache.get(w)
    if s is None:
        s = pygame.Surface((w, max(4, w // 3)), pygame.SRCALPHA)
        pygame.draw.ellipse(s, (0, 0, 0, 95), s.get_rect())
        _shadow_cache[w] = mob_rle(s)
    return s


def draw_bar(surf, rect, frac, color, bg=(28, 30, 44), border=PANEL_EDGE, radius=7):
    """Dolum çubuğu: mürekkep kontur, düz dolgu, üstte tek açık şerit."""
    rect = pygame.Rect(rect)
    radius = min(radius, 4)
    pygame.draw.rect(surf, INK, rect.inflate(2, 2), border_radius=radius + 1)
    pygame.draw.rect(surf, ui_warm(bg), rect, border_radius=radius)
    frac = clamp(frac, 0.0, 1.0)
    w = int((rect.w - 4) * frac)
    if w > 2:
        inner = pygame.Rect(rect.x + 2, rect.y + 2, w, rect.h - 4)
        pygame.draw.rect(surf, color, inner, border_radius=max(1, radius - 2))
        if inner.h >= 6:
            pygame.draw.line(surf, lighten(color, 0.35), (inner.x + 2, inner.y + 1),
                             (inner.right - 3, inner.y + 1), 2 if inner.h >= 10 else 1)
            pygame.draw.line(surf, scale_col(color, 0.7), (inner.x + 1, inner.bottom - 1),
                             (inner.right - 2, inner.bottom - 1), 1)
    pygame.draw.rect(surf, INK, rect, width=2, border_radius=radius)


# ses (tamamen kod ile sentezlenir - dış dosya gerekmez)
_SR = 22050


# ---- yumuşak kenarlı çizim yardımcıları ----
# Aşağıdaki yardımcılar gfxdraw ile kenarı yumuşatır ve üst üste birkaç ton
# koyarak yüzeye hacim kazandırır (koyu kontur -> gövde -> pah ışığı -> keskin
# parlama).


def _ipts(pts):
    return [(int(round(x)), int(round(y))) for x, y in pts]


def poly_aa(surf, pts, col):
    """Kenarı yumuşatılmış dolu çokgen."""
    if len(pts) < 3:
        return
    ip = _ipts(pts)
    if _gfx is not None:
        try:
            _gfx.filled_polygon(surf, ip, col)
            _gfx.aapolygon(surf, ip, col)
            return
        except Exception:
            pass
    pygame.draw.polygon(surf, col, ip)


def poly_edge(surf, pts, col, w=1):
    """Kenarı yumuşatılmış çokgen çerçevesi."""
    if len(pts) < 3:
        return
    ip = _ipts(pts)
    if w <= 1 and _gfx is not None:
        try:
            _gfx.aapolygon(surf, ip, col)
            return
        except Exception:
            pass
    pygame.draw.polygon(surf, col, ip, max(1, int(w)))


def circle_aa(surf, cx, cy, r, col):
    """Kenarı yumuşatılmış dolu daire."""
    r = int(round(r))
    if r < 1:
        return
    cx, cy = int(round(cx)), int(round(cy))
    if _gfx is not None:
        try:
            _gfx.filled_circle(surf, cx, cy, r, col)
            _gfx.aacircle(surf, cx, cy, r, col)
            return
        except Exception:
            pass
    pygame.draw.circle(surf, col, (cx, cy), r)


def ring_aa(surf, cx, cy, r, col, w=1):
    """Kenarı yumuşatılmış çember (içi boş)."""
    r = int(round(r))
    if r < 1:
        return
    if w <= 1 and _gfx is not None:
        try:
            _gfx.aacircle(surf, int(round(cx)), int(round(cy)), r, col)
            return
        except Exception:
            pass
    pygame.draw.circle(surf, col, (int(round(cx)), int(round(cy))), r, max(1, int(w)))


def disc_grad(surf, cx, cy, r, inner, outer, steps=10):
    """Merkezden kenara doğru renk geçişli daire (madalyon tabanı gibi)."""
    for i in range(steps, 0, -1):
        f = i / float(steps)
        circle_aa(surf, cx, cy, r * f, mix_col(inner, outer, f))


def poly_inset(pts, k, dx=0.0, dy=0.0):
    """Çokgeni merkezine doğru k oranında küçültür (pah/bizote katmanı için)."""
    n = float(len(pts))
    cx = sum(p[0] for p in pts) / n
    cy = sum(p[1] for p in pts) / n
    return [(cx + (x - cx) * k + dx, cy + (y - cy) * k + dy) for x, y in pts]


def thick_line(surf, p0, p1, w, col, cap=True):
    """Kenarı yumuşak kalın çizgi - pygame.draw.line'ın basamaklı hâli yerine."""
    dx, dy = p1[0] - p0[0], p1[1] - p0[1]
    ln = math.hypot(dx, dy)
    if ln < 1e-4 or w <= 0:
        return
    nx, ny = -dy / ln * w * 0.5, dx / ln * w * 0.5
    poly_aa(surf, [(p0[0] + nx, p0[1] + ny), (p1[0] + nx, p1[1] + ny),
                   (p1[0] - nx, p1[1] - ny), (p0[0] - nx, p0[1] - ny)], col)
    if cap and w > 3:
        circle_aa(surf, p0[0], p0[1], w * 0.5, col)
        circle_aa(surf, p1[0], p1[1], w * 0.5, col)


def taper_line(surf, pts, w0, w1, col0, col1=None):
    """Kalınlığı ve rengi uçtan uca değişen yumuşak şerit (kırbaç, alev dili)."""
    col1 = col1 or col0
    n = len(pts)
    for i in range(n - 1):
        f = i / max(1.0, n - 2.0)
        thick_line(surf, pts[i], pts[i + 1], lerp(w0, w1, f),
                   mix_col(col0, col1, f))


def metal(surf, pts, base, lite=None, dark=None, spec=True, ow=2.0, lx=-0.45, ly=-0.55):
    """Çelik yüzey: kontur + gövde + pah ışığı + keskin parlama."""
    lite = lite or lighten(base, 0.58)
    dark = dark or scale_col(base, 0.42)
    poly_aa(surf, [(x, y + max(1.0, ow * 0.9)) for x, y in pts], OUTLINE)
    poly_aa(surf, pts, dark)
    poly_aa(surf, poly_inset(pts, 0.93), base)
    poly_aa(surf, poly_inset(pts, 0.58, dx=lx * ow * 1.6, dy=ly * ow * 1.6), lite)
    if spec:
        poly_aa(surf, poly_inset(pts, 0.24, dx=lx * ow * 2.4, dy=ly * ow * 2.4), WHITE)
    poly_edge(surf, pts, scale_col(base, 0.70), max(1, int(ow * 0.6)))


def wood_shaft(surf, p0, p1, w, base=(152, 106, 62)):
    """Ahşap sap: koyu kontur + gövde + damar + üst kenarda ışık."""
    dark = scale_col(base, 0.44)
    lite = lighten(base, 0.42)
    dx, dy = p1[0] - p0[0], p1[1] - p0[1]
    ln = math.hypot(dx, dy) or 1.0
    nx, ny = -dy / ln, dx / ln
    thick_line(surf, p0, p1, w + 3.0, OUTLINE)
    thick_line(surf, p0, p1, w, dark)
    off = w * 0.14
    thick_line(surf, (p0[0] + nx * off, p0[1] + ny * off),
               (p1[0] + nx * off, p1[1] + ny * off), w * 0.66, base)
    off2 = -w * 0.26
    thick_line(surf, (p0[0] + nx * off2, p0[1] + ny * off2),
               (p1[0] + nx * off2, p1[1] + ny * off2), max(1.0, w * 0.20), lite)


def leather_wrap(surf, p0, p1, w, n=4, base=(96, 62, 44)):
    """Kabza sargısı: sapın üstüne çapraz deri şeritler."""
    dx, dy = p1[0] - p0[0], p1[1] - p0[1]
    ln = math.hypot(dx, dy) or 1.0
    ux, uy = dx / ln, dy / ln
    nx, ny = -uy, ux
    seg = ln / (n + 0.6)
    for i in range(n):
        s = (i + 0.3) * seg
        a0 = (p0[0] + ux * s - nx * w * 0.55, p0[1] + uy * s - ny * w * 0.55)
        a1 = (p0[0] + ux * (s + seg * 0.62) + nx * w * 0.55,
              p0[1] + uy * (s + seg * 0.62) + ny * w * 0.55)
        thick_line(surf, a0, a1, w * 0.42, base if i % 2 == 0 else scale_col(base, 0.72))


def _env_tone(freq, dur, vol=0.4, shape="sine", f_end=None, attack=0.004,
              power=1.6, noise=0.0, vib=0.0):
    n = max(1, int(dur * _SR))
    out = [0.0] * n
    phase = 0.0
    two_pi = math.pi * 2
    att_n = max(1, int(attack * _SR))
    for i in range(n):
        t = i / n
        f = freq if f_end is None else freq + (f_end - freq) * t
        if vib:
            f *= 1 + vib * math.sin(i / _SR * 30)
        phase += f / _SR
        p = phase - int(phase)
        if shape == "sine":
            s = math.sin(two_pi * phase)
        elif shape == "square":
            s = 1.0 if p < 0.5 else -1.0
        elif shape == "saw":
            s = 2 * p - 1
        elif shape == "tri":
            s = 4 * abs(p - 0.5) - 1
        else:
            s = random.uniform(-1, 1)
        if noise:
            s = s * (1 - noise) + random.uniform(-1, 1) * noise
        a = i / att_n if i < att_n else 1.0
        out[i] = s * a * ((1 - t) ** power) * vol
    return out


def _mix(parts, total=None):
    if total is None:
        total = max(int(off * _SR) + len(s) for s, off in parts)
    out = [0.0] * total
    for s, off in parts:
        o = int(off * _SR)
        for i, v in enumerate(s):
            j = o + i
            if j >= total:
                break
            out[j] += v
    return out


def _to_bytes(samples, channels=1):
    arr = array('h')
    for v in samples:
        iv = int(clamp(v, -1.0, 1.0) * 30000)
        arr.append(iv)
        if channels == 2:
            arr.append(iv)
    return arr.tobytes()


def _arp(notes, step, dur, vol, shape="tri"):
    return [(_env_tone(f, dur, vol, shape), i * step) for i, f in enumerate(notes)]


