def _midi(n):
    return 440.0 * 2 ** ((n - 69) / 12)


def _gen_music(kind):
    bpm = 132 if kind == "battle" else 84
    beat = 60.0 / bpm
    bars = 4
    total = int(bars * 4 * beat * _SR)
    roots = [45, 41, 36, 43]
    chords = [[69, 72, 76], [65, 69, 72], [72, 76, 79], [67, 71, 74]]
    parts = []
    step = beat / 2
    for b in range(bars):
        t0 = b * 4 * beat
        ch = chords[b]
        if kind == "battle":
            for i in range(8):
                nn = roots[b] + (12 if i % 4 == 3 else 0)
                parts.append((_env_tone(_midi(nn), step * 0.92, .15, "saw", power=1.1), t0 + i * step))
            for i in range(16):
                nn = ch[[0, 1, 2, 1][i % 4]] + (12 if i % 8 >= 6 else 0)
                parts.append((_env_tone(_midi(nn), step * 0.5, .055, "tri"), t0 + i * step / 2))
            for i in range(4):
                parts.append((_env_tone(130, .16, .45, "sine", f_end=45, power=2.0), t0 + i * beat))
            for i in (1, 3):
                parts.append((_env_tone(0, .11, .15, "noise", power=2.0), t0 + i * beat))
            for i in range(8):
                parts.append((_env_tone(0, .03, .05, "noise", power=1.0), t0 + i * step + step * 0.5))
        else:
            for n in ch:
                parts.append((_env_tone(_midi(n - 12), 4 * beat * 0.98, .05, "tri", power=.6, attack=.3), t0))
            parts.append((_env_tone(_midi(roots[b]), 4 * beat * 0.9, .09, "sine", power=.8, attack=.05), t0))
            for i in range(8):
                parts.append((_env_tone(_midi(ch[i % 3] + 12), step * 0.9, .045, "sine"), t0 + i * step))
    return _mix(parts, total)


class _NullAudio:
    ok = False

    def play(self, *a, **k):
        pass

    def update(self):
        pass

    def set_music(self, *a, **k):
        pass


audio = _NullAudio()


def sfx(name, vol=1.0, gap=0.03):
    audio.play(name, vol, gap)
    tap = _SFX_TAP[0]          # 2 kişilikte ev sahibi sesleri konuğa da yollar
    if tap is not None and len(tap) < 64:
        tap.append((name, vol))


class AudioManager:
    def __init__(self, settings):
        global _SR
        self.settings = settings
        self.ok = False
        self.sounds = {}
        self.music_snd = {}
        self._raw = {}
        self._lock = threading.Lock()
        self.want_music = None
        self.cur_music = None
        self.music_ch = None
        self._last = {}
        self.channels = 1
        try:
            try:
                pygame.mixer.init(22050, -16, 1, 512, allowedchanges=0)
            except TypeError:
                pygame.mixer.init(22050, -16, 1, 512)
            info = pygame.mixer.get_init()
            if info:
                _SR = int(info[0])
                self.channels = int(info[2]) if info[2] in (1, 2) else 1
                pygame.mixer.set_num_channels(24)
                pygame.mixer.set_reserved(1)
                self.music_ch = pygame.mixer.Channel(0)
                self.ok = True
                if IS_WEB:
                    # Tarayıcıda sesleri sentezlemek saniyeler sürer (ve iş
                    # parçacığı yok): derlemede hazırlanmış OGG'ler yüklenir.
                    self._load_prerendered()
                else:
                    threading.Thread(target=self._generate, daemon=True).start()
        except Exception:
            self.ok = False

    def _generate(self):
        try:
            for name, fn in SFX_BUILDERS.items():
                raw = _to_bytes(fn(), self.channels)
                with self._lock:
                    self._raw[("sfx", name)] = raw
            for kind in ("menu", "battle"):
                raw = _to_bytes(_gen_music(kind), self.channels)
                with self._lock:
                    self._raw[("music", kind)] = raw
        except Exception:
            pass

    def _load_prerendered(self):
        d = _ad_asset("audio", want_dir=True)
        if not d:
            return
        for name in SFX_BUILDERS:
            try:
                self.sounds[name] = pygame.mixer.Sound(os.path.join(d, "sfx_%s.ogg" % name))
            except Exception:
                pass
        for kind in ("menu", "battle"):
            try:
                self.music_snd[kind] = pygame.mixer.Sound(os.path.join(d, "music_%s.ogg" % kind))
            except Exception:
                pass

    def update(self):
        if not self.ok:
            return
        with self._lock:
            items = list(self._raw.items())
            self._raw.clear()
        for (kind, name), raw in items:
            try:
                snd = pygame.mixer.Sound(buffer=raw)
            except Exception:
                continue
            if kind == "sfx":
                self.sounds[name] = snd
            else:
                self.music_snd[name] = snd
        try:
            if self.want_music != self.cur_music:
                if self.want_music is None:
                    self.music_ch.fadeout(500)
                    self.cur_music = None
                elif self.want_music in self.music_snd:
                    self.music_ch.play(self.music_snd[self.want_music], loops=-1, fade_ms=700)
                    self.cur_music = self.want_music
            self.music_ch.set_volume(clamp(self.settings.get("music_vol", 0.5), 0.0, 1.0))
        except Exception:
            pass

    def set_music(self, name):
        self.want_music = name

    def play(self, name, vol=1.0, gap=0.03):
        if not self.ok:
            return
        snd = self.sounds.get(name)
        if snd is None:
            return
        now = time.time()
        if now - self._last.get(name, 0.0) < gap:
            return
        self._last[name] = now
        try:
            snd.set_volume(clamp(vol * self.settings.get("sfx_vol", 0.7), 0.0, 1.0))
            snd.play()
        except Exception:
            pass


# kayıt sistemi

# ---- hile koruması ----
# olay: bir oyuncu kayıt dosyasını (JSON) açıp "gems": 100000 ve hasarını elle
# değiştirip dünya sıralamasına girdi:
# 1) imza - kayıt dosyası HMAC-SHA256 ile imzalanır.
# 2) elmas defteri - elmasın mevcut değeri, "kazanılan - harcanan" toplamıyla
#    tutmak zorunda.
# 3) koşu denetimi - oyun sırasında oyuncunun istatistikleri, o seviyede
#    ulaşılabilecek tavanın üstüne çıkarsa (bellek düzenleyici / değiştirilmiş
#    kod) O koşu geçersiz sayılır.
# 4) sunucu - asıl koruma burada. server.py gönderilen skoru kendi başına
#    makullük denetiminden geçirir ve imzasız istekleri reddeder.

# Yerleşik anahtar. Tek başına sır değil (oyun dosyasında duruyor); işi dosyayı
# elle düzenlemeyi anlamsız kılmak.
_SAVE_SECRET = b"kasma-arena-save-v1:8f3a1c5e9b2d47a6"


def _machine_salt():
    """Kayıt imzasını bu bilgisayara bağlayan tuz."""
    if IS_WEB:
        # Tarayıcıda kullanıcı/makine adı yok. Bu tarayıcıya özel rastgele bir
        # tuz bir kez üretilip saklanır (kayıt da aynı yerde durur).
        v = str(web_call("lsGet", "evo:salt", default="") or "")
        if len(v) < 24:
            v = secrets.token_hex(16)
            web_call("lsSet", "evo:salt", v)
        return ("web@" + v).encode("ascii")
    try:
        import getpass
        import platform
        return f"{getpass.getuser()}@{platform.node()}".encode("utf-8", "replace")
    except Exception:
        return b"anon@unknown"


# ---- kullanıcı adı kuralları ----
# Sunucudakiyle (server.py) birebir aynı olmalı.
USERNAME_MIN = 3
USERNAME_MAX = 14
PASSWORD_MIN = 8
USERNAME_BLOCK = {"admin", "administrator", "moderator", "mod", "sistem", "system",
                  "kasma", "kasmaarena", "evolve", "evolvearena", "arenabonk", "root", "null", "undefined", "anonim",
                  "isimsiz", "server", "sunucu", "support", "destek"}


def email_ok(s):
    """Basit e-posta denetimi (sunucudaki EMAIL_RE ile aynı kural)."""
    s = str(s or "").strip()
    if not (5 <= len(s) <= 254) or s.count("@") != 1 or any(c.isspace() for c in s):
        return False
    user, dom = s.split("@")
    if not user or len(user) > 64 or "." not in dom:
        return False
    tld = dom.rsplit(".", 1)[1]
    return bool(dom.rsplit(".", 1)[0]) and 2 <= len(tld) <= 24 and tld.isalpha()


def check_username(u):
    """(uygun_mu, hata_metni) döner."""
    u = str(u or "").strip()
    if len(u) < USERNAME_MIN or len(u) > USERNAME_MAX:
        return False, L("ui.acc_bad_user", USERNAME_MIN, USERNAME_MAX)
    if not all(c.isalnum() or c == "_" for c in u):
        return False, L("ui.acc_bad_user", USERNAME_MIN, USERNAME_MAX)
    if u.lower() in USERNAME_BLOCK:
        return False, L("ui.acc_user_taken")
    return True, ""


# O girdi gizli bir sır değil: iki tahmin edilebilir metin.
INSTALL_ID_FILE = os.path.join(get_save_dir(), "install_id")
_INSTALL_ID = [None]


def _install_id():
    """Bu kuruluma özel kimlik."""
    if _INSTALL_ID[0]:
        return _INSTALL_ID[0]
    try:
        with open(INSTALL_ID_FILE, "r", encoding="utf-8") as fh:
            v = fh.read().strip()
        if v == "legacy" or len(v) >= 24:
            _INSTALL_ID[0] = v
            return v
    except Exception:
        pass
    eski_oyuncu = False
    try:
        eski_oyuncu = os.path.exists(SAVE_FILE) or os.path.exists(LEGACY_SAVE)
    except Exception:
        pass
    v = "legacy" if eski_oyuncu else secrets.token_hex(16)
    try:
        d = os.path.dirname(INSTALL_ID_FILE)
        if d:
            os.makedirs(d, exist_ok=True)
        with open(INSTALL_ID_FILE, "w", encoding="utf-8") as fh:
            fh.write(v)
        web_persist(INSTALL_ID_FILE)
    except Exception:
        # Yazılamadıysa (salt-okunur klasör) kimlik yine çalışır, yalnızca her
        # açılışta değişir - o durumda oyuncu yeniden giriş yapar.
        pass
    _INSTALL_ID[0] = v
    return v


def device_id():
    """Bu kurulumun takma kimliği (hesap oturumunu makineye bağlar)."""
    v = _install_id()
    if v == "legacy":
        # Güncellemeden önce oynamaya başlamış kurulum: eski kimlik korunur,
        # yoksa oyuncu her açılışta hesabından düşer (sunucu eski kimliği
        # saklıyor ve sunucu güncellenmemiş bile olabilir).
        return device_id_legacy()
    h = hashlib.sha256(b"kasma-device-v2|" + v.encode("utf-8")).hexdigest()
    return h[:32]


def device_id_legacy():
    """eski (v1) cihaz kimliği - yalnızca geçiş için."""
    h = hashlib.sha256(b"kasma-device-v1|" + _machine_salt()).hexdigest()
    return h[:32]


def _token_box_key():
    """Jetonu kayıt dosyasında açıkta tutmamak için kullanılan makine anahtarı."""
    return hashlib.sha256(b"kasma-token-box-v1|" + _SAVE_SECRET + b"|"
                          + _machine_salt()).digest()


def seal_token(token):
    """Oturum jetonunu bu makineye bağlı biçimde sarar (xor + etiket)."""
    if not token:
        return ""
    raw = token.encode("utf-8")
    key = _token_box_key()
    out = bytes(b ^ key[i % len(key)] for i, b in enumerate(raw))
    return "v1:" + base64.urlsafe_b64encode(out).decode("ascii")


def open_token(blob):
    """Seal_token'ın tersi."""
    if not blob:
        return ""
    if not blob.startswith("v1:"):
        return ""          # eski/biçimsiz kayıt: jeton yok say, yeniden giriş istenir
    try:
        raw = base64.urlsafe_b64decode(blob[3:].encode("ascii"))
    except Exception:
        return ""
    key = _token_box_key()
    try:
        return bytes(b ^ key[i % len(key)] for i, b in enumerate(raw)).decode("utf-8")
    except UnicodeDecodeError:
        return ""          # yanlış makine -> çöz(ül)emedi


# ---- kayıt dosyası şifreleme ----
# ne yapar: kayıt dosyası düz JSON değil. Not Defteri'yle açan biri anlamsız
# bir metin görür; "gems": 0 satırını bulup 999999 yazma yolu kapanır.
SAVE_MAGIC = b"KASMA1\n"


def _keystream(key, n):
    """SHA-256 sayaç kipiyle anahtar akışı üretir (ek kütüphane gerekmez)."""
    out = bytearray()
    i = 0
    while len(out) < n:
        out += hashlib.sha256(key + i.to_bytes(8, "big")).digest()
        i += 1
    return bytes(out[:n])


def _save_key():
    """Şifreleme anahtarı makineye bağlı değildir - bilerek."""
    return hashlib.sha256(b"kasma-save-box-v1|" + _SAVE_SECRET).digest()


def encrypt_save(text):
    raw = text.encode("utf-8")
    ks = _keystream(_save_key(), len(raw))
    return SAVE_MAGIC + base64.b64encode(bytes(a ^ b for a, b in zip(raw, ks)))


def decrypt_save(blob):
    """Şifreli kaydı çözer."""
    if not blob.startswith(SAVE_MAGIC):
        return blob.decode("utf-8")
    raw = base64.b64decode(blob[len(SAVE_MAGIC):], validate=False)
    ks = _keystream(_save_key(), len(raw))
    return bytes(a ^ b for a, b in zip(raw, ks)).decode("utf-8")


def _canonical(data):
    """İmzalanacak metin: anahtarlar sıralı, imza alanları hariç."""
    clean = {k: v for k, v in data.items() if k not in ("_sig", "_sig_ver")}
    return json.dumps(clean, sort_keys=True, ensure_ascii=False,
                      separators=(",", ":"))


def sign_save(data):
    """Kayıt sözlüğünün imzası."""
    key = hashlib.sha256(_SAVE_SECRET + b"|" + _machine_salt()).digest()
    return hmac.new(key, _canonical(data).encode("utf-8"), hashlib.sha256).hexdigest()


# Dünya sıralamasına gönderilen skorun imzası. Sunucudaki SUBMIT_SECRET ile
# aynı olmalıdır.
SUBMIT_SECRET = os.environ.get("KASMA_SUBMIT_SECRET",
                               "kasma-arena-submit-v1:3d7f90ac41be6528")


# İmzaya giren alanlar. Sunucudaki _expected_sig ile birebir aynı olmalı; biri
# değişirse diğeri de değişmeli, yoksa bütün gönderiler reddedilir.
SUBMIT_SIG_FIELDS = ("name", "score", "kills", "wave", "run_time", "created_at", "diff")


def build_hash(details):
    """Koşu kartı özeti (server.py _build_hash ile birebir aynı kanonik JSON)."""
    raw = json.dumps(details, sort_keys=True, separators=(",", ":"), ensure_ascii=True)
    return hashlib.sha256(raw.encode("utf-8")).hexdigest()[:32]


def sign_submit(payload):
    """Skor gönderisinin imzası (sunucudaki doğrulamayla birebir aynı sıra). koşu kartı varsa özeti ("build") de imzaya girer."""
    fields = SUBMIT_SIG_FIELDS + (("build",) if payload.get("build") else ())
    if payload.get("platform"):
        fields = fields + ("platform",)
    # dalga kipi (süreli dalgalar) imzalı - sunucu skoru buna göre denetler
    if payload.get("wmode"):
        fields = fields + ("wmode",)
    msg = "|".join(str(payload.get(k, "")) for k in fields)
    return hmac.new(SUBMIT_SECRET.encode("utf-8"), msg.encode("utf-8"),
                    hashlib.sha256).hexdigest()


# Oyun içi hile kodu da bir hiledir: kullanıldığı anda kayıt şaibelenir ve
# dünya sıralaması kapanır. Kod oynamak için duruyor, rekor kırmak için değil.
TAINT_REASONS = {
    "signature": "kayıt dosyası dışarıdan değiştirilmiş",
    "gems": "elmas sayısı kendi geçmişiyle tutmuyor",
    "cheat_code": "oyun içi hile kodu kullanıldı",
    "stats": "istatistikler ulaşılabilir sınırın üstünde",
}


class SaveManager:
    DEFAULT = {
        "gems": 0,
        "skins_owned": ["default"],
        "equipped_skin": "default",
        "cosmetics_owned": [],
        "books_owned": [],          # görevi tamamlanıp kalıcı açılmış kitaplar
        "weapons_owned": [],        # görevi tamamlanıp kalıcı açılmış silahlar
        # Oyuncunun "bu bana gelmesin" diyerek kapattığı silahlar.
        "weapons_muted": [],
        # Oyuncunun kapattığı kitaplar - silahlardakiyle birebir aynı mantık.
        # Kapalı kitap seviye atlama ekranında çıkmaz.
        "books_muted": [],
        "save_version": 0,
        # ---- hile koruması ----
        # tainted: kayıt bir kez şaibelendiyse bir daha temizlenmez
        # taint_reasons: hangi denetimin takıldığı (oyuncuya gösterilir)
        # gems_earned / gems_spent: elmas defteri. gems bu ikisini tutmalı.
        "tainted": False,
        "taint_reasons": [],
        # kalıcı dünya sıralaması yasağı - bir kez konunca hiç kalkmaz.
        "board_banned": False,
        "ban_reasons": [],
        "gems_earned": 0,
        "gems_spent": 0,
        "equipped_cosmetics": {"hat": None, "eyewear": None, "cape": None, "pet": None},
        # hesabın satın aldığı özel pet'ler [{"id","design",...}] - sunucunun
        # listesidir (oyun buraya kendi başına bir şey eklemez).
        "custom_pets": [],
        "leaderboard": [],
        "achievements": {},
        "settings": {"fullscreen": False, "player_name": "", "music_vol": 0.5, "sfx_vol": 0.7,
                     "shake": True, "dmg": True, "fps": False, "difficulty": "normal",
                     "skill_scale": 0.85, "plain_skin": False,
                     "fps_cap": 120, "weapon_fx": WEAPON_FX_DEFAULT, "pet_show": True,
                     "lang": DEFAULT_LANG},
        "mastery": {},
        # ücretsiz elmas sayaçları (reklam + günlük hediye) - profile ait
        "rewards": {},
        "stats": {"runs": 0, "best_score": 0, "total_kills": 0, "total_time": 0.0,
                  "bosses": 0, "best_wave": 0, "total_shots": 0, "total_lifesteal": 0.0,
                  "total_gold": 0, "best_run_gold": 0, "best_run_dashes": 0,
                  "best_run_shots": 0, "total_bonk_hits": 0, "shop_max": {}},
        # ---- profiller ----
        # İlerleme hesaba ait. "guest" = girişsiz oynanan ilerleme.
        "active_profile": "guest",
        "profiles": {},
    }

    # Hangi alanlar profile (hesaba) ait?
    PROFILE_KEYS = (
        "gems", "gems_earned", "gems_spent", "mastery",
        "skins_owned", "equipped_skin",
        "cosmetics_owned", "equipped_cosmetics", "custom_pets",
        "books_owned", "weapons_owned", "weapons_muted", "books_muted",
        "achievements", "stats", "leaderboard",
        "tainted", "taint_reasons",
        "board_banned", "ban_reasons",
        "rewards",
    )

    def __init__(self):
        self.data = self._load()
        self.apply_cfg()

    def _load(self):
        merged = json.loads(json.dumps(SaveManager.DEFAULT))
        found = False
        bad_sig = False
        for path in (SAVE_FILE, LEGACY_SAVE):
            if os.path.exists(path):
                try:
                    with open(path, "rb") as f:
                        loaded = json.loads(decrypt_save(f.read()))
                    # ---- 1. katman: imza (sıkılaştırıldı) ----
                    # Steam'de gerçek bir "imza sisteminden önceki kayıt" zaten
                    # yok, o yüzden bu geçiş yoluna ihtiyaç kalmadı.
                    sig = loaded.get("_sig")
                    if sig is None or not hmac.compare_digest(
                            str(sig), sign_save(loaded)):
                        bad_sig = True
                    for k, v in loaded.items():
                        if k in ("_sig", "_sig_ver"):
                            continue
                        if isinstance(v, dict) and isinstance(merged.get(k), dict):
                            merged[k].update(v)
                        else:
                            merged[k] = v
                    found = True
                    break
                except Exception:
                    continue
        if "default" not in merged.get("skins_owned", []):
            merged.setdefault("skins_owned", []).append("default")
        merged = self._migrate(merged)

        # ---- 2. katman: elmas defteri (imzayla birlikte) ----
        if found:
            earned = int(merged.get("gems_earned", 0) or 0)
            spent = int(merged.get("gems_spent", 0) or 0)
            gems = int(merged.get("gems", 0) or 0)
            if earned or spent:
                # Defter varsa elmas ona uymak zorunda (küçük bir pay
                # toleransla: eski kayıtlardan geçişte yuvarlama olabilir).
                if abs(gems - (earned - spent)) > 2:
                    self._mark_tainted_dict(merged, "gems")
            elif not bad_sig:
                # Defteri olmayan eski kayıt: mevcut elması "kazanılmış" sayıp
                # defteri şimdi açıyoruz. Geçmişi cezalandırmıyoruz - ama
                # yalnızca imza sağlamsa.
                merged["gems_earned"] = gems
                merged["gems_spent"] = 0
            else:
                self._mark_tainted_dict(merged, "gems")

        # ---- 1. katman: imza ----
        # İmza bu bilgisayara bağlı ve katı uygulanır: tutmayan kayıt ya
        # kurcalanmıştır ya başkasından kopyalanmıştır.
        if bad_sig:
            self._mark_tainted_dict(merged, "signature")
            # Dosyanın tamamı güvenilmez: içinde saklanan diğer profillerin
            # (misafir / öteki hesaplar) kopyaları da şaibeli sayılır.
            for snap in (merged.get("profiles") or {}).values():
                if isinstance(snap, dict):
                    self._mark_tainted_dict(snap, "signature")
        return merged

    # ---- dünya sıralamasından kalıcı çıkarma ----
    # Şaibe damgası iki ayrı şey yapıyor olmalı:
    #   tainted: "bu koşuyu sıralamaya gönderme" - geçici olabilir.
    #      Tek sebebi "signature" ise masum bir açıklaması var:
    #      kayıt imzası bilgisayarın adına bağlı, adamın
    #      kullanıcı adını değiştirmesi bile imzayı bozuyor.
    #      Hesabına girince sunucudan gelen ilerleme damgayı
    #      düşürüyor.
    #   board_banned: "bu hesap bir daha ASLA dünya sıralamasına girmez"
    #      kalıcı. Yalnızca masum açıklaması olmayan
    BAN_REASONS = ("cheat_code", "gems", "stats", "run")

    @staticmethod
    def _mark_tainted_dict(data, reason):
        """Kayıt sözlüğüne şaibe damgası vurur."""
        data["tainted"] = True
        reasons = data.setdefault("taint_reasons", [])
        if reason not in reasons:
            reasons.append(reason)
        if reason in SaveManager.BAN_REASONS:
            data["board_banned"] = True
            bans = data.setdefault("ban_reasons", [])
            if reason not in bans:
                bans.append(reason)

    # ---- hile koruması: dışarıya açık yüzey ----
    def mark_tainted(self, reason):
        self._mark_tainted_dict(self.data, reason)
        self.save()
        # kalıcı yasak gerektiren sebep sunucuya hemen bildirilir.
        if reason in self.BAN_REASONS and SaveManager.on_ban is not None:
            try:
                SaveManager.on_ban(reason)
            except Exception:
                pass

    # Kalıcı yasak konduğunda çağrılır (AccountClient bağlar).
    on_ban = None

    def is_tainted(self):
        return bool(self.data.get("tainted"))

    def is_board_banned(self):
        """Dünya sıralamasından kalıcı olarak çıkarıldı mı?"""
        return bool(self.data.get("board_banned"))

    @staticmethod
    def _merge_ban_reasons(local, remote):
        out = [str(r)[:24] for r in (local or [])]
        for r in (remote or []):
            r = str(r)[:24]
            if r not in out:
                out.append(r)
        return out[:8]

    def ban_text(self):
        rs = self.data.get("ban_reasons") or self.data.get("taint_reasons") or []
        if not rs:
            return LX("ui.taint_save", "kayıt doğrulanamadı")
        return ", ".join(TAINT_REASONS.get(r, r) for r in rs)

    def taint_text(self):
        """Oyuncuya gösterilecek kısa açıklama."""
        rs = self.data.get("taint_reasons") or []
        if not rs:
            return "kayıt doğrulanamadı"
        return ", ".join(TAINT_REASONS.get(r, r) for r in rs)

    # Kayıt biçimi değiştiğinde eski kayıtları düzelten tek yer.
    SAVE_VERSION = 3

    def _migrate(self, data):
        ver = int(data.get("save_version", 0) or 0)
        if ver < 2:
            # v2: Kitaplar elmasla satın alınmıyor, görevle açılıyor.
            data["books_owned"] = []
            data["save_version"] = 2
        if ver < 3:
            # v3: başlangıç kitabı yok - temel kitaplar dâhil bütün kitaplar
            # kilitli ve her kitabın birden fazla şartı olabiliyor.
            data["books_owned"] = []
            data["save_version"] = 3
        # kaldırılmış kitaplar her yüklemede süzülür
        for lk in ("books_owned", "books_muted"):
            if isinstance(data.get(lk), list):
                data[lk] = [k for k in data[lk] if k not in REMOVED_BOOKS]
        # kaldırılmış skinler karşılığına çevrilir
        migrate_removed_skins(data)
        return data

    # ---- profiller ----
    def profile_id(self):
        return str(self.data.get("active_profile") or "guest")

    @classmethod
    def blank_profile(cls):
        """Sıfırdan bir ilerleme."""
        d = json.loads(json.dumps(SaveManager.DEFAULT))
        return {k: d[k] for k in cls.PROFILE_KEYS}

    def _snapshot_profile(self):
        return {k: json.loads(json.dumps(self.data.get(k)))
                for k in self.PROFILE_KEYS if k in self.data}

    def switch_profile(self, pid):
        """Aktif ilerlemeyi saklar, istenen profilinkini yükler."""
        pid = str(pid or "guest")
        cur = self.profile_id()
        if pid == cur:
            return False
        self.data.setdefault("profiles", {})[cur] = self._snapshot_profile()
        incoming = self.data["profiles"].get(pid) or self.blank_profile()
        blank = self.blank_profile()
        for k in self.PROFILE_KEYS:
            src = incoming[k] if k in incoming else blank.get(k)
            self.data[k] = json.loads(json.dumps(src))
        self.data["profiles"].pop(pid, None)
        self.data["active_profile"] = pid
        if "default" not in self.data.get("skins_owned", []):
            self.data.setdefault("skins_owned", []).append("default")
        self.save()
        return True

    def export_progress(self):
        """Sunucuya gönderilecek ilerleme (ayarlar hariç)."""
        return self._snapshot_profile()

    # Sunucudan gelen ilerlemede yalnızca büyüyebilen alanlar.
    GROWING_STATS = ("runs", "best_score", "total_kills", "total_time", "bosses",
                     "best_wave", "total_shots", "total_gold", "total_lifesteal",
                     "best_run_gold", "best_run_dashes", "best_run_shots",
                     "total_bonk_hits", "total_crits", "total_dashes",
                     "total_bonks", "total_healed", "best_run_heal",
                     "best_combo", "best_run_kills",
                     # harita başarımı sayaçları
                     "frost_kills", "frost_bosses", "best_frost_wave", "frost_shots",
                     "desert_dashes", "best_desert_wind", "best_desert_wave", "desert_kills",
                     "desert_bonk_hits", "jungle_snakes", "jungle_bosses", "best_jungle_time",
                     "jungle_kills",
                     # harita kilidi
                     "best_stone_wave", "best_jungle_wave", "stone_cleared",
                     # anahtarlar / efsanevi sandık
                     "total_keys", "legend_chests",
                     "total_chests", "total_cursed", "best_curse", "total_goblins")
    MERGE_LISTS = ("skins_owned", "cosmetics_owned", "books_owned", "weapons_owned")

    def import_progress(self, prog):
        """Sunucudan gelen ilerlemeyi uygular - üzerine yazmadan, birleştirerek."""
        if not isinstance(prog, dict):
            return
        # yasak alanları döngüden önce okunur (asıl açık buydu). Hile kodu +
        # çıkış + giriş = yeniden dünya sıralaması.
        was_banned = bool(self.data.get("board_banned"))
        was_reasons = list(self.data.get("ban_reasons") or [])
        if self.is_tainted():
            # şaibeli yerel kayıt: yereldeki sayılara hiç güvenilmez;
            # sunucudaki ilerleme olduğu gibi alınır.
            blank = self.blank_profile()
            was_banned = bool(self.data.get("board_banned"))
            was_reasons = list(self.data.get("ban_reasons") or [])
            for k in self.PROFILE_KEYS:
                if k in ("tainted", "taint_reasons", "board_banned", "ban_reasons"):
                    continue
                src = prog[k] if prog.get(k) is not None else blank.get(k)
                self.data[k] = json.loads(json.dumps(src))
            self.data["gems_spent"] = min(int(self.data.get("gems_spent", 0) or 0),
                                          int(self.data.get("gems_earned", 0) or 0))
            self.data["gems"] = max(0, int(self.data.get("gems_earned", 0) or 0)
                                    - self.data["gems_spent"])
            rw = self.data.get("rewards")
            self.data["rewards"] = dict(rw) if isinstance(rw, dict) else {}
            self.data["rewards"]["pid"] = self.profile_id()
            self.data["tainted"] = False
            self.data["taint_reasons"] = []
            # Yasak hiçbir yerde kalkmaz.
            self.data["board_banned"] = was_banned or bool(prog.get("board_banned"))
            self.data["ban_reasons"] = self._merge_ban_reasons(
                was_reasons, prog.get("ban_reasons")) if self.data["board_banned"] else []
            if "default" not in self.data.get("skins_owned", []):
                self.data.setdefault("skins_owned", []).append("default")
            self.save()
            return
        for k in self.PROFILE_KEYS:
            if k not in prog or prog[k] is None:
                continue
            if k in ("tainted", "taint_reasons", "board_banned", "ban_reasons"):
                continue        # aşağıda ayrıca, yalnızca sıkılaşacak yönde işlenir
            v = json.loads(json.dumps(prog[k]))
            if k in self.MERGE_LISTS and isinstance(v, list):
                cur = self.data.get(k) or []
                merged_l = cur + [x for x in v if x not in cur]
                # paralı içerik (premium skin, pet) sunucunundur: sunucunun
                # listesinde olmayan paralı öğe yerelde de tutulmaz.
                self.data[k] = [x for x in merged_l if not _is_paid_item(k, x) or x in v]
                if k == "books_owned":
                    self.data[k] = [x for x in self.data[k] if x not in REMOVED_BOOKS]
                if k == "skins_owned":
                    migrate_removed_skins(self.data)
            elif k == "stats" and isinstance(v, dict):
                cur = dict(self.data.get(k) or {})
                for sk, sv in v.items():
                    if sk in self.GROWING_STATS:
                        try:
                            cur[sk] = max(float(cur.get(sk, 0) or 0), float(sv or 0))
                            if float(cur[sk]).is_integer() and sk != "total_time":
                                cur[sk] = int(cur[sk])
                        except (TypeError, ValueError):
                            cur[sk] = sv
                    else:
                        cur.setdefault(sk, sv)
                self.data[k] = cur
            elif k == "achievements" and isinstance(v, dict):
                cur = dict(self.data.get(k) or {})
                for ak, av in v.items():
                    cur.setdefault(ak, av)
                self.data[k] = cur
            elif k == "mastery" and isinstance(v, dict):
                # arena ustalığı kademesi geri gitmez: başka bir bilgisayarda
                # alınan kademe buraya iner, buradaki de orada kaybolmaz.
                cur = dict(self.data.get(k) or {})
                for mk, mv in v.items():
                    try:
                        cur[mk] = max(int(cur.get(mk, 0) or 0), int(mv or 0))
                    except (TypeError, ValueError):
                        pass
                self.data[k] = cur
            elif k == "rewards":
                # Hesabın reklam/hediye sayaçları sunucunundur (sunucu saatiyle
                # işler): olduğu gibi alınır.
                rw = dict(v) if isinstance(v, dict) else {}
                rw["pid"] = self.profile_id()
                self.data[k] = rw
            elif k in ("gems", "gems_earned", "gems_spent"):
                continue        # aşağıda defter olarak birlikte işlenir
            else:
                self.data[k] = v
        # ---- elmas defteri ----
        earned = max(int(self.data.get("gems_earned", 0) or 0),
                     int(prog.get("gems_earned", 0) or 0))
        spent = max(int(self.data.get("gems_spent", 0) or 0),
                    int(prog.get("gems_spent", 0) or 0))
        self.data["gems_earned"] = earned
        self.data["gems_spent"] = min(spent, earned)
        self.data["gems"] = max(0, earned - self.data["gems_spent"])
        # şaibe damgası düşer. Buradaki her sayı sunucunun kendi denetiminden
        # geçmiş sayıdır; yerel dosyanın daha önce neye benzediği bir şey ifade
        # etmiyor.
        self.data["tainted"] = False
        self.data["taint_reasons"] = []
        # yasak ayrı: sunucu da biz de bir kez "yasaklı" dediysek öyle kalır.
        # İkisinden biri yeterli; hiçbir yerde False'a dönmez.
        self.data["board_banned"] = was_banned or bool(prog.get("board_banned"))
        self.data["ban_reasons"] = self._merge_ban_reasons(
            was_reasons, prog.get("ban_reasons")) if self.data["board_banned"] else []
        if "default" not in self.data.get("skins_owned", []):
            self.data.setdefault("skins_owned", []).append("default")
        self.save()

    # Kaydı aynı anda birden fazla iş parçacığı yazabilir: ana döngü bir
    # yandan, hesap eşitlemesi (push/pull_progress) öbür yandan.
    _save_lock = threading.Lock()

    def save(self):
        with SaveManager._save_lock:
            try:
                # Her yazımda imza yenilenir. Dosya dışarıdan değiştirilirse
                # imza tutmaz ve bir sonraki açılışta kayıt şaibelenir.
                self.data.pop("_sig", None)
                self.data["_sig_ver"] = 1
                self.data["_sig"] = sign_save(self.data)
                # Dosya şifreli yazılır: metin düzenleyiciyle açıp sayı
                # değiştirme yolu kapansın.
                blob = encrypt_save(json.dumps(self.data, ensure_ascii=False))
                d = os.path.dirname(SAVE_FILE)
                if d:
                    os.makedirs(d, exist_ok=True)   # klasör silinmiş olabilir
                # Geçici ad iş parçacığına özel: iki yazma çakışsa bile
                # birbirinin dosyasını almasın.
                tmp = "%s.%d.tmp" % (SAVE_FILE, threading.get_ident())
                with open(tmp, "wb") as f:
                    f.write(blob)
                    f.flush()
                    os.fsync(f.fileno())            # çökmede yarım dosya kalmasın
                os.replace(tmp, SAVE_FILE)
                web_persist(SAVE_FILE)              # web: localStorage'a da
            except Exception as e:
                print("Kayit yazilamadi:", e)
                try:
                    os.remove(tmp)
                except Exception:
                    pass

    def apply_cfg(self):
        st = self.data.get("settings", {})
        CFG["shake"] = bool(st.get("shake", True))
        CFG["dmg"] = bool(st.get("dmg", True))
        CFG["fps"] = bool(st.get("fps", False))
        CFG["skill_scale"] = float(st.get("skill_scale", 0.85))
        CFG["plain_skin"] = bool(st.get("plain_skin", False))
        CFG["auto_aim"] = bool(st.get("auto_aim", True))
        # varsayılan FPS sınırı 60 -> 120. Eski kayıtlarda kalan 60'ı bir
        # kereliğine 120'ye çekiyoruz (oyuncu sonra yine seçebilir).
        if not st.get("fps_v326"):
            st["fps_v326"] = True
            if st.get("fps_cap", 60) == 60:
                st["fps_cap"] = 120
        cap = st.get("fps_cap", 120)
        CFG["fps_cap"] = cap if cap in FPS_CHOICES else 120
        # eşya efekti artık %0-100 arası bir sayı. Eski kayıtlarda metin
        # ("full"/"dim"/"off") duruyor olabilir; onu sayıya çeviriyoruz.
        fxm = st.get("weapon_fx", WEAPON_FX_DEFAULT)
        if isinstance(fxm, str):
            fxm = WEAPON_FX_LEGACY.get(fxm, WEAPON_FX_DEFAULT)
        try:
            fxm = int(round(float(fxm)))
        except (TypeError, ValueError):
            fxm = WEAPON_FX_DEFAULT
        CFG["weapon_fx"] = int(clamp(fxm, 0, 100))
        st["weapon_fx"] = CFG["weapon_fx"]
        CFG["pet_show"] = bool(st.get("pet_show", True))
        CFG["show_quests"] = bool(st.get("show_quests", True))
        # sol üstteki silah/kitap şeridinin boyutu (%50-150)
        try:
            CFG["hud_scale"] = int(clamp(int(round(float(st.get("hud_scale", 100)))),
                                         HUD_SCALE_MIN, HUD_SCALE_MAX))
        except (TypeError, ValueError):
            CFG["hud_scale"] = 100
        # tuş atama: yalnızca tanınan eylemler ve metin olan adlar alınır;
        # bozuk bir kayıt oyunu tuşsuz bırakmasın.
        ks = st.get("keys") or {}
        temiz = {}
        if isinstance(ks, dict):
            for a in KEY_ACTIONS:
                v = ks.get(a)
                if isinstance(v, list) and v:
                    ad = [str(x)[:24] for x in v[:3] if isinstance(x, str) and x]
                    if ad:
                        temiz[a] = ad
        CFG["keys"] = temiz
        _KEYCODE_CACHE.clear()
        set_lang(st.get("lang", DEFAULT_LANG))

    # ---- elmas ----
    def add_gems(self, amount):
        """Elmas ekler/çıkarır ve elmas defterini işler."""
        amount = int(amount)
        before = int(self.data.get("gems", 0))
        after = max(0, before + amount)
        self.data["gems"] = after
        delta = after - before
        if delta >= 0:
            self.data["gems_earned"] = int(self.data.get("gems_earned", 0)) + delta
        else:
            self.data["gems_spent"] = int(self.data.get("gems_spent", 0)) - delta

    # ---- ilerleme değişti kancası ----
    # Elmas, skin, pet gibi kalıcı bir şey değiştiğinde sunucuya haber verilir.
    on_progress_change = None

    def progress_changed(self):
        self.save()
        cb = SaveManager.on_progress_change
        if cb is not None:
            try:
                cb()
            except Exception:
                pass          # eşitleme oyunun yoluna çıkmasın

    def can_spend(self):
        """Şaibeli kayıt elmas harcayamaz (satın alma / kuşanma kilitli)."""
        return not self.is_tainted()

    def get_gems(self):
        return self.data.get("gems", 0)

    # ---- arena ustalığı (koşular arası kalıcı yükseltme) ----
    def mastery_level(self, key):
        try:
            return max(0, int((self.data.get("mastery") or {}).get(key, 0)))
        except (TypeError, ValueError):
            return 0

    def mastery_next_cost(self, key):
        m = MASTERY_BY_KEY.get(key)
        return mastery_cost(m, self.mastery_level(key)) if m else 0

    def mastery_maxed(self, key):
        m = MASTERY_BY_KEY.get(key)
        return bool(m and m.get("max") and self.mastery_level(key) >= int(m["max"]))

    def buy_mastery(self, key):
        """Bir ustalık kademesi alır."""
        m = MASTERY_BY_KEY.get(key)
        if not m or not self.can_spend() or self.mastery_maxed(key):
            return False
        cost = self.mastery_next_cost(key)
        if self.get_gems() < cost:
            return False
        self.add_gems(-cost)
        mt = self.data.setdefault("mastery", {})
        mt[key] = self.mastery_level(key) + 1
        self.progress_changed()
        return True

    def mastery_spent(self):
        """Ustalığa yatırılmış toplam elmas (ekranda gösterilir)."""
        mt = self.data.get("mastery") or {}
        return sum(mastery_total_cost(k, v) for k, v in mt.items())

    def mastery_bonus(self, key):
        """Kademenin verdiği bonus (0 ise ustalık alınmamış)."""
        m = MASTERY_BY_KEY.get(key)
        return mastery_bonus(m, self.mastery_level(key)) if m else 0.0

    # ---- skinler ----
    def owns_skin(self, skin_id):
        return skin_id in self.data.get("skins_owned", ["default"])

    def buy_skin(self, skin_id, cost):
        # Premium skinler yalnızca gerçek parayla alınır; elmasla satılmaz.
        if get_skin(skin_id).get("premium"):
            return False
        if self.owns_skin(skin_id) or self.get_gems() < cost or not self.can_spend():
            return False
        self.add_gems(-cost)
        self.data.setdefault("skins_owned", ["default"]).append(skin_id)
        self.data["equipped_skin"] = skin_id
        self.progress_changed()
        return True

    def grant_skin(self, skin_id):
        """Bir skini kalıcı olarak hesaba ekler (premium satın alma sonrası)."""
        owned = self.data.setdefault("skins_owned", ["default"])
        if skin_id not in owned:
            owned.append(skin_id)
        self.progress_changed()
        return True

    def equip_skin(self, skin_id):
        self.data["equipped_skin"] = skin_id
        self.progress_changed()

    def equipped_skin_id(self):
        sid = self.data.get("equipped_skin", "default")
        return sid if self.owns_skin(sid) else "default"

    # ---- kıyafetler (kozmetik: şapka / gözlük / pelerin) ----
    def owns_cosmetic(self, cid):
        return cid in self.data.get("cosmetics_owned", [])

    def buy_cosmetic(self, cid, cost):
        if self.owns_cosmetic(cid) or self.get_gems() < cost or not self.can_spend():
            return False
        self.add_gems(-cost)
        self.data.setdefault("cosmetics_owned", []).append(cid)
        self.progress_changed()
        return True

    # ---- kitaplar ----
    def owns_book(self, key):
        """Kitap açık mı?"""
        if key in self.data.get("books_owned", []):
            return True
        bk = BOOK_BY_KEY.get(key)
        if not bk:
            return False
        return book_progress(self, bk)[2]

    def refresh_book_unlocks(self):
        """Görevi yeni tamamlanan kitapları kalıcı olarak işaretler."""
        owned = self.data.setdefault("books_owned", [])
        newly = []
        for bk in BOOKS:
            key = bk["key"]
            if key in owned:
                continue
            if book_progress(self, bk)[2]:
                owned.append(key)
                newly.append(key)
        if newly:
            self.save()
        return newly

    # ---- kitap kapatma (silahlardakiyle birebir aynı mantık) ----
    def muted_books(self):
        return list(self.data.get("books_muted", []))

    def book_muted(self, key):
        return key in self.data.get("books_muted", [])

    def max_muted_books(self):
        """Bedava 6 + Arena Ustalığı'ndan alınan (en çok +4) kitap kapatma."""
        return MAX_MUTED_BOOKS + min(4, self.mastery_level("m_bmute"))

    def max_muted_weapons(self):
        """Bedava 4 + Arena Ustalığı'ndan alınan (en çok +4) silah kapatma."""
        return MAX_MUTED_WEAPONS + min(4, self.mastery_level("m_wmute"))

    def toggle_book_mute(self, key):
        """Kitabı kapatır/açar."""
        muted = self.data.setdefault("books_muted", [])
        # oyundan kaldırılmış kitapların (İkinci Nefes) eski kapatma kaydı bir
        # hak yemesin.
        muted[:] = [k for k in muted if k in BOOK_BY_KEY]
        if key in muted:
            muted.remove(key)
            self.save()
            return False, "açıldı"
        rare = bool(BOOK_BY_KEY.get(key, {}).get("rare"))
        if rare:
            n_rare = sum(1 for k in muted if BOOK_BY_KEY.get(k, {}).get("rare"))
            if n_rare >= MAX_MUTED_RARE_BOOKS:
                return True, (f"en fazla {MAX_MUTED_RARE_BOOKS} nadir kitap "
                              "kapatabilirsin")
        if len(muted) >= self.max_muted_books():
            return True, f"en fazla {self.max_muted_books()} kitap kapatabilirsin"
        open_left = [b["key"] for b in BOOKS
                     if self.owns_book(b["key"]) and b["key"] not in muted
                     and b["key"] != key]
        if not open_left:
            return False, "son açık kitabını kapatamazsın"
        # Nadir havuzu da hiç boşalmasın: en az bir nadir açık kalmalı, yoksa
        # nadir yuvası koşu boyunca hiç dolmaz.
        if rare and not [b["key"] for b in BOOKS
                         if b.get("rare") and self.owns_book(b["key"])
                         and b["key"] not in muted and b["key"] != key]:
            return False, "son açık nadir kitabını kapatamazsın"
        muted.append(key)
        self.save()
        return True, "kapatıldı"

    def effective_muted_books(self):
        """Gerçekten uygulanan kapatma listesi."""
        muted = [k for k in self.data.get("books_muted", []) if k in BOOK_BY_KEY]
        out, n_rare = [], 0
        for k in muted:
            if BOOK_BY_KEY.get(k, {}).get("rare"):
                n_rare += 1
                if n_rare > MAX_MUTED_RARE_BOOKS:
                    continue
            out.append(k)
        return out

    def unlocked_books(self):
        """Seviye atlamada çıkabilecek kitaplar: açık ve kapatılmamış olanlar."""
        muted = self.effective_muted_books()
        return [b for b in BOOKS if self.owns_book(b["key"]) and b["key"] not in muted]

    # ---- silahlar (kitaplarla aynı mantık) ----
    def owns_weapon(self, key):
        """Silah açık mı?"""
        owned = self.data.get("weapons_owned", [])
        if key in owned:
            return True
        if key == "quake" and "mines" in owned:
            return True
        w = WEAPON_BY_KEY.get(key) if "WEAPON_BY_KEY" in globals() else None
        if not w:
            return False
        return weapon_progress(self, w)[2]

    def refresh_weapon_unlocks(self):
        """Görevi yeni tamamlanan silahları kalıcı işaretler; yenilerini döndürür."""
        owned = self.data.setdefault("weapons_owned", [])
        newly = []
        # Silah zincirleri (bir silahın şartı başka bir silah olabilir) tek
        # geçişte çözülmeyebilir; liste büyümeyi bırakana kadar dönülür.
        for _pass in range(len(BOSS_WEAPONS) + 1):
            grew = False
            for w in BOSS_WEAPONS:
                key = w["key"]
                if key in owned:
                    continue
                if weapon_progress(self, w)[2] or (key == "quake" and "mines" in owned):
                    owned.append(key)
                    newly.append(key)
                    grew = True
            if not grew:
                break
        if newly:
            self.save()
        return newly

    def muted_weapons(self):
        return list(self.data.get("weapons_muted", []))

    def weapon_muted(self, key):
        return key in self.data.get("weapons_muted", [])

    def toggle_weapon_mute(self, key):
        """Silahı kapatır/açar."""
        muted = self.data.setdefault("weapons_muted", [])
        if key in muted:
            muted.remove(key)
            self.save()
            return False, "açıldı"
        if len(muted) >= self.max_muted_weapons():
            return True, f"en fazla {self.max_muted_weapons()} silah kapatabilirsin"
        open_left = [w["key"] for w in BOSS_WEAPONS
                     if self.owns_weapon(w["key"]) and w["key"] not in muted
                     and w["key"] != key]
        if not open_left:
            return False, "son açık silahını kapatamazsın"
        muted.append(key)
        self.save()
        return True, "kapatıldı"

    def unlocked_weapons(self):
        """Seviye atlamada çıkabilecek silahlar: açık ve kapatılmamış olanlar."""
        muted = self.data.get("weapons_muted", [])
        return [w for w in BOSS_WEAPONS
                if self.owns_weapon(w["key"]) and w["key"] not in muted]

    # ---- hile kodu: yalnızca premium skinler ----
    def unlock_premium_skins(self):
        """Gerçek parayla satılan 4 premium skini hesaba ekler."""
        owned = self.data.setdefault("skins_owned", ["default"])
        added = []
        for sk in SKINS:
            if not sk.get("premium"):
                continue
            if sk["id"] not in owned:
                owned.append(sk["id"])
                added.append(sk["name"])
        if added:
            self.save()
        return added

    # ---- hile kodu: her şeyi aç ----
    def unlock_everything(self):
        """Kilitli bütün içeriği açar (skin, kıyafet, kitap, silah)."""
        added = {"skins": 0, "cosmetics": 0, "books": 0, "weapons": 0, "pets": 0}
        owned = self.data.setdefault("skins_owned", ["default"])
        for sk in SKINS:
            if sk["id"] not in owned:
                owned.append(sk["id"])
                added["skins"] += 1
        cos = self.data.setdefault("cosmetics_owned", [])
        for cm in COSMETICS:
            if cm["id"] not in cos:
                cos.append(cm["id"])
                added["cosmetics"] += 1
        for pt in PETS:
            if pt["id"] not in cos:
                cos.append(pt["id"])
                added["pets"] += 1
        books = self.data.setdefault("books_owned", [])
        for bk in BOOKS:
            if bk["key"] not in books:
                books.append(bk["key"])
                added["books"] += 1
        weapons = self.data.setdefault("weapons_owned", [])
        for w in BOSS_WEAPONS:
            if w["key"] not in weapons:
                weapons.append(w["key"])
                added["weapons"] += 1
        self.save()
        return added

    def equip_cosmetic(self, slot, cid):
        eq = self.data.setdefault("equipped_cosmetics", {"hat": None, "eyewear": None, "cape": None})
        eq[slot] = cid
        self.save()

    def unequip_cosmetic(self, slot):
        eq = self.data.setdefault("equipped_cosmetics", {"hat": None, "eyewear": None, "cape": None})
        eq[slot] = None
        self.save()

    def equipped_cosmetic_id(self, slot):
        eq = self.data.get("equipped_cosmetics", {})
        cid = eq.get(slot)
        return cid if cid and self.owns_cosmetic(cid) else None

    def cosmetics_locked(self):
        """Kuşanılmış skin kendi kostümüyle mi geliyor?"""
        return bool(get_skin(self.equipped_skin_id()).get("locks_cosmetics"))

    def equipped_cosmetics(self):
        # Premium skin kuşanıldığında oyuncunun daha önce taktığı kıyafetler
        # otomatik olarak devre dışı kalır.
        if self.cosmetics_locked():
            return {"hat": None, "eyewear": None, "cape": None}
        return {slot: self.equipped_cosmetic_id(slot) for slot in ("hat", "eyewear", "cape")}

    # ---- yerel skor tablosu ----
    def submit_score(self, name, score, kills, run_time, wave, diff="normal", skin=None, map_key=None):
        board = self.data.setdefault("leaderboard", [])
        entry = {
            "name": (name[:14] if name else "İsimsiz"),
            "score": int(score), "kills": int(kills), "time": run_time,
            "wave": wave, "diff": diff, "date": time.strftime("%d.%m.%Y"),
        }
        # tabloda koşunun skini ve haritası da görünür
        if skin:
            entry["skin"] = str(skin)
        if map_key:
            entry["map"] = str(map_key)
        board.append(entry)
        board.sort(key=lambda e: e["score"], reverse=True)
        rank = -1
        for i, e in enumerate(board):
            if e is entry:
                rank = i
        del board[10:]
        if rank >= 10:
            rank = -1
        self.save()
        return rank

    def qualifies_for_board(self, score):
        board = self.data.get("leaderboard", [])
        if len(board) < 10:
            return True
        return score > board[-1]["score"]


# steam köprüsü (opsiyonel - SteamworksPy yoksa sessizce devre dışı)

class SteamBridge:
    def __init__(self):
        self.ok = False
        self.sw = None
        try:
            from steamworks import STEAMWORKS  # SteamworksPy
            self.sw = STEAMWORKS()
            self.sw.initialize()
            self.ok = True
        except Exception:
            self.ok = False

    def set_achievement(self, ach_id):
        if not self.ok:
            return
        try:
            try:
                self.sw.UserStats.SetAchievement(ach_id)
            except Exception:
                self.sw.UserStats.SetAchievement(ach_id.encode())
            self.sw.UserStats.StoreStats()
        except Exception:
            pass

    def run_callbacks(self):
        if self.ok:
            try:
                self.sw.run_callbacks()
            except Exception:
                pass


