ULT_FREEZE_ON_CAST = 0.5


def get_skin_ult(skin_id):
    """Skinin özel yeteneği."""
    u = SKIN_ULTS.get(skin_id)
    if u is not None and "id" not in u:
        u["id"] = skin_id
    return u


