def custom_pet_label(part, opt):
    pair = CUSTOM_PET_LABELS.get(part, {}).get(opt)
    if not pair:
        return str(opt)
    return pair[0] if lang() == "tr" else pair[1]


def clean_custom_pet(d):
    """Tasarımı bilinen parçalara indirger (server.py _clean_pet_design ile aynı kural)."""
    out = json.loads(json.dumps(CUSTOM_PET_DEFAULT))
    if not isinstance(d, dict):
        return out
    for key, allowed in CUSTOM_PET_PARTS.items():
        if d.get(key) in allowed:
            out[key] = d[key]
    for key in ("col", "col2", "eye"):
        c = d.get(key)
        if isinstance(c, (list, tuple)) and len(c) == 3:
            try:
                out[key] = [int(clamp(int(v), 0, 255)) for v in c]
            except (TypeError, ValueError):
                pass
    try:
        out["size"] = round(clamp(float(d.get("size", 1.0)), 0.8, 1.3), 2)
    except (TypeError, ValueError):
        pass
    nm = "".join(ch for ch in str(d.get("name", "") or "")
                 if ch.isalnum() or ch in " _-")[:14].strip()
    out["name"] = nm or CUSTOM_PET_DEFAULT["name"]
    return out


