_CUSTOM_PET_CACHE = {}


def pet_def(pid):
    """Kimliği verilen pet'in tanımı: hazır pet ya da hesabın özel pet'i."""
    if not pid:
        return None
    pet = PET_BY_ID.get(pid)
    if pet is not None or not str(pid).startswith("pet_custom_"):
        return pet
    sv = MASTERY_SAVE[0]
    entries = (sv.data.get("custom_pets") or []) if sv is not None else []
    for e in entries:
        if isinstance(e, dict) and e.get("id") == pid:
            d = clean_custom_pet(e.get("design"))
            key = (pid, json.dumps(d, sort_keys=True))
            hit = _CUSTOM_PET_CACHE.get(pid)
            if hit is None or hit[0] != key:
                hit = (key, dict(id=pid, slot="pet", kind="custom", design=d, name=d["name"],
                                 cost=0, item_id=CUSTOM_PET_PRODUCT_ID,
                                 price_hint=CUSTOM_PET_PRICE_HINT,
                                 color=tuple(d["col"]), accent=tuple(d["col2"]),
                                 desc=_tc("Senin tasarladığın, dünyada tek pet.",
                                          "The one-of-a-kind PET you designed."),
                                 perk_text=PET_PERK_TEXT))
                _CUSTOM_PET_CACHE[pid] = hit
            return hit[1]
    return None


def owned_custom_pets():
    """Aktif profilin özel pet tanımları (sahip olunanlar)."""
    sv = MASTERY_SAVE[0]
    if sv is None:
        return []
    out = []
    for e in (sv.data.get("custom_pets") or []):
        if isinstance(e, dict) and sv.owns_cosmetic(e.get("id")):
            pd = pet_def(e.get("id"))
            if pd:
                out.append(pd)
    return out


def draw_pet_def(surf, pet, x, y, r, t, face=1, moving=False, shadow=True):
    """Hazır ya da özel pet'i çizer (tanım pet_def'ten gelir)."""
    if pet.get("kind") == "custom":
        draw_custom_pet(surf, pet.get("design"), x, y, r, t, face=face, moving=moving, shadow=shadow)
    else:
        draw_pet(surf, pet["kind"], x, y, r, t, face=face, moving=moving, col=pet["color"],
                 acc=pet["accent"], shadow=shadow)


def _pet_state_update(st, p, t):
    """Peti oyuncunun arkasında yumuşak takip ettirir (dt, çizim zamanından)."""
    dt = clamp(t - st["last"], 0.0, 0.05)
    st["last"] = t
    vx, vy = getattr(p, "vx", 0.0), getattr(p, "vy", 0.0)
    sp = math.hypot(vx, vy)
    if sp > 20:
        st["dirx"], st["diry"] = vx / sp, vy / sp
    dirx, diry = st.get("dirx", -1.0), st.get("diry", 0.0)
    gap = p.radius + 30
    tx = p.x - dirx * gap - diry * 14
    ty = p.y - diry * gap + dirx * 14 + 6
    dx, dy = tx - st["x"], ty - st["y"]
    if dx * dx + dy * dy > 640 * 640:            # portal / ışınlanma: yanına atla
        st["x"], st["y"] = tx, ty
        dx = dy = 0.0
    else:
        k = 1.0 - math.exp(-dt * 5.0)
        st["x"] += dx * k
        st["y"] += dy * k
    st["moving"] = math.hypot(dx, dy) > 7
    if abs(dx) > 4:
        st["face"] = 1 if dx > 0 else -1


def draw_run_pet(world, run, t):
    """Kuşanılmış peti dünya yüzeyine çizer (ayarlardan kapatılabilir)."""
    if not CFG.get("pet_show", True):
        return
    p = run.player
    if not p.alive:
        return
    pid = getattr(run, "_pet_id", "?")
    if pid == "?":
        try:
            pid = run.save.equipped_cosmetic_id("pet")
        except Exception:
            pid = None
        run._pet_id = pid
        run._pet = None
    pet = pet_def(pid) if pid else None
    if not pet:
        return
    st = getattr(run, "_pet", None)
    if st is None:
        st = run._pet = {"x": p.x - 40.0, "y": p.y + 8.0, "last": t, "face": 1, "moving": False}
    _pet_state_update(st, p, t)
    draw_pet_hq(world, pet, st["x"], st["y"], RUN_PET_R, t, face=st["face"], moving=st["moving"])


# oyun içi pet biraz daha büyük ve yüksek çözünürlükte çiziliyor. Pet önce
# RUN_PET_SS kat büyük çizilip yumuşak küçültülür.
RUN_PET_R = 14
RUN_PET_SS = 3
_PET_HQ_SURF = {}


def draw_pet_hq(surf, pet, x, y, r, t, face=1, moving=False):
    """Peti büyük çizip küçülterek basar (ayrıntı korunur)."""
    k = RUN_PET_SS
    half = int(r * 3.2) + 4                     # kanat / kuyruk / hâle payı
    size = half * 2
    big = _PET_HQ_SURF.get(size)
    if big is None:
        big = _PET_HQ_SURF[size] = pygame.Surface((size * k, size * k), pygame.SRCALPHA)
    big.fill((0, 0, 0, 0))
    global _GLOW_ON_ALPHA
    _GLOW_ON_ALPHA = True
    try:
        draw_pet_def(big, pet, half * k, half * k, r * k, t, face=face, moving=moving, shadow=False)
    finally:
        _GLOW_ON_ALPHA = False
    small = pygame.transform.smoothscale(big, (size, size))
    surf.blit(shadow_sprite(int(r * 2.1)), (int(x - r * 1.05), int(y + r * 0.62)))
    surf.blit(small, (int(x - half), int(y - half)))


# ---- silah görselleri (açık / kısık / kapalı) ----
def weapon_fx_pct():
    """Eşya efekti görünürlüğü, 0-100 arası tam sayı (oyuncu ayarı)."""
    v = CFG.get("weapon_fx", WEAPON_FX_DEFAULT)
    if isinstance(v, str):                       # çok eski kayıt
        v = WEAPON_FX_LEGACY.get(v, WEAPON_FX_DEFAULT)
    try:
        return int(clamp(int(round(float(v))), 0, 100))
    except (TypeError, ValueError):
        return WEAPON_FX_DEFAULT


def set_weapon_fx_pct(v):
    """Ayarı yazar (0-100 arasına kırpılır) ve değeri geri döndürür."""
    CFG["weapon_fx"] = int(clamp(int(round(float(v))), 0, 100))
    return CFG["weapon_fx"]


def weapon_fx_mode():
    """Eski üç kademeli ad - kodun geri kalanıyla uyum için."""
    v = weapon_fx_pct()
    if v <= 0:
        return "off"
    return "full" if v >= 100 else "dim"


def _wfx_begin(world, cam, need=True):
    """Efekt katmanı çizilmeden önce görüntüyü saklar (kısık görünürlükte)."""
    if not need:
        return None
    pct = weapon_fx_pct()
    if pct >= 100 or pct <= 0:
        return None
    try:
        clip = cam.clip(world.get_rect())
        return world.subsurface(clip).copy(), clip.topleft, pct
    except Exception:
        return None


def _wfx_end(world, snap):
    """Saklanan eski görüntüyü yarı saydam basar: efekt o oranda soluklaşır."""
    if snap is None:
        return
    img, pos, pct = snap
    img.set_alpha(int(clamp(255 * (1.0 - pct / 100.0), 0, 255)))
    world.blit(img, pos)


def _player_cosmetic(p, slot):
    cm = getattr(p, "cosmetics", None)
    if not cm:
        return None
    return COSMETIC_BY_ID.get(cm.get(slot))


# pelerin hareketi ("pelerin tir tir titremesin, dalgalansın").
CAPE_TURN_RATE = 6.0       # yön yumuşatma hızı (1/sn): büyük = daha çevik
CAPE_MAX_TURN = 7.0        # en hızlı dönüş (rad/sn)
CAPE_SPEED_EASE = 3.0      # hız -> dalga temposu geçişinin yumuşaklığı (1/sn)
CAPE_BASE_FREQ = 3.4       # dururken dalga temposu (rad/sn)
CAPE_RUN_FREQ = 2.2        # koşarken eklenen tempo


def _cape_motion(p, t):
    """Pelerinin (bx, by, sp, faz) durumu: geri yönü, 0..1 hız, dalga fazı."""
    ax, ay = getattr(p, "aim_dir", (0.0, 1.0)) or (0.0, 1.0)
    dbx, dby = -ax, -ay
    vx = float(getattr(p, "vx", 0.0) or 0.0)
    vy = float(getattr(p, "vy", 0.0) or 0.0)
    vl = math.hypot(vx, vy)
    if vl > 30.0:
        # koşarken pelerin rüzgârla hareketin tersine savrulur
        k = clamp((vl - 30.0) / 220.0, 0.0, 0.75)
        dbx = dbx * (1.0 - k) - vx / vl * k
        dby = dby * (1.0 - k) - vy / vl * k
    ln = math.hypot(dbx, dby)
    if ln < 1e-3:
        dbx, dby = 0.0, 1.0
    else:
        dbx, dby = dbx / ln, dby / ln
    sp_raw = clamp(float(getattr(p, "speed_now", 0.0) or 0.0) / 260.0, 0.0, 1.0)
    st = getattr(p, "_cape_st", None)
    if st is None:
        st = {"t": t, "ang": math.atan2(dby, dbx), "sp": sp_raw, "ph": 0.0}
        try:
            p._cape_st = st
        except Exception:
            # __slots__'lu önizleme nesnesi: durumsuz, sabit tempo
            return dbx, dby, sp_raw, t * (CAPE_BASE_FREQ + CAPE_RUN_FREQ * sp_raw)
    dt = t - st["t"]
    st["t"] = t
    target = math.atan2(dby, dbx)
    if dt < 0 or dt > 0.5:
        # yeni koşu / sahne: yerine otur
        st["ang"], st["sp"] = target, sp_raw
        dt = 0.0
    diff = (target - st["ang"] + math.pi) % math.tau - math.pi
    step = diff * min(1.0, dt * CAPE_TURN_RATE)
    lim = CAPE_MAX_TURN * dt
    st["ang"] += clamp(step, -lim, lim)
    st["sp"] += (sp_raw - st["sp"]) * min(1.0, dt * CAPE_SPEED_EASE)
    st["ph"] += dt * (CAPE_BASE_FREQ + CAPE_RUN_FREQ * st["sp"])
    return math.cos(st["ang"]), math.sin(st["ang"]), st["sp"], st["ph"]


def draw_cosmetic_cape(surf, p, px, py, t):
    """Pelerin - gövdenin arkasında çizilir, harekete göre dalgalanır."""
    item = _player_cosmetic(p, "cape")
    if not item:
        return
    r = p.radius
    bx, by, sp, ph = _cape_motion(p, t)
    nx, ny = -by, bx
    col, acc = item["color"], item["accent"]
    if item["id"] == "wings_angelic":
        # melek kanadı: her kanat üç sıra tüyden oluşur (uzun uçuş tüyleri,
        # orta sıra, omuzdaki kısa örtü tüyleri).
        flap = math.sin(t * 5.0)
        open_amt = 0.92 + flap * 0.22          # çırpma: açılıp kapanma
        base_ang = math.atan2(by, bx)
        sx, sy = px + bx * r * 0.28, py + by * r * 0.28
        add_glow(surf, sx + bx * r * 0.5, sy + by * r * 0.5, r * 2.2, acc,
                 .26 + .08 * math.sin(t * 3))

        def feather(cx0, cy0, ang_, length, width, fill, edge):
            """Tek bir tüy: uçta sivrilen, dipte yuvarlak bir yaprak."""
            dxf, dyf = math.cos(ang_), math.sin(ang_)
            nxf, nyf = -dyf, dxf
            pts = [
                (cx0, cy0),
                (cx0 + dxf * length * 0.35 + nxf * width, cy0 + dyf * length * 0.35 + nyf * width),
                (cx0 + dxf * length * 0.78 + nxf * width * 0.72,
                 cy0 + dyf * length * 0.78 + nyf * width * 0.72),
                (cx0 + dxf * length, cy0 + dyf * length),
                (cx0 + dxf * length * 0.78 - nxf * width * 0.52,
                 cy0 + dyf * length * 0.78 - nyf * width * 0.52),
                (cx0 + dxf * length * 0.35 - nxf * width * 0.62,
                 cy0 + dyf * length * 0.35 - nyf * width * 0.62),
            ]
            pygame.draw.polygon(surf, OUTLINE, [(a + bx, b + by) for a, b in pts])
            pygame.draw.polygon(surf, fill, pts)
            pygame.draw.polygon(surf, edge, pts, 1)
            # tüy sapı
            pygame.draw.line(surf, edge, (cx0 + dxf * length * 0.12, cy0 + dyf * length * 0.12),
                             (cx0 + dxf * length * 0.92, cy0 + dyf * length * 0.92), 1)

        base_white = lighten(col, 0.42)
        for side in (-1, 1):
            # ---- 1. sıra: uzun uçuş tüyleri (en arkada) ----
            for i in range(5):
                f = i / 4.0
                a = base_ang + side * (0.42 + open_amt * (0.26 + f * 0.62))
                L = r * (2.55 - f * 0.55)
                feather(sx, sy, a, L, r * 0.26, base_white, scale_col(acc, 0.85))
            # ---- 2. sıra: orta tüyler ----
            for i in range(4):
                f = i / 3.0
                a = base_ang + side * (0.50 + open_amt * (0.22 + f * 0.52))
                L = r * (1.62 - f * 0.34)
                feather(sx, sy, a, L, r * 0.24, lighten(col, 0.62), scale_col(acc, 0.7))
            # ---- 3. sıra: omuzdaki kısa örtü tüyleri ----
            for i in range(3):
                f = i / 2.0
                a = base_ang + side * (0.58 + open_amt * (0.18 + f * 0.40))
                L = r * (0.92 - f * 0.18)
                feather(sx, sy, a, L, r * 0.22, WHITE, acc)
            # omuz eklemi
            jx, jy = sx + math.cos(base_ang + side * 0.55) * r * 0.30,                      sy + math.sin(base_ang + side * 0.55) * r * 0.30
            pygame.draw.circle(surf, OUTLINE, (int(jx), int(jy)), max(3, int(r * 0.20)))
            pygame.draw.circle(surf, WHITE, (int(jx), int(jy)), max(2, int(r * 0.16)))
            pygame.draw.circle(surf, acc, (int(jx), int(jy)), max(2, int(r * 0.16)), 1)

        # süzülen tüy parçacıkları
        for i in range(3):
            ph = (t * 0.5 + i * 0.33) % 1.0
            fxp = sx + bx * r * (0.7 + ph * 1.5) + nx * math.sin(t * 1.6 + i * 2.1) * r * 1.1
            fyp = sy + by * r * (0.7 + ph * 1.5) + ny * math.sin(t * 1.6 + i * 2.1) * r * 1.1
            pygame.draw.circle(surf, lighten(acc, 0.5), (int(fxp), int(fyp)),
                               max(1, int(2.4 * (1.0 - ph))))
    else:
        _draw_cloth_cape(surf, p, item, px, py, t, r, bx, by, nx, ny, col, acc, sp, ph)


# ---- kumaş pelerin ----
# Pelerin omuzdan eteğe dilimlenmiş bir kumaş:
# * her dilim kendi fazıyla dalgalanır (dalga omuzdan eteğe akar), koşarken
#   pelerin uzar ve daha sert çırpar,
# * omuzdan eteğe koyulaşan renk geçişi, iki kıvrım gölgesi, bir parlak şerit,
# * kenarda işleme (accent), omuzlarda iki toka,
# * her pelerinin kendi etek biçimi (yarasa kanadı, yaprak, sarkıt, alev dili,
#   duman püskülü...) ve kendi efekti (kıvılcım, kar tanesi, şimşek, kayan
#   yıldız, düşen yaprak, çelik pul, altın parıltı...).
CAPE_SEGS = 7             # omuzdan eteğe kaç dilim
CAPE_HEM_PTS = 14         # etek çizgisinin nokta sayısı


def _cape_hem_offset(kind, u, t, r):
    """Etek çizgisinin (soldan sağa u = 0..1) pelerin yönünde ne kadar uzadığı/kısaldığı."""
    if kind == "cape_bat":
        # yarasa kanadı: dört kemik ucu arasında içe oyulmuş yaylar
        return r * 0.30 - r * 0.62 * abs(math.sin(u * math.pi * 4))
    if kind == "cape_forest":
        # yaprak dişleri
        k = (u * 6.0) % 1.0
        return r * (0.10 + 0.42 * (1.0 - abs(k - 0.5) * 2.0))
    if kind == "cape_ice":
        # sarkıtlar: uzun-kısa sivri uçlar
        k = (u * 7.0) % 1.0
        tip = 1.0 - abs(k - 0.5) * 2.0
        long_ = 0.75 if int(u * 7.0) % 2 == 0 else 0.42
        return r * (0.05 + long_ * tip ** 2.2)
    if kind == "cape_flame":
        # yalazlanan alev dilleri yavaşlatıldı (7/11 -> 3.2/4.6): alev
        # yalazlanır, titremez
        return r * (0.12 + 0.55 * abs(math.sin(u * math.pi * 4 + t * 3.2))
                    * (0.70 + 0.30 * math.sin(t * 4.6 + u * 9.0)))
    if kind == "cape_shadow":
        # dumana dönen püsküller
        return r * (0.18 + 0.48 * (0.5 + 0.5 * math.sin(u * 17.0 + t * 2.4))
                    * math.sin(math.pi * u) ** 0.5)
    if kind == "cape_royal":
        return r * 0.42 * math.sin(math.pi * u) ** 0.8
    if kind == "cape_steel":
        # plaka uçları: basamaklı
        return r * (0.10 + 0.22 * (1.0 if int(u * 5.0) % 2 == 0 else 0.0))
    if kind == "cape_red":
        # kırlangıç kuyruğu
        return r * (0.38 - 0.34 * math.sin(math.pi * u) ** 6)
    return r * 0.30 * math.sin(math.pi * u)


def _cape_spark(surf, x, y, s, col):
    """Dört kollu küçük parıltı."""
    ix, iy = int(x), int(y)
    s = max(1, int(s))
    pygame.draw.line(surf, col, (ix - s, iy), (ix + s, iy), 1)
    pygame.draw.line(surf, col, (ix, iy - s), (ix, iy + s), 1)


def _draw_cloth_cape(surf, p, item, px, py, t, r, bx, by, nx, ny, col, acc, sp=0.0, ph=None):
    """sp: yumuşatılmış hız (0..1), ph: birikmiş dalga fazı."""
    kind = item["id"]
    if ph is None:
        ph = t * CAPE_BASE_FREQ
    length = r * (1.95 + 0.50 * sp)
    amp = r * (0.15 + 0.16 * sp)
    if kind == "cape_royal":
        length *= 1.12               # ağır, uzun asalet pelerini
    elif kind == "cape_steel":
        amp *= 0.45                  # çelik ağır: az dalgalanır
    sx0, sy0 = px + bx * r * 0.22, py + by * r * 0.22

    def center(s):
        # dalga omuzdan eteğe akar; omuzda (s=0) kumaş sabit
        wv = math.sin(ph - s * 3.0) * amp * s
        al = length * s * (1.0 + 0.04 * math.sin(ph * 0.6 + 1.3) * s)
        return sx0 + bx * al + nx * wv, sy0 + by * al + ny * wv

    def half(s):
        return r * (0.80 + 0.52 * s)

    # omuzdan eteğe sol (L) ve sağ (R) kenar
    Ls, Rs, Cs = [], [], []
    for i in range(CAPE_SEGS + 1):
        s = i / CAPE_SEGS
        cx_, cy_ = center(s)
        h = half(s)
        # kenarlar merkezden biraz geç dalgalanır: kumaş kıvrılır
        flut = math.sin(ph * 1.15 - s * 3.6 + 0.8) * r * 0.08 * s
        Ls.append((cx_ + nx * (h + flut), cy_ + ny * (h + flut)))
        Rs.append((cx_ - nx * (h - flut), cy_ - ny * (h - flut)))
        Cs.append((cx_, cy_))
    hem = []
    lx, ly = Ls[-1]
    rx, ry = Rs[-1]
    for k in range(CAPE_HEM_PTS + 1):
        u = k / CAPE_HEM_PTS
        off = _cape_hem_offset(kind, u, t, r)
        hem.append((lx + (rx - lx) * u + bx * off, ly + (ry - ly) * u + by * off))
    outline = Ls + hem[1:-1] + list(reversed(Rs))

    # ---- gölge + dış hat ----
    pygame.draw.polygon(surf, OUTLINE, [(x_ + 1, y_ + 3) for x_, y_ in outline])
    pygame.draw.polygon(surf, OUTLINE, outline)

    # ---- renk geçişi: omuz açık, etek koyu (dilim dilim) ----
    top_col = lighten(col, 0.18)
    bot_col = scale_col(col, 0.58)
    if kind == "cape_flame":
        bot_col = mix_col(col, acc, 0.75)          # alev eteğe doğru sararır
    elif kind == "cape_ice":
        bot_col = lighten(col, 0.45)               # buz eteğe doğru beyazlar
    elif kind == "cape_starlight":
        top_col, bot_col = scale_col(col, 0.75), scale_col(col, 0.35)
    elif kind == "cape_shadow":
        top_col, bot_col = lighten(col, 0.10), mix_col(col, acc, 0.22)
    for i in range(CAPE_SEGS):
        f = (i + 0.5) / CAPE_SEGS
        c = mix_col(top_col, bot_col, f)
        quad = [Ls[i], Ls[i + 1], Rs[i + 1], Rs[i]]
        pygame.draw.polygon(surf, c, quad)
    pygame.draw.polygon(surf, bot_col, [Ls[-1]] + hem + [Rs[-1]])

    # ---- kıvrımlar: iki koyu gölge, bir parlak şerit ----
    def strip(u, s0=0.08):
        out = []
        for i in range(CAPE_SEGS + 1):
            s = i / CAPE_SEGS
            if s < s0:
                continue
            ax_, ay_ = Ls[i]
            cx2, cy2 = Rs[i]
            out.append((ax_ + (cx2 - ax_) * u, ay_ + (cy2 - ay_) * u))
        return out
    fold_col = scale_col(col, 0.42)
    for u in (0.34, 0.68):
        pts = strip(u + 0.05 * math.sin(ph - u * 5.0))
        if len(pts) > 1:
            pygame.draw.lines(surf, fold_col, False, pts, 2)
    shine = strip(0.20 + 0.04 * math.sin(t * 2.0))
    if len(shine) > 1 and kind not in ("cape_shadow",):
        pygame.draw.lines(surf, lighten(col, 0.42), False, shine[:max(2, len(shine) - 2)], 1)

    # ---- desen / iç efektler (kumaşın üstüne) ----
    def cloth(u, s):
        """Kumaş üzerindeki (u: soldan sağa, s: omuzdan eteğe) noktanın dünya yeri."""
        s = clamp(s, 0.0, 1.0)
        fi = s * CAPE_SEGS
        i = min(CAPE_SEGS - 1, int(fi))
        k = fi - i
        ax_ = Ls[i][0] + (Ls[i + 1][0] - Ls[i][0]) * k
        ay_ = Ls[i][1] + (Ls[i + 1][1] - Ls[i][1]) * k
        cx2 = Rs[i][0] + (Rs[i + 1][0] - Rs[i][0]) * k
        cy2 = Rs[i][1] + (Rs[i + 1][1] - Rs[i][1]) * k
        return ax_ + (cx2 - ax_) * u, ay_ + (cy2 - ay_) * u

    mx_, my_ = cloth(0.5, 0.62)
    if kind == "cape_royal":
        # altın işleme: ortadan inen baklavalar + kürk yaka
        for j in range(3):
            qx, qy = cloth(0.5, 0.30 + j * 0.22)
            d = r * 0.20
            pts = [(qx + bx * d, qy + by * d), (qx + nx * d * 0.7, qy + ny * d * 0.7),
                   (qx - bx * d, qy - by * d), (qx - nx * d * 0.7, qy - ny * d * 0.7)]
            pygame.draw.polygon(surf, acc, pts)
            pygame.draw.polygon(surf, scale_col(acc, 0.6), pts, 1)
        fur = [cloth(u, 0.06) for u in (0.0, 0.25, 0.5, 0.75, 1.0)]
        pygame.draw.lines(surf, (246, 244, 236), False, fur, max(3, int(r * 0.38)))
        for u in (0.15, 0.45, 0.8):
            fx_, fy_ = cloth(u, 0.06)
            pygame.draw.circle(surf, (30, 26, 34), (int(fx_), int(fy_)), 1)
    elif kind == "cape_starlight":
        # kumaşa işlenmiş sabit yıldızlar (göz kırpar) + aşağı kayan yıldızlar
        rnd = random.Random(7)
        for j in range(9):
            u, s = rnd.uniform(0.12, 0.88), rnd.uniform(0.12, 0.95)
            tw = 0.5 + 0.5 * math.sin(t * (2.2 + j * 0.37) + j * 1.7)
            qx, qy = cloth(u, s)
            _cape_spark(surf, qx, qy, 1 + tw * 2.2, mix_col(col, acc, 0.4 + tw * 0.6))
        for j in range(2):
            s = (t * 0.32 + j * 0.5) % 1.0
            qx, qy = cloth(0.3 + 0.4 * j, s)
            add_glow(surf, qx, qy, r * 0.7, acc, 0.45 * math.sin(math.pi * s))
            _cape_spark(surf, qx, qy, 3, acc)
    elif kind == "cape_storm":
        beat = int(t * 4.0)
        if beat % 7 == 0:
            rnd = random.Random(beat)
            u0 = rnd.uniform(0.25, 0.75)
            pts = [cloth(clamp(u0 + rnd.uniform(-0.18, 0.18), 0.1, 0.9), s / 5.0)
                   for s in range(1, 6)]
            pygame.draw.lines(surf, acc, False, pts, 2)
            pygame.draw.lines(surf, WHITE, False, pts, 1)
            add_glow(surf, pts[2][0], pts[2][1], r * 1.6, acc, 0.42)
        # bulut kıvrımları
        for j in range(3):
            qx, qy = cloth(0.2 + j * 0.3, 0.25 + 0.08 * math.sin(t * 2 + j))
            pygame.draw.circle(surf, lighten(col, 0.25), (int(qx), int(qy)), max(2, int(r * 0.16)), 1)
    elif kind == "cape_steel":
        # üst üste binen çelik pullar + kayan parlama
        for i in range(1, CAPE_SEGS):
            s = i / CAPE_SEGS
            row = [cloth(u / 4.0, s) for u in range(5)]
            pygame.draw.lines(surf, scale_col(col, 0.55), False, row, 1)
            for u in range(4):
                qx, qy = cloth((u + 0.5 + 0.5 * (i % 2)) / 4.5, s - 0.5 / CAPE_SEGS)
                pygame.draw.circle(surf, lighten(col, 0.5), (int(qx), int(qy)), 1)
        sw = (t * 0.45) % 1.6
        if sw < 1.0:
            band = [cloth(u / 4.0, sw) for u in range(5)]
            pygame.draw.lines(surf, WHITE, False, band, 2)
    elif kind == "cape_forest":
        # yaprak damarları
        for j in range(4):
            qx, qy = cloth(0.22 + (j % 2) * 0.55, 0.28 + j * 0.17)
            ang = math.atan2(by, bx) + (0.6 if j % 2 else -0.6)
            dx_, dy_ = math.cos(ang) * r * 0.32, math.sin(ang) * r * 0.32
            pygame.draw.ellipse(surf, lighten(col, 0.25),
                                (int(qx - r * 0.18), int(qy - r * 0.18), int(r * 0.36), int(r * 0.36)))
            pygame.draw.line(surf, acc, (qx - dx_ * 0.5, qy - dy_ * 0.5), (qx + dx_ * 0.5, qy + dy_ * 0.5), 1)
    elif kind == "cape_bat":
        # kanat kemikleri: omuzdan her uca
        for j in range(5):
            u = j / 4.0
            hx, hy = hem[int(round(u * CAPE_HEM_PTS))]
            ox_, oy_ = cloth(0.5 + (u - 0.5) * 0.3, 0.05)
            pygame.draw.line(surf, scale_col(acc, 0.7), (ox_, oy_), (hx, hy), 1)
        add_glow(surf, mx_, my_, r * 1.4, acc, 0.22 + 0.08 * math.sin(t * 3))
    elif kind == "cape_pink":
        for j in range(4):
            s = (t * 0.25 + j * 0.25) % 1.0
            qx, qy = cloth(0.25 + 0.5 * ((j * 0.37) % 1.0), s)
            hr = max(2, int(r * 0.13))
            pygame.draw.circle(surf, acc, (int(qx - hr * 0.6), int(qy)), hr)
            pygame.draw.circle(surf, acc, (int(qx + hr * 0.6), int(qy)), hr)
            pygame.draw.polygon(surf, acc, [(qx - hr * 1.5, qy + 1), (qx + hr * 1.5, qy + 1),
                                            (qx, qy + hr * 2.0)])

    # ---- kenar işlemesi ----
    trim_w = 3 if kind in ("cape_gold_trim", "cape_royal") else 2
    pygame.draw.lines(surf, acc, False, Ls + hem[1:-1] + list(reversed(Rs)), trim_w)
    if kind in ("cape_gold_trim", "cape_royal"):
        pygame.draw.lines(surf, lighten(acc, 0.45), False, Ls[1:] + hem[1:-1], 1)
        # kenar boyunca dolaşan altın parıltı
        edge = Ls + hem[1:-1] + list(reversed(Rs))
        k = (t * 0.55) % 1.0
        gx, gy = edge[int(k * (len(edge) - 1))]
        add_glow(surf, gx, gy, r * 1.0, acc, 0.65)
        _cape_spark(surf, gx, gy, 4, WHITE)

    # ---- etek efektleri ----
    if kind == "cape_flame":
        add_glow(surf, mx_, my_, r * 2.0, acc, 0.30 + 0.10 * math.sin(t * 9))
        for k in range(1, CAPE_HEM_PTS, 2):
            hx, hy = hem[k]
            add_glow(surf, hx, hy, r * 0.6, (255, 140, 40), 0.35)
        for j in range(5):                      # yükselen kıvılcımlar
            ph = (t * 0.9 + j * 0.2) % 1.0
            hx, hy = hem[(j * 3) % len(hem)]
            ex = hx + bx * r * ph * 1.4 + nx * math.sin(t * 5 + j * 2.0) * r * 0.4
            ey = hy + by * r * ph * 1.4 + ny * math.sin(t * 5 + j * 2.0) * r * 0.4
            blit_disc(surf, ex, ey, max(1, int(2.6 * (1.0 - ph))), (255, 200, 90), 230 * (1.0 - ph))
    elif kind == "cape_ice":
        for k in range(0, CAPE_HEM_PTS + 1, 2):
            hx, hy = hem[k]
            tw = 0.5 + 0.5 * math.sin(t * 4.0 + k)
            if tw > 0.7:
                _cape_spark(surf, hx, hy, 2 + tw * 2, WHITE)
        for j in range(3):                      # soğuk buhar
            ph = (t * 0.5 + j * 0.33) % 1.0
            hx, hy = hem[(j * 5 + 2) % len(hem)]
            blit_disc(surf, hx + bx * r * ph * 1.2, hy + by * r * ph * 1.2,
                      r * (0.14 + ph * 0.30), (220, 240, 255), 55 * (1.0 - ph))
        add_glow(surf, mx_, my_, r * 1.6, acc, 0.20)
    elif kind == "cape_shadow":
        add_glow(surf, mx_, my_, r * 1.8, acc, 0.30 + 0.08 * math.sin(t * 2.5))
        for j in range(5):                      # eteğinden kopan duman
            ph = (t * 0.6 + j * 0.2) % 1.0
            hx, hy = hem[(j * 3 + 1) % len(hem)]
            wx = hx + bx * r * ph * 1.6 + nx * math.sin(t * 2 + j * 1.9) * r * 0.5
            wy = hy + by * r * ph * 1.6 + ny * math.sin(t * 2 + j * 1.9) * r * 0.5
            blit_disc(surf, wx, wy, r * (0.22 + ph * 0.5), mix_col(col, acc, 0.35), 150 * (1.0 - ph))
    elif kind == "cape_forest":
        for j in range(2):                      # düşen yapraklar
            ph = (t * 0.35 + j * 0.5) % 1.0
            hx, hy = hem[(j * 7 + 3) % len(hem)]
            lx_ = hx + bx * r * ph * 2.2 + nx * math.sin(t * 3 + j * 3) * r * 0.7
            ly_ = hy + by * r * ph * 2.2 + ny * math.sin(t * 3 + j * 3) * r * 0.7
            a = int(220 * (1.0 - ph))
            if a > 20:
                pygame.draw.ellipse(surf, lighten(col, 0.3), (int(lx_ - 3), int(ly_ - 2), 6, 4))
    elif kind == "cape_storm":
        add_glow(surf, mx_, my_, r * 1.5, acc, 0.18)
    elif kind == "cape_red":
        # rüzgârda dalgalanan kahraman pelerini: koşarken uçuşan kenar
        # çizgileri
        if sp > 0.35:
            for j in range(3):
                hx, hy = hem[2 + j * 5]
                d = r * (0.6 + 0.4 * math.sin(t * 9 + j))
                pygame.draw.line(surf, lighten(acc, 0.3), (hx, hy),
                                 (hx + bx * d, hy + by * d), 1)
    elif kind == "cape_pink":
        for k in range(1, CAPE_HEM_PTS, 3):
            hx, hy = hem[k]
            tw = 0.5 + 0.5 * math.sin(t * 5.0 + k * 1.3)
            if tw > 0.6:
                _cape_spark(surf, hx, hy, 1 + tw * 2.5, WHITE)

    # ---- omuz tokaları (gövdenin kenarında görünür) ----
    clasp = acc if kind not in ("cape_gold_trim", "cape_royal", "cape_red") else GOLD
    if kind == "cape_red":
        clasp = (232, 186, 90)
    for side in (1, -1):
        cx_, cy_ = sx0 + nx * side * r * 0.86, sy0 + ny * side * r * 0.86
        pygame.draw.circle(surf, OUTLINE, (int(cx_), int(cy_)), max(3, int(r * 0.24)))
        pygame.draw.circle(surf, clasp, (int(cx_), int(cy_)), max(2, int(r * 0.18)))
        pygame.draw.circle(surf, lighten(clasp, 0.55), (int(cx_ - 1), int(cy_ - 1)), 1)


def draw_cosmetic_hat(surf, p, px, py, t):
    """Şapka - kafanın üstünde, gövdeden sonra çizilir."""
    item = _player_cosmetic(p, "hat")
    if not item:
        return
    r = p.radius
    col, acc = item["color"], item["accent"]
    dark = scale_col(col, 0.62)
    lite = lighten(col, 0.34)

    if item["id"] == "cap_red":
        # Klasik beyzbol şapkası: siperlik tacın ön kenarından çıkar ve nişan
        # yönüne döner (kopuk bir yuvarlak değil, gerçek bir siperlik).
        cy = py - r * 0.58
        ax, ay = p.aim_dir
        ang = math.atan2(ay, ax)
        ca, sa = math.cos(ang), math.sin(ang)
        visor_local = [(r * 0.05, -r * 0.52), (r * 0.78, -r * 0.42), (r * 1.20, -r * 0.15),
                       (r * 1.20, r * 0.15), (r * 0.78, r * 0.42), (r * 0.05, r * 0.52)]
        vpts = [(px + lx * ca - ly * sa, cy + r * 0.26 + lx * sa + ly * ca) for lx, ly in visor_local]
        pygame.draw.polygon(surf, OUTLINE, [(x_, y_ + 2) for x_, y_ in vpts])
        pygame.draw.polygon(surf, dark, vpts)
        pygame.draw.line(surf, scale_col(col, 0.88), vpts[1], vpts[2], 2)
        pygame.draw.circle(surf, OUTLINE, (int(px), int(cy)), int(r * 0.77))
        pygame.draw.circle(surf, col, (int(px), int(cy)), int(r * 0.72))
        seam = pygame.Rect(int(px - r * 0.72), int(cy - r * 0.72), int(r * 1.44), int(r * 1.44))
        pygame.draw.arc(surf, dark, seam, 0.55, 2.60, 2)
        pygame.draw.circle(surf, lite, (int(px - r * 0.26), int(cy - r * 0.32)), max(2, int(r * 0.22)))
        pygame.draw.circle(surf, OUTLINE, (int(px), int(cy - r * 0.68)), max(3, int(r * 0.13)))
        pygame.draw.circle(surf, acc, (int(px), int(cy - r * 0.68)), max(2, int(r * 0.10)))

    elif item["id"] == "cap_blue":
        # Düz siperlikli "snapback": kırmızı şapkadan belirgin biçimde farklı,
        # köşeli bir taç ve geniş düz siperlik.
        cy = py - r * 0.60
        ax, ay = p.aim_dir
        ang = math.atan2(ay, ax)
        ca, sa = math.cos(ang), math.sin(ang)
        # düz, geniş ve köşeli siperlik - tacın ön alt kenarına yapışık
        visor_local = [(0.0, -r * 0.56), (r * 1.26, -r * 0.44), (r * 1.28, r * 0.44),
                       (0.0, r * 0.56)]
        vpts = [(px + lx * ca - ly * sa, cy + r * 0.40 + lx * sa + ly * ca) for lx, ly in visor_local]
        pygame.draw.polygon(surf, OUTLINE, [(x_, y_ + 2) for x_, y_ in vpts])
        pygame.draw.polygon(surf, dark, vpts)
        pygame.draw.line(surf, lighten(col, 0.18), vpts[0], vpts[1], 2)
        crown = pygame.Rect(int(px - r * 0.62), int(cy - r * 0.64), int(r * 1.24), int(r * 1.10))
        pygame.draw.rect(surf, OUTLINE, crown.inflate(4, 4), border_radius=max(4, int(r * 0.34)))
        pygame.draw.rect(surf, col, crown, border_radius=max(4, int(r * 0.34)))
        pygame.draw.line(surf, dark, (int(px), crown.y + 4), (int(px), crown.bottom - 4), 2)
        pygame.draw.rect(surf, lite, (crown.x + 4, crown.y + 4, max(3, int(r * 0.40)), max(3, int(r * 0.28))),
                         border_radius=3)
        pygame.draw.circle(surf, acc, (int(px), int(crown.y + 1)), max(2, int(r * 0.10)))

    elif item["id"] == "wizard_hat":
        # Ucu hafif kıvrık külah + yıldızlı bant.
        by = py - r - 2
        tip_sway = math.sin(t * 1.6) * 3.0
        tip = (px + 4 + tip_sway, by - 32)
        mid = (px + 1, by - 14)
        left, right = (px - 15, by + 6), (px + 15, by + 6)
        pts = [left, right, tip, mid]
        pygame.draw.polygon(surf, OUTLINE, [(x_, y_ + 2) for x_, y_ in pts])
        pygame.draw.polygon(surf, col, pts)
        pygame.draw.polygon(surf, dark, [mid, tip, (tip[0] - 4, tip[1] + 4)])
        pygame.draw.line(surf, lite, left, (tip[0] - 2, tip[1] + 3), 2)
        band = pygame.Rect(int(px - 16), int(by - 2), 32, max(4, int(r * 0.22)))
        pygame.draw.rect(surf, OUTLINE, band.inflate(2, 2), border_radius=3)
        pygame.draw.rect(surf, dark, band, border_radius=3)
        pygame.draw.ellipse(surf, OUTLINE, (int(px - 18), int(by + 1), 36, 10))
        pygame.draw.ellipse(surf, col, (int(px - 17), int(by + 2), 34, 8))
        pygame.draw.ellipse(surf, lite, (int(px - 15), int(by + 3), 30, 3))
        add_glow(surf, tip[0], tip[1] + 2, 12, acc, .55 + .18 * math.sin(t * 5))
        pygame.draw.circle(surf, acc, (int(tip[0]), int(tip[1] + 2)), 3)
        for i in range(3):
            sx = px - 10 + i * 10
            sy = by - 1 + (i % 2) * 3
            tw = 1 + max(0.0, math.sin(t * 4 + i * 2.1)) * 1.6
            pygame.draw.circle(surf, acc, (int(sx), int(sy)), int(tw))

    elif item["id"] == "crown_gold":
        # Beş uçlu taç: uçlarda taşlar, altta kalın bant.
        by = py - r - 3
        pts = [(px - 13, by + 9), (px - 13, by - 1), (px - 6, by + 6), (px, by - 9),
               (px + 6, by + 6), (px + 13, by - 1), (px + 13, by + 9)]
        pygame.draw.polygon(surf, OUTLINE, [(x_, y_ + 2) for x_, y_ in pts])
        pygame.draw.polygon(surf, col, pts)
        pygame.draw.polygon(surf, acc, pts, 1)
        band = pygame.Rect(int(px - 14), int(by + 7), 28, max(4, int(r * 0.24)))
        pygame.draw.rect(surf, OUTLINE, band.inflate(2, 2), border_radius=2)
        pygame.draw.rect(surf, dark, band, border_radius=2)
        pygame.draw.line(surf, lite, (band.x + 2, band.y + 1), (band.right - 2, band.y + 1), 1)
        gems = ((px, by - 6, (230, 60, 90)), (px - 13, by - 1, (90, 190, 255)), (px + 13, by - 1, (120, 235, 150)))
        for gx, gy, gc in gems:
            pygame.draw.circle(surf, OUTLINE, (int(gx), int(gy)), 3)
            pygame.draw.circle(surf, gc, (int(gx), int(gy)), 2)
        add_glow(surf, px, by, 18, col, .40 + .18 * math.sin(t * 3.4))

    elif item["id"] == "halo_ring":
        # Çift halka + yumuşak nabız; hafifçe süzülür.
        bob = math.sin(t * 2.0) * 1.8
        hy = py - r - 16 + bob
        add_glow(surf, px, hy, 22, col, .5 + .14 * math.sin(t * 4))
        pygame.draw.ellipse(surf, scale_col(acc, 0.55), (int(px - 18), int(hy - 5), 36, 11), 3)
        pygame.draw.ellipse(surf, acc, (int(px - 16), int(hy - 4), 32, 9), 2)
        pygame.draw.ellipse(surf, lighten(acc, 0.5), (int(px - 12), int(hy - 3), 24, 4), 1)
        for i in range(3):
            a = t * 1.4 + i * math.tau / 3
            sx = px + math.cos(a) * 17
            sy = hy + math.sin(a) * 4.5
            pygame.draw.circle(surf, acc, (int(sx), int(sy)), 1 + int(max(0.0, math.sin(t * 5 + i)) * 1.5))

    elif item["id"] == "beanie_gray":
        # Örgü bere: dokulu gövde, katlı bant ve ponpon.
        cy = py - r * 0.64
        pygame.draw.circle(surf, OUTLINE, (int(px), int(cy)), int(r * 0.74))
        pygame.draw.circle(surf, col, (int(px), int(cy)), int(r * 0.69))
        for i in range(-2, 3):
            kx = px + i * r * 0.24
            pygame.draw.line(surf, dark, (int(kx), int(cy - r * 0.55)), (int(kx), int(cy + r * 0.34)), 1)
        pygame.draw.circle(surf, lite, (int(px - r * 0.26), int(cy - r * 0.30)), max(2, int(r * 0.20)))
        band = pygame.Rect(0, 0, int(r * 1.48), int(r * 0.34))
        band.center = (int(px), int(cy + r * 0.44))
        pygame.draw.ellipse(surf, OUTLINE, band.inflate(3, 3))
        pygame.draw.ellipse(surf, dark, band)
        pygame.draw.ellipse(surf, lighten(col, 0.18), (band.x + 2, band.y + 1, band.w - 4, max(2, band.h // 2)))
        pom = (int(px), int(cy - r * 0.78 + math.sin(t * 2.4) * 1.2))
        pygame.draw.circle(surf, OUTLINE, pom, max(4, int(r * 0.20)))
        pygame.draw.circle(surf, acc, pom, max(3, int(r * 0.17)))
        pygame.draw.circle(surf, lighten(acc, 0.4), (pom[0] - 1, pom[1] - 1), max(1, int(r * 0.07)))

    elif item["id"] == "viking_helm":
        # Miğfer + burun koruması + kıvrık boynuzlar + perçinler.
        cy = py - r * 0.60
        pygame.draw.circle(surf, OUTLINE, (int(px), int(cy)), int(r * 0.70))
        pygame.draw.circle(surf, col, (int(px), int(cy)), int(r * 0.64))
        pygame.draw.circle(surf, lite, (int(px - r * 0.24), int(cy - r * 0.28)), max(2, int(r * 0.18)))
        rim = pygame.Rect(0, 0, int(r * 1.32), int(r * 0.26))
        rim.center = (int(px), int(cy + r * 0.40))
        pygame.draw.ellipse(surf, OUTLINE, rim.inflate(3, 3))
        pygame.draw.ellipse(surf, dark, rim)
        pygame.draw.rect(surf, OUTLINE, (int(px - 4), int(cy - r * 0.08), 8, int(r * 0.72)))
        pygame.draw.rect(surf, dark, (int(px - 3), int(cy - r * 0.08), 6, int(r * 0.70)))
        for s in (-1, 1):
            pygame.draw.circle(surf, dark, (int(px + s * r * 0.40), int(cy + r * 0.20)), max(2, int(r * 0.08)))
            hx0 = px + s * r * 0.52
            hy0 = cy - r * 0.16
            pts = [(hx0, hy0 + 4),
                   (hx0 + s * 7, hy0 - 12),
                   (hx0 + s * 19, hy0 - 19),
                   (hx0 + s * 15, hy0 - 8),
                   (hx0 + s * 17, hy0 + 2),
                   (hx0 + s * 7, hy0 + 6)]
            pygame.draw.polygon(surf, OUTLINE, [(x_ + s, y_ + 1) for x_, y_ in pts])
            pygame.draw.polygon(surf, acc, pts)
            pygame.draw.polygon(surf, scale_col(acc, 0.7), pts, 1)
            pygame.draw.line(surf, scale_col(acc, 0.72), (hx0 + s * 8, hy0 - 10), (hx0 + s * 15, hy0 - 14), 1)

    elif item["id"] == "ninja_hood":
        # Kukuleta + göz açıklığı bandı + arkada uçuşan kuşak.
        cy = py - r * 0.55
        tail = math.sin(t * 2.6) * r * 0.18
        pts = [(px - r * 0.78, cy + r * 0.38), (px - r * 0.62, cy - r * 0.58),
               (px, cy - r * 0.90), (px + r * 0.62, cy - r * 0.58), (px + r * 0.78, cy + r * 0.38)]
        pygame.draw.polygon(surf, OUTLINE, [(x_, y_ + 2) for x_, y_ in pts])
        pygame.draw.polygon(surf, col, pts)
        pygame.draw.polygon(surf, lighten(col, 0.22),
                            [(px - r * 0.52, cy - r * 0.40), (px, cy - r * 0.82), (px + r * 0.06, cy - r * 0.46)])
        band = pygame.Rect(0, 0, int(r * 1.54), int(r * 0.30))
        band.center = (int(px), int(cy + r * 0.16))
        pygame.draw.ellipse(surf, OUTLINE, band.inflate(3, 3), 3)
        pygame.draw.ellipse(surf, acc, band, 2)
        kx, ky = px + r * 0.70, cy + r * 0.10
        pygame.draw.lines(surf, OUTLINE, False,
                          [(kx, ky), (kx + r * 0.30, ky + r * 0.22), (kx + r * 0.56, ky + r * 0.10 + tail)], 5)
        pygame.draw.lines(surf, acc, False,
                          [(kx, ky), (kx + r * 0.30, ky + r * 0.22), (kx + r * 0.56, ky + r * 0.10 + tail)], 2)

    elif item["id"] == "flower_crown":
        # Gerçek taç yapraklı çiçekler + aralarında küçük yeşil yapraklar.
        ring_y = py - r * 0.38
        rx, ry = r * 0.80, r * 0.38
        n = 6
        for i in range(n):
            ang = i * math.tau / n - math.pi / 2
            cxf = px + math.cos(ang) * rx
            cyf = ring_y + math.sin(ang) * ry
            if i % 2 == 1:
                lp = [(cxf, cyf + 3), (cxf + 5, cyf - 3), (cxf, cyf - 8), (cxf - 5, cyf - 3)]
                pygame.draw.polygon(surf, OUTLINE, [(x_, y_ + 1) for x_, y_ in lp])
                pygame.draw.polygon(surf, (110, 180, 110), lp)
                continue
            fc = acc if (i // 2) % 2 == 0 else lighten(col, 0.28)
            sway = math.sin(t * 2.2 + i) * 0.10
            for k in range(5):
                pa = k * math.tau / 5 + sway
                pygame.draw.circle(surf, OUTLINE,
                                   (int(cxf + math.cos(pa) * 4.2), int(cyf + math.sin(pa) * 4.2)), 4)
            for k in range(5):
                pa = k * math.tau / 5 + sway
                pygame.draw.circle(surf, fc,
                                   (int(cxf + math.cos(pa) * 4.2), int(cyf + math.sin(pa) * 4.2)), 3)
            pygame.draw.circle(surf, (255, 235, 120), (int(cxf), int(cyf)), 2)

    elif item["id"] == "top_hat":
        # Silindir şapka: hafif konik gövde, saten bant ve parlama.
        by = py - r - 4
        brim = pygame.Rect(0, 0, int(r * 1.78), int(r * 0.28))
        brim.center = (int(px), int(by))
        pygame.draw.ellipse(surf, OUTLINE, brim.inflate(4, 4))
        pygame.draw.ellipse(surf, col, brim)
        pygame.draw.ellipse(surf, lighten(col, 0.20), (brim.x + 3, brim.y + 1, brim.w - 6, max(2, brim.h // 2)))
        top_w, bot_w = r * 1.02, r * 0.94
        top_y = by - r * 1.22
        body = [(px - bot_w / 2, by), (px - top_w / 2, top_y),
                (px + top_w / 2, top_y), (px + bot_w / 2, by)]
        pygame.draw.polygon(surf, OUTLINE, [(x_, y_ + 1) for x_, y_ in body])
        pygame.draw.polygon(surf, col, body)
        pygame.draw.line(surf, lighten(col, 0.30), (px - bot_w / 2 + 3, by - 3), (px - top_w / 2 + 3, top_y + 3), 2)
