SHOP_BY_KEY = {it["key"]: it for it in SHOP_ITEMS}


# denge düğmesi - market fiyatı. Anlık (iksir) ve cehennem eşyaları hariç bütün
# fiyatlar bu çarpanla büyür.
SHOP_COST_SCALE = 1.35


def shop_item_cost(item, level):
    k = 1.0 if (item.get("hell_only") or item.get("instant")) else SHOP_COST_SCALE
    return int(math.ceil(item["cost"] * k * (item["cost_mult"] ** level)))


def shop_item_unlocked(item, current_wave, biome="arena"):
    """Eşya markette alınabilir mi?"""
    if item.get("hell_only"):
        return biome == "hell"
    return current_wave >= TIER_UNLOCK_WAVE.get(item["tier"], 0)


# marketin şans ve XP'Sİ azalan getirili: "şans kitabı / bilgelik kitabı
# almadan marketten 200 şans 200 xp yapılıyor".
SHOP_LUCK_SOFT = 0.40
SHOP_XP_SOFT = 0.50
SHOP_SOFT_K = 0.30


def _shop_soft(raw, soft):
    raw = max(0.0, raw)
    return raw if raw <= soft else soft + (raw - soft) * SHOP_SOFT_K


def apply_shop_item(player, key):
    luck0, xp0 = player.run_luck_bonus, player.run_xp_mult
    _apply_shop_item_raw(player, key)
    d_luck = player.run_luck_bonus - luck0
    d_xp = player.run_xp_mult - xp0
    if d_luck > 0:
        raw = getattr(player, "shop_luck_raw", 0.0)
        player.shop_luck_raw = raw + d_luck
        player.run_luck_bonus = luck0 + (_shop_soft(raw + d_luck, SHOP_LUCK_SOFT)
                                         - _shop_soft(raw, SHOP_LUCK_SOFT))
    if d_xp > 0:
        raw = getattr(player, "shop_xp_raw", 0.0)
        player.shop_xp_raw = raw + d_xp
        player.run_xp_mult = xp0 + (_shop_soft(raw + d_xp, SHOP_XP_SOFT)
                                    - _shop_soft(raw, SHOP_XP_SOFT))


def _apply_shop_item_raw(player, key):
    # ---- çekirdekler: tavanı yok, her alımda birikir ----
    if key == "core_power":
        player.run_dmg_mult += 0.08
        return
    if key == "core_speed":
        player.run_aspd_mult += 0.06
        return
    if key == "core_vitality":
        player.base_max_hp += 30
        player.max_hp += 30
        player.hp = min(player.max_hp, player.hp + 30)   # eklenen can anında dolar
        return
    if key == "core_crit":
        player.crit_chance = clamp(player.crit_chance + 0.03, 0, 0.9)
        player.crit_dmg_mult += 0.06
        return
    if key == "core_guard":
        player.base_armor = clamp(player.base_armor + 0.02, 0, 0.5)
        return
    if key == "core_greed":
        # azalan getiri. İlk alımlar neredeyse tam değeri verir, toplam altın
        # +%48'e, tecrübe +%32'ye yaklaşır ama geçemez.
        lv = max(1, int(player.shop_levels.get("core_greed", 1)))
        player.run_coin_mult += stack_bonus(0.12, lv, 4.0) - stack_bonus(0.12, lv - 1, 4.0)
        player.run_xp_mult += stack_bonus(0.08, lv, 4.0) - stack_bonus(0.08, lv - 1, 4.0)
        return
    if key == "core_reach":
        lv = max(1, int(player.shop_levels.get("core_reach", 1)))
        player.run_pickup_mult += 0.14
        player.run_xp_mult += stack_bonus(0.06, lv, 4.0) - stack_bonus(0.06, lv - 1, 4.0)
        return
    if key == "fire":
        player.fire_level += 1
    elif key == "ice":
        player.ice_level += 1
    elif key == "multishot":
        player.multishot_level += 1
    elif key == "pierce":
        player.pierce_bonus += 1
    elif key == "shield":
        player.shield_charges += 1
    elif key == "heal":
        player.heal(40)
    elif key == "haste":
        player.run_aspd_mult += 0.09
        player.run_spd_mult += 0.05
    elif key == "explosive":
        player.explosive_level += 1
    elif key == "vampiric":
        player.vamp_level += 1
    elif key == "thorns":
        player.thorns_level += 1
    # ---- arena genişlemesi ----
    elif key == "quickdraw":
        player.run_aspd_mult += 0.07
        player.run_crit_bonus += 0.02
    elif key == "bandage":
        player.run_regen_bonus += 0.6
        player.base_max_hp += 12
        player.max_hp += 12
        player.hp = min(player.max_hp, player.hp + 12)
    elif key == "lucky_coin":
        player.run_coin_mult += 0.15
        player.run_crit_bonus += 0.02
        player.run_luck_bonus += LUCKY_COIN_LUCK
    elif key == "core_luck":
        lv = max(1, int(player.shop_levels.get("core_luck", 1)))
        player.run_luck_bonus += (stack_bonus(CORE_LUCK_PER_LEVEL, lv, CORE_LUCK_SOFT)
                                  - stack_bonus(CORE_LUCK_PER_LEVEL, lv - 1, CORE_LUCK_SOFT))
    elif key == "gambler_dice":
        player.run_luck_bonus += GAMBLER_DICE_LUCK
        player.run_spd_mult = max(0.5, player.run_spd_mult - 0.05)
    elif key == "gale_boots":
        player.run_spd_mult += 0.08
        player.dash_dist_mult += 0.04        # 0.12 -> 0.04
    elif key == "war_drum":
        player.bonk_mult += 0.20
        player.bonk_radius_mult += 0.08
        player.run_spd_mult += 0.04
    elif key == "iron_will":
        player.dmg_taken_mult = max(0.25, player.dmg_taken_mult - 0.05)
        player.base_max_hp += 20
        player.max_hp += 20
        player.hp = min(player.max_hp, player.hp + 20)
    elif key == "frost_core":
        player.ice_level += 1
        player.run_dmg_mult += 0.05
    elif key == "hunters_mark":
        player.boss_hunter += 1
    elif key == "sunder":
        player.execute_threshold = min(EXECUTE_MAX, player.execute_threshold + EXECUTE_SUNDER)
        player.run_dmg_mult += 0.08
    elif key == "soul_jar":
        player.kill_heal += 2
        player.run_xp_mult += 0.10
    elif key == "bulwark":
        player.shield_charges += 1
        player.thorns_level += 1
    elif key == "phoenix_ash":
        player.second_wind_charges += 1
        player.run_regen_bonus += 1.5
    elif key == "kings_ransom":
        player.run_coin_mult += 0.45
        player.run_xp_mult += 0.20
    # ---- cehennem eşyaları ----
    elif key == "brimstone":
        player.run_dmg_mult += 0.25
    elif key == "hell_ward":
        player.base_armor += 0.06
        player.base_max_hp += 40
        player.max_hp += 40
        player.hp = min(player.max_hp, player.hp + 40)
    elif key == "holy_flame":
        player.holy_flame += 1
    elif key == "soul_harvest":
        player.soul_harvest += 1
    elif key == "angel_wing":
        player.dash_cd_mult = max(0.30, player.dash_cd_mult - 0.20)
        player.angel_wing += 1
    elif key == "purgatory":
        player.purgatory_level += 1
        player.purgatory_timer = 0.0
    elif key == "infernal_core":
        player.run_dmg_mult += 0.10
        player.run_aspd_mult += 0.07
    elif key == "cursed_dagger":
        player.run_crit_bonus += 0.08
        player.run_critdmg_bonus += 0.30
    elif key == "dragon_heart":
        player.base_max_hp += 80
        player.max_hp += 80
        player.hp = min(player.max_hp, player.hp + 80)
        player.run_regen_bonus += 2.0
    elif key == "flame_orbit":
        player.orbit_level += 1
        player.fire_level += 1
    elif key == "soul_lantern":
        player.run_coin_mult += 0.35
        player.run_xp_mult += 0.25
        player.run_pickup_mult += 0.30
    elif key == "doom_sigil":
        player.boss_hunter += 1
    elif key == "ember_step":
        player.run_spd_mult += 0.14
        player.dash_cd_mult = max(0.30, player.dash_cd_mult - 0.15)
    elif key == "demon_pact":
        player.run_dmg_mult += 0.60
        player.dmg_taken_mult += 0.20
    elif key == "dash_cd":
        player.dash_cd_mult = max(0.35, player.dash_cd_mult - 0.18)
        player.dash_dist_mult += 0.03        # 0.10 -> 0.03
    elif key == "blood_pact":
        player.run_dmg_mult += 0.40
        player.max_hp = max(30, int(player.max_hp * 0.75))
        player.hp = min(player.hp, player.max_hp)
    elif key == "glass":
        player.run_aspd_mult += 0.30
        player.dmg_taken_mult += 0.25
    elif key == "devil":
        player.run_coin_mult += 0.20         # 0.50 -> 0.20
        player.run_xp_mult += 0.15           # 0.50 -> 0.15
        player.enemy_hp_curse += 0.12
    elif key == "chain":
        player.chain_level += 1
    elif key == "frenzy":
        player.frenzy_level += 1
    elif key == "second_wind":
        player.second_wind_charges += 1
    elif key == "storm":
        player.storm_level += 1
    elif key == "overcharge":
        player.bonk_mult += 0.35
        player.bonk_radius_mult += 0.15
    elif key == "execute_edge":
        player.execute_threshold = min(EXECUTE_MAX, player.execute_threshold + EXECUTE_EDGE)
    elif key == "titan_shield":
        player.shield_charges += 2
        player.base_armor = clamp(player.base_armor + 0.06, 0, 0.5)


# seviye atlama yükseltmeleri ("rare" olanlar seyrek çıkar ama çok güçlüdür).
# kitaplar (seviye atlayınca gelen yükseltmeler). Her yükseltme bir kitap:
# - temel kitaplar: birkaç koşuda dolan küçük hedefler
# - orta kitaplar: belli bir oynanış tarzını gerektiren iki hedef
# - nadir kitaplar: uzun soluklu sayaçlar + başarım / market şartı
#   unlock = dict(text=<özet>, reqs=[<şart>, <şart>, ...])
#   şart türleri:
#     rq_stat(stat, need, text): kayıttaki bir sayaç hedefe ulaşsın
#     rq_ach(ach_id): bir başarım açılmış olsun
#     rq_shop(item, need, text): koşu içi markette bir eşya şu seviyeye çıksın
#     rq_book(book_key): başka bir kitap açılmış olsun
#   total_kills, best_run_kills, bosses, best_wave, best_score, runs,
#   total_healed, best_run_heal, total_crits, total_bonks, total_bonk_hits,


def rq_stat(stat, need, text):
    return dict(kind="stat", stat=stat, need=need, text=text)


def rq_ach(ach_id, text=None):
    return dict(kind="ach", ach=ach_id, need=1, text=text)


def rq_shop(item, need, text):
    return dict(kind="shop", item=item, need=need, text=text)


def rq_book(book_key, text=None):
    return dict(kind="book", book=book_key, need=1, text=text)


def rq_weapon(weapon_key, text=None):
    """Şart: başka bir silah açılmış olsun (silah zincirleri için)."""
    return dict(kind="weapon", weapon=weapon_key, need=1, text=text)


# ---- kitaplar (koşu içi seviye sistemi) ----
# Kitaplar da tıpkı silahlar gibi bir "takım" kuruyor: denge: seviye tavanı
# geldiği için seviye başına kazançlar düşürüldü:
# * en çok 4 normal kitap taşınabilir (MAX_RUN_BOOKS) ve her biri
# 15. seviyeye kadar çıkar (BOOK_MAX_LEVEL).
# * en çok MAX_RUN_RARE_BOOKS nadir kitap alınabilir; her RARE_BOOK_EVERY
#   seviyede (5, 10, 15 ...) elde garanti bir nadir kart bulunur.
MAX_RUN_BOOKS = 4
# Bir koşuda alınabilecek en fazla nadir kitap (dolunca havuz kapanır).
MAX_RUN_RARE_BOOKS = 1
RARE_BOOK_EVERY = 5
# Normal kitapların çıkabileceği en yüksek seviye. 15 -> 30.
BOOK_MAX_LEVEL = 30
BOOK_SOFT_FROM = 15             # bu seviyeden sonrası "geç seviye"
BOOK_LATE_K = 0.5               # geç seviyelerin payı
BOOK_LATE_K_XP = 0.25           # Bilgelik kitabının geç payı (seviye kartopu olmasın)
# kitaplarda nadirlik (Megabonk usulü).
BOOK_RARITY_MULT = (1.0, 1.6, 2.5, 4.0, 8.0)
# (stat, yaygın kartın kazancı).
BOOK_GAINS = {
    "r_dmg": (("dmg", 0.05),),
    "r_hp": (("hp", 13.0),),
    "r_armor": (("armor", 0.02), ("hp", 8.0)),
    "r_spd": (("spd", 0.05), ("dash", 0.065)),
    "r_aspd": (("aspd", 0.05),),
    "r_crit": (("crit", 0.028),),
    "r_critd": (("critd", 0.11),),
    "r_regen": (("regen", 0.36),),
    "r_coin": (("coin", 0.055),),
    "r_xp": (("xp", 0.06),),
    "r_mag": (("mag", 1.0),),          # puan: menzil azalan getirili büyür
    "r_vamp": (("vamp", 0.016),),
    "r_pierce": (("pierce", 1.0),),    # tam sayı: kademeye göre +1..+3
    "r_bonk": (("bonk", 0.11), ("bonk_r", 0.055)),
    "r_swarm": (("swarm", 1.0),),      # puan: azalan getirili
    "r_bosshunter": (("hunter", 1.0),),
    "r_luck": (("luck", 0.05),),
    "r_wspd": (("wspd", 0.035),),      # soğuma kitabı: silahlar daha sık
    "r_evade": (("evade", 1.0),),      # kaçınma kitabı: puan, azalan getirili
}
BOOK_PIERCE_BY_TIER = (1, 1, 2, 2, 3)
LUCK_BOOK_FULL = 10             # Şans Kitabı bu seviyeye kadar tam güç
LUCK_BOOK_LATE_K = 0.4          # ... sonra bu payla
EVADE_PER = 0.03                # Kaçınma: stack_bonus(EVADE_PER, puan, EVADE_SOFT)
EVADE_SOFT = 12.0               # (tavan %36)


def book_late_k(key, lvl):
    """Geç seviyelerin (16-30) payı."""
    lvl = int(lvl)
    if key == "r_xp":
        return 1.0 if lvl <= BOOK_SOFT_FROM else BOOK_LATE_K_XP
    if key == "r_luck":
        return 1.0 if lvl <= LUCK_BOOK_FULL else LUCK_BOOK_LATE_K
    return 1.0 if lvl <= BOOK_SOFT_FROM else BOOK_LATE_K


def book_gain(key, tier, lvl):
    """Bu kitap kartının vereceği kazançlar: [(stat, miktar)]."""
    tier = int(clamp(int(tier or 0), 0, len(BOOK_RARITY_MULT) - 1))
    m = BOOK_RARITY_MULT[tier] * book_late_k(key, lvl)
    out = []
    for stat, base in BOOK_GAINS.get(key, ()):
        if stat == "pierce":
            out.append((stat, float(BOOK_PIERCE_BY_TIER[tier])))
        elif stat == "hp":
            out.append((stat, float(max(1, int(round(base * m))))))
        else:
            out.append((stat, base * m))
    return out


def book_max_level(key_or_book):
    """Bir kitabın çıkabileceği en yüksek seviye."""
    b = BOOK_BY_KEY.get(key_or_book) if isinstance(key_or_book, str) else key_or_book
    if not b:
        return BOOK_MAX_LEVEL
    if b.get("rare"):
        return 1
    return int(b.get("max", BOOK_MAX_LEVEL))

