WHIP_KB = 540.0                 # savurma kuvveti
# Kırbaç baktığın yöne doğru sallanarak atılıyor.
WHIP_SWING = 0.40               # savurma yayının yarısı (radyan)
WHIP_CURL = 0.55                # gövdenin ortasının dışa kabarması (radyan)
WHIP_GRIP = 17.0                # kabzanın ucunun oyuncu merkezinden uzaklığı (px)


# ---- emanet (kılıç) ----
EMANET_BASE_R = 132.0           # 1. seviyedeki erişim (yarıçap)
EMANET_R_PER_LEVEL = 3.8        # her seviyede eklenen erişim (25. sv: ~223 px)
EMANET_BASE_ARC = 0.62          # taradığı yarım açı (radyan)
EMANET_ARC_PER_LEVEL = 0.030    # her seviyede genişleyen yarım açı
EMANET_ARC_MAX = 1.35           # yarım açının tavanı (~155 derecelik koni)
EMANET_ARMOR_BONUS = 0.85       # zırhlı/kalkanlı düşmana ek hasar oranı
EMANET_KB = 180.0               # savurma kuvveti

# ---- görünmezlik pelerini ----
CLOAK_BASE_CD = 60.0            # 1. seviyede iki görünmezlik arası (saniye)
CLOAK_CD_PER_LEVEL = 1.0        # her seviyede beklemeden düşen saniye
CLOAK_MIN_CD = 36.0             # 25. seviyede ulaşılan taban
CLOAK_DUR = 5.0                 # görünmez kalma süresi (saniye)
CLOAK_DUR_PER_LEVEL = 0.10      # her seviyede süreye eklenen saniye


def whip_growth(lvl):
    """Kırbacın alan büyüme puanı (0 .."""
    top = float(WEAPON_MAX_LEVEL - 1)
    x = clamp((float(lvl) - 1.0) / top, 0.0, 1.0)
    return top * x ** WHIP_GROWTH_EXP


def whip_arc(lvl):
    """Kırbacın taradığı yarım açı - dar başlar, geç seviyelerde genişler."""
    return min(WHIP_ARC_MAX, WHIP_ARC + WHIP_ARC_PER_LEVEL * whip_growth(lvl))


def whip_reach(lvl):
    """Kırbacın erişimi - geç seviyelerde belirgin biçimde uzar."""
    return WHIP_LEN + WHIP_LEN_PER_LEVEL * whip_growth(lvl)


def emanet_radius(lvl):
    """Emanet'in taradığı yayın yarıçapı - seviyeyle ölçülü büyür."""
    return EMANET_BASE_R + EMANET_R_PER_LEVEL * weapon_growth(lvl)


def emanet_arc(lvl):
    """Emanet'in taradığı yarım açı (radyan) - seviyeyle genişler."""
    return min(EMANET_ARC_MAX,
               EMANET_BASE_ARC + EMANET_ARC_PER_LEVEL * weapon_growth(lvl))


def is_armored(e):
    """Düşman zırhlı mı? emanet bu düşmanlara ek hasar vurur."""
    if getattr(e, "armor", 0.0) > 0.005:
        return True
    if getattr(e, "guard_of", None) is not None:
        return True
    if getattr(e, "is_mini", False) or getattr(e, "is_boss", False):
        return True
    return getattr(e, "kind", "") in ("tank", "brute", "elite", "shieldman")


def cloak_cooldown(lvl):
    """İki görünmezlik arasındaki süre - her seviyede 3 saniye kısalır."""
    return max(CLOAK_MIN_CD, CLOAK_BASE_CD - CLOAK_CD_PER_LEVEL * weapon_growth(lvl))


def cloak_duration(lvl):
    """Görünmez kalma süresi."""
    return CLOAK_DUR + CLOAK_DUR_PER_LEVEL * weapon_growth(lvl)


# İşi (sıradan yaratıkları dondurmak) savunma tarafında gerçekten güçlü, o
# yüzden kaldırmak yerine kendi fantezisine uygun bir ödül eklendi: görünmezken
# vuruşların daha ağır:
# 1. sv +%35 ...
CLOAK_AMBUSH_BASE = 0.35
CLOAK_AMBUSH_PER_LEVEL = 0.025


def cloak_ambush_bonus(lvl):
    """Görünmezken hasara eklenen oran (0.35 = +%35)."""
    if lvl <= 0:
        return 0.0
    return CLOAK_AMBUSH_BASE + CLOAK_AMBUSH_PER_LEVEL * weapon_growth(lvl)


def book_slot_pos(p, i, n_book):
    """i numaralı kalkanın dünya konumu ve yörünge açısı."""
    a = p.book_angle + i * math.tau / max(1, n_book)
    # Hafif elips: kalkanlar tepe noktasında biraz yakın görünür, çemberin yere
    # yatık olduğu hissini verir.
    return (p.x + math.cos(a) * BOOK_ORBIT_R,
            p.y + math.sin(a) * BOOK_ORBIT_R * 0.72,
            a)


def penta_sear_hp_frac(lvl):
    """Mühre ilk adımda yaratığın canından kesilen oran (patronlar hariç)."""
    return min(PENTA_SEAR_HP_MAX,
               PENTA_SEAR_HP + PENTA_SEAR_HP_PER_LEVEL * weapon_growth(lvl))


def _penta_step(table, lvl):
    return table[clamp(int(lvl) - 1, 0, len(table) - 1)]


def penta_sear_cap(lvl):
    """İlk adım vuruşunun yaratığın O anki canından alabileceği en çok oran."""
    return min(1.0, PENTA_SEAR_CAP + PENTA_SEAR_CAP_PER_LEVEL * weapon_growth(lvl))


def penta_bat_sear_cap(lvl):
    """Yarasanın canından ilk adım vuruşuyla gidebilecek en çok oran."""
    return _penta_step(PENTA_BAT_SEAR_CAP, lvl)


def penta_bat_tick_mult(lvl):
    """Yarasaya işleyen sürekli hasarın çarpanı."""
    return _penta_step(PENTA_BAT_TICK, lvl)


def is_penta_bat(e):
    """Bu yaratık yarasa mı?"""
    return getattr(e, "shape", "") == PENTA_BAT_SHAPE


def penta_radius(lvl):
    """Pentagram alanının yarıçapı - her seviyede büyür."""
    return PENTA_BASE_R + PENTA_R_PER_LEVEL * weapon_growth(lvl)


def shoe_radius(lvl):
    """Baran'IN papucu'nun bıraktığı ateş halkasının başlangıç yarıçapı."""
    return SHOE_BASE_R + SHOE_R_PER_LEVEL * weapon_growth(lvl)


def shoe_life(lvl):
    """Ateş halkasının ömrü - seviyeye göre."""
    g = weapon_growth(lvl)
    if g <= len(SHOE_LIFE_STEPS) - 1:
        i = int(g)
        f = g - i
        a = SHOE_LIFE_STEPS[i]
        b = SHOE_LIFE_STEPS[min(i + 1, len(SHOE_LIFE_STEPS) - 1)]
        return lerp(a, b, f)
    return SHOE_LIFE_STEPS[-1] + SHOE_LIFE_PER_LEVEL * (g - (len(SHOE_LIFE_STEPS) - 1))


def draw_pentagram_field(surf, p, t):
    """Oyuncunun ayağının altındaki pentagram mührü (varsa)."""
    lvl = p.weapons.get("pentagram", 0)
    if lvl <= 0:
        return
    draw_pentagram(surf, p.x, p.y, penta_radius(lvl), p.penta_angle, t)


def draw_shield_books(surf, p, t, layer="front"):
    """Oyuncunun çevresinde dönen kalkanlar (varsa)."""
    lvl = p.weapons.get("book", 0)
    if lvl <= 0:
        return
    n_book = weapon_count(lvl)
    for i in range(n_book):
        bx, by, a = book_slot_pos(p, i, n_book)
        back = math.sin(a) < 0
        if back != (layer == "back"):
            continue
        # Derinlik: arkadaki kalkan küçülür, öndeki büyür.
        depth = (math.sin(a) + 1.0) * 0.5          # 0 = en arka, 1 = en ön
        k = (0.82 + 0.30 * depth) * (1.0 + 0.012 * (lvl - 1))
        charged = not (i < len(p.book_charges) and p.book_charges[i] > 0)
        draw_shield_book(surf, bx, by, a, k, charged, t, phase=i * 1.7)


# ---- silah açılışları ----
# Silahlar tıpkı kitaplar gibi görevle açılır; açılışı tamamlanmamış bir silah
# seviye atlama ekranında asla görünmez.


def weapon_reqs(w):
    unl = w.get("unlock")
    return list(unl.get("reqs", [])) if unl else []


def weapon_progress(save, w):
    """Silahın görev ilerlemesi: (tamamlanan, toplam, hepsi tamam mı)."""
    reqs = weapon_reqs(w)
    if not reqs:
        return 1, 1, True
    done = sum(1 for r in reqs if book_req_state(save, r)[2])
    return done, len(reqs), done >= len(reqs)


def weapon_frac(save, w):
    """Silahın görevlerindeki ortalama ilerleme (0..1) - çubuk ve sıralama için."""
    reqs = weapon_reqs(w)
    if not reqs:
        return 1.0
    tot = 0.0
    for r in reqs:
        cur, need, done, _ = book_req_state(save, r)
        tot += 1.0 if done else clamp(cur / max(1, need), 0.0, 1.0)
    return tot / len(reqs)


# Oyuncunun bir koşuda taşıyabileceği en fazla silah sayısı.
MAX_RUN_WEAPONS = 4


def slot_max(p, kind):
    """Bir oyuncunun koşudaki yuva sınırı: "w" silah, "b" kitap, "r" nadir kitap."""
    if kind == "w":
        return int(getattr(p, "max_weapons", MAX_RUN_WEAPONS))
    if kind == "b":
        return int(getattr(p, "max_books", MAX_RUN_BOOKS))
    return int(getattr(p, "max_rare", MAX_RUN_RARE_BOOKS))
# Oyuncunun "bu bana gelmesin" diyerek kapatabileceği en fazla silah sayısı.
MAX_MUTED_WEAPONS = 4


def weapon_max_level(w):
    """Silahın çıkabileceği en yüksek seviye."""
    return int(w.get("max", WEAPON_MAX_LEVEL))


def weapon_cooldown(w, level):
    """Silahın iki atışı arasındaki süre."""
    k = float(w.get("cdl", WEAPON_CD_PER_LEVEL))
    return max(0.22, w["cd"] * (k ** weapon_growth(level)))


def weapon_damage(player, w, level):
    """Silahın vuruş hasarı - oyuncunun o anki hasarına göre ölçeklenir."""
    dpl = float(w.get("dpl", WEAPON_DMG_PER_LEVEL))
    # şans: silahın nadirlik bonusu (sandık / seviye kartı). Tek-atma freni
    # (cap_oneshot) vuruşta ayrıca uygulanır; bonus onu atlamaz.
    boost = 1.0 + float(getattr(player, "weapon_boost", {}).get(w["key"], 0.0))
    evo = EVO_DMG_MULT if w["key"] in getattr(player, "evolved", ()) else 1.0
    return (player.eff_dmg() * w["dmg"] * WEAPON_DMG_GLOBAL
            * (1.0 + dpl * WEAPON_DPL_SCALE * weapon_growth(level)) * boost * evo)


# ---- tek-atma freni ----
# Çözüm, hasarı tek tek kısmak değil (o zaman silahlar geç oyunda çöpe
# dönüyor), ortak bir fren koymak: bir silahın tek vuruşu, yaratığın O anki
# canının en çok belirli bir oranını alabilir:
# 1. seviyede canın %80'i, 10. seviyede fren tamamen kalkar.
# 1. seviyede %68, 18. seviyede fren kalkar. ağır (tank, gürz, elit, siperci,
#    sancaktar, golem, kasap, gardiyan ve zırhı olan her şey - "tank") %46'dan
#    başlar, 25. seviyede ancak %74'e çıkar: hiçbir seviyede tek atılamaz.
#   hafif (mavi küçükler, koşucular, imp - "fare/yarasa")
ENEMY_WEIGHT_CLASS = {
    "blue": "frail", "sprinter": "frail", "imp": "frail",
    "red": "normal", "yellow": "normal", "hound": "normal",
    "bomber": "frail", "healer": "normal", "kamikaze": "frail",
    "wizard": "normal", "stinger": "frail",
    "seer": "normal", "reaver": "normal",
    "tank": "tough", "brute": "tough", "elite": "tough",
    "shieldman": "tough", "herald": "tough",
    "golem": "tough", "butcher": "tough", "warden": "tough",
    "splitter": "normal", "necro": "normal", "ghost": "frail", "goblin": "normal",
}
# (1. seviyedeki oran, frenin tamamen kalktığı seviye, hiç kalkmıyorsa tavan)
ONESHOT_CAP_TABLE = {
    "frail":  (0.80, 10, 1.0),
    "normal": (0.68, 18, 1.0),
    "tough":  (0.46, None, 0.74),
}


def enemy_weight_class(e):
    """Yaratığın sıkleti: "frail" | "normal" | "tough"."""
    if getattr(e, "armor", 0.0) > 0.005:
        return "tough"
    if getattr(e, "guard_of", None) is not None:
        return "tough"
    if getattr(e, "is_mini", False):
        return "tough"
    return ENEMY_WEIGHT_CLASS.get(getattr(e, "kind", ""), "normal")


def oneshot_cap(e, lvl):
    """Tek vuruşun yaratığın O anki canından alabileceği en çok oran (0..1]."""
    if getattr(e, "is_boss", False):
        return 1.0
    base, gate, top = ONESHOT_CAP_TABLE[enemy_weight_class(e)]
    lvl = max(1, int(lvl))
    if gate is None:
        # Fren hiç kalkmaz: taban ile tavan arasında seviyeyle yumuşak yürür.
        f = clamp(weapon_growth(lvl) / max(1.0, WEAPON_MAX_LEVEL - 1), 0.0, 1.0)
        return clamp(lerp(base, top, f), 0.0, 0.999)
    if lvl >= gate:
        return 1.0
    return clamp(lerp(base, 1.0, (lvl - 1) / float(gate - 1)), 0.0, 1.0)


# ---- frenin ikinci vuruşta bıraktığı ----
# İki kural eklendi: Yani kural artık "hiçbir eşya tek atmasın" değil, "hiçbir
# eşya TEK VURUŞTA atmasın": ilk vuruş yaratığı yere serer, ikinci vuruş
# bitirir:
# 1) bir kerelik: fren bir yaratığa yalnızca bir kez uygulanır.
# 2) merhamet eşiği: fren sonrası yaratık canının %6'sından azıyla kalacaksa
#    hiç frenlenmez, vuruş onu bitirir.
ONESHOT_MERCY = 0.06            # bu orandan az canla bırakma, bitir


def cap_oneshot(e, dmg, lvl):
    """Hasarı tek-atma frenine göre kırpar."""
    if lvl is None or dmg <= 0:
        return dmg
    # Bu yaratık frenini zaten yedi mi? Yediyse serbest.
    if getattr(e, "_oneshot_used", False):
        return dmg
    cap = oneshot_cap(e, lvl)
    if cap >= 1.0:
        return dmg
    hp = max(0.0, getattr(e, "hp", 0.0))
    capped = hp * cap
    if dmg <= capped:
        return dmg                      # vuruş zaten frenin altında
    # merhamet: geriye kıl payı can kalacaksa frenleme, bitir.
    if hp - capped <= hp * ONESHOT_MERCY:
        return dmg
    e._oneshot_used = True
    return capped


# ---- hasar dökümü ----
# Koşu boyunca hangi silahın (ve ana silah / bonk / yetenek ...) ne kadar hasar
# verdiği.
DMG_SRC = ["other"]
DMG_LOG = [None]
# evrilmiş silah anahtarları (vuruş anında hızlı bakılsın diye ayrı küme)
EVO_ON = set()


def dmg_note(amount):
    log = DMG_LOG[0]
    if log is None or amount <= 0:
        return
    k = DMG_SRC[0] or "other"
    log[k] = log.get(k, 0.0) + float(amount)


def dmg_src_label(key):
    """Döküm satırının adı, ikonu ve rengi."""
    w = WEAPON_BY_KEY.get(key)
    if w is not None:
        return w_name(w), w.get("icon", "sword"), w.get("color", TEXT)
    extra = {"gun": ("target", (255, 214, 120)), "bonk": ("skull", (150, 255, 130)),
             "storm": ("bolt", (190, 215, 255)), "ult": ("star", (255, 150, 230)),
             "orbit": ("orbit", (140, 200, 255)), "other": ("flame", (200, 160, 140))}
    ic, col = extra.get(key, ("flame", (200, 160, 140)))
    return L("dmg." + key) if ("dmg." + key) in STRINGS else key, ic, col


class BossChest:
    """Patron ölünce düşen sandık."""

    def __init__(self, x, y, boss_name=""):
        self.x, self.y = x, y
        self.r = 26
        self.t = 0.0
        self.open_t = 0.0          # açılma canlandırması
        self.opened = False
        self.taken = False         # ödül verildi mi (RunState işler)
        self.alive = True
        self.boss_name = boss_name
        self.bob = random.uniform(0, math.tau)

    def in_range(self, p):
        return dist(self.x, self.y, p.x, p.y) < self.r + p.radius + 10

    def update(self, dt, player):
        self.t += dt
        if self.opened:
            self.open_t += dt
            if self.open_t > 1.1:
                self.alive = False
            return
        if player.alive and self.in_range(player):
            self.opened = True
            self.open_t = 0.0

    def draw(self, surf, t):
        bob = math.sin(t * 2.4 + self.bob) * 3.0
        x, y = self.x, self.y + bob
        k = clamp(self.open_t / 0.4, 0.0, 1.0) if self.opened else 0.0
        surf.blit(shadow_sprite(int(self.r * 2)), (int(x - self.r), int(self.y + self.r * 0.5)))
        add_glow(surf, x, y, self.r * (2.0 + 1.6 * k), GOLD, 0.35 + 0.18 * math.sin(t * 3) + 0.4 * k)

        w, h = self.r * 1.7, self.r * 1.05
        # ---- gövde ----
        base = pygame.Rect(int(x - w), int(y - h * 0.25), int(w * 2), int(h * 1.35))
        pygame.draw.rect(surf, OUTLINE, base.inflate(6, 6), border_radius=6)
        pygame.draw.rect(surf, (126, 78, 42), base, border_radius=6)
        pygame.draw.rect(surf, (86, 52, 28), base, width=2, border_radius=6)
        for i in (-1, 1):
            pygame.draw.line(surf, (92, 58, 32), (x + i * w * 0.45, base.top + 3),
                             (x + i * w * 0.45, base.bottom - 3), 3)
        # ---- kapak (açılınca arkaya devrilir) ----
        lid_lift = h * 1.5 * k
        lid = pygame.Rect(int(x - w), int(y - h * 0.95 - lid_lift), int(w * 2), int(h * 0.85))
        pygame.draw.rect(surf, OUTLINE, lid.inflate(6, 6), border_radius=7)
        pygame.draw.rect(surf, (150, 96, 52), lid, border_radius=7)
        pygame.draw.rect(surf, GOLD, lid, width=2, border_radius=7)
        # ---- altın kilit ----
        pygame.draw.rect(surf, GOLD, (int(x - 7), int(y - h * 0.28 - lid_lift * 0.4), 14, 16),
                         border_radius=3)
        pygame.draw.circle(surf, (120, 80, 20), (int(x), int(y - h * 0.20 - lid_lift * 0.4)), 3)
        # ---- altın bantlar ----
        pygame.draw.line(surf, GOLD, (base.left + 2, base.top + 2), (base.right - 2, base.top + 2), 3)

        if self.opened:
            # açılırken içinden ışık sütunu ve kıvılcımlar fışkırır
            beam = pygame.Surface((int(w * 2), int(h * 6)), pygame.SRCALPHA)
            pygame.draw.polygon(beam, (255, 225, 140, int(150 * (1 - k * 0.4))),
                                [(w * 0.65, beam.get_height()), (w * 1.35, beam.get_height()),
                                 (w * 2.0, 0), (0, 0)])
            surf.blit(beam, (int(x - w), int(y - h * 6)))
            for i in range(8):
                a = t * 3 + i * math.tau / 8
                rr = self.r * (0.5 + 1.8 * k)
                blit_disc(surf, x + math.cos(a) * rr, y + math.sin(a) * rr * 0.6,
                          3.2 * (1 - k * 0.6), (255, 230, 150), int(220 * (1 - k)))
        else:
            # kapalıyken: yukarı süzülen altın zerreler + "YAKLAŞ" ipucu
            for i in range(4):
                ph = (t * 0.8 + i * 0.25 + self.bob) % 1.0
                sx_ = x + math.sin(t * 2 + i * 2.1) * self.r * 0.8
                sy_ = y - self.r * 0.4 - ph * self.r * 2.2
                blit_disc(surf, sx_, sy_, max(1.0, 3.0 * (1 - ph)), (255, 225, 140),
                          int(210 * (1 - ph)))
            draw_text(surf, L("ui.chest"), (x, y - self.r * 2.4), 13, GOLD,
                      bold=True, center=True)
            draw_text(surf, L("ui.chest_hint"), (x, y - self.r * 1.75), 10, TEXT_DIM,
                      center=True, shadow=False)


# ---- anahtarlar ve efsanevi sandık ----
# Dünya 5x5 olunca haritayı gezmeye bir sebep gerekti: haritanın rastgele
# yerlerinde 5 anahtar belirir (küçük haritada ve en yakını ekran kenarında
# görünür):
# * bir el efsanevi kart (hepsi efsanevi nadirlikte silah / kitap) - biri
#   seçilir,
# * ardından +3 seviye (üç normal kart eli).
KEY_COUNT = 1
KEY_PICK_R = 40
KEY_SPACING = 900               # anahtarlar arası en az mesafe
KEY_PLAYER_MIN = 700            # oyuncuya en az bu kadar uzakta doğar
KEY_PLAYER_MAX = 2300           # ... ve en çok bu kadar (keşif makul kalsın)
KEY_COLOR = (255, 214, 90)
KEY_COLOR2 = (255, 246, 200)
KEY_RESPAWN = 75.0              # sandık açıldıktan sonra yeni anahtarlara kadar (sn)
LEGEND_CHEST_MAX = 1
LEGEND_CHEST_LEVELS = 3
LEGEND_COLOR = (255, 196, 70)
LEGEND_COLOR2 = (200, 120, 255)


def draw_key_icon(surf, x, y, r, col, edge=OUTLINE):
    """Küçük anahtar simgesi (halka + sap + iki diş)."""
    w = max(2, int(r * 0.32))
    hx, hy = x - r * 0.45, y
    pygame.draw.line(surf, edge, (hx + r * 0.25, y), (x + r * 0.95, y), w + 3)
    pygame.draw.line(surf, col, (hx + r * 0.25, y), (x + r * 0.95, y), w)
    for tx in (0.55, 0.85):
        pygame.draw.line(surf, edge, (x + r * tx, y), (x + r * tx, y + r * 0.42), w + 2)
        pygame.draw.line(surf, col, (x + r * tx, y), (x + r * tx, y + r * 0.42), max(1, w - 1))
    pygame.draw.circle(surf, edge, (int(hx), int(hy)), int(r * 0.52) + 2)
    pygame.draw.circle(surf, col, (int(hx), int(hy)), int(r * 0.52))
    pygame.draw.circle(surf, edge, (int(hx), int(hy)), max(1, int(r * 0.22)))


class MapKey:
    """Haritada duran parlak anahtar."""

    def __init__(self, x, y, idx=0):
        self.x, self.y = x, y
        self.idx = idx
        self.t = random.uniform(0, 5)
        self.taken = False
        self.gone = False
        self.take_t = 0.0

    def update(self, dt):
        self.t += dt
        if self.taken:
            self.take_t += dt
            if self.take_t > 0.6:
                self.gone = True

    def draw(self, surf, t):
        x, y = self.x, self.y
        if self.taken:
            k = clamp(self.take_t / 0.6, 0.0, 1.0)
            add_glow(surf, x, y - 30 * k, 60 * (1 - k) + 10, KEY_COLOR, 0.6 * (1 - k))
            draw_key_icon(surf, x, y - 40 * k, 16 * (1 + k), KEY_COLOR2)
            return
        # parlamaz - yerde duran sade bir anahtar (gezerek bulunur)
        bob = math.sin(self.t * 2.0) * 2
        surf.blit(shadow_sprite(30), (int(x - 15), int(y + 8)))
        draw_key_icon(surf, x, y + bob - 4, 15, (214, 176, 84))


_KEY_BEAM = None


def _key_beam():
    global _KEY_BEAM
    if _KEY_BEAM is None:
        w, h = 44, 260
        s = pygame.Surface((w, h), pygame.SRCALPHA)
        for yy in range(h):
            k = yy / float(h)
            a = int(110 * k * k)
            half = int(4 + 18 * k)
            pygame.draw.line(s, (255, 220, 120, a), (w // 2 - half, yy), (w // 2 + half, yy))
        _KEY_BEAM = s
    return _KEY_BEAM


class LegendChest(BossChest):
    """5 anahtarla açılan efsanevi sandık: altın-mor, dönen ışınlar, yükselen yıldızlar."""

    def __init__(self, x, y):
        super().__init__(x, y, "")
        self.r = 34

    def draw(self, surf, t):
        x, y = self.x, self.y + math.sin(t * 2.0 + self.bob) * 4.0
        k = clamp(self.open_t / 0.4, 0.0, 1.0) if self.opened else 0.0
        # dönen ışınlar
        n = 12
        for i in range(n):
            a = t * 0.6 + i * math.tau / n
            ln = 150 + 30 * math.sin(t * 3 + i)
            pts = [(x, y), (x + math.cos(a - 0.08) * ln, y + math.sin(a - 0.08) * ln),
                   (x + math.cos(a + 0.08) * ln, y + math.sin(a + 0.08) * ln)]
            poly_alpha(surf, pts, LEGEND_COLOR if i % 2 == 0 else LEGEND_COLOR2, 46)
        add_glow(surf, x, y, 120 + 40 * k, LEGEND_COLOR, 0.55 + 0.15 * math.sin(t * 4))
        add_glow(surf, x, y, 70, LEGEND_COLOR2, 0.35)
        beam = _key_beam()
        big = pygame.transform.smoothscale(beam, (beam.get_width() * 2, int(beam.get_height() * 1.6)))
        surf.blit(big, (int(x - big.get_width() / 2), int(y - big.get_height() + 16)))
        surf.blit(shadow_sprite(int(self.r * 2.4)), (int(x - self.r * 1.2), int(self.y + self.r * 0.6)))
        w, h = self.r * 1.7, self.r * 1.05
        base = pygame.Rect(int(x - w), int(y - h * 0.25), int(w * 2), int(h * 1.35))
        pygame.draw.rect(surf, OUTLINE, base.inflate(8, 8), border_radius=8)
        pygame.draw.rect(surf, (70, 34, 110), base, border_radius=8)
        pygame.draw.rect(surf, LEGEND_COLOR, base, width=3, border_radius=8)
        for i in (-1, 1):
            pygame.draw.line(surf, LEGEND_COLOR, (x + i * w * 0.5, base.top + 3),
                             (x + i * w * 0.5, base.bottom - 3), 4)
        lid_lift = h * 1.6 * k
        lid = pygame.Rect(int(x - w), int(y - h * 1.0 - lid_lift), int(w * 2), int(h * 0.9))
        pygame.draw.rect(surf, OUTLINE, lid.inflate(8, 8), border_radius=10)
        pygame.draw.rect(surf, (96, 50, 150), lid, border_radius=10)
        pygame.draw.rect(surf, LEGEND_COLOR, lid, width=3, border_radius=10)
        gx, gy = x, y - h * 0.55 - lid_lift
        pygame.draw.polygon(surf, OUTLINE, [(gx, gy - 12), (gx + 10, gy), (gx, gy + 12), (gx - 10, gy)])
        pygame.draw.polygon(surf, (120, 230, 255), [(gx, gy - 9), (gx + 7, gy), (gx, gy + 9), (gx - 7, gy)])
        draw_key_icon(surf, x - 6, y + h * 0.35, 9, LEGEND_COLOR)
        for i in range(7):
            ph = (t * 0.7 + i * 0.143 + self.bob) % 1.0
            sx_ = x + math.sin(t * 1.8 + i * 2.1) * self.r * 1.1
            sy_ = y - self.r * 0.3 - ph * self.r * 3.0
            _sparkle(surf, sx_, sy_, 1.5 + 4.0 * (1 - ph), LEGEND_COLOR2 if i % 2 else KEY_COLOR2)
        if not self.opened:
            draw_text(surf, L("ui.legend_chest"), (x, y - self.r * 2.7), 15, LEGEND_COLOR,
                      bold=True, center=True)
            draw_text(surf, L("ui.chest_hint"), (x, y - self.r * 2.1), 11, TEXT_DIM,
                      center=True, shadow=False)


