def boss_skill_audit():
    """Her haritadaki her patronun en az 5 ayrı yeteneği var mı?"""
    bad = []
    for mp, kinds in BOSS_SKILLS_BY_MAP.items():
        for kind, sk in kinds.items():
            uniq = set(sk)
            if len(uniq) < BOSS_MIN_SKILLS:
                bad.append(f"{mp}/{kind}: yalnız {len(uniq)} yetenek")
            for s in uniq:
                if s not in BOSS_SKILL_NAMES:
                    bad.append(f"{mp}/{kind}: bilinmeyen yetenek {s}")
    return bad


def boss_skill_set(kind, theme=None, hellish=False):
    """Patronun yetenek takımı: arena / harita / cehennem (tek tablo)."""
    mp = "hell" if hellish else (theme if theme in BOSS_SKILLS_BY_MAP else "stone")
    sk = BOSS_SKILLS_BY_MAP.get(mp, {}).get(kind) or BOSS_SKILLS_BY_MAP["stone"].get(kind)
    if not sk:
        sk = tuple(BOSS_SKILL_SETS.get(kind, ("lunge",))) + tuple(BOSS_POWER_SKILLS.get(kind, ()))
    return tuple(dict.fromkeys(sk))

