def boss_trait(kind, hellish=False):
    """Patronun imza özelliği."""
    tr = dict(BOSS_TRAITS.get(kind, BOSS_TRAITS["warlord"]))
    tr["hellfire"] = bool(hellish) or tr["kind"] in ("burn", "inferno")
    return tr

# Patronlar 10. dalgadan itibaren her 5 dalgada bir gelir. arenada yalnızca
# dört patron dalgası vardır: 10, 15, 20, 25.
BOSS_FIRST_WAVE = 10
BOSS_WAVE_STEP = 5

# ---- yarı patron (sancaktar) dalgaları ----
# Bu sayılar bilerek seçildi: ne arenanın patron dalgalarına (10/15/20/25) ne
# de cehennemin patron dalgalarına (5/10/15) denk gelir, yani yarı patron
# hiçbir zaman gerçek bir patronla aynı dalgada çıkmaz:
# 4. dalgadan başlayarak her 5 dalgada bir gelir: 4, 9, 14, 19, 24, 29 ...
MINI_BOSS_FIRST_WAVE = 4
MINI_BOSS_STEP = 5
MINI_BOSS_GUARDS = 4            # yanında gelen siperci sayısı
MINI_BOSS_GUARDS_MAX = 9        # geç dalgalarda çıkabileceği en yüksek sayı (7 -> 9)


def mini_boss_wave(w):
    """Bu dalgada yarı patron gelir mi?"""
    return w >= MINI_BOSS_FIRST_WAVE and (w - MINI_BOSS_FIRST_WAVE) % MINI_BOSS_STEP == 0


def mini_boss_guard_count(w, hell=False):
    """Dalga ilerledikçe sancaktarın yanındaki siperci sayısı artar."""
    k = mini_boss_tier(w, hell)
    return min(MINI_BOSS_GUARDS_MAX, MINI_BOSS_GUARDS + k // 2)


# sancaktar ilerledikçe sertleşir. Her gelişinde (kademe) kendi canı,
# sipercilerin canı ve kalkanların emdiği pay büyür.
MINI_BOSS_HP_PER_TIER = 0.30        # sancaktarın canı, kademe başına
MINI_BOSS_GUARD_HP_PER_TIER = 0.25  # sipercilerin canı, kademe başına
MINI_BOSS_LEAK_PER_TIER = 0.012     # kalkandan sızan payın kademe başına düşüşü
MINI_BOSS_LEAK_MIN = 0.04
MINI_BOSS_GUARD_ARMOR_PER_TIER = 0.03
MINI_BOSS_GUARD_ARMOR_MAX = 0.30
MINI_BOSS_HELL_TIER = 5             # cehennemdeki kademe tabanı


def mini_boss_tier(w, hell=False):
    """Sancaktarın kaçıncı gelişi (0 = ilk)."""
    k = max(0, (int(w) - MINI_BOSS_FIRST_WAVE) // MINI_BOSS_STEP)
    return k + (MINI_BOSS_HELL_TIER if hell else 0)

# Patron dengelemesi: patronlar zorlu kalsın ama haksız hissettirmesin. gölge
# cadısı'nın "lanet çemberi" tuzakları:
#   HP -> %15 daha az can (dövüş "ölümsüz" hissi vermesin)
#   dmg -> %15 daha az hasar (hem temas hem de tüm saldırılar için)
#   extra -> her saldırının hazırlık (telegraph) süresine eklenen ek bekleme.
