BOSS_DMG_NERF = 0.85 * 0.90

# İki ek kural:
# * asgari darbe: patron darbesi en az (azami can x oran) kadar vurur (oran
#   saldırının gücüyle ölçeklenir: mermi temastan az).
# * yara: sahada patron varken her türlü iyileşme (yenilenme, can çalma,
#   öldürme şifası, kalp) azalır.
BOSS_THREAT_FROM = 10
BOSS_FLOOR_MAX = 0.30
BOSS_WOUND_MAX = 0.75


def boss_hit_floor(wave, hellish=False):
    """Temas darbesinin azami cana oranla en küçük değeri."""
    if hellish:
        return min(BOSS_FLOOR_MAX, 0.21 + 0.004 * max(0, wave - 1))
    if wave < BOSS_THREAT_FROM:
        return 0.0
    return min(BOSS_FLOOR_MAX, 0.06 + 0.0056 * wave)


def boss_wound(wave, hellish=False):
    """Patron sahadayken iyileşmeden kesilen pay (0.3 = %30 az şifa)."""
    if hellish:
        return min(BOSS_WOUND_MAX, 0.55 + 0.01 * max(0, wave - 1))
    if wave < BOSS_THREAT_FROM:
        return 0.0
    return min(0.60, 0.30 + 0.015 * (wave - BOSS_THREAT_FROM))
# patron canı +%20:
# 1) estimated_dps taşınan silahların hasarını da hesaba katıyor,
# 2) patron canı ayrıca bu çarpanla %20 yükseltiliyor.
BOSS_HP_BONUS = 1.20
BOSS_TELEGRAPH_EXTRA = 0.40


def boss_index_for_wave(wave):
    """Kaçıncı patron olduğunu döndürür (10. dalga -> 1, 15 -> 2, 20 -> 3 ...)."""
    if wave < BOSS_FIRST_WAVE:
        return 1
    return (wave - BOSS_FIRST_WAVE) // BOSS_WAVE_STEP + 1


def boss_power(wave, index=None):
    """Patronun dalgaya göre güç çarpanları: (can, hasar, zırh)."""
    idx = int(index) if index is not None else boss_index_for_wave(wave)
    hp = 1.12 + (idx - 1) * 0.62 + ((idx - 1) ** 1.6) * 0.055
    # denge: hasar artışı çok zayıftı (patron başına yalnızca +%16):
    # 10. dalgadan 20. dalgaya kadar kat kat güçlenirken patronlar yerinde
    dmg = 1.0 + (idx - 1) * 0.26 + ((idx - 1) ** 1.5) * 0.02
    armor = clamp(0.12 + (idx - 1) * 0.035, 0.0, 0.45)
    return hp, dmg, armor


# Birden fazla patronlu dalganın toplam canı, tek patronlu bir dalganın kaç
# katı olsun.
MULTI_BOSS_TOTAL = 1.7


def boss_hp_share(n_boss):
    """Birden fazla patron varken canın patronlar arasında dağıtımı."""
    return 1.0 if n_boss <= 1 else 1.0 / n_boss


def boss_count_for_wave(wave):
    """Geç dalgalarda aynı anda birden fazla patron gelir."""
    if wave >= 35:
        return 3
    if wave >= 20:
        return 2
    return 1


class _TgLayer:
    """Patron telgrafları için saydam katman."""
    def __init__(self, cx, cy):
        self.ops = []               # (tür, renk, noktalar, kalınlık)

    def line(self, col, p0, p1, w=1):
        self.ops.append(("l", col, (p0, p1), w))

    def polygon(self, col, pts, w=0):
        self.ops.append(("p", col, list(pts), w))

    def blit_to(self, surf):
        """Şekillerin kapladığı alan kadar (hedefin kırpımıyla sınırlı) saydam yüzey açılır"""
        if not self.ops:
            return
        xs = [q[0] for op in self.ops for q in op[2]]
        ys = [q[1] for op in self.ops for q in op[2]]
        pad = max(op[3] for op in self.ops) + 2
        bb = pygame.Rect(int(min(xs)) - pad, int(min(ys)) - pad,
                         int(max(xs) - min(xs)) + pad * 2 + 1, int(max(ys) - min(ys)) + pad * 2 + 1)
        bb = bb.clip(surf.get_clip() or surf.get_rect())
        if bb.w <= 0 or bb.h <= 0:
            return
        s = pygame.Surface(bb.size, pygame.SRCALPHA)
        ox, oy = bb.x, bb.y
        for kind, col, pts, w in self.ops:
            pp = [(q[0] - ox, q[1] - oy) for q in pts]
            if kind == "l":
                pygame.draw.line(s, col, pp[0], pp[1], w)
            else:
                pygame.draw.polygon(s, col, pp, w)
        surf.blit(s, bb.topleft)


