def poly_alpha(surf, pts, col, alpha):
    """Yarı saydam çokgen (yalnız kapladığı kutu kadar geçici yüzey)."""
    if alpha <= 0 or len(pts) < 3:
        return
    xs = [p[0] for p in pts]
    ys = [p[1] for p in pts]
    x0, y0 = int(min(xs)) - 1, int(min(ys)) - 1
    w, h = int(max(xs)) - x0 + 2, int(max(ys)) - y0 + 2
    if w <= 0 or h <= 0 or w > 2400 or h > 2400:
        return
    s = pygame.Surface((w, h), pygame.SRCALPHA)
    pygame.draw.polygon(s, (col[0], col[1], col[2], int(clamp(alpha, 0, 255))),
                        [(px - x0, py - y0) for px, py in pts])
    surf.blit(s, (x0, y0))


def _qbez(p0, p1, p2, n=8):
    """İkinci derece Bezier eğrisi üzerindeki noktalar."""
    out = []
    for i in range(n + 1):
        k = i / n
        a, b, c = (1 - k) * (1 - k), 2 * (1 - k) * k, k * k
        out.append((a * p0[0] + b * p1[0] + c * p2[0], a * p0[1] + b * p1[1] + c * p2[1]))
    return out


class MapBossArt:
    """Boss'un harita gövdeleri (karışım sınıfı - Boss bundan türer)."""

    # ---- ortak küçük parçalar ----
    def _crystal(self, surf, base_a, base_b, tip, col, edge=(255, 255, 255)):
        pts = [base_a, tip, base_b]
        pygame.draw.polygon(surf, OUTLINE, pts, 3)
        pygame.draw.polygon(surf, col, pts)
        mid = ((base_a[0] + base_b[0]) / 2, (base_a[1] + base_b[1]) / 2)
        pygame.draw.line(surf, edge, mid, tip, 1)

    def _leaf(self, surf, c, ang, ln, wd, col, vein=(40, 100, 40)):
        ca, sa = math.cos(ang), math.sin(ang)
        pts = [(c[0], c[1]),
               (c[0] + ca * ln * 0.5 - sa * wd, c[1] + sa * ln * 0.5 + ca * wd),
               (c[0] + ca * ln, c[1] + sa * ln),
               (c[0] + ca * ln * 0.5 + sa * wd, c[1] + sa * ln * 0.5 - ca * wd)]
        pygame.draw.polygon(surf, OUTLINE, pts, 2)
        pygame.draw.polygon(surf, col, pts)
        pygame.draw.line(surf, vein, pts[0], pts[2], 1)

    def _seg_leg(self, surf, P, root, knee, foot, col, w):
        pts = [P(*root), P(*knee), P(*foot)]
        self._limb(surf, pts, col, w)
        pygame.draw.circle(surf, lighten(col, 0.25), [int(v) for v in pts[1]], max(2, int(w * 0.55)))

    # buzul
    def _art_frost_knight(self, surf, x, y, r, col, t):
        """buz şövalyesi: buz plaka zırh, kristal kalkan, uzun buz kılıcı, donmuş pelerin, buz boynuzlu miğfer."""
        P, fx_, fy_, sx_, sy_ = self._mapper(x, y, r)
        step = math.sin(self.gait) * 0.10
        dark = scale_col(col, 0.55)
        lite = lighten(col, 0.42)
        frost = (226, 244, 255)
        # ---- donmuş pelerin + sarkıt saçağı ----
        cape = [P(0.0, 0.70), P(-0.30, 1.02)]
        hem = []
        for i in range(6):
            k = i / 5.0
            wob = math.sin(t * 2.0 + i * 1.3) * 0.10
            pt = P(-1.18 - 0.26 * math.sin(k * math.pi), (0.5 - k) * 1.96 + wob)
            cape.append(pt)
            hem.append(pt)
        cape += [P(-0.30, -1.02), P(0.0, -0.70)]
        self._poly(surf, cape, (34, 62, 112), x, y, grow=0.04)
        poly_alpha(surf, [P(-0.1, 0.5), P(-0.95, 0.75), P(-0.95, -0.75), P(-0.1, -0.5)], frost, 40)
        for pt in hem:
            tip = (pt[0] - fx_ * r * 0.24, pt[1] - fy_ * r * 0.24)
            a = (pt[0] + sx_ * r * 0.08, pt[1] + sy_ * r * 0.08)
            b = (pt[0] - sx_ * r * 0.08, pt[1] - sy_ * r * 0.08)
            self._crystal(surf, a, b, tip, (200, 232, 255))
        # ---- buz kılıcı (sağ) ----
        s0 = step
        base_a, base_b = P(0.36 + s0, 0.86), P(0.36 + s0, 1.10)
        tip = P(1.78 + s0, 0.98)
        add_glow(surf, *P(1.05 + s0, 0.98), r * 0.75, (150, 220, 255), 0.30 + 0.12 * math.sin(t * 4))
        blade = [base_a, P(1.50 + s0, 0.90), tip, P(1.50 + s0, 1.06), base_b]
        self._poly(surf, blade, (200, 236, 255), x, y, grow=0.03)
        pygame.draw.line(surf, WHITE, P(0.40 + s0, 0.98), P(1.66 + s0, 0.98), 2)
        pygame.draw.line(surf, OUTLINE, P(0.30 + s0, 0.70), P(0.30 + s0, 1.26), max(5, int(r * 0.15)))
        pygame.draw.line(surf, (120, 170, 220), P(0.30 + s0, 0.72), P(0.30 + s0, 1.24), max(3, int(r * 0.09)))
        pygame.draw.line(surf, (90, 70, 60), P(0.30 + s0, 0.98), P(0.05 + s0, 0.98), max(3, int(r * 0.10)))
        # ---- gövde: köşeli buz plaka ----
        body = [P(0.60, 0.40), P(0.34, 0.84), P(-0.44, 0.92), P(-0.82, 0.50),
                P(-0.82, -0.50), P(-0.44, -0.92), P(0.34, -0.84), P(0.60, -0.40)]
        self._poly(surf, body, col, x, y, grow=0.09)
        facet = [P(0.42, 0.0), P(0.0, 0.52), P(-0.52, 0.0), P(0.0, -0.52)]
        pygame.draw.polygon(surf, lite, facet)
        pygame.draw.polygon(surf, dark, facet, 2)
        pygame.draw.line(surf, WHITE, P(0.30, -0.10), P(-0.30, -0.36), 2)
        # omuz sarkıtları
        for sgn in (-1, 1):
            pl = [P(-0.30, 0.62 * sgn), P(-0.12, 1.12 * sgn), P(0.34, 1.02 * sgn), P(0.40, 0.60 * sgn)]
            self._poly(surf, pl, dark, x, y, grow=0.04)
            for i in range(3):
                self._crystal(surf, P(-0.24 + i * 0.20, 1.04 * sgn), P(-0.08 + i * 0.20, 1.04 * sgn),
                              P(-0.16 + i * 0.20, (1.36 + 0.06 * (i % 2)) * sgn), (214, 240, 255))
        # ---- kristal kalkan (sol) ----
        sh = [P(0.66, -1.0), P(0.36, -0.60), P(-0.26, -0.70), P(-0.50, -1.0),
              P(-0.26, -1.30), P(0.36, -1.40)]
        self._poly(surf, sh, (150, 210, 250), x, y, grow=0.05)
        poly_alpha(surf, [P(0.50, -1.0), P(0.30, -0.72), P(-0.14, -0.80), P(-0.14, -1.0)], WHITE, 90)
        cx_, cy_ = P(0.06, -1.0)
        for i in range(3):
            a = i * math.pi / 3 + t * 0.4
            dx_, dy_ = math.cos(a) * r * 0.24, math.sin(a) * r * 0.24
            pygame.draw.line(surf, (40, 90, 160), (cx_ - dx_, cy_ - dy_), (cx_ + dx_, cy_ + dy_), 3)
        pygame.draw.polygon(surf, (60, 110, 180), sh, 2)
        # ---- miğfer: buz boynuzları + T vizör ----
        hx, hy = P(0.48, 0.0)
        for sgn in (-1, 1):
            self._crystal(surf, P(0.56, 0.18 * sgn), P(0.40, 0.30 * sgn), P(0.95, 0.62 * sgn), (220, 244, 255))
        pygame.draw.circle(surf, OUTLINE, (int(hx), int(hy)), int(r * 0.40))
        pygame.draw.circle(surf, dark, (int(hx), int(hy)), int(r * 0.35))
        pygame.draw.circle(surf, lite, (int(hx - fx_ * r * 0.06), int(hy - fy_ * r * 0.06)), int(r * 0.26))
        pygame.draw.line(surf, (14, 22, 40), P(0.66, -0.20), P(0.66, 0.20), max(3, int(r * 0.12)))
        pygame.draw.line(surf, (14, 22, 40), P(0.66, 0.0), P(0.40, 0.0), max(3, int(r * 0.10)))
        add_glow(surf, *P(0.66, 0.0), r * 0.40, (120, 220, 255), 0.55 + 0.2 * math.sin(t * 5))
        pygame.draw.line(surf, (170, 240, 255), P(0.66, -0.16), P(0.66, 0.16), 2)

    def _art_frost_queen(self, surf, x, y, r, col, t):
        """ayaz kraliçesi: kat kat kristal etek, uzun beyaz saç, sivri buz tacı, kar tanesi asası"""
        y = y + math.sin(t * 1.7) * r * 0.10
        r = r * 1.12
        P, fx_, fy_, sx_, sy_ = self._mapper(x, y, r)
        deep = scale_col(col, 0.62)
        dark = scale_col(col, 0.42)
        for i in range(6):
            a = t * 0.9 + i * math.tau / 6
            gx = x + math.cos(a) * r * 1.65
            gy = y + math.sin(a) * r * 1.65 * 0.6 + r * 0.25
            sh = rot_pts([(0, -r * 0.20), (r * 0.08, 0), (0, r * 0.20), (-r * 0.08, 0)], a * 1.5, gx, gy)
            add_glow(surf, gx, gy, r * 0.25, (180, 230, 255), 0.30)
            pygame.draw.polygon(surf, OUTLINE, sh, 3)
            pygame.draw.polygon(surf, (220, 244, 255), sh)
        hair = [P(0.40, 0.30), P(-0.20, 0.48)]
        for i in range(5):
            k = i / 4.0
            hair.append(P(-1.15 - 0.18 * math.sin(k * math.pi) + 0.06 * math.sin(t * 2 + i),
                          (0.42 - 0.84 * k) + math.sin(t * 2.4 + i) * 0.08))
        hair += [P(-0.20, -0.48), P(0.40, -0.30)]
        self._poly(surf, hair, (238, 246, 255), x, y, grow=0.05)
        pygame.draw.lines(surf, (170, 196, 230), False, [P(0.1, 0.0), P(-0.6, 0.05), P(-1.1, 0.0)], 2)
        rot = t * 0.25
        for layer, (ro, ri) in enumerate(((1.12, 0.82), (0.86, 0.60))):
            pts = []
            for i in range(24):
                a = rot * (1 if layer else -1) + i * math.tau / 24
                rr = ro if i % 2 == 0 else ri
                pts.append((x + math.cos(a) * r * rr, y + math.sin(a) * r * rr))
            if layer == 0:
                self._poly(surf, pts, deep, x, y, grow=0.04)
                poly_alpha(surf, pts, WHITE, 40)
            else:
                self._poly(surf, pts, col, x, y, grow=0.05)
                pygame.draw.polygon(surf, WHITE, pts, 1)
        torso = [P(0.44, 0.0), P(0.18, 0.40), P(-0.30, 0.34), P(-0.30, -0.34), P(0.18, -0.40)]
        self._poly(surf, torso, (232, 242, 255), x, y, grow=0.07)
        pygame.draw.line(surf, dark, P(0.30, 0.0), P(-0.24, 0.0), 2)
        grip, top = P(0.10, 0.82), P(1.20, 0.95)
        pygame.draw.line(surf, OUTLINE, grip, top, max(5, int(r * 0.13)))
        pygame.draw.line(surf, (200, 230, 255), grip, top, max(3, int(r * 0.07)))
        add_glow(surf, top[0], top[1], r * 0.75, (160, 230, 255), 0.50 + 0.2 * math.sin(t * 4))
        for i in range(6):
            a = t * 1.5 + i * math.pi / 3
            ex, ey = top[0] + math.cos(a) * r * 0.32, top[1] + math.sin(a) * r * 0.32
            pygame.draw.line(surf, OUTLINE, top, (ex, ey), 5)
            pygame.draw.line(surf, WHITE, top, (ex, ey), 3)
            pygame.draw.circle(surf, (150, 220, 255), (int(ex), int(ey)), max(2, int(r * 0.05)))
        hx, hy = P(0.36, 0.0)
        hr = r * 0.28
        for i in range(9):
            a = math.atan2(fy_, fx_) + (i - 4) * 0.40
            ln = (0.40 if i % 2 == 0 else 0.24) + (0.14 if i == 4 else 0.0)
            ca, sa = math.cos(a), math.sin(a)
            base_a = (hx + ca * hr - sa * r * 0.08, hy + sa * hr + ca * r * 0.08)
            base_b = (hx + ca * hr + sa * r * 0.08, hy + sa * hr - ca * r * 0.08)
            self._crystal(surf, base_a, base_b, (hx + ca * (hr + r * ln), hy + sa * (hr + r * ln)),
                          (120, 200, 250) if i % 2 == 0 else (200, 238, 255))
        pygame.draw.circle(surf, OUTLINE, (int(hx), int(hy)), int(hr + 3))
        pygame.draw.circle(surf, (226, 238, 252), (int(hx), int(hy)), int(hr))
        self._boss_eyes(surf, P, r, t, n=2, spread=0.10, fwd=0.52, sz=0.06,
                        col=(240, 250, 255), glow=(60, 180, 255))
        gx, gy = P(0.62, 0.0)
        pygame.draw.circle(surf, (40, 160, 255), (int(gx), int(gy)), max(2, int(r * 0.05)))

    def _art_frost_giant(self, surf, x, y, r, col, t):
        """Buzul devi: köşeli buz bloklarından gövde, sırtında kristal kümeleri, omuzlarında kar"""
        P, fx_, fy_, sx_, sy_ = self._mapper(x, y, r)
        dark = scale_col(col, 0.55)
        lite = lighten(col, 0.38)
        step = math.sin(self.gait) * 0.13
        pulse = 0.55 + 0.45 * math.sin(t * 3.0)
        # ---- bacaklar ----
        for sgn in (-1, 1):
            fo = step * sgn
            foot = [P(-0.90 + fo, 0.28 * sgn), P(-1.32 + fo, 0.36 * sgn), P(-1.26 + fo, 0.82 * sgn),
                    P(-0.92 + fo, 0.74 * sgn)]
            self._poly(surf, foot, dark, x, y, grow=0.05)
        # ---- sırt kristal kümeleri ----
        for (bf, bs, ang0) in ((-0.55, 0.55, 2.3), (-0.75, 0.0, math.pi), (-0.55, -0.55, -2.3),
                               (-0.15, 0.85, 1.9), (-0.15, -0.85, -1.9)):
            for j in range(3):
                a = ang0 + (j - 1) * 0.35
                ca, sa = math.cos(a), math.sin(a)
                ln = 0.55 + 0.15 * ((j + int(bf * 10)) % 2)
                b0 = P(bf - sa * 0.07, bs + ca * 0.07)
                b1 = P(bf + sa * 0.07, bs - ca * 0.07)
                tip = P(bf + ca * ln, bs + sa * ln)
                self._crystal(surf, b0, b1, tip, (190, 230, 255) if j != 1 else (150, 210, 250))
        # ---- kollar + buz yumrukları ----
        for sgn in (-1, 1):
            fo = -step * sgn
            self._limb(surf, [P(0.20, 0.86 * sgn), P(0.58 + fo, 1.16 * sgn)], dark, max(8, int(r * 0.28)))
            fc = P(0.82 + fo, 1.24 * sgn)
            hexa = [(fc[0] + math.cos(a) * r * 0.44, fc[1] + math.sin(a) * r * 0.44)
                    for a in [i * math.tau / 6 + 0.3 for i in range(6)]]
            self._poly(surf, hexa, col, fc[0], fc[1], grow=0.12)
            pygame.draw.polygon(surf, lite, hexa[:3] + [fc], 0)
            pygame.draw.polygon(surf, WHITE, hexa, 1)
        # ---- gövde: düzensiz buz kütlesi ----
        body = []
        for j in range(9):
            a = j * math.tau / 9 + 0.2
            jit = 1.0 + 0.14 * math.sin(j * 2.3)
            body.append(P(math.cos(a) * 0.95 * jit, math.sin(a) * 1.08 * jit))
        self._poly(surf, body, col, x, y, grow=0.06)
        poly_alpha(surf, [body[0], body[1], body[2], P(0.0, 0.0)], WHITE, 60)
        poly_alpha(surf, [body[5], body[6], P(0.0, 0.0)], (20, 60, 120), 50)
        # çekirdek
        cx, cy = P(0.05, 0.0)
        add_glow(surf, cx, cy, r * (0.80 + 0.25 * pulse), (90, 190, 255), 0.45 + 0.25 * pulse)
        pygame.draw.circle(surf, (30, 80, 150), (int(cx), int(cy)), int(r * 0.30))
        pygame.draw.circle(surf, (170, 240, 255), (int(cx), int(cy)), int(r * (0.13 + 0.06 * pulse)))
        for i in range(5):
            a = i * math.tau / 5 + 0.4
            pygame.draw.line(surf, (200, 240, 255), (cx + math.cos(a) * r * 0.30, cy + math.sin(a) * r * 0.30),
                             (cx + math.cos(a) * r * 0.72, cy + math.sin(a) * r * 0.72), 1)
        # omuz karları
        for sgn in (-1, 1):
            for i, (ff, ss, rr) in enumerate(((0.35, 0.72, 0.24), (0.15, 0.88, 0.20), (0.48, 0.54, 0.16))):
                c0 = P(ff, ss * sgn)
                pygame.draw.circle(surf, (250, 252, 255), (int(c0[0]), int(c0[1])), max(3, int(r * rr)))
        # ---- baş: küçük blok + kırağı sakal ----
        head = [P(1.06, 0.24), P(1.06, -0.24), P(0.58, -0.34), P(0.58, 0.34)]
        self._poly(surf, head, dark, x, y, grow=0.06)
        for i in range(5):
            s_ = -0.24 + i * 0.12
            self._crystal(surf, P(1.02, s_ - 0.05), P(1.02, s_ + 0.05), P(1.28 + 0.06 * (i % 2), s_), WHITE)
        self._boss_eyes(surf, P, r, t, n=2, spread=0.12, fwd=0.88, sz=0.07,
                        col=(230, 250, 255), glow=(80, 190, 255))

    def _art_frost_wraith(self, surf, x, y, r, col, t):
        """kar orakçısı: kar savuran yırtık beyaz pelerin, kırağılı kukuleta, sarkıt orak, buz nefesi."""
        y = y + math.sin(t * 2.0) * r * 0.10
        P, fx_, fy_, sx_, sy_ = self._mapper(x, y, r)
        dark = scale_col(col, 0.50)
        # ---- savrulan kar perdeleri (arkada, saydam) ----
        for i in range(5):
            s0 = (i - 2) * 0.36
            pts = [P(-0.2, s0)]
            for k in range(1, 6):
                pts.append(P(-0.2 - k * 0.30, s0 + math.sin(t * 3 + i + k * 0.9) * 0.16 * k / 3))
            pygame.draw.lines(surf, (200, 230, 250), False, pts, max(2, int(r * (0.16 - i % 2 * 0.05))))
        for i in range(8):
            ph = (t * 0.8 + i * 0.13) % 1.0
            px_, py_ = P(-0.4 - ph * 1.6, math.sin(i * 2.1 + t) * 0.8)
            blit_disc(surf, px_, py_, 2.5, WHITE, int(220 * (1 - ph)))
        # ---- pelerin: dişli etek ----
        robe = [P(0.52, 0.30), P(0.30, 0.60), P(-0.20, 0.82)]
        for i in range(9):
            k = i / 8.0
            jag = 0.34 if i % 2 else 0.0
            robe.append(P(-0.86 - 0.36 * math.sin(k * math.pi) - jag + math.sin(t * 3.6 + i) * 0.07,
                          (0.5 - k) * 2.20))
        robe += [P(-0.20, -0.82), P(0.30, -0.60), P(0.52, -0.30)]
        self._poly(surf, robe, col, x, y, grow=0.05)
        poly_alpha(surf, robe[3:-3], WHITE, 45)
        pygame.draw.polygon(surf, dark, robe, 2)
        # ---- sarkıt orak (sağ) ----
        h0, h1 = P(-0.50, 0.92), P(1.25, 0.92)
        pygame.draw.line(surf, OUTLINE, h0, h1, max(5, int(r * 0.12)))
        pygame.draw.line(surf, (150, 190, 220), h0, h1, max(3, int(r * 0.07)))
        blade = [P(1.25, 0.92)]
        for i in range(1, 8):
            k = i / 7.0
            blade.append(P(1.25 - 0.55 * math.sin(k * math.pi * 0.5) * k, 0.92 - 1.25 * k))
        for i in range(6, 0, -1):
            k = i / 7.0
            blade.append(P(1.10 - 0.42 * math.sin(k * math.pi * 0.5) * k, 0.92 - 1.05 * k))
        add_glow(surf, *P(1.0, 0.30), r * 0.70, (160, 230, 255), 0.30)
        self._poly(surf, blade, (214, 242, 255), x, y, grow=0.03)
        pygame.draw.lines(surf, WHITE, False, blade[:8], 1)
        # ---- kukuleta + kırağı saçak ----
        hood = [P(0.76, 0.0), P(0.46, 0.50), P(-0.24, 0.58), P(-0.56, 0.0), P(-0.24, -0.58), P(0.46, -0.50)]
        self._poly(surf, hood, lighten(col, 0.25), x, y, grow=0.05)
        for i in range(7):
            s_ = -0.42 + i * 0.14
            f_ = 0.60 - abs(s_) * 0.5
            self._crystal(surf, P(f_, s_ - 0.05), P(f_, s_ + 0.05), P(f_ + 0.22 + 0.06 * (i % 2), s_),
                          (226, 246, 255))
        inner = [P(0.56, 0.0), P(0.30, 0.30), P(-0.10, 0.32), P(-0.24, 0.0), P(-0.10, -0.32), P(0.30, -0.30)]
        pygame.draw.polygon(surf, (10, 16, 30), inner)
        self._boss_eyes(surf, P, r, t, n=2, spread=0.13, fwd=0.26, sz=0.085,
                        col=(230, 250, 255), glow=(90, 210, 255))
        # buz nefesi
        for i in range(3):
            ph = (t * 1.2 + i / 3.0) % 1.0
            bx, by = P(0.80 + ph * 0.6, math.sin(t * 3 + i) * 0.1)
            blit_disc(surf, bx, by, r * (0.10 + 0.14 * ph), (220, 240, 255), int(120 * (1 - ph)))

    def _art_frost_spider(self, surf, x, y, r, col, t):
        """buz kovanı: kristal örümcek kraliçe - altıgen desenli buz karın, sekiz köşeli kristal bacak"""
        P, fx_, fy_, sx_, sy_ = self._mapper(x, y, r)
        dark = scale_col(col, 0.55)
        lite = lighten(col, 0.40)
        # ---- bacaklar ----
        for sgn in (-1, 1):
            for i in range(4):
                ph = self.gait + i * 1.3 + (0 if sgn > 0 else math.pi)
                sw = math.sin(ph) * 0.12
                rf = 0.42 - i * 0.22
                self._seg_leg(surf, P, (rf, 0.30 * sgn), (rf + 0.25 + sw - i * 0.08, 1.05 * sgn),
                              (rf + 0.10 + sw * 1.6 - i * 0.22, 1.55 * sgn), (170, 220, 250), max(3, int(r * 0.10)))
                ft = P(rf + 0.10 + sw * 1.6 - i * 0.22, 1.55 * sgn)
                pygame.draw.circle(surf, WHITE, (int(ft[0]), int(ft[1])), max(2, int(r * 0.05)))
        # ---- kristal yumurtalar ----
        for i, (ff, ss) in enumerate(((-1.25, 0.60), (-1.35, -0.45), (-1.50, 0.05))):
            ex, ey = P(ff, ss)
            add_glow(surf, ex, ey, r * 0.28, (170, 230, 255), 0.25 + 0.15 * math.sin(t * 3 + i))
            pygame.draw.circle(surf, OUTLINE, (int(ex), int(ey)), int(r * 0.19))
            pygame.draw.circle(surf, (210, 240, 255), (int(ex), int(ey)), int(r * 0.15))
        # ---- karın ----
        ab_c = P(-0.62, 0.0)
        ab = []
        for j in range(12):
            a = j * math.tau / 12
            ab.append((ab_c[0] + (fx_ * math.cos(a) * 0.72 + sx_ * math.sin(a) * 0.62) * r,
                       ab_c[1] + (fy_ * math.cos(a) * 0.72 + sy_ * math.sin(a) * 0.62) * r))
        self._poly(surf, ab, col, ab_c[0], ab_c[1], grow=0.08)
        for (ff, ss) in ((-0.40, 0.0), (-0.70, 0.30), (-0.70, -0.30), (-0.98, 0.0), (-0.42, 0.42), (-0.42, -0.42)):
            c0 = P(ff, ss)
            hexa = [(c0[0] + math.cos(a) * r * 0.15, c0[1] + math.sin(a) * r * 0.15)
                    for a in [k * math.tau / 6 for k in range(6)]]
            pygame.draw.polygon(surf, lite, hexa, 2)
        poly_alpha(surf, ab[9:] + ab[:3] + [ab_c], WHITE, 50)
        add_glow(surf, *P(-0.62, 0.0), r * 0.5, (120, 210, 255), 0.25)
        # ---- göğüs + baş ----
        th = [P(0.72, 0.0), P(0.50, 0.36), P(0.04, 0.40), P(-0.10, 0.0), P(0.04, -0.40), P(0.50, -0.36)]
        self._poly(surf, th, dark, x, y, grow=0.07)
        pygame.draw.polygon(surf, lite, [P(0.60, 0.0), P(0.30, 0.18), P(0.10, 0.0), P(0.30, -0.18)])
        for sgn in (-1, 1):
            self._crystal(surf, P(0.70, 0.10 * sgn), P(0.66, 0.22 * sgn), P(1.00, 0.12 * sgn), WHITE)
        for (ff, ss, sz) in ((0.58, 0.10, 0.06), (0.58, -0.10, 0.06), (0.50, 0.22, 0.045), (0.50, -0.22, 0.045),
                             (0.66, 0.0, 0.05)):
            ex, ey = P(ff, ss)
            add_glow(surf, ex, ey, r * sz * 3, (90, 210, 255), 0.4)
            pygame.draw.circle(surf, (210, 250, 255), (int(ex), int(ey)), max(2, int(r * sz)))

    # orman
    def _art_jungle_chief(self, surf, x, y, r, col, t):
        """Orman reisi: tüy başlık, oyma tiki maskesi, kemik kolye, yaprak etek, taş uçlu mızrak, boyalı ahşap kalkan."""
        P, fx_, fy_, sx_, sy_ = self._mapper(x, y, r)
        step = math.sin(self.gait) * 0.12
        skin = col
        dark = scale_col(col, 0.55)
        wood = (150, 98, 52)
        # ---- yaprak etek (arkada) ----
        for i in range(9):
            a = math.atan2(-fy_, -fx_) + (i - 4) * 0.34
            self._leaf(surf, P(-0.30, 0.0), a + math.sin(t * 2 + i) * 0.06, r * 1.05, r * 0.20,
                       (70, 150, 60) if i % 2 else (110, 186, 70))
        # ---- mızrak (sağ) ----
        s0 = step
        g0, g1 = P(-0.40 + s0, 0.92), P(1.55 + s0, 0.92)
        pygame.draw.line(surf, OUTLINE, g0, g1, max(5, int(r * 0.12)))
        pygame.draw.line(surf, wood, g0, g1, max(3, int(r * 0.07)))
        tip = [P(1.50 + s0, 0.80), P(1.92 + s0, 0.92), P(1.50 + s0, 1.04)]
        self._poly(surf, tip, (150, 150, 160), x, y, grow=0.04)
        for k, c_ in enumerate(((230, 60, 60), (250, 210, 70))):
            fp = P(1.40 + s0, 0.92)
            self._leaf(surf, fp, math.atan2(-fy_, -fx_) + (0.5 if k else -0.5), r * 0.40, r * 0.08, c_, c_)
        # ---- gövde ----
        body = [P(0.56, 0.42), P(0.28, 0.80), P(-0.40, 0.84), P(-0.72, 0.42),
                P(-0.72, -0.42), P(-0.40, -0.84), P(0.28, -0.80), P(0.56, -0.42)]
        self._poly(surf, body, skin, x, y, grow=0.09)
        for sgn in (-1, 1):                      # kabile boyası
            pygame.draw.line(surf, (240, 236, 220), P(0.30, 0.30 * sgn), P(-0.30, 0.55 * sgn), 3)
            pygame.draw.line(surf, (200, 50, 40), P(0.20, 0.40 * sgn), P(-0.36, 0.66 * sgn), 2)
        # kemik kolye
        for i in range(7):
            a = (i - 3) * 0.32
            bx, by = P(0.32 - abs(a) * 0.35, a * 1.05)
            pygame.draw.ellipse(surf, OUTLINE, (bx - r * 0.09, by - r * 0.06, r * 0.18, r * 0.12))
            pygame.draw.ellipse(surf, (244, 236, 210), (bx - r * 0.07, by - r * 0.045, r * 0.14, r * 0.09))
        # ---- kalkan (sol) ----
        sc = P(0.20 + step, -1.02)
        pygame.draw.circle(surf, OUTLINE, (int(sc[0]), int(sc[1])), int(r * 0.50))
        pygame.draw.circle(surf, wood, (int(sc[0]), int(sc[1])), int(r * 0.45))
        for k in range(3):
            rr = r * (0.36 - k * 0.11)
            box = pygame.Rect(0, 0, int(rr * 2), int(rr * 2))
            box.center = (int(sc[0]), int(sc[1]))
            pygame.draw.arc(surf, (230, 200, 90) if k % 2 == 0 else (200, 60, 40), box,
                            t * 0.5 + k, t * 0.5 + k + 4.4, 3)
        # ---- tüy başlık ----
        hx, hy = P(0.44, 0.0)
        cols = ((220, 50, 50), (250, 200, 60), (60, 170, 80), (60, 120, 220))
        for i in range(11):
            a = math.atan2(-fy_, -fx_) + (i - 5) * 0.27 + math.sin(t * 2.4 + i) * 0.03
            ln = r * (1.15 - abs(i - 5) * 0.06)
            self._leaf(surf, (hx, hy), a, ln, r * 0.14, cols[i % 4], (40, 30, 20))
        # ---- tiki maskesi ----
        mask = [P(0.80, 0.26), P(0.80, -0.26), P(0.22, -0.32), P(0.22, 0.32)]
        self._poly(surf, mask, (168, 112, 58), x, y, grow=0.08)
        pygame.draw.line(surf, (90, 56, 28), P(0.62, -0.26), P(0.62, 0.26), 2)
        pygame.draw.line(surf, (230, 220, 190), P(0.74, -0.18), P(0.74, 0.18), 3)   # dişler
        for i in range(4):
            s_ = -0.15 + i * 0.10
            pygame.draw.line(surf, (90, 56, 28), P(0.70, s_), P(0.78, s_), 1)
        for sgn in (-1, 1):
            pygame.draw.line(surf, (40, 160, 90), P(0.30, 0.20 * sgn), P(0.54, 0.24 * sgn), 3)
        self._boss_eyes(surf, P, r, t, n=2, spread=0.12, fwd=0.48, sz=0.07,
                        col=(255, 240, 160), glow=(255, 170, 40))

    def _art_jungle_witch(self, surf, x, y, r, col, t):
        """Sarmaşık cadısı: yapraklardan elbise, savrulan sarmaşık kolları, çiçekli yeşil saç"""
        y = y + math.sin(t * 1.6) * r * 0.08
        P, fx_, fy_, sx_, sy_ = self._mapper(x, y, r)
        dark = scale_col(col, 0.50)
        lite = lighten(col, 0.30)
        # ---- sarmaşık kolları ----
        for i in range(5):
            a0 = i * math.tau / 5 + t * 0.35
            p0 = (x + math.cos(a0) * r * 0.6, y + math.sin(a0) * r * 0.6)
            bend = math.sin(t * 2.2 + i * 1.7) * 0.8
            p1 = (x + math.cos(a0 + bend * 0.4) * r * 1.35, y + math.sin(a0 + bend * 0.4) * r * 1.35)
            p2 = (x + math.cos(a0 + bend) * r * 1.95, y + math.sin(a0 + bend) * r * 1.95)
            pts = _qbez(p0, p1, p2, 10)
            pygame.draw.lines(surf, OUTLINE, False, pts, max(5, int(r * 0.13)))
            pygame.draw.lines(surf, (60, 120, 40), False, pts, max(3, int(r * 0.08)))
            for k in (3, 6, 9):
                pa, pb = pts[k], pts[k - 1]
                ang = math.atan2(pa[1] - pb[1], pa[0] - pb[0]) + (1.2 if k % 2 else -1.2)
                self._leaf(surf, pa, ang, r * 0.30, r * 0.09, (100, 190, 70))
        # ---- yaprak elbise ----
        for i in range(14):
            a = i * math.tau / 14 + 0.2
            self._leaf(surf, (x, y), a, r * (1.05 + 0.10 * (i % 2)), r * 0.30,
                       col if i % 2 else lite, dark)
        pygame.draw.circle(surf, OUTLINE, (int(x), int(y)), int(r * 0.52))
        pygame.draw.circle(surf, dark, (int(x), int(y)), int(r * 0.48))
        # ---- saç (çiçekli) ----
        hair = [P(0.42, 0.30), P(-0.10, 0.50), P(-0.62, 0.36), P(-0.80, 0.0), P(-0.62, -0.36),
                P(-0.10, -0.50), P(0.42, -0.30)]
        self._poly(surf, hair, (40, 96, 50), x, y, grow=0.05)
        for i, (ff, ss) in enumerate(((-0.20, 0.36), (-0.50, -0.20), (-0.30, -0.40), (-0.62, 0.16), (0.0, -0.44))):
            c0 = P(ff, ss)
            pc = (236, 90, 140) if i % 2 else (250, 220, 90)
            for k in range(5):
                a = k * math.tau / 5 + t * 0.5
                blit_disc(surf, c0[0] + math.cos(a) * r * 0.07, c0[1] + math.sin(a) * r * 0.07,
                          max(2.0, r * 0.06), pc, 255)
            pygame.draw.circle(surf, (255, 240, 160), (int(c0[0]), int(c0[1])), max(1, int(r * 0.03)))
        # ---- burgulu asa (sağ) ----
        g0, g1 = P(-0.10, 0.80), P(1.25, 0.95)
        pts_a, pts_b = [], []
        for i in range(11):
            k = i / 10.0
            bx = g0[0] + (g1[0] - g0[0]) * k
            by = g0[1] + (g1[1] - g0[1]) * k
            w = math.sin(k * 12 + t) * r * 0.06
            pts_a.append((bx + sx_ * w, by + sy_ * w))
            pts_b.append((bx - sx_ * w, by - sy_ * w))
        pygame.draw.lines(surf, OUTLINE, False, pts_a, max(5, int(r * 0.11)))
        pygame.draw.lines(surf, (110, 72, 40), False, pts_a, max(3, int(r * 0.06)))
        pygame.draw.lines(surf, (140, 96, 54), False, pts_b, max(2, int(r * 0.05)))
        add_glow(surf, g1[0], g1[1], r * 0.70, (255, 130, 200), 0.45 + 0.2 * math.sin(t * 4))
        for k in range(6):
            a = k * math.tau / 6 + t * 0.8
            self._leaf(surf, g1, a, r * 0.30, r * 0.11, (246, 120, 180), (180, 60, 120))
        pygame.draw.circle(surf, (255, 236, 140), (int(g1[0]), int(g1[1])), max(2, int(r * 0.08)))
        # ---- yüz ----
        hx, hy = P(0.34, 0.0)
        pygame.draw.circle(surf, OUTLINE, (int(hx), int(hy)), int(r * 0.30))
        pygame.draw.circle(surf, (176, 214, 140), (int(hx), int(hy)), int(r * 0.26))
        self._boss_eyes(surf, P, r, t, n=2, spread=0.10, fwd=0.48, sz=0.06,
                        col=(240, 255, 200), glow=(190, 255, 80))

    def _art_jungle_ent(self, surf, x, y, r, col, t):
        """Kadim ent: kabuklu gövde, yaprak tacı, dal kollar, kök ayaklar, oyuk yüzünde kehribar gözler"""
        P, fx_, fy_, sx_, sy_ = self._mapper(x, y, r)
        bark = col
        dark = scale_col(col, 0.55)
        step = math.sin(self.gait) * 0.12
        # ---- kökler ----
        for i in range(7):
            a = math.atan2(-fy_, -fx_) + (i - 3) * 0.42
            ca, sa = math.cos(a), math.sin(a)
            p0 = (x + ca * r * 0.6, y + sa * r * 0.6)
            wig = math.sin(self.gait + i) * 0.12
            p1 = (x + math.cos(a + wig) * r * 1.15, y + math.sin(a + wig) * r * 1.15)
            p2 = (x + math.cos(a - wig) * r * 1.55, y + math.sin(a - wig) * r * 1.55)
            pts = _qbez(p0, p1, p2, 6)
            pygame.draw.lines(surf, OUTLINE, False, pts, max(6, int(r * 0.20)))
            pygame.draw.lines(surf, dark, False, pts, max(4, int(r * 0.14)))
        # ---- dal kollar ----
        for sgn in (-1, 1):
            fo = -step * sgn
            a0, a1, a2 = P(0.10, 0.80 * sgn), P(0.55 + fo, 1.20 * sgn), P(0.95 + fo, 1.30 * sgn)
            self._limb(surf, [a0, a1, a2], dark, max(7, int(r * 0.24)))
            for k in (-0.35, 0.0, 0.35):
                ang = math.atan2(fy_, fx_) + k * sgn + 0.3 * sgn
                tp = (a2[0] + math.cos(ang) * r * 0.36, a2[1] + math.sin(ang) * r * 0.36)
                pygame.draw.line(surf, OUTLINE, a2, tp, max(4, int(r * 0.10)))
                pygame.draw.line(surf, bark, a2, tp, max(2, int(r * 0.06)))
            self._leaf(surf, a1, math.atan2(fy_, fx_) + 1.6 * sgn, r * 0.42, r * 0.13, (90, 170, 60))
        # ---- gövde ----
        body = []
        for j in range(10):
            a = j * math.tau / 10
            jit = 1.0 + 0.08 * math.sin(j * 3.1)
            body.append(P(math.cos(a) * 0.88 * jit, math.sin(a) * 0.86 * jit))
        self._poly(surf, body, bark, x, y, grow=0.07)
        for i in range(6):
            s_ = -0.60 + i * 0.24
            pts = [P(0.70 - abs(s_) * 0.4, s_), P(0.10, s_ + 0.05 * math.sin(i)),
                   P(-0.70 + abs(s_) * 0.4, s_ - 0.03)]
            pygame.draw.lines(surf, dark, False, pts, 2)
        # ---- yaprak tacı (arka yarı) ----
        greens = ((60, 130, 50), (90, 170, 60), (120, 196, 80), (70, 150, 56))
        for i, (ff, ss, rr) in enumerate(((-0.55, 0.0, 0.52), (-0.35, 0.55, 0.42), (-0.35, -0.55, 0.42),
                                          (-0.80, 0.42, 0.36), (-0.80, -0.42, 0.36), (-0.10, 0.80, 0.30),
                                          (-0.10, -0.80, 0.30), (-1.05, 0.0, 0.34))):
            c0 = P(ff, ss)
            sway = math.sin(t * 1.6 + i) * r * 0.03
            pygame.draw.circle(surf, OUTLINE, (int(c0[0] + sway), int(c0[1])), int(r * rr + 2))
            pygame.draw.circle(surf, greens[i % 4], (int(c0[0] + sway), int(c0[1])), int(r * rr))
            pygame.draw.circle(surf, lighten(greens[i % 4], 0.25),
                               (int(c0[0] + sway - r * rr * 0.3), int(c0[1] - r * rr * 0.3)), int(r * rr * 0.35))
        # mantarlar
        for (ff, ss) in ((0.30, 0.66), (0.42, -0.62)):
            c0 = P(ff, ss)
            pygame.draw.circle(surf, OUTLINE, (int(c0[0]), int(c0[1])), int(r * 0.15))
            pygame.draw.circle(surf, (220, 50, 50), (int(c0[0]), int(c0[1])), int(r * 0.12))
            for k in range(3):
                a = k * 2.1
                pygame.draw.circle(surf, WHITE, (int(c0[0] + math.cos(a) * r * 0.06),
                                                 int(c0[1] + math.sin(a) * r * 0.06)), max(1, int(r * 0.025)))
        # ---- oyuk yüz ----
        fc = P(0.50, 0.0)
        hollow = pygame.Rect(0, 0, int(r * 0.62), int(r * 0.62))
        hollow.center = (int(fc[0]), int(fc[1]))
        pygame.draw.ellipse(surf, (40, 26, 16), hollow)
        pygame.draw.ellipse(surf, dark, hollow, 2)
        self._boss_eyes(surf, P, r, t, n=2, spread=0.13, fwd=0.58, sz=0.075,
                        col=(255, 230, 140), glow=(255, 170, 40))
        pygame.draw.line(surf, (20, 12, 8), P(0.36, -0.12), P(0.36, 0.12), max(2, int(r * 0.06)))

    def _art_jungle_panther(self, surf, x, y, r, col, t):
        """Gölge panteri: dört ayak üstünde sinsi kara panter - uzun kıvrık kuyruk, mor parıltılı post"""
        r = r * 1.28                     # ince gövdeli; patron boyunda okunsun
        P, fx_, fy_, sx_, sy_ = self._mapper(x, y, r)
        fur = col
        sheen = lighten(col, 0.40)
        dark = scale_col(col, 0.55)
        g = self.gait * 1.4
        for i in range(3):
            c0 = P(-0.6 - i * 0.45, 0.0)
            blit_disc(surf, c0[0], c0[1], r * (0.45 - i * 0.1), (130, 80, 210), 55 - i * 15)
        sw = math.sin(t * 2.6) * 0.6
        tail = _qbez(P(-0.85, 0.0), P(-1.45, 0.45 * sw + 0.2), P(-1.70, -0.55 * sw), 10)
        pygame.draw.lines(surf, OUTLINE, False, tail, max(7, int(r * 0.20)))
        pygame.draw.lines(surf, fur, False, tail, max(5, int(r * 0.14)))
        for (rf, sgn, ph) in ((0.40, 1, 0.0), (0.40, -1, math.pi), (-0.55, 1, math.pi), (-0.55, -1, 0.0)):
            o = math.sin(g + ph) * 0.22
            root, knee, paw = (rf, 0.32 * sgn), (rf + 0.05 + o * 0.5, 0.62 * sgn), (rf + 0.20 + o, 0.74 * sgn)
            self._limb(surf, [P(*root), P(*knee), P(*paw)], dark, max(6, int(r * 0.18)))
            pc = P(*paw)
            pygame.draw.circle(surf, OUTLINE, (int(pc[0]), int(pc[1])), int(r * 0.15))
            pygame.draw.circle(surf, fur, (int(pc[0]), int(pc[1])), int(r * 0.12))
            for k in (-1, 0, 1):
                cx_ = pc[0] + (fx_ * 0.14 + sx_ * 0.06 * k) * r
                cy_ = pc[1] + (fy_ * 0.14 + sy_ * 0.06 * k) * r
                pygame.draw.circle(surf, (230, 230, 240), (int(cx_), int(cy_)), max(1, int(r * 0.025)))
        body = []
        for j in range(18):
            a = j * math.tau / 18
            body.append(P(math.cos(a) * 0.82 - 0.16, math.sin(a) * (0.48 - 0.07 * math.cos(a))))
        self._poly(surf, body, fur, x, y, grow=0.06)
        poly_alpha(surf, body[13:] + body[:2] + [P(-0.16, 0.0)], (180, 140, 255), 40)
        pygame.draw.lines(surf, sheen, False, [P(0.40, 0.0), P(-0.20, 0.04), P(-0.82, 0.0)], 3)
        for (ff, ss) in ((0.10, 0.24), (-0.30, -0.26), (-0.55, 0.22), (0.25, -0.22), (-0.10, 0.02)):
            c0 = P(ff, ss)
            pygame.draw.circle(surf, scale_col(fur, 0.65), (int(c0[0]), int(c0[1])), max(2, int(r * 0.08)), 2)
        hc = P(0.80, 0.0)
        for sgn in (-1, 1):
            ear = [P(0.82, 0.18 * sgn), P(0.66, 0.42 * sgn), P(0.62, 0.16 * sgn)]
            self._poly(surf, ear, fur, x, y, grow=0.08)
            pygame.draw.polygon(surf, (160, 90, 170), [P(0.76, 0.20 * sgn), P(0.68, 0.33 * sgn), P(0.66, 0.20 * sgn)])
        pygame.draw.circle(surf, OUTLINE, (int(hc[0]), int(hc[1])), int(r * 0.34))
        pygame.draw.circle(surf, fur, (int(hc[0]), int(hc[1])), int(r * 0.30))
        mz = P(1.04, 0.0)
        pygame.draw.circle(surf, OUTLINE, (int(mz[0]), int(mz[1])), int(r * 0.18))
        pygame.draw.circle(surf, dark, (int(mz[0]), int(mz[1])), int(r * 0.15))
        pygame.draw.circle(surf, (200, 120, 160), [int(v) for v in P(1.14, 0.0)], max(2, int(r * 0.05)))
        for sgn in (-1, 1):
            for k in (-0.08, 0.04):
                pygame.draw.line(surf, (210, 210, 230), P(1.06, 0.10 * sgn), P(1.16 + k, 0.42 * sgn), 1)
            ex, ey = P(0.92, 0.13 * sgn)
            add_glow(surf, ex, ey, r * 0.22, (210, 255, 60), 0.55 + 0.2 * math.sin(t * 5))
            pygame.draw.circle(surf, (230, 255, 90), (int(ex), int(ey)), max(2, int(r * 0.07)))
            pygame.draw.line(surf, (20, 20, 10), (ex - fx_ * r * 0.05, ey - fy_ * r * 0.05),
                             (ex + fx_ * r * 0.05, ey + fy_ * r * 0.05), 2)

    def _art_jungle_serpent(self, surf, x, y, r, col, t):
        """Yılan ana: halka halka kıvrılmış dev gövde, elmas pullar, açık kobra başlığı, çatal dil ve yanında yumurtalar."""
        P, fx_, fy_, sx_, sy_ = self._mapper(x, y, r)
        scale_c = col
        belly = (226, 214, 140)
        dark = scale_col(col, 0.50)
        # ---- yumurtalar ----
        for i, (ff, ss) in enumerate(((-1.20, 0.80), (-1.35, 0.55), (-1.10, 1.02))):
            ex, ey = P(ff, ss)
            pygame.draw.ellipse(surf, OUTLINE, (ex - r * 0.15, ey - r * 0.19, r * 0.30, r * 0.38))
            pygame.draw.ellipse(surf, (236, 230, 200), (ex - r * 0.12, ey - r * 0.16, r * 0.24, r * 0.32))
            pygame.draw.circle(surf, (140, 170, 90), (int(ex - r * 0.03), int(ey - r * 0.04)), max(1, int(r * 0.04)))
        # ---- kıvrımlar (sarmal) ----
        path = []
        turns = 1.65
        n = 40
        for i in range(n + 1):
            k = i / n
            a = -math.pi * 0.5 + k * turns * math.tau + t * 0.3
            rr = 0.95 - 0.62 * k
            path.append(P(-0.25 + math.cos(a) * rr * 0.95, math.sin(a) * rr))
        neck = _qbez(path[-1], P(0.25, 0.0), P(0.62, 0.0), 6)
        full = path + neck[1:]
        wbase = r * 0.36
        for i in range(len(full) - 1):
            w = int(wbase * (0.65 + 0.35 * (1 - i / len(full))) + 4)
            pygame.draw.line(surf, OUTLINE, full[i], full[i + 1], w + 4)
        for i in range(len(full) - 1):
            w = int(wbase * (0.65 + 0.35 * (1 - i / len(full))))
            pygame.draw.line(surf, scale_c if (i // 3) % 2 == 0 else lighten(scale_c, 0.12),
                             full[i], full[i + 1], w)
            pygame.draw.circle(surf, scale_c if (i // 3) % 2 == 0 else lighten(scale_c, 0.12),
                               (int(full[i][0]), int(full[i][1])), w // 2)
        for i in range(2, len(full) - 2, 3):
            cx_, cy_ = full[i]
            nx, ny = full[i + 1][0] - cx_, full[i + 1][1] - cy_
            nl = math.hypot(nx, ny) or 1.0
            nx, ny = nx / nl, ny / nl
            d = r * 0.10
            dia = [(cx_ + nx * d, cy_ + ny * d), (cx_ - ny * d * 0.8, cy_ + nx * d * 0.8),
                   (cx_ - nx * d, cy_ - ny * d), (cx_ + ny * d * 0.8, cy_ - nx * d * 0.8)]
            pygame.draw.polygon(surf, dark, dia)
            pygame.draw.polygon(surf, belly, dia, 1)
        # ---- kobra başlığı ----
        hood = []
        for j in range(14):
            a = j * math.tau / 14
            hood.append(P(0.70 + math.cos(a) * 0.30, math.sin(a) * 0.56))
        self._poly(surf, hood, scale_c, x, y, grow=0.08)
        for sgn in (-1, 1):
            c0 = P(0.66, 0.30 * sgn)
            pygame.draw.circle(surf, belly, (int(c0[0]), int(c0[1])), max(2, int(r * 0.10)))
            pygame.draw.circle(surf, (30, 30, 20), (int(c0[0]), int(c0[1])), max(1, int(r * 0.05)))
        # ---- baş + dil ----
        head = [P(1.16, 0.0), P(1.02, 0.18), P(0.80, 0.20), P(0.80, -0.20), P(1.02, -0.18)]
        self._poly(surf, head, dark, x, y, grow=0.08)
        if math.sin(t * 6) > 0.2:
            tg = [P(1.16, 0.0), P(1.40, 0.0)]
            pygame.draw.line(surf, (220, 40, 60), tg[0], tg[1], 2)
            pygame.draw.line(surf, (220, 40, 60), tg[1], P(1.50, 0.07), 2)
            pygame.draw.line(surf, (220, 40, 60), tg[1], P(1.50, -0.07), 2)
        for sgn in (-1, 1):
            ex, ey = P(0.98, 0.11 * sgn)
            add_glow(surf, ex, ey, r * 0.18, (255, 210, 40), 0.5)
            pygame.draw.circle(surf, (255, 220, 60), (int(ex), int(ey)), max(2, int(r * 0.06)))
            pygame.draw.line(surf, (10, 10, 10), (ex - fx_ * r * 0.04, ey - fy_ * r * 0.04),
                             (ex + fx_ * r * 0.04, ey + fy_ * r * 0.04), 2)

    # çöl
    def _nemes_head(self, surf, P, x, y, r, hf, hr, face_col, t, glow=(80, 200, 255)):
        """Çizgili nemes başlıklı baş: üstten çizgili başlık, iki yanda omza inen çizgili kanatlar"""
        gold, lapis = (236, 196, 72), (44, 70, 168)
        for sgn in (-1, 1):                       # omza inen kanatlar (öne-yana)
            flap = [P(hf + 0.10, (hr - 0.04) * sgn), P(hf + 0.06, (hr + 0.30) * sgn),
                    P(hf - 0.34, (hr + 0.40) * sgn), P(hf - 0.30, (hr + 0.02) * sgn)]
            pygame.draw.polygon(surf, OUTLINE, flap, 4)
            pygame.draw.polygon(surf, gold, flap)
            for k in range(1, 4):
                f_ = hf + 0.10 - k * 0.11
                pygame.draw.line(surf, lapis, P(f_, (hr - 0.02) * sgn), P(f_ - 0.02, (hr + 0.36) * sgn), 3)
        tail = [P(hf - hr * 0.8, 0.13), P(hf - hr - 0.42, 0.0), P(hf - hr * 0.8, -0.13)]
        self._poly(surf, tail, gold, x, y, grow=0.04)
        hc = P(hf, 0.0)
        pygame.draw.circle(surf, OUTLINE, (int(hc[0]), int(hc[1])), int(r * hr + 3))
        pygame.draw.circle(surf, gold, (int(hc[0]), int(hc[1])), int(r * hr))
        for k in range(5):                        # başlık çizgileri
            s_ = (k - 2) * hr * 0.38
            half = math.sqrt(max(0.0, hr * hr - s_ * s_)) * 0.95
            pygame.draw.line(surf, lapis, P(hf - half, s_), P(hf + half * 0.6, s_), 3)
        face = [P(hf + hr * 0.95, 0.17), P(hf + hr * 0.95, -0.17), P(hf + hr * 0.25, -0.24),
                P(hf + hr * 0.25, 0.24)]
        self._poly(surf, face, face_col, x, y, grow=0.07)
        for sgn in (-1, 1):
            pygame.draw.line(surf, (20, 20, 40), P(hf + hr * 0.62, 0.06 * sgn), P(hf + hr * 0.62, 0.20 * sgn), 2)
        self._boss_eyes(surf, P, r, t, n=2, spread=0.12, fwd=hf + hr * 0.62, sz=0.05,
                        col=(255, 250, 220), glow=glow)
        beard = [P(hf + hr * 0.95, 0.06), P(hf + hr * 0.95 + 0.20, 0.04), P(hf + hr * 0.95 + 0.20, -0.04),
                 P(hf + hr * 0.95, -0.06)]
        self._poly(surf, beard, lapis, x, y, grow=0.06)
        ux, uy = P(hf + hr * 0.30, 0.0)
        add_glow(surf, ux, uy, r * 0.26, (255, 220, 120), 0.45)
        pygame.draw.circle(surf, OUTLINE, (int(ux), int(uy)), max(3, int(r * 0.085)))
        pygame.draw.circle(surf, (250, 210, 90), (int(ux), int(uy)), max(2, int(r * 0.06)))
        pygame.draw.circle(surf, (200, 40, 40), (int(ux), int(uy)), max(1, int(r * 0.026)))

    def _art_desert_pharaoh(self, surf, x, y, r, col, t):
        """firavun: lacivert pelerin, renkli usekh gerdanlık, çapraz asa ve kamçı, çizgili nemes başlık"""
        P, fx_, fy_, sx_, sy_ = self._mapper(x, y, r)
        gold = col
        lapis = (40, 66, 160)
        turq = (60, 190, 190)
        skin = (186, 128, 78)
        step = math.sin(self.gait) * 0.10
        # ---- pelerin ----
        cape = [P(0.0, 0.62), P(-0.26, 0.86)]
        for i in range(5):
            k = i / 4.0
            cape.append(P(-0.92 - 0.20 * math.sin(k * math.pi), (0.5 - k) * 1.62 + math.sin(t * 2 + i) * 0.07))
        cape += [P(-0.26, -0.86), P(0.0, -0.62)]
        self._poly(surf, cape, (34, 50, 130), x, y, grow=0.04)
        pygame.draw.lines(surf, (236, 196, 72), False, cape[2:-2], 3)
        # ---- kamçı (sol) ----
        f0, f1 = P(0.10 + step, -0.66), P(0.92 + step, -0.92)
        pygame.draw.line(surf, OUTLINE, f0, f1, max(5, int(r * 0.12)))
        for i in range(6):
            a0 = (f0[0] + (f1[0] - f0[0]) * i / 6, f0[1] + (f1[1] - f0[1]) * i / 6)
            a1 = (f0[0] + (f1[0] - f0[0]) * (i + 1) / 6, f0[1] + (f1[1] - f0[1]) * (i + 1) / 6)
            pygame.draw.line(surf, gold if i % 2 else lapis, a0, a1, max(3, int(r * 0.08)))
        for k in range(3):
            sway = math.sin(t * 4 + k) * 0.10
            pts = [f1]
            for j in range(1, 5):
                pts.append(P(0.92 + step + j * 0.10 + sway * j * 0.3, -0.92 - (k - 1) * 0.07 * j - j * 0.03))
            pygame.draw.lines(surf, OUTLINE, False, pts, 4)
            for pt in pts[1:]:
                pygame.draw.circle(surf, gold if k != 1 else (200, 40, 40), (int(pt[0]), int(pt[1])),
                                   max(2, int(r * 0.05)))
        # ---- gövde: ten + keten etek + altın kemer ----
        body = [P(0.50, 0.40), P(0.26, 0.74), P(-0.40, 0.76), P(-0.68, 0.38),
                P(-0.68, -0.38), P(-0.40, -0.76), P(0.26, -0.74), P(0.50, -0.40)]
        self._poly(surf, body, skin, x, y, grow=0.09)
        kilt = [P(-0.20, 0.72), P(-0.40, 0.76), P(-0.68, 0.38), P(-0.68, -0.38), P(-0.40, -0.76), P(-0.20, -0.72)]
        pygame.draw.polygon(surf, (244, 236, 214), kilt)
        pygame.draw.line(surf, gold, P(-0.20, 0.72), P(-0.20, -0.72), max(3, int(r * 0.10)))
        # ---- usekh gerdanlık ----
        hc = P(0.30, 0.0)
        back = math.atan2(fy_, -fx_)
        for k, c_ in enumerate((gold, lapis, turq, (200, 50, 40), gold)):
            rr = r * (0.74 - k * 0.085)
            box = pygame.Rect(0, 0, int(rr * 2), int(rr * 2))
            box.center = (int(hc[0]), int(hc[1]))
            pygame.draw.arc(surf, c_, box, back - 1.25, back + 1.25, max(3, int(r * 0.09)))
        # ---- asa (crook, sağ) ----
        c0, c1 = P(0.0 + step, 0.76), P(1.15 + step, 0.84)
        pygame.draw.line(surf, OUTLINE, c0, c1, max(6, int(r * 0.13)))
        for i in range(6):
            a0 = (c0[0] + (c1[0] - c0[0]) * i / 6, c0[1] + (c1[1] - c0[1]) * i / 6)
            a1 = (c0[0] + (c1[0] - c0[0]) * (i + 1) / 6, c0[1] + (c1[1] - c0[1]) * (i + 1) / 6)
            pygame.draw.line(surf, gold if i % 2 == 0 else lapis, a0, a1, max(4, int(r * 0.09)))
        hook = _qbez(c1, P(1.42 + step, 0.84), P(1.36 + step, 0.58), 6)
        pygame.draw.lines(surf, OUTLINE, False, hook, max(6, int(r * 0.13)))
        pygame.draw.lines(surf, gold, False, hook, max(4, int(r * 0.09)))
        self._nemes_head(surf, P, x, y, r, 0.40, 0.36, (250, 214, 100), t)

    def _art_desert_mirage(self, surf, x, y, r, col, t):
        """Serap cadısı: iki yanında titreşen serap yansımaları, kuyruklu yıldız gibi arkaya akan ipek elbise"""
        y = y + math.sin(t * 1.9) * r * 0.10
        r = r * 1.10
        P, fx_, fy_, sx_, sy_ = self._mapper(x, y, r)
        silk = col
        gold = (246, 206, 90)

        def gown(off, k=1.0):
            pts = [P(0.55, off)]
            for j in range(1, 8):
                a = j / 8.0 * math.pi
                pts.append(P(0.55 - (1 - math.cos(a)) * 0.85 * k, off + math.sin(a) * (0.55 + 0.25 * (j / 8.0)) * k
                             + math.sin(t * 3 + j) * 0.04))
            tail = []
            for j in range(5):
                tail.append(P(-1.15 * k - j * 0.05 + math.sin(t * 2.6 + j) * 0.06, off + (0.62 - j * 0.31) * k))
            pts += tail
            for j in range(7, 0, -1):
                a = j / 8.0 * math.pi
                pts.append(P(0.55 - (1 - math.cos(a)) * 0.85 * k, off - math.sin(a) * (0.55 + 0.25 * (j / 8.0)) * k
                             + math.sin(t * 3 + j) * 0.04))
            return pts

        # ---- serap yansımaları ----
        for sgn, c_ in ((-1, (120, 220, 255)), (1, (255, 140, 200))):
            off = (0.85 + 0.22 * math.sin(t * 2.3 + sgn)) * sgn
            poly_alpha(surf, gown(off, 0.9), c_, 70)
        # ---- uçuşan tüller ----
        for i, c_ in enumerate(((246, 150, 120), (255, 206, 120))):
            s0 = (i - 0.5) * 0.7
            pts = [P(0.0, s0)]
            for k in range(1, 7):
                pts.append(P(-k * 0.28, s0 * (1 + k * 0.25) + math.sin(t * 3 + k * 0.8 + i) * 0.12))
            pygame.draw.lines(surf, c_, False, pts, max(3, int(r * 0.10)))
        # ---- elbise ----
        g = gown(0.0)
        self._poly(surf, g, silk, x, y, grow=0.05)
        poly_alpha(surf, g[:9] + [P(-0.4, 0.0)], WHITE, 50)
        pygame.draw.polygon(surf, gold, g, 2)
        pygame.draw.line(surf, gold, P(0.05, 0.55), P(0.05, -0.55), max(3, int(r * 0.08)))
        for k in range(5):
            c0 = P(0.05, -0.44 + k * 0.22)
            pygame.draw.circle(surf, (60, 200, 200) if k % 2 else (220, 50, 60), (int(c0[0]), int(c0[1])),
                               max(2, int(r * 0.05)))
        for sgn in (-1, 1):
            a0, a1 = P(0.25, 0.42 * sgn), P(0.78, 0.66 * sgn)
            self._limb(surf, [a0, a1], (214, 164, 120), max(4, int(r * 0.12)))
            pygame.draw.circle(surf, gold, [int(v) for v in P(0.60, 0.58 * sgn)], max(3, int(r * 0.08)), 2)
            pygame.draw.circle(surf, (250, 214, 140), [int(v) for v in a1], max(3, int(r * 0.09)))
        # ---- kum küreleri ----
        for i in range(3):
            a = t * 1.4 + i * math.tau / 3
            ox, oy = x + math.cos(a) * r * 1.50, y + math.sin(a) * r * 1.05
            for k in range(1, 6):
                aa = a - k * 0.12
                blit_disc(surf, x + math.cos(aa) * r * 1.50, y + math.sin(aa) * r * 1.05, r * 0.10 * (1 - k / 6),
                          (240, 210, 150), 180 - k * 30)
            add_glow(surf, ox, oy, r * 0.35, (255, 200, 110), 0.40)
            pygame.draw.circle(surf, OUTLINE, (int(ox), int(oy)), int(r * 0.17))
            pygame.draw.circle(surf, (250, 214, 140), (int(ox), int(oy)), int(r * 0.14))
        # ---- baş, peçe, taç ----
        hc = P(0.48, 0.0)
        pygame.draw.circle(surf, OUTLINE, (int(hc[0]), int(hc[1])), int(r * 0.33))
        pygame.draw.circle(surf, (60, 34, 30), (int(hc[0]), int(hc[1])), int(r * 0.29))
        face = [P(0.76, 0.18), P(0.76, -0.18), P(0.52, -0.22), P(0.52, 0.22)]
        pygame.draw.polygon(surf, (214, 164, 120), face)
        veil = [P(0.80, 0.22), P(0.96, 0.0), P(0.80, -0.22), P(0.68, -0.20), P(0.68, 0.20)]
        poly_alpha(surf, veil, (255, 222, 205), 190)
        pygame.draw.line(surf, gold, P(0.58, -0.28), P(0.58, 0.28), 3)
        gc = P(0.70, 0.0)
        add_glow(surf, gc[0], gc[1], r * 0.20, (120, 230, 255), 0.55)
        pygame.draw.circle(surf, (110, 220, 255), (int(gc[0]), int(gc[1])), max(2, int(r * 0.055)))
        self._boss_eyes(surf, P, r, t, n=2, spread=0.09, fwd=0.66, sz=0.05,
                        col=(255, 245, 230), glow=(255, 150, 60))

    def _art_desert_sphinx(self, surf, x, y, r, col, t):
        """sfenks: aslan gövdesi, dört pençe, püsküllü kuyruk, katlanmış küçük taş kanatlar"""
        P, fx_, fy_, sx_, sy_ = self._mapper(x, y, r)
        stone = col
        dark = scale_col(col, 0.60)
        lite = lighten(col, 0.25)
        g = self.gait
        sw = math.sin(t * 2.0) * 0.4
        tail = _qbez(P(-0.95, 0.0), P(-1.35, 0.6 + sw), P(-1.20, 1.05 + sw * 0.5), 8)
        pygame.draw.lines(surf, OUTLINE, False, tail, max(5, int(r * 0.12)))
        pygame.draw.lines(surf, stone, False, tail, max(3, int(r * 0.07)))
        pygame.draw.circle(surf, OUTLINE, [int(v) for v in tail[-1]], int(r * 0.13))
        pygame.draw.circle(surf, (150, 100, 60), [int(v) for v in tail[-1]], int(r * 0.10))
        for (rf, sgn, ph, big) in ((0.50, 1, 0.0, 1), (0.50, -1, math.pi, 1),
                                   (-0.65, 1, math.pi, 0), (-0.65, -1, 0.0, 0)):
            o = math.sin(g + ph) * 0.16
            root, paw = P(rf, 0.42 * sgn), P(rf + 0.30 + o, 0.66 * sgn)
            self._limb(surf, [root, paw], dark, max(7, int(r * 0.24)))
            pr_ = r * (0.20 if big else 0.18)
            pygame.draw.circle(surf, OUTLINE, (int(paw[0]), int(paw[1])), int(pr_ + 2))
            pygame.draw.circle(surf, stone, (int(paw[0]), int(paw[1])), int(pr_))
            for k in (-1, 0, 1):
                tx_ = paw[0] + (fx_ * 0.18 + sx_ * 0.08 * k) * r
                ty_ = paw[1] + (fy_ * 0.18 + sy_ * 0.08 * k) * r
                pygame.draw.circle(surf, lite, (int(tx_), int(ty_)), max(1, int(r * 0.04)))
        body = []
        for j in range(16):
            a = j * math.tau / 16
            body.append(P(math.cos(a) * 0.95 - 0.20, math.sin(a) * 0.58))
        self._poly(surf, body, stone, x, y, grow=0.06)
        poly_alpha(surf, body[12:] + body[:3] + [P(-0.2, 0.0)], WHITE, 40)
        for sgn in (-1, 1):                         # küçük katlı kanatlar
            wing = [P(0.05, 0.18 * sgn), P(-0.20, 0.46 * sgn), P(-0.80, 0.40 * sgn), P(-0.58, 0.10 * sgn)]
            self._poly(surf, wing, lite, x, y, grow=0.04)
            for k in range(3):
                pygame.draw.line(surf, dark, P(-0.10 - k * 0.20, 0.22 * sgn), P(-0.26 - k * 0.20, 0.42 * sgn), 2)
        pygame.draw.lines(surf, dark, False, [P(0.25, 0.04), P(-0.10, 0.12), P(-0.45, -0.04), P(-0.95, 0.04)], 2)
        self._nemes_head(surf, P, x, y, r, 0.70, 0.34, stone, t, glow=(255, 180, 60))

    def _art_desert_mummy(self, surf, x, y, r, col, t):
        """Mumya orakçısı: geniş omuzlu sargılı gövde, savrulan sargı uçları, öne uzanmış kollar"""
        P, fx_, fy_, sx_, sy_ = self._mapper(x, y, r)
        wrap = col
        dark = scale_col(col, 0.60)
        rot = (150, 230, 120)
        add_glow(surf, x, y, r * 1.9, rot, 0.14 + 0.05 * math.sin(t * 2))
        # ---- savrulan sargı uçları ----
        for i in range(5):
            s0 = (i - 2) * 0.34
            pts = [P(-0.55, s0)]
            for k in range(1, 6):
                pts.append(P(-0.55 - k * 0.24, s0 + math.sin(t * 3.2 + i * 1.3 + k * 0.7) * 0.11 * k / 2))
            pygame.draw.lines(surf, OUTLINE, False, pts, max(6, int(r * 0.15)))
            pygame.draw.lines(surf, wrap if i % 2 else lighten(wrap, 0.1), False, pts, max(4, int(r * 0.10)))
        # ---- bok böcekleri ----
        for i in range(4):
            a = t * 1.2 + i * math.tau / 4
            bx, by = x + math.cos(a) * r * 1.60, y + math.sin(a) * r * 1.15
            ang = a + math.pi / 2
            ca, sa = math.cos(ang), math.sin(ang)
            for k in (-1, 1):
                pygame.draw.line(surf, (20, 30, 30), (bx + sa * k * r * 0.13, by - ca * k * r * 0.13),
                                 (bx - sa * k * r * 0.13, by + ca * k * r * 0.13), 2)
            pygame.draw.circle(surf, OUTLINE, (int(bx), int(by)), max(3, int(r * 0.11)))
            pygame.draw.circle(surf, (40, 130, 120), (int(bx), int(by)), max(2, int(r * 0.085)))
            pygame.draw.line(surf, (20, 60, 60), (bx - ca * r * 0.08, by - sa * r * 0.08),
                             (bx + ca * r * 0.08, by + sa * r * 0.08), 1)
        # ---- gövde: geniş omuzlu insan gövdesi ----
        body = [P(0.50, 0.42), P(0.26, 0.86), P(-0.46, 0.82), P(-0.74, 0.40),
                P(-0.74, -0.40), P(-0.46, -0.82), P(0.26, -0.86), P(0.50, -0.42)]
        self._poly(surf, body, wrap, x, y, grow=0.09)
        for k in range(8):                       # çapraz sargı bantları
            f_ = 0.42 - k * 0.15
            pygame.draw.line(surf, dark, P(f_ + 0.10, -0.80 + abs(f_) * 0.3), P(f_ - 0.10, 0.80 - abs(f_) * 0.3), 2)
        pygame.draw.line(surf, lighten(wrap, 0.2), P(0.30, -0.60), P(-0.50, 0.50), 3)
        # ---- öne uzanmış kollar ----
        for sgn in (-1, 1):
            sw = math.sin(self.gait + (0 if sgn > 0 else math.pi)) * 0.06
            a0, a1 = P(0.22, 0.64 * sgn), P(1.00 + sw, 0.48 * sgn)
            self._limb(surf, [a0, a1], wrap, max(7, int(r * 0.22)))
            for k in range(4):
                c0 = (a0[0] + (a1[0] - a0[0]) * (k + 0.5) / 4, a0[1] + (a1[1] - a0[1]) * (k + 0.5) / 4)
                pygame.draw.line(surf, dark, (c0[0] - sx_ * r * 0.10, c0[1] - sy_ * r * 0.10),
                                 (c0[0] + sx_ * r * 0.10 + fx_ * r * 0.05, c0[1] + sy_ * r * 0.10 + fy_ * r * 0.05), 2)
        # ---- khopesh (sağ el) ----
        hp = P(1.02, 0.48)
        blade = _qbez(hp, P(1.62, 0.62), P(1.52, 1.10), 8)
        back = _qbez(P(1.48, 1.06), P(1.44, 0.68), P(1.08, 0.54), 6)
        add_glow(surf, *P(1.40, 0.75), r * 0.45, (255, 190, 90), 0.28)
        self._poly(surf, blade + back, (206, 148, 70), hp[0], hp[1], grow=0.05)
        pygame.draw.lines(surf, (255, 224, 150), False, blade, 2)
        # ---- baş ----
        hc = P(0.50, 0.0)
        pygame.draw.circle(surf, OUTLINE, (int(hc[0]), int(hc[1])), int(r * 0.38))
        pygame.draw.circle(surf, lighten(wrap, 0.10), (int(hc[0]), int(hc[1])), int(r * 0.34))
        for k in range(5):
            pygame.draw.line(surf, dark, P(0.24 + k * 0.10, -0.30), P(0.30 + k * 0.10, 0.30), 2)
        gap = [P(0.74, 0.22), P(0.82, 0.0), P(0.74, -0.22), P(0.66, -0.20), P(0.66, 0.20)]
        pygame.draw.polygon(surf, (24, 18, 12), gap)
        ex, ey = P(0.75, 0.09)
        add_glow(surf, ex, ey, r * 0.32, rot, 0.65 + 0.2 * math.sin(t * 6))
        pygame.draw.circle(surf, (190, 255, 170), (int(ex), int(ey)), max(2, int(r * 0.075)))
        # sarkan tek sargı (yüzden)
        pts = [P(0.70, -0.24)] + [P(0.70 - k * 0.10, -0.30 - k * 0.08 + math.sin(t * 4 + k) * 0.04) for k in range(1, 5)]
        pygame.draw.lines(surf, wrap, False, pts, max(3, int(r * 0.07)))

    def _art_desert_scorpion(self, surf, x, y, r, col, t):
        """Akrep ana: sekiz bacak, iki dev kıskaç, halka halka zırh plakaları"""
        P, fx_, fy_, sx_, sy_ = self._mapper(x, y, r)
        shell = col
        dark = scale_col(col, 0.55)
        lite = lighten(col, 0.30)
        # ---- bacaklar ----
        for sgn in (-1, 1):
            for i in range(4):
                ph = self.gait * 1.3 + i * 1.1 + (0 if sgn > 0 else math.pi)
                sw = math.sin(ph) * 0.10
                rf = 0.20 - i * 0.24
                self._seg_leg(surf, P, (rf, 0.36 * sgn), (rf + 0.10 + sw, 0.95 * sgn),
                              (rf - 0.08 + sw * 1.6, 1.30 * sgn), dark, max(3, int(r * 0.10)))
        # ---- kıskaçlar ----
        snap = 0.5 + 0.5 * math.sin(t * 3.0)
        for sgn in (-1, 1):
            a0, a1 = P(0.40, 0.42 * sgn), P(0.90, 0.72 * sgn)
            self._limb(surf, [a0, a1], shell, max(6, int(r * 0.20)))
            cc = P(1.15, 0.72 * sgn)
            pygame.draw.circle(surf, OUTLINE, (int(cc[0]), int(cc[1])), int(r * 0.30))
            pygame.draw.circle(surf, shell, (int(cc[0]), int(cc[1])), int(r * 0.26))
            j1 = [P(1.25, 0.60 * sgn), P(1.72, (0.62 - 0.12 * snap) * sgn), P(1.30, 0.78 * sgn)]
            j2 = [P(1.25, 0.84 * sgn), P(1.66, (0.86 + 0.12 * snap) * sgn), P(1.30, 0.72 * sgn)]
            for j in (j1, j2):
                self._poly(surf, j, lite, x, y, grow=0.03)
        # ---- zırh plakaları ----
        ceph = [P(0.66, 0.0), P(0.50, 0.42), P(0.0, 0.50), P(-0.10, 0.0), P(0.0, -0.50), P(0.50, -0.42)]
        self._poly(surf, ceph, shell, x, y, grow=0.08)
        for k in range(5):
            f0 = -0.10 - k * 0.20
            w_ = 0.50 - k * 0.07
            seg = [P(f0 + 0.06, w_), P(f0 - 0.16, w_ - 0.02), P(f0 - 0.16, -w_ + 0.02), P(f0 + 0.06, -w_)]
            self._poly(surf, seg, shell if k % 2 == 0 else lite, x, y, grow=0.03)
            pygame.draw.line(surf, dark, P(f0 - 0.16, w_ - 0.02), P(f0 - 0.16, -w_ + 0.02), 2)
        pygame.draw.line(surf, dark, P(0.55, 0.0), P(-1.0, 0.0), 2)
        # ---- kuyruk (gövdenin üstüne kıvrılır) ----
        sway = math.sin(t * 2.4) * 0.10
        segs = [P(-1.08, 0.0), P(-1.30, 0.16 + sway), P(-1.32, 0.42 + sway), P(-1.08, 0.58 + sway),
                P(-0.72, 0.52 + sway * 0.6), P(-0.38, 0.32 + sway * 0.3)]
        for i, c0 in enumerate(segs):
            rr = r * (0.24 - i * 0.022)
            pygame.draw.circle(surf, OUTLINE, (int(c0[0]), int(c0[1])), int(rr + 2))
            pygame.draw.circle(surf, shell if i % 2 == 0 else lite, (int(c0[0]), int(c0[1])), int(rr))
        bulb = P(-0.20, 0.22 + sway * 0.2)
        add_glow(surf, bulb[0], bulb[1], r * 0.40, (255, 120, 60), 0.45 + 0.2 * math.sin(t * 6))
        pygame.draw.circle(surf, OUTLINE, (int(bulb[0]), int(bulb[1])), int(r * 0.17))
        pygame.draw.circle(surf, (255, 150, 70), (int(bulb[0]), int(bulb[1])), int(r * 0.13))
        sting = [bulb, P(0.10, 0.10 + sway * 0.1), P(-0.12, 0.16 + sway * 0.2)]
        self._poly(surf, sting, (40, 20, 16), x, y, grow=0.02)
        # gözler
        for (ff, ss) in ((0.52, 0.10), (0.52, -0.10), (0.42, 0.24), (0.42, -0.24)):
            ex, ey = P(ff, ss)
            add_glow(surf, ex, ey, r * 0.12, (255, 80, 40), 0.4)
            pygame.draw.circle(surf, (255, 200, 120), (int(ex), int(ey)), max(2, int(r * 0.045)))

    # cehennem süsleri (arena gövdesinin üstüne)
    HELL_HEAD = {"warlord": (0.46, 0.36), "witch": (0.14, 0.46), "colossus": (0.80, 0.32),
                 "reaper": (0.30, 0.42), "hive": (0.94, 0.38), "dragon": (1.25, 0.28)}

    def _horn(self, surf, pts, w0, col, tip_col):
        """Uca doğru incelen boynuz (orta çizgi + taban kalınlığı)."""
        left, right = [], []
        n = len(pts)
        for i, (px_, py_) in enumerate(pts):
            a = pts[min(i + 1, n - 1)]
            b = pts[max(i - 1, 0)]
            dx, dy = a[0] - b[0], a[1] - b[1]
            ln = math.hypot(dx, dy) or 1.0
            nx, ny = -dy / ln, dx / ln
            w = w0 * (1.0 - i / (n - 1)) + 0.6
            left.append((px_ + nx * w, py_ + ny * w))
            right.append((px_ - nx * w, py_ - ny * w))
        poly = left + list(reversed(right))
        pygame.draw.polygon(surf, OUTLINE, poly, 4)
        pygame.draw.polygon(surf, col, poly)
        k = max(2, n // 2)
        tip = left[k:] + list(reversed(right[k:]))
        if len(tip) >= 3:
            pygame.draw.polygon(surf, tip_col, tip)

    def _draw_hell_back(self, surf, x, y, r, t):
        """Gövdenin arkasına: geniş yarasa kanatları (lord/cadı/orakçı/kolos) ya da sırttan fışkıran obsidyen dikenler (kovan/ejderha)."""
        P, fx_, fy_, sx_, sy_ = self._mapper(x, y, r)
        if self.kind in ("warlord", "witch", "reaper", "colossus"):
            flap = math.sin(t * 3.0) * 0.16
            span = 1.0 if self.kind != "colossus" else 0.85
            for sgn in (-1, 1):
                root = P(-0.10, 0.45 * sgn)
                ribs = [(0.25, 1.55), (-0.35, 2.15), (-0.95, 2.00), (-1.30, 1.35)]
                tips = [P(ff + flap * 0.4, (ss * span + flap * (2 - k * 0.4)) * sgn)
                        for k, (ff, ss) in enumerate(ribs)]
                pts = [root, tips[0]]
                for k in range(1, len(tips)):
                    a, b = tips[k - 1], tips[k]
                    mid = ((a[0] + b[0]) / 2, (a[1] + b[1]) / 2)
                    pts.append((mid[0] + (x - mid[0]) * 0.16, mid[1] + (y - mid[1]) * 0.16))
                    pts.append(b)
                pts.append(P(-0.85, 0.55 * sgn))
                self._poly(surf, pts, (112, 20, 18), x, y, grow=0.0)
                pygame.draw.polygon(surf, OUTLINE, pts, 3)
                poly_alpha(surf, pts, (255, 110, 40), 34 + int(20 * math.sin(t * 4)))
                for tp in tips:
                    pygame.draw.line(surf, OUTLINE, root, tp, 5)
                    pygame.draw.line(surf, (60, 16, 14), root, tp, 3)
                    pygame.draw.circle(surf, (240, 200, 170), (int(tp[0]), int(tp[1])), 3)
        else:
            for i in range(7):
                a = math.atan2(-fy_, -fx_) + (i - 3) * 0.40
                ca, sa = math.cos(a), math.sin(a)
                b0 = (x + (ca * 0.55 - sa * 0.12) * r, y + (sa * 0.55 + ca * 0.12) * r)
                b1 = (x + (ca * 0.55 + sa * 0.12) * r, y + (sa * 0.55 - ca * 0.12) * r)
                ln = 1.45 + 0.18 * (i % 2)
                tip = (x + ca * r * ln, y + sa * r * ln)
                self._crystal(surf, b0, b1, tip, (46, 20, 22), (255, 150, 70))
                add_glow(surf, tip[0], tip[1], r * 0.12, (255, 120, 40), 0.4)

    def _draw_hell_front(self, surf, x, y, r, t):
        """Gövdenin üstüne: kızgın lav damarları, kıvrık şeytan boynuzları, başın üstünde yanan alev tacı."""
        P, fx_, fy_, sx_, sy_ = self._mapper(x, y, r)
        hf, hr = self.HELL_HEAD.get(self.kind, (0.4, 0.36))
        pulse = 0.6 + 0.4 * math.sin(t * 4.0)
        lava = (255, int(150 + 70 * pulse), 60)
        for i in range(4):                                    # lav damarları
            a = i * math.tau / 4 + 0.8
            p0 = P(-0.12 + math.cos(a) * 0.10, math.sin(a) * 0.10)
            p1 = P(-0.12 + math.cos(a + 0.25) * 0.40, math.sin(a + 0.25) * 0.40)
            p2 = P(-0.12 + math.cos(a - 0.15) * 0.62, math.sin(a - 0.15) * 0.62)
            pygame.draw.lines(surf, lava, False, [p0, p1, p2], 2)
        add_glow(surf, *P(-0.12, 0.0), r * 0.6, (255, 110, 40), 0.16 + 0.1 * pulse)
        for sgn in (-1, 1):                                   # boynuzlar (öne kıvrık)
            pts = [P(hf - 0.02, hr * 0.75 * sgn), P(hf + 0.02, (hr + 0.30) * sgn),
                   P(hf + 0.24, (hr + 0.52) * sgn), P(hf + 0.52, (hr + 0.52) * sgn),
                   P(hf + 0.70, (hr + 0.36) * sgn)]
            self._horn(surf, pts, r * 0.13, (70, 40, 36), (236, 214, 190))
            add_glow(surf, pts[-1][0], pts[-1][1], r * 0.16, (255, 120, 40), 0.45)
        hc = P(hf, 0.0)
        for i in range(7):                                    # alev tacı
            a = math.atan2(fy_, fx_) + (i - 3) * 0.42
            ph = (t * 2.2 + i * 0.21) % 1.0
            rr = r * (hr * 0.85 + 0.05 + 0.22 * ph)
            fxp = hc[0] + math.cos(a) * rr
            fyp = hc[1] + math.sin(a) * rr - r * 0.30 * ph
            blit_disc(surf, fxp, fyp, r * (0.10 * (1 - ph) + 0.03),
                      (255, int(210 - 130 * ph), 70), int(240 * (1 - ph)))

class Boss(MapBossArt):
    def __init__(self, kind, x, y, hp_mult, diff_mult=1.0, wave=10, hellish=False, theme=None,
                 champion=1):
        d = BOSS_DEFS[kind]
        self.kind = kind
        # cehennem patronu: davranışı arena patronuyla aynı (dengesi oturmuş),
        # kimliği bambaşka - yeni ad, yeni renk, alev görselliği ve daha yüksek
        # güç dizini (arenanın son patronundan zayıf olamaz).
        self.hellish = bool(hellish)
        self.name = HELL_BOSS_NAMES.get(kind, d["name"]) if hellish else d["name"]
        self.x, self.y = x, y
        self.wave = wave
        self.hit_floor = boss_hit_floor(wave, self.hellish)
        self.wound = boss_wound(wave, self.hellish)
        # Patronlar dalgaya göre üç eksende birden güçlenir: can, hasar ve
        # zırh.
        dmgm = (late_wave_dmg_mult(hell_dmg_wave(wave), LATE_DMG_COEF_HELL) if hellish
                else late_wave_dmg_mult(wave))
        self.boss_index = hell_boss_index(wave) if hellish else boss_index_for_wave(wave)
        pw_hp, pw_dmg, pw_armor = boss_power(wave, index=self.boss_index)
        self.armor = pw_armor
        self.max_hp = d["hp"] * hp_mult * diff_mult * pw_hp * BOSS_HP_NERF * BOSS_HP_BONUS
        self.hp = self.max_hp
        self.speed = d["speed"]
        self.dmg = d["dmg"] * diff_mult * pw_dmg * (0.55 + 0.45 * dmgm) * BOSS_DMG_NERF
        self.radius = d["radius"]
        self.hit_r = self.radius * 0.92
        self.color = HELL_BOSS_COLORS.get(kind, d["color"]) if hellish else d["color"]
        # harita patronu: davranışı, canı, hasarı ve yetenekleri arena
        # patronuyla aynı; adı, rengi ve haritaya özgü süsü farklı.
        self.theme = theme if (theme in MAP_BOSS_NAMES and not hellish) else None
        if self.theme:
            self.name = map_boss_name(self.theme, kind, self.name)
            self.color = MAP_BOSS_COLORS[self.theme].get(kind, self.color)
        # yetenek takımı haritaya / cehenneme göre
        self.skills = boss_skill_set(kind, self.theme, self.hellish)
        self.element = MAP_BOSS_ELEMENT.get(self.theme) if self.theme else None
        # şampiyon: eski 2-3 patronun yerine gelen tek güçlü patron
        self.champion = max(1, int(champion))
        if self.champion > 1:
            self.name = "★ " + self.name
            self.dmg *= 1.0 + CHAMPION_DMG_PER * (self.champion - 1)
            self.radius = int(self.radius * CHAMPION_SIZE)
            self.hit_r = self.radius * 0.92
        self.alive = True
        self.spawn_t = 0.0
        self.hit_flash = 0.0
        self.phase = 1
        self.atk_timer = 1.4
        self.telegraph = None  # ("kind", x, y, r, timer, total)
        self.wobble = 0.0
        self.touch_cd = 0.0
        self.enraged = False
        self.desperate = False  # 3. faz: çok düşük canda kaçıp yaratık çağırır
        self.is_boss = True
        # Zorlaştıkça ödül de büyür - geç dalgadaki patronu yenmek gerçekten
        # değsin.
        self.score = int(800 * (1.0 + (self.boss_index - 1) * 0.45)) * self.champion
        self.coin = int(260 * (1.0 + (self.boss_index - 1) * 0.35)) * self.champion
        self.xp = int(220 * (1.0 + (self.boss_index - 1) * 0.30)) * self.champion
        # Yaratık çağırma / kaçış mekaniği
        self.summon_cd = random.uniform(5.0, 7.0)
        self.flee_timer = 0.0
        self.summoned_enemies = []
        self.teleport_cd = random.uniform(4.0, 6.0)   # yalnızca "reaper" kullanır
        # ---- imza özelliği ----
        # Her patron farklı vurur: kimi yakar, kimi zehirler, kimi yavaşlatır,
        # kimi görünmez olur, kimi dibine ışınlanır.
        self.trait = boss_trait(kind, hellish)
        self.vanish_t = 0.0                            # görünmezlik kalan süresi
        self.vanish_cd = random.uniform(5.5, 8.0)      # bir sonraki görünmezliğe kalan
        self.fly_t = 0.0                               # ejderha: havada geçen süre
        self.fly_dir = (0.0, 0.0)
        self.fly_cd = random.uniform(6.0, 9.0)
        self.trail_acc = 0.0                           # alev/iz bırakma sayacı
        # ---- ek yetenekler ----
        self.skill_cd = random.uniform(3.5, 6.0)       # bir sonraki yeteneğe kalan
        self.last_skill = ""                           # üst üste aynısı gelmesin
        self.pull_t = 0.0                              # çekim kalan süresi
        self.buff_t = 0.0                              # savaş çığlığı kalan süresi
        self.hunt_t = 0.0                              # avlanma kalan süresi
        self.hunt_check = 0.0                          # kaç saniyedir uzakta
        # dönme (strafe): istenen mesafedeyken patron yerinde çakılı kalmasın
        # diye oyuncunun çevresinde dolanır. Yön belli aralıklarla değişir.
        self.strafe_dir = random.choice((-1, 1))
        self.strafe_t = random.uniform(1.4, 2.6)
        # Çizim için: patronun baktığı yön (yumuşatılmış) ve yürüyüş fazı.
        self.face_x, self.face_y = 0.0, 1.0
        self.gait = random.uniform(0, math.tau)
        # ---- yaylım ateş ----
        self.volley_cd = random.uniform(2.2, 3.4)
        # ---- hücum (yalnızca kolos) ----
        self.charge_t = 0.0
        self.charge_dir = (0.0, 0.0)
        # Her patron farklı mesafede savaşır: kolos üstüne gelir, cadı uzak
        # durur.
        self.want_dist = {"warlord": 190, "witch": 215, "colossus": 110,
                          "reaper": 160, "hive": 205, "dragon": 245}.get(kind, 190)
        # Zehir patronlarda da işler (süresi yoktur, ölene kadar sürer).
        self.poison_dps = 0.0
        self.poison_tick_acc = 0.0
        # ---- can çalma ----
        # Patron da verdiği hasarın bir kısmını canına ekliyor; dövüş gerçek
        # bir düelloya dönüşüyor.
        self.lifesteal = clamp(0.20 + 0.05 * (self.boss_index - 1), 0.0, 0.45)
        self.heal_budget = 0.0         # saniyede yenilenen can çalma bütçesi
        self.heal_rate = None          # saniyelik can çalma tavanı (spawn'da ayarlanır)
        self.intake_budget = None      # hasar tavanı havuzu (ilk vuruşta kurulur)
        self.heal_flash = 0.0
        self.healed_total = 0.0
        self.fight_time = 0.0          # dövüşün başından beri geçen süre
        # ---- güç yetenekleri ----
        self.aegis_hp = 0.0
        self.aegis_max = 0.0
        self.aegis_t = 0.0
        self.spiral_t = 0.0
        self.spiral_delay = 0.0
        self.spiral_acc = 0.0
        self.spiral_ang = 0.0
        self.power_phase = 0           # 1: öfke bariyeri, 2: çaresizlik sarmalı
        # ---- yeni yetenekler ----
        self.veil_t = 0.0              # görünmezlik kalan süresi
        self.ward_t = 0.0              # dokunulmazlık kalan süresi
        self.ward_pop = 0.0            # "BAĞIŞIK" yazısının sıklık sayacı
        self.drain_t = 0.0             # can emme bağı kalan süresi
        self.drain_acc = 0.0
        self.drain_px = self.drain_py = 0.0
        self.nova_n = 0                # kalan patlama halkası sayısı
        self.nova_cd = 0.0
        self.nova_ang = 0.0
        self.snares = []               # [x, y, kalan_süre] kök tuzakları
        self.blink_fx = None           # (x, y, süre) ışınlanma izi

    # ---- imza özelliği ----
    # Süreli etkilerin (yanık / zehir) saniyelik hasar tavanı, oyuncunun azami
    # canının oranı olarak konur.
    BURN_CAP_FRAC = 0.050      # azami canın %5'i / saniye
    POISON_CAP_FRAC = 0.035    # azami canın %3.5'i / saniye

    def _dot_dps(self, player, want, frac):
        """Süreli etkinin saniyelik hasarı - oyuncunun canına göre tavanlanır."""
        return min(want, max(2.0, player.max_hp * frac))

    def _area_dmg_k(self):
        """Alan yeteneklerinin hasar katsayısı (geç patronlarda kısılır)."""
        return max(0.45, 1.0 - (self.boss_index - 1) * 0.07)

    def afflict(self, player, k=1.0):
        """Patronun imza etkisini oyuncuya uygular."""
        if player is None or not player.alive:
            return
        tk = self.trait["kind"]
        base = max(1.0, self.dmg)
        BC, PC = self.BURN_CAP_FRAC, self.POISON_CAP_FRAC
        if tk in ("burn", "inferno"):
            want = base * (0.34 if tk == "inferno" else 0.28) * k
            player.apply_burn(self._dot_dps(player, want, BC), 3.2, self.name)
        elif tk == "venom":
            player.apply_poison(self._dot_dps(player, base * 0.22 * k, PC), 5.5, self.name)
        elif tk == "chill":
            player.apply_slow(0.58, 1.8)
        elif tk == "vanish":
            player.apply_slow(0.74, 1.4)
            player.apply_poison(self._dot_dps(player, base * 0.10 * k, PC * 0.5),
                                3.0, self.name)
        elif tk == "blink":
            player.apply_poison(self._dot_dps(player, base * 0.16 * k, PC * 0.7),
                                4.0, self.name)
        # harita elementi: buz yavaşlatır, zehir sızar, ateş yakar.
        el = getattr(self, "element", None)
        if el == "chill" and tk != "chill":
            player.apply_slow(0.78, 1.0)
        elif el == "venom" and tk != "venom":
            player.apply_poison(self._dot_dps(player, base * 0.10 * k, PC * 0.5), 3.5, self.name)
        elif el == "burn" and tk not in ("burn", "inferno"):
            player.apply_burn(self._dot_dps(player, base * 0.12 * k, BC * 0.5), 2.4, self.name)
        # cehennem patronları ayrıca yakar - cehennemde her darbe ateş taşır.
        if self.trait.get("hellfire") and tk not in ("burn", "inferno"):
            player.apply_burn(self._dot_dps(player, base * 0.15 * k, BC * 0.6),
                              2.4, self.name)

    def hit_player(self, player, amount, fx, src_x=None, src_y=None):
        """Oyuncuya hasar verir + imza etkisini uygular + can çalar."""
        if not player.alive:
            return 0.0
        # asgari darbe: çok canlı oyuncu da hissetsin
        fl = getattr(self, "hit_floor", 0.0)
        if fl > 0 and amount > 0 and self.dmg > 0:
            amount = max(amount, player.max_hp * fl * min(1.7, amount / self.dmg))
        dealt = player.take_damage(amount, fx,
                                   self.x if src_x is None else src_x,
                                   self.y if src_y is None else src_y, self.name)
        if dealt > 0:
            self.afflict(player)
            self.on_damage_dealt(amount)
        return dealt

    def is_hidden(self):
        """Gölge perdesi açıkken patron neredeyse görünmezdir."""
        return self.vanish_t > 0 or getattr(self, "veil_t", 0.0) > 0

    def _update_trait(self, dt, player, fx, projectiles, hazards):
        """İmza özelliğinin kare kare işleyişi (görünmezlik, uçuş, alev izi)."""
        tk = self.trait["kind"]

        # ---- gölge perdesi: kaybolur, sonra dibinde belirir ----
        if tk == "vanish" and self.spawn_t > 2.0:
            if self.vanish_t > 0:
                self.vanish_t -= dt
                # görünmezken hızla konum değiştirir
                dx, dy = norm_dir(self.x, self.y, player.x, player.y)
                self.x += dx * self.speed * 1.35 * dt
                self.y += dy * self.speed * 1.35 * dt
                if random.random() < dt * 6:
                    fx.spark(self.x + random.uniform(-20, 20), self.y + random.uniform(-20, 20),
                             self.color, 0, -30, 0.4, 3)
                if self.vanish_t <= 0:
                    fx.shockwave(self.x, self.y, 170, self.color, 0.4, 6)
                    fx.popup(self.x, self.y - self.radius - 28, "BELİRDİ!", self.color, 22, life=0.8)
                    sfx("warn", 0.7, 0.0)
                    self.atk_timer = 0.05      # belirir belirmez vurur
            else:
                self.vanish_cd -= dt
                if self.vanish_cd <= 0:
                    self.vanish_cd = random.uniform(7.0, 10.5) * (0.65 if self.enraged else 1.0)
                    self.vanish_t = 3.0 if self.enraged else 2.4
                    fx.ring(self.x, self.y, self.color, n=22, speed=210, life=0.45, r=3)
                    fx.popup(self.x, self.y - self.radius - 28, "GÖLGE PERDESİ!",
                             self.color, 20, life=0.9)
                    sfx("dash", 0.7, 0.0)

        # ---- ejderha: havalanıp oyuncunun üstüne dalar, ardında alev bırakır ----
        if tk == "inferno":
            if self.fly_t > 0:
                self.fly_t -= dt
                self.x += self.fly_dir[0] * self.speed * 3.6 * dt
                self.y += self.fly_dir[1] * self.speed * 3.6 * dt
                self.trail_acc += dt
                if self.trail_acc >= 0.19:
                    self.trail_acc = 0.0
                    hazards.append(Hazard(self.x, self.y, 52, 0.35, self.dmg * 0.48 * self._area_dmg_k(), owner=self))
                fx.spark(self.x + random.uniform(-30, 30), self.y + random.uniform(-30, 30),
                         (255, 170, 70), random.uniform(-40, 40), random.uniform(-40, 40), 0.4, 5)
                if self.fly_t <= 0:
                    # yere iniş: çevresine halka biçiminde alev saçar
                    fx.shockwave(self.x, self.y, 230, (255, 140, 60), 0.5, 8)
                    fx.shake(12, 0.35)
                    sfx("explosion", 0.8, 0.0)
                    for i in range(8):
                        a = i * math.tau / 8 + random.uniform(-0.2, 0.2)
                        hx = clamp(self.x + math.cos(a) * 130, ARENA_RECT.left + 20, ARENA_RECT.right - 20)
                        hy = clamp(self.y + math.sin(a) * 130, ARENA_RECT.top + 20, ARENA_RECT.bottom - 20)
                        hazards.append(Hazard(hx, hy, 58, 0.25 + i * 0.05, self.dmg * 0.62 * self._area_dmg_k(), owner=self))
            else:
                self.fly_cd -= dt
                if self.fly_cd <= 0 and self.spawn_t > 2.0:
                    self.fly_cd = random.uniform(8.0, 12.0) * (0.7 if self.enraged else 1.0)
                    px, py = self._lead_point(player, 0.5)
                    self.fly_dir = norm_dir(self.x, self.y, px, py)
                    self.fly_t = 0.85
                    self.trail_acc = 0.0
                    fx.popup(self.x, self.y - self.radius - 30, "EJDERHA DALIYOR!",
                             (255, 170, 80), 24, life=1.0)
                    fx.ring(self.x, self.y, (255, 160, 70), n=20, speed=240, life=0.45, r=4)
                    sfx("warn", 0.9, 0.0)

        # ---- ateşli çelik / ejder ateşi: yürüdüğü yerde kor bırakır ----
        if self.trait.get("hellfire") and self.fly_t <= 0 and self.spawn_t > 1.0:
            if random.random() < dt * 4.5:
                fx.spark(self.x + random.uniform(-self.radius, self.radius),
                         self.y + self.radius * 0.5,
                         (255, 170, 80), random.uniform(-14, 14), -40, 0.5, 4)

    # Aşağıdaki yetenekler bunun için var: mesafeyi kapatır, kaçış yolunu
    # keser, oyuncuyu kendine çeker ya da çevresini kapatır. yeni yetenek
    # eklemek: BOSS_SKILL_SETS'e adını yaz, _cast_skill içine bir dal ekle;
    # nişan alması gerekiyorsa _set_telegraph ile telgrafla ve _unleash ile
    # draw'daki telgraf çizimine birer dal ekle.

    def _skill_interval(self):
        """İki ek yetenek arasındaki süre."""
        base = max(3.0, 7.5 - (self.boss_index - 1) * 0.8)    # daha sık
        if self.desperate:
            base *= 0.55
        elif self.enraged:
            base *= 0.72
        if self.buff_t > 0:
            base *= 0.75
        return base * random.uniform(0.85, 1.15)

    def _escape_angle(self, player):
        """Oyuncunun kaçtığı yön."""
        vx, vy = getattr(player, "vx", 0.0), getattr(player, "vy", 0.0)
        if math.hypot(vx, vy) > 60:
            return math.atan2(vy, vx)
        return math.atan2(player.y - self.y, player.x - self.x)

    def _cast_skill(self, player, fx, projectiles, hazards):
        """Patronun yetenek listesinden birini seçip kullanır."""
        skills = getattr(self, "skills", None) or BOSS_SKILL_SETS.get(self.kind, ("lunge",))
        pool = [k for k in skills if k != self.last_skill] or list(skills)
        name = random.choice(pool)
        self.last_skill = name
        px, py = self._lead_point(player, 0.35)

        if name == "lunge":
            # atılış: telgraflanan yöne fırlar - mesafeyi bir anda kapatır.
            self._set_telegraph("lunge", px, py, 0, 0.55)
            fx.popup(self.x, self.y - self.radius - 30, "ATILIYOR!",
                     (255, 150, 90), 22, life=0.8)

        elif name == "wall":
            # alev/taş duvarı: oyuncunun kaçtığı yöne dik bir tuzak perdesi.
            esc = self._escape_angle(player)
            wx = clamp(player.x + math.cos(esc) * 190, ARENA_RECT.left + 30, ARENA_RECT.right - 30)
            wy = clamp(player.y + math.sin(esc) * 190, ARENA_RECT.top + 30, ARENA_RECT.bottom - 30)
            self._set_telegraph("wall", wx, wy, esc, 0.62)
            fx.popup(self.x, self.y - self.radius - 30, "YOLUNU KESİYOR!",
                     self.trait["color"], 20, life=0.9)

        elif name == "cage":
            # kafes: oyuncunun çevresine kapanan tuzak halkası (boşluğu var).
            self._set_telegraph("cage", px, py, self._ring_radius() * 0.82,
                                0.60 if self.enraged else 0.78)
            fx.ring(px, py, self.trait["color"], n=22, speed=170, life=0.5, r=3)

        elif name == "meteor":
            # kor yağmuru: oyuncunun çevresine gecikmeli olarak inen darbeler.
            self._set_telegraph("meteor", px, py, 0, 0.55)
            fx.popup(self.x, self.y - self.radius - 30, "KOR YAĞMURU!",
                     (255, 170, 80), 22, life=0.9)

        elif name == "pull":
            # çekim: oyuncuyu kendine doğru çeker - kaçış iptal olur.
            self._set_telegraph("pull", self.x, self.y, 0, 0.62)
            fx.popup(self.x, self.y - self.radius - 30, "ÇEKİYOR!",
                     (200, 130, 255), 22, life=0.9)

        elif name == "quake":
            # sarsıntı: patronun çevresinden yayılan halka halka taş darbeleri.
            fx.shockwave(self.x, self.y, 300, self.color, 0.55, 8)
            fx.shake(13, 0.4)
            fx.popup(self.x, self.y - self.radius - 30, "YER SARSILIYOR!",
                     (170, 200, 240), 22, life=1.0)
            for ring in range(3):
                n = 8 + ring * 3
                rad = 150 + ring * 115
                for i in range(n):
                    a = i * math.tau / n + ring * 0.24
                    hx = clamp(self.x + math.cos(a) * rad, ARENA_RECT.left + 20, ARENA_RECT.right - 20)
                    hy = clamp(self.y + math.sin(a) * rad, ARENA_RECT.top + 20, ARENA_RECT.bottom - 20)
                    hazards.append(Hazard(hx, hy, 56, 0.25 + ring * 0.30, self.dmg * 0.50 * self._area_dmg_k(),
                                          owner=self))
            if dist(self.x, self.y, player.x, player.y) < 520:
                player.apply_slow(0.62, 2.2)
            sfx("explosion", 0.7, 0.0)

        elif name == "warcry":
            # savaş çığlığı: kendini güçlendirir, çevresini iter ve tutuşturur.
            self.buff_t = 6.5
            fx.shockwave(self.x, self.y, 260, (255, 120, 60), 0.5, 7)
            fx.ring(self.x, self.y, (255, 180, 90), n=26, speed=300, life=0.55, r=4)
            fx.popup(self.x, self.y - self.radius - 30, "SAVAŞ ÇIĞLIĞI!",
                     (255, 180, 90), 26, life=1.2)
            fx.shake(10, 0.3)
            if dist(self.x, self.y, player.x, player.y) < 300:
                kx, ky = norm_dir(self.x, self.y, player.x, player.y)
                player.kbx += kx * 1500
                player.kby += ky * 1500
                player.apply_burn(self.dmg * 0.22, 3.0, self.name)
            sfx("boss", 0.8, 0.0)

        elif name == "harvest":
            # ruh biçimi: oyuncunun dibine ışınlanır ve geniş bir kesik atar.
            ang = random.uniform(0, math.tau)
            self.x = clamp(player.x + math.cos(ang) * 90,
                           ARENA_RECT.left + self.radius, ARENA_RECT.right - self.radius)
            self.y = clamp(player.y + math.sin(ang) * 90,
                           ARENA_RECT.top + self.radius, ARENA_RECT.bottom - self.radius)
            fx.ring(self.x, self.y, self.color, n=24, speed=260, life=0.4, r=3)
            hazards.append(Hazard(self.x, self.y, 165, 0.30, self.dmg * 1.00 * self._area_dmg_k(), owner=self))
            fx.popup(self.x, self.y - self.radius - 30, "RUH BİÇİMİ!",
                     self.color, 24, life=1.0)
            self.flee_timer = 0.0
            sfx("warn", 0.9, 0.0)

        elif name == "blink":
            # ışınlanma: duman olur, oyuncunun kaçtığı yönün önünde belirir ve
            # anında yelpaze ateşi açar.
            esc = self._escape_angle(player) + random.uniform(-0.6, 0.6)
            self.blink_fx = (self.x, self.y, 0.5)
            fx.burst(self.x, self.y, self.color, n=26, speed=220, life=0.45, r=4)
            rad = random.uniform(210, 280)
            self.x = clamp(player.x + math.cos(esc) * rad,
                           ARENA_RECT.left + self.radius, ARENA_RECT.right - self.radius)
            self.y = clamp(player.y + math.sin(esc) * rad,
                           ARENA_RECT.top + self.radius, ARENA_RECT.bottom - self.radius)
            fx.ring(self.x, self.y, lighten(self.color, 0.3), n=24, speed=260, life=0.4, r=3)
            fx.popup(self.x, self.y - self.radius - 30, "IŞINLANDI!", lighten(self.color, 0.3),
                     24, life=0.9)
            base = math.atan2(player.y - self.y, player.x - self.x)
            n = 5 if self.boss_index < 4 else 7
            for i in range(n):
                self._shoot(projectiles, base + (i - (n - 1) / 2) * 0.17, 330, 0.55, r=8)
            self.flee_timer = 0.0
            sfx("dash", 0.9, 0.0)

        elif name == "veil":
            # görünmezlik: 3 sn görünmez; belirince çevresi patlar.
            if self.trait["kind"] == "vanish":
                self.vanish_t = max(self.vanish_t, VEIL_TIME)
            else:
                self.veil_t = VEIL_TIME
            fx.ring(self.x, self.y, self.color, n=24, speed=220, life=0.45, r=3)
            fx.popup(self.x, self.y - self.radius - 30, "GÖRÜNMEZ OLDU!", (220, 200, 255),
                     22, life=1.0)
            sfx("dash", 0.7, 0.0)

        elif name == "ward":
            # dokunulmazlık: 3 sn hiçbir hasar işlemez.
            self.ward_t = WARD_TIME
            fx.ring(self.x, self.y, WARD_COLOR, n=30, speed=230, life=0.55, r=3.5)
            fx.shockwave(self.x, self.y, 180, WARD_COLOR, 0.45, 6)
            fx.popup(self.x, self.y - self.radius - 30, "DOKUNULMAZ! (3 sn)", WARD_COLOR,
                     24, life=1.2)
            sfx("guard", 0.9, 0.0)

        elif name == "drain":
            # can emme bağı: menzildeyse bağ atar, değilse çekim'e döner.
            if dist(self.x, self.y, player.x, player.y) <= DRAIN_RANGE * 0.92:
                self.drain_t = DRAIN_TIME + (0.6 if self.enraged else 0.0)
                self.drain_acc = 0.0
                self.drain_px, self.drain_py = player.x, player.y
                fx.popup(self.x, self.y - self.radius - 30, "CAN EMİYOR! UZAKLAŞ!",
                         DRAIN_COLOR, 22, life=1.1)
                sfx("warn", 0.8, 0.0)
            else:
                self._set_telegraph("pull", self.x, self.y, 0, 0.62)
                fx.popup(self.x, self.y - self.radius - 30, "ÇEKİYOR!",
                         (200, 130, 255), 22, life=0.9)

        elif name == "nova":
            # patlama halkaları: art arda 3 halka, aralarda boşluk.
            self.nova_n = 3 + (1 if self.desperate else 0)
            self.nova_cd = 0.35
            self.nova_ang = random.uniform(0, math.tau)
            fx.shockwave(self.x, self.y, 150, lighten(self.color, 0.3), 0.4, 5)
            fx.popup(self.x, self.y - self.radius - 30, "HALKA PATLAMASI!",
                     lighten(self.color, 0.35), 22, life=1.0)
            sfx("warn", 0.7, 0.0)

        elif name == "snare":
            # kök tuzağı: oyuncunun altına + kaçış yönüne iki tuzak.
            esc = self._escape_angle(player)
            spots = [(player.x, player.y),
                     (player.x + math.cos(esc) * 150, player.y + math.sin(esc) * 150)]
            if self.enraged:
                spots.append((player.x - math.cos(esc) * 150, player.y - math.sin(esc) * 150))
            for sx0, sy0 in spots:
                sx0 = clamp(sx0, ARENA_RECT.left + 30, ARENA_RECT.right - 30)
                sy0 = clamp(sy0, ARENA_RECT.top + 30, ARENA_RECT.bottom - 30)
                self.snares.append([sx0, sy0, SNARE_DELAY])
            fx.popup(self.x, self.y - self.radius - 30, "KÖK TUZAĞI!", (150, 220, 90),
                     22, life=1.0)
            sfx("warn", 0.7, 0.0)

        elif name == "aegis":
            self._start_aegis(fx)

        elif name == "spiral":
            self._start_spiral(fx)

        elif name == "mines":
            # kıyamet tarlası: oyuncunun çevresine ızgara hâlinde gecikmeli
            # patlamalar.
            safe = random.choice([(i, j) for i in (-1, 0, 1) for j in (-1, 0, 1)
                                  if (i, j) != (0, 0)])
            n = 3 if self.boss_index < 4 else 4
            for i in range(-n, n + 1):
                for j in range(-n, n + 1):
                    if (i, j) == safe or (abs(i) + abs(j) > 1 and random.random() < 0.30):
                        continue
                    if i * i + j * j > (n + 0.5) ** 2:
                        continue
                    hx = clamp(player.x + i * MINES_STEP, ARENA_RECT.left + 20, ARENA_RECT.right - 20)
                    hy = clamp(player.y + j * MINES_STEP, ARENA_RECT.top + 20, ARENA_RECT.bottom - 20)
                    delay = 1.05 + 0.10 * max(abs(i), abs(j))
                    hazards.append(Hazard(hx, hy, MINES_R, delay,
                                          self.dmg * 0.75 * self._area_dmg_k(), owner=self))
            fx.popup(self.x, self.y - self.radius - 30, "KIYAMET TARLASI!",
                     (255, 120, 90), 24, life=1.1)
            fx.shake(6, 0.25)
            sfx("warn", 0.9, 0.0)

        elif name == "swarm":
            # sürü: fazladan yaratık + hem kendi hem oyuncunun çevresine zehir.
            self._summon_minions(fx)
            for cx, cy in ((self.x, self.y), (player.x, player.y)):
                for i in range(5):
                    a = i * math.tau / 5 + random.uniform(-0.3, 0.3)
                    hx = clamp(cx + math.cos(a) * 110, ARENA_RECT.left + 20, ARENA_RECT.right - 20)
                    hy = clamp(cy + math.sin(a) * 110, ARENA_RECT.top + 20, ARENA_RECT.bottom - 20)
                    hazards.append(Hazard(hx, hy, 54, 0.30 + i * 0.10, self.dmg * 0.50 * self._area_dmg_k(),
                                          owner=self))
            fx.popup(self.x, self.y - self.radius - 30, "SÜRÜ GELİYOR!",
                     (200, 230, 100), 22, life=1.0)

    def _start_aegis(self, fx):
        """bariyer: canının bir payı kadar kalkan kurar."""
        self.aegis_max = self.max_hp * AEGIS_FRAC
        self.aegis_hp = self.aegis_max
        self.aegis_t = AEGIS_TIME
        fx.ring(self.x, self.y, AEGIS_COLOR, n=28, speed=240, life=0.6, r=3.5)
        fx.popup(self.x, self.y - self.radius - 30, "BARİYER! KIR ONU!",
                 AEGIS_COLOR, 24, life=1.2)
        sfx("guard", 0.8, 0.0)

    def _start_spiral(self, fx):
        """Ölüm sarmalı: kısa bir hazırlıktan sonra dönen mermi kolları."""
        self.spiral_delay = 0.65
        self.spiral_t = SPIRAL_TIME + (0.8 if self.desperate else 0.0)
        self.spiral_acc = 0.0
        self.spiral_ang = random.uniform(0, math.tau)
        fx.popup(self.x, self.y - self.radius - 30, "ÖLÜM SARMALI!",
                 (255, 110, 150), 24, life=1.1)
        fx.shockwave(self.x, self.y, 160, (255, 110, 150), 0.45, 5)
        sfx("warn", 0.8, 0.0)

    def _update_power(self, dt, player, fx, projectiles, hazards):
        """Güç yeteneklerinin kare kare işleyişi."""
        # Faz tetikleri: öfkede bariyer, çaresizlikte sarmal kendiliğinden
        # gelir.
        if self.enraged and self.power_phase == 0:
            self.power_phase = 1
            if "aegis" in getattr(self, "skills", ()):
                self._start_aegis(fx)
            else:
                self._start_spiral(fx)
        if self.desperate and self.power_phase == 1:
            self.power_phase = 2
            self._start_spiral(fx)
        # bariyer süresi doldu mu?
        if self.aegis_hp > 0:
            self.aegis_t -= dt
            if self.aegis_t <= 0:
                heal = self.aegis_hp * AEGIS_HEAL_K
                self.hp = min(self.max_hp, self.hp + heal)
                self.aegis_hp = 0.0
                if heal > 0.5:
                    self.heal_flash = 0.6
                    fx.popup(self.x, self.y - self.radius - 30, "BARİYER PATLADI! +%d" % int(heal),
                             AEGIS_COLOR, 22, life=1.1)
                n = 14 + 2 * min(5, self.boss_index)
                for i in range(n):
                    self._shoot(projectiles, i * math.tau / n, 300, 0.55, r=8, color=AEGIS_COLOR)
                fx.shockwave(self.x, self.y, 220, AEGIS_COLOR, 0.5, 6)
        # ölüm sarmalı
        if self.spiral_t > 0:
            if self.spiral_delay > 0:
                self.spiral_delay -= dt
                return
            self.spiral_t -= dt
            self.spiral_acc += dt
            arms = 4 if (self.enraged or self.desperate) else 3
            while self.spiral_acc >= SPIRAL_EVERY:
                self.spiral_acc -= SPIRAL_EVERY
                for i in range(arms):
                    self._shoot(projectiles, self.spiral_ang + i * math.tau / arms,
                                SPIRAL_SPEED, 0.42, r=7, color=(255, 110, 150))
                self.spiral_ang += 0.21 * (1 if self.strafe_dir > 0 else -1)

    def _update_new_skills(self, dt, player, fx, projectiles, hazards):
        """Yeteneklerinin kare kare işleyişi."""
        if self.blink_fx is not None:
            bx_, by_, bt_ = self.blink_fx
            bt_ -= dt
            self.blink_fx = (bx_, by_, bt_) if bt_ > 0 else None
        # ---- dokunulmazlık ----
        if self.ward_t > 0:
            self.ward_t -= dt
            if self.ward_pop > 0:
                self.ward_pop -= dt
            if self.ward_t <= 0:
                fx.ring(self.x, self.y, WARD_COLOR, n=20, speed=280, life=0.4, r=3)
        # ---- görünmezlik ----
        if self.veil_t > 0:
            self.veil_t -= dt
            # görünmezken oyuncunun yanına doğru süzülür
            sx_, sy_ = -(player.y - self.y), (player.x - self.x)
            ln = math.hypot(sx_, sy_) or 1.0
            dx, dy = norm_dir(self.x, self.y, player.x, player.y)
            self.x += (dx * 1.1 + sx_ / ln * 0.6 * self.strafe_dir) * self.speed * 1.4 * dt
            self.y += (dy * 1.1 + sy_ / ln * 0.6 * self.strafe_dir) * self.speed * 1.4 * dt
            if random.random() < dt * 6:
                fx.spark(self.x + random.uniform(-20, 20), self.y + random.uniform(-20, 20),
                         self.color, 0, -30, 0.4, 3)
            if self.veil_t <= 0:
                fx.shockwave(self.x, self.y, 190, self.color, 0.45, 7)
                fx.popup(self.x, self.y - self.radius - 28, "BELİRDİ!", self.color, 22, life=0.8)
                hazards.append(Hazard(self.x, self.y, 150, 0.30,
                                      self.dmg * 0.80 * self._area_dmg_k(), owner=self))
                self.atk_timer = 0.05
                sfx("warn", 0.7, 0.0)
        # ---- can emme bağı ----
        if self.drain_t > 0:
            self.drain_t -= dt
            self.drain_px, self.drain_py = player.x, player.y
            if not player.alive or dist(self.x, self.y, player.x, player.y) > DRAIN_RANGE:
                self.drain_t = 0.0
                fx.popup(player.x, player.y - 40, "BAĞ KOPTU!", (255, 200, 200), 20, life=0.8)
                sfx("crit", 0.5, 0.0)
            else:
                self.drain_acc += dt
                while self.drain_acc >= DRAIN_TICK and self.drain_t > 0:
                    self.drain_acc -= DRAIN_TICK
                    # Süreli etki gibi işler (kalkan yükü harcamaz, dash
                    # keser); tık başına azami canın %2.2'siyle tavanlı.
                    amt = min(max(1.0, self.dmg * DRAIN_DMG_K * self._area_dmg_k()),
                              max(2.0, player.max_hp * 0.022))
                    hp0 = player.hp
                    player._status_tick(amt, fx, self.name, DRAIN_COLOR)
                    dealt = max(0.0, hp0 - player.hp)
                    if dealt > 0:
                        self.on_damage_dealt(dealt * DRAIN_HEAL_K / max(0.05, self.lifesteal))
                    fx.spark(player.x, player.y, DRAIN_COLOR,
                             (self.x - player.x) * 1.5, (self.y - player.y) * 1.5, 0.45, 4)
        # ---- patlama halkaları ----
        if self.nova_n > 0:
            self.nova_cd -= dt
            if self.nova_cd <= 0:
                self.nova_cd = 0.42
                n = 16 + 2 * min(4, self.boss_index)
                gap = random.randrange(n)
                for i in range(n):
                    if i in (gap, (gap + 1) % n):
                        continue          # kaçış boşluğu
                    self._shoot(projectiles, self.nova_ang + i * math.tau / n, 250, 0.45, r=7,
                                color=lighten(self.color, 0.35))
                self.nova_ang += math.tau / n / 2
                self.nova_n -= 1
                fx.shockwave(self.x, self.y, 120, lighten(self.color, 0.35), 0.3, 4)
        # ---- kök tuzakları ----
        if self.snares:
            keep = []
            for sn in self.snares:
                sn[2] -= dt
                if sn[2] > 0:
                    keep.append(sn)
                    continue
                fx.burst(sn[0], sn[1], (120, 200, 80), n=16, speed=170, life=0.45, r=3.5)
                if player.alive and dist(sn[0], sn[1], player.x, player.y) < SNARE_R + player.radius - 4:
                    self.hit_player(player, self.dmg * 0.45 * self._area_dmg_k(), fx, sn[0], sn[1])
                    player.apply_slow(0.25, SNARE_ROOT)
                    fx.popup(player.x, player.y - 42, "KÖKLENDİN!", (170, 230, 110), 20, life=0.9)
            self.snares = keep

    def _update_skills(self, dt, player, fx, projectiles, hazards, d):
        """Yeteneklerin kare kare işleyişi: çekim, güç artışı, avlanma."""
        self._update_new_skills(dt, player, fx, projectiles, hazards)
        # ---- çekim: oyuncuyu patrona doğru sürükler ----
        if self.pull_t > 0:
            self.pull_t -= dt
            if player.alive:
                dx, dy = norm_dir(player.x, player.y, self.x, self.y)
                pull_v = 470.0 * (1.0 if not self.enraged else 1.25)
                player.x = clamp(player.x + dx * pull_v * dt,
                                 ARENA_RECT.left + player.radius, ARENA_RECT.right - player.radius)
                player.y = clamp(player.y + dy * pull_v * dt,
                                 ARENA_RECT.top + player.radius, ARENA_RECT.bottom - player.radius)
                if random.random() < dt * 14:
                    fx.spark(player.x + random.uniform(-24, 24), player.y + random.uniform(-24, 24),
                             (200, 140, 255), dx * 160, dy * 160, 0.35, 2.6)

        # ---- savaş çığlığı güç artışı ----
        if self.buff_t > 0:
            self.buff_t -= dt
            if random.random() < dt * 5:
                fx.spark(self.x + random.uniform(-self.radius, self.radius),
                         self.y + random.uniform(-self.radius, self.radius),
                         (255, 170, 80), 0, -60, 0.45, 3)

        # ---- avlanma: oyuncu fazla uzaklaşırsa patron kovalamaya başlar ----
        can_hunt = (self.flee_timer <= 0 and self.charge_t <= 0 and self.fly_t <= 0
                    and self.pull_t <= 0 and self.spawn_t > 2.0)
        if can_hunt and d > BOSS_HUNT_DIST:
            self.hunt_check += dt
            if self.hunt_check >= BOSS_HUNT_DELAY and self.hunt_t <= 0:
                self.hunt_t = BOSS_HUNT_TIME
                self.hunt_check = 0.0
                fx.popup(self.x, self.y - self.radius - 30, "AVLANIYOR!",
                         (255, 90, 70), 24, life=1.0)
                sfx("warn", 0.8, 0.0)
        else:
            self.hunt_check = 0.0
        if self.hunt_t > 0:
            self.hunt_t -= dt
            if d < self.want_dist * 1.15:
                self.hunt_t = 0.0      # yetişti, normal dövüş mesafesine döndü

        # ---- dönme yönü zaman zaman değişsin (tahmin edilemez olsun) ----
        self.strafe_t -= dt
        if self.strafe_t <= 0:
            self.strafe_t = random.uniform(1.4, 2.8)
            self.strafe_dir = -self.strafe_dir

        # ---- ek yetenek zamanlayıcısı ----
        if (self.spawn_t > 2.5 and self.charge_t <= 0 and self.fly_t <= 0
                and self.pull_t <= 0 and not self.is_hidden()):
            self.skill_cd -= dt
            if self.skill_cd <= 0:
                if self.telegraph is not None:
                    # Ekranda hâlihazırda bir uyarı varken yenisini kurmak onu
                    # siler ve oyuncu kaçmaya çalıştığı işaretin ortadan
                    # kalktığını görür.
                    self.skill_cd = 0.15
                else:
                    self.skill_cd = self._skill_interval()
                    self._cast_skill(player, fx, projectiles, hazards)

    def on_damage_dealt(self, amount):
        """Patron verdiği hasarın bir kısmını canına ekler (can çalma)."""
        if not self.alive or self.lifesteal <= 0 or amount <= 0:
            return
        heal = min(amount * self.lifesteal, self.heal_budget)
        if heal <= 0:
            return
        self.heal_budget -= heal
        before = self.hp
        self.hp = min(self.max_hp, self.hp + heal)
        gained = self.hp - before
        if gained > 0.5:
            self.heal_flash = 0.45
            self.healed_total += gained

    def apply_poison(self, dps):
        self.poison_dps += dps

    def apply_burn(self, dps, duration):
        """Patronlar da yanabilsin diye: yanık, zehirden farklı olarak süreli."""
        self.burn_timer = max(getattr(self, "burn_timer", 0.0), duration)
        self.burn_dps = max(getattr(self, "burn_dps", 0.0), dps)

    def apply_slow(self, mult, duration):
        cur = getattr(self, "slow_mult", 1.0)
        if getattr(self, "slow_timer", 0.0) <= 0 or mult < cur:
            self.slow_mult = mult
        self.slow_timer = max(getattr(self, "slow_timer", 0.0), duration)

    def update(self, dt, player, fx, projectiles, hazards, kill_cb=None):
        if not self.alive:
            return
        self.spawn_t += dt
        self.fight_time += dt
        self.wobble += dt * 3
        # can çalma bütçesi saniyede yenilenir (en fazla 1 saniyelik birikir)
        cap = self.heal_rate if self.heal_rate is not None else self.max_hp * BOSS_LIFESTEAL_CAP
        self.heal_budget = min(cap, self.heal_budget + cap * dt)
        # hasar tavanı havuzu saniyede max_hp / BOSS_MIN_FIGHT_TIME dolar.
        if self.intake_budget is not None:
            mft = getattr(self, "min_fight_time", BOSS_MIN_FIGHT_TIME)
            self.intake_budget = min(self.max_hp * BOSS_BURST_POOL,
                                     self.intake_budget + self.max_hp / mft * dt)
        if self.heal_flash > 0:
            self.heal_flash -= dt
        if self.touch_cd > 0:
            self.touch_cd -= dt

        # ---- zehir / yanık: patron da bu etkilerden hasar alır ----
        if self.poison_dps > 0:
            self.poison_tick_acc += dt
            while self.poison_tick_acc >= 0.5 and self.alive:
                self.poison_tick_acc -= 0.5
                if self.take_damage(self.poison_dps * 0.5, False, fx) and kill_cb:
                    kill_cb(self)
            if not self.alive:
                return
        if getattr(self, "burn_timer", 0.0) > 0:
            self.burn_timer -= dt
            self.burn_tick_acc = getattr(self, "burn_tick_acc", 0.0) + dt
            while self.burn_tick_acc >= 0.5 and self.alive:
                self.burn_tick_acc -= 0.5
                if self.take_damage(self.burn_dps * 0.5, False, fx) and kill_cb:
                    kill_cb(self)
            if self.burn_timer <= 0:
                self.burn_dps = 0.0
            if not self.alive:
                return
        scale_in = ease_out_cubic(self.spawn_t / 0.6)
        # Baktığı yön oyuncuya doğru yumuşakça döner + yürüyüş fazı ilerler.
        if player.alive:
            tfx, tfy = norm_dir(self.x, self.y, player.x, player.y)
            k = min(1.0, dt * 5.0)
            self.face_x += (tfx - self.face_x) * k
            self.face_y += (tfy - self.face_y) * k
            fl = math.hypot(self.face_x, self.face_y) or 1.0
            self.face_x /= fl
            self.face_y /= fl
        self.gait += dt * (7.0 if self.fly_t > 0 else 3.4)
        # Fazlar daha erken tetikleniyor: patron dövüşünün büyük bölümü öfkeli
        # geçiyor, yani daha hızlı ve daha agresif.
        if not self.enraged and self.hp < self.max_hp * 0.62:
            self.enraged = True
            fx.popup(self.x, self.y - self.radius - 30, "ÖFKELENDİ!", (255, 90, 70), 26, life=1.2)
            fx.do_flash((255, 60, 40), 0.35)
        if not self.desperate and self.hp < self.max_hp * 0.26:
            self.desperate = True
            self.summon_cd = min(self.summon_cd, 1.0)
            fx.popup(self.x, self.y - self.radius - 30, "ÇARESİZ!", (255, 190, 60), 28, life=1.3)
            fx.do_flash((255, 210, 80), 0.3)
            sfx("warn", 0.9, 0.0)

        # Öfkelendikten sonra periyodik olarak yanına yeni yaratıklar çağırır
        # ve kısa bir süre oyuncudan kaçarak mesafe açar - boss pasif bir hedef
        # değil, savaş alanını yöneten bir tehdit. kovan ana bunu daha da ileri
        # götürür: öfkelenmeyi beklemeden çağırır.
        if self.enraged or self.kind == "hive":
            self.summon_cd -= dt
            if self.summon_cd <= 0 and self.spawn_t > 1.0:
                base_cd = 4.2 if self.kind == "hive" else random.uniform(5.0, 7.0)
                self.summon_cd = base_cd * (0.55 if self.desperate else 1.0)
                self._summon_minions(fx)
                self.flee_timer = max(self.flee_timer, 2.4 if self.desperate else 1.6)

        # ---- imza özelliği: görünmezlik / uçuş / alev izi ----
        self._update_trait(dt, player, fx, projectiles, hazards)

        # orak: ruh sıçraması - oyuncunun dibine ışınlanır ve anında vurur.
        if self.kind == "reaper" and self.spawn_t > 1.2:
            self.teleport_cd -= dt
            if self.teleport_cd <= 0:
                self.teleport_cd = random.uniform(2.8, 4.4) * (0.55 if self.enraged else 1.0)
                fx.ring(self.x, self.y, self.color, n=16, speed=180, life=0.3, r=2.5)
                # oyuncunun gittiği yönün tersine, yani tam arkasına
                mvx, mvy = getattr(player, "vx", 0.0), getattr(player, "vy", 0.0)
                ml = math.hypot(mvx, mvy)
                if ml > 40:
                    ang = math.atan2(-mvy / ml, -mvx / ml) + random.uniform(-0.5, 0.5)
                else:
                    ang = random.uniform(0, math.tau)
                rad = self.want_dist * 0.62
                self.x = clamp(player.x + math.cos(ang) * rad,
                               ARENA_RECT.left + self.radius, ARENA_RECT.right - self.radius)
                self.y = clamp(player.y + math.sin(ang) * rad,
                               ARENA_RECT.top + self.radius, ARENA_RECT.bottom - self.radius)
                fx.ring(self.x, self.y, self.color, n=22, speed=240, life=0.38, r=3)
                fx.spark(self.x, self.y, self.color, 0, -60, 0.5, 6)
                sfx("warn", 0.5, 0.0)
                self.flee_timer = 0.0
                self.atk_timer = min(self.atk_timer, 0.18)   # belirince hemen vurur

        d = dist(self.x, self.y, player.x, player.y)
        dx, dy = norm_dir(self.x, self.y, player.x, player.y)
        # ---- ek yetenekler: çekim, güç artışı, avlanma ve yetenek sayacı ----
        self._update_skills(dt, player, fx, projectiles, hazards, d)
        self._update_power(dt, player, fx, projectiles, hazards)
        if self.fly_t > 0:
            # ejderha havada: yönünü _update_trait belirliyor, burada durulur.
            pass
        elif self.charge_t > 0:
            # kolos hücumu: telgraflanan yönde hızla ilerler, yolundakini ezer.
            self.charge_t -= dt
            cs = self.speed * 5.4
            self.x += self.charge_dir[0] * cs * dt
            self.y += self.charge_dir[1] * cs * dt
            fx.spark(self.x + random.uniform(-self.radius, self.radius),
                     self.y + random.uniform(-self.radius, self.radius),
                     self.color, random.uniform(-40, 40), random.uniform(-40, 40), .35, 5)
            if (self.x <= ARENA_RECT.left + self.radius or self.x >= ARENA_RECT.right - self.radius
                    or self.y <= ARENA_RECT.top + self.radius or self.y >= ARENA_RECT.bottom - self.radius):
                # duvara toslar: sersemler ve yer sarsılır
                self.charge_t = 0.0
                fx.shockwave(self.x, self.y, 190, self.color, 0.5, 7)
                fx.shake(12, 0.35)
                sfx("bonk", 0.8, 0.0)
        elif self.flee_timer > 0:
            self.flee_timer -= dt
            if d >= BOSS_FLEE_MAX_DIST:
                # Yeterince uzaklaştı: kaçışı kes, dövüşe geri dön.
                self.flee_timer = 0.0
            else:
                flee_k = 1.9 if self.desperate else 1.5
                self.x -= dx * self.speed * flee_k * dt * scale_in
                self.y -= dy * self.speed * flee_k * dt * scale_in
        elif self.hunt_t > 0:
            # avlanma: dövüş mesafesi umurunda değil, doğrudan üstüne gelir.
            hs = max(self.speed * BOSS_HUNT_SPEED,
                     player.eff_speed() * BOSS_HUNT_MIN_VS_PLAYER)
            if self.buff_t > 0:
                hs *= BOSS_BUFF_SPEED
            self.x += dx * hs * dt * scale_in
            self.y += dy * hs * dt * scale_in
            if random.random() < dt * 8:
                fx.spark(self.x - dx * self.radius, self.y - dy * self.radius,
                         self.trait["color"], -dx * 90, -dy * 90, 0.35, 3)
        else:
            want_d = self.want_dist
            speed_k = 1.7 if self.enraged else 1.2
            if self.buff_t > 0:
                speed_k *= BOSS_BUFF_SPEED
            # Mesafe açıldıkça yaklaşma hızı da artar: patron dövüş mesafesine
            # dönmek için oyalanmaz.
            if d > want_d + 200:
                speed_k *= 1.55
            # dönme: hangi yönde olursa olsun patron aynı anda oyuncunun
            # çevresinde de kayar.
            sxp, syp = -dy, dx
            strafe_k = 0.95 if self.enraged else 0.75
            if self.buff_t > 0:
                strafe_k *= BOSS_BUFF_SPEED
            self.x += sxp * self.speed * strafe_k * self.strafe_dir * dt * scale_in
            self.y += syp * self.speed * strafe_k * self.strafe_dir * dt * scale_in
            if d > want_d + 20:
                self.x += dx * self.speed * speed_k * dt * scale_in
                self.y += dy * self.speed * speed_k * dt * scale_in
            elif d < want_d - 20:
                self.x -= dx * self.speed * 0.6 * dt * scale_in
                self.y -= dy * self.speed * 0.6 * dt * scale_in
        self.x = clamp(self.x, ARENA_RECT.left + self.radius, ARENA_RECT.right - self.radius)
        self.y = clamp(self.y, ARENA_RECT.top + self.radius, ARENA_RECT.bottom - self.radius)

        if self.hit_flash > 0:
            self.hit_flash -= dt

        # ---- yaylım ateş: her patronun düzenli menzilli tehdidi ----
        if self.spawn_t > 1.5 and self.charge_t <= 0 and self.fly_t <= 0 and not self.is_hidden():
            self.volley_cd -= dt
            if self.volley_cd <= 0:
                self.volley_cd = self._volley_interval()
                self._fire_volley(player, fx, projectiles)

        if self.telegraph:
            kind, tx, ty, r, timer, total = self.telegraph
            timer -= dt
            if timer <= 0:
                self._unleash(kind, tx, ty, r, player, fx, projectiles, hazards)
                self.telegraph = None
            else:
                self.telegraph = (kind, tx, ty, r, timer, total)
        else:
            self.atk_timer -= dt
            if (self.atk_timer <= 0 and self.spawn_t > 1.0
                    and self.fly_t <= 0 and not self.is_hidden()):
                # Saldırı temposu hem faza hem de kaçıncı patron olduğuna
                # bağlı: geç dalgalardaki patronlar gözle görülür biçimde daha
                # sık vurur.
                cadence = 0.32 if self.desperate else (0.46 if self.enraged else 0.85)
                cadence *= max(0.45, 1.0 - (self.boss_index - 1) * 0.11)
                if self.buff_t > 0:
                    cadence *= BOSS_BUFF_CADENCE
                self.atk_timer = random.uniform(0.9, 1.45) * cadence
                self._start_attack(player, fx)

        if player.alive and self.touch_cd <= 0:
            if dist(self.x, self.y, player.x, player.y) < self.hit_r + player.radius - 3:
                self.touch_cd = 0.42
                # Hücum eden kolos'a ya da dalışa geçen ejderha'ya çarpmak
                # sıradan temastan çok daha acıtır.
                touch_dmg = self.dmg * (1.7 if (self.charge_t > 0 or self.fly_t > 0) else 1.0)
                self.hit_player(player, touch_dmg, fx)

    def _summon_minions(self, fx):
        """Boss'un yanına yeni, daha küçük yaratıklar doğurur ve oyuncudan kaçmaya başlar - böylece oyuncu hem patronla hem de çağrılan yaratıklarla aynı anda uğraşmak zorunda kalır."""
        if self.kind == "hive":
            n = 5 if self.desperate else 4
            kinds = ["red", "sprinter", "blue", "yellow"]
        else:
            n = 4 if self.desperate else 3
            kinds = ["red", "sprinter", "blue"]
        # Çağrılan yaratıklar patronun dalgasıyla ölçeklenir; 30. dalgadaki
        # patronun yaratıkları da 30. dalga gücündedir.
        mult = 1.0 + max(0, self.wave - 1) * 0.20
        for _ in range(n):
            ang = random.uniform(0, math.tau)
            mx = clamp(self.x + math.cos(ang) * 100, ARENA_RECT.left + 20, ARENA_RECT.right - 20)
            my = clamp(self.y + math.sin(ang) * 100, ARENA_RECT.top + 20, ARENA_RECT.bottom - 20)
            kind = random.choice(kinds)
            if self.hellish:
                self.summoned_enemies.append(
                    Enemy(kind, mx, my, mult, 1.0, wave=self.wave,
                          variant=hell_pick_kind(self.wave), biome="hell"))
            elif self.theme:
                # harita patronu kendi haritasının yaratıklarını çağırır
                self.summoned_enemies.append(
                    make_map_enemy(self.theme, kind, mx, my, mult, 1.0, wave=self.wave))
            else:
                self.summoned_enemies.append(Enemy(kind, mx, my, mult, 1.0, wave=self.wave))
        fx.ring(self.x, self.y, self.color, n=18, speed=190, life=0.4, r=3)
        fx.popup(self.x, self.y - self.radius - 10, "YARATIKLAR ÇAĞIRIYOR!", self.color, 16, life=0.9)
        sfx("warn", 0.6, 0.0)

    def _set_telegraph(self, kind, a, b, c, dur):
        """Patronun tüm saldırıları bu kapıdan geçer."""
        total = dur + BOSS_TELEGRAPH_EXTRA
        self.telegraph = (kind, a, b, c, total, total)

    def _lead_point(self, player, lead=0.34):
        """Oyuncunun bulunduğu yere değil, gideceği yere nişan alır."""
        lx = player.x + getattr(player, "vx", 0.0) * lead
        ly = player.y + getattr(player, "vy", 0.0) * lead
        return (clamp(lx, ARENA_RECT.left + 20, ARENA_RECT.right - 20),
                clamp(ly, ARENA_RECT.top + 20, ARENA_RECT.bottom - 20))

    def _aim_angle(self, player, speed, jitter=0.10):
        """Merminin oyuncuyu yakalayacağı açı (gerçek kesişim noktası)."""
        px, py = player.x, player.y
        vx, vy = getattr(player, "vx", 0.0), getattr(player, "vy", 0.0)
        speed = max(60.0, speed)
        t_hit = dist(self.x, self.y, px, py) / speed
        for _ in range(2):      # iki yineleme yeterince yakınsıyor
            t_hit = dist(self.x, self.y, px + vx * t_hit, py + vy * t_hit) / speed
        t_hit += random.uniform(-jitter, jitter)
        tx = clamp(px + vx * t_hit, ARENA_RECT.left + 20, ARENA_RECT.right - 20)
        ty = clamp(py + vy * t_hit, ARENA_RECT.top + 20, ARENA_RECT.bottom - 20)
        return math.atan2(ty - self.y, tx - self.x)

    def _ring_count(self):
        """Lanet çemberindeki tuzak sayısı."""
        want = 7 + min(3, self.boss_index - 1) + (1 if self.enraged else 0)
        # Halkanın çevresi, istenen tuzak sayısını geçilebilir aralıklarla
        # taşıyamıyorsa tuzak sayısı kırpılır - çember asla tamamen kapanmaz.
        max_n = int((math.tau * self._ring_radius()) // BOSS_RING_GAP_MIN)
        return max(5, min(want, max_n))

    def _ring_radius(self):
        # Yarıçap tuzak sayısından daha hızlı büyür; böylece tuzak merkezleri
        # arasındaki uzaklık her zaman 2*(tuzak_yarıçapı + oyuncu_yarıçapı)
        # değerinin üstünde kalır ve aradan geçilebilir.
        return 160 + self.boss_index * 12

    def _volley_interval(self):
        """İki yaylım ateş arasındaki süre - geç patronlarda belirgin kısalır."""
        base = max(1.5, 5.0 - (self.boss_index - 1) * 0.80)
        if self.desperate:
            base *= 0.55
        elif self.enraged:
            base *= 0.72
        return base * random.uniform(0.85, 1.15)

    def _ranged_dmg_k(self):
        """Menzilli saldırıların hasar katsayısı."""
        return max(0.45, 1.0 - (self.boss_index - 1) * 0.09)

    def _shoot(self, projectiles, ang, speed, dmg_k, r=8, color=None,
               target=None, turn=0.0, accel=0.0):
        projectiles.append(EnemyProjectile(
            self.x, self.y, math.cos(ang) * speed, math.sin(ang) * speed,
            self.dmg * dmg_k * self._ranged_dmg_k(), color=color or self.color, r=r,
            target=target, turn=turn, accel=accel, owner=self))

    def _fire_volley(self, player, fx, projectiles):
        """Her patronun kendine özgü menzilli saldırısı."""
        bi = self.boss_index
        eng = self.enraged or self.desperate

        if self.kind == "warlord":
            # Üç mermilik kısa seri - savaş lordu zaten ışın yağdırıyor.
            spd = 420 + bi * 14
            base = self._aim_angle(player, spd)
            n = 3 + min(3, (bi - 1) // 2)
            for i in range(n):
                self._shoot(projectiles, base + (i - (n - 1) / 2) * 0.16,
                            spd, 0.50, r=7)
            sfx("shoot_c", 0.5, 0.0)

        elif self.kind == "witch":
            # lanet mermileri: yay biçiminde çıkar, bir süre oyuncuyu takip
            # eder.
            spd = 290 + bi * 14
            base = self._aim_angle(player, spd, jitter=0.18)
            n = 4 + min(3, bi) + (2 if eng else 0)
            spread = 1.05
            for i in range(n):
                ang = base + (i - (n - 1) / 2) * (spread / max(1, n - 1))
                self._shoot(projectiles, ang, spd, 0.46, r=8,
                            color=(175, 110, 235), target=player,
                            turn=1.9 + 0.12 * bi, accel=40)
            fx.ring(self.x, self.y, (175, 110, 235), n=14, speed=150, life=0.35, r=3)
            sfx("shoot_c", 0.55, 0.0)

        elif self.kind == "colossus":
            # şok dalgası: yerden her yöne yayılan ağır taş parçaları.
            n = 10 + bi * 2 + (4 if eng else 0)
            off = random.uniform(0, math.tau)
            for i in range(n):
                self._shoot(projectiles, off + i * math.tau / n, 205 + bi * 8, 0.42,
                            r=11, color=(150, 165, 195))
            fx.shockwave(self.x, self.y, 150, self.color, 0.4, 6)
            fx.shake(7, 0.22)
            sfx("explosion", 0.5, 0.0)

        elif self.kind == "reaper":
            # çapraz kesik: iki hızlı, dar mermi dalgası.
            spd = 470 + bi * 16
            base = self._aim_angle(player, spd, jitter=0.07)
            for wave_i in range(2):
                for o in (-0.22, 0.0, 0.22):
                    self._shoot(projectiles, base + o + wave_i * 0.11,
                                spd, 0.40, r=6, color=(120, 240, 210))
            sfx("shoot_c", 0.5, 0.0)

        elif self.kind == "dragon":
            # alev topları: ağır, yavaş ama peşini bırakmayan kor yumakları +
            # aralarına serpiştirilen küçük kıvılcımlar.
            spd = 275 + bi * 12
            base = self._aim_angle(player, spd, jitter=0.16)
            n = 3 + min(3, bi // 2) + (2 if eng else 0)
            for i in range(n):
                ang = base + (i - (n - 1) / 2) * 0.22
                self._shoot(projectiles, ang, spd, 0.52, r=13,
                            color=(255, 130, 50), target=player,
                            turn=1.1 + 0.08 * bi, accel=70)
            spark_spd = 360 + bi * 16
            spark_base = self._aim_angle(player, spark_spd, jitter=0.14)
            for i in range(4 + bi):
                self._shoot(projectiles, spark_base + random.uniform(-0.8, 0.8),
                            spark_spd, 0.26, r=6, color=(255, 205, 110))
            fx.ring(self.x, self.y, (255, 150, 60), n=16, speed=180, life=0.4, r=3.5)
            sfx("shoot_c", 0.6, 0.0)

        else:  # hive
            # spor okları: yavaş ama ısrarla takip eden mermiler.
            spd = 225 + bi * 12
            base = self._aim_angle(player, spd, jitter=0.20)
            n = 5 + min(3, bi) + (3 if eng else 0)
            for i in range(n):
                ang = base + random.uniform(-0.9, 0.9)
                self._shoot(projectiles, ang, spd, 0.40, r=9,
                            color=(230, 190, 70), target=player,
                            turn=1.5 + 0.10 * bi, accel=55)
            fx.ring(self.x, self.y, (230, 190, 70), n=12, speed=130, life=0.35, r=3)
            sfx("shoot_c", 0.5, 0.0)

    def _start_attack(self, player, fx):
        bi = self.boss_index
        if self.kind == "warlord":
            # ikinci saldırı - kılıç kasırgası. savaş lordu oyuncunun
            # karşılaştığı ilk patron (10. dalga) ve en tek düzesiydi: 90
            # saniyede 58 saldırının 51'i aynı ışın yelpazesiydi (%88 tek tür),
            # oysa diğer beş patronun hepsinde 2-3 ana saldırı var.
            if bi >= 2 and random.random() < 0.38:
                self._set_telegraph("hazard_ring", 0, 0, 0,
                                    0.48 if self.enraged else 0.60)
                fx.ring(self.x, self.y, self.color, n=20, speed=180, life=0.45, r=3)
                return
            n = 9 if self.enraged else 5
            n += min(4, bi - 1)          # geç patron daha geniş yelpaze açar
            spread = 0.30 if self.enraged else 0.38
            # Işınlar 375-430 hızında mermi; telgraf süresi de eklenerek
            # oyuncunun ateş anında olacağı yere nişan alınır.
            base = self._aim_angle(player, 400, jitter=0.12)
            angs = [base + (i - (n - 1) / 2) * spread for i in range(n)]
            self._telegraph_beams(angs)
        elif self.kind == "witch":
            # lanet çemberi: halka patronun değil oyuncunun çevresine kurulur.
            if random.random() < (0.50 if bi >= 2 else 0.30):
                ang = self._aim_angle(player, 330 + bi * 20, jitter=0.16)
                self._set_telegraph("barrage", ang, 0, 0, 0.45)
            else:
                px, py = self._lead_point(player, 0.95)
                r = self._ring_radius()
                self._set_telegraph("ring_player", px, py, r, 0.62 if self.enraged else 0.80)
                fx.ring(px, py, self.color, n=24 if self.enraged else 20, speed=150, life=0.5, r=3)
        elif self.kind == "reaper":
            px, py = self._lead_point(player, 0.85)
            if random.random() < 0.5:
                # biçme darbesi: hedefin üstüne inen geniş alan
                self._set_telegraph("scythe", px, py, 120 if self.enraged else 100,
                                    0.5 if self.enraged else 0.62)
            else:
                # çapraz kesik: 2-3 hızlı ışın
                ang = self._aim_angle(player, 400, jitter=0.10)
                offs = (-0.26, 0.0, 0.26) if self.enraged else (-0.2, 0.2)
                self._telegraph_beams([ang + o for o in offs])
        elif self.kind == "hive":
            px, py = self._lead_point(player, 1.00)
            if bi >= 2 and random.random() < 0.40:
                # spor yağmuru: telgraflanan, hızlı ve yoğun bir mermi
                # yelpazesi.
                ang = self._aim_angle(player, 330 + bi * 20, jitter=0.18)
                self._set_telegraph("barrage", ang, 0, 0, 0.50)
            else:
                # Etrafına dağılan, birbirini takip eden çoklu zehir havuzları.
                self._set_telegraph("spore", px, py, 90, 0.7 if self.enraged else 0.85)
                fx.ring(self.x, self.y, self.color, n=16, speed=140, life=0.45, r=3)
        elif self.kind == "dragon":
            px, py = self._lead_point(player, 0.90)
            ang = math.atan2(py - self.y, px - self.x)
            roll = random.random()
            if roll < 0.50:
                # alev püskürtme: önüne uzanan, yere kor döşeyen alev koridoru
                self._set_telegraph("breath", ang, 0, 0, 0.62 if self.enraged else 0.80)
                fx.popup(self.x, self.y - self.radius - 28, "ALEV PÜSKÜRTÜYOR!",
                         (255, 170, 80), 22, life=0.9)
            elif roll < 0.78:
                # alev duvarı: oyuncunun yoluna dikine bir ateş perdesi çeker
                self._set_telegraph("firewall", px, py, ang, 0.58)
            else:
                # kanat darbesi: çevresine halka biçiminde kor saçar
                self._set_telegraph("wingburst", self.x, self.y, 200, 0.55)

        else:  # colossus
            px, py = self._lead_point(player, 0.95)
            if bi >= 2 and random.random() < 0.45:
                # hücum: yavaş olan kolos aradaki mesafeyi kapatabiliyor.
                self._set_telegraph("charge", px, py, 0, 0.62)
                fx.popup(self.x, self.y - self.radius - 26, "HÜCUM!", (255, 150, 60), 22, life=0.8)
            else:
                r = 165 if self.enraged else 140
                self._set_telegraph("slam", px, py, r, 0.52 if self.enraged else 0.68)
                fx.popup(px, py - 40, "!", (255, 90, 70), 30, life=0.7)
        sfx("warn", 0.7, 0.0)

    def _telegraph_beams(self, angles):
        """Aynı anda birden fazla ışını hedefler."""
        self._set_telegraph("beam", list(angles), 0, 0, 0.48)

    def _unleash(self, kind, a, b, c, player, fx, projectiles, hazards):
        if kind == "beam":
            speed = 430 if self.enraged else 375
            angs = a if isinstance(a, (list, tuple)) else [a]
            for ang in angs:
                projectiles.append(EnemyProjectile(self.x, self.y, math.cos(ang) * speed, math.sin(ang) * speed,
                                                    self.dmg * 0.9, color=self.color, r=8, owner=self))
                fx.bolt([(self.x, self.y), (self.x + math.cos(ang) * 60, self.y + math.sin(ang) * 60)],
                        self.color, 0.2)
            sfx("shoot_c", 0.6, 0.0)
        elif kind == "hazard_ring":
            n = 11 if self.enraged else 8
            for i in range(n):
                ang = i * math.tau / n
                hx = self.x + math.cos(ang) * 150
                hy = self.y + math.sin(ang) * 150
                hx = clamp(hx, ARENA_RECT.left + 20, ARENA_RECT.right - 20)
                hy = clamp(hy, ARENA_RECT.top + 20, ARENA_RECT.bottom - 20)
                hazards.append(Hazard(hx, hy, 56, 0.9, self.dmg * 1.0, owner=self))
        elif kind == "ring_player":
            # lanet çemberi: oyuncunun çevresine kapanan halka.
            n = self._ring_count()
            for i in range(n):
                ang = i * math.tau / n + random.uniform(-0.05, 0.05)
                hx = clamp(a + math.cos(ang) * c, ARENA_RECT.left + 20, ARENA_RECT.right - 20)
                hy = clamp(b + math.sin(ang) * c, ARENA_RECT.top + 20, ARENA_RECT.bottom - 20)
                hazards.append(Hazard(hx, hy, BOSS_RING_HAZARD_R, 0.45, self.dmg * 0.80, owner=self))
            fx.shockwave(a, b, c, self.color, 0.45, 6)
        elif kind == "barrage":
            # yağmur: telgraflanan yöne doğru sıkı ve hızlı bir mermi
            # yelpazesi. (cadı'nın lanet yağmuru / kovan ana'nın spor yağmuru.)
            n = 7 + self.boss_index * 2 + (3 if self.enraged else 0)
            spread = 0.62
            speed = 330 + self.boss_index * 20
            col = (210, 120, 250) if self.kind == "witch" else (245, 205, 90)
            for i in range(n):
                ang = a + (i - (n - 1) / 2) * (spread / max(1, n - 1))
                self._shoot(projectiles, ang, speed, 0.48, r=7, color=col)
            fx.bolt([(self.x, self.y),
                     (self.x + math.cos(a) * 90, self.y + math.sin(a) * 90)], col, 0.22)
            sfx("shoot_c", 0.7, 0.0)
        elif kind == "lunge":
            # atılış: telgraflanan yöne fırlar. kolos'un hücum mekaniğini
            # kullanır, ama her patron bunu yapabiliyor.
            self.charge_dir = norm_dir(self.x, self.y, a, b)
            self.charge_t = 0.55
            self.hunt_t = 0.0
            fx.shockwave(self.x, self.y, 150, self.trait["color"], 0.35, 5)
            fx.shake(8, 0.22)
            sfx("dash", 0.8, 0.0)

        elif kind == "wall":
            # duvar: (a,b) noktasından geçen, c açısına dik bir tuzak perdesi.
            # Oyuncunun kaçtığı yöne kurulur; kaçış yolunu kapatır.
            nx, ny = -math.sin(c), math.cos(c)
            n = 9 + self.boss_index
            for i in range(n):
                off = (i - (n - 1) / 2) * 76
                hx = clamp(a + nx * off, ARENA_RECT.left + 20, ARENA_RECT.right - 20)
                hy = clamp(b + ny * off, ARENA_RECT.top + 20, ARENA_RECT.bottom - 20)
                hazards.append(Hazard(hx, hy, 52, 0.05 + abs(i - (n - 1) / 2) * 0.05,
                                      self.dmg * 0.55 * self._area_dmg_k(), owner=self))
            sfx("explosion", 0.5, 0.0)

        elif kind == "cage":
            # kafes: oyuncunun çevresine kapanan halka. Aradan geçilebilecek
            # kadar boşluk bırakılır, ama oyuncu rahatça uzaklaşamaz.
            n = self._ring_count()
            for i in range(n):
                ang = i * math.tau / n + random.uniform(-0.05, 0.05)
                hx = clamp(a + math.cos(ang) * c, ARENA_RECT.left + 20, ARENA_RECT.right - 20)
                hy = clamp(b + math.sin(ang) * c, ARENA_RECT.top + 20, ARENA_RECT.bottom - 20)
                hazards.append(Hazard(hx, hy, BOSS_RING_HAZARD_R, 0.40, self.dmg * 0.55 * self._area_dmg_k(),
                                      owner=self))
            fx.shockwave(a, b, c, self.trait["color"], 0.45, 6)

        elif kind == "meteor":
            # yağmur: oyuncunun çevresine gecikmeli olarak inen darbeler.
            n = 7 + self.boss_index * 2 + (3 if self.enraged else 0)
            for i in range(n):
                ang = random.uniform(0, math.tau)
                rad = random.uniform(0, 210)
                hx = clamp(a + math.cos(ang) * rad, ARENA_RECT.left + 20, ARENA_RECT.right - 20)
                hy = clamp(b + math.sin(ang) * rad, ARENA_RECT.top + 20, ARENA_RECT.bottom - 20)
                hazards.append(Hazard(hx, hy, 58, 0.10 + i * 0.13, self.dmg * 0.60 * self._area_dmg_k(), owner=self))
            fx.shake(7, 0.3)
            sfx("explosion", 0.55, 0.0)

        elif kind == "pull":
            # çekim: oyuncuyu kısa bir süre boyunca patrona doğru sürükler.
            self.pull_t = 0.85
            fx.shockwave(self.x, self.y, 420, (200, 130, 255), 0.5, 6)
            # içe doğru akan kıvılcımlar: fx.ring dışa saçtığı için burada
            # parçacıklar elle, çeperden merkeze doğru üretiliyor.
            for i in range(26):
                a2 = i * math.tau / 26
                sx0 = self.x + math.cos(a2) * 230
                sy0 = self.y + math.sin(a2) * 230
                fx.spark(sx0, sy0, (200, 130, 255),
                         -math.cos(a2) * 320, -math.sin(a2) * 320, 0.6, 3.2)
            if player.alive:
                player.apply_slow(0.70, 1.6)
            sfx("warn", 0.9, 0.0)

        elif kind == "charge":
            # kolos hücumu: telgraflanan yöne doğru fırlar.
            self.charge_dir = norm_dir(self.x, self.y, a, b)
            self.charge_t = 0.62
            fx.shockwave(self.x, self.y, 140, self.color, 0.35, 5)
            fx.shake(9, 0.25)
            sfx("bonk", 0.6, 0.0)
        elif kind == "scythe":
            # orak: hedefin üstüne geniş, hızlı inen bir biçme darbesi.
            hazards.append(Hazard(a, b, c, 0.04, self.dmg * 1.25, owner=self))
            fx.shockwave(a, b, c, self.color, 0.3, 5)
            fx.shake(8, 0.22)
            sfx("bonk", 0.7, 0.0)
        elif kind == "spore":
            # kovan ana: hedefin çevresine saçılan zehir havuzları.
            n = 6 if self.enraged else 4
            for i in range(n):
                ang = i * math.tau / n + random.uniform(-0.3, 0.3)
                rad = random.uniform(40, 130)
                hx = clamp(a + math.cos(ang) * rad, ARENA_RECT.left + 20, ARENA_RECT.right - 20)
                hy = clamp(b + math.sin(ang) * rad, ARENA_RECT.top + 20, ARENA_RECT.bottom - 20)
                hazards.append(Hazard(hx, hy, 50, 0.2 + i * 0.12, self.dmg * 0.85, owner=self))
        elif kind == "breath":
            # alev püskürtme: patronun önünden uzanan, yere kor döşeyen
            # koridor. Hem hızlı alev mermileri hem de gecikmeli yanma
            # havuzları bırakır.
            steps = 7 + self.boss_index
            for i in range(steps):
                d = 90 + i * 74
                hx = clamp(self.x + math.cos(a) * d, ARENA_RECT.left + 20, ARENA_RECT.right - 20)
                hy = clamp(self.y + math.sin(a) * d, ARENA_RECT.top + 20, ARENA_RECT.bottom - 20)
                hazards.append(Hazard(hx, hy, 60, 0.06 * i, self.dmg * 0.60 * self._area_dmg_k(), owner=self))
            n = 9 + self.boss_index * 2
            for i in range(n):
                self._shoot(projectiles, a + random.uniform(-0.26, 0.26),
                            330 + random.uniform(-40, 90), 0.34, r=9,
                            color=(255, 150 + random.randint(0, 60), 60))
            fx.shockwave(self.x, self.y, 130, (255, 150, 60), 0.35, 5)
            fx.shake(7, 0.25)
            sfx("explosion", 0.6, 0.0)

        elif kind == "firewall":
            # alev duvarı: hedefin üstünden geçen, yola dik bir ateş perdesi.
            nx, ny = -math.sin(c), math.cos(c)
            n = 7 + self.boss_index
            for i in range(n):
                off = (i - (n - 1) / 2) * 88
                hx = clamp(a + nx * off, ARENA_RECT.left + 20, ARENA_RECT.right - 20)
                hy = clamp(b + ny * off, ARENA_RECT.top + 20, ARENA_RECT.bottom - 20)
                hazards.append(Hazard(hx, hy, 54, 0.05 + abs(i - (n - 1) / 2) * 0.05,
                                      self.dmg * 0.85 * self._area_dmg_k(), owner=self))
            sfx("explosion", 0.5, 0.0)

        elif kind == "wingburst":
            # kanat darbesi: çevresine halka hâlinde kor saçar + geri iter.
            n = 14 + self.boss_index * 2
            for i in range(n):
                self._shoot(projectiles, i * math.tau / n + random.uniform(-0.08, 0.08),
                            250 + self.boss_index * 10, 0.38, r=8, color=(255, 170, 70))
            fx.shockwave(self.x, self.y, c, (255, 160, 70), 0.45, 7)
            fx.shake(9, 0.28)
            sfx("bonk", 0.7, 0.0)

        elif kind == "slam":
            hazards.append(Hazard(a, b, c, 0.05, self.dmg * 1.5, owner=self))
            fx.shake(10, 0.3)
            if self.enraged:
                # öfkeliyken iki gecikmeli darbe daha gelir
                for k in range(2):
                    hazards.append(Hazard(a + random.uniform(-80, 80), b + random.uniform(-80, 80),
                                           c * 0.8, 0.3 + k * 0.28, self.dmg * 1.15, owner=self))

    def take_damage(self, amount, crit, fx, kx=0.0, ky=0.0, quiet=False):
        # dokunulmazlık: kalkan sürerken hiçbir hasar işlemez.
        if getattr(self, "ward_t", 0.0) > 0:
            if not quiet and getattr(self, "ward_pop", 0.0) <= 0:
                self.ward_pop = 0.35
                fx.popup(self.x + random.uniform(-24, 24), self.y - self.radius,
                         "BAĞIŞIK", WARD_COLOR, 15, life=0.4)
            return False
        # Patron zırhı gelen hasarın sabit bir yüzdesini keser.
        amount = amount * (1.0 - self.armor)
        # bariyer: hasarın çoğunu kalkan yutar.
        if getattr(self, "aegis_hp", 0.0) > 0 and amount > 0:
            soak = min(self.aegis_hp, amount * (1.0 - AEGIS_LEAK))
            self.aegis_hp -= soak
            amount -= soak
            if self.aegis_hp <= 0.5:
                self.aegis_hp = 0.0
                fx.popup(self.x, self.y - self.radius - 34, "BARİYER KIRILDI!",
                         AEGIS_COLOR, 24, life=1.0)
                fx.ring(self.x, self.y, AEGIS_COLOR, n=30, speed=320, life=0.55, r=4)
                sfx("crit", 0.9, 0.0)
        # patron hasar tavanı: havuzda ne varsa o kadarı işler, fazlası boşa
        # gider.
        if self.intake_budget is None:
            self.intake_budget = self.max_hp * BOSS_BURST_POOL
        if amount > self.intake_budget:
            amount = max(0.0, self.intake_budget)
        self.intake_budget -= amount
        if self.alive:
            dmg_note(min(amount, max(0.0, self.hp)))
        self.hp -= amount
        if DMG_SRC[0] in EVO_ON:
            evo_on_hit(self, amount, fx)
        self.hit_flash = 0.12
        col = (255, 230, 120) if crit else WHITE
        if not quiet and amount >= 1.0:
            fx.popup(self.x + random.uniform(-20, 20), self.y - self.radius,
                     f"{int(amount)}" + ("!" if crit else ""),
                     col, 20 if crit else 15, life=0.45)
        if self.hp <= 0 and self.alive:
            self.alive = False
            fx.burst(self.x, self.y, self.color, n=40, speed=260, life=0.8, r=5)
            fx.shockwave(self.x, self.y, 260, self.color, 0.6, 8)
            fx.do_flash(self.color, 0.5)
            fx.shake(14, 0.4)
            sfx("explosion", 1.0, 0.0)
            return True
        return False

    # ---- patron çizimleri ----
    # Her patronun kendine ait bir gövdesi var. Ortak kurallar: yeni patron
    # eklemek: buraya bir _draw_<tür> metodu yaz ve Boss.draw içindeki sözlüğe
    # ekle:
    # * Çizimler, patronun baktığı yöne göre yapılır.
    # * Önce outline ile biraz büyük bir kopya, sonra asıl renk çizilir: her
    #   parçaya koyu bir dış hat kazandırır (okunurluk).
    # * `col` hasar alınca beyaza döner (vuruş geri bildirimi).

    def _facing(self):
        """(ileri_x, ileri_y, sağ_x, sağ_y) - çizim için yön vektörleri."""
        fx_, fy_ = self.face_x, self.face_y
        l = math.hypot(fx_, fy_) or 1.0
        fx_, fy_ = fx_ / l, fy_ / l
        return fx_, fy_, -fy_, fx_

    def _mapper(self, x, y, r):
        """P(ileri, yan) -> dünya koordinatı."""
        fx_, fy_, sx_, sy_ = self._facing()

        def P(f, s):
            return (x + fx_ * r * f + sx_ * r * s,
                    y + fy_ * r * f + sy_ * r * s)
        return P, fx_, fy_, sx_, sy_

    def _poly(self, surf, pts, col, x, y, grow=0.09, outline=True, width=0):
        """Koyu dış hatlı çokgen."""
        if outline and grow > 0:
            pygame.draw.polygon(surf, OUTLINE,
                                [(px + (px - x) * grow, py + (py - y) * grow) for px, py in pts])
        pygame.draw.polygon(surf, col, pts, width)

    def _limb(self, surf, pts, col, w, outline=True):
        """Kalın, dış hatlı uzuv çizgisi (bacak, boyun, kuyruk)."""
        if outline:
            pygame.draw.lines(surf, OUTLINE, False, pts, int(w + 4))
        pygame.draw.lines(surf, col, False, pts, int(w))

    def _boss_eyes(self, surf, P, r, t, n=2, spread=0.30, fwd=0.50, sz=0.15,
                   col=(255, 248, 230), glow=(255, 70, 50)):
        """Patronun gözleri: dışı açık, içi parlayan bir renk + hafif ışıma."""
        offs = [0.0] if n == 1 else [(i - (n - 1) / 2) * 2 * spread for i in range(n)]
        for o in offs:
            ex, ey = P(fwd, o)
            if glow:
                add_glow(surf, ex, ey, r * sz * 3.2, glow, 0.42 + 0.16 * math.sin(t * 5))
            pygame.draw.circle(surf, col, (int(ex), int(ey)), max(2, int(r * sz)))
            pygame.draw.circle(surf, glow or RED, (int(ex), int(ey)), max(1, int(r * sz * 0.52)))

    def _draw_vanished(self, surf, x, y, r, t):
        """Gölge perdesi: gövde yok, yalnız havadaki titreşim ve puslu gözler."""
        P, fx_, fy_, sx_, sy_ = self._mapper(x, y, r)
        k = 0.35 + 0.25 * math.sin(t * 7)
        add_glow(surf, x, y, r * 1.7, self.color, 0.10 + 0.05 * k)
        for i in range(14):
            a0 = i * math.tau / 14
            a1 = a0 + math.tau / 26
            jit = 1.0 + 0.10 * math.sin(t * 9 + i)
            pygame.draw.line(surf, scale_col(self.color, 0.75 + 0.25 * k),
                             (x + math.cos(a0) * r * jit, y + math.sin(a0) * r * jit),
                             (x + math.cos(a1) * r * jit, y + math.sin(a1) * r * jit), 2)
        for i in range(5):
            a = t * 2.0 + i * math.tau / 5
            blit_disc(surf, x + math.cos(a) * r * 1.1, y + math.sin(a) * r * 1.1,
                      2.4, lighten(self.color, 0.5), 120)
        self._boss_eyes(surf, P, r, t, n=2, spread=0.20, fwd=0.32, sz=0.11,
                        col=(240, 220, 255), glow=(190, 110, 245))

    # ---- harita patronları ----
    # Patronun başının yeri ve yarıçapı (P(ileri, yan) biriminde). Taç / başlık
    # buraya oturur; her patronun gövdesi farklı olduğu için tek tek ölçüldü.
    MAP_HEAD = {"warlord": (0.46, 0.40), "witch": (0.14, 0.50), "colossus": (0.80, 0.36),
                "reaper": (0.30, 0.46), "hive": (0.94, 0.42)}

    def _draw_map_aura(self, surf, x, y, r, t):
        """Ayağının dibindeki harita halesi: kar taneleri / yapraklar / kum girdabı."""
        th = self.theme
        acc = MAP_ACCENT.get(th, WHITE)
        add_glow(surf, x, y, r * 2.6, acc, 0.14 + 0.05 * math.sin(t * 2.2))
        ring = pygame.Rect(0, 0, int(r * 2.8), int(r * 1.4))
        ring.center = (int(x), int(y + r * 0.55))
        pygame.draw.ellipse(surf, scale_col(acc, 0.8), ring, 2)
        if th == "frost":
            for i in range(8):
                a = t * 0.8 + i * math.tau / 8
                px_ = x + math.cos(a) * r * 1.40
                py_ = y + r * 0.55 + math.sin(a) * r * 0.70
                arm = 4.5 + (i % 2) * 2.0
                for k in range(3):
                    b = a * 0.5 + k * math.pi / 3
                    dx_, dy_ = math.cos(b) * arm, math.sin(b) * arm
                    pygame.draw.line(surf, (236, 248, 255), (px_ - dx_, py_ - dy_), (px_ + dx_, py_ + dy_), 2)
        elif th == "jungle":
            for i in range(8):
                a = -t * 0.7 + i * math.tau / 8
                px_ = x + math.cos(a) * r * 1.42
                py_ = y + r * 0.55 + math.sin(a) * r * 0.72
                ca, sa = math.cos(a * 2.0 + i), math.sin(a * 2.0 + i)
                lf = [(px_ + ca * 8, py_ + sa * 8), (px_ - sa * 3.5, py_ + ca * 3.5),
                      (px_ - ca * 8, py_ - sa * 8), (px_ + sa * 3.5, py_ - ca * 3.5)]
                pygame.draw.polygon(surf, (60, 150, 60) if i % 2 else (110, 196, 80), lf)
                pygame.draw.line(surf, (40, 100, 40), lf[0], lf[2], 1)
            for i in range(5):
                ph = (t * 0.5 + i * 0.2) % 1.0
                fx0 = x + math.sin(t * 1.3 + i * 2.3) * r * 1.2
                fy0 = y - r * 0.2 - ph * r * 1.4
                blit_disc(surf, fx0, fy0, 2.6, (230, 255, 120), int(220 * (1.0 - ph)))
        elif th == "desert":
            for k in range(3):
                a0 = t * 1.6 + k * math.tau / 3
                box = pygame.Rect(0, 0, int(r * (2.3 + 0.25 * k)), int(r * (1.15 + 0.12 * k)))
                box.center = (int(x), int(y + r * 0.55))
                pygame.draw.arc(surf, (236, 200, 130), box, a0, a0 + 1.4, 3)
            for i in range(12):
                a = t * 1.9 + i * math.tau / 12
                rr = 1.25 + 0.20 * math.sin(i * 1.7 + t)
                blit_disc(surf, x + math.cos(a) * r * rr, y + r * 0.55 + math.sin(a) * r * rr * 0.5,
                          2.2, (240, 210, 150), 200)

    def _draw_map_regalia(self, surf, x, y, r, t):
        """Haritanın tacı: buz tacı / yaprak tacı / firavun başlığı."""
        P, fx_, fy_, sx_, sy_ = self._mapper(x, y, r)
        hf, hr = self.MAP_HEAD.get(self.kind, (0.4, 0.40))
        th = self.theme
        if th == "frost":
            # başın arkasında yelpaze gibi açılan buz sarkıtları
            for i in range(9):
                a = math.pi * (0.55 + 0.9 * i / 8.0)          # arka yarım + yanlar
                ca, sa = math.cos(a), math.sin(a)
                ln = 0.36 if i % 2 == 0 else 0.24
                if i == 4:
                    ln = 0.46
                base_l = P(hf + ca * hr - sa * 0.07, sa * hr + ca * 0.07)
                base_r = P(hf + ca * hr + sa * 0.07, sa * hr - ca * 0.07)
                tip = P(hf + ca * (hr + ln), sa * (hr + ln))
                pygame.draw.polygon(surf, OUTLINE, [base_l, tip, base_r], 3)
                pygame.draw.polygon(surf, (214, 240, 255), [base_l, tip, base_r])
                pygame.draw.line(surf, WHITE, P(hf + ca * hr, sa * hr), tip, 1)
            add_glow(surf, *P(hf - hr * 0.6, 0.0), r * 0.55, (180, 230, 255), 0.35)
            cx_, cy_ = P(hf + hr * 0.15, 0.0)
            pygame.draw.circle(surf, OUTLINE, (int(cx_), int(cy_)), max(3, int(r * 0.09)))
            pygame.draw.circle(surf, (140, 220, 255), (int(cx_), int(cy_)), max(2, int(r * 0.065)))
        elif th == "jungle":
            # başı saran yaprak çelengi + arkada kırmızı orman çiçeği
            n = 11
            for i in range(n):
                a = i * math.tau / n + 0.15
                ca, sa = math.cos(a), math.sin(a)
                m = hr + 0.12
                pts = [P(hf + ca * hr * 0.95, sa * hr * 0.95),
                       P(hf + ca * m - sa * 0.09, sa * m + ca * 0.09),
                       P(hf + ca * (hr + 0.27), sa * (hr + 0.27)),
                       P(hf + ca * m + sa * 0.09, sa * m - ca * 0.09)]
                pygame.draw.polygon(surf, OUTLINE, pts, 3)
                pygame.draw.polygon(surf, (70, 160, 64) if i % 2 else (118, 200, 84), pts)
                pygame.draw.line(surf, (40, 104, 40), pts[0], pts[2], 1)
            fl = P(hf - hr - 0.06, 0.0)
            for i in range(5):
                a = i * math.tau / 5 + t * 0.6
                blit_disc(surf, fl[0] + math.cos(a) * r * 0.10, fl[1] + math.sin(a) * r * 0.10,
                          max(2.0, r * 0.08), (236, 70, 90), 255)
            pygame.draw.circle(surf, (255, 220, 90), (int(fl[0]), int(fl[1])), max(2, int(r * 0.055)))
        elif th == "desert":
            # firavun başlığı (nemes): başın arkasını örten çizgili başlık, iki
            # yandan omuzlara inen çizgili kanatlar, arkada örgü, alında kobra.
            gold, lapis = (236, 196, 72), (52, 78, 170)
            for sgn in (-1, 1):
                a0, a1 = P(hf + 0.04, hr * 0.62 * sgn), P(hf - 0.22, hr * 0.30 * sgn)
                b0, b1 = P(hf - hr - 0.34, (hr + 0.24) * sgn), P(hf - hr - 0.34, (hr - 0.02) * sgn)
                flap = [a0, b0, b1, a1]
                pygame.draw.polygon(surf, OUTLINE, flap, 4)
                for i in range(4):
                    k0, k1 = i / 4.0, (i + 1) / 4.0
                    band = [(a0[0] + (b0[0] - a0[0]) * k0, a0[1] + (b0[1] - a0[1]) * k0),
                            (a0[0] + (b0[0] - a0[0]) * k1, a0[1] + (b0[1] - a0[1]) * k1),
                            (a1[0] + (b1[0] - a1[0]) * k1, a1[1] + (b1[1] - a1[1]) * k1),
                            (a1[0] + (b1[0] - a1[0]) * k0, a1[1] + (b1[1] - a1[1]) * k0)]
                    pygame.draw.polygon(surf, gold if i % 2 == 0 else lapis, band)
            tail = [P(hf - hr * 0.9, 0.12), P(hf - hr - 0.55, 0.0), P(hf - hr * 0.9, -0.12)]
            pygame.draw.polygon(surf, gold, tail)
            pygame.draw.polygon(surf, OUTLINE, tail, 2)
            cx_, cy_ = P(hf - hr * 0.30, 0.0)
            cr = r * hr * 0.80
            pygame.draw.circle(surf, OUTLINE, (int(cx_), int(cy_)), int(cr + 2))
            pygame.draw.circle(surf, gold, (int(cx_), int(cy_)), int(cr))
            for kk in (0.72, 0.44):
                pygame.draw.circle(surf, lapis, (int(cx_), int(cy_)), max(2, int(cr * kk)), max(2, int(r * 0.045)))
            ux, uy = P(hf + hr * 0.48, 0.0)
            add_glow(surf, ux, uy, r * 0.30, (255, 220, 120), 0.45)
            pygame.draw.circle(surf, OUTLINE, (int(ux), int(uy)), max(3, int(r * 0.09)))
            pygame.draw.circle(surf, (250, 210, 90), (int(ux), int(uy)), max(2, int(r * 0.065)))
            pygame.draw.circle(surf, (200, 40, 40), (int(ux), int(uy)), max(1, int(r * 0.028)))

    # ---- savaş lordu ----
    def _draw_warlord(self, surf, x, y, r, col, t):
        """Zırhlı savaş lordu: dalgalanan pelerin, omuzluklar, boynuzlu miğfer"""
        P, fx_, fy_, sx_, sy_ = self._mapper(x, y, r)
        step = math.sin(self.gait) * 0.13
        dark = scale_col(col, 0.58)
        lite = lighten(col, 0.30)
        steel = (198, 205, 224)
        cape_col = (74, 18, 18) if not self.hellish else (84, 24, 12)

        # ---- pelerin: arkaya doğru genişleyen, kenarları dalgalanan kumaş ----
        cape = [P(0.06, 0.62), P(-0.28, 0.94)]
        for i in range(5):
            k = i / 4.0
            wob = math.sin(t * 2.4 + i * 1.1) * 0.16
            cape.append(P(-1.12 - 0.30 * math.sin(k * math.pi), (0.5 - k) * 1.72 + wob))
        cape += [P(-0.28, -0.94), P(0.06, -0.62)]
        self._poly(surf, cape, cape_col, x, y, grow=0.04)
        pygame.draw.polygon(surf, (66, 14, 14), cape, 2)

        # ---- baltalar: omuz hizasından öne uzanan sap + geniş ağız ----
        for sgn in (-1, 1):
            sw = step * sgn
            grip = P(0.10 + sw, 1.00 * sgn)
            tip = P(1.05 + sw, 1.12 * sgn)
            pygame.draw.line(surf, OUTLINE, grip, tip, max(5, int(r * 0.15)))
            pygame.draw.line(surf, (96, 66, 42), grip, tip, max(3, int(r * 0.10)))
            blade = [(tip[0] + (fx_ * 0.34 + sx_ * 0.02 * sgn) * r,
                      tip[1] + (fy_ * 0.34 + sy_ * 0.02 * sgn) * r),
                     (tip[0] + (fx_ * 0.16 + sx_ * 0.52 * sgn) * r,
                      tip[1] + (fy_ * 0.16 + sy_ * 0.52 * sgn) * r),
                     (tip[0] + (-fx_ * 0.30 + sx_ * 0.44 * sgn) * r,
                      tip[1] + (-fy_ * 0.30 + sy_ * 0.44 * sgn) * r),
                     (tip[0] - fx_ * 0.16 * r, tip[1] - fy_ * 0.16 * r)]
            self._poly(surf, blade, steel, x, y, grow=0.03)
            pygame.draw.polygon(surf, (110, 118, 140), blade, 2)
            if self.trait.get("hellfire"):
                add_glow(surf, tip[0], tip[1], r * 0.55, (255, 150, 60), 0.5)

        # ---- gövde: omuzları geniş, beli dar bir zırh ----
        body = [P(0.62, 0.36), P(0.30, 0.82), P(-0.46, 0.92),
                P(-0.86, 0.46), P(-0.86, -0.46), P(-0.46, -0.92),
                P(0.30, -0.82), P(0.62, -0.36)]
        self._poly(surf, body, col, x, y, grow=0.09)
        pygame.draw.polygon(surf, dark, body, 2)
        # göğüs plakası + orta kuşak
        chest = [P(0.46, 0.0), P(0.05, 0.46), P(-0.44, 0.0), P(0.05, -0.46)]
        self._poly(surf, chest, lite, x, y, grow=0.0, outline=False)
        pygame.draw.polygon(surf, dark, chest, 2)
        pygame.draw.line(surf, dark, P(0.30, 0.0), P(-0.50, 0.0), 2)

        # ---- omuzluklar ----
        for sgn in (-1, 1):
            pl = [P(-0.34, 0.66 * sgn), P(-0.18, 1.14 * sgn),
                  P(0.34, 1.06 * sgn), P(0.40, 0.62 * sgn)]
            self._poly(surf, pl, dark, x, y, grow=0.04)
            pygame.draw.polygon(surf, steel, pl, 2)
            for i in range(3):
                pygame.draw.circle(surf, steel,
                                   [int(v) for v in P(-0.12 + i * 0.22, (0.86 + i * 0.02) * sgn)],
                                   max(1, int(r * 0.055)))

        # ---- miğfer: boynuzlu, vizörlü ----
        hx, hy = P(0.46, 0.0)
        pygame.draw.circle(surf, OUTLINE, (int(hx), int(hy)), int(r * 0.42))
        pygame.draw.circle(surf, dark, (int(hx), int(hy)), int(r * 0.36))
        pygame.draw.circle(surf, steel, (int(hx), int(hy)), int(r * 0.36), 2)
        for sgn in (-1, 1):
            b0 = P(0.40, 0.30 * sgn)
            b1 = P(0.02, 0.86 * sgn)
            b2 = P(-0.28, 0.74 * sgn)
            pygame.draw.lines(surf, OUTLINE, False, [b0, b1, b2], max(5, int(r * 0.15)))
            pygame.draw.lines(surf, (240, 232, 214), False, [b0, b1, b2], max(3, int(r * 0.09)))
        pygame.draw.line(surf, (24, 18, 22), P(0.62, -0.22), P(0.62, 0.22), max(3, int(r * 0.13)))
        eye_glow = (255, 140, 60) if self.trait.get("hellfire") else (255, 90, 66)
        self._boss_eyes(surf, P, r, t, n=2, spread=0.11, fwd=0.62, sz=0.075, glow=eye_glow)

    # ---- gölge cadısı ----
    def _draw_witch(self, surf, x, y, r, col, t):
        """Kukuletalı cadı: yerden yükselen yırtık cübbe, kollarında asa, çevresinde dönen mühürler."""
        P, fx_, fy_, sx_, sy_ = self._mapper(x, y, r)
        dark = scale_col(col, 0.52)
        lite = lighten(col, 0.38)
        y = y + math.sin(t * 1.8) * r * 0.10
        P, fx_, fy_, sx_, sy_ = self._mapper(x, y, r)

        # ---- dönen mühürler (elips yörünge: yere yatık dursun) ----
        for i in range(5):
            a = t * 1.1 + i * math.tau / 5
            gx = x + math.cos(a) * r * 1.62
            gy = y + math.sin(a) * r * 1.62 * 0.55 + r * 0.30
            add_glow(surf, gx, gy, r * 0.30, lite, 0.35)
            rune = rot_pts([(0, -r * 0.16), (r * 0.12, 0), (0, r * 0.16), (-r * 0.12, 0)],
                           a * 2.0, gx, gy)
            pygame.draw.polygon(surf, lite, rune)
            pygame.draw.polygon(surf, (250, 238, 255), rune, 1)

        # ---- cübbe: omuzdan arkaya doğru açılan, etekleri yırtık ----
        robe = [P(0.46, 0.30), P(0.30, 0.62)]
        for i in range(7):
            k = i / 6.0
            wob = math.sin(t * 3.4 + i * 1.2) * 0.14
            jag = 0.16 if i % 2 else 0.0
            robe.append(P(-1.05 - 0.28 * math.sin(k * math.pi) - jag,
                          (0.5 - k) * 2.20 + wob))
        robe += [P(0.30, -0.62), P(0.46, -0.30)]
        self._poly(surf, robe, col, x, y, grow=0.05)
        pygame.draw.polygon(surf, dark, robe, 2)
        # cübbenin ön yarığı
        pygame.draw.line(surf, dark, P(0.30, 0.0), P(-0.95, 0.0), 2)

        # ---- kollar (iki yana uzanan geniş yenler) ----
        for sgn in (-1, 1):
            sleeve = [P(0.16, 0.42 * sgn), P(0.34, 0.96 * sgn),
                      P(-0.10, 1.12 * sgn), P(-0.30, 0.52 * sgn)]
            self._poly(surf, sleeve, dark, x, y, grow=0.04)

        # ---- asa: sağ elde, ucunda büyü küresi ----
        grip = P(0.20, 1.02)
        top = (grip[0] + fx_ * r * 0.30 - abs(r) * 0.0, grip[1] - r * 1.35)
        pygame.draw.line(surf, OUTLINE, (grip[0], grip[1] + r * 0.30), top, max(5, int(r * 0.13)))
        pygame.draw.line(surf, (86, 60, 46), (grip[0], grip[1] + r * 0.30), top, max(3, int(r * 0.08)))
        orb_k = 0.55 + 0.25 * math.sin(t * 4)
        add_glow(surf, top[0], top[1], r * 0.80, lite, 0.45 + 0.30 * orb_k)
        pygame.draw.circle(surf, OUTLINE, (int(top[0]), int(top[1])), int(r * 0.27))
        pygame.draw.circle(surf, lite, (int(top[0]), int(top[1])), int(r * 0.22))
        pygame.draw.circle(surf, (252, 242, 255),
                           (int(top[0] - r * 0.07), int(top[1] - r * 0.07)), max(1, int(r * 0.08)))
        for i in range(3):
            a = t * 3.0 + i * math.tau / 3
            blit_disc(surf, top[0] + math.cos(a) * r * 0.36, top[1] + math.sin(a) * r * 0.36,
                      2.4, (250, 230, 255), 170)

        # ---- kukuleta: sivri tepeli, içi kapkaranlık ----
        hood = [P(0.74, 0.0), P(0.44, 0.50), P(-0.26, 0.60),
                P(-0.62, 0.0), P(-0.26, -0.60), P(0.44, -0.50)]
        self._poly(surf, hood, dark, x, y, grow=0.05)
        pygame.draw.polygon(surf, scale_col(dark, 0.7), hood, 2)
        inner = [P(0.56, 0.0), P(0.30, 0.30), P(-0.12, 0.34),
                 P(-0.26, 0.0), P(-0.12, -0.34), P(0.30, -0.30)]
        pygame.draw.polygon(surf, (13, 9, 20), inner)
        self._boss_eyes(surf, P, r, t, n=2, spread=0.13, fwd=0.26, sz=0.085,
                        col=(246, 228, 255), glow=(208, 124, 255))

    # ---- kolos ----
    def _draw_colossus(self, surf, x, y, r, col, t):
        """Taş kolos: düzensiz kaya plakalardan örülü dev gövde, iki ağır yumruk"""
        P, fx_, fy_, sx_, sy_ = self._mapper(x, y, r)
        dark = scale_col(col, 0.55)
        lite = lighten(col, 0.26)
        core = (255, 140, 60) if self.hellish else (120, 200, 255)
        step = math.sin(self.gait) * 0.14
        pulse = 0.55 + 0.45 * math.sin(t * 3.4)

        # ---- bacaklar: kısa, kalın taş sütunlar ----
        for sgn in (-1, 1):
            fo = step * sgn
            self._limb(surf, [P(-0.50, 0.46 * sgn), P(-0.95 + fo, 0.56 * sgn),
                              P(-1.15 + fo, 0.50 * sgn)], dark, max(8, int(r * 0.30)))
            foot = [P(-1.02 + fo, 0.24 * sgn), P(-1.36 + fo, 0.34 * sgn),
                    P(-1.30 + fo, 0.78 * sgn), P(-0.98 + fo, 0.70 * sgn)]
            self._poly(surf, foot, dark, x, y, grow=0.04)

        # ---- kollar + yumruklar (öne uzanmış) ----
        for sgn in (-1, 1):
            fo = -step * sgn
            self._limb(surf, [P(0.20, 0.90 * sgn), P(0.55 + fo, 1.14 * sgn)],
                       dark, max(7, int(r * 0.26)))
            fist_c = P(0.78 + fo, 1.22 * sgn)
            pygame.draw.circle(surf, OUTLINE, (int(fist_c[0]), int(fist_c[1])), int(r * 0.46))
            pygame.draw.circle(surf, col, (int(fist_c[0]), int(fist_c[1])), int(r * 0.40))
            pygame.draw.circle(surf, lite,
                               (int(fist_c[0] - fx_ * r * 0.10), int(fist_c[1] - fy_ * r * 0.10)),
                               max(2, int(r * 0.15)))
            for i in range(3):
                pygame.draw.line(surf, dark,
                                 P(0.90 + fo, (1.02 + i * 0.14) * sgn),
                                 P(1.06 + fo, (1.00 + i * 0.14) * sgn), 2)

        # ---- gövde: üst üste binmiş düzensiz kaya plakalar ----
        plates = (
            (-0.62, 1.02, 0.42),   # kalça
            (0.02, 1.14, 0.46),    # gövde
            (0.52, 0.92, 0.34),    # göğüs
        )
        for i, (fwd, half_w, half_h) in enumerate(plates):
            pts = []
            n = 7
            for j in range(n):
                a = j * math.tau / n + 0.35 + i * 0.4
                jitter = 1.0 + 0.16 * math.sin(j * 2.7 + i)
                pts.append(P(fwd + math.cos(a) * half_h * jitter,
                             math.sin(a) * half_w * jitter))
            self._poly(surf, pts, col if i != 1 else lighten(col, 0.08), x, y, grow=0.05)
            pygame.draw.polygon(surf, dark, pts, 2)

        # ---- akkor çekirdek ----
        cx, cy = P(0.18, 0.0)
        add_glow(surf, cx, cy, r * (0.85 + 0.28 * pulse), core, 0.50 + 0.28 * pulse)
        pygame.draw.circle(surf, (20, 16, 20), (int(cx), int(cy)), int(r * 0.30))
        pygame.draw.circle(surf, core, (int(cx), int(cy)), int(r * (0.15 + 0.07 * pulse)))
        for i in range(6):
            a = i * math.tau / 6 + 0.3
            pygame.draw.line(surf, scale_col(core, 0.55 + 0.45 * pulse),
                             (cx + math.cos(a) * r * 0.26, cy + math.sin(a) * r * 0.26),
                             (cx + math.cos(a) * r * (0.70 + 0.25 * math.sin(i * 1.7)),
                              cy + math.sin(a) * r * (0.70 + 0.25 * math.sin(i * 1.7))), 2)

        # ---- kafa: omuzların arasına gömülü küçük taş blok ----
        hd = [P(1.10, 0.0), P(0.86, 0.38), P(0.50, 0.30), P(0.50, -0.30), P(0.86, -0.38)]
        self._poly(surf, hd, dark, x, y, grow=0.05)
        pygame.draw.polygon(surf, scale_col(dark, 0.75), hd, 2)
        self._boss_eyes(surf, P, r, t, n=2, spread=0.13, fwd=0.82, sz=0.085,
                        col=(255, 250, 240), glow=core)

    # ---- orak ----
    def _draw_reaper(self, surf, x, y, r, col, t):
        """Ruh toplayıcı: ayağı yere değmeyen paçavra pelerin, boş kukuleta, iki eliyle savurduğu dev tırpan."""
        P, fx_, fy_, sx_, sy_ = self._mapper(x, y, r)
        dark = scale_col(col, 0.46)
        lite = lighten(col, 0.42)
        y = y + math.sin(t * 2.4) * r * 0.13
        P, fx_, fy_, sx_, sy_ = self._mapper(x, y, r)

        # ---- ruh izi ----
        for i in range(4):
            k = 1.0 - i / 4.0
            gx, gy = P(-0.55 - i * 0.45, 0.0)
            blit_disc(surf, gx, gy, r * 0.40 * k, col, int(64 * k))

        # ---- tırpan: uzun sap + kavisli ağız (yavaşça salınır) ----
        ang0 = math.sin(t * 0.9) * 0.7 + self.wobble * 0.10
        base = P(0.10, 0.62)
        sh_end = (base[0] + math.cos(ang0) * r * 2.05, base[1] + math.sin(ang0) * r * 2.05)
        sh_start = (base[0] - math.cos(ang0) * r * 0.85, base[1] - math.sin(ang0) * r * 0.85)
        pygame.draw.line(surf, OUTLINE, sh_start, sh_end, max(6, int(r * 0.15)))
        pygame.draw.line(surf, (62, 50, 46), sh_start, sh_end, max(4, int(r * 0.10)))
        blade = pygame.Rect(0, 0, int(r * 1.9), int(r * 1.9))
        blade.center = (int(sh_end[0] - math.cos(ang0) * r * 0.66),
                        int(sh_end[1] - math.sin(ang0) * r * 0.66))
        pygame.draw.arc(surf, OUTLINE, blade.inflate(8, 8), ang0 - 0.25, ang0 + math.pi * 0.70, 8)
        pygame.draw.arc(surf, (228, 238, 246), blade, ang0 - 0.25, ang0 + math.pi * 0.70, 4)
        add_glow(surf, sh_end[0], sh_end[1], r * 0.55, lite, 0.45)

        # ---- pelerin: omuzdan aşağı açılan, etekleri şerit şerit yırtık ----
        cloak = [P(0.34, 0.54), P(0.10, 0.92)]
        for i in range(9):
            k = i / 8.0
            wob = math.sin(t * 4.2 + i * 1.35) * 0.16
            depth = -1.10 - 0.45 * math.sin(k * math.pi) - (0.22 if i % 2 else 0.0)
            cloak.append(P(depth, (0.5 - k) * 2.05 + wob))
        cloak += [P(0.10, -0.92), P(0.34, -0.54)]
        self._poly(surf, cloak, col, x, y, grow=0.05)
        pygame.draw.polygon(surf, dark, cloak, 2)

        # ---- iskelet eller (tırpanı kavrar) ----
        for grip_f, grip_s in ((0.16, 0.62), (-0.10, 0.34)):
            gx, gy = P(grip_f, grip_s)
            pygame.draw.circle(surf, OUTLINE, (int(gx), int(gy)), max(3, int(r * 0.16)))
            pygame.draw.circle(surf, (228, 232, 226), (int(gx), int(gy)), max(2, int(r * 0.12)))

        # ---- kukuleta: derin, içi boş ----
        hood = [P(0.86, 0.0), P(0.58, 0.46), P(-0.06, 0.54),
                P(-0.30, 0.0), P(-0.06, -0.54), P(0.58, -0.46)]
        self._poly(surf, hood, dark, x, y, grow=0.05)
        pygame.draw.polygon(surf, scale_col(dark, 0.7), hood, 2)
        inner = [P(0.64, 0.0), P(0.42, 0.28), P(0.02, 0.30),
                 P(-0.08, 0.0), P(0.02, -0.30), P(0.42, -0.28)]
        pygame.draw.polygon(surf, (9, 13, 15), inner)
        self._boss_eyes(surf, P, r, t, n=2, spread=0.12, fwd=0.34, sz=0.08,
                        col=(226, 255, 250), glow=lite)

    # ---- kovan ana ----
    def _draw_hive(self, surf, x, y, r, col, t):
        """Kovan anası: titreyen dört kanat, bölmeli karın, zehir iğnesi, altı eklemli bacak ve çeneli kafa."""
        P, fx_, fy_, sx_, sy_ = self._mapper(x, y, r)
        dark = scale_col(col, 0.58)
        lite = lighten(col, 0.30)
        venom = (172, 232, 92)

        # ---- bacaklar (altı adet, iki eklemli) ----
        for sgn in (-1, 1):
            for i in range(3):
                root_f = 0.34 - i * 0.34
                sw = math.sin(self.gait * 1.7 + i * 1.2 + (0 if sgn > 0 else 1.7)) * 0.16
                a = P(root_f, 0.52 * sgn)
                b = P(root_f + 0.24 + sw, 1.12 * sgn)
                c = P(root_f - 0.18 + sw, 1.60 * sgn)
                self._limb(surf, [a, b, c], dark, max(3, int(r * 0.09)))

        # ---- kanatlar: ince, uzun, yarı saydam (çırpınca bulanıklaşır) ----
        flap = 0.16 * math.sin(t * 18)
        pad = int(r * 3.2)
        wsurf = pygame.Surface((pad * 2, pad * 2), pygame.SRCALPHA)
        wcx, wcy = pad, pad

        def W(f, s):
            return (wcx + fx_ * r * f + sx_ * r * s, wcy + fy_ * r * f + sy_ * r * s)

        for sgn in (-1, 1):
            for j, (reach, back, alpha) in enumerate(((1.95, -1.35, 78), (1.55, -2.05, 62))):
                tipo = flap * (1 if j == 0 else -1)
                wing = [W(-0.15, 0.30 * sgn),
                        W(0.25 + tipo, (reach * 0.55) * sgn),
                        W(back * 0.42 + tipo, reach * sgn),
                        W(back, (reach * 0.42) * sgn)]
                pygame.draw.polygon(wsurf, (226, 240, 255, alpha), wing)
                pygame.draw.polygon(wsurf, (255, 255, 255, alpha + 50), wing, 1)
                pygame.draw.line(wsurf, (255, 255, 255, alpha + 40),
                                 W(-0.10, 0.30 * sgn), W(back * 0.42 + tipo, reach * sgn), 1)
        surf.blit(wsurf, (int(x - pad), int(y - pad)))

        # ---- karın: arkaya doğru küçülen bölmeler + zehir iğnesi ----
        for i in range(3):
            k = 1.0 - i * 0.20
            ax, ay = P(-0.78 - i * 0.56, 0.0)
            pygame.draw.circle(surf, OUTLINE, (int(ax), int(ay)), int(r * 0.62 * k + 2))
            pygame.draw.circle(surf, dark if i % 2 else col, (int(ax), int(ay)), int(r * 0.62 * k))
            pygame.draw.circle(surf, scale_col(col, 0.75), (int(ax), int(ay)), int(r * 0.62 * k), 2)
        sting = [P(-1.92, 0.20), P(-2.52, 0.0), P(-1.92, -0.20)]
        self._poly(surf, sting, venom, x, y, grow=0.03)
        add_glow(surf, *P(-2.45, 0.0), r * 0.40, venom, 0.5)

        # ---- göğüs ----
        pygame.draw.circle(surf, OUTLINE, (int(x), int(y)), int(r * 0.80))
        pygame.draw.circle(surf, col, (int(x), int(y)), int(r * 0.74))
        pygame.draw.circle(surf, lite, [int(v) for v in P(-0.16, 0.0)], int(r * 0.34))

        # ---- kafa + çeneler ----
        hx, hy = P(0.94, 0.0)
        pygame.draw.circle(surf, OUTLINE, (int(hx), int(hy)), int(r * 0.44))
        pygame.draw.circle(surf, dark, (int(hx), int(hy)), int(r * 0.38))
        chomp = 0.5 + 0.5 * math.sin(t * 6)
        for sgn in (-1, 1):
            m0 = P(1.18, 0.24 * sgn)
            m1 = P(1.62, (0.10 + 0.26 * chomp) * sgn)
            pygame.draw.line(surf, OUTLINE, m0, m1, max(4, int(r * 0.13)))
            pygame.draw.line(surf, (240, 230, 204), m0, m1, max(2, int(r * 0.08)))
        # duyargalar
        for sgn in (-1, 1):
            self._limb(surf, [P(1.10, 0.20 * sgn), P(1.50, 0.62 * sgn), P(1.40, 1.02 * sgn)],
                       (60, 48, 30), 3, outline=False)
        self._boss_eyes(surf, P, r, t, n=2, spread=0.15, fwd=1.02, sz=0.10,
                        col=(255, 252, 220), glow=venom)

        # ---- çevresinde dolanan yavrular ----
        for i in range(4):
            a = t * 2.0 + i * math.tau / 4
            lx = x + math.cos(a) * r * 1.80
            ly = y + math.sin(a) * r * 1.80 * 0.72
            pygame.draw.circle(surf, OUTLINE, (int(lx), int(ly)), 6)
            pygame.draw.circle(surf, lite, (int(lx), int(ly)), 4)

    # ---- ejderha ----
    def _draw_dragon(self, surf, x, y, r, col, t):
        """Cehennem ejderhası: kıvrılan dikenli kuyruk, zarlı iki kanat, uzun boyun, dişli çene ve ağzında biriken alev."""
        flying = self.fly_t > 0
        lift = (r * 0.55 if flying else 0.0) + math.sin(t * 2.6) * r * (0.16 if flying else 0.07)
        y = y - lift
        P, fx_, fy_, sx_, sy_ = self._mapper(x, y, r)
        dark = scale_col(col, 0.55)
        lite = lighten(col, 0.28)
        belly = (240, 192, 122)
        fire = (255, 150, 55)

        # ---- kuyruk: arkaya kıvrılan, ucunda ok başı ----
        tail = []
        for i in range(6):
            k = i / 5.0
            curl = math.sin(t * 2.0 + i * 0.85) * 0.34 * k
            tail.append(P(-0.70 - k * 2.20, curl))
        self._limb(surf, tail, col, max(5, int(r * 0.20)))
        td = (tail[-1][0] - tail[-2][0], tail[-1][1] - tail[-2][1])
        tl = math.hypot(*td) or 1.0
        td = (td[0] / tl, td[1] / tl)
        self._poly(surf, [(tail[-1][0] + td[0] * r * 0.50, tail[-1][1] + td[1] * r * 0.50),
                          (tail[-1][0] - td[1] * r * 0.30, tail[-1][1] + td[0] * r * 0.30),
                          (tail[-1][0] + td[1] * r * 0.30, tail[-1][1] - td[0] * r * 0.30)],
                   dark, x, y, grow=0.03)

        # ---- kanatlar: kemikli, tırtıklı zar ----
        flap = (0.86 if flying else 0.58) + 0.22 * math.sin(t * (7.0 if flying else 3.2))
        for sgn in (-1, 1):
            sh = P(-0.10, 0.36 * sgn)
            elbow = P(0.46, (1.06 * flap + 0.30) * sgn)
            tip = P(-0.20, (2.30 * flap + 0.45) * sgn)
            n1 = P(-0.72, (1.78 * flap + 0.32) * sgn)
            n2 = P(-1.02, (1.20 * flap + 0.26) * sgn)
            n3 = P(-1.14, (0.56 * flap + 0.20) * sgn)
            memb = [sh, elbow, tip,
                    P(-0.52, (2.00 * flap + 0.36) * sgn), n1,
                    P(-0.92, (1.46 * flap + 0.28) * sgn), n2,
                    P(-1.18, (0.86 * flap + 0.22) * sgn), n3]
            self._poly(surf, memb, scale_col(col, 0.70), x, y, grow=0.035)
            pygame.draw.polygon(surf, dark, memb, 2)
            for f in (elbow, tip, n1, n2, n3):
                pygame.draw.line(surf, lighten(dark, 0.30), sh, f, max(2, int(r * 0.06)))

        # ---- gövde ----
        body = [P(0.90, 0.0), P(0.60, 0.56), P(-0.10, 0.74),
                P(-0.84, 0.44), P(-0.84, -0.44), P(-0.10, -0.74), P(0.60, -0.56)]
        self._poly(surf, body, col, x, y, grow=0.08)
        pygame.draw.polygon(surf, dark, body, 2)
        # karın pulları
        for i in range(4):
            f = 0.50 - i * 0.32
            w = 0.46 - i * 0.05
            pygame.draw.line(surf, belly, P(f, -w), P(f, w), max(2, int(r * 0.08)))
        # sırt dikenleri
        for i in range(4):
            b_f = -0.15 - i * 0.40
            self._poly(surf, [P(b_f, 0.16), P(b_f - 0.38, 0.0), P(b_f, -0.16)],
                       (250, 228, 192), x, y, grow=0.03)

        # ---- arka pençeler ----
        for sgn in (-1, 1):
            self._limb(surf, [P(-0.40, 0.60 * sgn), P(-0.78, 0.96 * sgn)],
                       dark, max(3, int(r * 0.12)))
            for k in (-1, 0, 1):
                pygame.draw.line(surf, (248, 240, 224), P(-0.78, 0.96 * sgn),
                                 P(-1.02 + k * 0.10, (1.16 + abs(k) * 0.04) * sgn), 2)

        # ---- boyun + kafa ----
        neck = [P(0.60, 0.0), P(1.05, 0.0), P(1.45, 0.0)]
        self._limb(surf, neck, col, max(6, int(r * 0.28)))
        hx, hy = P(1.72, 0.0)
        head = [P(2.22, 0.0), P(1.86, 0.30), P(1.40, 0.34), P(1.30, 0.0),
                P(1.40, -0.34), P(1.86, -0.30)]
        self._poly(surf, head, lighten(col, 0.08), x, y, grow=0.05)
        pygame.draw.polygon(surf, dark, head, 2)
        # boynuzlar
        for sgn in (-1, 1):
            self._limb(surf, [P(1.42, 0.26 * sgn), P(1.02, 0.56 * sgn), P(0.72, 0.52 * sgn)],
                       (242, 230, 208), max(3, int(r * 0.10)))
        # çene + dişler
        jaw = 0.12 + 0.12 * (0.5 + 0.5 * math.sin(t * 3.2))
        self._poly(surf, [P(2.20, 0.0), P(1.82, 0.22), P(1.76, 0.0), P(1.82, -0.22)],
                   (42, 14, 12), x, y, grow=0.0, outline=False)
        for k in (-1, 1):
            pygame.draw.line(surf, (255, 250, 240), P(1.92, 0.16 * k), P(2.16, 0.06 * k), 2)
        pygame.draw.line(surf, (255, 250, 240), P(1.90, 0.0), P(2.14 + jaw, 0.0), 2)
        # ağızda biriken alev
        glow_k = 0.45 + 0.35 * math.sin(t * 5)
        if self.telegraph and self.telegraph[0] == "breath":
            glow_k = 1.0
        mx_, my_ = P(2.20, 0.0)
        add_glow(surf, mx_, my_, r * (0.45 + 0.50 * glow_k), fire, 0.30 + 0.50 * glow_k)
        for i in range(3):
            ph = (t * 1.6 + i * 0.33) % 1.0
            ex_, ey_ = P(2.20 + ph * 0.55, random.uniform(-0.10, 0.10))
            blit_disc(surf, ex_, ey_ - ph * r * 0.45, max(1.0, 4.0 * (1 - ph)),
                      (255, 205, 110), int(200 * (1 - ph)))
        self._boss_eyes(surf, P, r, t, n=2, spread=0.14, fwd=1.66, sz=0.09,
                        col=(255, 248, 214), glow=(255, 170, 60))

    def _draw_skill_marks(self, surf, t):
        """Kök tuzakları ve ışınlanma izi (zemine düşer)."""
        for sx0, sy0, rem in getattr(self, "snares", ()):
            k = 1.0 - clamp(rem / SNARE_DELAY, 0.0, 1.0)
            blit_disc(surf, sx0, sy0, SNARE_R * (0.35 + 0.65 * k), (90, 170, 60), 60)
            pulse = 0.6 + 0.4 * math.sin(t * 18)
            ring_aa(surf, sx0, sy0, SNARE_R, scale_col((170, 240, 110), pulse), 2)
            for i in range(6):
                a = i * math.tau / 6 + t * 0.8
                r0, r1 = SNARE_R * 0.95, SNARE_R * (0.95 - 0.55 * k)
                pygame.draw.line(surf, (70, 130, 40),
                                 (sx0 + math.cos(a) * r0, sy0 + math.sin(a) * r0),
                                 (sx0 + math.cos(a + 0.5) * r1, sy0 + math.sin(a + 0.5) * r1), 4)
        bf = getattr(self, "blink_fx", None)
        if bf is not None:
            bx_, by_, bt_ = bf
            k = clamp(bt_ / 0.5, 0.0, 1.0)
            blit_disc(surf, bx_, by_, self.radius * (1.0 + (1 - k) * 0.6), self.color, int(110 * k))
            ring_aa(surf, bx_, by_, self.radius * (1.2 + (1 - k)), lighten(self.color, 0.4), 2)

    def _draw_telegraph(self, surf, t, x, y, r):
        """Saldırı uyarıları - zemine düşer (2.5D / 3D zemin katmanı da bunu çağırır)."""
        self._draw_skill_marks(surf, t)
        if not self.telegraph:
            return
        kind, a, b, c, timer, total = self.telegraph
        k = 1 - clamp(timer / total, 0, 1)
        if kind == "beam":
            angs = a if isinstance(a, (list, tuple)) else [a]
            alpha = int(120 + 100 * math.sin(k * 20))
            s = _TgLayer(x, y)
            for ang in angs:
                ex, ey = x + math.cos(ang) * 900, y + math.sin(ang) * 900
                s.line((255, 80, 70, alpha), (x, y), (ex, ey), 5)
            s.blit_to(surf)
        elif kind == "hazard_ring":
            n = 11 if self.enraged else 8
            tc = Hazard.TRAIT_COLORS.get(self.trait["kind"], (255, 70, 60))
            for i in range(n):
                ang = i * math.tau / n
                hx, hy = x + math.cos(ang) * 150, y + math.sin(ang) * 150
                hx = clamp(hx, ARENA_RECT.left + 20, ARENA_RECT.right - 20)
                hy = clamp(hy, ARENA_RECT.top + 20, ARENA_RECT.bottom - 20)
                blit_disc(surf, hx, hy, 30 * k, tc, 90)
        elif kind in ("slam", "scythe"):
            # Alan işareti, patronun imza rengini taşısın: yerdeki tuzakla
            # (Hazard) aynı renk olsun ki neyin geleceği belli olsun.
            tc = Hazard.TRAIT_COLORS.get(self.trait["kind"], (255, 70, 60))
            blit_disc(surf, a, b, c * k, tc, 80)
            pygame.draw.circle(surf, lighten(tc, 0.3), (int(a), int(b)), int(c * k), 2)
        elif kind == "spore":
            for i in range(6 if self.enraged else 4):
                ang = i * math.tau / (6 if self.enraged else 4)
                hx = clamp(a + math.cos(ang) * 90, ARENA_RECT.left + 20, ARENA_RECT.right - 20)
                hy = clamp(b + math.sin(ang) * 90, ARENA_RECT.top + 20, ARENA_RECT.bottom - 20)
                blit_disc(surf, hx, hy, 28 * k, (230, 190, 70), 85)
        elif kind == "barrage":
            n = 7 + self.boss_index * 2 + (3 if self.enraged else 0)
            col = (210, 120, 250) if self.kind == "witch" else (245, 205, 90)
            s = _TgLayer(x, y)
            for i in range(n):
                ang = a + (i - (n - 1) / 2) * (0.62 / max(1, n - 1))
                ex, ey = x + math.cos(ang) * 900, y + math.sin(ang) * 900
                s.line((*col, int(45 + 95 * k)), (x, y), (ex, ey), 3)
            s.blit_to(surf)
            add_glow(surf, x, y, 40 + 34 * k, col, 0.35 + 0.35 * k)
        elif kind == "ring_player":
            # oyuncunun çevresine kapanan lanet çemberi
            n = self._ring_count()
            pygame.draw.circle(surf, (210, 120, 250), (int(a), int(b)), int(c), 2)
            for i in range(n):
                ang = i * math.tau / n
                hx = clamp(a + math.cos(ang) * c, ARENA_RECT.left + 20, ARENA_RECT.right - 20)
                hy = clamp(b + math.sin(ang) * c, ARENA_RECT.top + 20, ARENA_RECT.bottom - 20)
                blit_disc(surf, hx, hy, BOSS_RING_HAZARD_R * 0.56 * k, (230, 90, 220), 92)
            pygame.draw.circle(surf, (255, 170, 255), (int(a), int(b)), max(2, int(6 * k)))
        elif kind == "breath":
            # alev koridoru: patrondan ileri uzanan turuncu huni
            s = _TgLayer(x, y)
            spread = 0.30
            for sgn in (-1, 1):
                ang = a + spread * sgn
                ex, ey = x + math.cos(ang) * 900, y + math.sin(ang) * 900
                s.line((255, 150, 60, int(70 + 110 * k)), (x, y), (ex, ey), 4)
            ex, ey = x + math.cos(a) * 900, y + math.sin(a) * 900
            s.polygon((255, 110, 40, int(30 + 60 * k)), [
                (x, y),
                (x + math.cos(a - spread) * 900, y + math.sin(a - spread) * 900),
                (x + math.cos(a + spread) * 900, y + math.sin(a + spread) * 900)])
            s.blit_to(surf)
            add_glow(surf, x + math.cos(a) * r * 0.9, y + math.sin(a) * r * 0.9,
                     26 + 34 * k, (255, 180, 80), 0.4 + 0.4 * k)
        elif kind == "firewall":
            # alev duvarı: hedefin üstünden geçen dik perde
            nx, ny = -math.sin(c), math.cos(c)
            n = 7 + self.boss_index
            for i in range(n):
                off = (i - (n - 1) / 2) * 88
                hx = clamp(a + nx * off, ARENA_RECT.left + 20, ARENA_RECT.right - 20)
                hy = clamp(b + ny * off, ARENA_RECT.top + 20, ARENA_RECT.bottom - 20)
                blit_disc(surf, hx, hy, 30 * k, (255, 130, 50), 95)
        elif kind == "wingburst":
            pygame.draw.circle(surf, (255, 170, 70), (int(a), int(b)), int(c * k), 3)
            for i in range(12):
                ang = i * math.tau / 12
                blit_disc(surf, a + math.cos(ang) * c * k, b + math.sin(ang) * c * k,
                          7, (255, 190, 90), 130)
        elif kind == "lunge":
            # atılış hattı: patrondan hedefe uzanan dar koridor + ok ucu
            tc = self.trait["color"]
            ang = math.atan2(b - y, a - x)
            nx, ny = -math.sin(ang), math.cos(ang)
            w2 = self.radius * 0.72
            ls = _TgLayer(x, y)
            ls.polygon((*tc, int(50 + 80 * k)), [
                (x + nx * w2, y + ny * w2), (a + nx * w2, b + ny * w2),
                (a - nx * w2, b - ny * w2), (x - nx * w2, y - ny * w2)])
            ls.blit_to(surf)
            pygame.draw.polygon(surf, lighten(tc, 0.3), [
                (a + math.cos(ang) * 26, b + math.sin(ang) * 26),
                (a + nx * 16, b + ny * 16), (a - nx * 16, b - ny * 16)])
        elif kind == "wall":
            # duvar: (a,b) noktasından geçen, c açısına dik tuzak dizisi
            tc = self.trait["color"]
            nx, ny = -math.sin(c), math.cos(c)
            n = 9 + self.boss_index
            for i in range(n):
                off = (i - (n - 1) / 2) * 76
                hx = clamp(a + nx * off, ARENA_RECT.left + 20, ARENA_RECT.right - 20)
                hy = clamp(b + ny * off, ARENA_RECT.top + 20, ARENA_RECT.bottom - 20)
                blit_disc(surf, hx, hy, 30 * k, tc, 95)
            pygame.draw.line(surf, lighten(tc, 0.25),
                             (a + nx * 360, b + ny * 360), (a - nx * 360, b - ny * 360), 2)
        elif kind == "cage":
            # kafes: oyuncunun çevresine kapanan halka
            tc = self.trait["color"]
            n = self._ring_count()
            pygame.draw.circle(surf, tc, (int(a), int(b)), int(c), 2)
            for i in range(n):
                ang = i * math.tau / n
                hx = clamp(a + math.cos(ang) * c, ARENA_RECT.left + 20, ARENA_RECT.right - 20)
                hy = clamp(b + math.sin(ang) * c, ARENA_RECT.top + 20, ARENA_RECT.bottom - 20)
                blit_disc(surf, hx, hy, BOSS_RING_HAZARD_R * 0.56 * k, tc, 95)
        elif kind == "meteor":
            # yağmur: hedefin çevresinde büyüyen uyarı halkası
            tc = self.trait["color"]
            pygame.draw.circle(surf, tc, (int(a), int(b)), int(210 * k), 2)
            for i in range(8):
                ang = i * math.tau / 8 + k * 2.0
                blit_disc(surf, a + math.cos(ang) * 210 * k, b + math.sin(ang) * 210 * k,
                          8, lighten(tc, 0.3), 140)
        elif kind == "pull":
            # çekim: patrona doğru kapanan halkalar
            for i in range(3):
                rr = 420 * (1.0 - ((k + i * 0.33) % 1.0))
                pygame.draw.circle(surf, (200, 130, 255), (int(x), int(y)), int(rr), 2)
            add_glow(surf, x, y, 60 + 40 * k, (200, 130, 255), 0.35 + 0.35 * k)
        elif kind == "charge":
            # hücum hattı: patrondan hedefe uzanan geniş kırmızı koridor
            ang = math.atan2(b - y, a - x)
            ex, ey = x + math.cos(ang) * 900, y + math.sin(ang) * 900
            nx, ny = -math.sin(ang), math.cos(ang)
            w2 = self.radius * 1.05
            s = _TgLayer(x, y)
            s.polygon((255, 90, 60, int(60 + 70 * k)), [
                (x + nx * w2, y + ny * w2), (ex + nx * w2, ey + ny * w2),
                (ex - nx * w2, ey - ny * w2), (x - nx * w2, y - ny * w2)])
            s.blit_to(surf)
            for i in range(3):
                fx_ = x + math.cos(ang) * (60 + i * 46) * (0.5 + k)
                fy_ = y + math.sin(ang) * (60 + i * 46) * (0.5 + k)
                pygame.draw.circle(surf, (255, 150, 90), (int(fx_), int(fy_)), max(2, int(5 * k)), 2)


    def draw(self, surf, t, hud=True, layer="all"):
        """hud=False: can çubuğu / ad yazısı yok (harita seçimindeki portre). layer"""
        scale = ease_out_cubic(self.spawn_t / 0.6) if self.spawn_t < 0.6 else 1.0
        r = self.radius * scale
        x, y = self.x, self.y
        col = WHITE if self.hit_flash > 0 else self.color
        hidden = self.is_hidden()
        if layer == "ground":
            self._draw_telegraph(surf, t, x, y, r)
            return
        # gölge perdesi açıkken gölge, ışıma ve alev çemberi de kaybolur -
        # yoksa "görünmez" patron ışıldayan bir hedef tahtası olurdu.
        if not hidden:
            surf.blit(shadow_sprite(int(r * 2.4)), (int(x - r * 1.2), int(y + r * 0.6)))
            add_glow(surf, x, y, r * 2.2, self.color, 0.4 + 0.15 * math.sin(t * 3))
        if self.enraged and not hidden:
            add_glow(surf, x, y, r * 1.6, (255, 70, 50), 0.35)
        if self.buff_t > 0 and not hidden:
            # savaş çığlığı: gövdeyi saran turuncu güç halkası
            add_glow(surf, x, y, r * 2.4, (255, 170, 70), 0.30 + 0.12 * math.sin(t * 8))
            pygame.draw.circle(surf, (255, 190, 90), (int(x), int(y)),
                               int(r * 1.32 + 3 * math.sin(t * 8)), 2)
        if self.hunt_t > 0 and not hidden:
            # avlanma: arkasında bıraktığı hız izi
            fxh, fyh, _, _ = self._facing()
            for i in range(3):
                blit_disc(surf, x - fxh * r * (0.7 + i * 0.5), y - fyh * r * (0.7 + i * 0.5),
                          r * (0.55 - i * 0.13), self.trait["color"], 70 - i * 18)
        if getattr(self, "hellish", False) and not hidden:
            # ayağının dibinde dönen alev çemberi + yukarı süzülen korlar
            add_glow(surf, x, y, r * 3.0, (255, 130, 50), 0.22 + 0.08 * math.sin(t * 2.4))
            ring = pygame.Rect(0, 0, int(r * 2.9), int(r * 1.5))
            ring.center = (int(x), int(y + r * 0.55))
            pygame.draw.ellipse(surf, (255, 140, 60), ring, 3)
            for i in range(9):
                a = t * 1.3 + i * math.tau / 9
                fx0 = x + math.cos(a) * r * 1.45
                fy0 = y + r * 0.55 + math.sin(a) * r * 0.75
                blit_disc(surf, fx0, fy0, 3.4, (255, 190, 90), 190)
            for i in range(6):
                ph = (t * 0.7 + i * 0.17) % 1.0
                ex = x + math.sin(t * 1.6 + i * 2.1) * r * 1.0
                ey = y - r * 0.4 - ph * r * 2.2
                blit_disc(surf, ex, ey, max(1.0, 3.6 * (1.0 - ph)), (255, 170, 70),
                          int(210 * (1.0 - ph)))

        if self.theme and not hidden:
            self._draw_map_aura(surf, x, y, r, t)

        # ---- gövde ----
        # Her patronun kendi çizimi var. gölge perdesi açıkken gövde hiç
        # çizilmez; yalnızca havadaki titreşim ve puslu gözler görünür.
        if hidden:
            self._draw_vanished(surf, x, y, r, t)
        else:
            drawer = {
                "warlord": self._draw_warlord,
                "witch": self._draw_witch,
                "colossus": self._draw_colossus,
                "reaper": self._draw_reaper,
                "hive": self._draw_hive,
                "dragon": self._draw_dragon,
            }.get(self.kind, self._draw_warlord)
            art = MAP_BOSS_ART.get((self.theme, self.kind)) if self.theme else None
            if art:
                # harita patronunun kendi gövdesi (taç gövdenin parçası)
                getattr(self, art)(surf, x, y, r, col, t)
            else:
                if self.hellish:
                    self._draw_hell_back(surf, x, y, r, t)
                drawer(surf, x, y, r, col, t)
                if self.hellish:
                    self._draw_hell_front(surf, x, y, r, t)
                elif self.theme:
                    self._draw_map_regalia(surf, x, y, r, t)
        if getattr(self, "aegis_hp", 0.0) > 0 and not hidden:
            # bariyer: dönen altıgen kalkan + doluluk yayı
            frac = clamp(self.aegis_hp / max(1.0, self.aegis_max), 0.0, 1.0)
            rr = r * 1.45 + 2 * math.sin(t * 6)
            add_glow(surf, x, y, rr * 1.1, AEGIS_COLOR, 0.22 + 0.25 * frac)
            blit_disc(surf, x, y, rr, AEGIS_COLOR, int(28 + 40 * frac))
            pts = [(x + math.cos(t * 0.9 + i * math.tau / 6) * rr,
                    y + math.sin(t * 0.9 + i * math.tau / 6) * rr) for i in range(6)]
            pygame.draw.polygon(surf, lighten(AEGIS_COLOR, 0.3), [(int(px_), int(py_)) for px_, py_ in pts], 3)
            arc = pygame.Rect(0, 0, int(rr * 2 + 12), int(rr * 2 + 12))
            arc.center = (int(x), int(y))
            if frac > 0.01:
                pygame.draw.arc(surf, WHITE, arc, math.pi / 2, math.pi / 2 + math.tau * frac, 3)
        if getattr(self, "spiral_t", 0.0) > 0 and getattr(self, "spiral_delay", 0.0) > 0 and not hidden:
            add_glow(surf, x, y, r * 2.0, (255, 110, 150), 0.5)
        if getattr(self, "ward_t", 0.0) > 0 and not hidden:
            # dokunulmazlık: altın küre + dönen mühür halkası
            k = clamp(self.ward_t / WARD_TIME, 0.0, 1.0)
            rr = r * 1.55 + 3 * math.sin(t * 9)
            add_glow(surf, x, y, rr * 1.2, WARD_COLOR, 0.30 + 0.20 * k)
            blit_disc(surf, x, y, rr, WARD_COLOR, 46)
            ring_aa(surf, x, y, rr, (255, 240, 180), 3)
            for i in range(8):
                a = t * 2.2 + i * math.tau / 8
                px_, py_ = x + math.cos(a) * rr, y + math.sin(a) * rr
                pygame.draw.polygon(surf, (255, 250, 220), [
                    (px_ + math.cos(a) * 7, py_ + math.sin(a) * 7),
                    (px_ - math.sin(a) * 4, py_ + math.cos(a) * 4),
                    (px_ - math.cos(a) * 7, py_ - math.sin(a) * 7),
                    (px_ + math.sin(a) * 4, py_ - math.cos(a) * 4)])
            arc = pygame.Rect(0, 0, int(rr * 2 + 14), int(rr * 2 + 14))
            arc.center = (int(x), int(y))
            pygame.draw.arc(surf, WHITE, arc, math.pi / 2, math.pi / 2 + math.tau * k, 3)
        if getattr(self, "drain_t", 0.0) > 0:
            # can emme bağı: patrondan oyuncuya titreyen kızıl bağ
            tx_, ty_ = self.drain_px, self.drain_py
            segs = 14
            pts = []
            for i in range(segs + 1):
                k = i / segs
                ox = math.sin(t * 22 + i * 1.3) * 7 * math.sin(k * math.pi)
                nx_, ny_ = -(ty_ - y), (tx_ - x)
                nl = math.hypot(nx_, ny_) or 1.0
                pts.append((x + (tx_ - x) * k + nx_ / nl * ox, y + (ty_ - y) * k + ny_ / nl * ox))
            pygame.draw.lines(surf, (90, 0, 20), False, pts, 7)
            pygame.draw.lines(surf, DRAIN_COLOR, False, pts, 4)
            pygame.draw.lines(surf, (255, 170, 180), False, pts, 1)
            for i in range(4):
                k = (t * 1.6 + i / 4.0) % 1.0          # oyuncudan patrona akan kan damlaları
                blit_disc(surf, tx_ + (x - tx_) * k, ty_ + (y - ty_) * k, 4.0, (255, 90, 110), 230)
            add_glow(surf, tx_, ty_, 46, DRAIN_COLOR, 0.35)

        if layer != "body":
            self._draw_telegraph(surf, t, x, y, r)

        if not hud:
            return
        # HP bar (üst, isim + imza özelliği + zırh + dövüş süresi ile)
        w = 340
        bx, by = x - w / 2, y - r - 30
        if self.is_hidden():
            # gölge perdesi: can çubuğu da kaybolur, yalnızca soluk bir iz
            # kalır.
            hint = pygame.Surface((int(w), 10), pygame.SRCALPHA)
            pygame.draw.rect(hint, (120, 90, 160, 60), hint.get_rect(), border_radius=5)
            surf.blit(hint, (int(bx), int(by)))
            draw_text(surf, L("ui.invisible"), (x, by - 13), 14, (200, 150, 255), bold=True,
                      center=True)
            return
        draw_bar(surf, (bx, by, w, 10), self.hp / self.max_hp, (220, 70, 70))
        # can çaldığında çubuğun üstünde yeşil bir parıltı belirir
        if self.heal_flash > 0:
            k = clamp(self.heal_flash / 0.45, 0, 1)
            gs = pygame.Surface((int(w), 10), pygame.SRCALPHA)
            pygame.draw.rect(gs, (90, 230, 140, int(120 * k)), gs.get_rect(), border_radius=5)
            surf.blit(gs, (int(bx), int(by)))
            draw_text(surf, L("ui.lifesteal_pop"), (bx + w + 6, by + 12), 10, (120, 230, 160),
                      bold=True, shadow=False)
        label = self.name
        if self.desperate:
            label += "  -  ÇARESİZ"
        elif self.enraged:
            label += "  -  ÖFKELİ"
        # Oyuncu patronun ne yaptığını bir bakışta görsün.
        if self.hunt_t > 0:
            label += "  -  AVLANIYOR"
        if self.buff_t > 0:
            label += "  -  GÜÇLENDİ"
        if getattr(self, "ward_t", 0.0) > 0:
            label += "  -  DOKUNULMAZ"
        draw_text(surf, label, (x, by - 13), 14, GOLD, bold=True, center=True)
        # İmza özelliği rozeti: oyuncu neyle karşı karşıya olduğunu bilsin.
        tr = self.trait
        draw_text(surf, tr["label"], (x, by - 28), 11, tr["color"], bold=True,
                  center=True, shadow=False)
        draw_text(surf, fmt_time(self.fight_time), (bx - 6, by - 4), 11, TEXT_DIM,
                  bold=True, shadow=False, right=True)
        if self.armor > 0.005:
            draw_text(surf, f"ZIRH %{int(self.armor * 100)}", (bx + w + 6, by - 2), 11,
                      (170, 190, 220), bold=True, shadow=False)
        wd = getattr(self, "wound", 0.0) or 0.0
        if wd > 0.005:
            draw_text(surf, L("ui.boss_wound", int(round(wd * 100))), (x, by + 18), 11,
                      (255, 120, 120), bold=True, center=True, shadow=False)


def scale_bosses_to_player(bosses, player):
    """Dalgadaki tüm patronların toplam canını oyuncunun gücüne göre ölçekler."""
    if not bosses:
        return 1.0
    try:
        est = player.estimated_dps()
    except Exception:
        return 1.0
    n = len(bosses)
    base_total = sum(b.max_hp for b in bosses)
    # Hedeflenen toplam can, patron canı bonusuyla birlikte ölçeklenir:
    # "patronlara %20 daha fazla can" sözü, canı oyuncunun gücüne göre yeniden
    # kuran bu ölçekten sonra da geçerli kalsın.
    want = est * BOSS_FIGHT_UPTIME * BOSS_FIGHT_TARGET * BOSS_HP_BONUS
    # Süre = ham_can / (dps * (1 - zırh)) olduğundan, sürenin sabit kalması
    # için ham_can ∝ (1 - zırh).
    arm = sum(getattr(b, "armor", 0.0) for b in bosses) / max(1, n)
    want *= max(0.40, 1.0 - arm)
    # Ölçüm: tek patronlu 15. dalgada toplam 10.744, iki patronlu 20. dalgada
    # da 10.744 - yani iki patron tek patrondan kolaydı.
    if n > 1:
        want *= MULTI_BOSS_TOTAL
    # şampiyon: tek patron, eski 2 (3) patronun toplam canı kadar
    champ = max([int(getattr(b, "champion", 1)) for b in bosses] or [1])
    if n == 1 and champ > 1:
        want *= MULTI_BOSS_TOTAL * (1.0 + 0.35 * (champ - 2))
    scale = clamp(want / max(1.0, base_total), BOSS_HP_SCALE_MIN, BOSS_HP_SCALE_MAX)
    # Can çalma tavanı oyuncunun hasarına göre paylaştırılır: dalgadaki tüm
    # patronların toplam iyileşmesi, oyuncunun saniyelik hasarının belirli bir
    # oranını aşamaz.
    heal_rate = est * BOSS_LIFESTEAL_VS_DPS / max(1, n)
    # Süre dalgaya ait: her patron payına düşeni alır.
    per = BOSS_MIN_FIGHT_TIME / max(1, n)
    for b in bosses:
        b.max_hp *= scale
        b.hp = b.max_hp
        b.heal_rate = heal_rate
        b.min_fight_time = per
    return scale


# dalga / spawn yöneticisi

# Oyuncu 10 saniyelik yoğunluk penceresinde zaten bolca skor topluyor; bu ek
# olmadan dalgalar art arda atlıyor. Tek yerden ayarlanabilsin diye sabit:
# 10. dalgadan itibaren her dalgaya eklenen sabit "nefes payı" skoru.
WAVE_BREATHER_FROM = 10     # bu dalgadan itibaren uygulanır
WAVE_BREATHER_BASE = 380    # 10. dalgada eklenen skor
WAVE_BREATHER_STEP = 150    # her sonraki dalgada üstüne eklenen skor

# İlk dalgaların skor hedefleri elle belirlenir: oyunun açılışı burada
# şekillendiği için formüle bırakılmaz.
WAVE_GOAL_TABLE = {1: 600, 2: 2300, 3: 2900, 4: 3500, 5: 4100, 6: 4250}
# 6. dalgadan sonrası formülle devam eder; bu çarpan, formülü tablodaki
# değerlerle sürekli (kesintisiz) hâle getirir:
#   Büyütürsen -> dalgalar daha uzun sürer
#   Küçültürsen -> dalgalar daha hızlı geçer
WAVE_GOAL_SCALE = 5.9
# skor kazancı: "skor çok hızlı artıyor, %50 nerf" - 10 puanlık yaratık 5
# verir.
SCORE_GAIN = 0.35               # skor kazancı -%30 (0.5 -> 0.35)
# dalga hedefi: "dalga atlama hedeflerini artır, süre 15 sn olsun; oyuncu
# saniye beklemesin, SKOR bekletsin".
WAVE_GOAL_KILLS = 1.3
WAVE_GOAL_GAIN = SCORE_GAIN * WAVE_GOAL_KILLS


def wave_score_goal(wave, pace=1.0):
    """Bir sonraki dalgaya geçmek için o dalga içinde toplanması gereken skor."""
    w = max(1, int(wave))
    if w in WAVE_GOAL_TABLE:
        return int(WAVE_GOAL_TABLE[w] * WAVE_GOAL_GAIN)
    # Spawn modeliyle aynı kademeler: aynı anda kaç düşman geliyorsa o dalgada
    # toplanabilecek skor da o oranda artar.
    burst = 1 if w < 3 else 2 if w < 6 else 3 if w < 10 else 4 if w < 16 else 5
    goal = (95 + 22 * w) * burst * WAVE_GOAL_SCALE
    # 10. dalgadan sonra ayrıca sabit bir "nefes payı" eklenir.
    if w >= WAVE_BREATHER_FROM:
        goal += WAVE_BREATHER_BASE + (w - WAVE_BREATHER_FROM) * WAVE_BREATHER_STEP
    return int(goal * WAVE_GOAL_GAIN)


# Dalga atlandıktan sonraki "yoğunluk" penceresi: bu süre boyunca düşmanlar
# belirgin biçimde daha sık ve daha kalabalık gelir, sonra tempo normale döner.
SURGE_DURATION = 8.0
SURGE_RATE = 0.62      # spawn aralığı çarpanı (küçük = daha sık)
SURGE_EXTRA = 1        # her spawn'da kaç ek düşman
# Dalga atladıktan sonra yoğunluk penceresinin açılmasını bekleyen sükûnet.
SURGE_CALM = 2.0       # sıradan dalga
SURGE_CALM_BOSS = 3.2  # patron dalgası (kart/market nefesi daha uzun)

# ---- dalga içi hızlanma ----
# Oyun yalnızca dalga atlayınca hızlanmıyor. aynı dalga içinde de zaman
# geçtikçe düşmanlar kademeli olarak daha sık geliyor; böylece bir dalga asla
# "durgunlaşmıyor", baskı sürekli ve hissedilir biçimde artıyor:
#   spawn_aralığı /= 1 + min(WAVE_ACCEL_MAX, dalga_süresi * WAVE_ACCEL_RATE)
WAVE_ACCEL_RATE = 0.030   # saniye başına hızlanma
WAVE_ACCEL_MAX = 1.10     # en fazla 2.1 kat hızlanır
# Dalga uzadıkça her dalgada gelen düşman sayısı da artar (kaç saniyede bir ek
# düşman eklendiği).
WAVE_ACCEL_EXTRA_AFTER = 26.0

# "GİTTİKÇE DÜŞMANLAR BASİTLEŞİYOR". Cehennem temposu arenanın sonundan devam
# eder: cehennem 1 = arena 1 + HELL_TEMPO_OFFSET temposunda doğum.
HELL_TEMPO_OFFSET = 20


def spawn_tempo_wave(wave, biome):
    """Doğum temposunun okunduğu dalga (cehennemde arenadan devam eder)."""
    return int(wave) + (HELL_TEMPO_OFFSET if biome == "hell" else 0)


# Arenada aynı anda yaşayabilecek azami düşman sayısı.
def max_alive_enemies(wave):
    """Aynı anda arenada yaşayabilecek en çok yaratık."""
    # mobil: telefonda tavan 120 - ekranda yine kalabalık, kare hızı akıcı.
    # Mobilin dünya sıralaması ayrı olduğu için skorlar PC ile yarışmaz.
    return int(min(MOBILE_MAX_ALIVE if MOBILE else 175, 70 + wave * 4))


MOBILE_MAX_ALIVE = 120
MOBILE_MAX_TEXTS = 26


# Patron varken yaratık doğumu: normal hızın bu kadarı ve normal kalabalık
# tavanının bu kadarı.
BOSS_SPAWN_RATE = 0.5
BOSS_CROWD_SHARE = 0.5

# İlk dalgalardaki yarasa (mavi, çevik) yoğunluğu freni -
EARLY_BAT_WAVES = 10
EARLY_BAT_NERF = 0.10

# doğum hızı %10 yavaş. "Oyun çok hızlı" geri bildirimi: yaratıklar saniyede
# %10 daha az doğar (doğum aralığı 1/0.90 = %11 uzar).
SPAWN_RATE_TUNE = 0.90

# patron dalgası kilidi açıldı ("afk kalıp seviye kasılıyor").
BOSS_WAVE_TIMEOUT = 30.0

# dalga temposu artık süreye de bağlı ("5 dakikada 17 dalga çok hızlı; 20.
# dalgaya ~12, 25. dalgaya ~15 dakikada gelinsin"):
# 17. dalgaya çok daha güçlü varır. Zayıf oyuncu için hiçbir şey
#   (son dalga, süre sn) - dalga <= son dalga olduğu sürece bu süre geçerli
WAVE_MIN_TIME_BANDS = ((None, 15.0),)
WAVE_MIN_TIME_HELL = 15.0
# Zorluk asgari süreyi değiştirmez: kabusta kalabalık çok daha yoğundur ama
# 20. dalgaya yine ~12 dakikada gelinir (ölçüm: güçlü bot, normal 12.7 dk,
# kabus 11.6 dk). Ayar gerekirse zorluk başına çarpan buradan verilir:
WAVE_MIN_TIME_DIFF = {"normal": 1.0, "hard": 1.0, "nightmare": 1.0}


def wave_min_time(wave, diff="normal", biome="arena"):
    """Bir dalganın skor hedefi dolsa bile sürmesi gereken en kısa süre (sn)."""
    if biome == "hell":
        base = WAVE_MIN_TIME_HELL
    else:
        base = WAVE_MIN_TIME_BANDS[-1][1]
        for cap, secs in WAVE_MIN_TIME_BANDS:
            if cap is None or int(wave) <= cap:
                base = secs
                break
    return base * WAVE_MIN_TIME_DIFF.get(diff, 1.0)


# geç dalga güçlenmesi: "çok güçleniyoruz, düşman göremiyoruz; ilerleyen
# dalgalarda düşmanları hem çoğalt, hem canını, hem hasarını artır".
LATE_BOOST_FROM = 10
LATE_BOOST_HP = 0.045           # dalga başına ek can payı
LATE_BOOST_DMG = 0.028          # dalga başına ek hasar payı
LATE_BOOST_COUNT_EVERY = 6      # bu kadar dalgada bir doğum başına +1 yaratık
LATE_BOOST_COUNT_MAX = 4


def late_wave_boost(wave, biome="arena"):
    """(can çarpanı, hasar çarpanı, ek yaratık sayısı)."""
    w = int(wave) + (HELL_BASE_WAVE if biome == "hell" else 0)
    over = max(0, w - LATE_BOOST_FROM)
    if over <= 0:
        return 1.0, 1.0, 0
    return (1.0 + LATE_BOOST_HP * over, 1.0 + LATE_BOOST_DMG * over,
            min(LATE_BOOST_COUNT_MAX, over // LATE_BOOST_COUNT_EVERY))


# ---- süreli dalgalar ----
# "Her skorda bir dalga atlama mantığı olmayacak; saniye mantığıyla dalga
# atlanacak." Dalgalar oyuncunun skoruna bakmaz, yalnızca süreyle ilerler: kötü
# oynayan da iyi oynayan da aynı saatte aynı dalgadadır:
#   normal 35 dk, zor 30 dk, kabus 20 dk - cehennemde 40 / 34 / 23 dk.
WAVE_PLAN_COUNT = 25
WAVE_PLAN_GROW = 0.07
WAVE_PLAN_TOTAL = {
    "arena": {"normal": 35 * 60.0, "hard": 30 * 60.0, "nightmare": 20 * 60.0},
    "hell": {"normal": 40 * 60.0, "hard": 40 * 60.0 * 30 / 35, "nightmare": 40 * 60.0 * 20 / 35},
}
_WAVE_PLAN_W = sum(1.0 + WAVE_PLAN_GROW * (i - 1) for i in range(1, WAVE_PLAN_COUNT + 1))


def wave_plan_total(diff="normal", biome="arena"):
    tbl = WAVE_PLAN_TOTAL["hell" if biome == "hell" else "arena"]
    return float(tbl.get(diff, tbl["normal"]))


def wave_length(wave, diff="normal", biome="arena"):
    """Bir dalganın süresi (sn)."""
    w = min(WAVE_PLAN_COUNT, max(1, int(wave)))
    return wave_plan_total(diff, biome) * (1.0 + WAVE_PLAN_GROW * (w - 1)) / _WAVE_PLAN_W


def wave_start_time(wave, diff="normal", biome="arena"):
    """Dalganın başladığı an (o haritanın / cehennemin başından itibaren, sn)."""
    w = max(1, int(wave))
    t = 0.0
    for i in range(1, min(w, WAVE_PLAN_COUNT + 1)):
        t += wave_length(i, diff, biome)
    if w > WAVE_PLAN_COUNT + 1:
        t += (w - WAVE_PLAN_COUNT - 1) * wave_length(WAVE_PLAN_COUNT, diff, biome)
    return t


def wave_at_time(t, diff="normal", biome="arena"):
    """t saniyede ulaşılabilecek dalga (takvime göre)."""
    t = max(0.0, float(t))
    w = 1
    acc = 0.0
    while w <= WAVE_PLAN_COUNT:
        ln = wave_length(w, diff, biome)
        if acc + ln > t:
            return w
        acc += ln
        w += 1
    return WAVE_PLAN_COUNT + 1 + int((t - acc) // wave_length(WAVE_PLAN_COUNT, diff, biome))


def min_time_for_wave(total_wave, diff="normal"):
    """Toplam dalgaya (arena + cehennem) ulaşmak için gereken en kısa süre."""
    w = max(1, int(total_wave))
    t = wave_start_time(w, diff, "arena")
    for a in range(WAVE_PLAN_COUNT, w):
        t = min(t, wave_start_time(a, diff, "arena") + wave_start_time(w - a, diff, "hell"))
    return t


def time_wave_reachable(total_wave, run_time, diff="normal"):
    """Bu dalgaya bu sürede ulaşılabilir mi?"""
    w = max(1, int(total_wave))
    if w <= 2:
        return True
    return min_time_for_wave(w - 1, diff) <= float(run_time) + 10.0


WAVE_ACCEL_EXTRA_MAX = 2


class WaveManager:
    def __init__(self, diff="normal", biome="arena"):
        # biome: "arena" (1. harita) | "hell" (cehennem)
        self.biome = biome
        self.wave = 1
        self.wave_time = 0.0
        self.pace = DIFF_PACE.get(diff, 1.0)
        # harita kuralı + yemin: yaratık hızı ve doğum sıklığı çarpanı
        self.enemy_speed_mult = 1.0
        self.spawn_rate_mult = 1.0
        # haritanın yaratık takımı (MAP_ROSTER). "stone" = arena türleri.
        self.theme = "stone"
        self.doom = False           # cehennemsiz haritada ölüm duvarı
        # normal: yavaş/sakin tempo (uzun dalgalar) - kabus: hızlı/yoğun tempo
        # (kısa dalgalar)
        self.wave_duration = 24.0 / self.pace
        self.spawn_timer = 0.0
        self.announce_timer = 2.4
        self.announce_text = (L("ui.ann_hell", 1) if biome == "hell" else L("ui.wave", 1))
        self.diff = diff
        self.boss_idx = 0
        self.boss_active = False
        self.boss_pending = False
        # ---- skor tabanlı ilerleme ----
        self.wave_start_score = 0      # bu dalgaya girerken oyuncunun skoru
        self.wave_score = 0            # bu dalgada toplanan skor
        # dalga yalnızca süreyle ilerler. Skor hedefi kalktı; alanlar eski
        # kodla (tur, reklam) uyum için duruyor.
        self.wave_goal = 0
        self.wave_len = wave_length(1, diff, biome)
        self.min_time = self.wave_len
        # ---- yoğunluk (surge) penceresi ----
        self.surge_timer = 0.0
        self.surge_delay = 0.0     # pencere açılmadan önceki sükûnet
        # Patron dövüşünün süresi.
        self.boss_clock = 0.0
        # lanetli sandık: kabul edilen lanetler {anahtar: seviye}. RunState ile
        # aynı sözlük paylaşılır (cehenneme geçişte de taşınır).
        self.curses = {}
        # dalga olayı: RunState ayarlar (hız çarpanı, elit gecesi) 2 kişilik:
        # kalabalık tavanı ve yaratık hasarı çarpanı
        self.cap_mult = 1.0
        self.cap_max = None
        self.dmg_mult = 1.0

    # Dünya ekrandan büyük olduğu için doğum noktasını RunState belirler
    # (kameranın hemen dışı).
    spawn_pos_fn = None

    def spawn_pos(self):
        if self.spawn_pos_fn is not None:
            return self.spawn_pos_fn()
        side = random.randint(0, 3)
        if side == 0:
            return (random.uniform(ARENA_RECT.left, ARENA_RECT.right), ARENA_RECT.top - 30)
        elif side == 1:
            return (random.uniform(ARENA_RECT.left, ARENA_RECT.right), ARENA_RECT.bottom + 30)
        elif side == 2:
            return (ARENA_RECT.left - 30, random.uniform(ARENA_RECT.top, ARENA_RECT.bottom))
        else:
            return (ARENA_RECT.right + 30, random.uniform(ARENA_RECT.top, ARENA_RECT.bottom))

    def is_boss_wave(self, w):
        """Patron dalgaları."""
        if self.biome == "hell":
            # cehennemin son patronu 40. dalgada; sonrası ölüm duvarı
            return (w >= HELL_BOSS_FIRST_WAVE
                    and (HELL_FINAL_WAVE is None or w <= HELL_FINAL_WAVE)
                    and (w - HELL_BOSS_FIRST_WAVE) % HELL_BOSS_STEP == 0)
        if w > HELL_PORTAL_WAVE:
            return False
        return w >= BOSS_FIRST_WAVE and (w - BOSS_FIRST_WAVE) % BOSS_WAVE_STEP == 0

    def surge_active(self):
        """Yoğunluk penceresi açık mı?"""
        return self.surge_timer > 0 and self.surge_delay <= 0

    def goal_progress(self):
        """0..1 arası - dalganın süresinin ne kadarı geçti."""
        return 1.0 if self.wave_len <= 0 else clamp(self.wave_time / self.wave_len, 0.0, 1.0)

    def time_left(self):
        """Sonraki dalgaya kalan süre (sn)."""
        return max(0.0, self.wave_len - self.wave_time)

    def _begin_wave(self, new_wave, total_score):
        """Yeni dalgaya geçerken sayaçları sıfırlar ve yoğunluk penceresini açar."""
        self.wave = new_wave
        self.wave_time = 0.0
        self.wave_start_score = total_score
        self.wave_score = 0
        self.wave_goal = 0
        self.wave_len = wave_length(new_wave, self.diff, self.biome)
        self.min_time = self.wave_len
        self.wave_duration = min(42 / self.pace, self.wave_duration + 1.1 / self.pace)
        # Kısa bir sükûnetten sonra başlıyor; patron dalgasından sonra biraz
        # daha uzun.
        self.surge_delay = SURGE_CALM_BOSS if self.is_boss_wave(new_wave) else SURGE_CALM
        self.surge_timer = SURGE_DURATION
        self.announce_timer = 2.2

    def pick_kind(self):
        """Doğacak yaratığın türü."""
        if self.curses and random.random() < curse_spawn_chance(self.curses):
            ck = pick_curse_kind(self.curses)
            if ck:
                return ck
        return self.pick_base_kind()

    def pick_base_kind(self):
        if self.biome == "hell":
            return hell_pick_kind(self.wave)
        w = self.wave
        weights = {
            "red": 10,
            "blue": 6 + min(w, 10),
            "tank": max(0, min(w - 2, 8)),
            "yellow": max(0, min(w - 1, 8)),
            "sprinter": max(0, min(w - 3, 7)),
            "brute": max(0, min(w - 5, 6)),
            # Yeni arketipler sonradan girer: oyuncu önce temel yaratıkları
            # öğrensin, sonra "hedef seçme" sorusuyla tanışsın.
            "bomber": max(0, min(w - 6, 5)),
            "healer": max(0, min((w - 8) // 2, 3)),
            # büyücü 15. dalgada girer ve seyrek kalır (tavan 3): tehdidi
            # sayısı değil, uzaktan sürekli zehirlemesi.
            "wizard": max(0, min((w - 14), 3)) if w >= 15 else 0,
            # arı 25. dalgada girer; hızlı ama vuruşu küçük olduğu için
            # kalabalık gelebilir.
            "stinger": max(0, min((w - 24) * 2, 10)) if w >= 25 else 0,
            # kamikaze 20. dalgada girer, yavaş yavaş çoğalır.
            "kamikaze": max(0, min(w - 19, 5)) if w >= KAMIKAZE_WAVE else 0,
        }
        kinds = list(weights.keys())
        wts = list(weights.values())
        kind = random.choices(kinds, weights=wts, k=1)[0]
        # ilk 10 dalgada yarasa %10 az.
        if kind == "blue" and w <= EARLY_BAT_WAVES and random.random() < EARLY_BAT_NERF:
            rest = [(k, v) for k, v in weights.items() if k != "blue" and v > 0]
            if rest:
                kind = random.choices([k for k, _ in rest], weights=[v for _, v in rest], k=1)[0]
        return kind

    def update(self, dt, enemies, wave_mult_fn, boss_active=False, total_score=0):
        self.wave_time += dt
        if self.announce_timer > 0:
            self.announce_timer -= dt
        # sıra önemli: önce sükûnet tükenir, yoğunluk penceresi ancak ondan
        # sonra işlemeye başlar.
        if self.surge_delay > 0:
            self.surge_delay = max(0.0, self.surge_delay - dt)
        elif self.surge_timer > 0:
            self.surge_timer = max(0.0, self.surge_timer - dt)

        # O dalgada toplanan skor = güncel toplam - dalga başındaki toplam
        self.wave_score = max(0, int(total_score) - int(self.wave_start_score))

        wave_changed = False
        # patron süresi: patron BOSS_WAVE_TIMEOUT saniyede devrilmezse doğum
        # normal tempoya döner (patron sahada kalır). patron dalgayı hiç
        # durdurmaz - dalga saati patron varken de işler.
        if boss_active and not self.boss_pending:
            self.boss_clock += dt
        else:
            self.boss_clock = 0.0
        # süreli dalga: dalga, süresi dolunca ilerler - skor aranmaz.
        if self.wave_time >= self.wave_len:
            self._begin_wave(self.wave + 1, total_score)
            wave_changed = True
            if self.is_boss_wave(self.wave):
                self.boss_pending = True
                self.surge_timer = 0.0     # patron dalgasında yoğunluk olmaz
                self.announce_text = "PATRON YAKLAŞIYOR!"
            elif self.biome == "hell":
                self.announce_text = L("ui.ann_hell", self.wave)
            elif self.wave > HELL_PORTAL_WAVE:
                # Portal açıldıktan sonra arena her dalgada daha da azgınlaşır.
                self.announce_text = L("ui.ann_rage", self.wave)
            else:
                self.announce_text = L("ui.ann_surge", self.wave)

        # patron varken oyun durmaz. Patron zaten zor; amaç arenanın boş
        # kalmaması, oyuncuyu boğmak değil.
        boss_time = self.boss_pending or (boss_active and self.boss_clock < BOSS_WAVE_TIMEOUT)

        # Zorluk düşman istatistiklerini değil yalnızca TEMPOyu (pace) etkiler
        # - spawn hızı tamamen self.pace üzerinden belirlenir.
        tw = spawn_tempo_wave(self.wave, self.biome)
        base_interval = max(0.20, 1.15 - tw * 0.035) / (self.pace * SPAWN_RATE_TUNE
                                                         * self.spawn_rate_mult)
        if boss_time:
            # patron dövüşü uzasa da tempo artmaz; yalnızca yarı hız
            base_interval /= BOSS_SPAWN_RATE
        else:
            # dalga içi hızlanma: aynı dalgada bile tempo sürekli artar.
            base_interval /= (1.0 + min(WAVE_ACCEL_MAX, self.wave_time * WAVE_ACCEL_RATE))
            if self.surge_active():
                base_interval *= SURGE_RATE
        self.spawn_timer -= dt
        if self.spawn_timer <= 0:
            self.spawn_timer = base_interval
            # Kalabalık tavanı: arena tıkanmışsa bu turda yeni düşman doğmaz.
            cap = max_alive_enemies(tw)
            if self.cap_mult != 1.0:
                cap = int(cap * self.cap_mult)
                if self.cap_max:
                    cap = min(cap, int(self.cap_max))
            if boss_time:
                cap = max(6, int(cap * BOSS_CROWD_SHARE))
            # kalabalık laneti: kalabalık tavanı büyür
            sw_ = int(self.curses.get("swarm", 0))
            if sw_:
                cap = int(cap * (1.0 + CURSE_SWARM_CAP * sw_))
            if len(enemies) >= cap:
                return wave_changed
            # Geç dalgalarda yalnızca hasar değil, düşman yoğunluğu da artar -
            # maksimum eşyalı bir oyuncu bile kalabalığa yenik düşebilsin.
            if tw < 3:
                count = 1
            elif tw < 6:
                count = 2
            elif tw < 10:
                count = 3
            elif tw < 16:
                count = 4
            else:
                count = 5
            # Dalga uzadıkça kalabalık da büyür (dalga içi hızlanmanın ikinci
            # ayağı) - oyuncu oyalanırsa baskı gerçekten artar.
            if boss_time:
                count = max(1, int(round(count * BOSS_SPAWN_RATE)))
            else:
                count += min(WAVE_ACCEL_EXTRA_MAX, int(self.wave_time // WAVE_ACCEL_EXTRA_AFTER))
                if self.surge_active():
                    count += SURGE_EXTRA
            hell = self.biome == "hell"
            count += int(self.curses.get("swarm", 0))
            # geç dalgalarda doğum başına ek yaratık (late_wave_boost)
            count += late_wave_boost(self.wave, self.biome)[2]
            frenzy = int(self.curses.get("frenzy", 0))
            for _ in range(count):
                kind = self.pick_kind()
                x, y = self.spawn_pos()
                if kind in CURSE_KINDS:
                    e_new = Enemy(kind, x, y, wave_mult_fn(self.wave), 1.0, wave=self.wave,
                                  biome=self.biome)
                elif hell:
                    e_new = Enemy(None, x, y, wave_mult_fn(self.wave), 1.0,
                                  wave=self.wave, variant=kind, biome="hell")
                else:
                    # Buzul / Orman / Çöl kendi yaratıklarını doğurur
                    e_new = make_map_enemy(self.theme, kind, x, y, wave_mult_fn(self.wave),
                                           1.0, wave=self.wave)
                if frenzy:
                    # kudurma laneti: yaratıklar daha hızlı
                    e_new.speed *= 1.0 + CURSE_FRENZY_SPD * frenzy
                if self.enemy_speed_mult != 1.0:
                    e_new.speed *= self.enemy_speed_mult    # harita / yemin
                if self.doom:
                    self._doomify(e_new)
                self._late_boost(e_new)
                if kind not in CURSE_KINDS:
                    self._mutate_roll(e_new)
                enemies.append(e_new)
            elite_chance = 0.12 + min(0.28, self.wave * 0.008)
            if self.surge_active():
                elite_chance += 0.10
            if (not boss_time and self.wave % 5 == 0
                    and random.random() < elite_chance):
                x, y = self.spawn_pos()
                if hell:
                    el = Enemy(None, x, y, wave_mult_fn(self.wave) * 1.1, 1.0,
                               wave=self.wave, variant="h_warden", biome="hell")
                else:
                    el = make_map_enemy(self.theme, "elite", x, y, wave_mult_fn(self.wave) * 1.1,
                                        1.0, wave=self.wave)
                    if self.doom:
                        self._doomify(el)
                self._late_boost(el)
                enemies.append(el)

        return wave_changed

    def _mutate_roll(self, e):
        """mutasyon: 30. dalgadan sonra doğan her 3 yaratıktan 1'i mutant."""
        # cehennemde de - cehennem, taş meydanın 25. dalgasının devamı sayılır
        # (cehennemin 5. dalgası = toplam 30).
        w = int(self.wave) + (HELL_WAVE_OFFSET if self.biome == "hell" else 0)
        if w < MUTANT_FROM:
            return
        self.mutant_counter = getattr(self, "mutant_counter", 0) + 1
        if self.mutant_counter % MUTANT_EVERY == 0:
            e.mutate()

    def _late_boost(self, e):
        """Geç dalga güçlenmesi -"""
        hp_k, dmg_k, _extra = late_wave_boost(self.wave, self.biome)
        dmg_k *= getattr(self, "dmg_mult", 1.0)
        if hp_k == 1.0 and dmg_k == 1.0:
            return
        e.max_hp *= hp_k
        e.hp *= hp_k
        e.dmg *= dmg_k
        e.contact_dps *= dmg_k

    def _doomify(self, e):
        """Ölüm duvarı: 25. dalgadan sonra can ve hasara ek çarpan."""
        hp_k, dmg_k = doom_mult(self.wave)
        if hp_k == 1.0 and dmg_k == 1.0:
            return
        e.max_hp *= hp_k
        e.hp *= hp_k
        e.dmg *= dmg_k
        e.contact_dps *= dmg_k


# combo sayacı

class ComboMeter:
    def __init__(self):
        self.count = 0
        self.best = 0
        self.timer = 0.0
        self.window = 2.1
        self.pulse = 0.0

    def add_kill(self):
        self.count += 1
        self.best = max(self.best, self.count)
        self.timer = self.window
        self.pulse = 1.0

    def multiplier(self):
        return 1.0 + min(self.count * 0.04, 2.0)

    def update(self, dt):
        if self.timer > 0:
            self.timer -= dt
            if self.timer <= 0:
                self.count = 0
        if self.pulse > 0:
            self.pulse = max(0.0, self.pulse - dt * 3)


# buton / panel

def ui_warm(c):
    """Koyu lacivert zeminleri sıcak kahve-mora çevirir; renkli zeminler kalır.
    Eski ekranların çoğu kendi koyu mavisini veriyor, hepsi tek tek
    değişmesin diye burada çevriliyor."""
    if len(c) > 3:
        return ui_warm(c[:3]) + (int(c[3]),)
    r, g, b = int(c[0]), int(c[1]), int(c[2])
    key = (r, g, b)
    out = _warm_cache.get(key)
    if out is None:
        h, sat, v = colorsys.rgb_to_hsv(r / 255.0, g / 255.0, b / 255.0)
        if v < 0.45 and 0.50 <= h <= 0.72 and sat > 0.12:
            sat = min(sat, 0.32) * 0.85
            h = 0.985
            v = min(1.0, v * 1.12 + 0.015)
            rr, gg, bb = colorsys.hsv_to_rgb(h, sat, v)
            out = (int(rr * 255), int(gg * 255), int(bb * 255))
        else:
            out = key
        _warm_cache[key] = out
    return out


_warm_cache = {}


_poly_cache = {}


def _hand_poly(w, h, rad, seed, inset=0.0):
    """El kesimi dikdörtgen: dört köşe biraz farklı yuvarlak, kenarlar hafif
    dalgalı. Aynı ölçü + tohum hep aynı şekli verir; iç kat (inset) dış
    katla aynı dalgayı izler."""
    key = (w, h, rad, seed, inset)
    pts = _poly_cache.get(key)
    if pts is None:
        if len(_poly_cache) > 3000:
            _poly_cache.clear()
        pts = _poly_cache[key] = _hand_poly_make(w, h, rad, seed, inset)
    return pts


def _hand_poly_make(w, h, rad, seed, inset):
    rnd = random.Random(seed)
    lim = max(2.0, min(w, h) / 2.0 - 1)
    rads = [min(lim, rad * rnd.uniform(0.55, 1.3)) for _ in range(4)]
    wob = 0.0 if min(w, h) < 26 else (0.6 if min(w, h) < 60 else 1.0)
    x0, y0 = inset, inset
    x1, y1 = w - 1 - inset, h - 1 - inset
    centers = ((x0, y0, 1, 1, 180), (x1, y0, -1, 1, 270),
               (x1, y1, -1, -1, 0), (x0, y1, 1, -1, 90))
    edges = (w, h, w, h)
    pts = []
    for i, (cx, cy, sx, sy, a0) in enumerate(centers):
        r = max(1.0, rads[i] - inset)
        ox, oy = cx + sx * r, cy + sy * r
        for k in range(6):
            a = math.radians(a0 + 90 * k / 5.0)
            pts.append((ox + math.cos(a) * r, oy + math.sin(a) * r))
        # sonraki köşeye giden kenar boyunca küçük dalgalar
        n = int(edges[i] // 46)
        jit = [rnd.uniform(-1, 1) * wob for _ in range(n)]
        if n:
            nx, ny = pts[-1]
            j = (i + 1) % 4
            cx2, cy2, sx2, sy2, _a = centers[j]
            r2 = max(1.0, rads[j] - inset)
            ex = cx2 + sx2 * r2 if i % 2 == 0 else cx2
            ey = cy2 if i % 2 == 0 else cy2 + sy2 * r2
            for q in range(n):
                f = (q + 1) / (n + 1)
                px, py = nx + (ex - nx) * f, ny + (ey - ny) * f
                if i % 2 == 0:
                    py += jit[q] * (1 if i == 0 else -1)
                else:
                    px += jit[q] * (-1 if i == 1 else 1)
                pts.append((px, py))
    return pts


_hand_cache = {}


def hand_card(w, h, fill, edge=None, rad=12, alpha=255, ink=3, seed=0, lip=0):
    """Arayüzün ortak kartı (önbellekli): mürekkep kontur, düz dolgu, isteğe
    bağlı iç çizgi (edge) ve altta koyu dudak (lip, basılabilir düğme hissi)."""
    w, h = int(w), int(h)
    fill = tuple(int(v) for v in fill[:3])
    edge = tuple(int(v) for v in edge[:3]) if edge is not None else None
    key = (w, h, fill, edge, rad, alpha, ink, seed, lip)
    s = _hand_cache.get(key)
    if s is not None:
        return s
    if len(_hand_cache) > (700 if MOBILE else 360):
        _hand_cache.clear()
    sd = seed * 7919 + w * 31 + h
    s = pygame.Surface((w, h), pygame.SRCALPHA)
    outer = _hand_poly(w, h, rad, sd)
    pygame.draw.polygon(s, (*INK, max(alpha, 200)), outer)
    body = _hand_poly(w, h, rad, sd, inset=ink)
    if lip:
        pygame.draw.polygon(s, (*scale_col(fill, 0.62), alpha), body)
        top = _hand_poly(w, h - lip, rad, sd, inset=ink)
        pygame.draw.polygon(s, (*fill, alpha), top)
        if h - lip > 14:
            m = int(ink + rad * 0.7)
            pygame.draw.line(s, (*lighten(fill, 0.30), alpha), (m, ink + 2), (w - m, ink + 2), 2)
    else:
        pygame.draw.polygon(s, (*fill, alpha), body)
    if edge is not None and min(w, h) > 30:
        pygame.draw.lines(s, (*edge, 170), True, _ipts(_hand_poly(w, h, rad, sd, inset=ink + 3)), 1)
    pygame.draw.aalines(s, INK, True, outer)
    _hand_cache[key] = s
    return s


_hand_shadow_cache = {}


def hand_shadow(w, h, rad=12, seed=0, alpha=150):
    """Kartın sert gölgesi: bulanık değil, düz mürekkep lekesi."""
    w, h = int(w), int(h)
    key = (w, h, rad, seed, alpha)
    s = _hand_shadow_cache.get(key)
    if s is None:
        if len(_hand_shadow_cache) > 200:
            _hand_shadow_cache.clear()
        s = pygame.Surface((w, h), pygame.SRCALPHA)
        pygame.draw.polygon(s, (*INK, alpha), _hand_poly(w, h, rad, seed * 7919 + w * 31 + h))
        _hand_shadow_cache[key] = s
    return s


class Button:
    def __init__(self, rect, text, callback=None, color=(52, 60, 96),
                 hover_color=(78, 92, 150), text_size=24, enabled=True,
                 subtitle=None, text_color=None):
        self.rect = pygame.Rect(rect)
        self.text = text
        self.callback = callback
        self.color = color
        self.hover_color = hover_color
        self.text_size = text_size
        self.enabled = enabled
        self.subtitle = subtitle
        self.text_color = text_color
        self.hover = False
        self.anim = 0.0

    def update(self, mouse_pos, dt):
        was = self.hover
        self.hover = self.enabled and self.rect.collidepoint(mouse_pos)
        if self.hover and not was:
            sfx("hover", 0.4, 0.05)
        target = 1.0 if self.hover else 0.0
        self.anim += (target - self.anim) * min(1, dt * 12)

    def _colors(self):
        col = ui_warm(self.color)
        if self.hover:
            col = lighten(ui_warm(self.hover_color), 0.06)
        if not self.enabled:
            g = sum(col) // 3
            col = mix_col(col, (g, g, g), 0.75)
            col = scale_col(col, 0.7)
        tc = self.text_color or (TEXT if self.enabled else (126, 116, 108))
        return col, tc

    def _paint(self, surf, x, y, col, tc, step):
        """Basılabilir tuş: altta koyu dudak, üzerine gelince 2 piksel kalkar."""
        w, h = self.rect.w, self.rect.h
        lift = step
        lip = 5 if h >= 30 else 3
        surf.blit(hand_shadow(w, h, 10, alpha=140), (x + 3, y + 4))
        surf.blit(hand_card(w, h, col, rad=10, ink=3, lip=lip), (x, y - lift))
        label, sz = _fit_size(TRX(self.text), self.text_size, w - 18, True,
                              min_size=min(12, self.text_size))
        draw_text(surf, label, (x + w // 2, y - lift + (h - lip) // 2 + 1),
                  sz, tc, bold=True, center=True)
        if self.subtitle:
            draw_text(surf, self.subtitle, (x + w // 2, y + h + 13), 13, TEXT_DIM,
                      center=True, shadow=False)

    def draw(self, surf):
        """Düğmeyi çizer."""
        col, tc = self._colors()
        if MOBILE:
            self._draw_mobile(surf, col, tc)
            return
        self._paint(surf, self.rect.x, self.rect.y, col, tc, int(round(self.anim * 2)))

    _MOB_IMG = {}

    def _draw_mobile(self, surf, col, tc):
        """telefon: düğmenin bütün katmanları tek hazır görüntü"""
        step = int(round(self.anim * 2))
        key = (self.rect.size, col, step, self.text, self.text_size, tc, self.subtitle, lang())
        img = Button._MOB_IMG.get(key)
        if img is None:
            if len(Button._MOB_IMG) > 500:
                Button._MOB_IMG.clear()
            pad = 8
            extra = 28 if self.subtitle else 0
            img = pygame.Surface((self.rect.w + pad * 2, self.rect.h + pad * 2 + extra),
                                 pygame.SRCALPHA)
            self._paint(img, pad, pad, col, tc, step)
            img = mob_rle(img)
            Button._MOB_IMG[key] = img
        surf.blit(img, (self.rect.x - 8, self.rect.y - 8))

    def click(self, mouse_pos):
        if self.enabled and self.rect.collidepoint(mouse_pos):
            sfx("click", 0.6, 0.0)
            if self.callback:
                self.callback()
            return True
        return False


def hand_mask(img, rad, seed=0):
    """Hazır bir kart gövdesini el kesimi şekle kırpar (yerinde)."""
    w, h = img.get_size()
    m = pygame.Surface((w, h), pygame.SRCALPHA)
    pygame.draw.polygon(m, (255, 255, 255, 255), _hand_poly(w, h, rad, seed * 7919 + w * 31 + h))
    img.blit(m, (0, 0), special_flags=pygame.BLEND_RGBA_MIN)
    return img


def ink_frame(surf, rect, col=None, rad=12, width=2, seed=0):
    """Kartın çerçevesi: dışta mürekkep, içte (varsa) renkli ince çizgi.
    hand_mask ile kırpılmış gövdeyle aynı şekli izler."""
    rect = pygame.Rect(rect)
    w, h = rect.w, rect.h
    if w < 4 or h < 4:
        return
    sd = seed * 7919 + w * 31 + h
    k = 3 if min(w, h) >= 28 else 2
    ox, oy = rect.x, rect.y
    pygame.draw.lines(surf, INK, True, [(int(x + ox), int(y + oy)) for x, y in _hand_poly(w, h, rad, sd)], k)
    if col is not None and min(w, h) > 20:
        pygame.draw.lines(surf, tuple(col)[:3], True,
                          [(int(x + ox), int(y + oy)) for x, y in _hand_poly(w, h, rad, sd, inset=k)],
                          max(1, min(2, int(width) - 1)))


def _panel_shadow(w, h, radius=12):
    """Eski çağrılar için: (x - 6, y - 2) konumuna basılınca kartın sağ altına düşen sert gölge."""
    key = ("old", w, h, radius)
    s = _hand_shadow_cache.get(key)
    if s is None:
        s = pygame.Surface((w + 12, h + 12), pygame.SRCALPHA)
        s.blit(hand_shadow(w, h, min(radius, 14)), (10, 7))
        _hand_shadow_cache[key] = s
    return s


def _button_body(w, h, col, anim, rad):
    """Eski çağrılar için: düz dolgulu, alt dudaklı tuş gövdesi."""
    col = lighten(ui_warm(col), 0.06 * clamp(anim, 0.0, 1.0))
    return hand_card(w, h, col, rad=min(int(rad), 14), ink=3, lip=5 if h >= 30 else 3)


def key_button(surf, rect, col, hover=False, rad=10):
    """Button sınıfı dışında elle çizilen düğmeler için aynı basılabilir tuş
    gövdesi. Yazının ortalanacağı dikdörtgeni döndürür."""
    rect = pygame.Rect(rect)
    lip = 5 if rect.h >= 30 else 3
    lift = 2 if hover else 0
    c = lighten(ui_warm(col), 0.10) if hover else ui_warm(col)
    surf.blit(hand_shadow(rect.w, rect.h, rad, alpha=140), (rect.x + 3, rect.y + 4))
    surf.blit(hand_card(rect.w, rect.h, c, rad=rad, ink=3, lip=lip), (rect.x, rect.y - lift))
    return pygame.Rect(rect.x, rect.y - lift, rect.w, rect.h - lip)


def panel(surf, rect, bg=PANEL_BG, edge=PANEL_EDGE, alpha=235, radius=16, edge_w=2):
    """Oyundaki bütün pencerelerin ortak zemini."""
    rect = pygame.Rect(rect)
    rad = min(int(radius), 14)
    surf.blit(hand_shadow(rect.w, rect.h, rad, alpha=min(150, int(alpha * 0.62))),
              (rect.x + 5, rect.y + 6))
    surf.blit(hand_card(rect.w, rect.h, ui_warm(bg), edge=ui_warm(edge), rad=rad,
                        alpha=int(alpha), ink=3 if edge_w >= 2 else 2), rect.topleft)


def draw_scrollbar(surf, track_x, list_top, list_h, content_h, scroll):
    """Kaydırılabilir bir liste için sağ kenara ince bir scrollbar çizer."""
    track = pygame.Rect(track_x, list_top, 5, list_h)
    s = pygame.Surface(track.size, pygame.SRCALPHA)
    pygame.draw.rect(s, (255, 255, 255, 30), s.get_rect(), border_radius=3)
    surf.blit(s, track.topleft)
    max_scroll = max(1, content_h - list_h)
    thumb_h = max(24, int(list_h * clamp(list_h / content_h, 0.08, 1.0)))
    thumb_y = list_top + int((list_h - thumb_h) * clamp(scroll / max_scroll, 0.0, 1.0))
    thumb = pygame.Rect(track_x, thumb_y, 5, thumb_h)
    ts = pygame.Surface(thumb.size, pygame.SRCALPHA)
    pygame.draw.rect(ts, (*GOLD, 220), ts.get_rect(), border_radius=3)
    surf.blit(ts, thumb.topleft)


# run state

# ---- hile koruması - koşu denetimi (3. katman) ----
# İmza ve elmas defteri kayıt dosyasını korur:
#   tavan: oyuncunun o seviyede ulaşabileceği en yüksek değerin bir
#      miktar üstü. Oyunun kendi kaynakları (kitaplar, market, skin,
#      silahlar) toplandığında bile bu tavan aşılamaz; aşılıyorsa
#      değer dışarıdan yazılmıştır.
#   tutarlılık: koşu bitince skor; öldürme sayısı, dalga ve süreyle
#      karşılaştırılır. 5 öldürmeyle 10 milyon skor olmaz.
#      hasar 123x azami can 3.630 hız 16,3x zırh 0,60
RUNCHK_DMG_BASE = 12.0          # 1. seviyedeki hasar çarpanı tavanı
RUNCHK_DMG_PER_LEVEL = 4.3      # seviye başına eklenen pay
RUNCHK_DMG_CAP = 2000.0         # mutlak tavan (taban hasarın katı)
RUNCHK_HP_BASE = 800.0          # 1. seviyedeki azami can tavanı
RUNCHK_HP_PER_LEVEL = 170.0     # Efsanevi Can kartı tek seferde +104 verir
RUNCHK_HP_CAP = 400000.0
RUNCHK_SPEED_BASE = 4.5         # 1. seviyedeki hız tavanı (taban hızın katı)
RUNCHK_SPEED_PER_LEVEL = 0.52
RUNCHK_SPEED_CAP = 60.0
RUNCHK_SCORE_PER_KILL = 900.0   # bir öldürmeden çıkabilecek en yüksek skor
RUNCHK_SCORE_FLOOR = 6000.0     # bu skorun altında tutarlılık aranmaz
RUNCHK_SCORE_TIME_SLACK = 150.0  # koşu saniyesi başına ek skor payı


def run_integrity_check(run):
    """Koşu hâlâ kurallara uygun mu?"""
    p = run.player
    lvl = max(1, int(getattr(p, "level", 1)))
    try:
        # güç sunağının süreli payı oyunun kendi verdiği bir şey: sayılmaz
        dmg_ratio = p.eff_dmg() / (1.0 + getattr(p, "shrine_dmg", 0.0)) / max(1e-6, BASE_DMG)
        spd_ratio = p.eff_speed() / (1.0 + getattr(p, "shrine_spd", 0.0)) / max(1e-6, BASE_SPEED)
        hp = float(p.max_hp)
    except Exception:
        return None
    if dmg_ratio > min(RUNCHK_DMG_CAP, RUNCHK_DMG_BASE + RUNCHK_DMG_PER_LEVEL * lvl):
        return "hasar"
    if hp > min(RUNCHK_HP_CAP, RUNCHK_HP_BASE + RUNCHK_HP_PER_LEVEL * lvl):
        return "can"
    if spd_ratio > min(RUNCHK_SPEED_CAP,
                       RUNCHK_SPEED_BASE + RUNCHK_SPEED_PER_LEVEL * lvl):
        return "hız"
    # eff_armor zaten 0.60'ta kırpıyor; bu yalnızca alanın doğrudan yazıldığı
    # durumu yakalar.
    if p.eff_armor() > 0.61:
        return "zırh"
    return None


def run_score_plausible(run):
    """Koşu bitti: skor; öldürme, dalga ve süreyle tutarlı mı?"""
    score = float(getattr(run, "score", 0))
    # lanetli sandık: lanetlerin skor payı ayrılır (dürüst lanetli koşu
    # "imkânsız skor" sayılmasın). Sunucu da aynı payı tanıyor
    # (CURSE_SCORE_ROOM).
    score /= (1.0 + clamp(float(getattr(run, "curse_score_bonus", 0.0) or 0.0),
                          0.0, CURSE_SCORE_MAX))
    if score < RUNCHK_SCORE_FLOOR:
        return True
    kills = max(0, int(getattr(run, "kills", 0)))
    # Cehennemde arenada geçilen dalgalar da sayılır.
    wave = max(1, int(run.total_wave() if hasattr(run, "total_wave")
                      else getattr(run.waves, "wave", 1)))
    rt = max(1.0, float(getattr(run, "run_time", 1.0)))
    # 1) Öldürme başına düşen skorun tavanı var.
    if score > RUNCHK_SCORE_PER_KILL * (kills + 10):
        return False
    _ = wave
    # 3) Saniyede üretilebilecek skorun bir tavanı var. lanetli cehennemde
    #    dürüst uç bot saniyede ~2.700 (lanet payı ayrılmış) üretti; pay geniş
    #    tutuldu (sunucu: MAX_SCORE_PER_SEC).
    if score / rt > 12000.0:
        return False
    return True


# ---- güç sunakları ----
