def evo_name(key):
    return L("evo.name." + key)


def evo_book_name(key):
    bk = BOOK_BY_KEY.get(EVOLUTIONS[key][0])
    return bk_name(bk) if bk else EVOLUTIONS[key][0]


def evo_ready_keys(p):
    """Evrime hazır silahlar: seviyesi yeten, eş kitabı elde olan, henüz evrilmemiş."""
    done = getattr(p, "evolved", ())
    out = []
    for key, lvl in p.weapons.items():
        ev = EVOLUTIONS.get(key)
        if ev is None or key in done or lvl < EVO_LEVEL:
            continue
        if p.books.get(ev[0], 0) > 0:
            out.append(key)
    return out


# Vuruş anında hangi koşunun etkileri işliyor: koşu her karede kendini yazar.
EVO_CTX = [None]
EVO_BUSY = [False]


def evo_on_hit(e, amount, fx):
    """Evrilmiş silahın vuruş etkisi. Enemy / Boss take_damage içinden çağrılır."""
    run = EVO_CTX[0]
    if run is None or EVO_BUSY[0] or amount <= 0:
        return
    key = DMG_SRC[0]
    perk = run.evo_perks.get(key)
    if perk is None:
        return
    if perk == "blast":
        if e.hp <= 0 and e.alive:
            run.evo_blast(e, amount, key)
        return
    now = run.run_time
    if now < getattr(e, "_evo_t", -1.0):
        return
    e._evo_t = now + EVO_PROC_CD
    col = EVO_PERK_COLOR[perk]
    if perk == "burn":
        e.apply_burn(max(1.0, amount * 0.30), 2.5)
        fx.burst(e.x, e.y - 4, col, n=4, speed=70, life=0.35, r=2.4, gravity=-60)
    elif perk == "chill":
        e.apply_slow(0.55, 1.6)
        fx.burst(e.x, e.y, col, n=4, speed=60, life=0.4, r=2.2)
    elif perk == "poison":
        if not getattr(e, "_evo_poison", False):
            e._evo_poison = True
            e.apply_poison(max(0.5, amount * 0.10))
            fx.burst(e.x, e.y, col, n=5, speed=50, life=0.5, r=2.6, gravity=-30)
    elif perk == "leech":
        run.player.lifesteal(amount * 0.04)
    elif perk == "chain" and random.random() < EVO_CHAIN_CHANCE:
        run.evo_chain(e, amount, key)


class EvoMixin:
    """RunState'e evrim davranışı (karışım sınıf: RunState zaten çok uzun)."""


    def evo_init(self):
        self.evo_perks = {}            # evrilmiş silah -> etki
        self.evo_banner = None         # (başlangıç zamanı, silah)
        self.evo_blast_t = 0.0
        self.evo_blasts = 0
        self.player.evolved = set()
        EVO_ON.clear()

    def evo_update(self, dt):
        """Kareye bağlı evrim etkileri (pelerin: vuruşu olmayan silah)."""
        p = self.player
        if "cloak" in p.evolved and getattr(p, "invis_t", 0.0) > 0:
            self.evo_shroud_t = getattr(self, "evo_shroud_t", 0.0) - dt
            if self.evo_shroud_t <= 0:
                self.evo_shroud_t = 0.5
                col = EVO_PERK_COLOR["shroud"]
                dmg = weapon_damage(p, WEAPON_BY_KEY["emanet"], max(1, p.weapons.get("cloak", 1))) * 0.12
                self.fx.ring(p.x, p.y, col, n=12, speed=160, life=0.4, r=2.6)
                for e in self.enemies:
                    if e.alive and not getattr(e, "_evo_poison", False) and \
                            (e.x - p.x) ** 2 + (e.y - p.y) ** 2 < 220 * 220:
                        e._evo_poison = True
                        e.apply_poison(max(0.5, dmg))
                        self.fx.burst(e.x, e.y, col, n=4, speed=50, life=0.45, r=2.4, gravity=-30)

    def evo_offer(self, key):
        w = WEAPON_BY_KEY[key]
        book, perk, col = EVOLUTIONS[key]
        return dict(kind="evo", key=key, w=w, color=col, perk=perk, book=BOOK_BY_KEY.get(book),
                    name=evo_name(key), lvl=self.player.weapons.get(key, 1),
                    desc=L("evo.perk." + perk))

    def evo_inject(self, chosen):
        """Evrime hazır silah varsa elin bir kartı EVRİM kartı olur."""
        if getattr(self, "is_coop", False):
            return chosen
        ready = evo_ready_keys(self.player)
        if not ready or any(c.get("kind") == "evo" for c in chosen):
            return chosen
        off = self.evo_offer(random.choice(ready))
        if len(chosen) < 3:
            return chosen + [off]
        # aynı silahın seviye kartını, yoksa son kartı değiştirir
        victim = len(chosen) - 1
        for i, c in enumerate(chosen):
            if c.get("kind") == "weapon" and c.get("key") == off["key"]:
                victim = i
                break
        chosen = list(chosen)
        chosen[victim] = off
        return chosen

    def evolve_weapon(self, key):
        p = self.player
        book, perk, col = EVOLUTIONS[key]
        p.evolved.add(key)
        EVO_ON.add(key)
        if key == "cloak" and getattr(p, "invis_t", 0.0) <= 0:
            p.cloak_timer = min(getattr(p, "cloak_timer", 0.0), 1.0)
        self.evo_perks[key] = perk
        self.evo_banner = (self.run_time, key)
        self.evo_count = getattr(self, "evo_count", 0) + 1
        fx = self.fx
        fx.do_flash(col, 0.55)
        fx.shake(9, 0.3)
        for k in range(3):
            fx.shockwave(p.x, p.y, 120 + 90 * k, col if k != 1 else WHITE, 0.45 + 0.1 * k, 6 - k)
        fx.ring(p.x, p.y, col, n=40, speed=320, life=0.7, r=4)
        fx.burst(p.x, p.y, lighten(col, 0.4), n=30, speed=220, life=0.8, r=3.5, gravity=-40)
        # evrim dalgası: çevredeki yaratıkları iter
        for e in self.enemies:
            if e.alive:
                d = dist(e.x, e.y, p.x, p.y)
                if 1.0 < d < 260:
                    k = (1.0 - d / 260.0) * 520.0
                    e.knock_x += (e.x - p.x) / d * k
                    e.knock_y += (e.y - p.y) / d * k
        sfx("levelup", 1.0, 0.0)
        sfx("second", 0.8, 0.0)

    def evo_chain(self, src, amount, key):
        cands = []
        for e in self.enemies:
            if e is src or not e.alive or getattr(e, "phased", False):
                continue
            d2 = (e.x - src.x) ** 2 + (e.y - src.y) ** 2
            if d2 < EVO_CHAIN_R * EVO_CHAIN_R:
                cands.append((d2, e))
        if not cands:
            return
        cands.sort(key=lambda c: c[0])
        col = EVO_PERK_COLOR["chain"]
        EVO_BUSY[0] = True
        try:
            prev = src
            for _d, e in cands[:2]:
                self.fx.bolt(zigzag(prev.x, prev.y, e.x, e.y, 6, 9), col, 0.22)
                if e.take_damage(amount * EVO_CHAIN_DMG, False, self.fx, quiet=True):
                    self.on_enemy_killed(e)
                prev = e
        finally:
            EVO_BUSY[0] = False

    def evo_blast(self, src, amount, key):
        sec = int(self.run_time)
        if sec != self.evo_blast_t:
            self.evo_blast_t, self.evo_blasts = sec, 0
        if self.evo_blasts >= EVO_BLAST_PER_SEC:
            return
        self.evo_blasts += 1
        col = EVO_PERK_COLOR["blast"]
        self.fx.shockwave(src.x, src.y, EVO_BLAST_R, col, 0.3, 4)
        self.fx.burst(src.x, src.y, col, n=10, speed=200, life=0.35, r=3.2)
        dmg = amount * EVO_BLAST_DMG
        EVO_BUSY[0] = True
        try:
            for e in self.enemies:
                if e is src or not e.alive:
                    continue
                if (e.x - src.x) ** 2 + (e.y - src.y) ** 2 < EVO_BLAST_R * EVO_BLAST_R:
                    if e.take_damage(dmg, False, self.fx, quiet=True):
                        self.on_enemy_killed(e)
        finally:
            EVO_BUSY[0] = False


def draw_evo_orbs(world, run, t):
    """Evrilmiş her silah için oyuncunun çevresinde dönen küçük bir taş."""
    p = run.player
    keys = [k for k in BOSS_WEAPONS_ORDER if k in getattr(p, "evolved", ())]
    if not keys or not p.alive:
        return
    n = len(keys)
    for i, key in enumerate(keys):
        a = t * 1.6 + i * math.tau / n
        x = p.x + math.cos(a) * (p.radius + 20)
        y = p.y + math.sin(a) * (p.radius + 20) * 0.55 - 6
        col = EVOLUTIONS[key][2]
        add_glow(world, x, y, 16, col, 0.35)
        pts = [(x, y - 6), (x + 4, y), (x, y + 6), (x - 4, y)]
        pygame.draw.polygon(world, INK, [(px + (1 if px > x else -1), py + (1 if py > y else -1))
                                         for px, py in pts])
        pygame.draw.polygon(world, col, pts)
        pygame.draw.line(world, lighten(col, 0.6), (x - 1, y - 4), (x - 2, y), 1)


def draw_evo_banner(surf, run, t):
    """Evrim anında ekranın ortasına inen şerit: "EVRİM!" + "BALTA → KIYAMET BALTASI"."""
    eb = getattr(run, "evo_banner", None)
    if not eb:
        return
    st = run.run_time - eb[0]
    if st < 0 or st > EVO_BANNER_T:
        return
    key = eb[1]
    col = EVOLUTIONS[key][2]
    y = 250
    k = ease_out_cubic(min(1.0, st / 0.3))
    a = min(1.0, (EVO_BANNER_T - st) / 0.5)
    band = pygame.Surface((VIRTUAL_W, 128), pygame.SRCALPHA)
    band.fill((22, 14, 18, int(205 * a * k)))
    surf.blit(band, (0, y - 64))
    for sgn in (-1, 1):
        pygame.draw.line(surf, scale_col(col, 0.4 + 0.5 * a), (0, y + sgn * 64), (VIRTUAL_W, y + sgn * 64), 3)
    # iki yanda dönen ışın yıldızları
    for sgn in (-1, 1):
        cx = VIRTUAL_W / 2 + sgn * 330
        for i in range(8):
            ang = t * 1.4 * sgn + i * math.tau / 8
            r1 = 22 + 6 * math.sin(t * 5 + i)
            pygame.draw.line(surf, col, (cx + math.cos(ang) * 8, y - 12 + math.sin(ang) * 8),
                             (cx + math.cos(ang) * r1, y - 12 + math.sin(ang) * r1), 3)
        blit_sigil(surf, cx, y - 12, 13, key, lighten(col, 0.3))
    size = int(58 + 30 * (1 - k))
    draw_text(surf, L("evo.banner"), (VIRTUAL_W / 2, y - 18), size, col, bold=True, center=True,
              alpha=int(255 * a))
    w = WEAPON_BY_KEY[key]
    sub = "%s  →  %s" % (w_name(w), evo_name(key))
    draw_text(surf, sub, (VIRTUAL_W / 2, y + 28), 20, TEXT, bold=True, center=True, alpha=int(255 * a))
    draw_text(surf, L("evo.perk." + EVOLUTIONS[key][1]), (VIRTUAL_W / 2, y + 50), 13,
              lighten(col, 0.3), center=True, shadow=False, alpha=int(255 * a))


def draw_evo_card(surf, r2, ch, run, t, hover):
    """Seviye elindeki EVRİM kartı: öteki kartlardan belirgin şekilde ayrı."""
    key = ch["key"]
    col = tuple(ch["color"])
    perk = ch["perk"]
    pcol = EVO_PERK_COLOR[perk]
    pulse = 0.5 + 0.5 * math.sin(t * 4.0)
    surf.blit(_panel_shadow(r2.w, r2.h, 18), (r2.x - 6, r2.y - 2))
    surf.blit(_lu_card_bg(r2.w, r2.h, col, 4), r2.topleft)
    # arkada dönen ışınlar
    ecx, ecy = r2.centerx, r2.y + 92
    prev = surf.get_clip()
    surf.set_clip(r2.inflate(-6, -6).clip(prev) if prev else r2.inflate(-6, -6))
    rs = pygame.Surface((r2.w, r2.h), pygame.SRCALPHA)
    for i in range(12):
        a = t * 0.55 + i * math.tau / 12
        pts = [(ecx - r2.x, ecy - r2.y),
               (ecx - r2.x + math.cos(a - 0.08) * 170, ecy - r2.y + math.sin(a - 0.08) * 170),
               (ecx - r2.x + math.cos(a + 0.08) * 170, ecy - r2.y + math.sin(a + 0.08) * 170)]
        pygame.draw.polygon(rs, (*col, 34), pts)
    surf.blit(rs, r2.topleft)
    surf.set_clip(prev)
    ink_frame(surf, r2, lighten(col, 0.2 * pulse), 18, 4)
    ink_frame(surf, r2.inflate(-10, -10), scale_col(col, 0.5), 14, 1)
    # üst şerit
    band = pygame.Rect(r2.x + 3, r2.y + 3, r2.w - 6, 30)
    pygame.draw.rect(surf, scale_col(col, 0.55), band, border_top_left_radius=15, border_top_right_radius=15)
    pygame.draw.rect(surf, col, band.inflate(0, -6).move(0, -3), border_top_left_radius=14,
                     border_top_right_radius=14)
    bt = L("evo.band")
    draw_text(surf, bt, (band.centerx, band.centery - 2), 16, (28, 18, 20), bold=True, center=True,
              shadow=False)
    tw_ = text_width(bt, 16, True)
    for s_ in (-1, 1):
        _sparkle(surf, band.centerx + s_ * (tw_ / 2 + 14), band.centery - 2, 5 + pulse * 1.5,
                 (28, 18, 20))
    # arma: silah ve çevresinde dönen taç dişleri
    hh = 92 if hover else 86
    for i in range(14):
        a = t * 0.9 + i * math.tau / 14
        r0, r1 = hh * 0.56, hh * (0.66 + 0.04 * math.sin(t * 3 + i))
        thick_line(surf, (ecx + math.cos(a) * r0, ecy + math.sin(a) * r0),
                   (ecx + math.cos(a) * r1, ecy + math.sin(a) * r1), 3, col)
    draw_weapon_emblem(surf, ecx, ecy, hh, ch["w"], t)
    for i in range(6):
        ph = (t * 0.7 + i * 0.29) % 1.0
        a = i * math.tau / 6 + t * 0.3
        _sparkle(surf, ecx + math.cos(a) * (60 + 10 * ph), ecy + math.sin(a) * (60 + 10 * ph) - 18 * ph,
                 4.5 * math.sin(ph * math.pi), lighten(col, 0.5))
    # ad
    nm, nsz = ms_fit(ch["name"], 19, r2.w - 24, True)
    draw_text(surf, nm, (r2.centerx, r2.y + 152), nsz, lighten(col, 0.35), bold=True, center=True)
    pill = "%s  →  %s" % (_fit_text(w_name(ch["w"]), 11, (r2.w - 60) // 2, True), L("evo.short"))
    pw_ = text_width(pill, 11, True) + 18
    pr_ = pygame.Rect(0, 0, pw_, 18)
    pr_.center = (r2.centerx, r2.y + 174)
    pygame.draw.rect(surf, (23, 17, 18), pr_, border_radius=9)
    ink_frame(surf, pr_, scale_col(col, 0.8), 9, 1)
    draw_text(surf, pill, pr_.center, 11, lighten(col, 0.2), bold=True, center=True, shadow=False)
    # satırlar: hasar + etki + tarif
    box = pygame.Rect(r2.x + 14, r2.y + 190, r2.w - 28, 94)
    pygame.draw.rect(surf, (20, 15, 15), box, border_radius=10)
    ink_frame(surf, box, scale_col(col, 0.45), 10, 1)
    draw_text(surf, L("evo.dmg"), (box.x + 10, box.y + 9), 13, (176, 170, 160), shadow=False)
    draw_text(surf, "x%.1f" % EVO_DMG_MULT, (box.right - 10, box.y + 8), 15, GREEN, bold=True,
              right=True, shadow=False)
    draw_icon(surf, box.x + 18, box.y + 44, EVO_PERK_ICON[perk], pcol, 8)
    for i, ln in enumerate(wrap_text(ch["desc"], 13, box.w - 44)[:2]):
        draw_text(surf, ln, (box.x + 32, box.y + 36 + i * 16), 13, pcol, bold=True, shadow=False)
    bk = ch.get("book")
    req = L("evo.need", EVO_LEVEL, bk_name(bk) if bk else "?")
    draw_text(surf, _fit_text(req, 11, box.w - 16), (box.centerx, box.bottom - 15), 11, TEXT_DIM,
              center=True, shadow=False)
    if hover:
        br = pygame.Rect(r2.x + 18, r2.bottom - 44, r2.w - 36, 32)
        face = key_button(surf, br, col, True, rad=10)
        draw_text(surf, L("evo.pick"), face.center, 16, (28, 18, 20), bold=True, center=True,
                  shadow=False)
    else:
        draw_text(surf, L("evo.ready"), (r2.centerx, r2.bottom - 28), 12, lighten(col, 0.2 * pulse),
                  bold=True, center=True, shadow=False)


class RunState(EvoMixin, WorldExtrasMixin):
    def __init__(self, save, skin_id, diff="normal", ach=None):
        self.save = save
        self.diff = diff
        self.player = Player(skin_id)
        self.player.cosmetics = save.equipped_cosmetics()
        self.player.apply_cosmetic_perks()
        self.enemies = []
        # Geç dalgalarda aynı anda birden fazla patron gelebildiği için tek bir
        # boss değil, yaşayan patronların listesi tutuluyor.
        self.bosses = []
        self.hazards = []
        self.pickups = []
        self.enemy_projectiles = []
        self.player_projectiles = []
        self.dmg_log = {}           # kaynak -> verilen toplam hasar
        self.fx = EffectSystem()
        self.evo_init()
        self.extras_init()
        self.waves = WaveManager(diff)
        # Düşmanlar dünyanın kenarından değil, kameranın hemen dışından gelir.
        self.waves.spawn_pos_fn = self.near_camera_point
        self.combo = ComboMeter()
        self.ach = ach
        # Arkada kalan yaratıkları önüne ışınlama sayacı
        self.straggler_timer = 0.0

        # ---- kamera ----
        # Dünya ekrandan büyük olduğu için kamera oyuncuyu yumuşak takip eder.
        self.cam_x = clamp(self.player.x - VIEW_RECT.w / 2,
                           ARENA_RECT.left, ARENA_RECT.right - VIEW_RECT.w)
        self.cam_y = clamp(self.player.y - VIEW_RECT.h / 2,
                           ARENA_RECT.top, ARENA_RECT.bottom - VIEW_RECT.h)
        # ---- bölge ----
        self.biome = "arena"          # "arena" | "hell"
        self.hell_portal = None       # 25. dalga patronundan sonra açılan mor portal

        self.kills = 0
        # zaman durdu sayacı: skin yetenekleri düşmanları bu süre boyunca
        # dondurur.
        self.time_stop = 0.0
        self.bonk_hits = 0          # bu koşuda bonk ile vurulan düşman sayısı
        self.coins_earned = 0
        self.gem_coins = 0.0        # elmas hesabı için eski birimle altın
        self.score_frac = 0.0       # yarım skorların küsuratı
        self.gold_wallet = 0
        self.run_time = 0.0
        self.score = 0
        self.game_over = False
        self.submitted_online = False
        # hile koruması (3. katman): koşu denetimi. Bir kez bozulduysa düzelmez
        # - hile yapılıp geri alınan bir koşu da geçersizdir.
        self.cheat_flag = ""        # boş = temiz, dolu = takılan denetim
        self.integrity_timer = 0.0
        # Cehenneme girerken arenada ulaşılan dalga.
        self.arena_waves = 0
        self.pending_levelups = 0
        self.levelup_choices = []
        # ---- seviye atlama: yenileme ve pas ----
        # İlk REROLL_FREE yenileme ve SKIP_FREE pas bedava; sonrası altınla ve
        # her kullanımda pahalanır. Sayaçlar koşu boyunca birikir.
        self.reroll_used = 0
        self.skip_used = 0
        # ---- gizli denge ----
        # Her koşunun kendi "kader tohumu" var: hangi silah/kitapların bu
        # koşuda hiç gelmeyeceği buradan belirleniyor. Oyuncuya gösterilmez.
        self.destiny_seed = random.randrange(1 << 30)
        self.destiny_locked = set()
        self.offer_seen = {}
        self.shop_offers = []
        self.market_portal = None
        self.want_open_shop = False
        self.bonk8_check = False
        self.gems_earned = 0
        # yeni rekor: koşu başındaki kişisel rekor; geçildiği an ekranda büyük
        # bir "YENİ REKOR!" çıkar.
        self.best_at_start = int(save.data.get("stats", {}).get("best_score", 0) or 0)
        self.record_beaten = False
        self.record_flash = -1.0       # >= 0: damga gösteriliyor (geçen süre)
        self.death_cause = ""
        # Sağ üstteki "⋮" istatistik paneli açık mı?
        self.show_stats = False
        # M tuşuyla açılan büyük harita açık mı? (oyun bu sırada durmaz)
        self.show_map = False
        # Patron sandıkları (devrilen patronun yerine düşer)
        self.chests = []
        # anahtarlar + efsanevi sandık
        self.map_keys = []
        self.keys_got = 0
        self.keys_placed = False
        self.key_respawn_t = 0.0
        self.legend_chest = None
        self.legend_opened = 0
        self.legend_hands = 0
        # ---- yeni silahların dünya nesneleri ----
        self.water_zones = []       # zemzem birikintileri
        self.fire_rings = []        # baran'IN papucu ateş halkaları
        self.sword_slashes = []     # emanet'in çizdiği yaylar (yalnızca görsel)
        self.tornados = []          # hortum
        self.black_holes = []       # kara delik (Kozmik Gezgin yeteneği)
        self.flying_axes = []       # uçan baltalar
        self.whip_lashes = []       # kırbaç savuruş izleri
        # yeni silahlar
        self.ghost_blades = []      # hayalet kılıçlar (kalıcı minyonlar)
        self.wolves = []            # kurt sürüsü (kalıcı minyonlar)
        self.meteors = []           # meteor yağmuru göktaşları
        self.beams = []             # güneş ışını
        # 2. paket
        self.hawks = []             # şahin (kalıcı minyonlar)
        self.bats = []              # yarasa sürüsü yarasaları
        self.novas = []             # ayaz patlaması görselleri
        self.knives = []            # bıçak yelpazesi bıçakları
        self.quakes = []            # deprem halkaları
        self.bat_heal_budget = 0.0  # yarasa iyileştirmesinin saniye kovası
        self.minion_t = 0.0         # minyonların ortak saati (yörünge fazı)
        self.wolf_howl_cd = 6.0     # ilk sürü ulumasına kalan süre
        # pentagram: şu an mührün içinde olan yaratıklar. Küme her tikte
        # yalnızca O an içeride olanlarla yeniden kurulduğu için nesneleri
        # tutmak sızıntı yapmaz.
        self.penta_inside = set()
        # ---- mıknatıs ----
        self.magnets = []           # yerde duran mıknatıslar
        self.level_drops = []       # yerde duran seviye taşları (mor)
        self.level_kills = 0        # son seviye taşından bu yana öldürme
        self.magnet_kills = 0       # son mıknatıstan bu yana yapılan öldürme
        self.magnets_taken = 0      # bu koşuda toplanan mıknatıs sayısı
        self.magnets_dropped = 0    # bu koşuda düşen mıknatıs (seviye taşı bunu geçemez)
        self.level_drops_total = 0  # bu koşuda düşen seviye taşı
        self.chests_opened = 0      # açılan patron sandığı (şans kitabı görevi)
        self.reroll_bonus = 0       # kitap kartından kazanılan bedava yenileme
        self.goblins_caught = 0     # bu koşuda yakalanan hazine goblini
        # ---- lanetli sandık ----
        self.curses = {}            # kabul edilen lanetler {anahtar: seviye}
        self.waves.curses = self.curses
        self.curse_score_bonus = 0.0
        self.cursed_shrine = None   # haritadaki mağara ağzı (en çok bir tane)
        self.curse_offers = None    # açık teklif ekranı (liste) ya da None
        self.cursed_taken = 0       # bu koşuda kabul edilen lanetli teklif
        self.cursed_seen_wave = 0   # sandığın en son hangi dalgada belirdiği
        self.cursed_next_wave = CURSED_FIRST_WAVE   # (eski) 999 = kendiliğinden yerleşmez
        self.cursed_spawns = 0      # bu koşuda yerleşen mağara (en çok CURSED_MAX)
        self.corpses = []           # ölü çağırıcı için: (x, y, ölüm anı)
        # Koşu bitince doldurulur: bu koşuda kilidi açılan silah ve kitaplar.
        self.new_weapons = []
        self.new_books = []
        # ---- her koşu farklı ----
        self.map_theme = "stone"    # harita (App.start_run oyuncunun seçtiğini kurar)
        # koşu başında açık haritalar (ölüm ekranındaki "yeni harita" için)
        self.maps_at_start = [m for m in MAP_THEMES if map_unlocked(save, m)]
        self.theme_hp = 0.0         # haritanın yaratık canı payı (yalnız arenada)
        self.theme_speed = 1.0
        self.theme_spawn = 1.0
        self.oath = None            # koşu başında edilen yemin
        self.oath_speed = 1.0       # yeminin yaratık hızı çarpanı
        self.oath_spawn = 1.0       # yeminin doğum sıklığı çarpanı
        # gezgin tüccar. Koşu boyunca haritanın bir yerinde durur (haritada
        # gösterilmez); konuşmak isteğe bağlı.
        self.merchant = None
        self.merchant_open = False
        self.merchant_hand = []     # [(yemin, kademe), ...] - bir kez çekilir
        self.merchant_hand_lvl = 0  # elin çekildiği seviye (bilgi amaçlı)
        self.merchant_rerolls = 0   # altınla yapılan yenileme sayısı (en çok 3)
        self.oath_tier = 0          # edilen yeminin kademesi (0 Yaygın .. 4 Efsanevi)
        self.oath_period = OATH_BULWARK_EVERY
        self.oath_t = 0.0           # sur yemini: kalkan dolum sayacı
        self.quests = []            # koşu görevleri
        self.snakes_killed = 0      # zümrüt orman yılanları (başarım)
        self.doom_warned = False
        self.quest_gems = 0         # bu koşuda görevlerden ödenen elmas
        self.quest_t = 0.0
        self.quest_flash = 0.0      # HUD'daki görev kutusunun parlama süresi
        self.legend_taken = False   # bu koşuda efsanevi bir şey alındı mı (görev)
        # Kader kilidini şimdi at: havuz koşu boyunca sabit kalsın.
        self._roll_destiny()

    # ---- harita ----
    def set_map_theme(self, theme):
        """Koşunun haritasını kurar: zemin + harita kuralı."""
        if theme not in MAP_RULES:
            theme = "stone"
        p = self.player
        old = MAP_RULES.get(self.map_theme, {})
        # (önceki haritanın oyuncu paylarını geri al - tur/test iki kez
        # çağırabilir)
        p.run_xp_mult -= old.get("xp", 0.0)
        p.run_coin_mult -= old.get("gold", 0.0)
        self.map_theme = theme
        r = MAP_RULES[theme]
        self.theme_hp = r.get("enemy_hp", 0.0)
        self.theme_speed = r.get("enemy_speed", 1.0)
        self.theme_spawn = r.get("spawn_rate", 1.0)
        p.run_xp_mult += r.get("xp", 0.0)
        p.run_coin_mult += r.get("gold", 0.0)
        self._apply_wave_mods()

    # ---- harita başarımları ----
    def map_stat_values(self):
        """Bu koşunun, oynanan haritanın sayaçlarına katkısı {sayaç: değer}."""
        th = self.map_theme
        if th == "stone":
            return {}
        p = self.player
        src = {"kills": int(self.kills), "bosses": int(getattr(self, "bosses_killed", 0)),
               "shots": int(p.run_shots), "dashes": int(p.dash_count),
               "bonk_hits": int(self.bonk_hits), "wave": int(self.total_wave()),
               "wind": int(p.books.get("r_spd", 0)), "time": int(self.run_time),
               "snakes": int(self.snakes_killed)}
        return {st: src[MAP_STAT_SRC[st]] for st, (mp, _m) in MAP_ACH_STATS.items() if mp == th}

    def map_stat_total(self, stat, run_value):
        """Kayıttaki sayaç + bu koşu (toplam ya da en iyi)."""
        have = self.save.data.get("stats", {}).get(stat, 0) or 0
        if MAP_ACH_STATS[stat][1] == "sum":
            return have + run_value
        return max(have, run_value)

    def check_map_achs(self):
        """Harita başarımı koşu içinde dolduysa hemen açılır (bildirim gelir)."""
        if self.ach is None:
            return
        for stat, v in self.map_stat_values().items():
            tot = self.map_stat_total(stat, v)
            for a in MAP_ACHS:
                tr = a["track"]
                if tr["stat"] == stat and tot >= tr["need"] and not self.ach.has(a["id"]):
                    # sayaç kayda koşu sonunda yazılır; başarım şimdi açılır
                    self.ach.unlock(a["id"])

    def commit_map_stats(self):
        """Koşu bitti: harita sayaçlarını kayda yazar."""
        st = self.save.data.setdefault("stats", {})
        for stat, v in self.map_stat_values().items():
            st[stat] = self.map_stat_total(stat, v)

    # ---- koşu görevleri ----
    def roll_quests(self, rnd=random):
        """Kolay / orta / zor birer görev (üçü de farklı türden)."""
        keys = list(QUEST_DEFS)
        rnd.shuffle(keys)
        used, out = set(), []
        for tier in range(3):
            for k in keys:
                goal = QUEST_DEFS[k][2][tier]
                if k in used or goal is None:
                    continue
                used.add(k)
                out.append({"key": k, "tier": tier, "goal": int(goal), "done": False})
                break
        self.quests = out
        return out

    def quest_value(self, key):
        """Görevin şu anki ilerlemesi."""
        if key == "kills":
            return int(self.kills)
        if key == "wave":
            return int(self.total_wave())
        if key == "level":
            return int(self.player.level)
        if key == "gold":
            return int(self.coins_earned)
        if key == "combo":
            return int(self.combo.best)
        if key == "boss":
            return int(getattr(self, "bosses_killed", 0))
        if key == "cave":
            return int(self.cursed_taken)
        return 0

    def update_quests(self):
        """Biten görevi işaretler ve kutlar (ödeme finish_run'da)."""
        p = self.player
        for q in self.quests:
            if q["done"] or self.quest_value(q["key"]) < q["goal"]:
                continue
            q["done"] = True
            col = QUEST_TIER_COLORS[q["tier"]]
            gems = QUEST_GEMS[q["tier"]]
            # oyuncunun altında: sunak/sandık yazılarıyla üst üste binmesin
            self.fx.popup(p.x, p.y + 74, L("q.done"), col, 26, life=2.2)
            self.fx.popup(p.x, p.y + 100, L("q." + q["key"], q["goal"]) + "  +%d" % gems,
                          GEM_COLOR, 16, life=2.2)
            self.fx.ring(p.x, p.y, col, n=26, speed=260, life=0.6, r=3.5)
            self.quest_flash = 2.4
            sfx("ach", 0.8, 0.0)

    def quest_gems_due(self):
        return sum(QUEST_GEMS[q["tier"]] for q in self.quests if q["done"])

    # ---- gezgin tüccar ----
    def spawn_merchant(self):
        """Tüccar koşu başında haritanın bir yerinde belirir ve koşu boyunca orada kalır."""
        p = self.player
        cam = self.cam_rect().inflate(120, 120)
        x = y = 0.0
        for _ in range(80):
            x = random.uniform(ARENA_RECT.left + 220, ARENA_RECT.right - 220)
            y = random.uniform(ARENA_RECT.top + 240, ARENA_RECT.bottom - 160)
            if 650 < dist(x, y, p.x, p.y) < 1150 and not cam.collidepoint(x, y):
                break
        self.merchant = Merchant(x, y)
        self.merchant_hand = []
        self.merchant_hand_lvl = 0
        self.merchant_rerolls = 0
        self.fx.popup(p.x, p.y - 96, L("m.hint"), MERCHANT_COLOR, 18, life=4.0)

    def merchant_luck(self):
        """Tüccarın kademe şansı: oyuncunun şansı + seviye başına pay."""
        p = self.player
        return p.eff_luck() + MERCHANT_LUCK_PER_LEVEL * max(0, int(p.level) - 1)

    def _roll_merchant_hand(self):
        luck = self.merchant_luck()
        old = {k for k, _t in self.merchant_hand}
        pool = [k for k, _i, _c in OATHS]
        # yenilemede mümkünse eski elin yeminleri gelmesin (gerçekten "yeni")
        fresh = [k for k in pool if k not in old]
        keys = random.sample(fresh if len(fresh) >= 3 else pool, 3)
        self.merchant_hand = [(k, roll_rarity(luck)) for k in keys]
        self.merchant_hand_lvl = int(self.player.level)

    def merchant_offers(self):
        """Tüccarın eli: 3 farklı yemin, her biri kendi kademesiyle."""
        if not self.merchant_hand:
            self._roll_merchant_hand()
        return list(self.merchant_hand)

    def merchant_reroll_left(self):
        return max(0, MERCHANT_REROLLS - int(self.merchant_rerolls))

    def merchant_reroll_price(self):
        return merchant_reroll_cost(self.waves.wave, self.merchant_rerolls)

    def merchant_reroll(self):
        """Eli altınla yeniler."""
        if self.oath is not None:
            return False, "sworn"
        if self.merchant_reroll_left() <= 0:
            return False, "none"
        cost = self.merchant_reroll_price()
        if self.gold_wallet < cost:
            return False, "gold"
        self.gold_wallet -= cost
        self.merchant_rerolls += 1
        self._roll_merchant_hand()
        return True, ""

    def update_merchant(self, dt, input_state, portal_used=False):
        m = self.merchant
        if m is None:
            return
        m.update(dt)
        p = self.player
        if (not portal_used and not self.merchant_open and p.alive and self.curse_offers is None
                and input_state.get("use_pressed") and m.in_range(p)):
            self.merchant_offers()
            self.merchant_open = True

    def choose_oath(self, key, tier=0):
        """Tüccar ekranında seçilen yemin (None: vazgeç)."""
        if key is not None and self.oath is None:
            self.apply_oath(key, tier)
            if self.merchant is not None:
                self.merchant.done = True
        self.merchant_open = False

    def _scale_max_hp(self, f):
        p = self.player
        p.max_hp = max(30, int(round(p.max_hp * f)))
        p.hp = p.max_hp

    def apply_oath(self, key, tier=0):
        """yemin: koşu boyunca bir artı, bir eksi."""
        p = self.player
        if key not in OATH_BY_KEY:
            self.oath = None
            return
        self.oath = key
        self.oath_tier = tier = int(clamp(int(tier), 0, RARITY_COUNT - 1))
        v = oath_values(key, tier)
        if key == "glass":
            p.run_dmg_mult += v[0]
            self._scale_max_hp(0.75)
        elif key == "gold_fever":
            p.run_coin_mult += v[0]
            p.enemy_hp_curse += 0.10
        elif key == "turtle":
            p.max_hp += int(v[0])
            p.hp = p.max_hp
            p.run_armor_bonus += v[1]
            p.run_spd_mult -= 0.07
        elif key == "scholar":
            p.run_xp_mult += v[0]
            p.run_dmg_mult -= 0.12
        elif key == "gambler":
            p.run_luck_bonus += v[0]
            self._scale_max_hp(0.85)
        elif key == "blood":
            p.vamp_level += v[0] / 0.02         # can çalma = 0.02 x seviye
            p.regen_mult = 0.0
        elif key == "wind":
            p.run_spd_mult += v[0]
            p.dash_dist_mult += v[1]
            self.oath_speed = 1.10
        elif key == "bulwark":
            p.shield_charges += int(v[0])
            self.oath_period = float(v[1])
            p.run_aspd_mult -= 0.10
            self.oath_t = 0.0
        elif key == "hunter":
            p.boss_hunter += v[0]
            p.run_coin_mult -= 0.10
        elif key == "feast":
            p.run_xp_mult += v[0]
            p.run_coin_mult += v[0]
            self.oath_spawn = 1.15
        elif key == "hoard":
            self.gold_wallet += int(v[0])
            p.run_xp_mult -= 0.10
        elif key == "hawkeye":
            p.run_crit_bonus += v[0]
            p.run_critdmg_bonus += v[1]
            p.run_aspd_mult -= 0.10
        self._apply_wave_mods()

    def _apply_wave_mods(self):
        """Harita (yalnız arenada) + yemin çarpanlarını dalga yöneticisine yazar."""
        arena = self.biome != "hell"
        self.waves.enemy_speed_mult = (self.theme_speed if arena else 1.0) * self.oath_speed
        self.waves.spawn_rate_mult = (self.theme_spawn if arena else 1.0) * self.oath_spawn
        self.waves.theme = self.map_theme if arena else "stone"
        self.waves.doom = self.map_theme != "stone"

    # ---- kamera ----
    def cam_rect(self):
        return pygame.Rect(int(self.cam_x), int(self.cam_y), VIEW_RECT.w, VIEW_RECT.h)

    def update_camera(self, dt, snap=False):
        p = self.player
        tx = clamp(p.x - VIEW_RECT.w / 2, ARENA_RECT.left, ARENA_RECT.right - VIEW_RECT.w)
        ty = clamp(p.y - VIEW_RECT.h / 2, ARENA_RECT.top, ARENA_RECT.bottom - VIEW_RECT.h)
        k = 1.0 if snap else min(1.0, dt * 7.0)
        self.cam_x += (tx - self.cam_x) * k
        self.cam_y += (ty - self.cam_y) * k

    def screen_to_world(self, sx, sy):
        return screen_to_world(sx, sy, self.cam_rect())

    def world_to_screen(self, wx, wy):
        return world_to_screen(wx, wy, self.cam_rect())

    # ---- köşe / AFK kampı ----
    # Kenarda/köşede ya da yerinden kıpırdamadan duran oyuncunun çevresinde,
    # görüş alanının içinde de yaratık doğar (doğuş animasyonuyla, oyuncunun
    # dibinde değil).
    CAMP_EDGE = 460.0           # dünya kenarına bu kadar yakın = kenar kampı
    CAMP_STILL_R = 170.0        # bu yarıçapın içinde kalan oyuncu "duruyor"
    CAMP_STILL_T = 7.0          # ... bu kadar süre durursa AFK sayılır
    CAMP_RING = (230.0, 430.0)  # içeride doğum halkası (oyuncuya uzaklık)

    def _update_camping(self, dt):
        p = self.player
        a = getattr(self, "_camp_anchor", None)
        if a is None or math.hypot(p.x - a[0], p.y - a[1]) > self.CAMP_STILL_R:
            self._camp_anchor = (p.x, p.y)
            self._camp_still = 0.0
        else:
            self._camp_still = getattr(self, "_camp_still", 0.0) + dt
        edge = min(p.x - ARENA_RECT.left, ARENA_RECT.right - p.x,
                   p.y - ARENA_RECT.top, ARENA_RECT.bottom - p.y)
        corner = (min(p.x - ARENA_RECT.left, ARENA_RECT.right - p.x) < self.CAMP_EDGE
                  and min(p.y - ARENA_RECT.top, ARENA_RECT.bottom - p.y) < self.CAMP_EDGE)
        f = 0.0
        if edge < self.CAMP_EDGE:
            f = 0.35
        if corner:
            f = 0.60
        if self._camp_still >= self.CAMP_STILL_T:
            f = min(0.85, f + 0.45)
        self._camp_factor = f
        if f >= 0.6 and p.alive and not getattr(self, "_camp_warned", False):
            self._camp_warned = True
            self.fx.popup(p.x, p.y - 100, L("fx.no_camping"), (255, 150, 120), 20, life=2.4)

    def _camp_spawn_point(self):
        p = self.player
        for _ in range(14):
            a = random.uniform(0, math.tau)
            r = random.uniform(*self.CAMP_RING)
            x, y = p.x + math.cos(a) * r, p.y + math.sin(a) * r
            if ARENA_RECT.inflate(-40, -40).collidepoint(x, y):
                return x, y
        return None

    def near_camera_point(self, margin=60):
        """Kameranın hemen dışında, dünyanın içinde kalan bir doğum noktası."""
        cam = self.cam_rect()
        # köşe / AFK kampı - doğumların bir payı oyuncunun çevresinde
        camp = getattr(self, "_camp_factor", 0.0)
        if camp > 0 and self.player.alive and random.random() < camp:
            pt = self._camp_spawn_point()
            if pt is not None:
                return pt
        # önden doğum: dünya 5x5 olunca kaçmak kolaylaştı.
        ahead = self._ahead_spawn_chance()
        if ahead > 0 and random.random() < ahead:
            p = self.player
            sp = math.hypot(p.vx, p.vy)
            if p.alive and sp > 60:
                pt = self._ahead_spawn_point(p, p.vx / sp, p.vy / sp, cam)
                if pt is not None:
                    return pt
        for _ in range(12):
            side = random.randint(0, 3)
            if side == 0:
                x, y = random.uniform(cam.left, cam.right), cam.top - margin
            elif side == 1:
                x, y = random.uniform(cam.left, cam.right), cam.bottom + margin
            elif side == 2:
                x, y = cam.left - margin, random.uniform(cam.top, cam.bottom)
            else:
                x, y = cam.right + margin, random.uniform(cam.top, cam.bottom)
            if ARENA_RECT.collidepoint(x, y):
                return x, y
        for _ in range(30):
            a = random.uniform(0, math.tau)
            rr = max(cam.w, cam.h) * random.uniform(0.55, 0.75)
            x = cam.centerx + math.cos(a) * rr
            y = cam.centery + math.sin(a) * rr
            if (ARENA_RECT.inflate(-40, -40).collidepoint(x, y)
                    and not cam.inflate(-80, -80).collidepoint(x, y)):
                return x, y
        pt = self._camp_spawn_point()
        if pt is not None:
            return pt
        return ARENA_RECT.centerx, ARENA_RECT.centery

    # ---- kaçanın önüne ışınlanma ----
    # Kaçmak hâlâ mümkün ama bedava değil.
    STRAGGLER_CHECK = 0.45      # kaç saniyede bir bakılır
    STRAGGLER_MIN_SPEED = 95.0  # bu hızın altında "kaçıyor" sayılmaz
    STRAGGLER_BEHIND = 0.25     # arkada sayılması için gereken yön farkı (-1..1)
    STRAGGLER_FAR = 680.0       # bu mesafeden uzaktakiler ışınlanabilir
    STRAGGLER_MAX = 4           # tek seferde en fazla kaç yaratık ışınlanır
    STRAGGLER_COOLDOWN = 3.2    # aynı yaratık tekrar ışınlanana kadar geçen süre
    # Kaçış yönünde ne kadar ileriye bırakılacağı - kameranın hemen dışı.
    STRAGGLER_AHEAD_MIN = VIEW_RECT.w * 0.60
    STRAGGLER_AHEAD_MAX = VIEW_RECT.w * 0.85

    def reposition_stragglers(self, dt):
        """Oyuncunun arkasında kalan yaratıkları kaçış yönünün önüne ışınlar."""
        p = self.player
        if not p.alive:
            return
        self.straggler_timer -= dt
        if self.straggler_timer > 0:
            return
        self.straggler_timer = self.STRAGGLER_CHECK

        # Kaçış yönü: oyuncunun gerçek hızı (dash sırasında dash yönü).
        if p.dash_time > 0:
            mvx, mvy = p.dash_dx, p.dash_dy
            speed = p.dash_speed
        else:
            speed = math.hypot(p.vx, p.vy)
            if speed < 1e-3:
                return
            mvx, mvy = p.vx / speed, p.vy / speed
        if speed < self.STRAGGLER_MIN_SPEED:
            return

        # Bekleme süreleri önce topluca işlenir; aksi hâlde kontenjan dolunca
        # listenin sonundaki yaratıkların sayacı hiç azalmaz ve sonsuza kadar
        # "beklemede" kalırlardı.
        ready = []
        for e in self.enemies:
            if not e.alive or getattr(e, "is_boss", False):
                continue
            # sancaktar ve sipercileri ışınlanmaz: ışınlanma koruma düzenini
            # bozar, sancaktar korumasız kalır ve bulmaca anlamını yitirir.
            if getattr(e, "is_mini", False) or getattr(e, "guard_of", None) is not None:
                continue
            cd = getattr(e, "warp_cd", 0.0)
            if cd > 0:
                e.warp_cd = max(0.0, cd - self.STRAGGLER_CHECK)
            else:
                ready.append(e)

        cam = self.cam_rect()
        moved = 0
        for e in ready:
            if moved >= self.STRAGGLER_MAX:
                break
            dx, dy = e.x - p.x, e.y - p.y
            d = math.hypot(dx, dy)
            if d < self.STRAGGLER_FAR:
                continue
            # Oyuncunun gittiği yöne göre arkada mı? (nokta çarpımı negatifse
            # arkada)
            if (dx * mvx + dy * mvy) / max(1e-3, d) > -self.STRAGGLER_BEHIND:
                continue
            spot = self._ahead_spawn_point(p, mvx, mvy, cam)
            if spot is None:
                continue
            self.fx.ring(e.x, e.y, e.color, n=10, speed=150, life=0.28, r=2.5)
            e.x, e.y = spot
            e.warp_cd = self.STRAGGLER_COOLDOWN
            e.spawn_t = min(e.spawn_t, 0.12)   # küçülüp büyüyerek "doğsun"
            self.fx.ring(e.x, e.y, e.color, n=14, speed=200, life=0.34, r=3)
            moved += 1

    AHEAD_SPAWN_FROM = 10       # bu dalgadan itibaren önden doğum başlar
    AHEAD_SPAWN_BASE = 0.20     # ilk dalgadaki pay
    AHEAD_SPAWN_STEP = 0.025    # her dalgada artış
    AHEAD_SPAWN_MAX = 0.65

    def _ahead_spawn_chance(self):
        """Yeni yaratığın oyuncunun önünde doğma olasılığı (dalgaya göre)."""
        w = int(getattr(self.waves, "wave", 1) or 1)
        if self.biome == "hell":
            w += 25                    # cehennem, taş meydanın 25. dalgasının devamı
        if w < self.AHEAD_SPAWN_FROM:
            return 0.0
        return min(self.AHEAD_SPAWN_MAX,
                   self.AHEAD_SPAWN_BASE + (w - self.AHEAD_SPAWN_FROM) * self.AHEAD_SPAWN_STEP)

    def _ahead_spawn_point(self, p, mvx, mvy, cam):
        """Kaçış yönünde, kameranın hemen dışında kalan bir doğum noktası."""
        for _ in range(14):
            spread = random.uniform(-0.75, 0.75)
            ca, sa = math.cos(spread), math.sin(spread)
            ax = mvx * ca - mvy * sa
            ay = mvx * sa + mvy * ca
            d = random.uniform(self.STRAGGLER_AHEAD_MIN, self.STRAGGLER_AHEAD_MAX)
            x, y = p.x + ax * d, p.y + ay * d
            if not ARENA_RECT.inflate(-60, -60).collidepoint(x, y):
                continue
            if cam.inflate(60, 60).collidepoint(x, y):
                continue     # görüş alanının içinde belirmesin
            return x, y
        return None

    def wave_hp_mult(self, wave):
        if self.biome == "hell":
            # Cehennem yaratıkları arenanın 25. dalgası kadar canlı başlar.
            base = hell_hp_mult(wave)
        else:
            base = arena_hp_mult(wave) * (1.0 + getattr(self, "theme_hp", 0.0))
        return base * (1.0 + self.player.enemy_hp_curse)

    def open_shop(self):
        self.shop_offers = SHOP_ITEMS

    def spawn_market_portal(self):
        """Kaldırıldı."""
        self.market_portal = None

    def open_hell_portal(self):
        """25. dalga patronu devrildiğinde mor portalı açar."""
        # Taş Meydan bitti - bir sonraki harita açılır
        self.save.data.setdefault("stats", {})["stone_cleared"] = 1
        p = self.player
        for _ in range(24):
            ang = random.uniform(0, math.tau)
            d = random.uniform(150, 300)
            x = clamp(p.x + math.cos(ang) * d, ARENA_RECT.left + 90, ARENA_RECT.right - 90)
            y = clamp(p.y + math.sin(ang) * d, ARENA_RECT.top + 90, ARENA_RECT.bottom - 90)
            if dist(x, y, p.x, p.y) > 120:
                break
        self.hell_portal = HellPortal(x, y)
        self.fx.do_flash(HELL_PORTAL_COLOR, 0.65)
        self.fx.shake(14, 0.5)
        for k in range(4):
            self.fx.shockwave(x, y, 120 + k * 150, HELL_PORTAL_COLOR, 0.7, 7 - k)
        self.fx.burst(x, y, HELL_PORTAL_COLOR2, n=40, speed=300, life=0.9, r=4)
        self.fx.popup(p.x, p.y - 70, "CEHENNEM KAPISI AÇILDI!", HELL_PORTAL_COLOR2, 30, life=2.4)
        self.waves.announce_timer = 3.2
        self.waves.announce_text = "CEHENNEM KAPISI AÇILDI - E İLE GİR"
        sfx("boss", 1.0, 0.0)

    def enter_hell(self):
        """Portala girildiğinde 2. haritaya (cehennem) geçer."""
        if self.biome == "hell":
            return
        p = self.player
        self.biome = "hell"
        self.hell_portal = None
        self.market_portal = None
        self.enemies.clear()
        self.bosses = []
        self.hazards.clear()
        self.enemy_projectiles.clear()
        self.player_projectiles.clear()
        self.collect_all_pickups()
        self.pickups.clear()
        # Arenada kalan su/ateş/hortum ve uçan baltalar cehenneme taşınmaz.
        self.water_zones.clear()
        self.fire_rings.clear()
        self.sword_slashes.clear()
        self.tornados.clear()
        self.black_holes = []
        self.flying_axes.clear()
        self.whip_lashes.clear()
        self.meteors.clear()
        self.beams.clear()
        self.bats.clear()
        self.novas.clear()
        self.knives.clear()
        self.quakes.clear()
        # Minyonlar (kılıç, kurt, şahin) oyuncuyla birlikte geçer.
        for mn in list(self.ghost_blades) + list(self.wolves) + list(self.hawks):
            mn.x, mn.y = ARENA_RECT.centerx, ARENA_RECT.centery
        # Arenadaki yaratıklar gitti: mührün "içerideler" listesi de boşalır,
        # yoksa cehennemin ilk yaratıkları kavurucu vuruşu yemeden girebilir.
        self.penta_inside.clear()
        # Yerde kalan mıknatıs kaybolmaz: bu kadar nadir bir eşya geçiş
        # yüzünden yok olmasın, oyuncunun ayağının dibine taşınır.
        for mg in self.magnets:
            mg.x, mg.y = ARENA_RECT.centerx + random.uniform(-70, 70), \
                ARENA_RECT.centery + random.uniform(60, 120)
        for lv in self.level_drops:
            lv.x, lv.y = ARENA_RECT.centerx + random.uniform(-70, 70), \
                ARENA_RECT.centery + random.uniform(60, 120)
        self.time_stop = 0.0
        # Arenadan kalan yanık/zehir/yavaşlatma cehenneme taşınmasın.
        p.clear_status()

        # Dalga düzeni baştan başlar (1. haritadaki gibi). Arenada geçilen
        # dalgalar total_wave için saklanır.
        self.arena_waves = int(self.waves.wave)
        self.waves = WaveManager(self.diff, biome="hell")
        self.waves.spawn_pos_fn = self.near_camera_point
        # Lanetler cehenneme de taşınır (aynı sözlük); mağara ağzı kalır
        # arenada.
        self.waves.curses = self.curses
        self.biome = "hell"
        self._apply_wave_mods()         # harita kuralı biter, yemin sürer
        self.cursed_shrine = None
        self.cursed_seen_wave = 0
        # cehennemde mağara yok (koşuda 3 mağara: baş, ilk patron, kapı)
        self.corpses = []
        self.waves.wave_start_score = self.score
        self.waves.announce_timer = 3.4
        self.waves.announce_text = "CEHENNEM - DALGA 1"

        # Oyuncu cehenneme dinlenmiş girer (kapıdan geçiş ödülü).
        p.x, p.y = ARENA_RECT.centerx, ARENA_RECT.centery
        p.hp = p.max_hp
        p.invuln = max(p.invuln, 2.0)
        self.update_camera(0.0, snap=True)

        # Bellek: aynı anda tek zemin tutulur. Arena zemini bırakılır, cehennem
        # zemini burada (geçiş parlamasının altında) hazırlanır.
        _FLOOR_CACHE.pop("arena", None)
        floor_surface("hell")

        self.fx.do_flash(HELL_PORTAL_COLOR, 0.9)
        self.fx.shake(18, 0.7)
        self.fx.popup(p.x, p.y - 80, "CEHENNEME HOŞ GELDİN", (255, 140, 90), 34, life=2.6)
        if self.ach:
            self.ach.unlock("hell_gate")
        sfx("boss", 1.0, 0.0)

    def buy_shop_item(self, key):
        item = SHOP_BY_KEY.get(key)
        if not item:
            return False
        if not shop_item_unlocked(item, self.waves.wave, self.biome):
            return False
        lvl = self.player.shop_levels.get(key, 0)
        if lvl >= item.get("max", 999):
            return False
        cost = shop_item_cost(item, lvl)
        if self.gold_wallet < cost:
            sfx("error", 0.6, 0.0)
            return False
        self.gold_wallet -= cost
        self.player.shop_levels[key] = lvl + 1
        apply_shop_item(self.player, key)
        self.fx.ring(self.player.x, self.player.y, item["color"], n=14, speed=160, life=0.35, r=3)
        sfx("buy", 1.0, 0.0)
        if item.get("cursed") and self.ach:
            self.ach.unlock("cursed")
        return True

    def do_player_attack(self, aim_dx, aim_dy):
        p = self.player
        # ---- kitap çarpanları (atış anında hesaplanır) ----
        atk_mult = 1.0
        echo_shot = False
        if p.echo_level > 0:
            p.echo_count += 1
            if p.echo_count % 4 == 0:
                # yankı kitabı: her 4. atış çift hasar vurur
                atk_mult *= (1.0 + 1.0 * p.echo_level)
                echo_shot = True
        if p.swarm_level > 0:
            # sürü kitabı: çevrende 3+ düşman varsa hasarın artar
            near = 0
            for e in self.enemies:
                if e.alive and dist(e.x, e.y, p.x, p.y) < 240:
                    near += 1
                    if near >= 3:
                        break
            if near >= 3:
                atk_mult *= (1.0 + p.swarm_bonus())
        n = 1 + p.multishot_level
        spread_deg = 9
        base_ang = math.atan2(aim_dy, aim_dx)
        speed = 660 * p.proj_speed_mult
        sk = p.skin
        for i in range(n):
            offset = (i - (n - 1) / 2) * math.radians(spread_deg)
            ang = base_ang + offset
            vx, vy = math.cos(ang) * speed, math.sin(ang) * speed
            hits = p.eff_pierce_hits()
            self.player_projectiles.append(PlayerProjectile(
                p.x + aim_dx * (p.radius + sk["wlen"] * 0.55), p.y + aim_dy * (p.radius + sk["wlen"] * 0.55),
                vx, vy, p.eff_dmg() * atk_mult, hits, p.eff_crit_chance(), p.eff_crit_dmg(),
                homing=p.homing_level, style=sk["proj"], color=sk["color"], accent=sk["accent"]))
        p.run_shots += n
        p.recoil = 1.0
        p.flash_t = 0.08
        if echo_shot:
            self.fx.ring(p.x, p.y, (255, 235, 150), n=10, speed=190, life=0.28, r=2.5)
        self.fx.spark(p.x + aim_dx * p.radius, p.y + aim_dy * p.radius, sk["accent"], aim_dx * 40, aim_dy * 40, .15, 2)
        sfx("shoot_" + sk["sfx"], 0.5, 0.035)

    def _titan_smash_fx(self, p):
        """Ezici darbe'nin görsel/işitsel gösterisi."""
        self.fx.popup(p.x, p.y - 56, "EZİCİ DARBE!", (150, 255, 120), 30, life=1.1)
        self.fx.do_flash((150, 255, 130), 0.4)
        self.fx.shake(16, 0.45)
        for k in range(4):
            self.fx.shockwave(p.x, p.y, 260 + k * 260, (150, 255, 130), 0.55, 8 - k)
        self.fx.burst(p.x, p.y, (150, 255, 130), n=42, speed=320, life=0.7, r=5)
        sfx("explosion", 1.0, 0.0)

    def _apply_execute(self, p, e, dmg):
        """infaz (İnfaz Kitabı, İnfaz Kenarı, Zırh Kırıcı)."""
        if (p.execute_threshold > 0 and not getattr(e, "is_boss", False)
                and getattr(e, "kind", "") != "elite" and e.hp > 0
                and not getattr(e, "phased", False)):
            # ağır yaratıkta (zırhlı, kalkanlı, yarı patron) eşik yarıya iner -
            # tek kitapla bütün geç oyun ezilmesin.
            thr = p.execute_threshold
            if enemy_weight_class(e) == "tough":
                thr *= EXECUTE_TOUGH_K
            if (e.hp - dmg) / max(1e-6, e.max_hp) <= thr and e.hp > dmg:
                arm = clamp(float(getattr(e, "armor", 0.0) or 0.0), 0.0, 0.95)
                self.fx.popup(e.x, e.y - getattr(e, "radius", 14) - 18, L("fx.execute"),
                              (255, 170, 80), 14, life=0.5)
                return (e.hp + 1.0) / (1.0 - arm)
        return dmg

    def _explosion_splash(self, cx, cy, base_dmg, exclude_id=None):
        p = self.player
        if p.explosive_level <= 0:
            return
        radius = 74
        for e2 in self.enemies:
            if not e2.alive or id(e2) == exclude_id:
                continue
            if dist(cx, cy, e2.x, e2.y) <= radius:
                sdmg = base_dmg * 0.35 * p.explosive_level
                died2 = e2.take_damage(sdmg, False, self.fx)
                if died2:
                    self.on_enemy_killed(e2)
        self.fx.ring(cx, cy, (240, 130, 60), n=10, speed=140, life=0.25, r=2.5)

    def _all_targets(self):
        t = list(self.enemies)
        t.extend(b for b in self.bosses if b.alive)
        return t

    TITAN_SMASH_CD = 10.0          # ezici darbe bekleme süresi (saniye)
    TITAN_SMASH_HP_CUT = 0.5       # patron dışı düşmanların canı bu orana iner

    # ================= patron sandığı / otomatik silahlar =================.
    # yarı patron (sancaktar).
    def spawn_mini_boss(self):
        """Sırtında sandık taşıyan sancaktar'ı ve onu koruyan siperci'leri getirir."""
        p = self.player
        cam = self.cam_rect()
        mult = self.wave_hp_mult(self.waves.wave)
        hell = self.biome == "hell"
        # Kameranın hemen dışında, oyuncudan makul uzaklıkta bir giriş noktası
        hx, hy = self.near_camera_point(140)
        hx = clamp(hx, ARENA_RECT.left + 70, ARENA_RECT.right - 70)
        hy = clamp(hy, ARENA_RECT.top + 70, ARENA_RECT.bottom - 70)
        herald = Enemy("herald", hx, hy, mult, 1.0, wave=self.waves.wave,
                       biome=self.biome)
        tier = mini_boss_tier(self.waves.wave, hell)
        herald.max_hp *= 1.0 + MINI_BOSS_HP_PER_TIER * tier
        herald.hp = herald.max_hp
        herald.HERALD_LEAK = max(MINI_BOSS_LEAK_MIN,
                                 Enemy.HERALD_LEAK - MINI_BOSS_LEAK_PER_TIER * tier)
        self.enemies.append(herald)
        n = mini_boss_guard_count(self.waves.wave, hell)
        for i in range(n):
            a = math.tau * i / n
            gx = clamp(hx + math.cos(a) * 60, ARENA_RECT.left + 30, ARENA_RECT.right - 30)
            gy = clamp(hy + math.sin(a) * 60, ARENA_RECT.top + 30, ARENA_RECT.bottom - 30)
            g = Enemy("shieldman", gx, gy, mult, 1.0, wave=self.waves.wave,
                      biome=self.biome)
            g.max_hp *= 1.0 + MINI_BOSS_GUARD_HP_PER_TIER * tier
            g.hp = g.max_hp
            g.armor = max(float(getattr(g, "armor", 0.0) or 0.0),
                          min(MINI_BOSS_GUARD_ARMOR_MAX, MINI_BOSS_GUARD_ARMOR_PER_TIER * tier))
            g.guard_of = herald
            g.guard_slot = i
            herald.guards.append(g)
            self.enemies.append(g)
        self.fx.popup(p.x, p.y - 110, "SANCAKTAR GELDİ!", (246, 214, 120), 30, life=2.4)
        self.fx.popup(p.x, p.y - 80, "önce sipercileri temizle, sandığı o taşıyor",
                      TEXT_DIM, 15, life=2.4)
        self.fx.do_flash((246, 214, 120), 0.26)
        self.fx.ring(hx, hy, (246, 214, 120), n=26, speed=280, life=0.7, r=4)
        sfx("boss", 0.45, 0.0)

    def spawn_boss_chest(self, boss, dx=0.0):
        """Devrilen patronun yerine sandık bırakır."""
        x = clamp(boss.x + dx, ARENA_RECT.left + 60, ARENA_RECT.right - 60)
        y = clamp(boss.y, ARENA_RECT.top + 60, ARENA_RECT.bottom - 60)
        self.chests.append(BossChest(x, y, getattr(boss, "name", None)
                                     or getattr(boss, "disp_name", "")))
        self.fx.ring(x, y, GOLD, n=24, speed=230, life=0.6, r=4)
        self.fx.popup(x, y - 70, "SANDIK DÜŞTÜ!", GOLD, 26, life=1.6)
        sfx("coin", 0.9, 0.0)

    def grant_weapon(self, chest):
        """Sandığı açar."""
        p = self.player
        self.chests_opened += 1
        # Yükseltilebilecek silahlar: oyuncunun taşıdığı ve tavana ulaşmamış.
        can_up = [k for k, lvl in p.weapons.items()
                  if k in WEAPON_BY_KEY and lvl < weapon_max_level(WEAPON_BY_KEY[k])]
        if not can_up:
            gem = 400 + self.waves.wave * 45
            gold = int(gem * GOLD_TRIM)
            self.gold_wallet += gold
            self.coins_earned += gold
            self.gem_coins += gem
            self.fx.popup(chest.x, chest.y - 60, f"+{gold} ALTIN", GOLD, 26, life=1.6)
            if not p.weapons:
                # Henüz hiç silahı yok: sandığın niye altına döndüğünü söyle.
                sub = "silahlar seviye atlarken seçilir"
            else:
                sub = "bütün silahların tavanda"
            self.fx.popup(chest.x, chest.y - 34, sub, TEXT, 14, life=1.8)
            sfx("coin", 0.9, 0.0)
            return
        # En düşük seviyeli silah öne alınır: sandıklar takımı dengeli
        # büyütsün.
        low = min(p.weapons[k] for k in can_up)
        key = random.choice([k for k in can_up if p.weapons[k] == low])
        w = WEAPON_BY_KEY[key]
        p.weapons[key] += 1
        # şans: sandık bir nadirlik kademesi çeker; silah kademe çarpanı kadar
        # kalıcı hasar kazanır.
        tier = roll_rarity(p.eff_luck())
        gained = p.add_weapon_boost(key, rarity_boost(tier))
        extra = False
        if (tier >= RARITY_COUNT - 1 and LEGEND_CHEST_EXTRA_LEVEL
                and p.weapons[key] < weapon_max_level(w)):
            p.weapons[key] += 1
            extra = True
        self._chest_rarity_fx(chest, w, tier, gained, extra)

    def _chest_rarity_fx(self, chest, w, tier, gained, extra):
        """Sandık açılış gösterisi: kademe yükseldikçe daha büyük ve parlak."""
        p = self.player
        rc = rarity_color(tier)
        lvl = p.weapons.get(w["key"], 1)
        if gained > 0:
            # "EPİK • BALTA +%20 HASAR" (yüzde işaretinin yeri dile göre)
            head = L("ui.chest_boost", rarity_name(tier), w_name(w).upper(), fmt_pct1(gained))
        else:
            head = "%s • %s (%s)" % (rarity_name(tier), w_name(w).upper(), L("ui.boost_capped"))
        sub = L("ui.chest_level", w_name(w), lvl)
        size = 26 + 2 * tier
        self.fx.popup(chest.x, chest.y - 80, head, rc, size, life=1.9 + 0.25 * tier)
        self.fx.popup(chest.x, chest.y - 50, sub, w["color"], 15, life=1.9)
        if extra:
            self.fx.popup(chest.x, chest.y - 28, L("ui.chest_legend_extra"), GOLD, 16, life=2.2)
        self.fx.do_flash(rc, 0.30 + 0.08 * tier)
        for k in range(1 + tier):
            self.fx.ring(chest.x, chest.y, rc, n=22 + 8 * tier, speed=240 + 60 * k,
                         life=0.55 + 0.08 * k, r=3 + 0.5 * tier)
        if tier >= 2:
            self.fx.shockwave(chest.x, chest.y, 140 + 70 * tier, rc, 0.45, 4 + tier)
        if tier >= 3:
            self.fx.burst(chest.x, chest.y, rc, n=20 + 14 * tier, speed=300, life=0.8, r=4)
            self.fx.shake(4 + 3 * (tier - 2), 0.25)
        if tier >= 4:
            self.fx.burst(chest.x, chest.y, WHITE, n=40, speed=420, life=1.0, r=5)
            for k in range(3):
                self.fx.shockwave(chest.x, chest.y, 260 + 160 * k, GOLD, 0.6, 7 - k)
        sfx("levelup", 1.0, 0.0)
        if tier >= 3:
            sfx("second", 0.8, 0.0)

    # ---- anahtarlar + efsanevi sandık ----
    def _far_point(self, min_player, avoid=(), spacing=0, tries=120, max_player=None):
        p = self.player
        area = ARENA_RECT.inflate(-180, -180)
        best, best_d = None, -1.0
        for _ in range(tries):
            x = random.uniform(area.left, area.right)
            y = random.uniform(area.top, area.bottom)
            dp = dist(x, y, p.x, p.y)
            if dp < min_player or (max_player is not None and dp > max_player):
                continue
            dm = min([dist(x, y, ax, ay) for ax, ay in avoid] or [1e9])
            if dm >= spacing:
                return x, y
            if dm > best_d:
                best, best_d = (x, y), dm
        return best or (area.left + 200, area.top + 200)

    def place_keys(self):
        """Haritaya KEY_COUNT anahtar dağıtır (birbirinden ve oyuncudan uzak)."""
        pts = []
        for _ in range(KEY_COUNT):
            pts.append(self._far_point(KEY_PLAYER_MIN, pts, KEY_SPACING, max_player=KEY_PLAYER_MAX))
        self.map_keys = [MapKey(x, y, i) for i, (x, y) in enumerate(pts)]
        self.keys_got = 0
        self.keys_placed = True

    def nearest_key(self):
        p = self.player
        ks = [k for k in self.map_keys if not k.taken]
        if not ks:
            return None
        return min(ks, key=lambda k: dist(k.x, k.y, p.x, p.y))

    def update_keys(self, dt):
        p = self.player
        if not self.keys_placed:
            self.place_keys()
        if not self.map_keys and self.legend_chest is None and self.keys_got <= 0:
            if self.legend_opened < LEGEND_CHEST_MAX:
                self.key_respawn_t -= dt
                if self.key_respawn_t <= 0:
                    self.place_keys()
                    if p.alive:
                        self.fx.popup(p.x, p.y - 96, L("fx.keys_new"), KEY_COLOR, 20, life=2.2)
        for k in self.map_keys:
            k.update(dt)
            if (not k.taken and p.alive
                    and dist(k.x, k.y, p.x, p.y) < KEY_PICK_R + p.radius):
                k.taken = True
                self.keys_got += 1
                self.fx.popup(k.x, k.y - 50, L("fx.key", self.keys_got, KEY_COUNT), KEY_COLOR, 24, life=1.6)
                self.fx.ring(k.x, k.y, KEY_COLOR, n=22, speed=220, life=0.5, r=3)
                sfx("coin", 1.0, 0.0)
                self.run_keys = getattr(self, "run_keys", 0) + 1
        self.map_keys = [k for k in self.map_keys if not k.gone]
        if (self.keys_got >= KEY_COUNT and self.legend_chest is None
                and not any(not k.taken for k in self.map_keys)):
            x, y = self._far_point(1100, [(self.hell_portal.x, self.hell_portal.y)]
                                   if self.hell_portal is not None else [], 300)
            self.legend_chest = LegendChest(x, y)
            self.keys_got = 0
            if p.alive:
                self.fx.popup(p.x, p.y - 110, L("fx.keys_done"), LEGEND_COLOR, 24, life=3.0)
                self.fx.do_flash(LEGEND_COLOR, 0.35)
            sfx("levelup", 0.9, 0.0)
        ch = self.legend_chest
        if ch is not None:
            ch.update(dt, p)
            if ch.opened and not ch.taken:
                ch.taken = True
                self.open_legend_chest(ch)
            if not ch.alive:
                self.legend_chest = None

    def open_legend_chest(self, ch):
        """Efsanevi sandık: bir el efsanevi kart + LEGEND_CHEST_LEVELS seviye."""
        p = self.player
        self.legend_opened += 1
        self.key_respawn_t = KEY_RESPAWN
        n = LEGEND_CHEST_LEVELS
        for _ in range(n):
            p.level += 1
            p.xp_to_next = xp_next_need(p.xp_to_next, p.level)
        p.on_level_up(n)
        self.legend_hands += 1
        self.pending_levelups += n + 1
        self.fx.popup(ch.x, ch.y - 90, L("fx.legend_open", n), LEGEND_COLOR, 30, life=2.6)
        self.fx.do_flash(LEGEND_COLOR, 0.55)
        self.fx.shake(10, 0.4)
        self.fx.burst(ch.x, ch.y, LEGEND_COLOR, n=70, speed=420, life=1.0, r=5)
        self.fx.burst(ch.x, ch.y, LEGEND_COLOR2, n=40, speed=320, life=0.9, r=4)
        for k in range(3):
            self.fx.shockwave(ch.x, ch.y, 260 + 170 * k, LEGEND_COLOR if k % 2 == 0 else LEGEND_COLOR2, 0.6, 7 - k)
        sfx("levelup", 1.0, 0.0)
        sfx("second", 0.9, 0.0)

    def _legend_hand(self):
        """Efsanevi el: nadirlik taşıyabilen (silah / normal kitap) kartlar, hepsi efsanevi kademede."""
        offers, weights = self.levelup_pool()
        top = RARITY_COUNT - 1
        pool = []
        for o, w in zip(offers, weights):
            if o["kind"] == "weapon":
                o["rarity"] = top
                o["boost"] = rarity_boost(top, "card")
            elif o["kind"] == "book" and not o.get("rare") and o["key"] in BOOK_GAINS:
                o["rarity"] = top
                o["gains"] = book_gain(o["key"], top, o["lvl"])
            else:
                continue
            o["legend"] = True
            pool.append((o, max(1.0, w)))
        if not pool:
            return []
        chosen, seen = [], set()
        for kind in ("weapon", "book"):
            c = [(o, w) for o, w in pool if o["kind"] == kind]
            if c:
                o = random.choices([a for a, _ in c], weights=[b for _, b in c], k=1)[0]
                chosen.append(o)
                seen.add((o["kind"], o["key"]))
        rest = [(o, w) for o, w in pool if (o["kind"], o["key"]) not in seen]
        while len(chosen) < 3 and rest:
            o = random.choices([a for a, _ in rest], weights=[b for _, b in rest], k=1)[0]
            chosen.append(o)
            rest = [(a, b) for a, b in rest if a is not o]
        random.shuffle(chosen)
        return chosen

    def update_chests(self, dt):
        for ch in list(self.chests):
            ch.update(dt, self.player)
            if ch.opened and not ch.taken:
                ch.taken = True
                self.grant_weapon(ch)
        self.chests = [c for c in self.chests if c.alive]

    def _weapon_targets(self, max_d=WEAPON_RANGE):
        """Silahların vurabileceği, menzildeki canlı hedefler."""
        p = self.player
        out = []
        for e in self.enemies:
            if e.alive and dist(p.x, p.y, e.x, e.y) <= max_d:
                out.append(e)
        for b in self.bosses:
            # Görünmez patrona silahlar da kilitlenemez.
            if b.alive and not b.is_hidden() and dist(p.x, p.y, b.x, b.y) <= max_d:
                out.append(b)
        return out

    def update_boss_weapons(self, dt):
        """Sandıktan çıkan silahları otomatik ateşler."""
        p = self.player
        if not p.weapons or not p.alive:
            return
        targets = None
        for key in list(p.weapons.keys()):
            w = WEAPON_BY_KEY.get(key)
            if w is None:
                continue
            # sürekli silahlar (kitap / pentagram / papuç) buradan atılmaz.
            if w.get("passive"):
                continue
            lvl = p.weapons[key]
            p.weapon_timers[key] = p.weapon_timers.get(key, 0.0) - dt
            if p.weapon_timers[key] > 0:
                continue
            if targets is None:
                targets = self._weapon_targets()
            if not targets:
                # Hedef yokken sayaç eksiye kaymasın; silah "hazır" bekler.
                p.weapon_timers[key] = 0.0
                continue
            DMG_SRC[0] = key
            before = self._weapon_object_counts()
            self._fire_weapon(w, lvl, targets)
            self._tag_weapon_objects(key, before)
            p.weapon_timers[key] = weapon_cooldown(w, lvl) / (1.0 + p.weapon_speed_bonus)

    def _weapon_hit(self, e, dmg, kb=90, crit=None, wlvl=None):
        """Silah vuruşunun ortak kapısı: kritik, infaz, kan emme, ölüm."""
        p = self.player
        if crit is None:
            crit = random.random() < p.eff_crit_chance()
        if crit:
            p.run_crits += 1
            dmg *= p.eff_crit_dmg()
        if p.boss_hunter > 0 and (getattr(e, "is_boss", False) or getattr(e, "kind", "") == "elite"):
            dmg *= (1.0 + p.boss_hunter_bonus())
        dmg = cap_oneshot(e, dmg, wlvl)
        dmg = self._apply_execute(p, e, dmg)     # frenden sonra
        kx, ky = norm_dir(p.x, p.y, e.x, e.y)
        real_kb = 12 if getattr(e, "is_boss", False) else kb
        died = e.take_damage(dmg, crit, self.fx, kx * real_kb, ky * real_kb)
        if p.vamp_level > 0:
            p.lifesteal(dmg * 0.02 * p.vamp_level)
        if died:
            self.on_enemy_killed(e)
        return died

    def _weapon_projectile(self, w, dmg, ang, speed, hits, life):
        p = self.player
        # Silah mermileri de oyuncunun kritik şansını ve kritik hasarını
        # kullanır; çarpışma çözümü normal mermilerle aynı yerden geçer.
        pr = PlayerProjectile(p.x, p.y, math.cos(ang) * speed, math.sin(ang) * speed,
                              dmg, hits, p.eff_crit_chance(), p.eff_crit_dmg(),
                              style=w["style"] or "bolt", color=w["color"], accent=WHITE)
        pr.life = life
        pr._wsrc = w["key"]
        self.player_projectiles.append(pr)
        return pr

    def _field_damage(self, e, dmg, burn=0.0, wlvl=None):
        """alan hasarının ortak kapısı (su / ateş / pentagram / kitap)."""
        p = self.player
        if p.boss_hunter > 0 and (getattr(e, "is_boss", False) or getattr(e, "kind", "") == "elite"):
            dmg *= (1.0 + p.boss_hunter_bonus())
        dmg = cap_oneshot(e, dmg, wlvl)
        dmg = self._apply_execute(p, e, dmg)     # frenden sonra
        died = e.take_damage(dmg, False, self.fx, quiet=True)
        if burn > 0 and hasattr(e, "apply_burn"):
            e.apply_burn(burn, 1.4)
        if p.vamp_level > 0:
            # Alan hasarının saniyede birkaç kez vurması saniye tavanıyla
            # (vamp_rate_cap) frenlendiği için oranı ayrıca yarıya indirmeye
            # gerek yok.
            p.lifesteal(dmg * 0.02 * p.vamp_level)
        if died:
            self.on_enemy_killed(e)
        return died

    # ---- sürekli çalışan silahlar ----
    def update_passive_weapons(self, dt):
        """Bekleme süresi olmayan, hep açık duran silahlar."""
        p = self.player
        if not p.alive:
            return

        # ---- kalkan ----
        # Kalkan sayısı seviyeye eşit değil, bantlı artar (weapon_count):
        # mermiyi savuşturur ve bir süre boşta kalır:
        # 25. seviyede 25 değil 9 kalkan döner. Dolu bir kalkan gelen bir
        blvl = p.weapons.get("book", 0)
        DMG_SRC[0] = "book"
        if blvl > 0:
            n_book = weapon_count(blvl)
            p.book_angle += dt * BOOK_SPIN
            while len(p.book_charges) < n_book:
                p.book_charges.append(0.0)
            if len(p.book_charges) > n_book:
                del p.book_charges[n_book:]
            for i in range(n_book):
                if p.book_charges[i] > 0:
                    p.book_charges[i] = max(0.0, p.book_charges[i] - dt)
                    if p.book_charges[i] <= 0:
                        # kitap yeniden doldu
                        bx, by, _a = book_slot_pos(p, i, n_book)
                        self.fx.ring(bx, by, SHIELD_COLOR, n=8, speed=120, life=0.3, r=2.2)
            # Kalkanlar dokundukları yaratığı da hafifçe öğütür.
            bw = WEAPON_BY_KEY["book"]
            bdmg = weapon_damage(p, bw, blvl) * dt
            for i in range(n_book):
                if p.book_charges[i] > 0:
                    continue
                bx, by, _a = book_slot_pos(p, i, n_book)
                for e in self._all_targets():
                    if not e.alive:
                        continue
                    if dist(bx, by, e.x, e.y) < getattr(e, "radius", 12) + 15:
                        self._field_damage(e, bdmg * 6.0, wlvl=blvl)

        # ---- pentagram ----
        plvl = p.weapons.get("pentagram", 0)
        DMG_SRC[0] = "pentagram"
        if plvl > 0:
            p.penta_angle += dt * 0.65
            p.penta_tick -= dt
            if p.penta_tick <= 0:
                p.penta_tick = PENTA_TICK
                pw = WEAPON_BY_KEY["pentagram"]
                rad = penta_radius(plvl)
                dps = weapon_damage(p, pw, plvl)
                tick_dmg = dps * PENTA_TICK
                # mühre ilk adım: sabit kısım + canın bir oranı.
                sear_flat = dps * PENTA_SEAR_K
                sear_frac = penta_sear_hp_frac(plvl)
                # İlk adım vuruşunun canından alabileceği en çok oran: 1.0'ın
                # altındayken mühür tek atamaz.
                sear_cap = penta_sear_cap(plvl)
                bat_tick = penta_bat_tick_mult(plvl)
                hit = 0
                seared = 0
                sparks_left = 3
                inside_now = set()
                was_inside = self.penta_inside
                for e in self._all_targets():
                    if not e.alive:
                        continue
                    if dist(p.x, p.y, e.x, e.y) <= rad + getattr(e, "radius", 12) * 0.5:
                        inside_now.add(e)
                        bat_capped = False
                        if e not in was_inside:
                            # Mührün eşiğini yeni geçti: kavurucu vuruş.
                            # Patronun canından oran kesilmez (tornado ile aynı
                            # ilke), yalnızca sabit kısmı yer.
                            sear = sear_flat
                            if not getattr(e, "is_boss", False):
                                sear += max(0.0, getattr(e, "hp", 0.0)) * sear_frac
                            # genel fren: mühür her şeyi tek atmıyor.
                            cap = sear_cap
                            if is_penta_bat(e):
                                cap = min(cap, penta_bat_sear_cap(plvl))
                            if cap < 1.0 and not getattr(e, "is_boss", False):
                                ehp = max(0.0, getattr(e, "hp", 0.0))
                                if sear > ehp * cap:
                                    sear = ehp * cap
                                    bat_capped = is_penta_bat(e)
                            if seared < 4:
                                seared += 1
                                self.fx.spark(e.x, e.y - 6, PENTA_COLOR2,
                                              random.uniform(-40, 40),
                                              random.uniform(-90, -40), 0.35, 2.8)
                            if self._field_damage(e, sear):
                                continue
                            if bat_capped:
                                # (Diğer yaratıklarda sürekli hasar normal
                                # işler.)
                                hit += 1
                                continue
                        # Sürekli hasar da yarasada 6. seviyeye kadar kısık.
                        self._field_damage(
                            e, tick_dmg * (bat_tick if is_penta_bat(e) else 1.0))
                        hit += 1
                        if sparks_left > 0 and random.random() < 0.4:
                            sparks_left -= 1
                            self.fx.spark(e.x + random.uniform(-9, 9), e.y,
                                          PENTA_COLOR2, random.uniform(-14, 14),
                                          random.uniform(-70, -34), 0.4, 2.2)
                self.penta_inside = inside_now
                if seared:
                    sfx("blaze", 0.22, 0.05)
                if hit:
                    sfx("hit", 0.10, 0.10)

        # ---- baran'IN papucu ----
        slvl = p.weapons.get("shoe", 0)
        if slvl > 0:
            if p.shoe_last is None:
                p.shoe_last = (p.x, p.y)
            p.shoe_idle += dt
            # Halka iki yoldan tutuşur: SHOE_STEP kadar yürüyünce ya da hiç
            # yürümeden SHOE_IDLE_EVERY saniye geçince.
            stepped = dist(p.x, p.y, p.shoe_last[0], p.shoe_last[1]) >= SHOE_STEP
            if stepped or p.shoe_idle >= SHOE_IDLE_EVERY:
                p.shoe_last = (p.x, p.y)
                p.shoe_idle = 0.0
                sw = WEAPON_BY_KEY["shoe"]
                dps = weapon_damage(p, sw, slvl)
                self.fire_rings.append(FireRing(p.x, p.y, shoe_radius(slvl), dps,
                                                shoe_life(slvl), burn=dps * 0.30,
                                                lvl=slvl))
                sfx("blaze", 0.16, 0.06)

        # ---- görünmezlik pelerini ----
        # cloak_timer sıfıra inince oyuncu bir süre görünmez olur.
        clvl = p.weapons.get("cloak", 0)
        if clvl > 0:
            if p.invis_t > 0:
                p.invis_t = max(0.0, p.invis_t - dt)
                if p.invis_t <= 0:
                    p.cloak_timer = cloak_cooldown(clvl) * (0.7 if "cloak" in p.evolved else 1.0)
                    self.fx.ring(p.x, p.y, CLOAK_COLOR2, n=18, speed=260,
                                 life=0.45, r=3)
                    self.fx.popup(p.x, p.y - 46, "GÖRÜNDÜN", CLOAK_COLOR2, 16,
                                  life=0.8)
                    sfx("guard", 0.35, 0.0)
            else:
                p.cloak_timer -= dt
                if p.cloak_timer <= 0:
                    p.invis_t = cloak_duration(clvl)
                    p.cloak_timer = cloak_cooldown(clvl) * (0.7 if "cloak" in p.evolved else 1.0)
                    self.fx.popup(p.x, p.y - 64, L("ui.cloak_on"), CLOAK_COLOR2, 26,
                                  life=1.4)
                    self.fx.ring(p.x, p.y, CLOAK_COLOR, n=26, speed=320,
                                 life=0.6, r=3.4)
                    self.fx.shockwave(p.x, p.y, 150, CLOAK_COLOR2, 0.45, 4)
                    sfx("dash", 0.55, 0.0)

        # ---- hayalet kılıçlar (, minyon) ----
        self.minion_t += dt
        glvl = p.weapons.get("ghost_swords", 0)
        DMG_SRC[0] = "ghost_swords"
        if glvl > 0:
            n_gb = ghost_count(glvl)
            while len(self.ghost_blades) < n_gb:
                self.ghost_blades.append(GhostBlade(len(self.ghost_blades), p))
            del self.ghost_blades[n_gb:]
            gdmg = weapon_damage(p, WEAPON_BY_KEY["ghost_swords"], glvl)
            for gb in self.ghost_blades:
                gb.update(dt, self, n_gb, glvl, gdmg, self.minion_t)
        elif self.ghost_blades:
            self.ghost_blades.clear()

        # ---- şahin (, minyon) ----
        hlvl = p.weapons.get("hawk", 0)
        DMG_SRC[0] = "hawk"
        if hlvl > 0:
            n_h = hawk_count(hlvl)
            while len(self.hawks) < n_h:
                self.hawks.append(Hawk(len(self.hawks), p))
            del self.hawks[n_h:]
            hdmg = weapon_damage(p, WEAPON_BY_KEY["hawk"], hlvl)
            for hk in self.hawks:
                hk.update(dt, self, n_h, hlvl, hdmg, self.minion_t)
        elif self.hawks:
            self.hawks.clear()
        # yarasa iyileştirme kovası dolar (saniyede azami canın %1,5'i)
        self.bat_heal_budget = min(p.max_hp * BAT_HEAL_RATE * 2.0,
                                   self.bat_heal_budget + p.max_hp * BAT_HEAL_RATE * dt)

        # ---- kurt sürüsü (, minyon) ----
        wlvl_ = p.weapons.get("wolves", 0)
        DMG_SRC[0] = "wolves"
        if wlvl_ > 0:
            n_w = wolf_count(wlvl_)
            while len(self.wolves) < n_w:
                self.wolves.append(SpectralWolf(len(self.wolves), p))
                if len(self.wolves) > 1:
                    self.fx.popup(p.x, p.y - 58, L("fx.wolf_join"), WOLF_COLOR2, 16, life=1.0)
            del self.wolves[n_w:]
            wdmg = weapon_damage(p, WEAPON_BY_KEY["wolves"], wlvl_)
            # sürü uluması: kalabalık varken her WOLF_HOWL_CD saniyede sürü
            # durup uluyor, sonra kısa süre coşkuyla koşup sık ısırıyor.
            self.wolf_howl_cd -= dt
            if self.wolf_howl_cd <= 0 and self._weapon_targets(WOLF_LEASH):
                self.wolf_howl_cd = WOLF_HOWL_CD
                for wf in self.wolves:
                    wf.howl_t = WOLF_HOWL_T
                    wf.frenzy_t = WOLF_HOWL_T + WOLF_FRENZY_T
                    self.fx.shockwave(wf.x, wf.y, 90, WOLF_COLOR2, 0.45, 3)
                lead = self.wolves[0]
                self.fx.popup(lead.x, lead.y - 46, L("fx.howl"), WOLF_COLOR2, 22, life=1.2)
                sfx("roar", 0.45, 0.05)
            for wf in self.wolves:
                wf.update(dt, self, self.wolves, wlvl_, wdmg)
        elif self.wolves:
            self.wolves.clear()

        # ---- buz izi ----
        # Papucun aynısı, başka element: yakmak yerine yavaşlatır. Adım
        # mesafesi biraz daha uzun, böylece iki silah birden varken halkalar
        # üst üste yığılmaz.
        flvl = p.weapons.get("frost", 0)
        if flvl > 0:
            if p.frost_last is None:
                p.frost_last = (p.x, p.y)
            p.frost_idle += dt
            # papuç ile birebir aynı kural: ya SHOE_STEP kadar yürünür, ya da
            # hiç yürümeden SHOE_IDLE_EVERY saniye geçer.
            stepped = dist(p.x, p.y, p.frost_last[0], p.frost_last[1]) >= SHOE_STEP
            if stepped or p.frost_idle >= SHOE_IDLE_EVERY:
                p.frost_last = (p.x, p.y)
                p.frost_idle = 0.0
                fw = WEAPON_BY_KEY["frost"]
                dps = weapon_damage(p, fw, flvl)
                self.fire_rings.append(FireRing(p.x, p.y, shoe_radius(flvl), dps,
                                                shoe_life(flvl), ice=True, lvl=flvl,
                                                slow=max(0.30, 0.62
                                                        - 0.013 * weapon_growth(flvl))))
                sfx("ice_step", 0.16, 0.06)

    # ---- yeni silahların dünya nesneleri ----
    WEAPON_OBJECT_LISTS = ("water_zones", "fire_rings", "tornados",
                           "flying_axes", "whip_lashes", "sword_slashes",
                           "meteors", "beams", "bats", "novas", "knives", "quakes")
    WEAPON_OBJECT_SRC = {"water_zones": "zemzem", "tornados": "tornado",
                         "flying_axes": "axe", "whip_lashes": "whip",
                         "sword_slashes": "emanet", "meteors": "meteor",
                         "beams": "beam", "bats": "bats", "novas": "nova",
                         "knives": "knives", "quakes": "quake"}

    def _weapon_object_counts(self):
        return {n: len(getattr(self, n)) for n in self.WEAPON_OBJECT_LISTS}

    def _tag_weapon_objects(self, key, before):
        """Az önce (bu atışta) doğan silah nesnelerine kaynağını yazar."""
        for lst_name in self.WEAPON_OBJECT_LISTS:
            lst = getattr(self, lst_name)
            for obj in lst[before.get(lst_name, 0):]:
                if getattr(obj, "_wsrc", None) is None:
                    obj._wsrc = key

    def update_weapon_objects(self, dt):
        """Su birikintileri, ateş halkaları, hortumlar, baltalar, kırbaçlar."""
        for lst_name in self.WEAPON_OBJECT_LISTS:
            lst = getattr(self, lst_name)
            for obj in list(lst):
                src = getattr(obj, "_wsrc", None)
                if src is None:
                    if lst_name == "fire_rings":
                        src = "frost" if getattr(obj, "ice", False) else "shoe"
                    else:
                        src = self.WEAPON_OBJECT_SRC.get(lst_name, "other")
                DMG_SRC[0] = src
                obj.update(dt, self)
            setattr(self, lst_name, [o for o in lst if o.alive])
        DMG_SRC[0] = "other"

    # ---- kalkan: mermiyi savuşturma ----
    def block_with_book(self, proj):
        """Gelen düşman mermisi bir kalkana değdi mi?"""
        p = self.player
        lvl = p.weapons.get("book", 0)
        if lvl <= 0 or not p.book_charges:
            return False
        n_book = weapon_count(lvl)
        rech = max(1.4, BOOK_RECHARGE - BOOK_RECHARGE_PER_LEVEL * weapon_growth(lvl))
        for i in range(min(n_book, len(p.book_charges))):
            if p.book_charges[i] > 0:
                continue
            bx, by, _a = book_slot_pos(p, i, n_book)
            if dist(proj.x, proj.y, bx, by) < getattr(proj, "r", 5) + 17:
                p.book_charges[i] = rech
                proj.alive = False
                self.fx.ring(bx, by, SHIELD_COLOR, n=14, speed=210, life=0.35, r=3)
                self.fx.burst(bx, by, SHIELD_COLOR2, n=8, speed=140, life=0.3, r=2.4)
                self.fx.popup(bx, by - 22, "SAVUŞTURDU", SHIELD_COLOR2, 14, life=0.5)
                sfx("guard", 0.34, 0.02)
                return True
        return False

    # ---- mıknatıs ----
    def update_magnets(self, dt):
        p = self.player
        for mg in list(self.magnets):
            mg.update(dt, p)
            if mg.collected:
                self.collect_magnet(mg)
        self.magnets = [m for m in self.magnets if m.alive]
        for lv in list(self.level_drops):
            lv.update(dt, p)
            if lv.collected:
                self.collect_level_drop(lv)
        self.level_drops = [m for m in self.level_drops if m.alive]

    def collect_level_drop(self, lv):
        """Seviye taşı toplandı: anında bir seviye."""
        p = self.player
        p.level += 1
        p.xp_to_next = xp_next_need(p.xp_to_next, p.level)
        p.on_level_up(1)
        self.pending_levelups += 1
        self.fx.popup(p.x, p.y - 74, "SEVİYE TAŞI!", LEVEL_COLOR, 34, life=1.8)
        self.fx.popup(p.x, p.y - 44, "+1 SEVİYE", LEVEL_COLOR2, 18, life=1.6)
        self.fx.do_flash(LEVEL_COLOR, 0.42)
        self.fx.shake(6, 0.24)
        for i, rr in enumerate((240, 460)):
            self.fx.shockwave(p.x, p.y, rr,
                              LEVEL_COLOR if i % 2 == 0 else LEVEL_COLOR2,
                              0.55 + i * 0.15, 5)
        sfx("levelup", 1.0, 0.0)
        if p.level >= 10 and self.ach:
            self.ach.unlock("lvl10")

    def collect_all_pickups(self):
        """Yerdeki bütün altın ve tecrübeyi anında oyuncuya yazar."""
        p = self.player
        for pu in self.pickups:
            if pu.collected or pu.dead:
                continue
            if pu.kind == "xp":
                lv = p.gain_xp(pu.value)
                if lv > 0:
                    self.pending_levelups += lv
            elif pu.kind == "coin":
                self.coins_earned += pu.value
                self.gem_coins += pu.value / (coin_drop_scale(self.biome)
                                              * econ_wave_factor(self.waves.wave, self.biome, "gold", self.diff))
                self.gold_wallet += pu.value
            pu.collected = True

    def collect_magnet(self, mg):
        """Mıknatıs toplandı: haritadaki bütün altın ve tecrübe oyuncuya uçar."""
        p = self.player
        n = 0
        for pu in self.pickups:
            if pu.kind in ("coin", "xp") and not pu.magnet:
                pu.magnet = True
                # Yeni düşmüş eşyaların 0.15 sn bekleme süresi çekimi
                # geciktirmesin.
                pu.spawn_t = max(pu.spawn_t, 0.2)
                n += 1
        self.magnets_taken += 1
        self.fx.popup(p.x, p.y - 74, "MIKNATIS!", MAGNET_COLOR, 34, life=1.8)
        self.fx.popup(p.x, p.y - 44, f"{n} eşya çekiliyor", MAGNET_COLOR2, 16, life=1.6)
        self.fx.do_flash(MAGNET_COLOR, 0.42)
        self.fx.shake(6, 0.24)
        # Oyuncudan dışa doğru açılan üç çekim halkası
        for i, rr in enumerate((240, 460, 680)):
            self.fx.shockwave(p.x, p.y, rr, MAGNET_COLOR if i % 2 == 0 else MAGNET_COLOR2,
                              0.55 + i * 0.15, 5)
        self.fx.ring(p.x, p.y, MAGNET_COLOR2, n=34, speed=380, life=0.7, r=3.4)
        sfx("magnet", 1.0, 0.0)

    def _fire_weapon(self, w, lvl, targets):
        p = self.player
        dmg = weapon_damage(p, w, lvl)
        key = w["key"]
        nearest = min(targets, key=lambda e: dist(p.x, p.y, e.x, e.y))
        ang = math.atan2(nearest.y - p.y, nearest.x - p.x)

        if key == "axe":
            # balta: birkaç seviyede bir balta daha. Her balta rastgele bir
            # düşmana uçar, vurur ve oyuncuya geri döner. Boyu seviyeyle büyür.
            n_axe = weapon_count(lvl)
            k = 0.92 + 0.021 * weapon_growth(lvl)
            for i in range(n_axe):
                tgt = random.choice(targets)
                ax = FlyingAxe(p, tgt, dmg, k, w["color"], lvl=lvl)
                # Baltalar tam üst üste çıkmasın: oyuncunun çevresine dağıt.
                a0 = random.uniform(0, math.tau)
                ax.x += math.cos(a0) * 16
                ax.y += math.sin(a0) * 16
                self.flying_axes.append(ax)
            self.fx.ring(p.x, p.y, w["color"], n=12, speed=220, life=0.3, r=3.0 * k)
            self.fx.shake(2.5, 0.09)
            sfx("shoot_c", 0.42, 0.0)

        elif key == "whip":
            # kırbaç: ilk kırbaç baktığın yöne savrulur (nişan yönü); birkaç
            # seviyede bir kırbaç daha eklenir ve yönler çevreye eşit dağılır
            # (2. seviyede biri öne, biri arkaya).
            adx, ady = p.aim_dir
            base_ang = math.atan2(ady, adx)
            n_whip = weapon_count(lvl, "whip")
            reach = whip_reach(lvl)
            half_arc = whip_arc(lvl)
            width = 7.0 + 0.5 * n_whip        # ince, gerçek bir kamçı
            total_hit = 0
            # 8 kırbaç x 20 düşman x 7 parçacık = 1120 parçacık; tavan 650. Bu
            # yüzden şaklama patlaması atış başına bütçelidir.
            fx_left = 6
            for i in range(n_whip):
                a = base_ang + i * math.tau / n_whip
                ca, sa = math.cos(a), math.sin(a)
                # Komşu kırbaçlar ters yöne savrulsun: hepsi aynı tarafa
                # yatarsa kalabalık bir seviyede tek bir bulanıklığa dönüyor.
                self.whip_lashes.append(WhipLash(p, a, reach, width, w["color"],
                                                 spin=1 if i % 2 == 0 else -1))
                for e in self._all_targets():
                    if not e.alive:
                        continue
                    d = dist(p.x, p.y, e.x, e.y)
                    if d > reach + getattr(e, "radius", 12):
                        continue
                    if d < 1:
                        continue
                    ex, ey = (e.x - p.x) / d, (e.y - p.y) / d
                    # Kırbacın taradığı koni: yaratık bu açının içinde mi?
                    if ca * ex + sa * ey < math.cos(half_arc):
                        continue
                    # savurma: hasarla birlikte düşmanı ileri fırlatır.
                    self._weapon_hit(e, dmg, kb=WHIP_KB, wlvl=lvl)
                    if fx_left > 0:
                        fx_left -= 1
                        self.fx.burst(e.x, e.y, WHIP_COLOR2, n=5, speed=190, life=0.3, r=2.6)
                    total_hit += 1
            if total_hit:
                self.fx.shake(3.5, 0.10)
            sfx("whip", 0.42, 0.0)

        elif key == "emanet":
            # emanet: saniyede bir, en yakın düşmana doğru bir yay çizer.
            rad = emanet_radius(lvl)
            half = emanet_arc(lvl)
            ca, sa = math.cos(ang), math.sin(ang)
            hit = 0
            fx_left = 5
            for e in self._all_targets():
                if not e.alive:
                    continue
                d = dist(p.x, p.y, e.x, e.y)
                if d > rad + getattr(e, "radius", 12):
                    continue
                if d >= 1:
                    ex, ey = (e.x - p.x) / d, (e.y - p.y) / d
                    if ca * ex + sa * ey < math.cos(half):
                        continue
                edmg = dmg
                if is_armored(e):
                    edmg *= (1.0 + EMANET_ARMOR_BONUS)
                    arm = getattr(e, "armor", 0.0)
                    if arm > 0.005:
                        # take_damage zırhı ayrıca kesecek; payı burada geri
                        # al.
                        edmg /= max(0.25, 1.0 - arm)
                self._weapon_hit(e, edmg, kb=EMANET_KB, wlvl=lvl)
                if fx_left > 0:
                    fx_left -= 1
                    self.fx.spark(e.x, e.y, EMANET_COLOR2,
                                  random.uniform(-40, 40), random.uniform(-60, -20),
                                  0.3, 2.4)
                hit += 1
            self.sword_slashes.append(SwordSlash(p, ang, rad, half))
            if hit:
                self.fx.shake(2.0, 0.07)
            sfx("whip", 0.30, 0.0)

        elif key == "zemzem":
            # zemzem suyu: yere su döker, su 3 saniye kalır. Tavan 25'e çıkınca
            # eşikler de yayıldı: 6'da iki, 13'te üç, 20'de dört.
            n = 1 + (1 if lvl >= 6 else 0) + (1 if lvl >= 13 else 0) \
                  + (1 if lvl >= 20 else 0)
            rad = ZEMZEM_BASE_R + ZEMZEM_R_PER_LEVEL * weapon_growth(lvl)
            # su yalnızca ekranda görünen yere dökülür.
            vis = self.cam_rect().inflate(-60, -60)
            spots = []
            pool = [e for e in targets if vis.collidepoint(e.x, e.y)]
            # Önce oyuncuya yakın olanlar (yakındaki kalabalık en tehlikelisi),
            # ama her seferinde aynı yere dökülmesin diye biraz karıştırılır.
            pool.sort(key=lambda e: dist(p.x, p.y, e.x, e.y) * random.uniform(0.7, 1.3))
            for e in pool:
                # Birikintiler üst üste binmesin: aralarında en az bir yarıçap
                # olsun.
                if all(dist(e.x, e.y, sx, sy) > rad * 1.15 for (sx, sy) in spots):
                    spots.append((e.x, e.y))
                if len(spots) >= n:
                    break
            tries = 0
            while len(spots) < n and tries < 40:
                tries += 1
                a = random.uniform(0, math.tau)
                r2 = random.uniform(ZEMZEM_THROW * 0.35, ZEMZEM_THROW)
                sx = clamp(p.x + math.cos(a) * r2, vis.left, vis.right)
                sy = clamp(p.y + math.sin(a) * r2, vis.top, vis.bottom)
                if all(dist(sx, sy, ox, oy) > rad * 0.9 for (ox, oy) in spots) or tries > 30:
                    spots.append((sx, sy))
            for (sx, sy) in spots:
                self.water_zones.append(WaterZone(sx, sy, rad, dmg, ZEMZEM_LIFE, lvl=lvl))
                self.fx.burst(sx, sy, ZEMZEM_COLOR2, n=16, speed=210, life=0.45, r=3.0)
                self.fx.shockwave(sx, sy, rad, ZEMZEM_COLOR, 0.35, 4)
                # suyun oyuncudan hedefe uçtuğu iz
                self.fx.bolt([(p.x, p.y), ((p.x + sx) / 2, (p.y + sy) / 2 - 70), (sx, sy)],
                             ZEMZEM_COLOR2, 0.22)
            sfx("splash", 0.5, 0.0)

        elif key == "tornado":
            # hortum: kalabalığın ortasına iner, yaratıkları oraya toplar,
            # canlarını keser ve huninin içinde kalanı öğütür.
            bx = sum(e.x for e in targets) / len(targets)
            by = sum(e.y for e in targets) / len(targets)
            # Ama tam oyuncunun üstüne de inmesin: bütün sürüyü kucağına
            # boşaltmak ölüm tuzağı olurdu. En az bu kadar uzağa itilir.
            d0 = dist(bx, by, p.x, p.y)
            if d0 < 240:
                a0 = math.atan2(by - p.y, bx - p.x) if d0 > 1 else ang
                bx = p.x + math.cos(a0) * 260
                by = p.y + math.sin(a0) * 260
            self.tornados.append(tor := Tornado(bx, by, lvl=lvl, dps=dmg))
            self.fx.do_flash(TORNADO_COLOR, 0.22)
            self.fx.shockwave(bx, by, tor.PULL_R * 0.5, TORNADO_COLOR, 0.6, 6)
            self.fx.shake(9, 0.4)
            self.fx.popup(bx, by - 170, "HORTUM!", TORNADO_COLOR2, 26, life=1.2)
            sfx("vortex", 0.7, 0.0)

        elif key == "tesla":
            # yıldırım zinciri: en yakın yaratığa çakar, sonra her adımda henüz
            # çarpılmamış en yakın komşuya sıçrar (TESLA_JUMP_R).
            n_hit = tesla_targets(lvl)
            cur = nearest
            pts = [(p.x, p.y - 8)]
            done = set()
            hdmg = dmg
            for i in range(n_hit):
                if cur is None:
                    break
                done.add(id(cur))
                pts.append((cur.x, cur.y))
                self._weapon_hit(cur, hdmg, kb=30, wlvl=lvl)
                if hasattr(cur, "apply_slow") and not getattr(cur, "is_boss", False):
                    cur.apply_slow(0.45, 0.30)
                self.fx.burst(cur.x, cur.y, TESLA_COLOR2, n=4, speed=160, life=0.22, r=2.2)
                hdmg *= TESLA_FALLOFF
                nxt, best = None, TESLA_JUMP_R
                for e in self._all_targets():
                    if not e.alive or id(e) in done:
                        continue
                    d = dist(cur.x, cur.y, e.x, e.y)
                    if d < best:
                        nxt, best = e, d
                cur = nxt
            for a_, b_ in zip(pts, pts[1:]):
                self.fx.bolt(zigzag(a_[0], a_[1], b_[0], b_[1], 6, 14), TESLA_COLOR, 0.22)
                self.fx.bolt(zigzag(a_[0], a_[1], b_[0], b_[1], 4, 6), TESLA_COLOR2, 0.14)
            sfx("lightning", 0.36, 0.06)

        elif key == "meteor":
            # meteor yağmuru: göktaşları ekranda görünen kalabalığa düşer - en
            # çok komşusu olan yaratıklar önce seçilir, üst üste düşmesinler
            # diye aralarında en az bir yarıçap olur.
            rad = meteor_radius(lvl)
            vis = self.cam_rect().inflate(-40, -40)
            pool = [e for e in targets if vis.collidepoint(e.x, e.y)] or list(targets)
            sample = pool if len(pool) <= 40 else random.sample(pool, 40)

            def crowd(e):
                return sum(1 for o in sample if dist(o.x, o.y, e.x, e.y) < rad)
            sample.sort(key=lambda e: -crowd(e) + random.uniform(0, 0.8))
            spots = []
            for e in sample:
                if all(dist(e.x, e.y, sx, sy) > rad for (sx, sy) in spots):
                    spots.append((e.x, e.y))
                if len(spots) >= meteor_count(lvl):
                    break
            for i, (sx, sy) in enumerate(spots):
                self.meteors.append(MeteorStrike(sx, sy, rad, dmg, lvl,
                                                 METEOR_DELAY + 0.16 * i))
            sfx("blaze", 0.30, 0.05)

        elif key == "bats":
            # yarasa sürüsü: eşit aralıklı, yarısı saat yönünde dönen sarmal.
            n_b = bat_count(lvl)
            a0 = random.uniform(0, math.tau)
            for i in range(n_b):
                self.bats.append(BatSwarmBat(p, a0 + i * math.tau / n_b,
                                             1 if i % 2 == 0 else -1, dmg, lvl))
            sfx("dash", 0.22, 0.05)

        elif key == "nova":
            # ayaz patlaması: çevredeki herkese hasar; sıradan yaratıklar
            # donar.
            rad = nova_radius(lvl)
            frz = nova_freeze(lvl)
            for e in self._all_targets():
                if not e.alive:
                    continue
                if dist(p.x, p.y, e.x, e.y) <= rad + getattr(e, "radius", 12):
                    self._weapon_hit(e, dmg, kb=120, wlvl=lvl)
                    if hasattr(e, "apply_slow"):
                        if getattr(e, "is_boss", False):
                            e.apply_slow(0.6, frz)
                        else:
                            e.apply_slow(0.02, frz)
            self.novas.append(FrostNova(p.x, p.y, rad))
            sfx("ice_step", 0.6, 0.0)

        elif key == "knives":
            # bıçak yelpazesi: nişan yönüne yelpaze.
            adx, ady = p.aim_dir
            base = math.atan2(ady, adx)
            n_k = knife_count(lvl)
            fan = 0.70 + 0.04 * n_k
            for i in range(n_k):
                a = base + (i - (n_k - 1) / 2.0) * (fan / max(1, n_k - 1))
                self.knives.append(ThrownKnife(p.x + math.cos(a) * 12, p.y + math.sin(a) * 12,
                                               a, dmg, knife_pierce(lvl), lvl))
            sfx("whip", 0.22, 0.04)

        elif key == "quake":
            # deprem: ayağının altında birikip patlayan halka.
            self.quakes.append(QuakeCharge(p, quake_radius(lvl), dmg, lvl))
            sfx("ice_step", 0.30, 0.08)

        elif key == "beam":
            # güneş ışını: nişan yönünden başlayıp tam tur döner.
            adx, ady = p.aim_dir
            self.beams.append(SunBeam(p, math.atan2(ady, adx), beam_count(lvl),
                                      beam_len(lvl), dmg, lvl))
            self.fx.ring(p.x, p.y, BEAM_COLOR, n=14, speed=200, life=0.35, r=3)
            sfx("blaze", 0.40, 0.0)

    def do_bonk(self):
        DMG_SRC[0] = "bonk"
        p = self.player
        # yeşil dev - ezici darbe: 10 saniyede bir, bonk tüm arenayı kaplar ve
        # patronlar dışındaki her düşmanın canını yarıya indirir.
        smash = bool(p.titan_smash) and p.smash_timer <= 0
        if smash:
            p.smash_timer = self.TITAN_SMASH_CD
            radius = math.hypot(ARENA_RECT.width, ARENA_RECT.height)
            self._titan_smash_fx(p)
        else:
            radius = p.eff_bonk_radius()
        dmg = p.eff_dmg() * 1.9 * p.bonk_mult
        hit_any = 0
        hit_ids = set()
        for e in self._all_targets():
            if not e.alive:
                continue
            d = dist(p.x, p.y, e.x, e.y)
            if d <= radius:
                hit_any += 1
                hit_ids.add(id(e))
                crit = random.random() < p.eff_crit_chance()
                final_dmg = dmg * (p.eff_crit_dmg() if crit else 1.0)
                final_dmg = self._apply_execute(p, e, final_dmg)
                kx, ky = norm_dir(p.x, p.y, e.x, e.y)
                if p.boss_hunter > 0 and (getattr(e, "is_boss", False) or e.kind == "elite"):
                    final_dmg *= (1.0 + p.boss_hunter_bonus())
                died = e.take_damage(final_dmg, crit, self.fx, kx * 260, ky * 260)
                # kükreme kitabı: bonk yiyen sıradan düşmanlar korkup kaçar
                if p.roar_level > 0 and not getattr(e, "is_boss", False) and hasattr(e, "fear_timer"):
                    e.fear_timer = max(e.fear_timer, 1.0 + 0.6 * p.roar_level)
                    # Korkan yaratık savunmasız kalır: Lv.1 +%30, Lv.5 +%50.
                    e.fear_vuln = max(e.fear_vuln,
                                      min(0.60, 0.25 + 0.05 * p.roar_level))
                if p.vamp_level > 0:
                    p.lifesteal(final_dmg * 0.02 * p.vamp_level)
                if died:
                    self.on_enemy_killed(e)
        if smash:
            # Canı yarıya indirme: hasardan ayrı bir etkidir, patronlara
            # işlemez.
            for e in self.enemies:
                if e.alive and not getattr(e, "is_boss", False) and e.hp > 1:
                    e.hp = max(1.0, e.hp * self.TITAN_SMASH_HP_CUT)
                    self.fx.spark(e.x, e.y, (170, 255, 140), 0, -40, .5, 3)
        self.bonk_hits += hit_any
        if hit_any >= 8 and self.ach:
            self.ach.unlock("bonk8")
        if p.chain_level > 0:
            candidates = [e for e in self.enemies if e.alive and id(e) not in hit_ids
                          and dist(p.x, p.y, e.x, e.y) <= radius * 2.2]
            candidates.sort(key=lambda e: dist(p.x, p.y, e.x, e.y))
            for e in candidates[:1 + p.chain_level]:
                cdmg = dmg * 0.5
                died = e.take_damage(cdmg, False, self.fx)
                self.fx.ring(e.x, e.y, (120, 200, 255), n=8, speed=120, life=0.25, r=2)
                if died:
                    self.on_enemy_killed(e)
        self.fx.ring(p.x, p.y, ORANGE, n=20, speed=260, life=0.35, r=3)
        self.fx.shockwave(p.x, p.y, radius, ORANGE, 0.3, 4)
        self.fx.shake(6 if hit_any else 3, 0.15)
        sfx("bonk", 1.0, 0.0)

    def do_storm_strike(self):
        DMG_SRC[0] = "storm"
        p = self.player
        targets = [e for e in self.enemies if e.alive]
        targets.extend(b for b in self.bosses if b.alive)
        if not targets:
            return
        e = random.choice(targets)
        dmg = p.eff_dmg() * (0.9 + 0.35 * p.storm_level)
        died = e.take_damage(dmg, False, self.fx)
        self.fx.bolt(zigzag(e.x, e.y - 320, e.x, e.y, 6, 22), (190, 215, 255), 0.3)
        self.fx.shockwave(e.x, e.y, 40, (190, 215, 255), 0.25, 3)
        sfx("lightning", 0.7, 0.0)
        if died:
            self.on_enemy_killed(e)

    # ---- skin özel yetenekleri ----
    # Yetenekler otomatik çalışır. ortak kural: hangi yetenek tetiklenirse
    # tetiklensin düşmanlar ULT_FREEZE_ON_CAST kadar (0.5 sn) donar, sonra
    # hareketlerine kaldıkları yerden devam eder.

    def _densest_point(self, p, reach, cluster_r):
        """Oyuncunun yakınında düşmanların en sık olduğu nokta (kara delik)."""
        cand = [e for e in self.enemies if e.alive and dist(p.x, p.y, e.x, e.y) <= reach]
        if not cand:
            ax, ay = getattr(p, "aim_dir", (1.0, 0.0))
            return p.x + ax * 220, p.y + ay * 220
        if len(cand) > 90:
            cand = random.sample(cand, 90)
        best, best_n = cand[0], -1
        r2 = cluster_r * cluster_r
        for e in cand:
            n = 0
            for o in cand:
                dx, dy = e.x - o.x, e.y - o.y
                if dx * dx + dy * dy <= r2:
                    n += 1
            if n > best_n:
                best, best_n = e, n
        return best.x, best.y

    def _update_black_holes(self, dt):
        if not self.black_holes:
            return
        p = self.player
        keep = []
        for bh in self.black_holes:
            bh["t"] += dt
            x, y, R = bh["x"], bh["y"], bh["r"]
            # çekim: merkeze yakın olan daha hızlı çekilir; patron az kıpırdar
            for e in self._all_targets():
                if not e.alive:
                    continue
                dx, dy = x - e.x, y - e.y
                d = math.hypot(dx, dy)
                if d > R or d < 6:
                    continue
                pull = (90.0 + 360.0 * (1.0 - d / R)) * (0.18 if getattr(e, "is_boss", False) else 1.0)
                step = min(d - 4, pull * dt)
                e.x += dx / d * step
                e.y += dy / d * step
            bh["tick"] -= dt
            if bh["tick"] <= 0:
                bh["tick"] = 0.3
                for e in self._all_targets():
                    if e.alive and dist(x, y, e.x, e.y) <= R * 0.55:
                        self._ult_hit(e, p.eff_dmg() * 0.22)
            if bh["t"] >= bh["dur"]:
                for e in self._all_targets():
                    if e.alive and dist(x, y, e.x, e.y) <= R * 0.8:
                        self._ult_hit(e, p.eff_dmg() * bh["mult"], crit=True)
                col = (180, 150, 255)
                self.fx.do_flash((200, 180, 255), 0.35)
                self.fx.shake(14, 0.4)
                for k in range(3):
                    self.fx.shockwave(x, y, R * (0.5 + 0.3 * k), col, 0.45 + 0.1 * k, 7 - 2 * k)
                self.fx.burst(x, y, (200, 180, 255), n=46, speed=420, life=0.7, r=5)
                self.fx.burst(x, y, (130, 230, 255), n=24, speed=260, life=0.6, r=4)
                sfx("explosion", 1.0, 0.0)
            else:
                keep.append(bh)
        self.black_holes = keep

    def _ult_targets(self, radius=None):
        """Yeteneğin vuracağı canlı hedefler (patronlar dâhil)."""
        p = self.player
        out = []
        for e in self._all_targets():
            if not e.alive:
                continue
            if radius is None or dist(p.x, p.y, e.x, e.y) <= radius:
                out.append(e)
        return out

    def _ult_hit(self, e, dmg, crit=False, kb=0.0):
        """Yetenek hasarı uygular; ölürse ödülleri işler."""
        p = self.player
        if p.boss_hunter > 0 and (getattr(e, "is_boss", False) or getattr(e, "kind", "") == "elite"):
            dmg *= (1.0 + p.boss_hunter_bonus())
        kx, ky = norm_dir(p.x, p.y, e.x, e.y)
        died = e.take_damage(dmg, crit, self.fx, kx * kb, ky * kb)
        if died:
            self.on_enemy_killed(e)
        return died

    def freeze_enemies(self, duration):
        """Zamanı durdurur: düşmanlar, patronlar, mermileri ve tuzakları donar."""
        self.time_stop = max(self.time_stop, float(duration))

    def _ult_spawn_nova(self, n, mult, pierce=1, homing=0, style=None, spread=math.tau,
                        base_ang=None, speed=640):
        """Oyuncunun çevresine halka biçiminde mermi saçar."""
        p = self.player
        sk = p.skin
        if base_ang is None:
            base_ang = math.atan2(p.aim_dir[1], p.aim_dir[0])
        for i in range(n):
            ang = base_ang + (spread * i / n if spread >= math.tau else
                              (spread * (i / max(1, n - 1) - 0.5)))
            vx, vy = math.cos(ang) * speed, math.sin(ang) * speed
            self.player_projectiles.append(PlayerProjectile(
                p.x + math.cos(ang) * (p.radius + 6), p.y + math.sin(ang) * (p.radius + 6),
                vx, vy, p.eff_dmg() * mult, p.eff_pierce_hits() + pierce,
                p.eff_crit_chance(), p.eff_crit_dmg(), homing=homing,
                style=style or sk["proj"], color=sk["color"], accent=sk["accent"]))
            self.player_projectiles[-1]._wsrc = "ult"
        p.run_shots += n

    def _ult_lightning_fx(self, x, y, color=(190, 215, 255)):
        self.fx.bolt(zigzag(x, y - 320, x, y, 6, 22), color, 0.3)
        self.fx.shockwave(x, y, 46, color, 0.25, 3)

    def _ult_banner(self, text, color):
        p = self.player
        self.fx.popup(p.x, p.y - 58, text, color, 26, life=1.0)

    def update_skin_ult(self, dt):
        """Skin yeteneğinin bekleme süresini işler ve zamanı gelince çalıştırır."""
        p = self.player
        if not p.ult or not p.alive:
            return
        DMG_SRC[0] = "ult"
        # Şarta bağlı (trigger) yetenekler Player içinde işaretlenir.
        if p.ult_trigger:
            kind = p.ult_trigger
            p.ult_trigger = None
            self.fire_skin_ult(kind)
        elif p.ult.get("mode", "auto") == "auto" and p.ult_ready():
            p.start_ult_cooldown()
            self.fire_skin_ult(p.ult["kind"])

        # ---- kara delik ----
        self._update_black_holes(dt)
        # ---- diken tarlası: süresi boyunca çevreyi zehirlemeye devam eder ----
        if p.thorn_field_t > 0:
            p.thorn_field_t -= dt
            p.thorn_field_tick -= dt
            if p.thorn_field_tick <= 0:
                p.thorn_field_tick = 0.5
                for e in self._ult_targets(p.thorn_field_r):
                    self._ult_hit(e, p.eff_dmg() * 0.35)
                    if hasattr(e, "apply_slow"):
                        e.apply_slow(0.7, 0.8)
                self.fx.shockwave(p.x, p.y, p.thorn_field_r, (120, 220, 140), 0.3, 3)

    def fire_skin_ult(self, kind):
        """Bir skin yeteneğini çalıştırır."""
        p = self.player
        ult = p.ult or {}
        col = tuple(ult.get("color", (255, 255, 255)))
        # ortak kural: her yetenek düşmanları kısa süre dondurur.
        self.freeze_enemies(ULT_FREEZE_ON_CAST)
        self.fx.ring(p.x, p.y, col, n=22, speed=260, life=0.45, r=3.5)
        self.fx.shake(6, 0.2)
        p.ult_fx_t = 0.5
        name = TRX(ult.get("name", "YETENEK"))

        # ---- klasik mavi: kalkan protokolü ----
        if kind == "guard":
            p.shield_charges += 2
            p.heal(p.max_hp * 0.15)
            self.fx.shockwave(p.x, p.y, 120, col, 0.4, 5)
            self._ult_banner(name, col)
            sfx("shield", 1.0, 0.0)

        # ---- yeşil öncü: öncü atılımı ----
        elif kind == "sprint":
            p.add_temp_buff(6.0, run_spd_mult=0.35, run_aspd_mult=0.25)
            p.dash_cd_timer = 0.0
            self._ult_banner(name, col)
            sfx("dash", 1.0, 0.0)

        # ---- çok yönlü mermi yağmuru ----
        elif kind == "nova":
            self._ult_spawn_nova(int(ult.get("n", 14)), float(ult.get("mult", 0.85)),
                                 pierce=int(ult.get("pierce", 1)))
            self._ult_banner(name, col)
            sfx("shoot_" + p.skin["sfx"], 0.7, 0.0)

        # ---- güdümlü salvo ----
        elif kind == "salvo":
            self._ult_spawn_nova(int(ult.get("n", 9)), float(ult.get("mult", 0.95)),
                                 pierce=1, homing=2)
            self._ult_banner(name, col)
            sfx("shoot_" + p.skin["sfx"], 0.7, 0.0)

        # ---- zehir bulutu ----
        elif kind == "poison_cloud":
            rad = float(ult.get("radius", 280))
            for e in self._ult_targets(rad):
                if hasattr(e, "apply_poison"):
                    e.apply_poison(6.0)
                if hasattr(e, "apply_slow"):
                    e.apply_slow(0.6, 3.0)
                self._ult_hit(e, p.eff_dmg() * 0.5)
            self.fx.shockwave(p.x, p.y, rad, col, 0.5, 6)
            self._ult_banner(name, col)
            sfx("explosion", 0.7, 0.0)

        # ---- kraliyet fermanı ----
        elif kind == "star_fall":
            targets = self._ult_targets()
            random.shuffle(targets)
            for e in targets[:int(ult.get("n", 7))]:
                self._ult_hit(e, p.eff_dmg() * float(ult.get("mult", 1.35)), kb=90)
                self.fx.burst(e.x, e.y, col, n=10, speed=150, life=0.4, r=3)
                self.fx.shockwave(e.x, e.y, 54, col, 0.3, 3)
            self._ult_banner(name, col)
            sfx("levelup", 0.8, 0.0)

        # ---- elektrik cyan: yıldırım fırtınası ----
        elif kind == "chain_storm":
            # Haritadaki herkese yıldırım düşer:
            # - sıradan düşman / elit: azami canının %20'si gider
            # - patron: Lv.3 fırtına hasarı (yüzde değil)
            boss_dmg = p.eff_dmg() * (0.9 + 0.35 * 3)
            for e in self._ult_targets():
                if getattr(e, "is_boss", False):
                    self._ult_hit(e, boss_dmg)
                else:
                    self._ult_hit(e, max(1.0, e.max_hp * 0.20))
                self._ult_lightning_fx(e.x, e.y, col)
            self.fx.do_flash(col, 0.35)
            self._ult_banner(name, col)
            sfx("lightning", 1.0, 0.0)

        # ---- gölge suikastçı: gölge duruşu ----
        elif kind == "death_defy":
            dur = float(ult.get("duration", 5.0))
            # Zaman durur: düşmanlar, mermileri ve tuzaklar donar; oyuncu
            # serbest.
            self.freeze_enemies(dur)
            p.hp = max(1.0, p.hp)
            p.invuln = max(p.invuln, dur + 0.4)
            self.fx.do_flash(col, 0.5)
            for k in range(3):
                self.fx.shockwave(p.x, p.y, 200 + k * 180, col, 0.6, 6 - k)
            self._ult_banner(name + "  -  ZAMAN DURDU", col)
            sfx("second", 1.0, 0.0)

        # ---- inferno: alev halkası ----
        elif kind == "fire_ring":
            rad = float(ult.get("radius", 330))
            for e in self._ult_targets(rad):
                self._ult_hit(e, p.eff_dmg() * 1.1, kb=140)
                if hasattr(e, "apply_burn"):
                    e.apply_burn(10.0, 4.0)
            for k in range(3):
                self.fx.shockwave(p.x, p.y, rad * (0.5 + k * 0.28), col, 0.45, 6 - k)
            self.fx.burst(p.x, p.y, col, n=26, speed=280, life=0.6, r=4)
            self._ult_banner(name, col)
            sfx("explosion", 1.0, 0.0)

        # ---- altın efsane: altın dokunuş ----
        elif kind == "midas":
            rad = float(ult.get("radius", 340))
            for e in self._ult_targets(rad):
                self._ult_hit(e, p.eff_dmg() * 0.9)
                if e.alive:
                    self.pickups.append(Pickup(e.x + random.uniform(-10, 10),
                                               e.y + random.uniform(-10, 10), "coin",
                                               max(2, int(e.coin * 0.6))))
                self.fx.spark(e.x, e.y, GOLD, 0, -40, 0.5, 3)
            self.fx.shockwave(p.x, p.y, rad, GOLD, 0.45, 5)
            self._ult_banner(name, GOLD)
            sfx("coin", 1.0, 0.0)

        # ---- gölge avcı: sessiz pusu ----
        elif kind == "ambush":
            dur = float(ult.get("duration", 4.0))
            p.invuln = max(p.invuln, dur)
            p.crit_forced = max(p.crit_forced, dur)
            p.add_temp_buff(dur, run_spd_mult=0.2)
            for k in range(6):
                p.ghosts.append([p.x, p.y, 0.5, (90, 60, 150)])
            self._ult_banner(name, col)
            sfx("dash", 1.0, 0.0)

        # ---- buz büyücüsü: buz çağı ----
        elif kind == "ice_age":
            freeze = float(ult.get("freeze", 2.5))
            self.freeze_enemies(freeze)
            for e in self._ult_targets():
                self._ult_hit(e, p.eff_dmg() * 0.7)
                if hasattr(e, "apply_slow"):
                    e.apply_slow(0.45, freeze + 5.0)
            self.fx.do_flash(col, 0.3)
            self.fx.shockwave(p.x, p.y, 520, col, 0.6, 6)
            self._ult_banner(name, col)
            sfx("shield", 1.0, 0.0)

        # ---- kan kontesi: kan ayini ----
        elif kind == "blood_rite":
            rad = float(ult.get("radius", 320))
            drained = 0.0
            for e in self._ult_targets(rad):
                dmg = e.max_hp * 0.10 + p.eff_dmg() * 0.5
                before = e.hp
                self._ult_hit(e, dmg)
                drained += max(0.0, before - max(0.0, e.hp))
                self.fx.bolt([(e.x, e.y), (p.x, p.y)], (235, 70, 100), 0.25)
            if drained > 0:
                p.lifesteal(drained * 0.5, capped=False)
            self.fx.shockwave(p.x, p.y, rad, col, 0.45, 5)
            self._ult_banner(name, col)
            sfx("hurt", 0.8, 0.0)

        # ---- zırhlı devriye: zırh kilidi ----
        elif kind == "bulwark":
            dur = float(ult.get("duration", 6.0))
            p.add_temp_buff(dur, dmg_taken_mult=-0.55)
            p.shield_charges += 1
            for e in self._ult_targets(260):
                self._ult_hit(e, p.eff_dmg() * 0.6, kb=420)
            self.fx.shockwave(p.x, p.y, 260, col, 0.45, 6)
            self._ult_banner(name, col)
            sfx("shield", 1.0, 0.0)

        # ---- fırtına getirici: gök gürültüsü ----
        elif kind == "thunder":
            targets = self._ult_targets()
            random.shuffle(targets)
            n = int(ult.get("n", 6))
            for e in targets[:n] if targets else []:
                self._ult_hit(e, p.eff_dmg() * float(ult.get("mult", 1.6)))
                self._ult_lightning_fx(e.x, e.y, col)
            self.fx.do_flash(col, 0.3)
            self._ult_banner(name, col)
            sfx("lightning", 1.0, 0.0)

        # ---- zehir vuruşçu: diken tarlası ----
        elif kind == "thorn_field":
            p.thorn_field_t = float(ult.get("duration", 6.0))
            p.thorn_field_r = float(ult.get("radius", 240))
            p.thorn_field_tick = 0.0
            self.fx.shockwave(p.x, p.y, p.thorn_field_r, col, 0.45, 5)
            self._ult_banner(name, col)
            sfx("buy", 0.8, 0.0)

        # ---- çılgın canavar: kan çılgınlığı ----
        elif kind == "frenzy_rush":
            dur = float(ult.get("duration", 7.0))
            p.add_temp_buff(dur, run_dmg_mult=0.40, run_aspd_mult=0.30)
            p.frenzy_stacks = max(p.frenzy_stacks, 4)
            p.frenzy_timer = max(p.frenzy_timer, dur)
            self.fx.do_flash(col, 0.25)
            self._ult_banner(name, col)
            sfx("bonk", 0.9, 0.0)

        # ---- yörünge bekçisi: yörünge kalkanı ----
        elif kind == "orbit_shield":
            dur = float(ult.get("duration", 8.0))
            p.add_temp_buff(dur, orbit_level=3)
            p.shield_charges += 1
            self.fx.shockwave(p.x, p.y, 120, col, 0.4, 5)
            self._ult_banner(name, col)
            sfx("shield", 1.0, 0.0)

        # ---- ağ ustası: ağ tuzağı ----
        elif kind == "web_trap":
            rad = float(ult.get("radius", 360))
            for e in self._ult_targets(rad):
                if hasattr(e, "apply_slow"):
                    e.apply_slow(0.12, 4.0)
                self._ult_hit(e, p.eff_dmg() * 0.6)
                self.fx.bolt([(p.x, p.y), (e.x, e.y)], (240, 240, 255), 0.3)
            self.fx.shockwave(p.x, p.y, rad, col, 0.45, 5)
            self._ult_banner(name, col)
            sfx("shoot_a", 0.8, 0.0)

        # ---- kül savaşçısı: kül kasırgası ----
        elif kind == "ash_spin":
            rad = float(ult.get("radius", 230))
            total = 0.0
            for e in self._ult_targets(rad):
                dmg = p.eff_dmg() * float(ult.get("mult", 2.0))
                before = e.hp
                self._ult_hit(e, dmg, kb=260)
                total += max(0.0, before - max(0.0, e.hp))
            if total > 0:
                p.lifesteal(total * 0.25, capped=False)
            for k in range(3):
                self.fx.shockwave(p.x, p.y, rad * (0.55 + k * 0.25), col, 0.4, 5 - k)
            self._ult_banner(name, col)
            sfx("bonk", 1.0, 0.0)

        # ---- yeşil dev: yer sarsıntısı ----
        elif kind == "quake":
            for e in self._ult_targets():
                self._ult_hit(e, p.eff_dmg() * float(ult.get("mult", 1.3)), kb=360)
                self.fx.spark(e.x, e.y, col, 0, -50, 0.5, 3)
            self.fx.shake(18, 0.5)
            for k in range(4):
                self.fx.shockwave(p.x, p.y, 240 + k * 260, col, 0.55, 8 - k)
            self._ult_banner(name, col)
            sfx("explosion", 1.0, 0.0)

        # ---- pembe rüya: rüya patlaması ----
        # kozmik gezgin: kara delik.
        elif kind == "black_hole":
            rad = float(ult.get("radius", 430))
            cx, cy = self._densest_point(p, 700.0, 210.0)
            self.black_holes.append({"x": cx, "y": cy, "t": 0.0, "dur": float(ult.get("duration", 3.0)),
                                     "r": rad, "mult": float(ult.get("mult", 2.6)), "tick": 0.0})
            self.fx.shockwave(cx, cy, rad, col, 0.5, 4)
            self._ult_banner(name, col)
            sfx("vortex", 1.0, 0.0)

        elif kind == "dream":
            rad = float(ult.get("radius", 300))
            dur = float(ult.get("duration", 6.0))
            p.heal(p.max_hp * 0.25)
            p.add_temp_buff(dur, run_crit_bonus=0.25)
            for e in self._ult_targets(rad):
                self._ult_hit(e, p.eff_dmg() * 0.7)
                if hasattr(e, "fear_timer"):
                    e.fear_timer = max(e.fear_timer, 3.0)
            self.fx.shockwave(p.x, p.y, rad, col, 0.5, 6)
            self.fx.burst(p.x, p.y, col, n=24, speed=220, life=0.6, r=4)
            self._ult_banner(name, col)
            sfx("levelup", 0.9, 0.0)

    # Yerdeki eşya sayısının üst sınırı. Bu sayının üstünde birleştirme
    # yarıçapı büyür; yani eşyalar kaybolmaz, tek yığında toplanır.
    PICKUP_SOFT_CAP = 160
    PICKUP_MERGE_R = 30.0
    PICKUP_MERGE_R_BUSY = 95.0
    # son emniyet: yerdeki eşya sayısı bunu aşarsa yeni bir nesne hiç eklenmez;
    # düşen kazanç en yakın aynı türden yığına katılır.
    PICKUP_HARD_CAP = 240

    def drop_pickup(self, x, y, kind, value):
        """Yere altın/tecrübe düşürür; yakındaki aynı türden eşyayla birleştirir."""
        if value <= 0:
            return
        merge_r = (self.PICKUP_MERGE_R_BUSY if len(self.pickups) > self.PICKUP_SOFT_CAP
                   else self.PICKUP_MERGE_R)
        best, best_d = None, merge_r
        for pu in self.pickups:
            if pu.kind != kind or pu.collected or pu.magnet:
                continue
            # altın: yalnızca yeterince yeni bir parayla birleşir.
            d = dist(x, y, pu.x, pu.y)
            if d < best_d:
                best, best_d = pu, d
        if best is None and len(self.pickups) >= self.PICKUP_HARD_CAP:
            # Tavan doldu: mesafeye ve yaşa bakmadan en yakın aynı türden
            # yığına kat. Kazanç kaybolmaz, ekrandaki nesne sayısı büyümez.
            for pu in self.pickups:
                if pu.kind != kind or pu.collected or pu.magnet:
                    continue
                d = dist(x, y, pu.x, pu.y)
                if best is None or d < best_d:
                    best, best_d = pu, d
        if best is not None:
            best.value += value
            return
        self.pickups.append(Pickup(x + random.uniform(-8, 8), y + random.uniform(-8, 8),
                                   kind, value))

    def on_enemy_killed(self, e):
        # Bir ölüm yalnızca bir kez sayılır.
        if getattr(e, "death_counted", False):
            return
        try:
            e.death_counted = True
        except AttributeError:
            pass        # __slots__ kullanan bir tür gelirse sessizce geç
        # bombacı öldüğü yerde patlar.
        if getattr(e, "kind", "") == "bomber":
            self.hazards.append(Hazard(e.x, e.y, BOMBER_RADIUS, BOMBER_DELAY,
                                       e.dmg * BOMBER_DMG_MULT,
                                       color=ENEMY_COLORS["bomber"]))
            self.fx.ring(e.x, e.y, ENEMY_COLORS["bomber"], n=16, speed=180,
                         life=0.4, r=3)
        p = self.player
        self.kills += 1
        if getattr(e, "variant", None) == "j_snake":
            self.snakes_killed += 1
        self.combo.add_kill()
        # kan kitabı: her öldürmede bir miktar can geri kazanılır. Sabit pay
        # (perk/eşya kaynaklı) ve oransal pay (kitap) birlikte işler.
        heal = p.kill_heal + p.kill_heal_amount()
        if heal > 0:
            p.heal(heal)
        # ruh hasadı (cehennem eşyası): can + yığılan hasar bonusu
        if p.soul_harvest > 0:
            p.heal(2.0 * p.soul_harvest)
            p.soul_stacks = min(p.soul_stacks + 1, 4 + 4 * p.soul_harvest)
            p.soul_timer = 5.0
        p.register_kill_for_frenzy()
        combo_mult = self.combo.multiplier()
        coin_gain = scaled_coin_gain(e.coin, p.eff_coin_mult()
                                     * econ_wave_factor(self.waves.wave, self.biome, "gold", self.diff),
                                     self.biome)
        xp_gain = (e.xp * econ_wave_factor(self.waves.wave, self.biome, "xp", self.diff)
                   * xp_level_softcap(p.level, self.total_wave()))
        if getattr(e, "kind", "") == "goblin":
            self._goblin_loot(e)
        # Altın artık ölüm anında verilmiyor: yere düşen parayı toplaman gerek.
        gain = (e.score * combo_mult * (1.0 + self.curse_score_bonus) * SCORE_GAIN
                + self.score_frac)
        self.score += int(gain)
        self.score_frac = gain - int(gain)
        if not getattr(e, "raised", False):
            # Diriltilmiş iskelet altın/tecrübe düşürmez (sonsuz döngü
            # olmasın).
            self.drop_pickup(e.x, e.y, "coin", coin_gain)
            self.drop_pickup(e.x, e.y, "xp", xp_gain)
        self._on_cursed_death(e)
        if random.random() < HEART_DROP_CHANCE and p.hp < p.max_hp * 0.9:
            self.pickups.append(Pickup(e.x, e.y, "heart", 26))
        # mıknatıs: binde 2.5 düşer (kötü şansa karşı kademeli garanti için).
        can_stone = self.level_drops_total < self.magnets_dropped
        if can_stone:
            self.level_kills += 1
        if (can_stone and not self.level_drops
                and random.random() < magnet_drop_chance(self.level_kills) * LEVEL_STONE_RATE):
            self.level_kills = 0
            self.level_drops_total += 1
            self.level_drops.append(LevelDrop(e.x, e.y))
            self.fx.popup(e.x, e.y - 58, "SEVİYE TAŞI!", LEVEL_COLOR, 26, life=2.2)
            self.fx.ring(e.x, e.y, LEVEL_COLOR, n=30, speed=300, life=0.8, r=4)
            self.fx.shockwave(e.x, e.y, 160, LEVEL_COLOR2, 0.5, 5)
            self.fx.do_flash(LEVEL_COLOR, 0.30)
            sfx("levelup", 0.8, 0.0)
        self.magnet_kills += 1
        if not self.magnets and random.random() < magnet_drop_chance(self.magnet_kills,
                                                                     p.eff_luck()):
            self.magnet_kills = 0
            self.magnets_dropped += 1
            self.magnets.append(MagnetDrop(e.x, e.y))
            self.fx.popup(e.x, e.y - 58, "MIKNATIS DÜŞTÜ!", MAGNET_COLOR, 26, life=2.2)
            self.fx.ring(e.x, e.y, MAGNET_COLOR, n=30, speed=300, life=0.8, r=4)
            self.fx.shockwave(e.x, e.y, 160, MAGNET_COLOR2, 0.5, 5)
            self.fx.do_flash(MAGNET_COLOR, 0.30)
            sfx("magnet", 0.85, 0.0)
        if self.combo.count > 0 and self.combo.count % 10 == 0:
            self.fx.popup(p.x, p.y - 50, f"COMBO x{self.combo.count}!", CYAN, 24, life=1.0)
        if self.combo.count >= 30 and self.ach:
            self.ach.unlock("combo30")
        if self.kills == 1 and self.ach:
            self.ach.unlock("first_kill")
        if self.kills >= 250 and self.ach:
            self.ach.unlock("massacre")
        if getattr(e, "is_boss", False):
            # şampiyon, yerine geçtiği patron sayısı kadar sayılır
            nb = max(1, int(getattr(e, "champion", 1)))
            self.save.data["stats"]["bosses"] = self.save.data["stats"].get("bosses", 0) + nb
            # Günlük görev için bu koşuda devrilen patron sayısı.
            self.bosses_killed = getattr(self, "bosses_killed", 0) + nb
            if self.ach:
                self.ach.unlock("boss")
        # sancaktar devrildi: taşıdığı sandığı düşürür.
        if getattr(e, "is_mini", False):
            self.spawn_boss_chest(e)
            for g in (e.guards or []):
                if g.alive:
                    g.guard_of = None

    def update(self, dt, input_state):
        if self.game_over or self.pending_levelups > 0:
            self.fx.update(dt)
            return

        p = self.player
        DMG_LOG[0] = self.dmg_log
        DMG_SRC[0] = "other"
        EVO_CTX[0] = self
        self.run_time += dt
        # koşu görevleri: yarım saniyede bir bakılır.
        self.quest_t -= dt
        if self.quest_t <= 0:
            self.quest_t = 0.5
            if self.quests and not self.game_over:
                self.update_quests()
            if self.map_theme != "stone" and not self.game_over:
                self.check_map_achs()
        if self.quest_flash > 0:
            self.quest_flash = max(0.0, self.quest_flash - dt)
        # sur yemini: 40 sn'de bir kalkan dolar (en çok 3).
        if self.oath == "bulwark":
            self.oath_t += dt
            if self.oath_t >= self.oath_period:
                self.oath_t = 0.0
                if self.player.shield_charges < 3:
                    self.player.shield_charges += 1
                    self.fx.popup(self.player.x, self.player.y - 40, "+1", (170, 180, 255), 16, life=0.7)
        # hile koruması: oyuncunun değerleri yarım saniyede bir denetlenir.
        # (Her karede bakmanın anlamı yok; denetim ucuz ama bedavaya değil.)
        self.integrity_timer -= dt
        if self.integrity_timer <= 0:
            self.integrity_timer = 0.5
            if not self.cheat_flag:
                bad = run_integrity_check(self)
                if bad:
                    self.cheat_flag = bad
        if self.time_stop > 0:
            self.time_stop = max(0.0, self.time_stop - dt)
        p.update(dt, input_state, self.fx)
        if self.evo_perks:
            self.evo_update(dt)
        self.extras_update(dt)
        self.update_camera(dt)
        # Skin yeteneği: süresi dolduysa kendiliğinden çalışır (ve zamanı
        # durdurabilir).
        self.update_skin_ult(dt)
        # dikkat: 'frozen' yetenek çalıştıktan sonra hesaplanır; yoksa
        # yeteneğin başlattığı donma bir kare geç işlerdi.
        frozen = self.time_stop > 0

        # Ekran koordinatı taşınıyor ve dünyaya burada, kamera güncellendikten
        # sonra çevriliyor: nişan fareyle aynı karede.
        if "aim_sx" in input_state:
            ax_w, ay_w = self.screen_to_world(input_state["aim_sx"],
                                              input_state["aim_sy"])
        else:
            ax_w = input_state.get("aim_x", p.x)
            ay_w = input_state.get("aim_y", p.y - 1)
        aim_dx, aim_dy = norm_dir(p.x, p.y, ax_w, ay_w)
        p.set_aim(aim_dx, aim_dy)

        if input_state.get("mouse_down") and p.try_attack():
            self.do_player_attack(*p.aim_dir)
        if input_state.get("bonk_pressed") and p.try_bonk():
            self.do_bonk()
        if input_state.get("dash_pressed"):
            if p.try_dash(self.fx) and p.dash_slow_level > 0:
                # zaman kitabı: dash çevredeki düşmanları kısa süre yavaşlatır.
                # güçlendi: 180 px / 2,0 sn / %25 -> 230 px / 2,8 sn / %45
                rad = 200 + 30 * p.dash_slow_level
                dur = 2.0 + 0.8 * p.dash_slow_level
                mult = max(0.30, 0.70 - 0.15 * p.dash_slow_level)
                for e in self.enemies:
                    if e.alive and dist(e.x, e.y, p.x, p.y) < rad and hasattr(e, "apply_slow"):
                        e.apply_slow(mult, dur)
                for b in self.bosses:
                    if b.alive and dist(b.x, b.y, p.x, p.y) < rad and hasattr(b, "apply_slow"):
                        b.apply_slow(mult, dur)
                self.fx.shockwave(p.x, p.y, rad, (150, 210, 255), 0.30, 3)

        if p.orbit_level > 0:
            DMG_SRC[0] = "orbit"
            p.orbit_angle += dt * 3.2
            n = p.orbit_level
            orad = 58
            for i in range(n):
                ang = p.orbit_angle + i * math.tau / n
                ox = p.x + math.cos(ang) * orad
                oy = p.y + math.sin(ang) * orad
                for e in self._all_targets():
                    if not e.alive:
                        continue
                    if dist(ox, oy, e.x, e.y) < e.radius + 10:
                        dmg = p.eff_dmg() * 0.45 * dt * 6
                        died = e.take_damage(dmg, False, self.fx)
                        if died:
                            self.on_enemy_killed(e)

        if p.storm_level > 0:
            p.storm_timer -= dt
            if p.storm_timer <= 0:
                p.storm_timer = max(1.0, 2.6 - p.storm_level * 0.4)
                self.do_storm_strike()

        # ---- patron mantığı ----
        self._tick_boss_wound((p,))
        if self.waves.boss_pending:
            self.waves.boss_pending = False
            self.waves.boss_active = True
            self.waves.boss_clock = 0.0
            wave = self.waves.wave
            # 2-3 patron yerine tek şampiyon (gücü eski sayı kadar)
            champ = boss_count_for_wave(wave)
            n_boss = 1
            hp_mult = boss_hp_share(n_boss)
            self.enemies.clear()
            # önceki dalganın patronu hâlâ ayaktaysa sahada kalır
            self.bosses = [b for b in self.bosses if b.alive]
            new_from = len(self.bosses)
            hell = self.biome == "hell"
            order = HELL_BOSS_ORDER if hell else BOSS_ORDER
            for i in range(n_boss):
                kind = order[self.waves.boss_idx % len(order)]
                self.waves.boss_idx += 1
                # Birden fazla patron varsa arenanın üst kısmına yatayda
                # yayılırlar.
                cam = self.cam_rect()
                if n_boss == 1:
                    bx = cam.centerx
                else:
                    span = min(cam.width - 220, 220 * (n_boss - 1))
                    bx = cam.centerx - span / 2 + span * i / max(1, n_boss - 1)
                by = cam.top + 110
                bx = clamp(bx, ARENA_RECT.left + 90, ARENA_RECT.right - 90)
                by = clamp(by, ARENA_RECT.top + 90, ARENA_RECT.bottom - 90)
                nb_ = Boss(kind, bx, by, hp_mult, 1.0, wave, hellish=hell,
                           theme=None if hell else self.map_theme, champion=champ)
                nb_.boss_wave = wave
                self.bosses.append(nb_)
            # Patron canı oyuncunun gücüne göre ölçeklenir: dövüş, oyuncu ne
            # kadar güçlenirse güçlensin benzer uzunlukta sürsün.
            scale_bosses_to_player(self.bosses[new_from:], p)
            self.fx.do_flash((255, 60, 50), 0.4)
            if champ > 1:
                self.fx.popup(self.cam_rect().centerx, self.cam_rect().top + 60,
                              L("ui.champ_boss"), (255, 90, 70), 34, life=1.8)
            sfx("boss", 1.0, 0.0)

        if self.bosses:
            DMG_SRC[0] = "other"
            for b in list(self.bosses):
                if b.alive:
                    if not frozen:
                        b.update(dt, p, self.fx, self.enemy_projectiles, self.hazards, self.on_enemy_killed)
                    if b.summoned_enemies:
                        self.enemies.extend(b.summoned_enemies)
                        b.summoned_enemies = []
                else:
                    self.on_enemy_killed(b)
                    self._beaten_boss_wave = max(getattr(self, "_beaten_boss_wave", 0),
                                                 int(getattr(b, "boss_wave", self.waves.wave)))
                    # Devrilen her patron yerine bir sandık bırakır (şampiyon,
                    # yerine geçtiği patron sayısı kadar).
                    nb = max(1, int(getattr(b, "champion", 1)))
                    for i in range(nb):
                        self.spawn_boss_chest(b, dx=(i - (nb - 1) / 2.0) * 90)
                    self.bosses.remove(b)
            if not self.bosses:
                # Tüm patronlar devrildi. dalga süreyle ilerlediği için patron
                # ölümü dalgayı atlatmaz; yalnızca patron temposu biter.
                beaten_wave = int(getattr(self, "_beaten_boss_wave", 0) or self.waves.wave)
                self._beaten_boss_wave = 0
                if self.waves.boss_active:
                    self.waves.boss_active = False
                    self.waves.announce_timer = 2.5
                    self.waves.announce_text = L("ui.boss_down")
                sfx("wave", 0.6, 0.0)
                if self.ach and self.biome != "hell":
                    self.ach.unlock({5: "wave5", 10: "wave10", 15: "wave15",
                                     20: "wave20"}.get(beaten_wave, ""))
                if self.ach and self.biome == "hell":
                    self.ach.unlock("hell_boss")
                # 1. haritanın finali: 25. dalga patronu devrildiğinde
                if (self.biome == "hell" and HELL_FINAL_WAVE is not None
                        and beaten_wave >= HELL_FINAL_WAVE and not self.doom_warned):
                    # cehennemin son patronu devrildi - ölüm duvarı
                    self.doom_warned = True
                    self.waves.announce_timer = 3.6
                    self.waves.announce_text = L("hell.end")
                    self.fx.do_flash((200, 40, 40), 0.45)
                if (self.biome != "hell" and beaten_wave >= HELL_PORTAL_WAVE
                        and self.hell_portal is None):
                    if self.map_theme == "stone":
                        self.open_hell_portal()
                    elif not self.doom_warned:
                        # bu haritada cehennem yok - ölüm duvarı başlar
                        self.doom_warned = True
                        self.waves.announce_timer = 3.4
                        self.waves.announce_text = L("map.doom")
                        self.fx.do_flash((200, 40, 40), 0.4)

        self._wave_milestones()

        if not frozen:
            for hz in list(self.hazards):
                hz.update(dt, self)
        self.hazards = [h for h in self.hazards if h.alive]

        if not frozen:
            DMG_SRC[0] = "other"
            for e in list(self.enemies):
                e.update(dt, p, self.fx, self.enemy_projectiles,
                         self.on_enemy_killed, self.enemies)
        self.enemies = [e for e in self.enemies if e.alive]
        if not frozen:
            # Kaçan oyuncunun arkasında kalan yaratıklar önüne ışınlanır.
            self.reposition_stragglers(dt)
            self._update_camping(dt)
        # Patron sandıkları ve sandıktan çıkan otomatik silahlar
        self.update_chests(dt)
        self.update_keys(dt)
        # oyuncunun silahları zaman durunca da çalışır. Donan yalnızca
        # yaratıklar, mermileri ve tuzakları olmalı.
        self.update_boss_weapons(dt)
        # sürekli silahlar (kalkan / pentagram / papuç / pelerin)
        self.update_passive_weapons(dt)
        # Su birikintileri, ateş halkaları, hortumlar, uçan baltalar, kırbaçlar
        self.update_weapon_objects(dt)
        self.update_magnets(dt)

        self._update_enemy_projectiles(dt, frozen)
        self._update_player_projectiles(dt)
        self._update_pickups(dt)

        # ---- yeni rekor ----
        if self.record_flash >= 0:
            self.record_flash += dt
            if self.record_flash > 2.6:
                self.record_flash = -1.0
        if (not self.record_beaten and self.best_at_start > 0
                and self.score > self.best_at_start):
            self.record_beaten = True
            self.record_flash = 0.0
            self.fx.do_flash(GOLD, 0.30)
            self.fx.ring(p.x, p.y, GOLD, n=30, speed=320, life=0.8, r=4)
            sfx("levelup", 1.0, 0.0)

        wave_changed = self.waves.update(0.0 if frozen else dt, self.enemies, self.wave_hp_mult,
                                         self.waves.boss_active, total_score=self.score)
        if wave_changed:
            sfx("wave", 0.6, 0.0)
            if self.waves.wave % 5 == 0 and self.ach:
                self.ach.unlock({5: "wave5", 10: "wave10", 15: "wave15", 20: "wave20"}.get(self.waves.wave, ""))
            if self.diff == "nightmare" and self.total_wave() >= 10 and self.ach:
                self.ach.unlock("nightmare")
        if (wave_changed and not self.waves.boss_pending and not self.waves.boss_active
                and mini_boss_wave(self.waves.wave)):
            self.spawn_mini_boss()
        if wave_changed:
            self._roll_goblin()
            self.extras_wave_changed()
        self._update_goblins()

        if self.coins_earned >= 1500 and self.ach:
            self.ach.unlock("rich")
        if p.dash_count >= 40 and self.ach:
            self.ach.unlock("dasher")

        # ---- cehennem kapısı: ölene ya da girene kadar yerinde durur ----
        portal_used = False
        if self.hell_portal is not None:
            self.hell_portal.update(dt)
            if (p.alive and input_state.get("use_pressed")
                    and self.hell_portal.in_range(p)):
                self.enter_hell()
                portal_used = True

        # ---- lanetli sandık ----
        self.update_cursed(dt, input_state, portal_used)
        # ---- gezgin tüccar (koşu boyunca haritada) ----
        self.update_merchant(dt, input_state, portal_used)

        self.combo.update(dt)
        self.fx.update(dt)
        if self.ach:
            self.ach.update(dt)

        if not p.alive and not self.game_over:
            self.death_cause = p.last_hit_by
            self.finish_run()

    # ana döngünün bu üç parçası ayrı metot (2 kişilikte oyuncu başına
    # çağrılır)
    def _update_enemy_projectiles(self, dt, frozen):
        p = self.player
        for proj in list(self.enemy_projectiles):
            if not frozen:
                proj.update(dt)
            if proj.alive and p.alive and not frozen:
                # kalkan: mermi önce kalkanlara çarpar. Kalkan mermiyi yutarsa
                # hasar sayılmaz - oyuncuya hiç ulaşmaz.
                if self.block_with_book(proj):
                    continue
                if dist(proj.x, proj.y, p.x, p.y) < proj.r + p.radius:
                    owner = getattr(proj, "owner", None)
                    if owner is not None and hasattr(owner, "hit_player"):
                        # Patron mermisi: hasarın yanında imza etkisini de
                        # taşır.
                        owner.hit_player(p, proj.dmg, self.fx, proj.x, proj.y)
                    else:
                        p.take_damage(proj.dmg, self.fx, proj.x, proj.y, "mermi")
                        # büyücü'nün zehir oku: hasarın yanında zehir bırakır.
                        if getattr(proj, "poison", 0.0) > 0:
                            p.apply_poison(proj.poison, WIZARD_POISON_TIME,
                                           LX("en.wizard", "Büyücü"))
                    proj.alive = False
        self.enemy_projectiles = [pr for pr in self.enemy_projectiles if pr.alive]

    def _update_player_projectiles(self, dt):
        p = self.player
        for proj in list(self.player_projectiles):
            if proj.homing > 0 and proj.alive:
                nearest, nd = None, 1e9
                for e in self.enemies:
                    if not e.alive:
                        continue
                    dd = dist(proj.x, proj.y, e.x, e.y)
                    if dd < nd:
                        nd = dd
                        nearest = e
                if nearest is not None:
                    proj.steer_toward(nearest.x, nearest.y, dt)
            proj.update(dt)
            proj.emit(self.fx, dt)
            DMG_SRC[0] = getattr(proj, "_wsrc", None) or "gun"
            if proj.alive:
                for e in self._all_targets():
                    if not e.alive or id(e) in proj.hit_set:
                        continue
                    e_hit_r = getattr(e, "hit_r", e.radius)
                    # Merminin ucu hedefin görünen alanına biraz bile değse
                    # isabet sayılsın; kıl payı ıskalar/es geçmeler olmasın
                    # diye küçük bir tolerans payı var.
                    forgive = max(3.0, proj.r * 0.35)
                    if getattr(e, "phased", False):
                        continue            # hayalet dokunulmazken mermi içinden geçer
                    if dist(proj.x, proj.y, e.x, e.y) < proj.r + e_hit_r + forgive:
                        proj.hit_set.add(id(e))
                        crit = random.random() < proj.crit_chance
                        if crit:
                            p.run_crits += 1
                        dmg = proj.dmg * (proj.crit_mult if crit else 1.0)
                        # patron avcısı kitabı: patron ve elitlere ek hasar
                        if p.boss_hunter > 0 and (getattr(e, "is_boss", False) or e.kind == "elite"):
                            dmg *= (1.0 + p.boss_hunter_bonus())
                        dmg = self._apply_execute(p, e, dmg)
                        kx, ky = norm_dir(p.x, p.y, e.x, e.y)
                        kb = 12 if getattr(e, "is_boss", False) else 90
                        died = e.take_damage(dmg, crit, self.fx, kx * kb, ky * kb)
                        if p.fire_level > 0 and hasattr(e, "apply_burn"):
                            e.apply_burn(4 * p.fire_level, 2.2 + p.fire_level * 0.5)
                        # kutsal alev (cehennem eşyası): çok daha ağır bir
                        # yanık
                        if p.holy_flame > 0 and hasattr(e, "apply_burn"):
                            e.apply_burn(18 * p.holy_flame, 3.0 + p.holy_flame * 0.6)
                        if p.ice_level > 0 and hasattr(e, "apply_slow"):
                            e.apply_slow(max(0.3, 1 - 0.18 * p.ice_level), 1.4 + p.ice_level * 0.3)
                        # zehir kitabı: bulaştığı düşman ölene kadar sürer ve
                        # her isabette üstüne biner. Seviye başına saniyede 3
                        # hasar.
                        if p.poison_level > 0 and hasattr(e, "apply_poison"):
                            e.apply_poison(3.0 * p.poison_level)
                        if p.vamp_level > 0:
                            p.lifesteal(dmg * 0.02 * p.vamp_level)
                        self.fx.burst((proj.x + e.x) / 2, (proj.y + e.y) / 2,
                                      (255, 230, 150) if crit else proj.color, n=4, speed=90, life=0.25, r=2.2)
                        if died:
                            self.on_enemy_killed(e)
                            self._explosion_splash(e.x, e.y, proj.dmg, exclude_id=id(e))
                        proj.hits_left -= 1
                        if proj.hits_left <= 0:
                            proj.alive = False
                            break
        self.player_projectiles = [pr for pr in self.player_projectiles if pr.alive]
        DMG_SRC[0] = "other"

    def _update_pickups(self, dt):
        p = self.player
        for pu in list(self.pickups):
            pu.update(dt, p)
            if pu.collected:
                if pu.kind == "xp":
                    lv = p.gain_xp(pu.value)
                    if lv > 0:
                        self.pending_levelups += lv
                        self.fx.popup(p.x, p.y - 40, "SEVİYE ATLADI!", GOLD, 20, life=1.0)
                        self.fx.ring(p.x, p.y, GOLD, n=18, speed=200, life=0.5, r=3)
                        sfx("levelup", 1.0, 0.0)
                        if p.level >= 10 and self.ach:
                            self.ach.unlock("lvl10")
                elif pu.kind == "heart":
                    p.heal(pu.value)
                    self.fx.popup(pu.x, pu.y - 10, f"+{pu.value}", (255, 120, 140), 15, life=0.5)
                    sfx("heart", 0.7, 0.05)
                else:
                    # Altın yalnızca burada, yani parayı gerçekten toplayınca
                    # kazanılır.
                    self.coins_earned += pu.value
                    # elmas, dalga kısıntısından etkilenmez
                    self.gem_coins += pu.value / (coin_drop_scale(self.biome)
                                                  * econ_wave_factor(self.waves.wave, self.biome, "gold", self.diff))
                    self.gold_wallet += pu.value
                    self.fx.popup(pu.x, pu.y - 10, f"+{pu.value}", GOLD, 14, life=0.5)
                    sfx("coin", 0.4, 0.02)
        self.pickups = [pu for pu in self.pickups if not (pu.collected or pu.dead)]

    def _wave_milestones(self):
        """Dalgaya bağlı kalıcı tehditler - zırh delme payını yazar ve her yeni tehdidi bir kez duyurur (zırh delme, kamikaze, kudurma)."""
        p = self.player
        w = int(self.waves.wave)
        p.armor_pierce = enemy_armor_pierce(w, self.biome)
        seen = self.__dict__.setdefault("milestones", set())
        msg = None
        if self.biome != "hell":
            if w > PIERCE_FROM and "pierce" not in seen:
                seen.add("pierce")
                msg = ("th.pierce", (255, 170, 120))
            elif w >= KAMIKAZE_WAVE and "kamikaze" not in seen:
                seen.add("kamikaze")
                msg = ("th.kamikaze", ENEMY_COLORS["kamikaze"])
            elif w > RAGE_FROM and "rage" not in seen:
                seen.add("rage")
                msg = ("th.rage", RAGE_FIRE)
            elif w >= MUTANT_FROM and "mutant" not in seen:
                seen.add("mutant")
                msg = ("th.mutant", (200, 255, 190))
        elif "hell_pierce" not in seen:
            seen.add("hell_pierce")
            msg = ("th.hell_pierce", (255, 120, 90))
        elif w + HELL_WAVE_OFFSET >= MUTANT_FROM and "mutant" not in seen:
            seen.add("mutant")
            msg = ("th.mutant", (200, 255, 190))
        if msg and p.alive:
            self.fx.popup(p.x, p.y - 118, L(msg[0]), msg[1], 22, life=3.0)
            sfx("warn", 0.5, 0.0)

    # ---- lanetli sandık ----
    def _cursed_due(self):
        """Sıradaki mağaranın vakti geldi mi?"""
        n = int(getattr(self, "cursed_spawns", 0))
        if n >= CURSED_MAX or self.biome == "hell" or int(self.cursed_next_wave) >= 999:
            return False
        if n == 0:
            return True
        # Önceki mağara hâlâ duruyorsa: oyuncu onu bulduysa ya da yeni
        # yerleştiyse (iki olay üst üste gelince) bekler - mağara boşa
        # gitmesin.
        old = self.cursed_shrine
        if old is not None and old.alive and not old.used:
            if old.discovered or self.run_time - getattr(self, "cursed_spawn_t", -999.0) < CURSED_MIN_LIFE:
                return False
        if n == 1:
            return int(getattr(self, "bosses_killed", 0)) >= 1
        # 25. dalga patronu devrilince: Taş Meydan'da kapı açılır, öbür
        # haritalarda ölüm duvarı başlar (doom_warned) - ikisi de aynı an.
        return self.hell_portal is not None or bool(getattr(self, "doom_warned", False))

    def spawn_cursed_shrine(self):
        """Mağara ağzını oyuncudan uzakta, haritanın rastgele bir yerine koyar."""
        p = self.player
        cam = self.cam_rect().inflate(160, 160)
        x = y = 0.0
        for _ in range(80):
            x = random.uniform(ARENA_RECT.left + 220, ARENA_RECT.right - 220)
            y = random.uniform(ARENA_RECT.top + 220, ARENA_RECT.bottom - 220)
            d = dist(x, y, p.x, p.y)
            far_portal = (self.hell_portal is None
                          or dist(x, y, self.hell_portal.x, self.hell_portal.y) > 320)
            # ekranda görünmeyen, keşfe değer bir uzaklıkta
            if 700 < d < 1500 and far_portal and not cam.collidepoint(x, y):
                break
        # duyuru yok: oyuncu kendisi bulur.
        self.cursed_shrine = CursedShrine(x, y)
        # koşudaki mağara sayısı (takvim: _cursed_due)
        self.cursed_spawns = int(getattr(self, "cursed_spawns", 0)) + 1
        self.cursed_spawn_t = self.run_time

    def update_cursed(self, dt, input_state, portal_used=False):
        p = self.player
        # yerleşme: sayaç dolunca, harita boşsa (duyurusuz)
        w = int(self.waves.wave)
        if self._cursed_due():
            # kullanılmadan kalan eski mağara çöker; yenisi yerleşir
            self.cursed_seen_wave = w
            self.spawn_cursed_shrine()
        sh = self.cursed_shrine
        if sh is not None:
            sh.update(dt)
            if not sh.discovered and self.cam_rect().inflate(-80, -60).collidepoint(sh.x, sh.y):
                # bulundu: haritada ve kenar okunda görünür
                sh.discovered = True
                self.fx.popup(p.x, p.y - 92, L("cu.found"), CURSE_COLOR2, 24, life=2.4)
                self.fx.popup(p.x, p.y - 66, L("cu.found_sub", key_label("map")),
                              (210, 190, 230), 14, life=2.4)
                sfx("magnet", 0.5, 0.0)
            if not sh.alive:
                self.cursed_shrine = None
            elif (not portal_used and p.alive and not sh.used and self.curse_offers is None
                  and input_state.get("use_pressed") and sh.in_range(p)):
                self.open_cursed()
        # cesetler bir süre sonra çürür
        if self.corpses:
            now = self.run_time
            self.corpses = [c for c in self.corpses if now - c[2] < CORPSE_LIFE]
        # ölü çağırıcı: sayacı dolunca yakındaki cesetleri kaldırır
        for e in self.enemies:
            if e.alive and e.kind == "necro" and e.spawn_t > 1.0:
                e.necro_cd -= dt
                if e.necro_cd <= 0:
                    e.necro_cd = NECRO_CD
                    self._necro_raise(e)

    def _make_enemy(self, kind, x, y, themed=True):
        """Şu anki dalga ve haritaya göre tek bir yaratık üretir. themed"""
        w = int(self.waves.wave)
        x = clamp(x, ARENA_RECT.left + 30, ARENA_RECT.right - 30)
        y = clamp(y, ARENA_RECT.top + 30, ARENA_RECT.bottom - 30)
        if kind in HELL_ENEMIES:
            e = Enemy(None, x, y, self.wave_hp_mult(w), 1.0, wave=w, variant=kind, biome="hell")
        elif themed and self.biome != "hell" and map_variant(self.waves.theme, kind):
            e = make_map_enemy(self.waves.theme, kind, x, y, self.wave_hp_mult(w), 1.0, wave=w)
        else:
            e = Enemy(kind, x, y, self.wave_hp_mult(w), 1.0, wave=w, biome=self.biome)
        fz = int(self.curses.get("frenzy", 0))
        if fz:
            e.speed *= 1.0 + CURSE_FRENZY_SPD * fz
        # mutasyon: 30. dalgadan sonra doğan her 3 yaratıktan 1'i
        w_tot = w + (HELL_WAVE_OFFSET if self.biome == "hell" else 0)
        if (w_tot >= MUTANT_FROM
                and kind not in ("goblin", "herald", "shieldman")):
            self.mutant_counter = getattr(self, "mutant_counter", 0) + 1
            if self.mutant_counter % MUTANT_EVERY == 0:
                e.mutate()
        return e

    # ---- dalga olayları + hazine goblini ----
    def _roll_goblin(self):
        """Dalga değişti: arada bir hazine goblini çıkar (patron dalgası değilse)."""
        w = int(self.waves.wave)
        if (w < GOBLIN_MIN_WAVE or self.waves.boss_pending or self.waves.boss_active
                or self.waves.is_boss_wave(w)):
            return
        if random.random() < GOBLIN_CHANCE:
            self.spawn_goblin()

    def spawn_goblin(self):
        x, y = self.near_camera_point()
        g = self._make_enemy("goblin", x, y)
        g.speed = min(g.speed, BASE_SPEED * 0.80)   # yakalanabilir kalsın
        self.enemies.append(g)
        p = self.player
        self.fx.popup(p.x, p.y - 104, L("fx.goblin"), GOBLIN_COLOR, 20, life=1.8)

    def _update_goblins(self):
        for e in self.enemies:
            if e.alive and e.kind == "goblin" and e.spawn_t > GOBLIN_LIFE:
                # kaçtı: sayılmaz, ganimet yok
                e.alive = False
                e.death_counted = True
                self.fx.burst(e.x, e.y, (200, 200, 200), n=12, speed=150, life=0.5, r=3.5)
                self.fx.popup(e.x, e.y - 30, L("fx.goblin_escaped"), (200, 200, 210), 16, life=1.2)

    def _goblin_loot(self, e):
        """Hazine goblini devrildi: altın saçar + şansa göre ganimet."""
        p = self.player
        w = max(1, int(self.waves.wave))
        # Taban %45 kısıldı; yine de "hazine" gibi hissettirecek kadar fazla
        # kalıyor.
        GOBLIN_GOLD_TRIM = 0.55
        gold = int(scaled_coin_gain((250 + 45 * w) * GOBLIN_GOLD_TRIM, p.eff_coin_mult(), self.biome))
        n = 10
        for i in range(n):
            a = i * math.tau / n
            self.drop_pickup(e.x + math.cos(a) * 26, e.y + math.sin(a) * 26, "coin", gold / n)
        tier = roll_rarity(p.eff_luck() * 1.2 + 0.2)
        if tier == 1:
            self.reroll_bonus += 1
        elif tier == 2:
            self.magnets.append(MagnetDrop(e.x, e.y))
        elif tier == 3:
            self.level_drops.append(LevelDrop(e.x, e.y))
        elif tier >= 4:
            self.chests.append(BossChest(e.x, e.y, "goblin"))
        self.goblins_caught += 1
        col = rarity_color(tier)
        self.fx.popup(e.x, e.y - 60, L("fx.goblin_loot", rarity_name(tier)), col, 22 + 2 * tier, life=2.0)
        self.fx.popup(e.x, e.y - 36, L("fx.goblin_r%d" % tier), lighten(col, 0.2), 14, life=2.0)
        self.fx.ring(e.x, e.y, GOLD, n=24, speed=240, life=0.5, r=3.5)
        self.fx.do_flash(col, 0.2 + 0.05 * tier)
        sfx("coin", 1.0, 0.0)

    def bat_heal(self, x, y):
        """Yarasa sürüsü isabeti: kovadan biraz can."""
        p = self.player
        amt = min(self.bat_heal_budget, p.max_hp * BAT_HEAL_FRAC)
        if amt > 0.05:
            self.bat_heal_budget -= amt
            p.heal(amt)
            if random.random() < 0.25:
                self.fx.spark(x, y, (255, 120, 150), 0, -40, 0.35, 2.2)

    def _necro_raise(self, nec):
        near = [c for c in self.corpses
                if dist(c[0], c[1], nec.x, nec.y) < NECRO_RADIUS][:NECRO_MAX_RAISE]
        if not near:
            return
        col = ENEMY_COLORS["necro"]
        for c in near:
            self.corpses.remove(c)
            sk = self._make_enemy("red", c[0], c[1], themed=False)
            sk.raised = True
            sk.color = RAISED_COLOR
            sk.red_intensity = 0.0
            sk.max_hp *= 0.55
            sk.hp = sk.max_hp
            sk.coin = 0
            sk.xp = 0
            sk.score = max(1, int(sk.score * 0.5))
            sk.disp_name = L("en.raised")
            self.enemies.append(sk)
            self.fx.bolt(zigzag(nec.x, nec.y - 18, c[0], c[1], 5, 10), col, 0.30)
            self.fx.burst(c[0], c[1], RAISED_COLOR, n=8, speed=120, life=0.4, r=3)
        self.fx.popup(nec.x, nec.y - 36, L("fx.raise"), lighten(col, 0.3), 14, life=0.8)
        sfx("vortex", 0.25, 0.08)

    def _on_cursed_death(self, e):
        """Bölünen ikiye ayrılır; sıradan ölüler ölü çağırıcı için ceset bırakır."""
        if getattr(e, "is_boss", False):
            return
        kind = getattr(e, "kind", "")
        if kind == "splitter" and getattr(e, "split_gen", 2) < 2:
            for s_ in (-1, 1):
                ch = self._make_enemy("splitter", e.x + s_ * e.radius * 0.7, e.y)
                ch.split_gen = e.split_gen + 1
                ch.max_hp = e.max_hp * 0.45
                ch.hp = ch.max_hp
                ch.radius = e.radius * 0.76
                ch.hit_r = e.hit_r * 0.76
                ch.speed = e.speed * 1.15
                ch.coin = max(1, int(e.coin * 0.5))
                ch.xp = e.xp * 0.5
                ch.score = max(1, int(e.score * 0.5))
                ch.knock_x = s_ * 200.0
                ch.spawn_t = 0.3
                self.enemies.append(ch)
            self.fx.burst(e.x, e.y, ENEMY_COLORS["splitter"], n=10, speed=170, life=0.4, r=3.2)
            return
        if (self.curses.get("necro") and not getattr(e, "raised", False)
                and kind not in ("necro",) and len(self.corpses) < 40):
            self.corpses.append((e.x, e.y, self.run_time))

    def open_cursed(self):
        sh = self.cursed_shrine
        if sh is None:
            return
        sh.opened = True
        self.curse_offers = self._build_curse_offers()
        self.fx.do_flash(CURSE_COLOR, 0.35)
        sfx("magnet", 0.6, 0.0)

    def _build_curse_offers(self):
        p = self.player
        luck = p.eff_luck()
        rewards = [r for r in CURSE_REWARDS if r != "arsenal" or p.weapons]
        random.shuffle(rewards)
        curses = list(CURSE_KINDS)
        random.shuffle(curses)
        # Üç tekliften biri bazen genel bir lanet taşır (kudurma / kalabalık).
        if random.random() < 0.45:
            curses[2] = random.choice(("frenzy", "swarm"))
        offers = []
        # mağarada şans daha çok işler (CAVE_LUCK_*). Epik teklif +1, Efsanevi
        # teklif +2 seviye ve bütün silahlara +1 seviye ekler.
        cave_luck = luck * CAVE_LUCK_MULT + CAVE_LUCK_BASE
        for i in range(3):
            tier = roll_rarity(cave_luck)
            rk = rewards[i % len(rewards)]
            vals = cursed_reward_values(rk, tier, self.waves.wave)
            if tier >= 3:
                vals["levels"] = int(vals.get("levels", 0)) + (2 if tier >= 4 else 1)
            if tier >= 4 and p.weapons:
                vals["wlevels"] = int(vals.get("wlevels", 0)) + 1
            offers.append(dict(kind="pair", reward=rk, tier=tier, vals=vals,
                               lines=cursed_reward_lines(rk, vals), curse=curses[i]))
        # Üçüncü teklif bazen eksantrik olur: zar ya da kan bedeli.
        r = random.random()
        if r < 0.35:
            offers[2]["kind"] = "gamble"
            offers[2]["win"] = min(GAMBLE_WIN_MAX, GAMBLE_WIN + GAMBLE_WIN_LUCK * luck)
        elif r < 0.60:
            offers[2]["kind"] = "blood"
            offers[2]["curse"] = None
        return offers

    def decline_curse(self):
        """Vazgeç: teklifler kapanır ve mağara çöker."""
        sh = self.cursed_shrine
        if sh is not None:
            sh.opened = False
            sh.used = True                      # çöküş animasyonu + sonraki sayaç
            p = self.player
            self.fx.popup(sh.x, sh.y - 70, L("cu.collapsed"), (200, 180, 220), 20, life=1.8)
            self.fx.burst(sh.x, sh.y, (120, 100, 140), n=26, speed=180, life=0.7, r=4.0)
            self.fx.shake(6, 0.3)
            sfx("bonk", 0.5, 0.0)
        self.curse_offers = None

    def accept_curse(self, idx):
        offers = self.curse_offers or []
        if not (0 <= idx < len(offers)):
            return
        o = offers[idx]
        p = self.player
        sh = self.cursed_shrine
        sx, sy = (sh.x, sh.y + 30) if sh is not None else (p.x, p.y)
        mult = 1
        if o["kind"] == "gamble":
            won = random.random() < float(o.get("win", GAMBLE_WIN))
            mult = 2 if won else 0
            self.fx.popup(p.x, p.y - 96, L("cu.won") if won else L("cu.lost"),
                          GREEN if won else CURSE_RED, 30, life=2.0)
        if mult:
            self._apply_curse_reward(o["vals"], mult)
        if o["kind"] == "blood":
            loss = int(p.max_hp * BLOOD_PRICE)
            p.max_hp = max(30, int(p.max_hp) - loss)
            p.hp = min(p.hp, p.max_hp)
            self.fx.popup(p.x, p.y - 70, f"-{loss} " + L("cu.maxhp"), CURSE_RED, 20, life=1.6)
            self.fx.do_flash(CURSE_RED, 0.4)
        else:
            c = o.get("curse")
            if c:
                self.curses[c] = int(self.curses.get(c, 0)) + 1
                self.curse_score_bonus = min(CURSE_SCORE_MAX,
                                             self.curse_score_bonus + CURSE_SCORE_PER)
                self._curse_trap(c, sx, sy)
        self.cursed_taken += 1
        if sh is not None:
            sh.used = True
        self.curse_offers = None
        sfx("levelup", 0.9, 0.0)

    def _apply_curse_reward(self, vals, mult=1):
        p = self.player
        n = int(vals.get("levels", 0)) * mult
        if n > 0:
            for _ in range(n):
                p.level += 1
                p.xp_to_next = xp_next_need(p.xp_to_next, p.level)
            p.on_level_up(n)
            self.pending_levelups += n
        wl = int(vals.get("wlevels", 0)) * mult
        if wl > 0:
            for k in list(p.weapons):
                w = WEAPON_BY_KEY.get(k)
                if w is not None:
                    p.weapons[k] = min(weapon_max_level(w), p.weapons[k] + wl)
                    p.add_weapon_boost(k, float(vals.get("boost", 0.0)) * mult)
        hp = int(vals.get("hp", 0)) * mult
        if hp:
            p.max_hp += hp
            p.hp = min(p.max_hp, p.hp + hp)
        p.run_dmg_mult += float(vals.get("dmg", 0.0)) * mult
        p.run_luck_bonus += float(vals.get("luck", 0.0)) * mult
        self.gold_wallet += int(vals.get("gold", 0)) * mult
        p.run_coin_mult += float(vals.get("coin", 0.0)) * mult
        p.run_armor_bonus += float(vals.get("armor", 0.0)) * mult
        p.shield_charges += int(vals.get("shields", 0)) * mult
        p.run_crit_bonus += float(vals.get("crit", 0.0)) * mult
        p.run_critdmg_bonus += float(vals.get("critd", 0.0)) * mult
        p.run_aspd_mult += float(vals.get("aspd", 0.0)) * mult
        self.fx.ring(p.x, p.y, GREEN, n=24, speed=260, life=0.5, r=3.5)

    def _curse_trap(self, curse, sx, sy):
        """tuzak: lanet kabul edilince mağaranın önünde bir dalga patlar."""
        n = min(20, CURSE_TRAP_BASE + int(self.waves.wave) // 2)
        for i in range(n):
            a = i / float(n) * math.tau + random.uniform(-0.2, 0.2)
            rr = random.uniform(110, 250)
            kind = curse if curse in CURSE_KINDS else self.waves.pick_base_kind()
            self.enemies.append(self._make_enemy(kind, sx + math.cos(a) * rr,
                                                 sy + math.sin(a) * rr))
        self.fx.do_flash(CURSE_COLOR, 0.55)
        self.fx.shake(12, 0.45)
        for k in range(3):
            self.fx.shockwave(sx, sy, 160 + 150 * k, CURSE_COLOR if k % 2 == 0 else CURSE_RED,
                              0.5 + 0.12 * k, 6 - k)
        self.fx.burst(sx, sy, CURSE_COLOR2, n=36, speed=320, life=0.7, r=4)
        self.fx.popup(sx, sy - 120, L("cu.trap"), CURSE_RED, 38, life=1.8)
        sfx("explosion", 0.8, 0.0)

    # ---- seviye atlama ----
    # Seviye atlayınca yalnızca kitap değil, silah da çıkar. Oyuncu kendi 4
    # silahını buradan kurar; sandıklar ise yalnızca o 4 silahın seviyesini
    # yükseltir.
    REROLL_FREE = 3
    SKIP_FREE = 3
    # 120 x1,55 -> 40 x1,30.
    REROLL_BASE = 40            # bedavalar bitince ilk yenilemenin bedeli
    REROLL_GROWTH = 1.30        # her kullanımda bedelin çarpanı
    SKIP_BASE = 90
    SKIP_GROWTH = 1.55

    @staticmethod
    def _step_cost(used, free, base, growth):
        if used < free:
            return 0
        return int(round(base * (growth ** (used - free)) / 10.0) * 10)

    def reroll_cost(self):
        if getattr(self, "reroll_bonus", 0) > 0:
            return 0                # kitap kartından kazanılmış bedava hak
        return self._step_cost(self.reroll_used, self.REROLL_FREE,
                               self.REROLL_BASE, self.REROLL_GROWTH)

    def skip_cost(self):
        return self._step_cost(self.skip_used, self.SKIP_FREE,
                               self.SKIP_BASE, self.SKIP_GROWTH)

    def rerolls_left_free(self):
        return max(0, self.REROLL_FREE - self.reroll_used) + int(getattr(self, "reroll_bonus", 0))

    def skips_left_free(self):
        return max(0, self.SKIP_FREE - self.skip_used)

    def _weapon_offer(self, w, lvl, is_new):
        """Seviye atlama kartı için silah teklifi."""
        off = {
            "kind": "weapon", "key": w["key"], "w": w, "lvl": lvl, "new": is_new,
            "name": w_name(w), "color": tuple(w["color"]), "icon": w["icon"],
            "desc": w_desc(w) if is_new else (w_up(w) or L("ui.weapon_up_short")),
        }
        # yeni silah kartı da kademe çeker - her kart kendi zarını atar.
        tier = roll_rarity(self.player.eff_luck())
        off["rarity"] = tier
        off["boost"] = rarity_boost(tier, "card")
        return off

    def _book_offer(self, bk, lvl, is_new):
        """Seviye atlama kartı için kitap teklifi."""
        rare = bool(bk.get("rare"))
        off = {
            "kind": "book", "key": bk["key"], "book": bk, "lvl": lvl, "new": is_new,
            "name": bk_name(bk), "color": tuple(bk["color"]), "icon": bk.get("icon", "star"),
            "desc": bk_desc(bk), "rare": rare,
            "max": book_max_level(bk),
        }
        if not rare and bk["key"] in BOOK_GAINS:
            tier = roll_rarity(self.player.eff_luck())
            off["rarity"] = tier
            off["gains"] = book_gain(bk["key"], tier, lvl)
        return off

    # ---- gizli denge (anti-meta) ----
    # Oyun dünya sıralamalı olduğu için her koşunun aynı bitmesi istenmiyor:
    # 1) kader kilidi: her koşunun başında birkaç silah/kitap o koşuya hiç
    #    gelmemek üzere kapanır.
    # 2) kombo ısısı: bilinen güçlü setlerin eksik parçası, oyuncu o setten ne
    #    kadar çok parça topladıysa o kadar seyrek çıkar.
    # 3) tekrar baskısı: aynı kart üst üste teklif edildikçe ağırlığı düşer;
    #    "ben bunu zaten gördüm" hissi azalır.
    COMBO_SETS = [
        # (parçalar, komboyu ne kadar frenleyeceğimiz)
        (("tornado", "zemzem", "r_vamp"), 0.80),
        (("tornado", "zemzem", "r_killheal"), 0.80),
        (("pentagram", "shoe", "frost"), 0.70),
        (("whip", "emanet", "r_swarm"), 0.60),
        (("axe", "r_critd", "r_crit"), 0.60),
        (("book", "cloak", "r_lasthope"), 0.65),
        (("r_rage", "r_lasthope", "r_killheal"), 0.75),
    ]

    def _roll_destiny(self):
        """Koşunun başında kapanacak silah/kitapları seçer (kader kilidi)."""
        self.destiny_locked = set()
        rnd = random.Random(self.destiny_seed)
        wk = [w["key"] for w in self.save.unlocked_weapons()]
        if len(wk) >= 6:
            rnd.shuffle(wk)
            self.destiny_locked.update(wk[:rnd.randint(1, 2)])
        bk = [b["key"] for b in self.save.unlocked_books() if not b.get("rare")]
        if len(bk) >= 8:
            rnd.shuffle(bk)
            self.destiny_locked.update(bk[:rnd.randint(1, 2)])
        rb = [b["key"] for b in self.save.unlocked_books() if b.get("rare")]
        if len(rb) >= 4:
            rnd.shuffle(rb)
            self.destiny_locked.update(rb[:rnd.randint(1, 2)])

    def _combo_damp(self, key):
        """Kombo ısısı: oyuncu bir setin ne kadarını topladıysa, eksik parçasının ağırlığı o kadar düşer (0.18 .."""
        p = self.player
        owned = set(p.weapons) | set(p.books)
        damp = 1.0
        for parts, strength in self.COMBO_SETS:
            if key not in parts or key in owned:
                continue
            have = sum(1 for k in parts if k in owned)
            if have <= 0:
                continue
            # setin tamamına ne kadar yaklaşıldıysa o kadar sert fren
            f = have / float(len(parts) - 1) if len(parts) > 1 else 1.0
            damp *= max(0.18, 1.0 - strength * clamp(f, 0.0, 1.0))
        return damp

    def _meta_weight(self, key, base):
        """Bir teklifin gerçek ağırlığı: gizli frenlerden geçmiş hâli."""
        if key in self.destiny_locked:
            return 0.0
        w = base * self._combo_damp(key)
        seen = self.offer_seen.get(key, 0)
        if seen > 2:
            # aynı kart tekrar tekrar çıkmasın: her fazladan görülmede -%12
            w *= max(0.45, 1.0 - 0.12 * (seen - 2))
        return max(0.0, w)

    def levelup_pool(self):
        """Bu seviye atlamada çıkabilecek bütün teklifler ve ağırlıkları."""
        p = self.player
        offers, weights = [], []

        # ---- silahlar ----
        unlocked = self.save.unlocked_weapons()
        have = set(p.weapons)
        room = len(have) < slot_max(p, 'w')
        for w in unlocked:
            key = w["key"]
            if key in have:
                if p.weapons[key] < weapon_max_level(w):
                    offers.append(self._weapon_offer(w, p.weapons[key] + 1, False))
                    weights.append(self._meta_weight(key, 11))
            elif room:
                # Henüz 4 silahı dolmayan oyuncuya yeni silah daha sık çıkar:
                # oyuncunun önce kendi takımını kurması isteniyor.
                offers.append(self._weapon_offer(w, 1, True))
                weights.append(self._meta_weight(key, 18))

        # ---- kitaplar ----
        # kitaplar da silahlar gibi yuvalı.
        books = self.save.unlocked_books()
        if not books:
            # emniyet: hiç kitap açılmamışsa ekran boş kalmasın.
            books = [BOOK_BY_KEY[k] for k in STARTER_BOOKS] or list(BOOKS)
        book_room = p.normal_book_count() < slot_max(p, 'b')
        rare_room = p.rare_book_count() < slot_max(p, 'r')
        for bk in books:
            key = bk["key"]
            cur = p.books.get(key, 0)
            rare = bool(bk.get("rare"))
            if rare:
                if cur > 0 or not rare_room:
                    continue
                offers.append(self._book_offer(bk, 1, True))
                # şans: gizli frenlerden sonra nadir kitap ağırlığı büyür.
                weights.append(self._meta_weight(key, 8)
                               * (1.0 + LUCK_RARE_BOOK_K * p.eff_luck()))
                continue
            if cur <= 0:
                if not book_room:
                    continue
                # Yeni kitap, yeni silah kadar sık çıksın: oyuncu seviye
                # atlarken gerçekten "silah mı, kitap mı?" diye düşünsün.
                offers.append(self._book_offer(bk, 1, True))
                weights.append(self._meta_weight(key, 17))
            elif cur < book_max_level(bk):
                offers.append(self._book_offer(bk, cur + 1, False))
                weights.append(self._meta_weight(key, 12))
        return offers, weights

    def start_levelup_choice(self):
        """Üç teklif seçer."""
        if getattr(self, "legend_hands", 0) > 0:
            hand = self._legend_hand()
            if hand:
                self.levelup_choices = hand
                return
            self.legend_hands = 0          # verecek efsanevi kart yok: normal ele düş
        offers, weights = self.levelup_pool()
        pool = [(o, w) for o, w in zip(offers, weights) if w > 0]
        if not pool:
            # Gizli frenler her şeyi kapattıysa frensiz havuza düş.
            pool = [(o, max(1.0, w)) for o, w in zip(offers, weights)]
        if not pool:
            # Hiçbir teklif üretilemezse (her şey tavanda) seviye boşa
            # gitmesin.
            self.levelup_choices = []
            return
        offers = [o for o, _ in pool]
        weights = [w for _, w in pool]

        def draw(cands, cand_w, seen):
            for _ in range(60):
                pick = random.choices(cands, weights=cand_w, k=1)[0]
                if (pick["kind"], pick["key"]) not in seen:
                    return pick
            for c in cands:
                if (c["kind"], c["key"]) not in seen:
                    return c
            return None

        want = min(3, len(offers))
        chosen, seen = [], set()
        # 1) Önce birer silah ve birer kitap garanti edilir (varsa).
        for kind in ("weapon", "book"):
            if len(chosen) >= want:
                break
            cands = [o for o in offers if o["kind"] == kind]
            if not cands:
                continue
            cw = [weights[offers.index(o)] for o in cands]
            pick = draw(cands, cw, seen)
            if pick is not None:
                seen.add((pick["kind"], pick["key"]))
                chosen.append(pick)
        # 2) Kalan yerler normal ağırlıkla dolar.
        while len(chosen) < want:
            pick = draw(offers, weights, seen)
            if pick is None:
                break
            seen.add((pick["kind"], pick["key"]))
            chosen.append(pick)
        # 3) her 5 seviyede garanti nadir kart.
        rare = self._guaranteed_rare_offer(chosen)
        if rare is not None:
            if len(chosen) < 3:
                chosen.append(rare)
            else:
                kinds = [c["kind"] for c in chosen]
                # aynı türden ikinci kartı değiştir; yoksa son kartı
                victim = len(chosen) - 1
                for i, c in enumerate(chosen):
                    if kinds.count(c["kind"]) > 1:
                        victim = i
                chosen[victim] = rare
        chosen = self.evo_inject(chosen)
        random.shuffle(chosen)
        for c in chosen:
            self.offer_seen[c["key"]] = self.offer_seen.get(c["key"], 0) + 1
        self.levelup_choices = chosen

    def levelup_hand_level(self):
        """Şu an açılan seviye kartının hangi seviyeye ait olduğu."""
        return max(1, self.player.level - max(0, self.pending_levelups) + 1)

    def _guaranteed_rare_offer(self, chosen):
        """Her RARE_BOOK_EVERY seviyede ele girecek nadir kitap (yoksa None)."""
        if any(c.get("rare") for c in chosen):
            return None
        if self.levelup_hand_level() % RARE_BOOK_EVERY != 0:
            return None
        p = self.player
        if p.rare_book_count() >= slot_max(p, 'r'):
            return None
        try:
            muted = set(self.save.effective_muted_books())
        except Exception:
            muted = set()
        cands = [b for b in self.save.unlocked_books() if b.get("rare") and b["key"] not in p.books]
        trial = False
        if not cands:
            cands = [b for b in BOOKS if b.get("rare") and b["key"] not in p.books
                     and b["key"] not in muted]
            trial = True
        if not cands:
            return None
        bk = random.choice(cands)
        off = self._book_offer(bk, 1, True)
        off["trial"] = trial and not self.save.owns_book(bk["key"])
        return off

    def choose_levelup(self, idx):
        """Karttaki teklifi uygular. idx, levelup_choices içindeki sıradır."""
        if not (0 <= idx < len(self.levelup_choices)):
            return
        ch = self.levelup_choices[idx]
        p = self.player
        if ch["kind"] == "evo":
            col = ch["color"]
            self.evolve_weapon(ch["key"])
        elif ch["kind"] == "book":
            col = ch["color"]
            lvl = p.take_book(ch["key"], int(ch.get("rarity") or 0))
            if lvl > 0 and ch.get("rarity"):
                tier = int(ch["rarity"])
                self.fx.popup(p.x, p.y - 40, rarity_name(tier), rarity_color(tier),
                              15 + tier, life=1.3)
            if lvl <= 0:
                # Yuvası dolmuş / tavanı dolmuş bir kitap kartı (olmaması
                # gerekir ama el bir kare eskimişse olabilir): seviye yanmasın.
                self.start_levelup_choice()
                return
            bk = ch["book"]
            if bk.get("rare"):
                self.fx.popup(p.x, p.y - 64, f"{bk['name']}", col, 24, life=1.6)
            else:
                self.fx.popup(p.x, p.y - 64,
                              bk_name(bk) + ("" if lvl <= 1 else f"  Lv.{lvl}"),
                              col, 22, life=1.3)
        else:
            key = ch["key"]
            w = ch["w"]
            first = key not in p.weapons
            p.weapons[key] = p.weapons.get(key, 0) + 1
            if first:
                # Yeni silah hemen ateşlemesin diye kısa bir ilk bekleme.
                p.weapon_timers[key] = weapon_cooldown(w, 1) * 0.35
            col = ch["color"]
            self.fx.popup(p.x, p.y - 64,
                          w_name(w) + ("" if first else " " + L("ui.level_up_n", p.weapons[key])),
                          col, 24, life=1.4)
            # şans: kartın nadirlik bonusu (yeni silah kartında da).
            if ch.get("boost"):
                gained = p.add_weapon_boost(key, ch["boost"])
                tier = int(ch.get("rarity", 0))
                if gained > 0:
                    rc = rarity_color(tier)
                    self.fx.popup(p.x, p.y - 40, "%s  %s" % (
                        rarity_name(tier), L("ui.boost_dmg", fmt_pct1(gained))),
                        rc, 15 + tier, life=1.4)
                    if tier >= 3:
                        self.fx.ring(p.x, p.y, rc, n=24 + 6 * tier, speed=260, life=0.55, r=3.5)
                        self.fx.do_flash(rc, 0.2 + 0.05 * tier)
        if ch.get("legend"):
            self.legend_hands = max(0, getattr(self, "legend_hands", 0) - 1)
        self.pending_levelups -= 1
        self.fx.ring(p.x, p.y, col, n=16, speed=190, life=0.45, r=3)
        sfx("buy", 0.8, 0.0)
        self._next_levelup_or_close()

    def _next_levelup_or_close(self):
        if self.pending_levelups > 0:
            self.start_levelup_choice()
        else:
            self.levelup_choices = []

    def reroll_levelup(self):
        """Eli yeniler."""
        cost = self.reroll_cost()
        lucky = False
        bonus = False
        if self.reroll_used >= self.REROLL_FREE and getattr(self, "reroll_bonus", 0) > 0:
            bonus = True            # kitaptan kazanılan bedava hak harcanır
            cost = 0
        elif cost > 0:
            # şanslı yenileme: bedava hak bitmiş olsa bile şans * 0.20 (en
            # fazla %35) olasılıkla yenileme bedava olur ve sayaca da yazılmaz
            # - sonraki yenilemenin fiyatı artmaz.
            if random.random() < min(LUCK_FREE_REROLL_MAX,
                                     self.player.eff_luck() * LUCK_FREE_REROLL_K):
                lucky = True
                cost = 0
        if cost > self.gold_wallet:
            return False, L("ui.need_gold", cost)
        if cost:
            self.gold_wallet -= cost
        if bonus:
            self.reroll_bonus -= 1
        elif not lucky:
            self.reroll_used += 1
        prev = [(c["kind"], c["key"]) for c in self.levelup_choices]
        # Yeni el eskisinin aynısı çıkmasın diye birkaç deneme yapılır.
        for _ in range(6):
            self.start_levelup_choice()
            if [(c["kind"], c["key"]) for c in self.levelup_choices] != prev:
                break
        sfx("click", 0.7, 0.0)
        if lucky:
            p = self.player
            self.fx.popup(p.x, p.y - 90, L("ui.luck_free"), GREEN, 18, life=1.4)
            return True, L("ui.luck_free")
        return True, (L("ui.free_reroll") if cost == 0 else L("ui.minus_gold", cost))

    def skip_levelup(self):
        """Bu seviyeyi pas geçer."""
        cost = self.skip_cost()
        if cost > self.gold_wallet:
            return False, L("ui.need_gold", cost)
        if cost:
            self.gold_wallet -= cost
        self.skip_used += 1
        if any(c.get("legend") for c in self.levelup_choices):
            self.legend_hands = max(0, getattr(self, "legend_hands", 0) - 1)
        self.pending_levelups -= 1
        sfx("hover", 0.8, 0.0)
        self._next_levelup_or_close()
        return True, (L("ui.free_skip") if cost == 0 else L("ui.minus_gold", cost))

    def run_is_clean(self):
        """Bu koşu sıralamalara yazılabilir mi?"""
        return not self.cheat_flag

    def _tick_boss_wound(self, players):
        """yara: sahada yaşayan patron varken oyuncuların şifası azalır."""
        wd = 0.0
        for b in self.bosses:
            if b.alive:
                wd = max(wd, float(getattr(b, "wound", 0.0) or 0.0))
        for pl in players:
            pl.wound = wd

    def total_wave(self):
        """Bu koşuda geçilen toplam dalga: cehennemde arenadakiler de sayılır."""
        w = int(self.waves.wave)
        return w + int(self.arena_waves) if self.biome == "hell" else w

    def finish_run(self):
        self.game_over = True
        _st0 = self.save.data.get("stats", {})
        self.prev_best = {
            "score": int(_st0.get("best_score", 0) or 0),
            "wave": int(_st0.get("best_wave", 0) or 0),
            "kills": int(_st0.get("best_run_kills", 0) or 0),
            "combo": int(_st0.get("best_combo", 0) or 0),
        }
        # Koşu bitti: skor; öldürme, dalga ve süreyle tutarlı mı?
        if not self.cheat_flag and not run_score_plausible(self):
            self.cheat_flag = "skor"
        # koşu denetimi takıldıysa hesap kalıcı olarak sıralama dışı.
        if self.cheat_flag:
            self.save.mark_tainted("run")
        # Hileli koşu elmas da kazandırmaz; yoksa "hile yap, elması al,
        # sıralamaya girme" diye bir yol açık kalırdı. arena ustalığı "HAZİNE"
        # dalı elmas kazancını büyütür.
        gems = (int(self.gem_coins * RUN_GEM_RATE * getattr(self.player, "gem_mult", 1.0))
                if self.run_is_clean() else 0)
        # koşu görevleri: biten görevlerin elması (yalnız temiz koşu)
        if self.quests and not self.cheat_flag:
            self.update_quests()
        self.quest_gems = self.quest_gems_due() if self.run_is_clean() else 0
        gems += self.quest_gems
        self.save.add_gems(gems)
        st = self.save.data["stats"]
        st["runs"] = st.get("runs", 0) + 1
        st["best_score"] = max(st.get("best_score", 0), int(self.score))
        st["total_kills"] = st.get("total_kills", 0) + int(self.kills)
        st["total_time"] = st.get("total_time", 0.0) + self.run_time
        st["best_wave"] = max(st.get("best_wave", 0), self.total_wave())   # cehennemde arena + cehennem
        # ---- kitap görevleri için izlenen istatistikler ----
        p = self.player
        st["best_run_kills"] = max(st.get("best_run_kills", 0), int(self.kills))
        st["total_healed"] = st.get("total_healed", 0.0) + float(p.run_healed)
        st["best_run_heal"] = max(st.get("best_run_heal", 0.0), float(p.run_healed))
        st["total_crits"] = st.get("total_crits", 0) + int(p.run_crits)
        st["total_bonks"] = st.get("total_bonks", 0) + int(p.run_bonks)
        # total_dashes artık canlı işleniyor; burada bir daha eklenirse koşu
        # başına iki kat sayılırdı.
        st["best_run_dashes"] = max(st.get("best_run_dashes", 0), int(p.dash_count))
        st["best_combo"] = max(st.get("best_combo", 0), int(self.combo.best))
        st["best_run_dashes"] = max(st.get("best_run_dashes", 0), int(p.dash_count))
        st["total_shots"] = st.get("total_shots", 0) + int(p.run_shots)
        # anahtarlar / efsanevi sandık
        st["total_keys"] = int(st.get("total_keys", 0) or 0) + int(getattr(self, "run_keys", 0))
        st["legend_chests"] = (int(st.get("legend_chests", 0) or 0)
                               + int(getattr(self, "legend_opened", 0)))
        st["best_run_shots"] = max(st.get("best_run_shots", 0), int(p.run_shots))
        st["total_lifesteal"] = st.get("total_lifesteal", 0.0) + float(p.run_lifesteal)
        st["total_gold"] = st.get("total_gold", 0) + int(self.coins_earned)
        st["best_run_gold"] = max(st.get("best_run_gold", 0), int(self.coins_earned))
        st["total_bonk_hits"] = st.get("total_bonk_hits", 0) + int(self.bonk_hits)
        # şans kitabı görevi. Eski kayıtta alan yoksa 0'dan başlar.
        st["total_chests"] = int(st.get("total_chests", 0) or 0) + int(getattr(self, "chests_opened", 0))
        # kabul edilen lanetli teklifler ve en yüksek lanet çarpanı
        st["total_cursed"] = int(st.get("total_cursed", 0) or 0) + int(getattr(self, "cursed_taken", 0))
        st["best_curse"] = max(int(st.get("best_curse", 0) or 0), int(getattr(self, "cursed_taken", 0)))
        st["total_goblins"] = int(st.get("total_goblins", 0) or 0) + int(getattr(self, "goblins_caught", 0))
        # Koşu içi markette hangi eşyanın kaç seviyeye kadar çıkarıldığı: bazı
        # kitaplar "şu eşyayı tavana kadar yükselt" görevini bunun üzerinden
        # ölçer.
        shop_max = st.setdefault("shop_max", {})
        for key, lvl in (p.shop_levels or {}).items():
            if int(lvl) > int(shop_max.get(key, 0)):
                shop_max[key] = int(lvl)
        # harita sayaçları (Buzul / Çöl / Orman başarımları)
        maps_before = getattr(self, "maps_at_start", None)
        if maps_before is None:
            maps_before = [m for m in MAP_THEMES if map_unlocked(self.save, m)]
        self.commit_map_stats()
        # harita kilidi: haritanın en iyi dalgası (cehennem dahil)
        th_ = getattr(self, "map_theme", "stone")
        if th_ in MAP_THEMES:
            k_ = "best_%s_wave" % th_
            st[k_] = max(_stat_int(st, k_), int(self.total_wave()))
        self.new_maps = [m for m in MAP_THEMES
                         if m not in maps_before and map_unlocked(self.save, m)]
        if self.ach:
            self.ach.check_stats()      # silah şartı başarımsa önce o açılsın
        # Görevi bu koşuda tamamlanan kitapları kalıcı olarak aç.
        self.new_books = self.save.refresh_book_unlocks()
        self.new_weapons = self.save.refresh_weapon_unlocks()
        # Toplam sayaçlara bağlı başarımları tara (Usta Avcı, Sülük, ...).
        if self.ach:
            self.ach.check_stats()
        self.save.progress_changed()
        self.gems_earned = gems
        sfx("gameover", 1.0, 0.0)


# arka plan

class Background:
    """Menü ve ekran-arası zemin."""

    def __init__(self):
        self.gradient = self._build_gradient()
        self.dust = []
        for _ in range(70):
            self.dust.append({
                "x": random.uniform(0, VIRTUAL_W), "y": random.uniform(0, VIRTUAL_H),
                "r": random.uniform(1, 2.6), "spd": random.uniform(6, 22),
                "a": random.uniform(30, 90), "phase": random.uniform(0, math.tau),
            })
        # kırpışan yıldızlar (menünün derinliği)
        self.stars = [(random.uniform(0, VIRTUAL_W), random.uniform(0, VIRTUAL_H),
                       random.uniform(0.7, 1.9), random.uniform(0, math.tau),
                       random.uniform(0.6, 2.2))
                      for _ in range(150)]
        # dolaşan renkli sis: (renk, yarıçap, hız, faz, dikey oran)
        self.nebula = [((58, 84, 170), 340, 0.055, 0.0, 0.30),
                       ((120, 60, 150), 300, 0.041, 2.1, 0.62),
                       ((40, 110, 140), 260, 0.033, 4.0, 0.44),
                       ((150, 110, 50), 220, 0.026, 5.4, 0.78)]
        self.t = 0.0
        # ---- yılbaşı: kar taneleri ----
        # Yalnızca mevsiminde dolu; değilse liste boş kalır ve update/ draw'da
        # hiçbir ek işlem/maliyet olmaz.
        self.snow = []
        if NEW_YEAR_THEME:
            for _ in range(90):
                self.snow.append({
                    "x": random.uniform(0, VIRTUAL_W),
                    "y": random.uniform(-VIRTUAL_H, VIRTUAL_H),
                    "r": random.uniform(1.4, 3.6), "spd": random.uniform(24, 70),
                    "drift": random.uniform(-18, 18), "phase": random.uniform(0, math.tau),
                    "a": random.uniform(120, 220),
                })

    def _build_gradient(self):
        surf = pygame.Surface((VIRTUAL_W, VIRTUAL_H))
        for y in range(VIRTUAL_H):
            t = y / VIRTUAL_H
            col = (int(lerp(BG_TOP[0], BG_BOTTOM[0], t)), int(lerp(BG_TOP[1], BG_BOTTOM[1], t)),
                   int(lerp(BG_TOP[2], BG_BOTTOM[2], t)))
            pygame.draw.line(surf, col, (0, y), (VIRTUAL_W, y))
        return surf

    def update(self, dt):
        self.t += dt
        for d in self.dust:
            d["y"] -= d["spd"] * dt
            d["x"] += math.sin(self.t * 0.5 + d["phase"]) * 6 * dt
            if d["y"] < -10:
                d["y"] = VIRTUAL_H + 10
                d["x"] = random.uniform(0, VIRTUAL_W)
        for s in self.snow:
            s["y"] += s["spd"] * dt
            s["x"] += (s["drift"] + math.sin(self.t * 0.8 + s["phase"]) * 14) * dt
            if s["y"] > VIRTUAL_H + 10:
                s["y"] = -10
                s["x"] = random.uniform(0, VIRTUAL_W)
            if s["x"] < -10:
                s["x"] = VIRTUAL_W + 10
            elif s["x"] > VIRTUAL_W + 10:
                s["x"] = -10

    def draw(self, surf):
        if MOBILE:
            # telefon: arka plan saniyede ~12 kez çizilir, arada hazır görüntü
            # (tek opak kopya) basılır.
            c = getattr(self, "_mob_cache", None)
            if c is None or abs(self.t - self._mob_t) >= 0.08:
                if c is None:
                    c = pygame.Surface((VIRTUAL_W, VIRTUAL_H)).convert()
                    self._mob_cache = c
                self._draw_full(c)
                self._mob_t = self.t
            surf.blit(c, (0, 0))
            return
        self._draw_full(surf)

    def _draw_full(self, surf):
        surf.blit(self.gradient, (0, 0))
        # ---- dolaşan renkli sis ----
        for (col, rad, spd, ph, vy) in self.nebula:
            nx = VIRTUAL_W * (0.5 + 0.42 * math.sin(self.t * spd + ph))
            ny = VIRTUAL_H * vy + math.cos(self.t * spd * 1.3 + ph) * 40
            add_glow(surf, nx, ny, rad, col, 0.13)
        # ---- kırpışan yıldızlar ----
        for (sx, sy, sr, sph, ssp) in self.stars:
            tw = 0.35 + 0.65 * (0.5 + 0.5 * math.sin(self.t * ssp + sph))
            blit_disc(surf, sx, sy, sr * (0.7 + 0.5 * tw), (210, 224, 255),
                      int(150 * tw))
        surf.blit(self._grid(), (0, 0))
        for d in self.dust:
            a = int(d["a"] * (0.6 + 0.4 * math.sin(self.t * 2 + d["phase"])))
            blit_disc(surf, d["x"], d["y"], d["r"], (150, 180, 255), max(0, a))
        # ---- yılbaşı: kar taneleri ----
        for s in self.snow:
            tw = 0.75 + 0.25 * math.sin(self.t * 3 + s["phase"])
            blit_disc(surf, s["x"], s["y"], s["r"], (255, 255, 255), int(s["a"] * tw))
        surf.blit(self._vignette(), (0, 0), special_flags=pygame.BLEND_RGBA_SUB)

    # ---- performans ----
    def _grid(self):
        g = getattr(self, "_grid_surf", None)
        if g is None:
            g = pygame.Surface((VIRTUAL_W, VIRTUAL_H), pygame.SRCALPHA)
            for x in range(0, VIRTUAL_W, 64):
                pygame.draw.line(g, (255, 255, 255, 6), (x, 0), (x, VIRTUAL_H))
            for y in range(0, VIRTUAL_H, 64):
                pygame.draw.line(g, (255, 255, 255, 6), (0, y), (VIRTUAL_W, y))
            self._grid_surf = g
        return g

    def _vignette(self):
        v = getattr(self, "_vig_surf", None)
        if v is None:
            v = pygame.Surface((VIRTUAL_W, VIRTUAL_H), pygame.SRCALPHA)
            pygame.draw.rect(v, (0, 0, 0, 90), v.get_rect())
            pygame.draw.rect(v, (0, 0, 0, 0), v.get_rect().inflate(-220, -160), border_radius=140)
            self._vig_surf = v
        return v

    def static_frame(self):
        """Oyun sırasında kullanılan donuk zemin (tek blit)."""
        f = getattr(self, "_static", None)
        if f is None:
            f = pygame.Surface((VIRTUAL_W, VIRTUAL_H)).convert()
            snow, self.snow = self.snow, []
            try:
                self.draw(f)
            finally:
                self.snow = snow
            self._static = f
        return f


# ekran / ölçekleme

# ---- kontrolcü (gamepad) ----
# neden sanal imleç: oyunun bütün arayüzü fare konumuna göre çalışıyor (her
# ekran mouse_pos alıp collidepoint ediyor).

PAD_DEADZONE = 0.28          # çubuk merkezdeyken titremesin
PAD_CURSOR_SPEED = 900.0     # menüde imleç hızı (sanal piksel/sn)
PAD_AIM_RADIUS = 300.0       # oyunda nişangahın oyuncudan uzaklığı


def _dz(v, dead=PAD_DEADZONE):
    """Ölü bölge + yeniden ölçekleme: eşiğin hemen üstünde ani sıçrama olmasın."""
    a = abs(v)
    if a < dead:
        return 0.0
    return math.copysign((a - dead) / (1.0 - dead), v)


class Gamepad:
    """Tek bir kontrolcüyü okur."""

    def __init__(self):
        self.ok = False
        self.pad = None
        self.name = ""
        self.cursor = [VIRTUAL_W / 2, VIRTUAL_H / 2]
        self.active = False          # son girdi pad'den mi geldi?
        self._prev = {}              # düğme kenarı yakalamak için
        self._edge = set()           # bu karede yeni basılan düğmeler
        try:
            from pygame._sdl2 import controller as _ctrl
            _ctrl.init()
            self._ctrl = _ctrl
            self.rescan()
        except Exception:
            self._ctrl = None

    def rescan(self):
        """Takılı pad'i bulur."""
        if self._ctrl is None:
            return
        try:
            for i in range(self._ctrl.get_count()):
                if self._ctrl.is_controller(i):
                    self.pad = self._ctrl.Controller(i)
                    self.name = self._ctrl.name_forindex(i) or "Kontrolcü"
                    self.ok = True
                    return
        except Exception:
            pass
        self.pad = None
        self.ok = False

    def handle_event(self, event):
        """Pad takma/çıkarma olayları."""
        if event.type in (pygame.JOYDEVICEADDED, pygame.JOYDEVICEREMOVED):
            self.rescan()

    # ---- ham okuma ----
    def _axis(self, which):
        if not self.ok:
            return 0.0
        try:
            return _dz(self.pad.get_axis(which) / 32768.0)
        except Exception:
            return 0.0

    def _btn(self, which):
        if not self.ok:
            return False
        try:
            return bool(self.pad.get_button(which))
        except Exception:
            return False

    def update(self, dt, mouse_moved):
        """Her karede bir kez."""
        if not self.ok:
            self.active = False
            self._edge = set()
            return
        C = pygame
        now = {
            "a": self._btn(C.CONTROLLER_BUTTON_A),
            "b": self._btn(C.CONTROLLER_BUTTON_B),
            "x": self._btn(C.CONTROLLER_BUTTON_X),
            "y": self._btn(C.CONTROLLER_BUTTON_Y),
            "lb": self._btn(C.CONTROLLER_BUTTON_LEFTSHOULDER),
            "rb": self._btn(C.CONTROLLER_BUTTON_RIGHTSHOULDER),
            "start": self._btn(C.CONTROLLER_BUTTON_START),
            "back": self._btn(C.CONTROLLER_BUTTON_BACK),
            "up": self._btn(C.CONTROLLER_BUTTON_DPAD_UP),
            "down": self._btn(C.CONTROLLER_BUTTON_DPAD_DOWN),
            "left": self._btn(C.CONTROLLER_BUTTON_DPAD_LEFT),
            "right": self._btn(C.CONTROLLER_BUTTON_DPAD_RIGHT),
        }
        self._edge = {k for k, v in now.items() if v and not self._prev.get(k)}
        self._prev = now

        lx, ly = self.left_stick()
        rx, ry = self.right_stick()
        used = (abs(lx) + abs(ly) + abs(rx) + abs(ry)) > 0.01 or any(now.values()) \
            or self.trigger_right() > 0.2
        # Fare oynarsa söz fareye geçer, pad oynarsa pad'e. İkisi birbirinin
        # imlecini kapmasın diye son hareket eden kazanıyor.
        if used:
            self.active = True
        elif mouse_moved:
            self.active = False
        if self.active:
            self.cursor[0] = clamp(self.cursor[0] + lx * PAD_CURSOR_SPEED * dt, 0, VIRTUAL_W)
            self.cursor[1] = clamp(self.cursor[1] + ly * PAD_CURSOR_SPEED * dt, 0, VIRTUAL_H)

    # ---- dışarıya açık yüzey ----
    def left_stick(self):
        return self._axis(pygame.CONTROLLER_AXIS_LEFTX), self._axis(pygame.CONTROLLER_AXIS_LEFTY)

    def right_stick(self):
        return self._axis(pygame.CONTROLLER_AXIS_RIGHTX), self._axis(pygame.CONTROLLER_AXIS_RIGHTY)

    def trigger_right(self):
        if not self.ok:
            return 0.0
        try:
            return clamp(self.pad.get_axis(pygame.CONTROLLER_AXIS_TRIGGERRIGHT) / 32768.0, 0.0, 1.0)
        except Exception:
            return 0.0

    def pressed(self, name):
        """Bu karede yeni basıldı mı?"""
        return name in self._edge

    def held(self, name):
        return bool(self._prev.get(name))

    def fire_held(self):
        """Ateş: sağ tetik ya da A."""
        return self.trigger_right() > 0.3 or self.held("a")


# Pad düğmelerinin arayüzde görünen adları (yetenek çubuğu etiketleri).
PAD_LABELS = {"fire": "RT", "bonk": "X", "dash": "LB", "shop": "Y",
              "use": "A", "pause": "START", "stats": "BACK", "map": "RB"}

# Çizim işlevleri App örneğini görmüyor (hepsi serbest fonksiyon).
PAD_ACTIVE = [False]


# ---- mağaza / ücretsiz elmas / yılbaşı / açılış metinleri ----
