# başlangıç seçimi: koşu başında 3 silah kartı (nadirlik çeker; nadir silah
# daha yüksek seviyeden başlar) ve 3 yemin kartı.
OATH_BULWARK_EVERY = 40.0            # sur yemini: kalkan dolum aralığı (sn)
MERCHANT_LUCK_PER_LEVEL = 0.08       # tüccarın kademe şansı: seviye başına +%8
# "tüccar her seviyede değişiyor - bir kez açalım, 3 kez parayla yenileme
# hakkımız olsun". El ilk konuşmada bir kez çekilir ve kendiliğinden değişmez.
MERCHANT_REROLLS = 3
MERCHANT_REROLL_BASE = 100           # 1. yenilemenin taban fiyatı
MERCHANT_REROLL_WAVE = 20            # dalga başına fiyat artışı
MERCHANT_REROLL_STEP = (1, 2, 3)     # 1. / 2. / 3. yenilemenin katı


def merchant_reroll_cost(wave, used):
    """Tüccarın elini yenilemenin altın bedeli (used: kaç kez yenilendi)."""
    k = MERCHANT_REROLL_STEP[min(int(used), len(MERCHANT_REROLL_STEP) - 1)]
    return int((MERCHANT_REROLL_BASE + MERCHANT_REROLL_WAVE * max(1, int(wave))) * k)
# Yeminin güç tarafı kademeyle büyür (Yaygın .. Efsanevi); bedel sabittir.
OATH_TIER_MULT = (1.0, 1.25, 1.5, 1.85, 2.3)


def oath_values(key, tier=0):
    """Yeminin güç değerleri bu kademede: (değer1, değer2?)."""
    m = OATH_TIER_MULT[int(clamp(int(tier), 0, len(OATH_TIER_MULT) - 1))]
    t = int(clamp(int(tier), 0, len(OATH_TIER_MULT) - 1))
    if key == "glass":
        return (0.30 * m,)
    if key == "gold_fever":
        return (0.35 * m,)
    if key == "turtle":
        return (float(int(round(50 * m))), 0.08 * m)
    if key == "scholar":
        return (0.25 * m,)
    if key == "gambler":
        return (0.50 * m,)
    if key == "blood":
        return (0.02 * m,)
    if key == "wind":
        return (0.12 * m, 0.25 * m)
    if key == "bulwark":
        return (float(3 + t), float(int(round(OATH_BULWARK_EVERY / m))))
    if key == "hunter":
        return (1.0 * m,)
    if key == "feast":
        return (0.25 * m,)
    if key == "hoard":
        return (float(int(round(350 * m / 10.0)) * 10),)
    if key == "hawkeye":
        return (0.12 * m, 0.25 * m)
    return ()


def oath_up_text(key, tier=0):
    """Yemin kartının güç satırı, kademenin gerçek sayılarıyla."""
    v = oath_values(key, tier)
    pct = lambda x: "+" + fmt_pct1(x)
    if key == "turtle":
        args = ("+%d" % int(v[0]), pct(v[1]))
    elif key == "bulwark":
        args = ("+%d" % int(v[0]), "%d" % int(v[1]))
    elif key == "hoard":
        args = (fmt_num(int(v[0])),)
    elif key == "hunter":
        args = (pct(stack_bonus(0.385, v[0], soft=3.5)),)
    else:
        args = tuple(pct(x) for x in v)
    return L("oath.%s.up" % key, *args)
