def run_floor_key(run):
    """Bu koşunun zemin/stil anahtarı (cehennem ya da arenanın haritası)."""
    if getattr(run, "biome", "arena") == "hell":
        return "hell"
    return MAP_FLOOR_KEY.get(getattr(run, "map_theme", "stone"), "arena")


_FLOOR_CACHE = {}


def _decorate_arena_floor(surf, st, rnd):
    """1. haritanın zeminini boyar."""
    stone, stone_lo = st["stone"], st["stone_lo"]
    moss, rune = st["moss"], st["rune"]
    sand, crystal = st["sand"], st["crystal"]
    W, H = ARENA_RECT.w, ARENA_RECT.h

    # ---- kırık taş döşeme ----
    # Izgaraya oturan ama her biri biraz kaymış/dönmüş taşlar: dümdüz bir
    # fayans deseni yerine yıllanmış, oturmuş bir meydan hissi.
    TILE = 104
    for gy in range(-1, H // TILE + 2):
        for gx in range(-1, W // TILE + 2):
            if rnd.random() < 0.09:
                continue                      # eksik/kırılmış taş
            cx = gx * TILE + TILE * 0.5 + rnd.uniform(-3, 3)
            cy = gy * TILE + TILE * 0.5 + rnd.uniform(-3, 3)
            # doğal zemin: taş yalnız meydanda ve yollarda
            if st.get("terrain") and rnd.random() > terrain_tile_weight(st, cx, cy, W, H):
                continue
            # Bazı taşlar iki kat geniş: tek tip kare fayans hissi olmasın.
            wide = rnd.random() < 0.16
            hw = TILE * (0.96 if wide else 0.5) - rnd.uniform(2.5, 5.0)
            hh = TILE * 0.5 - rnd.uniform(2.5, 5.0)
            ang = rnd.uniform(-0.022, 0.022)
            pts = rot_pts([(-hw, -hh), (hw, -hh), (hw, hh), (-hw, hh)],
                          ang, cx, cy)
            shade = rnd.uniform(0.80, 1.20)
            face = scale_col(stone, shade)
            # derz gölgesi (taşın altına düşen koyu bant)
            pygame.draw.polygon(surf, scale_col(stone_lo, 0.55),
                                [(x, y + 4) for x, y in pts])
            pygame.draw.polygon(surf, face, pts)
            # üst kenarda pah ışığı, alt kenarda gölge: taş kabarık dursun
            pygame.draw.line(surf, scale_col(face, 1.5), pts[0], pts[1], 2)
            pygame.draw.line(surf, scale_col(face, 1.28), pts[0], pts[3], 1)
            pygame.draw.line(surf, scale_col(stone_lo, 0.7), pts[3], pts[2], 2)
            pygame.draw.polygon(surf, scale_col(stone_lo, 0.85), pts, 1)
            # taşın üstünde çatlak
            if rnd.random() < 0.30:
                a = rnd.uniform(0, math.pi)
                ln = hw * rnd.uniform(0.5, 1.1)
                pygame.draw.line(surf, scale_col(stone_lo, 0.75),
                                 (cx - math.cos(a) * ln, cy - math.sin(a) * ln * 0.8),
                                 (cx + math.cos(a) * ln, cy + math.sin(a) * ln * 0.8), 2)
            # derzden fışkıran yosun
            if rnd.random() < 0.22:
                mx = cx + rnd.uniform(-hw, hw)
                my = cy + hh * rnd.choice((-1, 1))
                blit_disc(surf, mx, my, rnd.uniform(5, 13), moss,
                          int(rnd.uniform(40, 95)))

    # ---- merkezdeki kadim mühür ----
    # Dünyanın tam ortası: oyuncunun doğduğu yer. İki taş halka, aralarında bir
    # yazıt kuşağı ve ortada sekiz kollu bir yıldız.
    ccx, ccy = W * 0.5, H * 0.5
    R = 300
    blit_disc(surf, ccx, ccy, R * 1.06, sand, 60)
    for k, rad in ((0.52, R), (0.68, R * 0.82), (0.40, R * 0.55), (0.58, R * 0.40)):
        ring_aa(surf, ccx, ccy, rad, scale_col(rune, k), 3)
    # yazıt kuşağı: iki halka arasında eşit aralıklı kısa çentikler
    for i in range(72):
        a = i * math.tau / 72
        r0, r1 = R * 0.84, R * 0.98
        w = 3 if i % 6 == 0 else 1
        pygame.draw.line(surf, scale_col(rune, 0.70 if i % 6 == 0 else 0.42),
                         (ccx + math.cos(a) * r0, ccy + math.sin(a) * r0),
                         (ccx + math.cos(a) * r1, ccy + math.sin(a) * r1), w)
    # sekiz kollu yıldız
    star = []
    for i in range(16):
        a = -math.pi / 2 + i * math.pi / 8
        rr = R * (0.38 if i % 2 == 0 else 0.15)
        star.append((ccx + math.cos(a) * rr, ccy + math.sin(a) * rr))
    poly_aa(surf, star, scale_col(rune, 0.26))
    poly_edge(surf, star, scale_col(rune, 0.62), 2)
    circle_aa(surf, ccx, ccy, R * 0.09, scale_col(rune, 0.50))

    # ---- köşe sütun kaideleri ----
    # Dört köşede yıkılmış sütunların kaidesi: harita bir "yapı" gibi dursun.
    for (px, py) in ((W * 0.22, H * 0.22), (W * 0.78, H * 0.22),
                     (W * 0.22, H * 0.78), (W * 0.78, H * 0.78)):
        blit_disc(surf, px, py + 8, 74, (0, 0, 0), 70)
        for rr, k in ((66, 0.72), (52, 1.0), (40, 1.22)):
            pts = [(px + math.cos(i * math.tau / 8) * rr,
                    py + math.sin(i * math.tau / 8) * rr * 0.86) for i in range(8)]
            pygame.draw.polygon(surf, scale_col(stone, k), pts)
            pygame.draw.polygon(surf, scale_col(stone_lo, 0.9), pts, 2)
        ring_aa(surf, px, py, 30, scale_col(rune, 0.52), 2)
        # kırık sütun gövdesi: kaidenin üstünde kısa bir kütük
        for i in range(3):
            rr = 26 - i * 5
            pygame.draw.circle(surf, scale_col(stone, 1.0 + i * 0.12),
                               (int(px), int(py - i * 7)), rr)
        pygame.draw.circle(surf, scale_col(stone_lo, 1.1),
                           (int(px), int(py - 14)), 16, 2)

    # ---- yerden çıkan kristaller ----
    for _ in range(_nd(46)):
        cx, cy = rnd.uniform(60, W - 60), rnd.uniform(60, H - 60)
        if dist(cx, cy, ccx, ccy) < R * 1.1:
            continue                          # mührün üstüne kristal çıkmaz
        h = rnd.uniform(16, 38)
        w = h * rnd.uniform(0.26, 0.40)
        blit_disc(surf, cx, cy + 3, w * 2.2, (0, 0, 0), 70)
        add_glow(surf, cx, cy - h * 0.4, h * 1.5, crystal, 0.16)
        for sgn, k in ((-1, 0.62), (1, 1.0)):
            pts = [(cx, cy - h * k), (cx + sgn * w, cy - h * 0.34 * k),
                   (cx + sgn * w * 0.7, cy + 4), (cx - sgn * w * 0.2, cy + 4)]
            pygame.draw.polygon(surf, scale_col(crystal, 0.30 + 0.22 * k), pts)
            pygame.draw.polygon(surf, scale_col(crystal, 0.62), pts, 1)

    # ---- moloz / çakıl ----
    for _ in range(_nd(300)):
        cx, cy = rnd.uniform(10, W - 10), rnd.uniform(10, H - 10)
        rad = rnd.uniform(2.5, 7.0)
        n = rnd.randint(5, 7)
        pts = [(cx + math.cos(i * math.tau / n) * rad * rnd.uniform(0.7, 1.25),
                cy + math.sin(i * math.tau / n) * rad * rnd.uniform(0.6, 1.0))
               for i in range(n)]
        pygame.draw.polygon(surf, scale_col(stone_lo, 0.85), [(x, y + 2) for x, y in pts])
        pygame.draw.polygon(surf, scale_col(stone, rnd.uniform(0.85, 1.25)), pts)

    # ---- eski dövüşlerin izleri ----
    # Zemine kazınmış uzun kılıç çizikleri: burada çok kan dökülmüş.
    for _ in range(_nd(46)):
        x0, y0 = rnd.uniform(0, W), rnd.uniform(0, H)
        a = rnd.uniform(0, math.tau)
        ln = rnd.uniform(26, 64)
        p1 = (x0 + math.cos(a) * ln, y0 + math.sin(a) * ln * 0.75)
        pygame.draw.line(surf, scale_col(stone_lo, 0.6), (x0, y0), p1, 2)

# taş meydan süsleri: "ana oyun taş meydanının arka planı çok sade".
STONE_ROAD_W = 176
_STONE_FIRES = None      # [(dünya_x, dünya_y, boy)] - mangal / meşale alevleri


def stone_fire_spots():
    """Taş Meydan'daki alevlerin dünya koordinatları (bir kez hesaplanır)."""
    global _STONE_FIRES
    if _STONE_FIRES is None:
        W, H = ARENA_RECT.w, ARENA_RECT.h
        cx, cy = W * 0.5, H * 0.5
        spots = []
        for i in range(8):                      # mührün çevresindeki mangallar
            a = math.pi / 8 + i * math.tau / 8
            spots.append((cx + math.cos(a) * 430, cy + math.sin(a) * 430, 1.0))
        half = STONE_ROAD_W * 0.5 + 26
        for d in range(560, int(max(W, H) * 0.5), 420):   # yol boyu meşaleler
            for sgn in (-1, 1):
                for sx_, sy_ in ((cx + d * sgn, cy - half), (cx + d * sgn, cy + half),
                                 (cx - half, cy + d * sgn), (cx + half, cy + d * sgn)):
                    if 60 < sx_ < W - 60 and 60 < sy_ < H - 60:
                        spots.append((sx_, sy_, 0.62))
        _STONE_FIRES = [(ARENA_RECT.left + x, ARENA_RECT.top + y, k) for x, y, k in spots]
    return _STONE_FIRES


def _decorate_stone_plaza(surf, st, rnd):
    """Taş Meydan'a özel süsler."""
    W, H = ARENA_RECT.w, ARENA_RECT.h
    cx, cy = W * 0.5, H * 0.5
    R = 300
    rw = STONE_ROAD_W
    pave = (88, 80, 92)
    pave_lo = (40, 34, 46)
    trim = (168, 132, 74)
    # ---- tören yolları: mühre çıkan dört kaldırım (balıksırtı tuğla) ----
    for horiz in (True, False):
        length = W if horiz else H
        step_a, step_b = 34, 17
        row = 0
        across = -rw / 2 + 6
        while across < rw / 2 - 6:
            off = (row % 2) * step_a * 0.5
            along = -off
            while along < length:
                if horiz:
                    bx, by = along, cy + across
                else:
                    bx, by = cx + across, along
                if dist(bx + (step_a / 2 if horiz else step_b / 2),
                        by + (step_b / 2 if horiz else step_a / 2), cx, cy) > R * 1.26:
                    rect = (pygame.Rect(int(bx), int(by), step_a - 2, step_b - 2) if horiz
                            else pygame.Rect(int(bx), int(by), step_b - 2, step_a - 2))
                    col = scale_col(pave, rnd.uniform(0.82, 1.14))
                    pygame.draw.rect(surf, pave_lo, rect.move(0, 2))
                    pygame.draw.rect(surf, col, rect)
                    pygame.draw.line(surf, scale_col(col, 1.25), rect.topleft, rect.topright, 1)
                along += step_a
            across += step_b
            row += 1
        # yol kenarı: altın-kahve bordür + gölge
        for sgn in (-1, 1):
            for k_, w_ in ((0, 7), (1, 2)):
                col = (30, 24, 32) if k_ == 0 else trim
                if horiz:
                    y = cy + sgn * (rw / 2) + (0 if k_ == 0 else -sgn * 3)
                    pygame.draw.line(surf, col, (0, y), (cx - R * 1.24, y), w_)
                    pygame.draw.line(surf, col, (cx + R * 1.24, y), (W, y), w_)
                else:
                    x = cx + sgn * (rw / 2) + (0 if k_ == 0 else -sgn * 3)
                    pygame.draw.line(surf, col, (x, 0), (x, cy - R * 1.24), w_)
                    pygame.draw.line(surf, col, (x, cy + R * 1.24), (x, H), w_)
        # yolun ortasında aralıklı mühür taşları
        for d in range(int(R * 1.6), int(length * 0.5), 260):
            for sgn in (-1, 1):
                px_, py_ = (cx + d * sgn, cy) if horiz else (cx, cy + d * sgn)
                if 40 < px_ < W - 40 and 40 < py_ < H - 40:
                    pts = [(px_, py_ - 22), (px_ + 22, py_), (px_, py_ + 22), (px_ - 22, py_)]
                    pygame.draw.polygon(surf, (36, 30, 40), [(x, y + 3) for x, y in pts])
                    pygame.draw.polygon(surf, (112, 96, 82), pts)
                    pygame.draw.polygon(surf, trim, pts, 2)
                    circle_aa(surf, px_, py_, 6, (120, 160, 255))

    # ---- güneş mozaiği: mührü çeviren renkli taş kuşak ----
    cols = ((124, 58, 50), (164, 128, 70), (52, 96, 104), (164, 128, 70))
    r0, r1 = R * 1.06, R * 1.24
    nseg = 64
    for i in range(nseg):
        a0 = i * math.tau / nseg + 0.006
        a1 = (i + 1) * math.tau / nseg - 0.006
        pts = [(cx + math.cos(a0) * r0, cy + math.sin(a0) * r0),
               (cx + math.cos(a0) * r1, cy + math.sin(a0) * r1),
               (cx + math.cos(a1) * r1, cy + math.sin(a1) * r1),
               (cx + math.cos(a1) * r0, cy + math.sin(a1) * r0)]
        col = scale_col(cols[i % 4], rnd.uniform(0.80, 1.0))
        pygame.draw.polygon(surf, col, pts)
        pygame.draw.polygon(surf, scale_col(col, 0.55), pts, 1)
    ring_aa(surf, cx, cy, r1 + 3, trim, 3)
    ring_aa(surf, cx, cy, r0 - 2, scale_col(trim, 0.7), 2)
    # dört yönde altın ok uçları (yollar mühre bağlanır)
    for i in range(4):
        a = i * math.pi / 2
        tip = (cx + math.cos(a) * (r1 + 46), cy + math.sin(a) * (r1 + 46))
        bl = (cx + math.cos(a - 0.10) * (r1 + 6), cy + math.sin(a - 0.10) * (r1 + 6))
        br = (cx + math.cos(a + 0.10) * (r1 + 6), cy + math.sin(a + 0.10) * (r1 + 6))
        poly_aa(surf, [tip, bl, br], trim)

    # ---- mangallar ve meşaleler (taban; alevler canlı katmanda) ----
    for (wx, wy, k) in stone_fire_spots():
        x, y = wx - ARENA_RECT.left, wy - ARENA_RECT.top
        blit_disc(surf, x, y, 120 * k, (255, 150, 70), 26)       # sıcak ışık havuzu
        blit_disc(surf, x, y + 5, 26 * k, (0, 0, 0), 90)
        if k >= 1.0:
            for rr, col in ((22, (58, 50, 56)), (18, (96, 84, 88)), (13, (40, 26, 22))):
                pygame.draw.circle(surf, col, (int(x), int(y)), rr)
            pygame.draw.circle(surf, trim, (int(x), int(y)), 22, 2)
            for j in range(5):
                a = j * math.tau / 5 + 0.3
                circle_aa(surf, x + math.cos(a) * 7, y + math.sin(a) * 7, 2.6, (210, 90, 40))
        else:
            pygame.draw.circle(surf, (50, 40, 36), (int(x), int(y)), 9)
            pygame.draw.circle(surf, (110, 82, 50), (int(x), int(y)), 7)
            pygame.draw.circle(surf, (36, 22, 18), (int(x), int(y)), 4)

    # ---- dikilitaşlar: yolların dünya kenarındaki ağızlarında ----
    for (ox, oy) in ((cx, 120), (cx, H - 120), (120, cy), (W - 120, cy)):
        for sgn in (-1, 1):
            if abs(ox - cx) < 1:
                x, y = ox + sgn * (rw / 2 + 70), oy
            else:
                x, y = ox, oy + sgn * (rw / 2 + 70)
            s_ = 34
            blit_disc(surf, x + 6, y + 10, s_ * 1.4, (0, 0, 0), 80)
            base = pygame.Rect(int(x - s_ - 8), int(y - s_ - 8), (s_ + 8) * 2, (s_ + 8) * 2)
            pygame.draw.rect(surf, (50, 44, 56), base, border_radius=4)
            pygame.draw.rect(surf, trim, base, 2, border_radius=4)
            # tepeden bakılan piramit uç: dört yüzü farklı ışıkta
            c = (x, y)
            p1, p2, p3, p4 = (x - s_, y - s_), (x + s_, y - s_), (x + s_, y + s_), (x - s_, y + s_)
            pygame.draw.polygon(surf, (138, 128, 140), (p1, p2, c))
            pygame.draw.polygon(surf, (112, 102, 116), (p2, p3, c))
            pygame.draw.polygon(surf, (70, 62, 76), (p3, p4, c))
            pygame.draw.polygon(surf, (96, 86, 100), (p4, p1, c))
            for a_, b_ in ((p1, p3), (p2, p4)):
                pygame.draw.line(surf, (54, 48, 60), a_, b_, 1)
            circle_aa(surf, x, y, 5, (150, 190, 255))

    # ---- ay ışığı birikintileri ve derz çimeni ----
    for _ in range(_nd(34)):
        x, y = rnd.uniform(80, W - 80), rnd.uniform(80, H - 80)
        if dist(x, y, cx, cy) < R * 1.4 or abs(x - cx) < rw * 0.6 or abs(y - cy) < rw * 0.6:
            continue
        w_, h_ = rnd.uniform(50, 120), rnd.uniform(20, 46)
        rect = pygame.Rect(int(x - w_ / 2), int(y - h_ / 2), int(w_), int(h_))
        pygame.draw.ellipse(surf, (26, 34, 58), rect)
        pygame.draw.ellipse(surf, (44, 60, 96), rect.inflate(-8, -6))
        pygame.draw.line(surf, (150, 180, 240), (rect.x + w_ * 0.28, rect.y + h_ * 0.34),
                         (rect.x + w_ * 0.58, rect.y + h_ * 0.28), 2)
    for _ in range(_nd(520)):
        x, y = rnd.uniform(0, W), rnd.uniform(0, H)
        if dist(x, y, cx, cy) < R * 1.3:
            continue
        col = scale_col((86, 140, 92), rnd.uniform(0.6, 1.15))
        for sgn in (-1, 0, 1):
            pygame.draw.line(surf, col, (x, y), (x + sgn * rnd.uniform(2, 5), y - rnd.uniform(4, 9)), 1)


_FLAME_FRAMES = {}
FLAME_NFRAMES = 10


def _flame_frame(k, i):
    """telefon: hazır alev karesi (k = boy, i = kare)."""
    key = (k, i)
    img = _FLAME_FRAMES.get(key)
    if img is None:
        global _GLOW_ON_ALPHA
        W, H = int(60 * k + 20), int(110 * k + 30)
        img = pygame.Surface((W, H), pygame.SRCALPHA)
        x, y = W / 2, H - 14
        tt = i / FLAME_NFRAMES * (math.tau / 1.6)
        _GLOW_ON_ALPHA = True
        try:
            _draw_one_fire(img, x, y, k, tt, 0.0)
        finally:
            _GLOW_ON_ALPHA = False
        img = mob_rle(img)
        _FLAME_FRAMES[key] = img
    return img


def _draw_one_fire(world, x, y, k, t, seed):
    fl = 0.75 + 0.25 * math.sin(t * 11.0 + seed * 0.013) * math.sin(t * 6.3 + seed * 0.011)
    h = (26 if k >= 1.0 else 16) * fl
    w = (12 if k >= 1.0 else 7)
    for j, (col, sc) in enumerate((((255, 120, 40), 1.0), ((255, 196, 80), 0.68),
                                   ((255, 246, 200), 0.36))):
        sway = math.sin(t * 7.0 + j + seed * 0.02) * 3 * k
        pts = [(x - w * sc, y), (x + sway * 0.4 - w * sc * 0.4, y - h * sc * 0.55),
               (x + sway, y - h * sc), (x + sway * 0.4 + w * sc * 0.4, y - h * sc * 0.55),
               (x + w * sc, y)]
        poly_aa(world, pts, col)
    for j in range(2):
        ph = (t * 1.6 + j * 0.5 + seed * 0.003) % 1.0
        circle_aa(world, x + math.sin(t * 4 + j * 3 + seed) * 6, y - h - ph * 34 * k,
                  1.4 * (1.0 - ph) + 0.5, (255, 210, 120))


def _draw_stone_fires(world, cam, t):
    """Taş Meydan mangal ve meşale alevleri (yalnız görünenler)."""
    if MOBILE:
        for (x, y, k) in stone_fire_spots():
            if not cam.inflate(80, 80).collidepoint(x, y):
                continue
            fl = 0.75 + 0.25 * math.sin(t * 11.0 + x * 0.013) * math.sin(t * 6.3 + y * 0.011)
            add_glow(world, x, y - 6 * k, 56 * k * fl, (255, 150, 60), 0.34)
            img = _flame_frame(k, int(t * 12 + x * 0.37) % FLAME_NFRAMES)
            world.blit(img, (int(x - img.get_width() / 2), int(y - img.get_height() + 14)))
        return
    for (x, y, k) in stone_fire_spots():
        if not cam.inflate(80, 80).collidepoint(x, y):
            continue
        fl = 0.75 + 0.25 * math.sin(t * 11.0 + x * 0.013) * math.sin(t * 6.3 + y * 0.011)
        add_glow(world, x, y - 6 * k, 90 * k * fl, (255, 150, 60), 0.30)
        h = (26 if k >= 1.0 else 16) * fl
        w = (12 if k >= 1.0 else 7)
        for j, (col, sc) in enumerate((((255, 120, 40), 1.0), ((255, 196, 80), 0.68),
                                       ((255, 246, 200), 0.36))):
            sway = math.sin(t * 7.0 + j + x * 0.02) * 3 * k
            pts = [(x - w * sc, y), (x + sway * 0.4 - w * sc * 0.4, y - h * sc * 0.55),
                   (x + sway, y - h * sc), (x + sway * 0.4 + w * sc * 0.4, y - h * sc * 0.55),
                   (x + w * sc, y)]
            poly_aa(world, pts, col)
        for j in range(2):
            ph = (t * 1.6 + j * 0.5 + x * 0.003) % 1.0
            circle_aa(world, x + math.sin(t * 4 + j * 3 + y) * 6, y - h - ph * 34 * k,
                      1.4 * (1.0 - ph) + 0.5, (255, 210, 120))


def _decorate_theme_floor(surf, key, st, rnd):
    """Haritaya özel ek süslemeler (taş döşemenin üstüne, bir kez çizilir)."""
    W, H = ARENA_RECT.w, ARENA_RECT.h
    if key == "frost":
        # kar birikintileri + donmuş su birikintileri + buz çatlakları
        for _ in range(_nd(240)):
            cx, cy = rnd.uniform(0, W), rnd.uniform(0, H)
            blit_disc(surf, cx, cy, rnd.uniform(14, 60), (226, 238, 252), int(rnd.uniform(16, 44)))
        for _ in range(_nd(26)):
            cx, cy = rnd.uniform(80, W - 80), rnd.uniform(80, H - 80)
            rw, rh = rnd.uniform(60, 150), rnd.uniform(26, 60)
            rect = pygame.Rect(int(cx - rw / 2), int(cy - rh / 2), int(rw), int(rh))
            pygame.draw.ellipse(surf, (120, 168, 210), rect)
            pygame.draw.ellipse(surf, (160, 206, 240), rect.inflate(-10, -8))
            pygame.draw.ellipse(surf, (215, 240, 255), rect, 2)
            pygame.draw.line(surf, (240, 250, 255), (rect.x + rw * 0.25, rect.y + rh * 0.35),
                             (rect.x + rw * 0.55, rect.y + rh * 0.30), 2)
        for _ in range(_nd(70)):
            x0, y0 = rnd.uniform(0, W), rnd.uniform(0, H)
            a = rnd.uniform(0, math.tau)
            pts = [(x0, y0)]
            for _s in range(rnd.randint(3, 6)):
                a += rnd.uniform(-0.7, 0.7)
                x0 += math.cos(a) * rnd.uniform(14, 34)
                y0 += math.sin(a) * rnd.uniform(14, 34)
                pts.append((x0, y0))
            pygame.draw.lines(surf, (190, 230, 255), False, pts, 1)
    elif key == "jungle":
        # kökler, yaprak öbekleri, çimen tutamları ve küçük çiçekler
        for _ in range(_nd(60)):
            x0, y0 = rnd.uniform(0, W), rnd.uniform(0, H)
            a = rnd.uniform(0, math.tau)
            pts = [(x0, y0)]
            for _s in range(rnd.randint(4, 8)):
                a += rnd.uniform(-0.6, 0.6)
                x0 += math.cos(a) * rnd.uniform(18, 40)
                y0 += math.sin(a) * rnd.uniform(18, 40)
                pts.append((x0, y0))
            pygame.draw.lines(surf, (40, 30, 20), False, pts, 6)
            pygame.draw.lines(surf, (84, 62, 38), False, pts, 3)
        for _ in range(_nd(170)):
            cx, cy = rnd.uniform(0, W), rnd.uniform(0, H)
            for _l in range(rnd.randint(3, 6)):
                a = rnd.uniform(0, math.tau)
                d = rnd.uniform(0, 16)
                lx, ly = cx + math.cos(a) * d, cy + math.sin(a) * d * 0.7
                lw = rnd.uniform(7, 13)
                pygame.draw.ellipse(surf, scale_col((70, 150, 70), rnd.uniform(0.6, 1.2)),
                                    pygame.Rect(int(lx - lw), int(ly - lw * 0.45), int(lw * 2), int(lw * 0.9)))
        for _ in range(_nd(420)):
            cx, cy = rnd.uniform(0, W), rnd.uniform(0, H)
            col = scale_col((96, 190, 90), rnd.uniform(0.6, 1.25))
            for sgn in (-1, 0, 1):
                pygame.draw.line(surf, col, (cx, cy), (cx + sgn * rnd.uniform(3, 6), cy - rnd.uniform(6, 12)), 2)
        for _ in range(_nd(160)):
            cx, cy = rnd.uniform(0, W), rnd.uniform(0, H)
            col = rnd.choice(((255, 120, 160), (255, 230, 120), (190, 150, 255), (255, 255, 255)))
            for i in range(5):
                a = i * math.tau / 5
                pygame.draw.circle(surf, col, (int(cx + math.cos(a) * 3), int(cy + math.sin(a) * 3)), 2)
            pygame.draw.circle(surf, (255, 220, 90), (int(cx), int(cy)), 2)
    elif key == "desert":
        # kum dalgaları, kayalar, kaktüsler, ağarmış kemikler
        for _ in range(_nd(220)):
            x0, y0 = rnd.uniform(-40, W), rnd.uniform(0, H)
            ln = rnd.uniform(60, 180)
            amp = rnd.uniform(3, 7)
            pts = [(x0 + i * ln / 10.0, y0 + math.sin(i * 0.9) * amp) for i in range(11)]
            pygame.draw.lines(surf, scale_col((210, 168, 108), rnd.uniform(0.7, 1.05)), False, pts, 2)
        for _ in range(_nd(60)):
            cx, cy = rnd.uniform(40, W - 40), rnd.uniform(40, H - 40)
            hgt = rnd.uniform(26, 46)
            blit_disc(surf, cx + 6, cy + 4, hgt * 0.5, (0, 0, 0), 60)
            pygame.draw.rect(surf, (52, 110, 62), pygame.Rect(int(cx - 6), int(cy - hgt), 12, int(hgt)),
                             border_radius=6)
            for sgn in (-1, 1):
                ay = cy - hgt * rnd.uniform(0.45, 0.7)
                pygame.draw.rect(surf, (52, 110, 62), pygame.Rect(int(cx + sgn * 6 - (10 if sgn < 0 else 0)),
                                                                  int(ay), 10, 6), border_radius=3)
                pygame.draw.rect(surf, (52, 110, 62), pygame.Rect(int(cx + sgn * 13 - 3), int(ay - 12), 7, 16),
                                 border_radius=3)
            pygame.draw.line(surf, (96, 160, 100), (cx - 2, cy - hgt + 4), (cx - 2, cy - 4), 2)
        for _ in range(_nd(55)):
            cx, cy = rnd.uniform(20, W - 20), rnd.uniform(20, H - 20)
            pygame.draw.ellipse(surf, (222, 212, 190), pygame.Rect(int(cx - 9), int(cy - 7), 18, 14))
            pygame.draw.circle(surf, (60, 46, 36), (int(cx - 3), int(cy - 1)), 2)
            pygame.draw.circle(surf, (60, 46, 36), (int(cx + 3), int(cy - 1)), 2)
            a = rnd.uniform(0, math.tau)
            pygame.draw.line(surf, (222, 212, 190), (cx + 14, cy + 6),
                             (cx + 14 + math.cos(a) * 18, cy + 6 + math.sin(a) * 10), 3)


def _decorate_hell_floor(surf, st, rnd):
    """Cehennem zeminini boyar: lav çatlakları, magma gölleri, obsidyen kayalar."""
    lava, hot = st["lava"], st["lava_hot"]
    rock, ash = st["rock"], st["ash"]
    W, H = ARENA_RECT.w, ARENA_RECT.h

    # ---- yanık kömür lekeleri (zemine derinlik verir) ----
    for _ in range(_nd(260)):
        cx, cy = rnd.uniform(0, W), rnd.uniform(0, H)
        blit_disc(surf, cx, cy, rnd.uniform(18, 70), (10, 4, 6), int(rnd.uniform(18, 46)))

    # ---- magma gölleri: dış hâle + akkor göbek + kabuk kenarı ----
    for _ in range(_nd(18)):
        cx, cy = rnd.uniform(60, W - 60), rnd.uniform(60, H - 60)
        rad = rnd.uniform(44, 112)
        pts = []
        n = rnd.randint(8, 12)
        for i in range(n):
            a = i * math.tau / n
            rr = rad * rnd.uniform(0.72, 1.18)
            pts.append((cx + math.cos(a) * rr, cy + math.sin(a) * rr * 0.72))
        add_glow(surf, cx, cy, rad * 1.4, lava, 0.22)
        # koyu çukur -> soğumuş kabuk -> ergimiş göbek (üç katman)
        pygame.draw.polygon(surf, (24, 9, 10), [(px, py + 4) for px, py in pts])
        pygame.draw.polygon(surf, (56, 24, 20), pts)
        pygame.draw.polygon(surf, scale_col(lava, 0.68),
                            [(cx + (px - cx) * 0.78, cy + (py - cy) * 0.78) for px, py in pts])
        pygame.draw.polygon(surf, scale_col(hot, 0.78),
                            [(cx + (px - cx) * 0.34, cy + (py - cy) * 0.34) for px, py in pts])
        # kabuk üstünde soğumuş siyah adacıklar
        for _isl in range(rnd.randint(2, 4)):
            ia = rnd.uniform(0, math.tau)
            ir = rad * rnd.uniform(0.15, 0.55)
            blit_disc(surf, cx + math.cos(ia) * ir, cy + math.sin(ia) * ir * 0.7,
                      rnd.uniform(6, 16), (26, 12, 14), 230)
        pygame.draw.polygon(surf, (48, 20, 18), pts, 3)

    # ---- lav çatlakları: dallanan, akkor damarlar ----
    for _ in range(_nd(58)):
        x0, y0 = rnd.uniform(0, W), rnd.uniform(0, H)
        ang = rnd.uniform(0, math.tau)
        for _branch in range(rnd.randint(1, 3)):
            bx, by, ba = x0, y0, ang + rnd.uniform(-0.9, 0.9)
            pts = [(bx, by)]
            for _seg in range(rnd.randint(4, 9)):
                ba += rnd.uniform(-0.55, 0.55)
                step = rnd.uniform(22, 54)
                bx += math.cos(ba) * step
                by += math.sin(ba) * step
                pts.append((bx, by))
            if len(pts) < 2:
                continue
            pygame.draw.lines(surf, (22, 8, 9), False, pts, 6)
            pygame.draw.lines(surf, scale_col(lava, 0.58), False, pts, 3)
            pygame.draw.lines(surf, scale_col(hot, 0.80), False, pts, 1)

    # ---- obsidyen kayalar ve kemik parçaları ----
    for _ in range(_nd(150)):
        cx, cy = rnd.uniform(20, W - 20), rnd.uniform(20, H - 20)
        rad = rnd.uniform(9, 26)
        pts = []
        n = rnd.randint(5, 7)
        for i in range(n):
            a = i * math.tau / n + rnd.uniform(-0.2, 0.2)
            rr = rad * rnd.uniform(0.7, 1.25)
            pts.append((cx + math.cos(a) * rr, cy + math.sin(a) * rr * 0.8))
        pygame.draw.polygon(surf, (12, 6, 9), [(px + 3, py + 4) for px, py in pts])
        pygame.draw.polygon(surf, rock, pts)
        pygame.draw.polygon(surf, ash, pts, 1)
    for _ in range(_nd(70)):
        cx, cy = rnd.uniform(20, W - 20), rnd.uniform(20, H - 20)
        a = rnd.uniform(0, math.tau)
        ln = rnd.uniform(14, 30)
        p0 = (cx - math.cos(a) * ln, cy - math.sin(a) * ln * 0.7)
        p1 = (cx + math.cos(a) * ln, cy + math.sin(a) * ln * 0.7)
        pygame.draw.line(surf, (186, 176, 158), p0, p1, 3)
        pygame.draw.circle(surf, (196, 186, 168), (int(p0[0]), int(p0[1])), 3)
        pygame.draw.circle(surf, (196, 186, 168), (int(p1[0]), int(p1[1])), 3)


# ---- doğal zemin + harita simge yapıları ----
# haritalar baştan sona aynı taş fayanstan ibaretti; orman bile taş döşemeydi.
# buzul / orman / çöl'de zemin doğal (kar, çim-toprak, kum lekeleri); taş
# döşeme yalnız ortadaki meydanda ve oradan dünyanın kenarlarına kıvrılarak
# giden yollarda kalır.
TERRAIN_STYLE = {
    "frost": dict(g=[(54, 66, 90), (70, 86, 114), (96, 116, 146)], speck=(170, 196, 226)),
    "jungle": dict(g=[(30, 50, 32), (40, 68, 40), (56, 46, 30)], speck=(70, 120, 60)),
    "desert": dict(g=[(104, 76, 48), (128, 96, 62), (86, 62, 40)], speck=(160, 126, 84)),
}
TERRAIN_PLAZA_R = 980          # meydanın taş döşemeli yarıçapı
TERRAIN_ROAD_W = 118           # yol yarı genişliği


def _soft_blob_maker():
    cache = {}

    def blob(surf, x, y, r, col, alpha):
        rq = max(16, int(r) // 24 * 24)
        aq = max(8, int(alpha) // 12 * 12)
        key = (rq, col, aq)
        sp = cache.get(key)
        if sp is None:
            sp = pygame.Surface((rq * 2, rq * 2), pygame.SRCALPHA)
            for i in range(8, 0, -1):
                k = i / 8.0
                pygame.draw.circle(sp, (col[0], col[1], col[2], int(aq * (1.0 - k) ** 0.8 + aq * 0.15)),
                                   (rq, rq), int(rq * k))
            cache[key] = sp
        surf.blit(sp, (int(x - rq), int(y - rq)))
    return blob, cache


def _road_offset(along, seed):
    return math.sin(along * 0.0013 + seed) * 150 + math.sin(along * 0.0037 + seed * 2.1) * 55


def terrain_tile_weight(st, x, y, W, H):
    """Bu noktada taş döşeme olsun mu (0..1)?"""
    if not st.get("terrain"):
        return 1.0
    cx, cy = W * 0.5, H * 0.5
    d = math.hypot(x - cx, y - cy)
    w = clamp((TERRAIN_PLAZA_R - d) / 260.0, 0.0, 1.0)
    ry = cy + _road_offset(x, 1.3)
    rx = cx + _road_offset(y, 2.7)
    w = max(w, clamp((TERRAIN_ROAD_W - abs(y - ry)) / 60.0 + 0.4, 0.0, 1.0),
            clamp((TERRAIN_ROAD_W - abs(x - rx)) / 60.0 + 0.4, 0.0, 1.0))
    return w


def _paint_terrain(surf, key, st, rnd):
    """Doğal zemin: büyük yumuşak lekeler + benekler (taş döşemeden önce)."""
    ts = TERRAIN_STYLE.get(key)
    if ts is None:
        return
    W, H = ARENA_RECT.w, ARENA_RECT.h
    surf.fill(ts["g"][0])
    blob, cache = _soft_blob_maker()
    for _ in range(_nd(260)):
        blob(surf, rnd.uniform(0, W), rnd.uniform(0, H), rnd.uniform(120, 300),
             rnd.choice(ts["g"][1:]), rnd.uniform(40, 90))
    for _ in range(_nd(420)):
        blob(surf, rnd.uniform(0, W), rnd.uniform(0, H), rnd.uniform(30, 90),
             rnd.choice(ts["g"]), rnd.uniform(40, 90))
    sp = ts["speck"]
    for _ in range(_nd(5200)):
        x, y = rnd.uniform(0, W), rnd.uniform(0, H)
        c = scale_col(sp, rnd.uniform(0.55, 1.05))
        pygame.draw.circle(surf, c, (int(x), int(y)), rnd.choice((1, 1, 2)))
    cache.clear()


def _far_from_center(rnd, W, H, min_d=900, pad=80):
    for _ in range(20):
        x, y = rnd.uniform(pad, W - pad), rnd.uniform(pad, H - pad)
        if math.hypot(x - W * 0.5, y - H * 0.5) >= min_d:
            return x, y
    return rnd.uniform(pad, W - pad), rnd.uniform(pad, H - pad)


def _off_road(st, rnd, W, H, min_d=900, tries=12):
    """Yola ve meydana denk gelmeyen bir nokta (yapılar yolu kapatmasın)."""
    x, y = _far_from_center(rnd, W, H, min_d)
    for _ in range(tries):
        if terrain_tile_weight(st, x, y, W, H) < 0.05:
            return x, y
        x, y = _far_from_center(rnd, W, H, min_d)
    return x, y


def _star_poly(cx, cy, n, r1, r2, rot=0.0):
    pts = []
    for i in range(n * 2):
        a = rot + i * math.pi / n
        rr = r1 if i % 2 == 0 else r2
        pts.append((cx + math.cos(a) * rr, cy + math.sin(a) * rr))
    return pts


def _ground_shadow(surf, x, y, rx, ry, alpha=70):
    s = pygame.Surface((int(rx * 2) + 2, int(ry * 2) + 2), pygame.SRCALPHA)
    pygame.draw.ellipse(s, (0, 0, 0, alpha), s.get_rect())
    surf.blit(s, (int(x - rx), int(y - ry)))


def _lake(surf, rnd, x, y, size, deep, mid, rim, ice=False):
    pts = []
    n = 14
    for i in range(n):
        a = i * math.tau / n
        rr = size * rnd.uniform(0.75, 1.15)
        pts.append((x + math.cos(a) * rr * 1.5, y + math.sin(a) * rr))
    pygame.draw.polygon(surf, scale_col(rim, 0.6), [(px, py + 5) for px, py in pts])
    pygame.draw.polygon(surf, rim, pts)
    inner = [(x + (px - x) * 0.86, y + (py - y) * 0.86) for px, py in pts]
    pygame.draw.polygon(surf, deep, inner)
    core = [(x + (px - x) * 0.58 - size * 0.12, y + (py - y) * 0.58 - size * 0.08) for px, py in pts]
    pygame.draw.polygon(surf, mid, core)
    if ice:
        for _ in range(7):
            a = rnd.uniform(0, math.tau)
            x0, y0 = x + math.cos(a) * size * 0.3, y + math.sin(a) * size * 0.2
            pl = [(x0, y0)]
            for _s in range(4):
                a += rnd.uniform(-0.8, 0.8)
                x0 += math.cos(a) * size * 0.22
                y0 += math.sin(a) * size * 0.15
                pl.append((x0, y0))
            pygame.draw.lines(surf, (220, 240, 255), False, pl, 1)
        pygame.draw.line(surf, (240, 250, 255), (x - size * 0.7, y - size * 0.35),
                         (x - size * 0.2, y - size * 0.5), 3)
    else:
        for _ in range(3):
            a = rnd.uniform(0, math.tau)
            rr = rnd.uniform(0.2, 0.6) * size
            ring_aa(surf, x + math.cos(a) * rr, y + math.sin(a) * rr * 0.6, size * 0.12,
                    lighten(mid, 0.3), 1)


def _decorate_terrain_landmarks(surf, key, st, rnd):
    """Haritanın simge yapıları."""
    W, H = ARENA_RECT.w, ARENA_RECT.h
    if key == "frost":
        blob, cache = _soft_blob_maker()
        for _ in range(_nd(150)):                                  # kar yığıntıları
            blob(surf, rnd.uniform(0, W), rnd.uniform(0, H), rnd.uniform(40, 120),
                 (210, 226, 244), rnd.uniform(40, 80))
        cache.clear()
        for _ in range(_nd(9)):                                    # donmuş göller
            x, y = _off_road(st, rnd, W, H, 1000)
            _lake(surf, rnd, x, y, rnd.uniform(90, 170), (96, 150, 200), (150, 200, 236),
                  (214, 232, 248), ice=True)
        for _ in range(_nd(26)):                                   # buz kristali kümeleri
            x, y = _off_road(st, rnd, W, H, 950)
            for j in range(rnd.randint(3, 6)):
                a = -math.pi / 2 + rnd.uniform(-0.9, 0.9)
                ln = rnd.uniform(26, 60)
                bx, by = x + rnd.uniform(-18, 18), y + rnd.uniform(-8, 8)
                tip = (bx + math.cos(a) * ln, by + math.sin(a) * ln)
                b0 = (bx - math.sin(a) * 7, by + math.cos(a) * 7)
                b1 = (bx + math.sin(a) * 7, by - math.cos(a) * 7)
                pygame.draw.polygon(surf, OUTLINE, [b0, tip, b1], 3)
                pygame.draw.polygon(surf, (170, 220, 250) if j % 2 else (210, 240, 255), [b0, tip, b1])
                pygame.draw.line(surf, WHITE, (bx, by), tip, 1)
        for _ in range(_nd(60)):                                   # karlı çamlar
            x, y = _off_road(st, rnd, W, H, 1000)
            s = rnd.uniform(34, 62)
            _ground_shadow(surf, x + s * 0.35, y + s * 0.55, s * 1.0, s * 0.45, 80)
            rot = rnd.uniform(0, math.tau)
            for k, (rk, c) in enumerate(((1.0, (30, 66, 60)), (0.74, (40, 86, 74)), (0.48, (56, 110, 92)))):
                pts = _star_poly(x, y - k * s * 0.12, 8, s * rk, s * rk * 0.62, rot + k * 0.3)
                pygame.draw.polygon(surf, OUTLINE, pts, 2)
                pygame.draw.polygon(surf, c, pts)
                snow = [(px, py) for i, (px, py) in enumerate(pts) if i % 4 in (0, 1)]
                for px, py in snow[:4]:
                    pygame.draw.circle(surf, (236, 244, 255), (int(px + (x - px) * 0.2), int(py + (y - py) * 0.2)), 3)
            pygame.draw.circle(surf, (236, 244, 255), (int(x), int(y - s * 0.3)), max(2, int(s * 0.10)))
        for _ in range(_nd(40)):                                   # karlı kayalar
            x, y = _off_road(st, rnd, W, H, 950)
            s = rnd.uniform(18, 34)
            _ground_shadow(surf, x + 4, y + s * 0.5, s * 1.1, s * 0.4, 70)
            pts = [(x + math.cos(a) * s * rnd.uniform(0.8, 1.1), y + math.sin(a) * s * 0.7)
                   for a in [i * math.tau / 7 for i in range(7)]]
            pygame.draw.polygon(surf, (70, 80, 100), pts)
            pygame.draw.polygon(surf, (236, 244, 255), pts[3:6] + [(x, y - s * 0.2)])
            pygame.draw.polygon(surf, OUTLINE, pts, 2)
    elif key == "jungle":
        blob, cache = _soft_blob_maker()
        for _ in range(_nd(90)):                                   # toprak açıklıkları
            blob(surf, rnd.uniform(0, W), rnd.uniform(0, H), rnd.uniform(60, 140),
                 (70, 56, 34), rnd.uniform(40, 80))
        for _ in range(_nd(140)):                                  # gür çimen öbekleri
            blob(surf, rnd.uniform(0, W), rnd.uniform(0, H), rnd.uniform(40, 110),
                 (60, 110, 54), rnd.uniform(40, 80))
        cache.clear()
        for _ in range(_nd(11)):                                   # gölcükler + nilüferler
            x, y = _off_road(st, rnd, W, H, 1000)
            sz = rnd.uniform(70, 130)
            _lake(surf, rnd, x, y, sz, (24, 70, 74), (40, 104, 106), (64, 96, 52))
            for _l in range(rnd.randint(3, 6)):
                a = rnd.uniform(0, math.tau)
                rr = rnd.uniform(0.2, 0.75) * sz
                lx, ly = x + math.cos(a) * rr * 1.3, y + math.sin(a) * rr * 0.8
                lr = rnd.uniform(9, 15)
                pygame.draw.circle(surf, (50, 130, 60), (int(lx), int(ly)), int(lr))
                pygame.draw.polygon(surf, (40, 104, 106), [(lx, ly), (lx + lr, ly - lr * 0.4), (lx + lr, ly + lr * 0.4)])
                if rnd.random() < 0.4:
                    for i in range(5):
                        b = i * math.tau / 5
                        pygame.draw.circle(surf, (255, 150, 190), (int(lx + math.cos(b) * 3), int(ly + math.sin(b) * 3)), 2)
        for _ in range(_nd(120)):                                  # çalılar
            x, y = _off_road(st, rnd, W, H, 900, tries=4)
            s = rnd.uniform(14, 26)
            _ground_shadow(surf, x + 3, y + s * 0.5, s * 1.4, s * 0.5, 60)
            for j in range(4):
                a = j * math.tau / 4 + rnd.uniform(-0.4, 0.4)
                c = scale_col((70, 150, 64), rnd.uniform(0.75, 1.15))
                pygame.draw.circle(surf, c, (int(x + math.cos(a) * s * 0.55), int(y + math.sin(a) * s * 0.35)), int(s * 0.62))
            pygame.draw.circle(surf, (120, 196, 90), (int(x - s * 0.2), int(y - s * 0.25)), int(s * 0.30))
        for _ in range(_nd(42)):                                   # dev ağaç tepeleri
            x, y = _off_road(st, rnd, W, H, 1050)
            s = rnd.uniform(60, 110)
            _ground_shadow(surf, x + s * 0.30, y + s * 0.40, s * 1.25, s * 0.85, 90)
            greens = ((34, 84, 40), (48, 110, 50), (66, 140, 62), (90, 170, 76))
            for k in range(4):
                for j in range(6 - k):
                    a = j * math.tau / (6 - k) + k * 0.5 + rnd.uniform(-0.2, 0.2)
                    rr = s * (0.55 - k * 0.14)
                    cr = s * (0.52 - k * 0.09)
                    pygame.draw.circle(surf, greens[k], (int(x + math.cos(a) * rr - k * s * 0.06),
                                                         int(y + math.sin(a) * rr - k * s * 0.08)), int(cr))
            for _f in range(rnd.randint(0, 3)):
                a = rnd.uniform(0, math.tau)
                fx_, fy_ = x + math.cos(a) * s * 0.5, y + math.sin(a) * s * 0.4
                pygame.draw.circle(surf, rnd.choice(((255, 120, 160), (255, 220, 110))), (int(fx_), int(fy_)), 4)
        for _ in range(_nd(28)):                                   # mantar halkaları
            x, y = _off_road(st, rnd, W, H, 950)
            for j in range(rnd.randint(4, 7)):
                a = j * math.tau / 7 + rnd.uniform(-0.2, 0.2)
                mx, my = x + math.cos(a) * 26, y + math.sin(a) * 18
                pygame.draw.circle(surf, OUTLINE, (int(mx), int(my)), 7)
                pygame.draw.circle(surf, (210, 60, 60), (int(mx), int(my)), 5)
                pygame.draw.circle(surf, WHITE, (int(mx - 2), int(my - 1)), 1)
        for _ in range(_nd(36)):                                   # yosunlu kayalar
            x, y = _off_road(st, rnd, W, H, 950)
            s = rnd.uniform(16, 30)
            _ground_shadow(surf, x + 4, y + s * 0.45, s * 1.1, s * 0.4, 70)
            pts = [(x + math.cos(a) * s * rnd.uniform(0.8, 1.1), y + math.sin(a) * s * 0.72)
                   for a in [i * math.tau / 7 for i in range(7)]]
            pygame.draw.polygon(surf, (70, 76, 70), pts)
            pygame.draw.polygon(surf, (80, 150, 70), pts[3:6] + [(x, y - s * 0.1)])
            pygame.draw.polygon(surf, OUTLINE, pts, 2)
    elif key == "desert":
        for _ in range(_nd(55)):                                   # kum tepeleri (hilal)
            x, y = _off_road(st, rnd, W, H, 950, tries=4)
            s = rnd.uniform(90, 200)
            a = rnd.uniform(-0.3, 0.3)
            r1 = pygame.Rect(0, 0, int(s * 2), int(s * 0.9))
            r1.center = (int(x), int(y))
            sh = pygame.Surface(r1.size, pygame.SRCALPHA)
            pygame.draw.ellipse(sh, (70, 48, 28, 70), sh.get_rect())
            pygame.draw.ellipse(sh, (0, 0, 0, 0), sh.get_rect().move(0, -int(s * 0.16)))
            surf.blit(sh, r1.topleft)
            lit = pygame.Surface(r1.size, pygame.SRCALPHA)
            pygame.draw.ellipse(lit, (176, 140, 92, 60), lit.get_rect().inflate(-int(s * 0.3), -int(s * 0.25)))
            surf.blit(lit, (r1.x, r1.y - int(s * 0.12)))
            pts = [(x - s * 0.9 + i * s * 0.18, y - s * 0.22 + math.sin(i * 0.7 + a) * 6) for i in range(11)]
            pygame.draw.lines(surf, (190, 156, 106), False, pts, 2)
        for _ in range(_nd(22)):                                   # çatlak toprak
            x, y = _off_road(st, rnd, W, H, 950)
            s = rnd.uniform(70, 130)
            for _c in range(9):
                a = rnd.uniform(0, math.tau)
                x0, y0 = x + math.cos(a) * s * 0.3, y + math.sin(a) * s * 0.2
                pl = [(x0, y0)]
                for _s in range(4):
                    a += rnd.uniform(-0.9, 0.9)
                    x0 += math.cos(a) * s * 0.2
                    y0 += math.sin(a) * s * 0.14
                    pl.append((x0, y0))
                pygame.draw.lines(surf, (70, 48, 30), False, pl, 2)
        for _ in range(_nd(5)):                                    # vahalar
            x, y = _off_road(st, rnd, W, H, 1100)
            sz = rnd.uniform(80, 120)
            blob, cache = _soft_blob_maker()
            blob(surf, x, y, sz * 2.2, (80, 120, 60), 70)
            cache.clear()
            _lake(surf, rnd, x, y, sz, (40, 110, 150), (80, 170, 200), (190, 170, 120))
            for _p in range(rnd.randint(3, 5)):                    # palmiyeler
                a = rnd.uniform(0, math.tau)
                px_, py_ = x + math.cos(a) * sz * 1.7, y + math.sin(a) * sz * 1.1
                _ground_shadow(surf, px_ + 18, py_ + 22, 46, 18, 70)
                for k in range(7):
                    b = k * math.tau / 7 + rnd.uniform(-0.15, 0.15)
                    tip = (px_ + math.cos(b) * 50, py_ + math.sin(b) * 40)
                    mid = (px_ + math.cos(b + 0.25) * 28, py_ + math.sin(b + 0.25) * 22)
                    pygame.draw.polygon(surf, (40, 110, 50), [(px_, py_), mid, tip,
                                                             (px_ + math.cos(b - 0.2) * 26, py_ + math.sin(b - 0.2) * 20)])
                    pygame.draw.line(surf, (90, 160, 80), (px_, py_), tip, 1)
                pygame.draw.circle(surf, (120, 86, 50), (int(px_), int(py_)), 6)
        for _ in range(_nd(14)):                                   # devrik dikilitaşlar
            x, y = _off_road(st, rnd, W, H, 1000)
            ln, wd = rnd.uniform(120, 190), rnd.uniform(26, 34)
            a = rnd.uniform(0, math.pi)
            ca, sa = math.cos(a), math.sin(a)
            pts = [(x - ca * ln / 2 - sa * wd / 2, y - sa * ln / 2 + ca * wd / 2),
                   (x + ca * ln / 2 - sa * wd / 2, y + sa * ln / 2 + ca * wd / 2),
                   (x + ca * (ln / 2 + 22), y + sa * (ln / 2 + 22)),
                   (x + ca * ln / 2 + sa * wd / 2, y + sa * ln / 2 - ca * wd / 2),
                   (x - ca * ln / 2 + sa * wd / 2, y - sa * ln / 2 - ca * wd / 2)]
            pygame.draw.polygon(surf, (60, 40, 26), [(px, py + 8) for px, py in pts])
            pygame.draw.polygon(surf, (176, 146, 104), pts)
            pygame.draw.polygon(surf, OUTLINE, pts, 2)
            for k in range(5):
                gx = x - ca * ln * 0.35 + ca * k * ln * 0.16
                gy = y - sa * ln * 0.35 + sa * k * ln * 0.16
                pygame.draw.circle(surf, (110, 84, 56), (int(gx), int(gy)), 4, 1)
        for _ in range(_nd(55)):                                   # kayalar
            x, y = _off_road(st, rnd, W, H, 950, tries=4)
            s = rnd.uniform(14, 30)
            _ground_shadow(surf, x + 5, y + s * 0.5, s * 1.2, s * 0.42, 80)
            pts = [(x + math.cos(a) * s * rnd.uniform(0.75, 1.1), y + math.sin(a) * s * 0.7)
                   for a in [i * math.tau / 7 for i in range(7)]]
            pygame.draw.polygon(surf, (132, 100, 70), pts)
            pygame.draw.polygon(surf, (168, 134, 96), pts[4:7] + [(x, y)])
            pygame.draw.polygon(surf, OUTLINE, pts, 2)
    elif key == "arena":
        blob, cache = _soft_blob_maker()
        for _ in range(_nd(70)):                                   # yosun halıları (dış halka)
            x, y = _far_from_center(rnd, W, H, 1300)
            blob(surf, x, y, rnd.uniform(60, 160), (50, 96, 76), rnd.uniform(40, 70))
        cache.clear()
        for _ in range(_nd(8)):                                    # yıkık sütun çemberleri
            x, y = _far_from_center(rnd, W, H, 1500, 260)
            R = rnd.uniform(130, 190)
            ring_aa(surf, x, y, R + 26, (60, 64, 92), 3)
            n = rnd.randint(6, 9)
            for i in range(n):
                a = i * math.tau / n + rnd.uniform(-0.1, 0.1)
                px_, py_ = x + math.cos(a) * R, y + math.sin(a) * R
                if rnd.random() < 0.35:                            # devrilmiş sütun
                    b = rnd.uniform(0, math.tau)
                    e = (px_ + math.cos(b) * 70, py_ + math.sin(b) * 70)
                    pygame.draw.line(surf, (20, 22, 34), (px_, py_ + 6), (e[0], e[1] + 6), 22)
                    pygame.draw.line(surf, (96, 100, 132), (px_, py_), e, 18)
                    pygame.draw.line(surf, (130, 136, 170), (px_, py_ - 5), (e[0], e[1] - 5), 3)
                    continue
                _ground_shadow(surf, px_ + 10, py_ + 14, 26, 12, 90)
                pygame.draw.circle(surf, (30, 32, 48), (int(px_), int(py_ + 4)), 22)
                pygame.draw.circle(surf, (104, 110, 146), (int(px_), int(py_)), 20)
                pygame.draw.circle(surf, (136, 142, 180), (int(px_ - 5), int(py_ - 5)), 9)
                pygame.draw.circle(surf, OUTLINE, (int(px_), int(py_)), 20, 2)
            pygame.draw.circle(surf, (96, 130, 220), (int(x), int(y)), 10)
            ring_aa(surf, x, y, 30, (118, 158, 255), 2)


def _build_floor(biome):
    """Bütün dünyanın zeminini bir kez çizip saklar."""
    st = BIOME_STYLE.get(biome, BIOME_STYLE["arena"])
    surf = pygame.Surface((ARENA_RECT.w, ARENA_RECT.h)).convert()

    # ---- dikey degrade ----
    for y in range(ARENA_RECT.h):
        k = y / max(1, ARENA_RECT.h - 1)
        col = (int(lerp(st["top"][0], st["bottom"][0], k)),
               int(lerp(st["top"][1], st["bottom"][1], k)),
               int(lerp(st["top"][2], st["bottom"][2], k)))
        pygame.draw.line(surf, col, (0, y), (ARENA_RECT.w, y))

    # ---- zemin lekeleri ----
    # arena'da taş döşeme zaten doku veriyor; lekeler orada yalnızca hafif bir
    # renk oynaması olarak kalsın (yoksa döşemeyi bulandırıyor).
    rnd = random.Random(sum(ord(c) for c in biome) * 7919)
    if st.get("terrain"):
        _paint_terrain(surf, biome, st, rnd)     # doğal zemin (kar / çim / kum)
    n_decal, a_lo, a_hi = (420, 10, 30) if biome == "hell" else (180, 6, 16)
    n_decal = _nd(n_decal)
    for _ in range(n_decal):
        dx = rnd.uniform(0, ARENA_RECT.w)
        dy = rnd.uniform(0, ARENA_RECT.h)
        dr = rnd.uniform(8, 44)
        blit_disc(surf, dx, dy, dr, st["decal"], int(rnd.uniform(a_lo, a_hi)))

    # ---- bölgeye özel zemin süslemeleri ----
    if biome == "hell":
        _decorate_hell_floor(surf, st, rnd)   # lav, magma gölü, obsidyen
    else:
        _decorate_arena_floor(surf, st, rnd)  # taş döşeme, mühür, kristal
        if biome == "arena":
            _decorate_stone_plaza(surf, st, rnd)    # Taş Meydan süsleri
        if biome != "arena":
            _decorate_theme_floor(surf, biome, st, rnd)   # harita süsleri
        _decorate_terrain_landmarks(surf, biome, st, rnd)  # simge yapılar

    # ---- ince ızgara + hücre sınırları ----
    # dünya 5x5 olunca dünya boyu saydam katman (~80 MB) çok pahalıydı;
    # çizgiler çizgi boyu küçük saydam şeritlerle basılıyor (aynı görüntü).
    def _aline(col, vertical, pos, w=1):
        if len(col) < 4 or col[3] >= 255:
            if vertical:
                pygame.draw.line(surf, col[:3], (pos, 0), (pos, ARENA_RECT.h), w)
            else:
                pygame.draw.line(surf, col[:3], (0, pos), (ARENA_RECT.w, pos), w)
            return
        key = (tuple(col), vertical, w)
        strip = _GRID_STRIPS.get(key)
        if strip is None:
            size = (w, ARENA_RECT.h) if vertical else (ARENA_RECT.w, w)
            strip = pygame.Surface(size, pygame.SRCALPHA)
            strip.fill(tuple(col))
            _GRID_STRIPS[key] = strip
        surf.blit(strip, (pos - w // 2, 0) if vertical else (0, pos - w // 2))
    _GRID_STRIPS = {}
    step = 64
    for x in range(0, ARENA_RECT.w + 1, step):
        _aline(st["grid"], True, x)
    for y in range(0, ARENA_RECT.h + 1, step):
        _aline(st["grid"], False, y)
    for i in range(1, WORLD_TILES_X):
        _aline(st["cell"], True, BASE_VIEW_W * i, 3)
    for j in range(1, WORLD_TILES_Y):
        _aline(st["cell"], False, BASE_VIEW_H * j, 3)
    _GRID_STRIPS.clear()

    # ---- çıkılmaz dünya duvarı ----
    # İçeriye doğru bir bant: koyu dolgu + eğik uyarı şeritleri + parlak kenar.
    # Oyuncu dünyanın bittiği yeri bir bakışta görsün.
    band = 20
    wcol = st["wall"]
    # dünya boyu saydam katman yerine yalnız kenar şeritleri (bellek)
    wall = _EdgeCanvas(ARENA_RECT.w, ARENA_RECT.h, band + 4, 92)
    edges = [pygame.Rect(0, 0, ARENA_RECT.w, band),
             pygame.Rect(0, ARENA_RECT.h - band, ARENA_RECT.w, band),
             pygame.Rect(0, 0, band, ARENA_RECT.h),
             pygame.Rect(ARENA_RECT.w - band, 0, band, ARENA_RECT.h)]
    for r in edges:
        wall.rect((*scale_col(wcol, 0.22), 235), r)
    # eğik şeritler
    stripe = (*scale_col(wcol, 0.55), 90)
    for r in edges:
        cl = wall.get_clip()
        wall.set_clip(r)
        x = r.left - r.height
        while x < r.right + r.height:
            wall.line(stripe, (x, r.bottom), (x + r.height, r.top), 6)
            x += 26
        wall.set_clip(cl)
    # parlak iç kenar + en dış çizgi
    wall.rect((*wcol, 255), pygame.Rect(0, 0, ARENA_RECT.w, ARENA_RECT.h), width=3)
    wall.rect((*lighten(wcol, 0.25), 200),
                     pygame.Rect(band, band, ARENA_RECT.w - band * 2, ARENA_RECT.h - band * 2),
                     width=2)
    # köşe köşebentleri
    L = 90
    for (cx, cy, dx, dy) in ((0, 0, 1, 1), (ARENA_RECT.w, 0, -1, 1),
                             (0, ARENA_RECT.h, 1, -1), (ARENA_RECT.w, ARENA_RECT.h, -1, -1)):
        wall.line((*lighten(wcol, 0.5), 230), (cx, cy + dy * 2),
                         (cx + dx * L, cy + dy * 2), 5)
        wall.line((*lighten(wcol, 0.5), 230), (cx + dx * 2, cy),
                         (cx + dx * 2, cy + dy * L), 5)
    wall.blit_to(surf)
    return surf


class _EdgeCanvas:
    """Dünya boyu srcalpha yüzey gibi davranan ama yalnız dört kenar şeridini (ve köşeleri) bellekte tutan çizim tuvali - duvar bandı için."""

    def __init__(self, w, h, band, corner):
        self.w, self.h = w, h
        b = max(band, corner)
        self.parts = [(pygame.Rect(0, 0, w, b),), (pygame.Rect(0, h - b, w, b),),
                      (pygame.Rect(0, b, b, h - 2 * b),), (pygame.Rect(w - b, b, b, h - 2 * b),)]
        self.parts = [(r, pygame.Surface(r.size, pygame.SRCALPHA)) for (r,) in self.parts]
        self._clip = None

    def get_clip(self):
        return self._clip

    def set_clip(self, r):
        self._clip = r

    def _each(self):
        for r, s in self.parts:
            if self._clip is not None:
                c = r.clip(self._clip)
                if c.w <= 0 or c.h <= 0:
                    continue
                s.set_clip(c.move(-r.x, -r.y))
            else:
                s.set_clip(None)
            yield r, s

    def rect(self, col, rect, width=0):
        rect = pygame.Rect(rect)
        for r, s in self._each():
            pygame.draw.rect(s, col, rect.move(-r.x, -r.y), width)

    def line(self, col, a, b, w=1):
        for r, s in self._each():
            pygame.draw.line(s, col, (a[0] - r.x, a[1] - r.y), (b[0] - r.x, b[1] - r.y), w)

    def blit_to(self, surf):
        for r, s in self.parts:
            s.set_clip(None)
            surf.blit(s, r.topleft)


def floor_surface(biome):
    surf = _FLOOR_CACHE.get(biome)
    if surf is None:
        # her harita büyük bir zemin (5x5 dünyada ~80 MB).
        for k in [k for k in _FLOOR_CACHE if k != "hell"]:
            del _FLOOR_CACHE[k]
        if biome != "hell" and "hell" in _FLOOR_CACHE:
            del _FLOOR_CACHE["hell"]
        surf = _build_floor(biome)
        _FLOOR_CACHE[biome] = surf
    return surf


# cehennem havasında süzülen korlar. Dünya koordinatında bir kez üretilir; her
# karede yalnızca kameranın gördükleri çizilir ve zamanla yukarı süzülür.
_HELL_EMBERS = None


def hell_embers():
    global _HELL_EMBERS
    if _HELL_EMBERS is None:
        rnd = random.Random(90210)
        _HELL_EMBERS = [(rnd.uniform(0, ARENA_RECT.w), rnd.uniform(0, ARENA_RECT.h),
                         rnd.uniform(16, 46), rnd.uniform(1.4, 3.4),
                         rnd.uniform(0, math.tau))
                        for _ in range(_nd(900))]
    return _HELL_EMBERS


def _draw_hell_air(world, cam, t):
    """Cehennem'in canlı katmanı: yukarı süzülen korlar ve sıcaklık parıltısı."""
    span = 420.0
    for (ex, ey, spd, sz, ph) in hell_embers():
        # kor yukarı süzülür, tepeye varınca başa sarar
        yy = ey - (t * spd) % span
        if yy < cam.top - 20 or yy > cam.bottom + 20:
            continue
        xx = ex + math.sin(t * 0.8 + ph) * 22.0
        if xx < cam.left - 20 or xx > cam.right + 20:
            continue
        k = 1.0 - ((ey - yy) % span) / span
        # Renk kasten basamaklı: blit_disc sprite önbelleği renge göre
        # anahtarlanıyor, her karede yeni bir ton üretilirse önbellek sürekli
        # dolup temizleniyor ve kare hızı düşüyor.
        blit_disc(world, xx, yy, sz * (0.45 + 0.55 * k),
                  (255, 150 + (int(70 * k) // 24) * 24, 60), int(70 + 130 * k))
    # ısı parıltısı: ekranın altından yukarı doğru sönen, nabız gibi atan örtü
    h = 170
    peak = 30 + 12 * math.sin(t * 1.3)
    heat = pygame.Surface((8, h), pygame.SRCALPHA)
    for i in range(h):
        k = (i / (h - 1)) ** 2          # aşağı indikçe güçlenir, kenarı belli olmaz
        pygame.draw.line(heat, (255, 92, 40, int(peak * k)), (0, i), (8, i))
    world.blit(pygame.transform.scale(heat, (cam.w, h)), (cam.left, cam.bottom - h))


# arena havasında süzülen ışık zerreleri ("ateş böcekleri").
_ARENA_MOTES = None


def arena_motes():
    global _ARENA_MOTES
    if _ARENA_MOTES is None:
        rnd = random.Random(31337)
        _ARENA_MOTES = [(rnd.uniform(0, ARENA_RECT.w), rnd.uniform(0, ARENA_RECT.h),
                         rnd.uniform(9, 26), rnd.uniform(1.1, 2.6),
                         rnd.uniform(0, math.tau))
                        for _ in range(_nd(620))]
    return _ARENA_MOTES


def _draw_arena_air(world, cam, t):
    """Arena'nın canlı katmanı."""
    span = 340.0
    # Telefonda süzülen ışık zerreleri çizilmez (her karede ~60 küçük çizim).
    motes = () if MOBILE else arena_motes()
    for (ex, ey, spd, sz, ph) in motes:
        yy = ey - (t * spd) % span
        if yy < cam.top - 16 or yy > cam.bottom + 16:
            continue
        xx = ex + math.sin(t * 0.55 + ph) * 16.0
        if xx < cam.left - 16 or xx > cam.right + 16:
            continue
        k = 1.0 - ((ey - yy) % span) / span
        tw = 0.45 + 0.55 * math.sin(t * 2.2 + ph)
        blit_disc(world, xx, yy, sz * (0.5 + 0.5 * k),
                  (150, 190 + (int(50 * k) // 25) * 25, 255),
                  int((40 + 120 * k) * tw))

    # ---- merkezdeki mührün nefesi ----
    # dikkat: bu katman her karede çalışıyor.
    ccx = ARENA_RECT.left + ARENA_RECT.w * 0.5
    ccy = ARENA_RECT.top + ARENA_RECT.h * 0.5
    if cam.inflate(120, 120).collidepoint(ccx, ccy):
        pulse = 0.5 + 0.5 * math.sin(t * 1.1)
        if not MOBILE:
            add_glow(world, ccx, ccy, 190, (90, 140, 255), 0.11 + 0.07 * pulse)
        ph = (t * 0.28) % 1.0
        ring_aa(world, ccx, ccy, 300 * (0.55 + 0.45 * ph),
                scale_col((118, 158, 255), 0.30 * (1.0 - ph)), 2)


def _draw_theme_air(world, cam, key, t):
    """Haritanın canlı havası: kar, ateş böcekleri, kum rüzgârı."""
    if key == "frost":
        span = 420.0
        for (ex, ey, spd, sz, ph) in arena_motes():
            yy = ey + (t * (spd * 1.4 + 20)) % span
            if yy < cam.top - 16 or yy > cam.bottom + 16:
                continue
            xx = ex + math.sin(t * 0.9 + ph) * 26.0
            if xx < cam.left - 16 or xx > cam.right + 16:
                continue
            blit_disc(world, xx, yy, sz * 0.9 + 0.6, (236, 244, 255), 150)
    elif key == "jungle":
        for (ex, ey, spd, sz, ph) in arena_motes():
            xx = ex + math.sin(t * 0.7 + ph) * 34.0
            yy = ey + math.cos(t * 0.5 + ph * 1.3) * 22.0
            if not (cam.left - 16 < xx < cam.right + 16 and cam.top - 16 < yy < cam.bottom + 16):
                continue
            tw = 0.5 + 0.5 * math.sin(t * 3.1 + ph * 5)
            if tw < 0.35:
                continue
            blit_disc(world, xx, yy, sz * (0.8 + 0.6 * tw), (200, 255, 120), int(60 + 150 * tw))
    elif key == "desert":
        span = 600.0
        for (ex, ey, spd, sz, ph) in arena_motes():
            xx = ex + (t * (spd * 4 + 60)) % span
            if xx < cam.left - 30 or xx > cam.right + 30:
                continue
            yy = ey + math.sin(t * 1.3 + ph) * 8
            if yy < cam.top - 10 or yy > cam.bottom + 10:
                continue
            ln = 8 + sz * 4
            pygame.draw.line(world, (232, 196, 140), (xx - ln, yy), (xx, yy), 1)
    else:
        _draw_arena_air(world, cam, t)


def draw_world_floor(world, cam, biome, t):
    """Kameranın gördüğü zemin parçasını dünya yüzeyine kopyalar."""
    world.blit(floor_surface(biome), cam.topleft, cam)
    if biome == "hell":
        _draw_hell_air(world, cam, t)
    elif biome == "arena":
        _draw_arena_air(world, cam, t)
        _draw_stone_fires(world, cam, t)
    else:
        _draw_theme_air(world, cam, biome, t)


_VIGNETTE = None


def view_vignette():
    """Kaldırıldı."""
    global _VIGNETTE
    if _VIGNETTE is None:
        _VIGNETTE = pygame.Surface(VIEW_RECT.size, pygame.SRCALPHA)
    return _VIGNETTE


# ---- imleç ----
# Windows imleci tamamen gizli (pygame.mouse.set_visible(False)); oyunun kendi
# nişangahı her ekranda çiziliyor:
#   "aim" - oyun içi nişangah: ortası boş halka, dört kertik, ince bir
#      merkez noktası. Ateş ederken kısa bir "geri tepme" ile açılır.
#   "ui" - menü / market imleci: sivri uçlu klasik ok, ama oyunun kendi
#      renkleriyle ve kontürlü - Windows okunun yerine geçiyor.

def draw_cursor(surf, pos, kind="ui", t=0.0, hot=False):
    """Oyunun kendi imleci. pos sanal ekran koordinatıdır."""
    if not pos:
        return
    x, y = int(pos[0]), int(pos[1])
    if kind == "aim":
        R = 11
        col = (255, 255, 255)
        acc = (255, 90, 90) if hot else (120, 220, 255)
        pad = 22
        cs = pygame.Surface((R * 2 + pad, R * 2 + pad), pygame.SRCALPHA)
        c = R + pad // 2
        # dış halka (ince, kontürlü)
        pygame.draw.circle(cs, (8, 9, 14, 170), (c, c), R + 1, 3)
        pygame.draw.circle(cs, (*col, 225), (c, c), R, 2)
        # dört kertik
        for dx, dy in ((0, -1), (0, 1), (-1, 0), (1, 0)):
            x0, y0 = c + dx * (R + 3), c + dy * (R + 3)
            x1, y1 = c + dx * (R + 9), c + dy * (R + 9)
            pygame.draw.line(cs, (8, 9, 14, 170), (x0, y0), (x1, y1), 4)
            pygame.draw.line(cs, (*acc, 235), (x0, y0), (x1, y1), 2)
        # merkez noktası
        pygame.draw.circle(cs, (8, 9, 14, 190), (c, c), 2)
        pygame.draw.circle(cs, (*acc, 255), (c, c), 1)
        surf.blit(cs, (x - c, y - c))
        return

    # ---- menü oku ----
    # Klasik ok biçimi, ama oyunun kendi kontürüyle: koyu bir gölge, koyu bir
    # çerçeve ve içinde açık gri -> beyaz degrade.
    body = [(0, 0), (0, 15.5), (3.9, 12.0), (6.4, 17.6), (8.8, 16.5),
            (6.5, 11.0), (11.3, 10.6)]
    sh = [(x + px + 1.5, y + py + 1.5) for px, py in body]
    pts = [(x + px, y + py) for px, py in body]
    pygame.draw.polygon(surf, (6, 7, 13), sh)
    pygame.draw.polygon(surf, (14, 16, 26), [(px - 1, py - 1) for px, py in pts])
    pygame.draw.polygon(surf, (248, 250, 255), pts)
    # gövdenin sağ yarısına hafif bir gri: düz beyaz "yapıştırma" gibi durmasın
    pygame.draw.polygon(surf, (206, 212, 230),
                        [pts[0], pts[6], pts[5], pts[3], pts[4]])
    pygame.draw.lines(surf, (20, 22, 36), True, pts, 1)


MINIMAP_W = 196          # sağ üstteki küçük haritanın genişliği
BIGMAP_H_FRAC = 0.62     # büyük haritanın ekran yüksekliğine oranı


def minimap_rect(big=False):
    """Haritanın dikdörtgeni. big=True ise ekranın ortasında büyük hâli."""
    if big:
        mh = int(VIRTUAL_H * BIGMAP_H_FRAC)
        mw = int(mh * ARENA_RECT.w / ARENA_RECT.h)
        if mw > VIRTUAL_W - 200:
            mw = VIRTUAL_W - 200
            mh = int(mw * ARENA_RECT.h / ARENA_RECT.w)
        r = pygame.Rect(0, 0, mw, mh)
        r.center = (VIRTUAL_W // 2, VIRTUAL_H // 2 + 4)
        return r
    mw = MINIMAP_W
    mh = int(MINIMAP_W * ARENA_RECT.h / ARENA_RECT.w)
    return pygame.Rect(VIRTUAL_W - mw - 16, ARENA_MARGIN_TOP + 10, mw, mh)


def draw_minimap(surf, run, t, big=False):
    """Dünya haritası."""
    st = BIOME_STYLE.get(run_floor_key(run), BIOME_STYLE["arena"])
    rect = minimap_rect(big)
    # Kök ölçek: harita 5 kat büyürken işaretler yalnızca ~2 kat büyüyor.
    k = max(1.0, (rect.w / float(MINIMAP_W)) ** 0.55)

    if big:
        # Büyük harita açıkken arkadaki saha karartılır ki harita okunsun.
        dim = pygame.Surface((VIRTUAL_W, VIRTUAL_H), pygame.SRCALPHA)
        pygame.draw.rect(dim, (4, 5, 11, 188), dim.get_rect())
        surf.blit(dim, (0, 0))

    bg = pygame.Surface((rect.w, rect.h), pygame.SRCALPHA)
    pygame.draw.rect(bg, (8, 9, 16, 236 if big else 210), bg.get_rect(),
                     border_radius=int(8 * (2 if big else 1)))
    surf.blit(bg, rect.topleft)

    sx = rect.w / ARENA_RECT.w
    sy = rect.h / ARENA_RECT.h

    def mp(x, y):
        return (rect.x + (x - ARENA_RECT.left) * sx, rect.y + (y - ARENA_RECT.top) * sy)

    # 3x3 hücre çizgileri
    for i in range(1, WORLD_TILES_X):
        x = rect.x + BASE_VIEW_W * i * sx
        pygame.draw.line(surf, (*st["wall"], 90), (x, rect.y + 2), (x, rect.bottom - 2), 1)
    for j in range(1, WORLD_TILES_Y):
        y = rect.y + BASE_VIEW_H * j * sy
        pygame.draw.line(surf, (*st["wall"], 90), (rect.x + 2, y), (rect.right - 2, y), 1)

    # toplanabilirler (çok soluk)
    for pu in run.pickups:
        if pu.kind == "coin":
            px, py = mp(pu.x, pu.y)
            surf.set_at((int(px), int(py)), (150, 130, 60))

    # düşmanlar
    for e in run.enemies:
        if not e.alive:
            continue
        px, py = mp(e.x, e.y)
        # Cehennem yaratıklarının kendi renkleri var - küçük haritada da onları
        # göster.
        col = getattr(e, "color", None) or ENEMY_COLORS.get(e.kind, RED)
        pygame.draw.circle(surf, col, (int(px), int(py)),
                           max(1, int(k * (2 if e.kind != "elite" else 3))))

    # patronlar
    for b in run.bosses:
        if b.alive and not b.is_hidden():
            px, py = mp(b.x, b.y)
            pulse = 3 + math.sin(t * 6) * 1.2
            pygame.draw.circle(surf, (255, 90, 80), (int(px), int(py)),
                               max(2, int(k * (4 + pulse * 0.4))))
            pygame.draw.circle(surf, WHITE, (int(px), int(py)), max(1, int(k * 2)))

    # güç sunağı
    _psh = getattr(run, "shrine", None)
    if _psh is not None and not _psh.used:
        px, py = mp(_psh.x, _psh.y)
        pulse = 0.5 + 0.5 * math.sin(t * 5)
        pygame.draw.circle(surf, INK, (int(px), int(py)), max(3, int(k * (5 + pulse))))
        pygame.draw.circle(surf, _psh.color(), (int(px), int(py)), max(2, int(k * (4 + pulse))))
    # mıknatıs - nadir eşya, küçük haritada nabız gibi atar ki kaçırılmasın
    for mg in run.magnets:
        px, py = mp(mg.x, mg.y)
        pulse = 0.5 + 0.5 * math.sin(t * 7)
        add_glow(surf, px, py, (16 + pulse * 8) * k, MAGNET_COLOR, 0.45 + pulse * 0.35)
        pygame.draw.circle(surf, MAGNET_COLOR, (int(px), int(py)), max(2, int(k * (4 + pulse * 2))))
    # seviye taşı - mıknatıs kadar nadir, aynı biçimde göze sokulur
    for lv in run.level_drops:
        px, py = mp(lv.x, lv.y)
        pulse = 0.5 + 0.5 * math.sin(t * 7)
        add_glow(surf, px, py, (16 + pulse * 8) * k, LEVEL_COLOR, 0.45 + pulse * 0.35)
        pygame.draw.circle(surf, LEVEL_COLOR, (int(px), int(py)), max(2, int(k * (4 + pulse * 2))))
        pygame.draw.circle(surf, MAGNET_COLOR2, (int(px), int(py)), max(1, int(k * 2)))

    # hortum (küçük haritada dönen halka)
    for tn in run.tornados:
        px, py = mp(tn.x, tn.y)
        pygame.draw.circle(surf, TORNADO_COLOR, (int(px), int(py)), max(3, int(k * 5)),
                           max(1, int(k)))

    # lanetli sandık (yalnızca bulunduktan sonra; M haritasında belirgin
    # parlar)
    _csh = getattr(run, "cursed_shrine", None)
    if _csh is not None and not _csh.used and getattr(_csh, "discovered", False):
        px, py = mp(_csh.x, _csh.y)
        pulse = 0.5 + 0.5 * math.sin(t * 5)
        gk = 2.2 if big else 1.0
        add_glow(surf, px, py, (18 + pulse * 6) * k * gk, CURSE_COLOR, 0.45 + pulse * 0.35)
        if big:
            for j in range(2):
                ph = (t * 0.8 + j * 0.5) % 1.0
                pygame.draw.circle(surf, scale_col(CURSE_COLOR2, 1.0 - ph), (int(px), int(py)),
                                   max(4, int(k * (8 + 26 * ph))), 2)
            draw_text(surf, L("cu.map_label"), (px, py - k * 22), max(10, int(9 * k)),
                      CURSE_COLOR2, bold=True, center=True)
        pygame.draw.circle(surf, CURSE_COLOR, (int(px), int(py)), max(3, int(k * 5)))
        pygame.draw.circle(surf, CURSE_COLOR2, (int(px), int(py)), max(1, int(k * 2)))

    # anahtarlar (altın) ve efsanevi sandık (büyük, nabız gibi)
    _lc = getattr(run, "legend_chest", None)
    if _lc is not None and not _lc.opened:
        px, py = mp(_lc.x, _lc.y)
        pulse = 0.5 + 0.5 * math.sin(t * 6)
        add_glow(surf, px, py, (22 + pulse * 10) * k, LEGEND_COLOR, 0.5 + pulse * 0.3)
        pygame.draw.rect(surf, OUTLINE, (int(px - 5 * k), int(py - 4 * k), int(10 * k), int(8 * k)))
        pygame.draw.rect(surf, LEGEND_COLOR, (int(px - 4 * k), int(py - 3 * k), int(8 * k), int(6 * k)))

    # market portalı cehennem portalı
    if run.hell_portal is not None:
        px, py = mp(run.hell_portal.x, run.hell_portal.y)
        pulse = 0.5 + 0.5 * math.sin(t * 4)
        add_glow(surf, px, py, 22 * k, HELL_PORTAL_COLOR, 0.25 + pulse * 0.25)
        pygame.draw.circle(surf, HELL_PORTAL_COLOR, (int(px), int(py)),
                           max(3, int(k * 5)), max(2, int(k * 2)))

    # kameranın gördüğü alan
    cam = run.cam_rect()
    vr = pygame.Rect(mp(cam.left, cam.top), (cam.w * sx, cam.h * sy))
    pygame.draw.rect(surf, (235, 240, 255), vr, width=max(1, int(k)))

    # oyuncu
    p = run.player
    px, py = mp(p.x, p.y)
    pygame.draw.circle(surf, WHITE, (int(px), int(py)), max(2, int(k * 3)))
    pygame.draw.circle(surf, p.skin["color"], (int(px), int(py)), max(1, int(k * 2)))
    ax, ay = p.aim_dir
    pygame.draw.line(surf, WHITE, (px, py), (px + ax * 7 * k, py + ay * 7 * k),
                     max(1, int(k)))

    if big:
        # Büyük haritanın çerçevesi, köşebentleri ve başlığı
        edge = st.get("wall", (90, 110, 170))
        pygame.draw.rect(surf, lighten(edge, 0.30), rect.inflate(6, 6), width=2,
                         border_radius=16)
        for cxs in (-1, 1):
            for cys in (-1, 1):
                ox = rect.centerx + cxs * (rect.w / 2 + 3)
                oy = rect.centery + cys * (rect.h / 2 + 3)
                pygame.draw.line(surf, GOLD, (ox, oy), (ox - cxs * 22, oy), 3)
                pygame.draw.line(surf, GOLD, (ox, oy), (ox, oy - cys * 22), 3)
        head = ("CEHENNEM HARİTASI" if run.biome == "hell"
                else L("map.%s.name" % getattr(run, "map_theme", "stone")))
        cap = pygame.Surface((rect.w, 30), pygame.SRCALPHA)
        pygame.draw.rect(cap, (6, 7, 14, 200), cap.get_rect())
        surf.blit(cap, (rect.x, rect.y))
        pygame.draw.line(surf, scale_col(GOLD, 0.6), (rect.x + 10, rect.y + 30),
                         (rect.right - 10, rect.y + 30), 1)
        draw_text(surf, head, (rect.x + 14, rect.y + 7), 17, GOLD, bold=True,
                  shadow=False)
        draw_text(surf, L("ui.map_info", run.waves.wave, len(run.enemies)),
                  (rect.right - 14, rect.y + 9), 12, TEXT_DIM, right=True, shadow=False)
        draw_text(surf, L("ui.map_close"), (rect.centerx, rect.bottom - 20), 12,
                  (150, 156, 184), center=True, shadow=False)

    # çerçeve + etiket
    pygame.draw.rect(surf, st["wall"], rect, width=2, border_radius=8)
    lab = st["name"] if run.biome == "hell" else L("map.%s.short" % getattr(run, "map_theme", "stone"))
    lw = text_width(lab, 10, True) + 12
    lr = pygame.Rect(rect.x + 6, rect.y - 9, int(lw), 16)
    ls = pygame.Surface(lr.size, pygame.SRCALPHA)
    pygame.draw.rect(ls, (10, 11, 20, 235), ls.get_rect(), border_radius=6)
    surf.blit(ls, lr.topleft)
    draw_text(surf, lab, (lr.centerx, lr.y + 2), 10, st["wall"], bold=True, center=True,
              shadow=False)


def _draw_key_counter(surf, run, t):
    """Küçük haritanın altında anahtar sayacı: 🔑 3/5 ya da sandık uyarısı."""
    rect = minimap_rect(False)
    got = int(getattr(run, "keys_got", 0))
    chest = getattr(run, "legend_chest", None)
    if chest is not None and not chest.opened:
        txt, col = L("ui.legend_chest"), LEGEND_COLOR
    elif getattr(run, "map_keys", None):
        txt, col = "%d/%d" % (got, KEY_COUNT), KEY_COLOR
    else:
        return
    w = text_width(txt, 12, True) + 34
    r = pygame.Rect(0, 0, int(w), 22)
    r.topright = (rect.right, rect.bottom + 6)
    bg = pygame.Surface(r.size, pygame.SRCALPHA)
    pygame.draw.rect(bg, (26, 19, 19, 215), bg.get_rect(), border_radius=8)
    surf.blit(bg, r.topleft)
    ink_frame(surf, r, scale_col(col, 0.8), 8, 1)
    draw_key_icon(surf, r.x + 13, r.centery - 1, 8, col)
    draw_text(surf, txt, (r.x + 26, r.y + 4), 12, col, bold=True, shadow=False)


def draw_offscreen_markers(surf, run, cam, t):
    """Ekran dışındaki önemli hedefler için kenar okları (patron / portallar)."""
    marks = []
    for b in run.bosses:
        # gölge perdesi açıkken patron küçük haritada da, kenar okunda da
        # yoktur.
        if b.alive and not b.is_hidden():
            marks.append((b.x, b.y, (255, 90, 80), "skull"))
    if run.hell_portal is not None:
        marks.append((run.hell_portal.x, run.hell_portal.y, HELL_PORTAL_COLOR, "gem"))
    _csh = getattr(run, "cursed_shrine", None)
    if _csh is not None and not _csh.used and getattr(_csh, "discovered", False):
        marks.append((_csh.x, _csh.y, CURSE_COLOR, "skull"))
    _psh = getattr(run, "shrine", None)
    if _psh is not None and not _psh.used:
        marks.append((_psh.x, _psh.y, _psh.color(), SHRINE_KINDS[_psh.kind][1]))
    # hazine goblini: kaçan ganimet ekran dışındaysa ok göster
    for e in run.enemies:
        if e.alive and e.kind == "goblin":
            marks.append((e.x, e.y, GOLD, "coin"))
    # mıknatıs ekran dışında kalırsa kenarda oku görünsün.
    for mg in run.magnets:
        marks.append((mg.x, mg.y, MAGNET_COLOR, "magnet"))
    for lv in run.level_drops:
        marks.append((lv.x, lv.y, LEVEL_COLOR, "star"))
    _lc = getattr(run, "legend_chest", None)
    if _lc is not None and not _lc.opened:
        marks.append((_lc.x, _lc.y, LEGEND_COLOR, "gem"))
    for (wx, wy, col, icon) in marks:
        if cam.collidepoint(wx, wy):
            continue
        cx, cy = cam.centerx, cam.centery
        dx, dy = wx - cx, wy - cy
        l = math.hypot(dx, dy) or 1.0
        dx, dy = dx / l, dy / l
        ex = clamp(cx + dx * cam.w, cam.left + 30, cam.right - 30)
        ey = clamp(cy + dy * cam.h, cam.top + 30, cam.bottom - 30)
        sx, sy = world_to_screen(ex, ey, cam)
        if SAFE_X:
            sx = clamp(sx, 34, VIRTUAL_W - 34)
        add_glow(surf, sx, sy, 34, col, 0.28)
        pygame.draw.circle(surf, (12, 13, 22), (int(sx), int(sy)), 13)
        pygame.draw.circle(surf, col, (int(sx), int(sy)), 13, 2)
        if icon == "key":
            draw_key_icon(surf, sx + 1, sy - 1, 8, col)
        else:
            draw_icon(surf, sx, sy, icon, col, 7)
        pygame.draw.polygon(surf, col, [(sx + dx * 20, sy + dy * 20),
                                        (sx + dx * 13 - dy * 6, sy + dy * 13 + dx * 6),
                                        (sx + dx * 13 + dy * 6, sy + dy * 13 - dx * 6)])


