# ---- yetenek çubuğu ----
# Ekranın altındaki yetenek yuvaları:
#   key: ekranda görünen tuş etiketi
#   name: yuvanın altındaki kısa ad
#   icon: draw_icon simge adı
#   color: yuva rengi
#   cd: (kalan, toplam) döndüren fonksiyon - bekleme süresi yoksa None
#   lock: True dönerse yuva kilitli (gri) çizilir - henüz açılmamış yetenekler

SKILL_SLOTS = [
    {"key": "SOL TIK", "pad": "fire", "name": "ATEŞ", "icon": "target", "color": (150, 210, 255),
     "cd": lambda p: (p.atk_timer, p.eff_atk_cd())},
    {"key": "SPACE", "pad": "bonk", "name": "BONK", "icon": "fist", "color": (245, 150, 80),
     "cd": lambda p: (p.bonk_timer, p.eff_bonk_cd())},
    {"key": "SHIFT", "pad": "dash", "name": "DASH", "icon": "dash", "color": (130, 225, 210),
     "cd": lambda p: (p.dash_cd_timer, p.eff_dash_cd())},
    {"key": "B", "pad": "shop", "name": "MARKET", "icon": "coin", "color": GOLD, "cd": None},
]

# Yalnızca belirli skinlerde görünen ek yuvalar.
SKILL_SLOT_SMASH = {"key": "SPACE", "pad": "bonk", "name": "EZİCİ", "icon": "skull", "color": (150, 255, 130),
                    "cd": lambda p: (p.smash_timer, RunState.TITAN_SMASH_CD)}


def skill_slots_for(p):
    """Oyuncunun skinine göre gösterilecek yetenek yuvaları."""
    slots = list(SKILL_SLOTS)
    if getattr(p, "titan_smash", 0):
        slots.insert(2, SKILL_SLOT_SMASH)
    # skin özel yeteneği: her skinin kendi yuvası. Tuş etiketi yerine yeteneğin
    # toplam bekleme süresi yazar (örn.
    ult = getattr(p, "ult", None)
    if ult:
        slots.append({"key": L("ui.sec_fmt", int(round(ult["cd"]))),
                      # Yeteneğin kısa adı (yuvanın altında) - her dilde ayrı,
                      # çünkü "BLOOD FRENZY"nin ilk kelimesi iyi bir etiket
                      # değil.
                      "name": LX("ults." + str(ult.get("id", "")),
                                 ult.get("short") or ult["name"].split()[0]),
                      "icon": ult.get("icon", "star"),
                      "color": tuple(ult.get("color", GOLD)),
                      "cd": lambda pp: (pp.ult_timer, pp.ult_cd)})
    # not: silahlar artık bu çubukta değil.
    return slots


# Yetenek çubuğu boyut kademeleri - duraklatma menüsünden değiştirilir.
SKILL_SCALES = [(0.65, "ÇOK KÜÇÜK"), (0.75, "KÜÇÜK"), (0.85, "NORMAL"),
                (1.0, "BÜYÜK"), (1.15, "ÇOK BÜYÜK")]


def skill_scale_label():
    cur = float(CFG.get("skill_scale", 0.85))
    best = min(SKILL_SCALES, key=lambda it: abs(it[0] - cur))
    return LX("size." + best[1], best[1])


def cycle_skill_scale():
    """Bir sonraki boyut kademesine geçer ve seçilen değeri döndürür."""
    cur = float(CFG.get("skill_scale", 0.85))
    idx = min(range(len(SKILL_SCALES)), key=lambda i: abs(SKILL_SCALES[i][0] - cur))
    nxt = SKILL_SCALES[(idx + 1) % len(SKILL_SCALES)][0]
    CFG["skill_scale"] = nxt
    return nxt


_wslot_panel_cache = {}


def _fit_text(txt, size, max_w, bold=False):
    """Metni verilen genişliğe sığdırır; sığmıyorsa sonunu kısaltır."""
    txt = TRX(txt)
    if text_width(txt, size, bold) <= max_w:
        return txt
    for n in range(len(txt) - 1, 1, -1):
        cut = txt[:n] + "."
        if text_width(cut, size, bold) <= max_w:
            return cut
    return txt[:1]


def _fit_size(txt, size, max_w, bold=False, min_size=9):
    """Metni küçülterek sığdırır; en küçük boyda da sığmazsa kısaltır."""
    size = int(size)
    for sz in range(max(size, UI_MIN_FONT), int(min_size) - 1, -1):
        if text_width(txt, sz, bold, tiny=True) <= max_w:
            return txt, sz
    return _fit_text(txt, min_size, max_w, bold), int(min_size)


def _slot_strip(w, h):
    """Yatay yuva şeridinin arka paneli - önbellekli."""
    key = (w, h)
    bs = _wslot_panel_cache.get(key)
    if bs is not None:
        return bs
    if len(_wslot_panel_cache) > 24:
        _wslot_panel_cache.clear()
    bs = hand_card(w, h, (34, 26, 28), edge=(118, 88, 70), rad=12, alpha=196).copy()
    _wslot_panel_cache[key] = bs
    return bs


_EMPTY_SLOT_CACHE = {}


def _empty_slot(surf, r, t, i, radius=10):
    """Boş yuva: nefes alan kesik çizgili çerçeve + soluk artı."""
    breathe = 0.5 + 0.5 * math.sin(t * 1.6 + i * 0.7)
    lvl = int(breathe * 9 + 0.5)
    key = (r.w, r.h, radius, lvl)
    img = _EMPTY_SLOT_CACHE.get(key)
    if img is None:
        if len(_EMPTY_SLOT_CACHE) > 400:
            _EMPTY_SLOT_CACHE.clear()
        img = _build_empty_slot(r.w, r.h, radius, lvl / 9.0)
        _EMPTY_SLOT_CACHE[key] = img
    surf.blit(img, r.topleft)


def _build_empty_slot(w, h, radius, breathe):
    surf = pygame.Surface((w, h), pygame.SRCALPHA)
    r = pygame.Rect(0, 0, w, h)
    pygame.draw.rect(surf, (31, 23, 23), r, border_radius=radius)
    dash_col = tuple(int(lerp(40, 68, breathe)) for _ in range(3))
    dr = r.inflate(-3, -3)
    seg, gapl = 6, 5
    pts = [dr.topleft, dr.topright, dr.bottomright, dr.bottomleft, dr.topleft]
    edges = list(zip(pts, pts[1:]))
    perim = 2 * (dr.w + dr.h)
    pos = 0.0
    while pos < perim:
        d = pos
        for (ax, ay), (bx, by) in edges:
            elen = math.hypot(bx - ax, by - ay)
            if d <= elen:
                f0, f1 = d / elen, min(1.0, (d + seg) / elen)
                pygame.draw.line(surf, dash_col,
                                 (ax + (bx - ax) * f0, ay + (by - ay) * f0),
                                 (ax + (bx - ax) * f1, ay + (by - ay) * f1), 2)
                break
            d -= elen
        pos += seg + gapl
    a_ = int(55 + 65 * breathe)
    ps = pygame.Surface(r.size, pygame.SRCALPHA)
    arm = max(4, r.w * 0.13)
    pygame.draw.line(ps, (140, 150, 190, a_), (r.w / 2 - arm, r.h / 2), (r.w / 2 + arm, r.h / 2), 2)
    pygame.draw.line(ps, (140, 150, 190, a_), (r.w / 2, r.h / 2 - arm), (r.w / 2, r.h / 2 + arm), 2)
    surf.blit(ps, (0, 0))
    return surf


def _level_badge(surf, cx, cy, lvl, col, maxed=False, h=18):
    """Yuvanın köşesindeki seviye madalyonu (iki haneli sayıda hap biçimi)."""
    txt = str(lvl)
    bw = h + (0 if lvl < 10 else 7)
    badge = pygame.Rect(0, 0, bw, h)
    badge.center = (int(cx), int(cy))
    pygame.draw.rect(surf, (22, 16, 17), badge, border_radius=h // 2)
    ink_frame(surf, badge, GOLD if maxed else col, h // 2, 2)
    draw_text(surf, txt, badge.center, 10 if lvl < 10 else 9,
              GOLD if maxed else lighten(col, 0.2), bold=True, center=True, shadow=False)


# Yatay şeritlerin ortak ölçüleri.
HUD_STRIP_X = 18
# Hücreler büyüdü - hem adlar sığıyor hem de simgeler uzaktan daha net.
WSLOT_CELL = 54
WSLOT_GAP = 8
BSLOT_CELL = 48
BSLOT_GAP = 7
HUD_WEAPON_Y = 96        # silah şeridinin üst kenarı
HUD_BOOK_Y = HUD_WEAPON_Y + WSLOT_CELL + 35   # kitap şeridinin üst kenarı


# iki şerit birlikte %50-150 arası ölçeklenir (ESC > sol üst panel).
HUD_SCALE_MIN = 50
HUD_SCALE_MAX = 150
_TEAM_STRIP_MOB = {}
_TEAM_STRIP_BUF = [None]


def hud_scale_pct():
    try:
        return int(clamp(int(CFG.get("hud_scale", 100)), HUD_SCALE_MIN, HUD_SCALE_MAX))
    except (TypeError, ValueError):
        return 100


def draw_team_strips(surf, run, t):
    """Silah ve kitap şeritlerini ayardaki boyutta çizer."""
    pct = hud_scale_pct()
    # şeritlerin hemen altında koşu görevleri kutusu
    _oy = HUD_WEAPON_Y - 22
    qy = int(_oy + (HUD_BOOK_Y + BSLOT_CELL + 22 - _oy) * pct / 100.0) + 6
    if MOBILE:
        _mob_team_strips(surf, run, t, pct, qy)
        return
    if getattr(run, "quests", None) and CFG.get("show_quests", True):
        draw_quest_hud(surf, run, HUD_STRIP_X - 8, qy, t)
    if pct == 100 and not MOBILE:
        draw_weapon_slots(surf, run, t)
        draw_book_slots(surf, run, t)
        return
    global _GLOW_ON_ALPHA
    ox, oy = HUD_STRIP_X - 12, HUD_WEAPON_Y - 22
    w, h = 470, HUD_BOOK_Y + BSLOT_CELL + 42 - oy
    if MOBILE:
        # telefon: şeritler saniyede ~12 kez tazelenir, arada hazır görüntü
        # basılır (her karede ~40 küçük çizim yerine tek blit).
        c = _TEAM_STRIP_MOB
        if c.get("run") is run and c.get("img") is not None and 0 <= t - c.get("t", -9) < 0.15:
            surf.blit(c["img"], (ox, oy))
            return
    buf = _TEAM_STRIP_BUF[0]
    if buf is None or buf.get_size() != (ox + w, oy + h):
        buf = pygame.Surface((ox + w, oy + h), pygame.SRCALPHA)
        _TEAM_STRIP_BUF[0] = buf
    buf.fill((0, 0, 0, 0))
    _GLOW_ON_ALPHA = True
    try:
        draw_weapon_slots(buf, run, t)
        draw_book_slots(buf, run, t)
    finally:
        _GLOW_ON_ALPHA = False
    k = pct / 100.0
    part = buf.subsurface((ox, oy, w, h))
    if pct == 100:
        img = part.copy()
    else:
        img = pygame.transform.smoothscale(part, (max(1, int(w * k)), max(1, int(h * k))))
    if MOBILE:
        _TEAM_STRIP_MOB.update(run=run, img=mob_rle(img), t=t)
    surf.blit(img, (ox, oy))


_MOB_FRAME = [0]             # telefon: önbellek tazelemelerini karelere yaymak için


def _mob_team_strips(surf, run, t, pct, qy):
    """telefon: silah + kitap şeritleri ve koşu görevleri tek hazır görüntü."""
    global _GLOW_ON_ALPHA
    c = _TEAM_STRIP_MOB
    show_q = bool(getattr(run, "quests", None) and CFG.get("show_quests", True))
    ox, oy = HUD_STRIP_X - 12, HUD_WEAPON_Y - 22
    w, h = 470, HUD_BOOK_Y + BSLOT_CELL + 42 - oy
    if pct == 100:
        # iki ayrı katman, iki ayrı karede tazelenir
        size = (ox + w, (qy + 130) if show_q else (oy + h))
        mob_layer(surf, "team_w", run, t, 4, size, lambda b: draw_weapon_slots(b, run, t))

        def _books(b):
            draw_book_slots(b, run, t)
            if show_q:
                draw_quest_hud(b, run, HUD_STRIP_X - 8, qy, t)
        mob_layer(surf, "team_b", run, t, 6, size, _books)
        return
    fresh = (c.get("run") is run and c.get("img") is not None and c.get("q") == show_q
             and c.get("pct") == pct and (_MOB_FRAME[0] % 8) != 4 and abs(t - c.get("t", -9)) < 0.5)
    if not fresh:
        bh = qy + 130 if show_q else oy + h
        buf = c.get("work")
        if buf is None or buf.get_size() != (ox + w, bh):
            buf = pygame.Surface((ox + w, bh), pygame.SRCALPHA)
            c["work"] = buf
        buf.fill((0, 0, 0, 0))
        _GLOW_ON_ALPHA = True
        try:
            if pct == 100:
                draw_weapon_slots(buf, run, t)
                draw_book_slots(buf, run, t)
            else:
                tmp = c.get("tmp")
                if tmp is None or tmp.get_size() != (ox + w, oy + h):
                    tmp = pygame.Surface((ox + w, oy + h), pygame.SRCALPHA)
                    c["tmp"] = tmp
                tmp.fill((0, 0, 0, 0))
                draw_weapon_slots(tmp, run, t)
                draw_book_slots(tmp, run, t)
                k = pct / 100.0
                part = tmp.subsurface((ox, oy, w, h))
                buf.blit(pygame.transform.smoothscale(part, (max(1, int(w * k)), max(1, int(h * k)))),
                         (ox, oy))
            if show_q:
                draw_quest_hud(buf, run, HUD_STRIP_X - 8, qy, t)
        finally:
            _GLOW_ON_ALPHA = False
        br = buf.get_bounding_rect()
        if br.w <= 0 or br.h <= 0:
            c.update(run=run, img=None, t=t, q=show_q, pct=pct)
            return
        c.update(run=run, img=mob_rle(buf.subsurface(br).copy()), pos=br.topleft, t=t,
                 q=show_q, pct=pct)
    if c.get("img") is not None:
        surf.blit(c["img"], c["pos"])


def draw_weapon_slots(surf, run, t):
    """Canın altındaki yatay silah şeridi."""
    p = run.player
    cell, gap = WSLOT_CELL, WSLOT_GAP
    keys = [k for k in BOSS_WEAPONS_ORDER if p.weapons.get(k, 0) > 0]
    n_filled = len(keys)
    n = max(slot_max(p, 'w'), n_filled)
    x0, y0 = HUD_STRIP_X, HUD_WEAPON_Y

    back = pygame.Rect(x0 - 8, y0 - 17, n * cell + (n - 1) * gap + 16, cell + 25)
    surf.blit(_slot_strip(back.w, back.h), back.topleft)
    full = n_filled >= slot_max(p, 'w')
    hcol = GOLD if full else TEXT_DIM
    draw_text(surf, L("ui.weapons"), (back.x + 10, y0 - 15), 10, hcol, bold=True, shadow=False)
    draw_text(surf, f"{n_filled}/{slot_max(p, 'w')}",
              (back.x + 14 + text_width(L("ui.weapons"), 10, True), y0 - 15), 10,
              hcol if full else (104, 110, 136), bold=True, shadow=False)

    evolved = getattr(p, "evolved", ())
    ready_evo = evo_ready_keys(p) if not getattr(run, "is_coop", False) else ()
    for i in range(n):
        r = pygame.Rect(x0 + i * (cell + gap), y0, cell, cell)
        if i >= n_filled:
            _empty_slot(surf, r, t, i)
            continue

        key = keys[i]
        w = WEAPON_BY_KEY[key]
        lvl = p.weapons[key]
        is_evo = key in evolved
        col = EVOLUTIONS[key][2] if is_evo else tuple(w["color"])
        passive = bool(w.get("passive"))
        timed = bool(w.get("timed"))
        invis_now = timed and getattr(p, "invis_t", 0.0) > 0
        if timed:
            remain, total_cd = ((0.0, 0.0) if invis_now
                                else (max(0.0, getattr(p, "cloak_timer", 0.0)),
                                      cloak_cooldown(lvl)))
        elif passive:
            remain, total_cd = 0.0, 0.0
        else:
            remain = max(0.0, p.weapon_timers.get(key, 0.0))
            total_cd = weapon_cooldown(w, lvl) / (1.0 + getattr(p, "weapon_speed_bonus", 0.0))
        ready = (passive and not timed) or invis_now or remain <= 0.001 or total_cd <= 0
        frac = 0.0 if ready else clamp(remain / max(0.0001, total_cd), 0.0, 1.0)
        pulse = 0.5 + 0.5 * math.sin(t * 3.2 + i * 0.9)

        if ready:
            add_glow(surf, r.centerx, r.centery, cell * 0.95, col, 0.20 + 0.13 * pulse)
        pygame.draw.rect(surf, (36, 26, 27), r, border_radius=10)
        surf.blit(_slot_tint(r.size, scale_col(col, 0.55), 46), r.topleft)

        if frac > 0:
            fh = max(1, int(r.h * frac))
            surf.blit(_slot_cool(r.w, fh, lighten(col, 0.3)), (r.x, r.y + r.h - fh))
        else:
            surf.blit(_slot_tint(r.size, col, int(150 * (0.14 + 0.10 * pulse))),
                      r.topleft)

        edge_col = col if ready else scale_col(col, 0.42)
        ink_frame(surf, r, edge_col, 10, 3 if ready and pulse > 0.55 else 2)

        icx, icy = r.centerx, r.centery - 1
        icon_r = cell * 0.30
        for k_ in range(8):
            a = t * 0.6 + k_ * math.tau / 8
            r0, r1 = icon_r * 1.26, icon_r * (1.40 + 0.06 * pulse)
            ring_col = edge_col if ready else scale_col(edge_col, 0.7)
            pygame.draw.line(surf, ring_col,
                             (icx + math.cos(a) * r0, icy + math.sin(a) * r0),
                             (icx + math.cos(a) * r1, icy + math.sin(a) * r1), 1)
        pygame.draw.circle(surf, (26, 19, 19), (int(icx), int(icy)), int(icon_r * 1.2))
        blit_sigil(surf, icx, icy, icon_r, key,
                   col if ready else scale_col(col, 0.55))

        if frac > 0:
            txt = f"{remain:.1f}"
            plaque = pygame.Rect(0, 0, text_width(txt, 12, True) + 8, 14)
            plaque.center = (r.centerx, r.centery - 2)
            ps = pygame.Surface(plaque.size, pygame.SRCALPHA)
            pygame.draw.rect(ps, (15, 10, 11, 175), ps.get_rect(), border_radius=5)
            surf.blit(ps, plaque.topleft)
            draw_text(surf, txt, (r.centerx, r.centery - 4), 12, WHITE, bold=True, center=True)

        # Rozet üst sağ köşede: alttaki ad yazısının üstüne binmesin.
        _level_badge(surf, r.right - 1, r.y + 1, lvl, col,
                     maxed=lvl >= weapon_max_level(w), h=17)
        if is_evo or key in ready_evo:
            # evrilmiş: sol üstte EVO etiketi; evrime hazır: yanıp sönen ok
            tag = L("evo.short") if is_evo else "!"
            tr_ = pygame.Rect(r.x - 4, r.y - 6, text_width(tag, 9, True) + 8, 14)
            if is_evo or pulse > 0.4:
                pygame.draw.rect(surf, col if is_evo else GOLD, tr_, border_radius=4)
                pygame.draw.rect(surf, INK, tr_, width=1, border_radius=4)
                draw_text(surf, tag, tr_.center, 9, INK, bold=True, center=True, shadow=False)
        name = _fit_text(evo_name(key) if is_evo else w_name(w), 8, cell + gap - 7, bold=True)
        ncol = (CLOAK_COLOR2 if invis_now else
                (lighten(col, 0.25) if ready else (118, 124, 148)))
        draw_text(surf, name, (r.centerx, r.bottom + 3), 8, ncol, bold=True,
                  center=True, shadow=False)


# İkisi de yalnızca boyuta, renge ve saydamlığa bağlı, o yüzden saklanıyorlar.
_slot_layer_cache = {}


def _slot_tint(size, col, alpha):
    alpha = int(clamp(alpha, 0, 255)) // 6 * 6
    ck = ("t", size, (int(col[0]), int(col[1]), int(col[2])), alpha)
    sfc = _slot_layer_cache.get(ck)
    if sfc is None:
        if len(_slot_layer_cache) > 600:
            _slot_layer_cache.clear()
        sfc = pygame.Surface(size, pygame.SRCALPHA)
        pygame.draw.rect(sfc, (int(col[0]), int(col[1]), int(col[2]), alpha),
                         sfc.get_rect(), border_radius=10)
        _slot_layer_cache[ck] = sfc
    return sfc


def _slot_cool(w, h, line_col):
    ck = ("c", w, h, (int(line_col[0]), int(line_col[1]), int(line_col[2])))
    sfc = _slot_layer_cache.get(ck)
    if sfc is None:
        if len(_slot_layer_cache) > 600:
            _slot_layer_cache.clear()
        sfc = pygame.Surface((w, h), pygame.SRCALPHA)
        pygame.draw.rect(sfc, (19, 14, 14, 205), sfc.get_rect())
        pygame.draw.line(sfc, (int(line_col[0]), int(line_col[1]), int(line_col[2]), 150),
                         (2, 0), (w - 2, 0), 2)
        _slot_layer_cache[ck] = sfc
    return sfc


def draw_book_slots(surf, run, t):
    """Silah şeridinin altındaki yatay kitap şeridi."""
    p = run.player
    cell, gap = BSLOT_CELL, BSLOT_GAP
    normals = [k for k in p.books if not BOOK_BY_KEY.get(k, {}).get("rare")]
    rares = [k for k in p.books if BOOK_BY_KEY.get(k, {}).get("rare")]
    n_norm = max(slot_max(p, 'b'), len(normals))
    n_rare = max(slot_max(p, 'r'), len(rares))
    n_tot = n_norm + n_rare
    x0, y0 = HUD_STRIP_X, HUD_BOOK_Y
    # Nadir yuva, normallerden biraz ayrı dursun: aradaki boşluk iki katı.
    sep = gap * 2

    width = n_tot * cell + (n_tot - 1) * gap + sep
    back = pygame.Rect(x0 - 8, y0 - 17, width + 16, cell + 22)
    surf.blit(_slot_strip(back.w, back.h), back.topleft)
    full_b = len(normals) >= slot_max(p, 'b')
    hcol = GOLD if full_b else TEXT_DIM
    draw_text(surf, L("ui.books_hud"), (back.x + 10, y0 - 15), 10, hcol, bold=True, shadow=False)
    draw_text(surf, f"{len(normals)}/{slot_max(p, 'b')}",
              (back.x + 14 + text_width(L("ui.books_hud"), 10, True), y0 - 15), 10,
              hcol if full_b else (104, 110, 136), bold=True, shadow=False)

    def slot_rect(i):
        x = x0 + i * (cell + gap) + (sep if i >= n_norm else 0)
        return pygame.Rect(x, y0, cell, cell)

    for i in range(n_tot):
        r = slot_rect(i)
        rare_slot = i >= n_norm
        idx = i - n_norm if rare_slot else i
        src = rares if rare_slot else normals
        if idx >= len(src):
            _empty_slot(surf, r, t, i + 3, radius=8)
            if rare_slot:
                # boş nadir yuva altın bir ipucu halkası taşır
                ink_frame(surf, r, scale_col(GOLD, 0.45), 8, 1)
            continue

        key = src[idx]
        bk = BOOK_BY_KEY[key]
        lvl = p.books[key]
        col = tuple(bk["color"])
        maxed = lvl >= book_max_level(bk)
        pulse = 0.5 + 0.5 * math.sin(t * 2.4 + i * 0.8)

        add_glow(surf, r.centerx, r.centery, cell * 0.9, col, 0.16 + 0.10 * pulse)
        pygame.draw.rect(surf, (16, 17, 27), r, border_radius=8)
        tint = pygame.Surface(r.size, pygame.SRCALPHA)
        pygame.draw.rect(tint, (*scale_col(col, 0.55), 44), tint.get_rect(), border_radius=8)
        surf.blit(tint, r.topleft)
        ink_frame(surf, r, GOLD if rare_slot else col, 8, 3 if rare_slot else 2)
        draw_icon(surf, r.centerx, r.centery - 1, bk.get("icon", "star"), col, cell * 0.26)
        _level_badge(surf, r.right - 1, r.y + 1, lvl, col, maxed=maxed, h=15)
        name = _fit_text(bk_short(bk), 8, cell + gap - 7, bold=True)
        draw_text(surf, name, (r.centerx, r.bottom + 3), 8, lighten(col, 0.2),
                  bold=True, center=True, shadow=False)


def draw_skill_bar(surf, run, t):
    """Ekranın alt ortasında yetenek yuvalarını çizer."""
    p = run.player
    slots = skill_slots_for(p)
    n = len(slots)
    k = clamp(float(CFG.get("skill_scale", 0.85)), 0.5, 1.4)
    sw, sh, gap = int(62 * k), int(62 * k), max(5, int(10 * k))
    total = n * sw + (n - 1) * gap
    x0 = VIRTUAL_W / 2 - total / 2
    y0 = VIRTUAL_H - sh - int(30 * k)

    # arka panel
    back = pygame.Rect(int(x0 - 12 * k), int(y0 - 10 * k), int(total + 24 * k), int(sh + 32 * k))
    bs = pygame.Surface(back.size, pygame.SRCALPHA)
    pygame.draw.rect(bs, (26, 19, 19, 188), bs.get_rect(), border_radius=14)
    pygame.draw.rect(bs, (102, 74, 77, 220), bs.get_rect(), width=2, border_radius=14)
    surf.blit(bs, back.topleft)

    for i, sk in enumerate(slots):
        r = pygame.Rect(int(x0 + i * (sw + gap)), int(y0), sw, sh)
        locked = bool(sk.get("lock") and sk["lock"](p))
        col = (129, 103, 106) if locked else sk["color"]

        remain, total_cd = 0.0, 0.0
        if sk.get("cd") and not locked:
            try:
                remain, total_cd = sk["cd"](p)
            except Exception:
                remain, total_cd = 0.0, 0.0
        ready = remain <= 0.001 or total_cd <= 0
        frac = 0.0 if ready else clamp(remain / max(0.0001, total_cd), 0.0, 1.0)

        # yuva zemini
        pygame.draw.rect(surf, (37, 27, 28), r, border_radius=10)
        # bekleme süresi: aşağıdan yukarı dolan karartma
        if frac > 0:
            fill_h = int(r.h * frac)
            cs = pygame.Surface((r.w, fill_h), pygame.SRCALPHA)
            pygame.draw.rect(cs, (19, 14, 14, 200), cs.get_rect())
            surf.blit(cs, (r.x, r.y + r.h - fill_h))
        elif not locked:
            # hazır: hafif nabız
            pulse = 0.18 + 0.10 * math.sin(t * 4 + i)
            gs = pygame.Surface((r.w, r.h), pygame.SRCALPHA)
            pygame.draw.rect(gs, (*col, int(255 * pulse)), gs.get_rect(), border_radius=10)
            surf.blit(gs, r.topleft)

        ink_frame(surf, r, col if ready and (not locked) else (88, 65, 67), 10, 2)

        # simge
        icon_col = col if (ready and not locked) else scale_col(col, 0.55)
        draw_icon(surf, r.centerx, r.centery - 4 * k, sk["icon"], icon_col, max(7, int(15 * k)))

        # kalan süre yazısı
        if frac > 0:
            draw_text(surf, f"{remain:.1f}", (r.centerx, r.centery - 8 * k), max(9, int(15 * k)), WHITE,
                      bold=True, center=True)

        # tuş etiketi
        kb = pygame.Rect(r.x + 3, int(r.bottom - 17 * k), r.w - 6, max(9, int(14 * k)))
        pygame.draw.rect(surf, (59, 43, 45) if not locked else (46, 33, 35), kb, border_radius=4)
        # kontrolcü etkinse tuş yerine pad düğmesi yazar: oyuncu elindeki alete
        # bakıp "SPACE" görmesin.
        klabel = PAD_LABELS.get(sk.get("pad", ""), "") if PAD_ACTIVE[0] else ""
        if not klabel:
            # tuş atama: şerit, oyuncunun kendi tuşunu yazar. Sabit "SPACE"
            # yazmak, tuşunu değiştiren oyuncuya yalan söylemek olurdu.
            eylem = sk.get("pad", "")
            if eylem in KEY_ACTIONS:
                klabel = key_label_short(eylem)
        ktxt = klabel or LX("key." + str(sk["key"]), sk["key"])
        ktxt, ksize = _fit_size(ktxt, max(6, int(9 * k)), kb.w - 4,
                                bold=True, min_size=9)
        draw_text(surf, ktxt, kb.center, ksize,
                  TEXT if not locked else (110, 114, 136),
                  bold=True, center=True, shadow=False, tiny=True)

        # yuva adı - yuvadan taşmasın, komşusuna binmesin
        nsize = max(7, int(10 * k))
        sname = LX("slot." + str(sk.get("name", "")), sk.get("name", ""))
        sname, nsize = _fit_size(sname, nsize, sw + gap - 6, min_size=10)
        draw_text(surf, sname,
                  (r.centerx, r.bottom + 4 * k), nsize,
                  TEXT_DIM if not locked else (92, 96, 118), center=True,
                  shadow=False, tiny=True)

        if locked:
            pygame.draw.line(surf, (140, 100, 110), (r.x + 8, r.y + 8), (r.right - 8, r.bottom - 8), 2)


# ---- istatistik paneli (TAB / sağ üstteki "⋮" düğmesi) ----
# yeniden tasarlandı:
# * konu başlıklarına ayrılmış (hayatta kalma / hasar / hareket / kazanç)
# * çubuk yok - solda etiket, sağda değer, iki sütun hizalı
# * yalnızca anlamlı satırlar görünür (kalkanın yoksa "Kalkan" satırı yok)
# * panel belirgin biçimde daraldı ve kısaldı

STATS_BTN_W, STATS_BTN_H = 30, 26
STATS_PANEL_W = 254      # eski: 336 - panel daraldı
STATS_HEAD_H = 30        # başlık şeridinin yüksekliği
STATS_ROW_H = 17         # tek satırın yüksekliği
STATS_GROUP_GAP = 11     # gruplar arası boşluk
STATS_GROUP_HEAD_H = 13  # grup başlığının kapladığı yükseklik
_stats_head_cache = {}


def stats_button_rect():
    """Sağ üst köşedeki üç nokta düğmesi."""
    return pygame.Rect(VIRTUAL_W - STATS_BTN_W - 10, 8, STATS_BTN_W, STATS_BTN_H)


def _stats_header(w, h):
    """İstatistik panelinin başlık şeridi (degrade + alt ayraç) - önbellekli."""
    key = (w, h)
    sh = _stats_head_cache.get(key)
    if sh is None:
        if len(_stats_head_cache) > 6:
            _stats_head_cache.clear()
        sh = pygame.Surface((w, h), pygame.SRCALPHA)
        for yy in range(h):
            f = yy / max(1, h - 1)
            pygame.draw.line(sh, (int(lerp(34, 22, f)), int(lerp(52, 34, f)),
                                  int(lerp(44, 30, f)), 255), (0, yy), (w, yy))
        mask = pygame.Surface((w, h), pygame.SRCALPHA)
        pygame.draw.rect(mask, (255, 255, 255, 255), mask.get_rect(),
                         border_top_left_radius=10, border_top_right_radius=10,
                         border_bottom_left_radius=0, border_bottom_right_radius=0)
        sh.blit(mask, (0, 0), special_flags=pygame.BLEND_RGBA_MIN)
        _stats_head_cache[key] = sh
    return sh


def stats_panel_rect(n_rows, n_groups=0):
    """Panelin dikdörtgeni."""
    b = stats_button_rect()
    h = (STATS_HEAD_H + n_rows * STATS_ROW_H
         + n_groups * STATS_GROUP_HEAD_H
         + max(0, n_groups - 1) * STATS_GROUP_GAP + 10)
    return pygame.Rect(VIRTUAL_W - STATS_PANEL_W - 10, b.bottom + 6, STATS_PANEL_W, h)


def _pct(v):
    """Oranı yüzdeye çevirir."""
    return fmt_pct(v * 100)


def _mult(v):
    """Çarpanı okunur biçimde yazar: 2.0 -> "2,0x" (tr) / "2.0x" (en)."""
    t = f"{v:.1f}x"
    return t.replace(".", ",") if lang() == "tr" else t


def _vamp_text(p):
    """Can çalma satırının yazısı."""
    oran = _pct(0.02 * p.vamp_level)
    if p.vamp_level <= 0:
        return oran
    return "%s (%s)" % (oran, L("st.vamp_cap", _pct(0.04 + 0.02 * p.vamp_level)))


def player_stat_groups(p, run):
    """İstatistikleri gruplanmış biçimde döndürür."""
    dmg_r = p.eff_dmg() / max(1e-6, BASE_DMG)
    aspd_r = BASE_ATK_CD / max(1e-6, p.eff_atk_cd())
    spd_r = p.eff_speed() / max(1e-6, BASE_SPEED)
    pick_r = p.eff_pickup() / max(1e-6, BASE_PICKUP)
    dash_r = BASE_DASH_CD / max(1e-6, p.eff_dash_cd())
    bonk_r = BASE_BONK_CD / max(1e-6, p.eff_bonk_cd())
    base_dps = BASE_DMG * (1.0 + 0.05 * (1.6 - 1.0)) / BASE_ATK_CD

    hayat = [
        (L("st.max_hp"), f"{int(p.max_hp)}", (235, 120, 150)),
        (L("st.regen"), f"{p.eff_regen():.1f}" + L("ui.per_sec"), GREEN),
        (L("st.armor"), _pct(p.eff_armor()), (160, 180, 220)),
        (L("st.vamp"), _vamp_text(p), (220, 60, 90)),
    ]
    if p.shield_charges:
        hayat.append((L("st.shield"), f"{p.shield_charges}", (160, 170, 200)))
    if p.second_wind_charges:
        hayat.append((L("st.second"), f"{p.second_wind_charges}", GOLD))
    if p.thorns_level:
        hayat.append((L("st.thorns"), f"{p.thorns_level}", (170, 125, 90)))
    if getattr(p, "evade_pts", 0) > 0:
        hayat.append((L("bs.evade"), _pct(p.eff_evasion()), (200, 225, 255)))

    hasar = [
        (L("st.dmg"), _pct(dmg_r), (245, 120, 110)),
        (L("st.crit"), _pct(p.eff_crit_chance()), (230, 220, 120)),
        (L("st.critd"), _pct(p.eff_crit_dmg()), (255, 210, 130)),
        (L("st.aspd"), _pct(aspd_r), (150, 210, 255)),
        (L("st.dps"), _pct(p.estimated_dps() / max(1e-6, base_dps)), (255, 190, 90)),
        (L("st.multi"), f"{1 + p.multishot_level}", PURPLE),
        (L("st.pierce"), f"{p.eff_pierce_hits()}", RED),
    ]
    if p.boss_hunter:
        hasar.append((L("st.bossdmg"), f"+{_pct(p.boss_hunter_bonus())}", (200, 90, 220)))
    if getattr(p, "weapon_speed_bonus", 0) > 0:
        hasar.append((L("bs.wspd"), "+" + _pct(p.weapon_speed_bonus), (120, 200, 255)))
    if p.execute_threshold > 0:
        hasar.append((L("st.execute"), _pct(p.execute_threshold), GOLD))

    hareket = [
        (L("st.speed"), _pct(spd_r), (130, 230, 170)),
        (L("st.dash"), _pct(dash_r), (130, 225, 210)),
        (L("st.bonk"), _pct(bonk_r), (245, 150, 80)),
        (L("st.pickup"), f"{int(p.eff_pickup())}", (150, 220, 255)),
    ]

    kazanc = [
        (L("st.gold"), _pct(p.eff_coin_mult()), GOLD),
        (L("st.xp"), _pct(p.eff_xp_mult()), PURPLE),
        # şans: 0 iken de görünür - oyuncu statın var olduğunu bilsin.
        (L("st.luck"), fmt_pct1(p.eff_luck()), GREEN),
    ]
    if p.frenzy_stacks:
        kazanc.append((L("st.frenzy"), f"{p.frenzy_stacks}", (255, 200, 80)))
    if p.soul_stacks:
        kazanc.append((L("st.souls"), f"{p.soul_stacks}", (200, 120, 255)))
    # koşunun yemini (kademesiyle, kademe renginde)
    _oath = getattr(run, "oath", None) if run is not None else None
    if _oath in OATH_BY_KEY:
        _tier = int(getattr(run, "oath_tier", 0) or 0)
        _nm, _col = L("oath.%s.name" % _oath), OATH_BY_KEY[_oath][2]
        if _tier > 0:
            _col = rarity_color(_tier)
            _full = "%s - %s" % (_nm, rarity_name(_tier))
            # dar panelde sığmazsa yalnız ad kalır (renk kademeyi zaten söyler)
            if text_width(_full, 13, True) + text_width(L("st.oath"), 13) + 40 <= STATS_PANEL_W:
                _nm = _full
        kazanc.append((L("st.oath"), _nm, _col))

    return [(L("st.g_life"), hayat), (L("st.g_dmg"), hasar),
            (L("st.g_move"), hareket), (L("st.g_gain"), kazanc)]


# ---- koşu kartı - dünya sıralamasının ayrıntı ekranı için ----
def run_build_snapshot(run):
    """Koşunun kartı: skin, harita, silah/kitap seviyeleri, hasar dökümü ve istatistik panelinin sayıları."""
    p = run.player

    def r3(v):
        try:
            return round(float(v), 3)
        except (TypeError, ValueError):
            return 0.0
    base_dps = BASE_DMG * (1.0 + 0.05 * (1.6 - 1.0)) / BASE_ATK_CD
    st = {
        "hp": r3(p.max_hp), "regen": r3(p.eff_regen()), "armor": r3(p.eff_armor()),
        "vamp": r3(0.02 * p.vamp_level), "dmg": r3(p.eff_dmg() / max(1e-6, BASE_DMG)),
        "crit": r3(p.eff_crit_chance()), "critd": r3(p.eff_crit_dmg()),
        "aspd": r3(BASE_ATK_CD / max(1e-6, p.eff_atk_cd())),
        "dps": r3(p.estimated_dps() / max(1e-6, base_dps)),
        "multi": int(1 + p.multishot_level), "pierce": int(p.eff_pierce_hits()),
        "speed": r3(p.eff_speed() / max(1e-6, BASE_SPEED)),
        "dash": r3(BASE_DASH_CD / max(1e-6, p.eff_dash_cd())),
        "bonk": r3(BASE_BONK_CD / max(1e-6, p.eff_bonk_cd())),
        "pickup": int(p.eff_pickup()), "gold": r3(p.eff_coin_mult()),
        "xp": r3(p.eff_xp_mult()), "luck": r3(p.eff_luck()),
        "lvl": int(p.level), "bosses": int(getattr(run, "bosses_killed", 0)),
    }
    dmg = sorted(((k, int(v)) for k, v in (getattr(run, "dmg_log", None) or {}).items() if v >= 1),
                 key=lambda kv: -kv[1])[:16]
    return {
        "v": 1,
        "skin": str(p.skin.get("id", "default")),
        "map": str(getattr(run, "map_theme", "stone") or "stone"),
        "hell": run.biome == "hell",
        "w": [[k, int(lv)] for k, lv in sorted(p.weapons.items(), key=lambda kv: -kv[1]) if lv > 0][:6],
        "b": [[k, int(lv)] for k, lv in p.books.items() if lv > 0][:8],
        "d": [[k, v] for k, v in dmg],
        "st": st,
    }


# Kart istatistiklerinin ekrandaki biçimi: (anahtar, etiket, biçim, renk, grup)
BUILD_STAT_VIEW = (
    ("hp", "st.max_hp", "int", (235, 120, 150), "st.g_life"),
    ("regen", "st.regen", "regen", GREEN, "st.g_life"),
    ("armor", "st.armor", "pct", (160, 180, 220), "st.g_life"),
    ("vamp", "st.vamp", "pct", (220, 60, 90), "st.g_life"),
    ("dmg", "st.dmg", "pct", (245, 120, 110), "st.g_dmg"),
    ("crit", "st.crit", "pct", (230, 220, 120), "st.g_dmg"),
    ("critd", "st.critd", "pct", (255, 210, 130), "st.g_dmg"),
    ("aspd", "st.aspd", "pct", (150, 210, 255), "st.g_dmg"),
    ("dps", "st.dps", "pct", (255, 190, 90), "st.g_dmg"),
    ("multi", "st.multi", "int", PURPLE, "st.g_dmg"),
    ("pierce", "st.pierce", "int", RED, "st.g_dmg"),
    ("speed", "st.speed", "pct", (130, 230, 170), "st.g_move"),
    ("dash", "st.dash", "pct", (130, 225, 210), "st.g_move"),
    ("bonk", "st.bonk", "pct", (245, 150, 80), "st.g_move"),
    ("pickup", "st.pickup", "int", (150, 220, 255), "st.g_move"),
    ("gold", "st.gold", "pct", GOLD, "st.g_gain"),
    ("xp", "st.xp", "pct", PURPLE, "st.g_gain"),
    ("luck", "st.luck", "pct1", GREEN, "st.g_gain"),
)


def build_stat_text(kind, v):
    try:
        v = float(v)
    except (TypeError, ValueError):
        return "-"
    if kind == "int":
        return str(int(v))
    if kind == "regen":
        return f"{v:.1f}" + L("ui.per_sec")
    if kind == "pct1":
        return fmt_pct1(v)
    return _pct(v)


def draw_stats_panel(surf, run, t):
    """İstatistik panelini çizer ve kapladığı dikdörtgeni döndürür."""
    p = run.player
    groups = player_stat_groups(p, run)
    n_rows = sum(len(r) for _g, r in groups)
    rect = stats_panel_rect(n_rows, len(groups))
    panel(surf, rect, bg=(29, 21, 22), edge=(96, 106, 152), alpha=244, radius=11, edge_w=2)

    # ---- başlık şeridi: koyu yeşil bir künye bandı + iki yanında köşebent ----
    head = pygame.Rect(rect.x + 2, rect.y + 2, rect.w - 4, STATS_HEAD_H - 6)
    surf.blit(_stats_header(head.w, head.h), head.topleft)
    pygame.draw.line(surf, (150, 190, 160), (head.x + 6, head.bottom - 1),
                     (head.right - 6, head.bottom - 1), 1)
    draw_text(surf, L("ui.stats"), (head.x + 12, head.y + 5), 16, (226, 236, 226),
              bold=True, shadow=False)
    for sgn, ax in ((1, head.right - 11), (-1, head.x + 7)):
        pygame.draw.polygon(surf, (190, 214, 192),
                            [(ax, head.y + 5), (ax + sgn * 5, head.y + 5),
                             (ax + sgn * 5, head.y + 10), (ax, head.y + 10)], 1)

    y = rect.y + STATS_HEAD_H
    for gi, (gname, rows) in enumerate(groups):
        if gi:
            y += STATS_GROUP_GAP
            pygame.draw.line(surf, (68, 50, 51), (rect.x + 12, y - 6),
                             (rect.right - 12, y - 6), 1)
        draw_text(surf, gname, (rect.x + 13, y - 1), 9, (122, 132, 166),
                  bold=True, shadow=False)
        y += STATS_GROUP_HEAD_H
        for (label, value, col) in rows:
            draw_text(surf, label, (rect.x + 15, y), 13, (206, 211, 228), shadow=False)
            draw_text(surf, value, (rect.right - 15, y), 13, col, bold=True,
                      right=True, shadow=False)
            y += STATS_ROW_H
    return rect


def draw_stats_button(surf, run, mouse_pos, t):
    """Sağ üstteki üç nokta düğmesi (açıkken altın renginde yanar)."""
    r = stats_button_rect()
    open_ = getattr(run, "show_stats", False)
    hover = r.collidepoint(mouse_pos) if mouse_pos else False
    bg = (58, 50, 26) if open_ else ((75, 54, 56) if hover else (50, 37, 38))
    pygame.draw.rect(surf, bg, r, border_radius=7)
    ink_frame(surf, r, GOLD if open_ or hover else PANEL_EDGE, 7, 2)
    dot = GOLD if (open_ or hover) else (170, 178, 205)
    for i in (-1, 0, 1):
        pygame.draw.circle(surf, dot, (r.centerx, int(r.centery + i * 7)), 2)


_hud_bar_cache = {}


def _hud_scrim(w, h):
    """Üstteki yazıların arkasına basılan çok hafif karartma."""
    key = (w, h)
    sc = _hud_bar_cache.get(key)
    if sc is None:
        if len(_hud_bar_cache) > 8:
            _hud_bar_cache.clear()
        sc = pygame.Surface((w, h), pygame.SRCALPHA)
        for yy in range(h):
            f = yy / max(1, h - 1)
            a = int(lerp(104, 0, f ** 0.75))
            if a <= 0:
                continue
            pygame.draw.line(sc, (6, 7, 14, a), (0, yy), (w, yy))
        _hud_bar_cache[key] = sc
    return sc


_HUD_PLATE_CACHE = {}


def _hud_plate(w, h, edge, hellish=False):
    """HUD plakası: yarı saydam, mürekkep konturlu, iki perçinli levha."""
    key = (int(w), int(h), tuple(edge), bool(hellish))
    sc = _HUD_PLATE_CACHE.get(key)
    if sc is None:
        if len(_HUD_PLATE_CACHE) > 24:
            _HUD_PLATE_CACHE.clear()
        w, h = int(w), int(h)
        sc = hand_card(w, h, (54, 20, 20) if hellish else (34, 26, 28), edge=edge, rad=12,
                       alpha=196).copy()
        for x_ in (10, w - 10):
            pygame.draw.circle(sc, (*edge, 200), (x_, h // 2), 2)
        _HUD_PLATE_CACHE[key] = sc
    return sc


_HUD_TOP_MOB = {}


def draw_hud(surf, run, t):
    """Üst bilgi şeridi + ekranın ortasındaki duyurular."""
    if MOBILE:
        # Üst bilgi ile küçük harita + anahtar sayacı iki ayrı hazır görüntü; 8
        # karede bir, farklı karelerde tazelenir.
        size = (VIRTUAL_W, HUD_TOP_H)
        mob_layer(surf, "hud_top", run, t, 0, size, lambda b: _draw_hud_top(b, run, t))
        mob_layer(surf, "hud_map", run, t, 2, size,
                  lambda b: (draw_minimap(b, run, t), _draw_key_counter(b, run, t)))
    else:
        _draw_hud_top(surf, run, t)
    _draw_hud_center(surf, run, t)
    if getattr(run, "coop_others", None):
        draw_coop_hud(surf, run, t)       # 2 kişilik - arkadaşın kartı


HUD_TOP_H = 236          # telefon önbelleği: üst şerit + küçük harita + anahtar sayacı
_MOB_LAYERS = {}


def mob_layer(surf, name, run, t, phase, size, draw, period=8):
    """telefon: HUD'un bir katmanını hazır görüntüde tutar."""
    global _GLOW_ON_ALPHA
    c = _MOB_LAYERS.get(name)
    if c is None:
        c = _MOB_LAYERS[name] = {}
    if not (c.get("run") is run and c.get("size") == size and (_MOB_FRAME[0] % period) != phase
            and abs(t - c.get("t", -9)) < 0.5):
        buf = c.get("work")
        if buf is None or buf.get_size() != size:
            buf = pygame.Surface(size, pygame.SRCALPHA)
            c["work"] = buf
        buf.fill((0, 0, 0, 0))
        _GLOW_ON_ALPHA = True
        try:
            draw(buf)
        finally:
            _GLOW_ON_ALPHA = False
        # Tampon dikey dilimlere bölünür ve her dilimin yalnız dolu kısmı
        # saklanır: RLE kodlamasının maliyeti alanla orantılı; üst bilgi gibi
        # iki ucu dolu, ortası boş katmanlarda alan ~3 kat küçülür.
        parts = []
        W, H = size
        n = c.get("n", 0)
        rects = c.get("rects")
        if rects is None or n % 12 == 0 or c.get("size") != size:
            rects = []
            for x0 in range(0, W, 192):
                tw = min(192, W - x0)
                br = buf.subsurface((x0, 0, tw, H)).get_bounding_rect()
                if br.w > 0 and br.h > 0:
                    rects.append(br.move(x0, 0).inflate(12, 12).clip(pygame.Rect(x0, 0, tw, H)))
            c["rects"] = rects
        c["n"] = n + 1
        for rc in rects:
            parts.append((mob_rle(buf.subsurface(rc).copy()), rc.topleft))
        c.update(parts=parts, run=run, size=size, t=t)
    parts = c.get("parts")
    if parts:
        _fast_blits(surf, parts)
_FLAT_OV = {}


_EDGE_OV = {}


def _edge_overlay(surf, col, alpha):
    """telefon: tam ekran renk örtüsü yerine kenarlardan içe sönen çerçeve."""
    a = int(alpha) // 16 * 16
    if a <= 0:
        return
    key = (col, a)
    img = _EDGE_OV.get(key)
    if img is None:
        if len(_EDGE_OV) > 40:
            _EDGE_OV.clear()
        img = pygame.Surface((VIRTUAL_W, VIRTUAL_H), pygame.SRCALPHA)
        band = 110
        for i in range(band // 6):
            k = 1.0 - i / (band / 6)
            aa = int(min(255, a * 1.6) * k * k)
            if aa <= 0:
                continue
            pygame.draw.rect(img, (col[0], col[1], col[2], aa),
                             pygame.Rect(i * 6, i * 6, VIRTUAL_W - i * 12, VIRTUAL_H - i * 12), 6)
        img = mob_rle(img)
        _EDGE_OV[key] = img
    surf.blit(img, (0, 0))


def _flat_overlay(surf, col, alpha):
    alpha = int(clamp(alpha, 0, 255))
    if alpha <= 0:
        return
    col = (int(col[0]), int(col[1]), int(col[2]))
    if MOBILE:
        _edge_overlay(surf, col, alpha)
        return
    col = (int(col[0]), int(col[1]), int(col[2]))
    s = _FLAT_OV.get(col)
    if s is None:
        if len(_FLAT_OV) > 8:
            _FLAT_OV.clear()
        s = pygame.Surface((VIRTUAL_W, VIRTUAL_H)).convert() if pygame.display.get_surface() \
            else pygame.Surface((VIRTUAL_W, VIRTUAL_H))
        s.fill(col)
        _FLAT_OV[col] = s
    s.set_alpha(alpha)
    surf.blit(s, (0, 0))


def _draw_hud_top(surf, run, t):
    p = run.player
    # Yerinde yalnızca yazıların okunabilmesi için aşağı doğru sönen çok soluk
    # bir gölge var; arena ekranın en üstüne kadar görünüyor.
    if not MOBILE:
        surf.blit(_hud_scrim(VIRTUAL_W, ARENA_MARGIN_TOP + 14), (0, 0))
    # üç bilgi kümesinin arkasına ince altın kenarlı plakalar
    hellish_ = run.biome == "hell"
    pedge = (150, 80, 60) if hellish_ else (150, 124, 80)
    surf.blit(_hud_plate(306, 74, pedge, hellish_), (2, 4))
    surf.blit(_hud_plate(300, 74, pedge, hellish_), (VIRTUAL_W / 2 - 150, 2))
    # Sağ kenarı sabit, sola doğru büyür.
    _rx = VIRTUAL_W - 48
    _sc_txt = L("ui.score", fmt_num(run.score))
    _kl_txt = L("ui.kills", fmt_num(run.kills))
    _pw = max(text_width(_sc_txt, 16, True), text_width(_kl_txt, 13, False)) + 44
    _pw = int(math.ceil(max(118, _pw) / 8.0) * 8)
    _plate_x = _rx + 12 - _pw
    surf.blit(_hud_plate(_pw, 46, pedge, hellish_), (_plate_x, 5))

    hp_rect = pygame.Rect(18, 14, 248, 20)
    frac = clamp(p.hp / p.max_hp, 0, 1)
    hp_col = GREEN if frac > 0.5 else (ORANGE if frac > 0.25 else RED)
    # can azalınca çubuk nabız gibi atsın
    if frac < 0.35:
        add_glow(surf, hp_rect.centerx, hp_rect.centery, 130, RED,
                 0.10 + 0.10 * (0.5 + 0.5 * math.sin(t * 6)))
    draw_bar(surf, hp_rect, frac, hp_col)
    # dörtte bir çentikleri
    for q in (0.25, 0.5, 0.75):
        qx = hp_rect.x + int(hp_rect.w * q)
        pygame.draw.line(surf, (26, 19, 19), (qx, hp_rect.y + 3), (qx, hp_rect.bottom - 3), 1)
    # çubuğun üst yarısına cam parlaması
    gl = pygame.Surface((hp_rect.w - 4, hp_rect.h // 2 - 1), pygame.SRCALPHA)
    gl.fill((255, 255, 255, 26))
    surf.blit(gl, (hp_rect.x + 2, hp_rect.y + 2))
    draw_text(surf, f"{int(p.hp)}/{int(p.max_hp)}", hp_rect.center, 14, WHITE, bold=True, center=True)
    draw_icon(surf, hp_rect.x - 12, hp_rect.centery, "heart", RED, 12)

    xp_rect = pygame.Rect(18, 40, 248, 10)
    draw_bar(surf, xp_rect, p.xp / p.xp_to_next, PURPLE, radius=5)
    # seviye rozeti: sayı düz yazı yerine mor bir madalyonda
    lv_txt = f"LV {p.level}"
    lv_r = pygame.Rect(0, 0, text_width(lv_txt, 14, True) + 18, 19)
    lv_r.midleft = (xp_rect.right + 8, xp_rect.centery)
    pygame.draw.rect(surf, (28, 20, 44), lv_r, border_radius=9)
    ink_frame(surf, lv_r, PURPLE, 9, 1)
    draw_text(surf, lv_txt, lv_r.center, 14, PURPLE, bold=True, center=True, shadow=False)

    draw_coin_label(surf, 18 + coin_label_width(fmt_num(run.gold_wallet), 15, 7) / 2,
                    62, fmt_num(run.gold_wallet), GOLD, 15, icon_r=7)

    # ---- patron durum etkileri: altının sağında küçük sayaçlar ----
    st_x = 136
    for (act, icon, scol, label) in ((p.burn_t, "flame", (255, 150, 70), "YANIK"),
                                     (p.poison_t, "drop", (150, 240, 120), "ZEHİR"),
                                     (p.slow_t, "snow", (150, 210, 255), "YAVAŞ")):
        if act <= 0:
            continue
        chip = pygame.Rect(st_x, 54, 74, 18)
        cs = pygame.Surface(chip.size, pygame.SRCALPHA)
        pygame.draw.rect(cs, (*scol, 52), cs.get_rect(), border_radius=6)
        pygame.draw.rect(cs, (*scol, 190), cs.get_rect(), width=1, border_radius=6)
        surf.blit(cs, chip.topleft)
        draw_icon(surf, chip.x + 11, chip.centery, icon, scol, 6)
        draw_text(surf, f"{label} {act:0.1f}", (chip.x + 20, chip.y + 3), 10, scol,
                  bold=True, shadow=False)
        st_x += 80

    draw_text(surf, fmt_time(run.run_time), (VIRTUAL_W / 2, 18), 26, TEXT, bold=True, center=True)
    for sgn in (-1, 1):          # saatin iki yanında küçük süs çizgileri
        x0 = VIRTUAL_W / 2 + sgn * 52
        pygame.draw.line(surf, pedge, (x0, 18), (x0 + sgn * 40, 18), 1)
        circle_aa(surf, x0 + sgn * 44, 18, 2.2, pedge)

    w = run.waves
    if run.bosses:
        n = len([b for b in run.bosses if b.alive])
        champ = max([int(getattr(b, "champion", 1)) for b in run.bosses] or [1])
        label = (L("ui.champ_boss") if champ > 1 else L("ui.boss_wave")) if n <= 1 \
            else "%s  ×%d" % (L("ui.boss_wave"), n)
        draw_text(surf, label, (VIRTUAL_W / 2, 41), 15, RED, bold=True, center=True)
        # patron varken de dalga saati işler
        draw_text(surf, L("ui.boss_wave_clock", w.wave, fmt_time(w.time_left())),
                  (VIRTUAL_W / 2, 61), 11, TEXT_DIM, center=True, shadow=False)
    else:
        # dalga süreyle ilerler; şerit dalganın geçen süresini, alttaki yazı
        # sonraki dalgaya kalan süreyi gösterir.
        surge = w.surge_active()
        next_is_boss = w.is_boss_wave(w.wave + 1)
        hellish = run.biome == "hell"
        wave_col = ORANGE if surge else (GOLD if next_is_boss else
                                         ((255, 130, 80) if hellish else CYAN))
        head = (L("ui.hell_wave", (str(w.wave) if HELL_FINAL_WAVE is None else
                                   "%d/%d" % (w.wave, HELL_FINAL_WAVE))) if hellish
                else L("ui.wave", w.wave))
        if run.hell_portal is not None and not hellish:
            head += "   " + L("ui.portal_open_hud", key_label_short("use"))
        if next_is_boss:
            head += "   " + L("ui.next_boss_hud")
        draw_text(surf, head, (VIRTUAL_W / 2, 40), 14, wave_col, bold=True, center=True)

        gbar = pygame.Rect(VIRTUAL_W / 2 - 120, 52, 240, 7)
        draw_bar(surf, gbar, w.goal_progress(), wave_col,
                 bg=(32, 23, 24), border=(88, 65, 67), radius=4)
        # dolan şeridin ucunda parlayan nokta
        gx = gbar.x + int(gbar.w * clamp(w.goal_progress(), 0.0, 1.0))
        add_glow(surf, gx, gbar.centery, 12, wave_col, 0.35 + 0.15 * math.sin(t * 6))
        circle_aa(surf, gx, gbar.centery, 3.0, lighten(wave_col, 0.4))
        draw_text(surf, L("ui.next_wave_in", fmt_time(w.time_left())),
                  (VIRTUAL_W / 2, 64), 10, TEXT_DIM, center=True, shadow=False)
        if surge:
            draw_text(surf, L("ui.surge", f"{w.surge_timer:0.1f}"), (gbar.right + 10, 49), 12,
                      ORANGE, bold=True, shadow=False)
    if getattr(run, "curse_score_bonus", 0) > 0:
        ctxt = L("cu.hud", "%.2f" % (1.0 + run.curse_score_bonus) if lang() != "tr"
                 else ("%.2f" % (1.0 + run.curse_score_bonus)).replace(".", ","))
        cw_ = text_width(ctxt, 11, True) + 30
        cr_ = pygame.Rect(0, 0, cw_, 18)
        cr_.midleft = (VIRTUAL_W / 2 + 70, 19)     # zamanın sağında
        cs_ = pygame.Surface(cr_.size, pygame.SRCALPHA)
        pygame.draw.rect(cs_, (*CURSE_COLOR, 46), cs_.get_rect(), border_radius=9)
        pygame.draw.rect(cs_, (*CURSE_COLOR, 200), cs_.get_rect(), width=1, border_radius=9)
        surf.blit(cs_, cr_.topleft)
        draw_icon(surf, cr_.x + 11, cr_.centery, "skull", CURSE_COLOR2, 6)
        draw_text(surf, ctxt, (cr_.x + 21, cr_.y + 3), 11, CURSE_COLOR2, bold=True, shadow=False)

    # Sağ üstteki "⋮" istatistik düğmesine yer açmak için biraz sola
    # kaydırıldı.
    rx = _rx
    draw_text(surf, _sc_txt, (rx, 11), 16, TEXT, bold=True, right=True)
    draw_text(surf, _kl_txt, (rx, 32), 13, TEXT_DIM, right=True)
    draw_icon(surf, _plate_x + 17, 19, "star", GOLD, 8)
    draw_icon(surf, _plate_x + 17, 39, "skull", TEXT_DIM, 6)
    # zırh delme rozeti: düşmanlar zırhının ne kadarını yok sayıyor
    pc = getattr(p, "armor_pierce", 0.0)
    if pc > 0.001:
        ptxt = L("ui.pierce_chip", int(round(pc * 100)))
        pw_ = text_width(ptxt, 10, True) + 26
        pr_ = pygame.Rect(0, 56, pw_, 16)
        pr_.right = _rx + 12
        pcs = pygame.Surface(pr_.size, pygame.SRCALPHA)
        pygame.draw.rect(pcs, (255, 120, 80, 46), pcs.get_rect(), border_radius=8)
        pygame.draw.rect(pcs, (255, 140, 100, 190), pcs.get_rect(), width=1, border_radius=8)
        surf.blit(pcs, pr_.topleft)
        draw_icon(surf, pr_.x + 10, pr_.centery, "shield", (255, 160, 120), 5)
        draw_text(surf, ptxt, (pr_.x + 18, pr_.y + 2), 10, (255, 180, 150), bold=True, shadow=False)

    icon_x = rx
    badges = []
    if p.fire_level: badges.append(("bolt", ORANGE, p.fire_level))
    if p.ice_level: badges.append(("target", CYAN, p.ice_level))
    if p.shield_charges: badges.append(("shield", (160, 170, 200), p.shield_charges))
    if p.pierce_bonus: badges.append(("sword", RED, p.pierce_bonus))
    if p.multishot_level: badges.append(("star", PURPLE, p.multishot_level))
    if p.explosive_level: badges.append(("star", (240, 110, 60), p.explosive_level))
    if p.vamp_level: badges.append(("heart", (220, 60, 90), max(1, int(round(p.vamp_level)))))
    if p.thorns_level: badges.append(("shield", (170, 125, 90), p.thorns_level))
    if p.chain_level: badges.append(("bolt", (120, 200, 255), p.chain_level))
    if p.homing_level: badges.append(("target", (140, 220, 200), p.homing_level))
    if p.orbit_level: badges.append(("orbit", (150, 220, 255), p.orbit_level))
    if p.storm_level: badges.append(("bolt", (190, 215, 255), p.storm_level))
    if p.second_wind_charges: badges.append(("heart", GOLD, p.second_wind_charges))
    if p.holy_flame: badges.append(("cross", (255, 235, 150), p.holy_flame))
    if p.soul_harvest: badges.append(("skull", (200, 120, 255), p.soul_harvest))
    if p.angel_wing: badges.append(("boot", (220, 240, 255), p.angel_wing))
    if p.purgatory_level: badges.append(("shield", (255, 215, 120), p.purgatory_level))
    if p.execute_threshold > 0: badges.append(("sword", GOLD, round(p.execute_threshold * 100)))
    by = 62
    for kind, col, lvl in badges[:14]:
        icon_x -= 26
        draw_icon(surf, icon_x, by, kind, col, 11)
        draw_text(surf, f"x{lvl}", (icon_x + 12, by + 6), 11, col, shadow=False)


def _draw_hud_center(surf, run, t):
    p = run.player
    frac = clamp(p.hp / p.max_hp, 0, 1)
    dy = 16 if MOBILE else 0
    if p.frenzy_stacks > 0:
        draw_text(surf, L("ui.frenzy", p.frenzy_stacks), (VIRTUAL_W / 2, 96 + dy * 1.6), 14, (255, 200, 80), bold=True, center=True)

    if run.combo.count >= 3:
        pulse = 1 + run.combo.pulse * 0.4
        size = int(20 * pulse)
        col = GOLD if run.combo.count >= 20 else (ORANGE if run.combo.count >= 10 else CYAN)
        draw_text(surf, L("ui.combo", run.combo.count), (VIRTUAL_W / 2, 76 + dy), size, col, bold=True, center=True)
        br = pygame.Rect(VIRTUAL_W / 2 - 80, 94 + dy, 160, 5)
        draw_bar(surf, br, run.combo.timer / run.combo.window, col, radius=3)

    if run.waves.announce_timer > 0 and run.waves.announce_text:
        a = clamp(run.waves.announce_timer / 2.2, 0, 1)
        alpha = int(255 * min(1, a * 2))
        scale_t = ease_out_cubic(1 - a)
        size = int(lerp(64, 44, scale_t))
        if "PATRON" in run.waves.announce_text:
            col = RED
        elif "YOĞUNLUK" in run.waves.announce_text:
            col = ORANGE
        else:
            col = CYAN
        draw_text(surf, run.waves.announce_text, (VIRTUAL_W / 2, VIRTUAL_H / 2 - 40), size, col,
                  bold=True, center=True, alpha=alpha)

    if frac < 0.3 and p.alive:
        pulse = (math.sin(t * 8) + 1) / 2
        # Tek renkli tam ekran örtü: her karede yeni saydam yüzey açmak yerine
        # önbellekteki düz yüzey, yüzey-alfasıyla basılır (aynı görüntü).
        _flat_overlay(surf, (180, 0, 0), int(40 * pulse * (1 - frac / 0.3 + 0.3)))

    if run.fx.flash > 0:
        _flat_overlay(surf, run.fx.flash_col, int(run.fx.flash * 130))

    if run.ach:
        run.ach.draw(surf)


def draw_invisible_player(world, p, t):
    """Görünmezlik pelerini açıkken oyuncunun hayalet hâli."""
    size = 260
    tmp = pygame.Surface((size, size), pygame.SRCALPHA)
    ox, oy = p.x, p.y
    p.x, p.y = size * 0.5, size * 0.5
    try:
        p.draw(tmp, t)
    except Exception:
        p.x, p.y = ox, oy
        p.draw(world, t)         # beklenmedik bir durumda normal çizime dön
        return
    p.x, p.y = ox, oy
    # Süre biterken yavaşça geri belirir: oyuncu ne zaman görüneceğini görsün.
    fade = clamp(p.invis_t / 1.2, 0.0, 1.0)
    tmp.set_alpha(int(lerp(150, 66, fade)))
    world.blit(tmp, (ox - size * 0.5, oy - size * 0.5))
    # çevresinde dönen gizlilik halkası + savrulan zerreler
    pulse = 0.5 + 0.5 * math.sin(t * 3.4)
    add_glow(world, ox, oy, 54, CLOAK_COLOR, 0.18 + 0.10 * pulse)
    for i in range(10):
        a = t * 1.6 + i * math.tau / 10
        rr = 30 + 6 * math.sin(t * 2.6 + i)
        circle_aa(world, ox + math.cos(a) * rr, oy + math.sin(a) * rr * 0.6,
                  1.6 + 1.2 * ((i + int(t * 3)) % 3 == 0), CLOAK_COLOR2)


# Sıralamada zorluk rozeti.
DIFF_BADGE = {"nightmare": ((255, 120, 110), (62, 22, 26)),
              "hard": ((255, 186, 96), (56, 38, 18)),
              "normal": ((150, 190, 235), (22, 32, 50))}


def _lb_diff_badge(surf, cx, y, diff):
    """Sıralamada zorluk rozeti - yalnızca zor/kabus için çizilir."""
    d = str(diff or "normal")
    if d not in DIFF_BADGE or d == "normal":
        return
    fg, bg = DIFF_BADGE[d]
    txt = LX("diff." + d, DIFF_LABEL.get(d, d))
    w = int(text_width(txt, 9, True)) + 14
    r = pygame.Rect(int(cx - w / 2), int(y), w, 14)
    pygame.draw.rect(surf, bg, r, border_radius=7)
    ink_frame(surf, r, fg, 7, 1)
    draw_text(surf, txt, r.center, 9, fg, bold=True, center=True, shadow=False)


def _fast_blits(surf, seq):
    """Toplu blit: pygame-ce'de fblits (en hızlı), değilse blits."""
    f = getattr(surf, "fblits", None)
    if f is not None:
        f(seq)
    else:
        surf.blits(seq, doreturn=False)


def _enemy_y(e):
    return e.y


_HPBAR_CACHE = {}
_SRING_CACHE = {}


def _hpbar_sprite(w, b):
    """telefon: yaratık can çubuğu (ortak, 24 dilim)."""
    key = (w, b)
    img = _HPBAR_CACHE.get(key)
    if img is None:
        if len(_HPBAR_CACHE) > 600:
            _HPBAR_CACHE.clear()
        img = pygame.Surface((max(1, w), 4), pygame.SRCALPHA)
        pygame.draw.rect(img, (48, 38, 39), (0, 0, w, 4), border_radius=2)
        frac = b / 24.0
        hc = GREEN if frac > 0.5 else (ORANGE if frac > 0.25 else RED)
        if b > 0:
            pygame.draw.rect(img, hc, (0, 0, max(1, int(w * frac)), 4), border_radius=2)
        img = mob_rle(img)
        _HPBAR_CACHE[key] = img
    return img


def _status_ring_sprite(r, slow, burn, poison):
    """telefon: yavaşlama / yanma / zehir halkaları (ortak)."""
    key = (r, slow, burn, poison)
    img = _SRING_CACHE.get(key)
    if img is None:
        if len(_SRING_CACHE) > 300:
            _SRING_CACHE.clear()
        R_ = r + 10
        img = pygame.Surface((R_ * 2, R_ * 2), pygame.SRCALPHA)
        if slow:
            pygame.draw.circle(img, CYAN, (R_, R_), r + 4, 1)
        if burn:
            pygame.draw.circle(img, ORANGE, (R_, R_), r + 6, 1)
        if poison:
            pygame.draw.circle(img, (120, 225, 90), (R_, R_), r + 8, 1)
        img = mob_rle(img)
        _SRING_CACHE[key] = img
    return img


def _draw_enemies_fast(world, ens, t):
    """telefon: sıradan yaratıklar toplu blit (fblits) ile çizilir."""
    tick = Enemy._spr_tick[0]
    batch = []
    flash = None
    for e in sorted(ens, key=_enemy_y):
        if (e.spawn_t < 0.3 or e.phased or e.rage > 0 or e.mutant or e.kind == "kamikaze"):
            if batch:
                _fast_blits(world, batch)
                batch = []
            e.draw(world, t)
            continue
        stg = e.__dict__.get("_stg")
        if stg is None:
            stg = e._stg = (id(e) >> 4) % 3
        if e._spr is None or (tick + stg) % 3 == 0:
            if e._atlas_ok():
                e._ensure_shared(t, e.radius)
            else:
                e._ensure_spr(t, e.radius)
        x, y = int(e.x), int(e.y)
        batch.append((e._spr, (x - e._spr_off[0], y - e._spr_off[1])))
        if e.__dict__.get("_spr_shared"):
            # ortak gövdeye gömülmeyen kişisel katmanlar: durum halkaları, can
            # çubuğu
            rr = e.radius
            if e.slow_timer > 0 or e.burn_timer > 0 or e.poison_dps > 0:
                rs = _status_ring_sprite(int(rr), e.slow_timer > 0, e.burn_timer > 0, e.poison_dps > 0)
                batch.append((rs, (x - rs.get_width() // 2, y - rs.get_height() // 2)))
            if e.hp < e.max_hp:
                w = int(rr * 2)
                hb = _hpbar_sprite(w, int(clamp(e.hp / e.max_hp, 0.0, 1.0) * 24))
                batch.append((hb, (int(e.x - w / 2), int(e.y - rr - 12))))
        if e.hit_flash > 0:
            r = max(1, int(e.radius * 0.9))
            if r > 14:
                r = r // 4 * 4
            if flash is None:
                flash = {}
            d = flash.get(r)
            if d is None:
                d = flash[r] = disc_sprite(r, (255, 255, 255), 90)
            batch.append((d, (x - r, y - r)))
    if batch:
        _fast_blits(world, batch)


def draw_run(surf, run, t, aim_pos=None, shake=(0, 0)):
    """Koşuyu çizer."""
    world = world_surface()
    cam = run.cam_rect()
    prev_clip = world.get_clip()
    world.set_clip(cam)

    draw_world_floor(world, cam, run_floor_key(run), t)

    if run.hell_portal is not None:
        run.hell_portal.draw(world, t)
    # lanetli sandık (mağara ağzı) - zeminde, yaratıkların altında
    _csh = getattr(run, "cursed_shrine", None)
    if _csh is not None and cam.inflate(400, 400).collidepoint(_csh.x, _csh.y):
        _csh.draw(world, t)
    draw_world_extras(world, run, cam, t)
    # gezgin tüccar (haritada işaretlenmez; oyuncu bulur)
    _mer = getattr(run, "merchant", None)
    if _mer is not None and cam.inflate(400, 400).collidepoint(_mer.x, _mer.y):
        _mer.draw(world, t)
    # ekran dışını çizme.
    vis_near = cam.inflate(200, 200)        # küçük nesneler (eşya, yaratık)
    vis_far = cam.inflate(900, 900)         # geniş alanlar (su, ateş, mühür)

    for hz in run.hazards:
        if vis_far.collidepoint(hz.x, hz.y):
            hz.draw(world, t)
    # ---- zemine çizilen silah alanları (varlıkların altında kalır) ----
    # silah görselleri açık / kısık / kapalı (Ayarlar). Hasar aynen işler;
    # yalnızca çizim değişir.
    _fxm = weapon_fx_mode()
    _pw = run.player.weapons
    _coop_o = getattr(run, "coop_others", None)
    if _coop_o:
        # 2 kişilik: öbür oyuncunun silahları da çizim katmanlarını açsın
        _pw = dict(_pw)
        for _op in _coop_o:
            for _k, _v in getattr(_op, "weapons", {}).items():
                _pw[_k] = max(_pw.get(_k, 0), _v)
    if _fxm != "off":
        _snap = _wfx_begin(world, cam, _pw.get("pentagram", 0) > 0
                           or bool(run.water_zones) or bool(run.fire_rings)
                           or bool(run.meteors))
        draw_pentagram_field(world, run.player, t)
        if _coop_o:
            draw_coop_world(world, run, t, "ground")
        for mt in run.meteors:
            if vis_far.collidepoint(mt.x, mt.y):
                mt.draw_ground(world, t)
        for qk in run.quakes:
            qk.draw(world, t)
        for wz in run.water_zones:
            if vis_far.collidepoint(wz.x, wz.y):
                wz.draw(world, t)
        for fr in run.fire_rings:
            if vis_far.collidepoint(fr.x, fr.y):
                fr.draw(world, t)
        _wfx_end(world, _snap)
    for bh in getattr(run, "black_holes", ()):
        draw_black_hole(world, bh, t)
    if MOBILE:
        # Telefon: yerdeki altın/tecrübe tek bir toplu blit (fblits) ile.
        _bt = []
        _bob = t * 4
        for pu in run.pickups:
            if vis_near.collidepoint(pu.x, pu.y):
                img = _pickup_sprite(pu.kind)
                _bt.append((img, (int(pu.x) - img.get_width() // 2,
                                  int(pu.y + math.sin(_bob + pu.bob) * 2.5) - img.get_height() // 2)))
        if _bt:
            _fast_blits(world, _bt)
    else:
        for pu in run.pickups:
            if vis_near.collidepoint(pu.x, pu.y):
                pu.draw(world, t)
    for mg in run.magnets:
        if vis_far.collidepoint(mg.x, mg.y):
            mg.draw(world, t)
    for lv in run.level_drops:
        if vis_far.collidepoint(lv.x, lv.y):
            lv.draw(world, t)
    for ch in run.chests:
        ch.draw(world, t)
    # anahtarlar + efsanevi sandık
    for mk in getattr(run, "map_keys", ()):
        if vis_far.collidepoint(mk.x, mk.y):
            mk.draw(world, t)
    _lc = getattr(run, "legend_chest", None)
    if _lc is not None and vis_far.collidepoint(_lc.x, _lc.y):
        _lc.draw(world, t)
    # Kalkan kitaplarının yörüngesinin arka yarısı oyuncudan önce çizilir.
    if _fxm != "off":
        _snap = _wfx_begin(world, cam, _pw.get("book", 0) > 0)
        draw_shield_books(world, run.player, t, layer="back")
        if _coop_o:
            draw_coop_world(world, run, t, "back")
        _wfx_end(world, _snap)
    _vis_en = [e for e in run.enemies if vis_near.collidepoint(e.x, e.y)]
    Enemy._spr_budget[0] = int(clamp(len(_vis_en) * 0.36, Enemy.SPR_BUDGET, Enemy.SPR_BUDGET_MAX))
    Enemy._spr_tick[0] += 1
    if MOBILE:
        _draw_enemies_fast(world, _vis_en, t)
    else:
        for e in sorted(_vis_en, key=lambda e: e.y):
            e.draw(world, t)
    for b in sorted(run.bosses, key=lambda b: b.y):
        if b.alive:
            b.draw(world, t)
    for proj in run.enemy_projectiles:
        if vis_near.collidepoint(proj.x, proj.y):
            proj.draw(world, t)
    for proj in run.player_projectiles:
        if vis_near.collidepoint(proj.x, proj.y):
            proj.draw(world, t)
    if _coop_o:
        draw_coop_world(world, run, t, "body")
    if run.player.alive:
        if getattr(run.player, "invis_t", 0.0) > 0:
            draw_invisible_player(world, run.player, t)
        else:
            run.player.draw(world, t)
    # ---- pet: oyuncunun yanında gezer (yalnızca görünüş) ----
    draw_run_pet(world, run, t)
    draw_evo_orbs(world, run, t)
    # ---- oyuncunun üstüne çizilenler ----
    if _fxm != "off":
        _snap = _wfx_begin(world, cam, _pw.get("book", 0) > 0 or bool(run.flying_axes)
                           or bool(run.whip_lashes) or bool(run.sword_slashes)
                           or bool(run.tornados) or bool(run.ghost_blades)
                           or bool(run.wolves) or bool(run.meteors) or bool(run.beams)
                           or bool(run.hawks) or bool(run.bats) or bool(run.novas)
                           or bool(run.knives))
        draw_shield_books(world, run.player, t, layer="front")
        if _coop_o:
            draw_coop_world(world, run, t, "front")
        # kurtlar, ışın, hayalet kılıçlar, düşen göktaşları
        for wf in run.wolves:
            if vis_near.collidepoint(wf.x, wf.y):
                wf.draw(world, t)
        for bm in run.beams:
            bm.draw(world, t)
        for gb in run.ghost_blades:
            if vis_near.collidepoint(gb.x, gb.y):
                gb.draw(world, t)
        for mt in run.meteors:
            if vis_far.collidepoint(mt.x, mt.y):
                mt.draw(world, t)
        # 2. paket
        for nv in run.novas:
            nv.draw(world, t)
        for kn in run.knives:
            if vis_near.collidepoint(kn.x, kn.y):
                kn.draw(world, t)
        for bt in run.bats:
            if vis_near.collidepoint(bt.x, bt.y):
                bt.draw(world, t)
        for hk in run.hawks:
            if vis_near.collidepoint(hk.x, hk.y):
                hk.draw(world, t)
        for ax in run.flying_axes:
            if vis_near.collidepoint(ax.x, ax.y):
                ax.draw(world, t)
        for wl in run.whip_lashes:
            if vis_far.collidepoint(wl.x, wl.y):
                wl.draw(world, t)
        for sl in run.sword_slashes:
            if vis_far.collidepoint(sl.x, sl.y):
                sl.draw(world, t)
        # Hortum en üstte: huni ekranın yukarısına doğru uzanıyor.
        for tn in run.tornados:
            if vis_far.collidepoint(tn.x, tn.y):
                tn.draw(world, t)
        _wfx_end(world, _snap)
    run.fx.draw(world)
    if _csh is not None and run.player.alive:
        _csh.draw_prompt(world, t, run.player)
    if _mer is not None and run.player.alive:
        _mer.draw_prompt(world, t, run.player)
    run.fx.draw_texts(world)          # hasar sayıları da dünya koordinatında
    world.set_clip(prev_clip)

    _tgt, _ox = surf, 0
    if SAFE_X and surf.get_parent() is not None:
        # Telefon: dünya güvenli alanın dışına da (çentiğin altına) uzanır.
        _tgt, _ox = surf.get_parent(), surf.get_offset()[0]
    _tgt.blit(world, (VIEW_RECT.x + _ox + int(shake[0]), VIEW_RECT.y + int(shake[1])), cam)


    draw_offscreen_markers(surf, run, cam, t)
    _MOB_FRAME[0] += 1
    draw_hud(surf, run, t)
    if not MOBILE:              # telefonda ikisi de draw_hud'un hazır görüntüsünde
        draw_minimap(surf, run, t)
        _draw_key_counter(surf, run, t)
    # M ile açılan büyük harita: küçük haritanın aynısı, ekranın ortasında.
    # Oyun bu sırada durmaz - harita bir mola değil, bir bakış.
    if getattr(run, "show_map", False):
        draw_minimap(surf, run, t, big=True)
    draw_team_strips(surf, run, t)
    draw_extras_hud(surf, run, t)
    draw_evo_banner(surf, run, t)
    if not MOBILE:
        draw_skill_bar(surf, run, t)     # telefonda düğmeler sağ altta (TouchUI)
    # istatistik paneli en üstte çizilir: açıkken küçük haritayı örter.
    draw_stats_button(surf, run, aim_pos, t)
    if getattr(run, "show_stats", False):
        draw_stats_panel(surf, run, t)

    # (nişangah burada değil, her ekranda tek yerden çiziliyor -)


# seviye atlama kart seçimi

# ---- simge önbelleği (HUD) ----
# Silah simgeleri elle çizilmiş vektör şekiller: her biri 20-60 çizim çağrısı.
_sigil_cache = {}


def sigil_sprite(key, r, col):
    r = max(4, int(r))
    col = (int(col[0]), int(col[1]), int(col[2]))
    ck = (key, r, col)
    s = _sigil_cache.get(ck)
    if s is None:
        if len(_sigil_cache) > 320:
            _sigil_cache.clear()
        pad = int(r * 2.4) + 8
        global _GLOW_ON_ALPHA
        _GLOW_ON_ALPHA = True
        try:
            # 2 kat çizip küçültmek denendi, ince parlamalar sönükleşti.
            # Asıl bulanıklık ekran ölçeklemesindeydi.
            s = pygame.Surface((pad * 2, pad * 2), pygame.SRCALPHA)
            draw_weapon_sigil(s, pad, pad, r, key, col, 0.0)
        finally:
            _GLOW_ON_ALPHA = False
        _sigil_cache[ck] = s
    return s


def blit_sigil(surf, cx, cy, r, key, col):
    """Önbellekten simge basar (HUD için)."""
    s = sigil_sprite(key, r, col)
    w = s.get_width() // 2
    surf.blit(s, (int(cx) - w, int(cy) - w))


def draw_weapon_sigil(surf, cx, cy, r, key, col, t=0.0):
    """Silaha özel, elle çizilmiş sembol."""
    lite = lighten(col, 0.45)
    dark = scale_col(col, 0.58)
    # Malzeme tonları, gelen rengin parlaklığına göre kısılır.
    lum = (col[0] + col[1] + col[2]) / 765.0
    sh = clamp(0.42 + 0.80 * lum, 0.42, 1.0)
    steel = scale_col((214, 226, 244), sh)
    steel_d = scale_col((84, 96, 120), sh)
    gold = scale_col((232, 190, 96), sh)
    timber = scale_col((156, 108, 62), sh)

    if key == "axe":
        # ---- savaş baltası ----
        # Dik duran ahşap sap + üstüne oturan sakallı (bearded) tek ağızlı baş.
        tilt = -0.30 + math.sin(t * 1.5) * 0.04

        def P(px, py):
            # rot ilk iki değeri yerel sapma sayar, (cx, cy) ise merkezdir.
            return rot(px, py, tilt, cx, cy)

        def Pl(pts):
            return [P(a, b) for a, b in pts]

        # 1) sap (aşağıdan yukarı) + dipteki metal bilezik + kabza sargısı
        butt, top = P(-r * 0.10, r * 0.98), P(-r * 0.10, -r * 0.88)
        wood_shaft(surf, butt, top, r * 0.17, timber)
        leather_wrap(surf, butt, P(-r * 0.10, r * 0.34), r * 0.19, 4,
                     scale_col((104, 66, 46), sh))
        thick_line(surf, P(-r * 0.10, r * 1.00), P(-r * 0.10, r * 0.84),
                   r * 0.23, steel_d)

        # 2) arkadaki çekiç topuzu (poll)
        metal(surf, Pl([(-r * 0.18, -r * 0.78), (-r * 0.18, -r * 0.38),
                        (-r * 0.48, -r * 0.44), (-r * 0.48, -r * 0.74)]),
              steel_d, lite=scale_col(steel, 0.80), spec=False, ow=r * 0.09)

        # Ağız daire değil hilal: yay yatayda basık (0.72), dikeyde tam (1.0):
        # 3) ağız: sağa doğru bombeli yay + aşağı uzanan sakal
        arc = []
        for i in range(13):
            th = -1.00 + 2.06 * i / 12.0
            arc.append((r * 0.14 + math.cos(th) * r * 0.72,
                        -r * 0.36 + math.sin(th) * r * 0.86))
        blade = arc + [(r * 0.22, r * 0.46), (r * 0.00, r * 0.06),
                       (r * 0.00, -r * 0.70)]
        metal(surf, Pl(blade), steel, lite=scale_col((248, 251, 255), sh),
              dark=steel_d, ow=r * 0.10, lx=-0.30, ly=-0.60)
        # keskin ağız: yayın tam üstünde bembeyaz ince bir şerit
        taper_line(surf, Pl(arc), max(1.4, r * 0.085), max(1.4, r * 0.085),
                   scale_col((255, 255, 255), sh))
        # ağzın hemen gerisinde silahın renginde ikinci bir hat (tav çizgisi)
        inner = [(r * 0.14 + math.cos(-0.94 + 1.92 * i / 12.0) * r * 0.55,
                  -r * 0.36 + math.sin(-0.94 + 1.92 * i / 12.0) * r * 0.66)
                 for i in range(13)]
        taper_line(surf, Pl(inner), max(1.0, r * 0.05), max(1.0, r * 0.05),
                   scale_col(col, 0.90))

        # 4) boyundaki iki bilezik + perçin
        for yy in (-r * 0.70, -r * 0.34):
            thick_line(surf, P(-r * 0.24, yy), P(r * 0.10, yy), r * 0.10, gold)
        circle_aa(surf, *P(-r * 0.07, -r * 0.52), max(1, r * 0.055),
                  scale_col(gold, 1.15))
        add_glow(surf, *P(r * 0.86, -r * 0.36), r * 0.36, lite, 0.30)

    elif key == "book":
        # ---- kalkan ----
        # (Anahtar tarihsel olarak "book"; dövme bir kalkan çiziyor.) Altın
        # kaplamalı çember, ahşap gövde, ortada kubbeli göbek (umbo).
        rr = r * 0.96
        bob = math.sin(t * 2.0) * r * 0.035
        sx, sy = cx, cy + bob
        circle_aa(surf, sx, sy + r * 0.10, rr, OUTLINE)
        # gövde: kenarı koyu, ortası açık - hafif küresel his.
        disc_grad(surf, sx - rr * 0.08, sy - rr * 0.09, rr * 0.84,
                  scale_col((178, 200, 230), sh), scale_col((70, 86, 112), sh), 9)
        # dört ahşap tahta (dikey şeritler)
        for i in (-1, 1):
            thick_line(surf, (sx + i * rr * 0.44, sy - rr * 0.80),
                       (sx + i * rr * 0.44, sy + rr * 0.80),
                       max(1.0, rr * 0.06), scale_col((58, 72, 96), sh))
        # altın çember (kaplama) + iç bilezik - bant biraz daha kalın, daha
        # "dövme" ve sağlam duruyor.
        ring_aa(surf, sx, sy, rr, scale_col(gold, 0.72), max(2, int(rr * 0.18)))
        ring_aa(surf, sx, sy, rr * 0.90, gold, max(1, int(rr * 0.07)))
        ring_aa(surf, sx, sy, rr * 0.62, scale_col(col, 0.85), max(1, int(rr * 0.05)))
        for i in range(8):
            a2 = t * 0.35 + i * math.tau / 8
            px, py = sx + math.cos(a2) * rr * 0.91, sy + math.sin(a2) * rr * 0.91
            circle_aa(surf, px, py, max(1, rr * 0.075), scale_col(gold, 1.10))
            circle_aa(surf, px - rr * 0.02, py - rr * 0.02, max(1, rr * 0.035),
                      scale_col((255, 248, 220), sh))
        # göbek (umbo): kubbe + tepe parlaması
        circle_aa(surf, sx, sy, rr * 0.34, steel_d)
        disc_grad(surf, sx - rr * 0.08, sy - rr * 0.10, rr * 0.30,
                  scale_col((248, 252, 255), sh), scale_col((110, 128, 158), sh), 7)
        circle_aa(surf, sx - rr * 0.10, sy - rr * 0.12, rr * 0.08,
                  scale_col((255, 255, 255), sh))
        # sol üstte keskin bir yansıma yayı
        ring_aa(surf, sx, sy, rr * 0.86, scale_col((255, 255, 255), sh * 0.7), 1)
        add_glow(surf, sx, sy, rr * 1.25, col, 0.16 + 0.08 * math.sin(t * 2.4))

    elif key == "emanet":
        # ---- emanet (miras kılıç) ----
        # Düz, ortasında oluk (fuller) olan bir kılıç: sargılı kabza, hafif
        # kıvrık balçak, üstünde taş olan yuvarlak topuz.
        a = -0.78 + math.sin(t * 1.3) * 0.03
        ca, sa = math.cos(a), math.sin(a)
        nx, ny = -sa, ca

        def Q(u, v):
            return (cx + ca * u + nx * v, cy + sa * u + ny * v)

        blade_l = r * 1.16
        halfw = r * 0.155
        # 1) namlu (bıçak): uca doğru sivrilen gövde
        blade = [Q(-r * 0.06, -halfw), Q(blade_l * 0.74, -halfw * 0.72),
                 Q(blade_l, 0.0), Q(blade_l * 0.74, halfw * 0.72),
                 Q(-r * 0.06, halfw)]
        metal(surf, blade, scale_col((226, 236, 250), sh),
              lite=scale_col((255, 255, 255), sh),
              dark=scale_col((104, 118, 146), sh), ow=r * 0.09)
        # oluk (fuller): namlunun ortasında koyu bir kanal + yanında ışık
        thick_line(surf, Q(r * 0.02, 0), Q(blade_l * 0.80, 0), max(1.0, r * 0.07),
                   scale_col((132, 148, 178), sh))
        thick_line(surf, Q(r * 0.04, -halfw * 0.52), Q(blade_l * 0.78, -halfw * 0.40),
                   max(1.0, r * 0.045), scale_col((255, 255, 255), sh))
        # gezinen parlama: kılıcın üstünde ileri geri kayan ışık
        gl = (math.sin(t * 1.9) * 0.5 + 0.5)
        gu = lerp(r * 0.10, blade_l * 0.80, gl)
        thick_line(surf, Q(gu, -halfw * 0.7), Q(gu + r * 0.16, halfw * 0.7),
                   max(1.0, r * 0.05), scale_col((255, 255, 255), sh))
        # 2) balçak (crossguard): iki yana uzanan, uçları hafif kalkık kollar
        guard = [Q(-r * 0.16, -r * 0.54), Q(-r * 0.02, -r * 0.48),
                 Q(-r * 0.02, r * 0.48), Q(-r * 0.16, r * 0.54),
                 Q(-r * 0.24, r * 0.38), Q(-r * 0.24, -r * 0.38)]
        metal(surf, guard, gold, lite=scale_col((255, 240, 180), sh),
              dark=scale_col((130, 96, 40), sh), ow=r * 0.09)
        # 3) kabza: sargılı
        grip0, grip1 = Q(-r * 0.78, 0.0), Q(-r * 0.30, 0.0)
        thick_line(surf, grip0, grip1, r * 0.20, OUTLINE)
        thick_line(surf, grip0, grip1, r * 0.155, scale_col((84, 54, 40), sh))
        leather_wrap(surf, grip0, grip1, r * 0.20, 4, scale_col((126, 84, 58), sh))
        # 4) topuz + taş
        px, py = Q(-r * 0.88, 0.0)
        circle_aa(surf, px, py, r * 0.155, scale_col((132, 98, 42), sh))
        disc_grad(surf, px - r * 0.03, py - r * 0.04, r * 0.13,
                  scale_col((255, 238, 170), sh), scale_col((150, 112, 46), sh), 6)
        circle_aa(surf, px, py, r * 0.065, scale_col(col, 1.0))
        circle_aa(surf, px - r * 0.02, py - r * 0.03, r * 0.03,
                  scale_col((255, 255, 255), sh))
        add_glow(surf, *Q(blade_l, 0.0), r * 0.36, scale_col((236, 246, 255), sh), 0.26)

    elif key == "cloak":
        # ---- görünmezlik pelerini ----
        # Boş bir başlık (kukuleta) ve altında dalgalanan kumaş.
        sway = math.sin(t * 1.5) * r * 0.06
        top = cy - r * 0.86
        hem = cy + r * 0.92
        body = []
        # sol kenar: omuzdan aşağı
        body.append((cx - r * 0.30, top + r * 0.20))
        body.append((cx - r * 0.66, cy - r * 0.10))
        body.append((cx - r * 0.86 + sway * 0.6, cy + r * 0.44))
        # dalgalı alt kenar
        for i in range(5):
            f = i / 4.0
            xx = cx - r * 0.86 + f * r * 1.72 + sway * (1.0 - abs(f - 0.5) * 2) * 0.5
            yy = hem - (r * 0.20 if i % 2 else 0.0) + math.sin(t * 3 + i * 1.4) * r * 0.05
            body.append((xx, yy))
        body.append((cx + r * 0.86 - sway * 0.6, cy + r * 0.44))
        body.append((cx + r * 0.66, cy - r * 0.10))
        body.append((cx + r * 0.30, top + r * 0.20))
        poly_aa(surf, [(x, y + r * 0.06) for x, y in body], OUTLINE)
        poly_aa(surf, body, scale_col(col, 0.50))
        poly_aa(surf, poly_inset(body, 0.86, dy=-r * 0.03), scale_col(col, 0.78))
        poly_aa(surf, poly_inset(body, 0.50, dx=-r * 0.10, dy=-r * 0.08), col)
        # kıvrımlar
        for i in (-1, 0, 1):
            thick_line(surf, (cx + i * r * 0.34, cy - r * 0.06),
                       (cx + i * r * 0.40 + sway * 0.4, hem - r * 0.14),
                       max(1.0, r * 0.05), scale_col(col, 0.42))
        # başlık: dolu bir kaput, içi karanlık
        hood = [(cx - r * 0.50, cy - r * 0.16), (cx - r * 0.44, top + r * 0.16),
                (cx - r * 0.18, top - r * 0.04), (cx + r * 0.18, top - r * 0.04),
                (cx + r * 0.44, top + r * 0.16), (cx + r * 0.50, cy - r * 0.16)]
        # not: başlığın altına gölge kopyası çizilmiyor.
        poly_aa(surf, hood, scale_col(col, 0.62))
        poly_edge(surf, hood, scale_col(col, 0.34), max(1, int(r * 0.05)))
        poly_aa(surf, poly_inset(hood, 0.84, dx=-r * 0.04, dy=-r * 0.04),
                lighten(col, 0.18))
        # kukuletanın içi: tepesi kemerli, altı yuvarlak bir karanlık boşluk
        void = []
        for i in range(15):
            th = math.pi * (1.0 + i / 14.0)          # üst yarım kemer
            void.append((cx + math.cos(th) * r * 0.29,
                         cy - r * 0.30 + math.sin(th) * r * 0.26))
        for i in range(9):
            th = math.pi * (i / 8.0)                 # alt yuvarlak (sağdan sola)
            void.append((cx + math.cos(th) * r * 0.29,
                         cy - r * 0.30 + math.sin(th) * r * 0.30))
        poly_aa(surf, void, (10, 10, 18))
        poly_edge(surf, void, scale_col(col, 0.45), 1)
        # içeride iki soluk göz
        eg = 0.55 + 0.45 * math.sin(t * 2.6)
        for sgn in (-1, 1):
            ex, ey = cx + sgn * r * 0.12, cy - r * 0.33
            circle_aa(surf, ex, ey, max(1, r * 0.055), scale_col(lite, 0.5 + 0.5 * eg))
        # kenarda titreyen parıltı
        for i in range(5):
            ph = (t * 0.7 + i * 0.2) % 1.0
            px = cx - r * 0.8 + (i * 0.4 + ph) % 1.6 * r
            py = lerp(cy + r * 0.8, cy - r * 0.5, ph)
            circle_aa(surf, px, py, max(1, r * 0.05 * (1 - ph)), CLOAK_COLOR2)
        add_glow(surf, cx, cy, r * 1.15, col, 0.14 + 0.10 * math.sin(t * 2.0))

    elif key == "pentagram":
        # ---- mühür ----
        ang = t * 0.55
        circle_aa(surf, cx, cy, r * 0.98, scale_col(col, 0.16))
        ring_aa(surf, cx, cy, r * 0.98, scale_col(col, 0.85), max(2, int(r * 0.07)))
        ring_aa(surf, cx, cy, r * 0.84, scale_col(lite, 0.6), max(1, int(r * 0.04)))
        pts = [(cx + math.cos(ang - math.pi / 2 + i * math.tau / 5) * r * 0.78,
                cy + math.sin(ang - math.pi / 2 + i * math.tau / 5) * r * 0.78)
               for i in range(5)]
        order = (0, 2, 4, 1, 3, 0)
        for i in range(5):
            thick_line(surf, pts[order[i]], pts[order[i + 1]], max(2.0, r * 0.10),
                       scale_col(col, 0.55))
            thick_line(surf, pts[order[i]], pts[order[i + 1]], max(1.0, r * 0.05), lite)
        for (px, py) in pts:
            add_glow(surf, px, py, r * 0.28, lite, 0.34)
            circle_aa(surf, px, py, max(1, r * 0.10), lite)
            circle_aa(surf, px, py, max(1, r * 0.045), WHITE)
        for i in range(12):
            a2 = -ang * 0.7 + i * math.tau / 12
            c2, s2 = math.cos(a2), math.sin(a2)
            thick_line(surf, (cx + c2 * r * 0.90, cy + s2 * r * 0.90),
                       (cx + c2 * r * 1.00, cy + s2 * r * 1.00),
                       max(1.0, r * 0.05), scale_col(col, 0.75))

    elif key == "whip":
        # ---- kırbaç ----
        # Örgülü deri kayış: sapı sol altta, ucu sağ üstte sivrilerek biter.
        pts = []
        for i in range(25):
            f = i / 24.0
            px = cx - r * 0.72 + f * r * 1.62
            py = cy + math.sin(f * math.pi * 1.55 + t * 1.8) * r * 0.42 * (1 - f * 0.30)
            pts.append((px, py))
        taper_line(surf, pts, r * 0.21, max(1.0, r * 0.035), OUTLINE)
        for i in range(len(pts) - 1):
            f = i / float(len(pts) - 2)
            w2 = lerp(r * 0.16, max(1.0, r * 0.025), f)
            thick_line(surf, pts[i], pts[i + 1], w2,
                       scale_col(col, 0.55) if i % 2 == 0 else mix_col(col, lite, 0.45))
        # üstte ince bir ışık hattı - kayışın yuvarlaklığını verir
        taper_line(surf, [(x, y - r * 0.045) for x, y in pts], r * 0.07,
                   max(1.0, r * 0.015), lite)
        # sap: ahşap + sargı + metal dip
        h0 = (pts[0][0] - r * 0.42, pts[0][1] + r * 0.20)
        wood_shaft(surf, h0, pts[0], r * 0.20, timber)
        leather_wrap(surf, h0, pts[0], r * 0.22, 3, scale_col((112, 72, 48), sh))
        circle_aa(surf, h0[0], h0[1], r * 0.12, steel_d)
        circle_aa(surf, h0[0] - r * 0.02, h0[1] - r * 0.03, r * 0.05,
                  scale_col(steel, 1.0))
        # uçtaki kamçı (popper)
        ex, ey = pts[-1]
        for sgn in (-1, 1):
            thick_line(surf, (ex, ey), (ex + r * 0.22, ey + sgn * r * 0.13),
                       max(1.0, r * 0.028), lite)
        add_glow(surf, ex, ey, r * 0.34, WHIP_COLOR2, 0.38 + 0.2 * math.sin(t * 6))

    elif key == "zemzem":
        # ---- zemzem (kutsal su) ----
        # Tepesi sivri, altı yuvarlak gerçek bir damla: alttaki çemberin
        # neredeyse tamamı çizilir, iki ucu tepedeki sivri noktada birleşir.
        bx, by, br = cx, cy + r * 0.20, r * 0.56
        drop = [(cx, cy - r * 0.96)]
        for i in range(19):
            th = -0.52 + (math.pi + 1.04) * i / 18.0
            drop.append((bx + math.cos(th) * br, by + math.sin(th) * br))
        poly_aa(surf, [(x, y + r * 0.06) for x, y in drop], OUTLINE)
        poly_aa(surf, drop, scale_col(col, 0.52))
        poly_aa(surf, poly_inset(drop, 0.82, dy=-r * 0.02), col)
        poly_aa(surf, poly_inset(drop, 0.46, dx=-r * 0.10, dy=-r * 0.14), lite)
        # iki yansıma: biri geniş, biri nokta
        circle_aa(surf, cx - r * 0.18, cy + r * 0.06, r * 0.13,
                  scale_col((255, 255, 255), sh))
        circle_aa(surf, cx + r * 0.18, cy + r * 0.32, r * 0.055,
                  scale_col((255, 255, 255), sh * 0.85))
        add_glow(surf, cx, cy + r * 0.1, r * 0.80, col, 0.22)
        # altında yayılan halkalar
        for i in range(2):
            ph = (t * 0.7 + i * 0.5) % 1.0
            rr = r * (0.40 + 0.60 * ph)
            pygame.draw.ellipse(surf, scale_col(col, 0.26 + 0.48 * (1 - ph)),
                                (int(cx - rr), int(cy + r * 0.80 - rr * 0.24),
                                 int(rr * 2), int(rr * 0.48)), 2)

    elif key == "shoe":
        # ---- baran'IN papucu ----
        # Yandan görünen yassı bir papuç: kalın deri taban, alçak yüz ve yukarı
        # kıvrık sivri burun.
        for i in range(3):
            fl = 1.0 + 0.26 * math.sin(t * 7 + i * 1.7)
            bxx = cx - r * 0.86 + i * r * 0.28
            flame = [(bxx - r * 0.12, cy + r * 0.54),
                     (bxx - r * 0.02, cy - r * 0.16 * fl),
                     (bxx + r * 0.07, cy - r * 0.76 * fl),
                     (bxx + r * 0.17, cy - r * 0.12 * fl),
                     (bxx + r * 0.22, cy + r * 0.54)]
            poly_aa(surf, flame, scale_col(SHOE_COLOR, 0.80 * sh))
            poly_aa(surf, poly_inset(flame, 0.52, dy=r * 0.10),
                    scale_col(SHOE_COLOR2, sh))
        # taban - uçta yukarı kıvrılır
        sole = [(-0.78, 0.30), (0.80, 0.18), (1.06, -0.06), (1.10, 0.14),
                (0.86, 0.44), (-0.74, 0.52)]
        sole = [(cx + a * r, cy + b * r) for a, b in sole]
        poly_aa(surf, [(x, y + r * 0.06) for x, y in sole], OUTLINE)
        poly_aa(surf, sole, scale_col((86, 56, 38), sh))
        poly_aa(surf, poly_inset(sole, 0.84, dy=-r * 0.04),
                scale_col((126, 82, 52), sh))
        # yüz (papucun üstü) - alçak ve yassı, burnu sivri
        upper = [(-0.74, 0.34), (-0.72, 0.06), (-0.48, -0.12), (-0.06, -0.20),
                 (0.36, -0.10), (0.74, 0.06), (1.02, -0.04), (0.84, 0.24),
                 (-0.66, 0.38)]
        upper = [(cx + a * r, cy + b * r) for a, b in upper]
        poly_aa(surf, [(x, y + r * 0.05) for x, y in upper], OUTLINE)
        poly_aa(surf, upper, scale_col((166, 56, 48), sh))
        poly_aa(surf, poly_inset(upper, 0.86, dx=-r * 0.02, dy=-r * 0.05),
                scale_col((212, 80, 64), sh))
        poly_aa(surf, poly_inset(upper, 0.42, dx=-r * 0.12, dy=-r * 0.09),
                scale_col((242, 126, 94), sh))
        # taban dikişi + yüzdeki altın işleme
        for i in range(8):
            f = i / 7.0
            circle_aa(surf, lerp(cx - r * 0.60, cx + r * 0.80, f),
                      lerp(cy + r * 0.38, cy + r * 0.18, f),
                      max(1, r * 0.026), scale_col(gold, 1.05))
        for i in range(3):
            circle_aa(surf, cx + r * (-0.16 + i * 0.22), cy + r * 0.02,
                      max(1, r * 0.05), gold)
        # burun ucundaki püskül
        circle_aa(surf, cx + r * 1.04, cy - r * 0.06, max(1, r * 0.08), gold)
        add_glow(surf, cx - r * 0.6, cy, r * 0.8, SHOE_COLOR, 0.26)

    elif key == "frost":
        # ---- buz kristali ----
        ice = scale_col((226, 246, 255), sh)
        for i in range(6):
            a = t * 0.4 + i * math.tau / 6
            ex, ey = cx + math.cos(a) * r * 0.94, cy + math.sin(a) * r * 0.94
            thick_line(surf, (cx, cy), (ex, ey), max(2.0, r * 0.13), scale_col(col, 0.75))
            thick_line(surf, (cx, cy), (ex, ey), max(1.0, r * 0.06), ice)
            for f, ln in ((0.40, 0.30), (0.64, 0.24), (0.84, 0.16)):
                mx, my = cx + math.cos(a) * r * f, cy + math.sin(a) * r * f
                for sgn in (-1, 1):
                    a2 = a + sgn * 0.68
                    thick_line(surf, (mx, my),
                               (mx + math.cos(a2) * r * ln, my + math.sin(a2) * r * ln),
                               max(1.0, r * 0.045), mix_col(col, ice, 0.5))
        # ortada altı köşeli çekirdek
        hexp = [(cx + math.cos(t * 0.4 + i * math.tau / 6) * r * 0.22,
                 cy + math.sin(t * 0.4 + i * math.tau / 6) * r * 0.22) for i in range(6)]
        poly_aa(surf, hexp, scale_col(col, 0.9))
        poly_aa(surf, poly_inset(hexp, 0.58, dx=-r * 0.03, dy=-r * 0.04), ice)
        add_glow(surf, cx, cy, r * 0.8, col, 0.24)

    elif key == "tornado":
        # ---- hortum ----
        # Aşağı doğru daralan dolu bir huni: gövde tek parça çizilir, üstüne
        # dönen bantlar ve savrulan kırıntılar konur.

        def fun_x(f):
            return cx + math.sin(t * 3.0 - f * 3.4) * r * 0.14 * f

        def fun_y(f):
            return cy + r * 0.84 - f * r * 1.64

        def fun_w(f):
            return r * (0.13 + 0.84 * f)

        right, left = [], []
        for i in range(9):
            f = i / 8.0
            right.append((fun_x(f) + fun_w(f), fun_y(f)))
            left.append((fun_x(f) - fun_w(f), fun_y(f)))
        body = right + left[::-1]
        poly_aa(surf, body, scale_col(col, 0.34))
        poly_aa(surf, poly_inset(body, 0.78, dx=-r * 0.05), scale_col(col, 0.52))
        # dönen bantlar: huninin ön yüzünde soldan sağa geçen yaylar
        for i in range(6):
            f = 0.10 + i * 0.16
            ww, yy, xx = fun_w(f), fun_y(f), fun_x(f)
            band = [(xx + math.cos(th) * ww, yy + math.sin(th) * ww * 0.34)
                    for th in [j * math.pi / 8 for j in range(9)]]
            taper_line(surf, band, max(1.4, r * 0.075), max(1.4, r * 0.075),
                       mix_col(col, lite, f))
        # tepedeki ağız
        topw, topy, topx = fun_w(1.0), fun_y(1.0), fun_x(1.0)
        ring = [(topx + math.cos(th) * topw, topy + math.sin(th) * topw * 0.34)
                for th in [j * math.tau / 20 for j in range(21)]]
        taper_line(surf, ring, max(1.4, r * 0.07), max(1.4, r * 0.07), lite)
        # savrulan kırıntılar
        for i in range(7):
            ph = (t * 0.9 + i * 0.143) % 1.0
            th = t * 5 + i * 1.7
            circle_aa(surf, fun_x(ph) + math.cos(th) * fun_w(ph) * 1.12,
                      fun_y(ph) + math.sin(th) * fun_w(ph) * 0.34,
                      max(1, r * 0.06 * (1 - ph * 0.5)), lite)
        # tabanda savrulan toz
        pygame.draw.ellipse(surf, scale_col(col, 0.55),
                            (int(cx - r * 0.44), int(cy + r * 0.76),
                             int(r * 0.88), int(r * 0.26)), 2)
        add_glow(surf, cx, cy - r * 0.2, r * 0.9, col, 0.16)

    elif key == "ghost_swords":
        # ---- hayalet kılıçlar ----
        # Yelpaze gibi açılmış üç ruh kılıcı; ortadaki önde ve parlak.
        for ang, k, a_k in ((-2.05, 0.78, 0.55), (-1.09, 0.78, 0.55), (-1.57, 1.0, 1.0)):
            ox = cx + math.cos(ang) * r * 0.05
            oy = cy + r * 0.38
            draw_ghost_blade(surf, ox + math.cos(ang) * r * 0.30, oy + math.sin(ang) * r * 0.30,
                             ang, r / 24.0 * k, col, alpha_k=a_k, glow=0.0)
        add_glow(surf, cx, cy - r * 0.2, r * 0.8, col, 0.22)
        for i in range(3):
            ph = (t * 0.7 + i / 3.0) % 1.0
            circle_aa(surf, cx + math.sin(t * 2 + i * 2.1) * r * 0.55,
                      cy + r * 0.5 - ph * r * 1.2, max(1, r * 0.05 * (1 - ph)), lite)

    elif key == "wolves":
        # ---- kurt başı ----
        # Önden bakan kurt: sivri kulaklar, uzun burun, parlayan gözler.
        head = [(cx - r * 0.62, cy - r * 0.30), (cx - r * 0.50, cy - r * 0.86),
                (cx - r * 0.18, cy - r * 0.46), (cx + r * 0.18, cy - r * 0.46),
                (cx + r * 0.50, cy - r * 0.86), (cx + r * 0.62, cy - r * 0.30),
                (cx + r * 0.46, cy + r * 0.22), (cx + r * 0.16, cy + r * 0.74),
                (cx - r * 0.16, cy + r * 0.74), (cx - r * 0.46, cy + r * 0.22)]
        poly_aa(surf, [(x_, y_ + r * 0.05) for x_, y_ in head], OUTLINE)
        poly_aa(surf, head, scale_col(col, 0.62))
        poly_aa(surf, poly_inset(head, 0.72, dy=r * 0.06), scale_col(col, 0.80))
        # iç kulaklar
        for s_ in (-1, 1):
            poly_aa(surf, [(cx + s_ * r * 0.50, cy - r * 0.40), (cx + s_ * r * 0.46, cy - r * 0.72),
                           (cx + s_ * r * 0.28, cy - r * 0.46)], scale_col(col, 0.38))
        # burun köprüsü + burun
        poly_aa(surf, [(cx - r * 0.14, cy - r * 0.10), (cx + r * 0.14, cy - r * 0.10),
                       (cx + r * 0.20, cy + r * 0.52), (cx - r * 0.20, cy + r * 0.52)],
                lighten(col, 0.25))
        circle_aa(surf, cx, cy + r * 0.56, r * 0.11, (24, 22, 40))
        # gözler
        for s_ in (-1, 1):
            ex_, ey_ = cx + s_ * r * 0.28, cy - r * 0.08
            add_glow(surf, ex_, ey_, r * 0.32, WOLF_COLOR2, 0.45)
            poly_aa(surf, [(ex_ - s_ * r * 0.12, ey_ - r * 0.04), (ex_ + s_ * r * 0.12, ey_ - r * 0.08),
                           (ex_ + s_ * r * 0.08, ey_ + r * 0.05)], WOLF_COLOR2)

    elif key == "tesla":
        # ---- yıldırım zinciri ----
        # Bobin direği + tepesinden üç yöne çatallanan şimşek.
        thick_line(surf, (cx, cy + r * 0.80), (cx, cy + r * 0.05), max(2, r * 0.16), steel_d)
        for i in range(4):
            yy = cy + r * (0.68 - i * 0.17)
            thick_line(surf, (cx - r * 0.22, yy), (cx + r * 0.22, yy), max(1.5, r * 0.07), gold)
        circle_aa(surf, cx, cy - r * 0.05, r * 0.20, scale_col(col, 0.7))
        circle_aa(surf, cx - r * 0.05, cy - r * 0.10, r * 0.10, lite)
        rnd = random.Random(int(t * 12))
        for tx_, ty_ in ((-0.80, -0.70), (0.0, -0.95), (0.82, -0.62)):
            pts = zigzag(cx, cy - r * 0.15, cx + tx_ * r, cy + ty_ * r, 4, r * 0.10, rnd=rnd)
            taper_line(surf, pts, max(1.6, r * 0.10), 1.0, col)
            taper_line(surf, pts, max(1.0, r * 0.04), 0.6, WHITE)
        add_glow(surf, cx, cy - r * 0.4, r * 0.9, col, 0.25)

    elif key == "meteor":
        # ---- meteor ----
        # Sağ üstten çapraz düşen, alev kuyruklu taş. katmanlı alev kuyruğu
        # (dünyadaki göktaşıyla aynı dil)
        ux, uy = 0.707, -0.707
        nx_, ny_ = 0.707, 0.707
        bx, by = cx - r * 0.08, cy + r * 0.10
        for sc_, fc in ((1.0, (226, 84, 34)), (0.72, (255, 150, 52)), (0.42, (255, 230, 150))):
            w_ = r * 0.40 * sc_
            Lt = r * 1.15 * sc_
            fl = 0.92 + 0.08 * math.sin(t * 20 + sc_ * 5)
            poly_aa(surf, [(bx + nx_ * w_, by + ny_ * w_),
                           (bx + ux * Lt * fl + nx_ * w_ * 0.3, by + uy * Lt * fl + ny_ * w_ * 0.3),
                           (bx + ux * Lt * 1.08 * fl, by + uy * Lt * 1.08 * fl),
                           (bx + ux * Lt * fl - nx_ * w_ * 0.3, by + uy * Lt * fl - ny_ * w_ * 0.3),
                           (bx - nx_ * w_, by - ny_ * w_)], fc)
        add_glow(surf, cx - r * 0.12, cy + r * 0.12, r * 0.85, col, 0.45)
        rock = [(cx - r * 0.48, cy + r * 0.02), (cx - r * 0.22, cy - r * 0.30),
                (cx + r * 0.16, cy - r * 0.22), (cx + r * 0.30, cy + r * 0.12),
                (cx + r * 0.10, cy + r * 0.46), (cx - r * 0.34, cy + r * 0.42)]
        poly_aa(surf, [(x_, y_ + r * 0.04) for x_, y_ in rock], OUTLINE)
        poly_aa(surf, rock, (104, 66, 50))
        poly_aa(surf, poly_inset(rock, 0.62, dx=-r * 0.05, dy=-r * 0.05), (150, 92, 62))
        circle_aa(surf, cx - r * 0.18, cy + r * 0.06, r * 0.07, (70, 44, 36))
        circle_aa(surf, cx + r * 0.04, cy + r * 0.24, r * 0.05, (70, 44, 36))
        thick_line(surf, (cx - r * 0.26, cy - r * 0.20), (cx + r * 0.10, cy - r * 0.16),
                   max(1, r * 0.06), lite)

    elif key == "beam":
        # ---- güneş ----
        # Dönen ışınlı güneş kursu.
        add_glow(surf, cx, cy, r * 1.0, col, 0.30)
        for i in range(12):
            a = t * 0.8 + i * math.tau / 12
            long_ = i % 3 == 0
            r0, r1 = r * 0.42, r * (0.95 if long_ else 0.70)
            taper_line(surf, [(cx + math.cos(a) * r0, cy + math.sin(a) * r0),
                              (cx + math.cos(a) * r1, cy + math.sin(a) * r1)],
                       max(1.5, r * (0.12 if long_ else 0.08)), 0.8,
                       lite if long_ else col)
        circle_aa(surf, cx, cy, r * 0.40, scale_col(col, 0.75))
        disc_grad(surf, cx - r * 0.05, cy - r * 0.05, r * 0.34, lite, col, 6)
        circle_aa(surf, cx - r * 0.12, cy - r * 0.12, r * 0.08, WHITE)

    elif key == "hawk":
        # ---- şahin ----
        add_glow(surf, cx, cy, r * 0.9, col, 0.20)
        draw_hawk_shape(surf, cx, cy + r * 0.05, -math.pi / 2, 0.6 * math.sin(t * 3), r / 24.0, col)

    elif key == "bats":
        # ---- yarasa ----
        flap = math.sin(t * 6)
        for sg in (-1, 1):
            wing = [(cx + sg * r * 0.12, cy - r * 0.05), (cx + sg * r * 0.55, cy - r * (0.55 + 0.1 * flap)),
                    (cx + sg * r * 0.95, cy - r * 0.20), (cx + sg * r * 0.78, cy + r * 0.10),
                    (cx + sg * r * 0.55, cy - r * 0.02), (cx + sg * r * 0.40, cy + r * 0.30),
                    (cx + sg * r * 0.15, cy + r * 0.18)]
            poly_aa(surf, wing, scale_col(col, 0.75))
            poly_aa(surf, poly_inset(wing, 0.6), col)
        circle_aa(surf, cx, cy + r * 0.05, r * 0.24, scale_col(col, 0.6))
        for sg in (-1, 1):
            poly_aa(surf, [(cx + sg * r * 0.08, cy - r * 0.12), (cx + sg * r * 0.18, cy - r * 0.38),
                           (cx + sg * r * 0.22, cy - r * 0.10)], scale_col(col, 0.6))
            circle_aa(surf, cx + sg * r * 0.09, cy + r * 0.02, r * 0.05, (255, 120, 150))
        add_glow(surf, cx, cy, r * 0.8, col, 0.18)

    elif key == "nova":
        # ---- ayaz ----
        add_glow(surf, cx, cy, r * 1.0, col, 0.28)
        ring_aa(surf, cx, cy, r * 0.62, lite, max(1, int(r * 0.08)))
        for i in range(8):
            a = t * 0.4 + i * math.tau / 8
            r0, r1 = r * (0.12 if i % 2 == 0 else 0.30), r * (0.95 if i % 2 == 0 else 0.62)
            thick_line(surf, (cx + math.cos(a) * r0, cy + math.sin(a) * r0),
                       (cx + math.cos(a) * r1, cy + math.sin(a) * r1),
                       max(1.5, r * (0.10 if i % 2 == 0 else 0.06)), lite if i % 2 == 0 else col)
            if i % 2 == 0:
                for sg in (-1, 1):
                    bx, by = cx + math.cos(a) * r * 0.62, cy + math.sin(a) * r * 0.62
                    thick_line(surf, (bx, by), (bx + math.cos(a + sg * 0.7) * r * 0.18,
                                                by + math.sin(a + sg * 0.7) * r * 0.18),
                               max(1.0, r * 0.05), lite)
        circle_aa(surf, cx, cy, r * 0.16, WHITE)

    elif key == "knives":
        # ---- bıçak yelpazesi ----
        for i, a in enumerate((-2.15, -1.57, -0.99)):
            ca, sa = math.cos(a), math.sin(a)
            nx, ny = -sa, ca
            bx, by = cx + ca * r * 0.10, cy + r * 0.45 + sa * r * 0.10
            tip = (bx + ca * r * 1.05, by + sa * r * 1.05)
            blade = [tip, (bx + ca * r * 0.35 + nx * r * 0.10, by + sa * r * 0.35 + ny * r * 0.10),
                     (bx + ca * r * 0.30, by + sa * r * 0.30),
                     (bx + ca * r * 0.35 - nx * r * 0.10, by + sa * r * 0.35 - ny * r * 0.10)]
            poly_aa(surf, blade, steel if i != 1 else lite)
            thick_line(surf, (bx + ca * r * 0.30 + nx * r * 0.13, by + sa * r * 0.30 + ny * r * 0.13),
                       (bx + ca * r * 0.30 - nx * r * 0.13, by + sa * r * 0.30 - ny * r * 0.13),
                       max(1.5, r * 0.07), gold)
            thick_line(surf, (bx + ca * r * 0.28, by + sa * r * 0.28), (bx, by), max(1.5, r * 0.09), timber)

    elif key == "quake":
        # ---- deprem: çatlayan toprak + şok halkaları ----
        pulse = 0.5 + 0.5 * math.sin(t * 5)
        for i, rr in enumerate((0.92, 0.74)):
            ph = (t * 0.8 + i * 0.5) % 1.0
            pygame.draw.ellipse(surf, scale_col(col, 0.35 + 0.5 * (1 - ph)),
                                pygame.Rect(int(cx - r * rr), int(cy + r * 0.05 - r * rr * 0.45),
                                            int(2 * r * rr), int(r * rr * 0.9)), max(1, int(r * 0.07)))
        slab = [(cx - r * 0.78, cy + r * 0.10), (cx - r * 0.30, cy - r * 0.22),
                (cx + r * 0.42, cy - r * 0.18), (cx + r * 0.80, cy + r * 0.12),
                (cx + r * 0.35, cy + r * 0.46), (cx - r * 0.45, cy + r * 0.42)]
        poly_aa(surf, [(px_, py_ + r * 0.08) for px_, py_ in slab], OUTLINE)
        poly_aa(surf, slab, (122, 96, 74))
        poly_aa(surf, poly_inset(slab, 0.6, dx=-r * 0.04, dy=-r * 0.06), (160, 128, 96))
        crack = [(cx - r * 0.05, cy - r * 0.22), (cx + r * 0.06, cy - r * 0.02),
                 (cx - r * 0.08, cy + r * 0.12), (cx + r * 0.05, cy + r * 0.44)]
        for a_, b_ in zip(crack, crack[1:]):
            thick_line(surf, a_, b_, max(2.0, r * 0.13), (40, 24, 14))
            thick_line(surf, a_, b_, max(1.0, r * 0.05), scale_col(col, 0.7 + 0.3 * pulse))
        add_glow(surf, cx, cy + r * 0.1, r * 0.55, col, 0.25 + 0.25 * pulse)
        for sg in (-1, 1):
            for j in range(2):
                bx_ = cx + sg * r * (0.30 + 0.25 * j)
                by_ = cy - r * (0.40 + 0.22 * j)
                circle_aa(surf, bx_, by_ - math.sin(t * 9 + j + sg) * r * 0.05, r * (0.10 - 0.02 * j),
                          (140, 112, 86))

    else:
        draw_icon(surf, cx, cy, "star", col, int(r))


_MOB_SPR = {}
_MOB_LIVE = {}
_UI_FRAME = [0]               # her karede bir artar (App.frame)


def mob_live_sprite(key, w, h, every, phase, draw_fn):
    """telefon: canlı (hareketli) küçük bir çizimi kendi saydam görüntüsünde tutar ve yalnızca `every` karede bir yeniden çizer; aradaki karelerde hazır görüntü basılır. `phase` tazelemeleri karelere yayar (hepsi aynı karede çizilip takılma yapmasın)."""
    f = _UI_FRAME[0]
    ent = _MOB_LIVE.get(key)
    if ent is None or ((f + phase) % every == 0 and ent[1] != f):
        if ent is None:
            if len(_MOB_LIVE) > 80:
                _MOB_LIVE.clear()
            img = pygame.Surface((int(w), int(h)), pygame.SRCALPHA)
        else:
            img = ent[0]
            img.fill((0, 0, 0, 0))
        global _GLOW_ON_ALPHA
        _GLOW_ON_ALPHA = True
        try:
            draw_fn(img, w / 2.0, h / 2.0)
        finally:
            _GLOW_ON_ALPHA = False
        ent = (img, f)
        _MOB_LIVE[key] = ent
    return ent[0]


def mob_static_sprite(key, size, draw_fn):
    """telefon: vektörle çizilen süslü bir simgeyi (silah arması"""
    img = _MOB_SPR.get(key)
    if img is None:
        if len(_MOB_SPR) > 700:
            _MOB_SPR.clear()
        global _GLOW_ON_ALPHA
        n = int(size)
        img = pygame.Surface((n, n), pygame.SRCALPHA)
        _GLOW_ON_ALPHA = True
        try:
            draw_fn(img, n / 2.0, n / 2.0)
        finally:
            _GLOW_ON_ALPHA = False
        img = mob_rle(img)
        _MOB_SPR[key] = img
    return img


def draw_weapon_emblem(surf, cx, cy, h, w, t=0.0, locked=False, glow=True):
    if MOBILE and not _GLOW_ON_ALPHA:
        n = int(h * 2.3) + 8
        img = mob_static_sprite(("wemb", w.get("key") or w.get("name"), int(h), bool(locked), bool(glow)), n,
                                lambda im, x, y: _draw_weapon_emblem(im, x, y, h, w, 0.0, locked, glow))
        surf.blit(img, (int(cx - n / 2.0), int(cy - n / 2.0)))
        return
    _draw_weapon_emblem(surf, cx, cy, h, w, t, locked, glow)


def _draw_weapon_emblem(surf, cx, cy, h, w, t=0.0, locked=False, glow=True):
    """Bir silahın arması: dövme madalyon + silaha özel sembol + ışık."""
    r = h * 0.46
    col = tuple(w["color"])
    if locked:
        col = scale_col(col, 0.34)
    pulse = 0.5 + 0.5 * math.sin(t * 2.4 + cx * 0.01)
    if glow and not locked:
        add_glow(surf, cx, cy, r * 1.95, col, 0.24 + 0.16 * pulse)

    R_OUT = r * 1.10          # bileziğin dış sınırı
    R_IN = r * 0.88           # bileziğin iç sınırı (koyu yüzün başladığı yer)
    R_BAND = (R_OUT + R_IN) * 0.5

    # 1) dış kertikler - yavaşça dönen, yumuşak tırnaklar
    for i in range(16):
        a = t * 0.42 + i * math.tau / 16
        long_tick = (i % 2 == 0)
        r0 = R_OUT * 1.04
        r1 = r0 + r * ((0.20 if long_tick else 0.12) + 0.03 * pulse)
        thick_line(surf, (cx + math.cos(a) * r0, cy + math.sin(a) * r0),
                   (cx + math.cos(a) * r1, cy + math.sin(a) * r1),
                   1.8 if long_tick else 1.1,
                   scale_col(col, 0.45 + 0.40 * pulse))

    # Dış hat tek ve tam eş merkezli; ışık/gölge kenara taşmayan ince birer
    # kavis (parça) olarak, karşılıklı iki tarafa ekleniyor:
    # 2) gövde: kontur + altın bilezik (üstü ışıklı, altı gölgeli) + iç zemin
    circle_aa(surf, cx, cy + 2, R_OUT + 3, OUTLINE)
    rim_lo = scale_col(col, 0.34)
    rim_hi = lighten(col, 0.52)
    circle_aa(surf, cx, cy, R_OUT, rim_lo)
    hi_pts = [(cx + math.cos(a) * (R_BAND + 1.2), cy + math.sin(a) * (R_BAND + 1.2))
              for a in [math.pi * (1.04 + i * 0.055) for i in range(10)]]
    taper_line(surf, hi_pts, R_OUT - R_IN, R_OUT - R_IN, mix_col(rim_lo, rim_hi, 0.80))
    sh_pts = [(cx + math.cos(a) * (R_BAND + 1.2), cy + math.sin(a) * (R_BAND + 1.2))
              for a in [math.pi * (0.06 + i * 0.045) for i in range(9)]]
    taper_line(surf, sh_pts, (R_OUT - R_IN) * 0.85, (R_OUT - R_IN) * 0.85,
               scale_col(rim_lo, 0.55))
    circle_aa(surf, cx, cy, R_IN, scale_col(col, 0.20))
    # iç zemin: merkeze doğru açılan koyu bir çanak.
    disc_grad(surf, cx - r * 0.04, cy - r * 0.05, R_IN * 0.90,
              scale_col(col, 0.46 if not locked else 0.30),
              (14, 15, 24), 9)
    # iç bilezik
    ring_aa(surf, cx, cy, R_IN * 0.98, scale_col(col, 0.85), max(1, int(r * 0.055)))
    ring_aa(surf, cx, cy, R_IN * 0.80, scale_col(col, 0.40), 1)

    # 3) dört perçin - kalınlaşan altın bandın tam ortasında
    for i in range(4):
        a = math.pi / 4 + i * math.pi / 2
        px, py = cx + math.cos(a) * R_BAND, cy + math.sin(a) * R_BAND
        circle_aa(surf, px, py, max(2, r * 0.085), scale_col(col, 0.30))
        circle_aa(surf, px - r * 0.02, py - r * 0.02, max(1, r * 0.05),
                  lighten(col, 0.45))

    # 4) silaha özel sembol. Kilitliyken söner ve yukarı kayar: kilit
    #    gövdesinin altında kalmasın, ikisi birbirini ezmesin.
    sig_y = cy if not locked else cy - r * 0.24
    draw_weapon_sigil(surf, cx, sig_y, r * (0.64 if not locked else 0.46), w["key"],
                      lighten(col, 0.20) if not locked else scale_col(col, 0.60), t)

    # 5) cam parlaması: sol üstte ince bir yansıma yayı
    if not locked:
        arc_pts = [(cx + math.cos(a) * R_IN * 0.90, cy + math.sin(a) * R_IN * 0.90)
                   for a in [math.pi * (1.02 + i * 0.030) for i in range(10)]]
        taper_line(surf, arc_pts, 2.0, 0.8, (255, 255, 255))

    if locked:
        # asma kilit - madalyonun alt yarısına oturur: gövde + kemer + delik.
        bw = r * 0.46
        bh = r * 0.34
        by = cy + r * 0.32
        sh_ = r * 0.34
        arc_r = pygame.Rect(int(cx - bw * 0.62), int(by - bh - sh_),
                            int(bw * 1.24), int(sh_ * 2))
        pygame.draw.arc(surf, OUTLINE, arc_r.inflate(4, 4), 0.12, math.pi - 0.12,
                        max(3, int(r * 0.13)))
        pygame.draw.arc(surf, (196, 200, 222), arc_r, 0.12, math.pi - 0.12,
                        max(2, int(r * 0.09)))
        body = [(cx - bw, by - bh), (cx + bw, by - bh),
                (cx + bw, by + bh), (cx - bw, by + bh)]
        metal(surf, body, (214, 198, 132), lite=(252, 244, 196),
              dark=(128, 112, 62), spec=False, ow=r * 0.10)
        circle_aa(surf, cx, by - bh * 0.18, max(1, r * 0.09), (54, 44, 28))
        poly_aa(surf, [(cx - r * 0.05, by - bh * 0.10), (cx + r * 0.05, by - bh * 0.10),
                       (cx + r * 0.03, by + bh * 0.52), (cx - r * 0.03, by + bh * 0.52)],
                (54, 44, 28))


# seviye kartı istatistikleri - "Hasar 101 -> 112" satırları.
def weapon_stat_values(key, lvl):
    """Silahın kartta gösterilen özel değerleri: [(etiket_anahtarı, değer, tür)]."""
    w = WEAPON_BY_KEY.get(key)
    if w is None or lvl <= 0:
        return []
    g = weapon_growth(lvl)
    if key == "axe":
        return [("cs.count", weapon_count(lvl), "n")]
    if key == "book":
        return [("cs.count", weapon_count(lvl), "n"),
                ("cs.recharge", max(1.4, BOOK_RECHARGE - BOOK_RECHARGE_PER_LEVEL * g), "s")]
    if key == "pentagram":
        return [("cs.area", penta_radius(lvl), "px")]
    if key == "whip":
        return [("cs.count", weapon_count(lvl, "whip"), "n"), ("cs.reach", whip_reach(lvl), "px")]
    if key == "zemzem":
        n = 1 + (lvl >= 6) + (lvl >= 13) + (lvl >= 20)
        return [("cs.pools", n, "n"), ("cs.area", ZEMZEM_BASE_R + ZEMZEM_R_PER_LEVEL * g, "px")]
    if key in ("shoe", "frost"):
        return [("cs.area", shoe_radius(lvl), "px"), ("cs.duration", shoe_life(lvl), "s")]
    if key == "emanet":
        return [("cs.reach", emanet_radius(lvl), "px"), ("cs.cd", weapon_cooldown(w, lvl), "s")]
    if key == "cloak":
        return [("cs.duration", cloak_duration(lvl), "s"), ("cs.cd", cloak_cooldown(lvl), "s")]
    if key == "tornado":
        return [("cs.reach", Tornado.BASE_PULL_R + Tornado.PULL_R_PER_LEVEL * g, "px"),
                ("cs.cd", weapon_cooldown(w, lvl), "s")]
    if key == "ghost_swords":
        return [("cs.count", ghost_count(lvl), "n"), ("cs.cd", ghost_cd(lvl), "s")]
    if key == "wolves":
        return [("cs.wolves", wolf_count(lvl), "n"), ("cs.bite", wolf_bite_cd(lvl), "s")]
    if key == "tesla":
        return [("cs.targets", tesla_targets(lvl), "n"), ("cs.cd", weapon_cooldown(w, lvl), "s")]
    if key == "meteor":
        return [("cs.meteors", meteor_count(lvl), "n"), ("cs.area", meteor_radius(lvl), "px")]
    if key == "beam":
        return [("cs.beams", beam_count(lvl), "n"), ("cs.length", beam_len(lvl), "px")]
    if key == "hawk":
        return [("cs.hawks", hawk_count(lvl), "n"), ("cs.cd", hawk_cd(lvl), "s")]
    if key == "bats":
        return [("cs.bats", bat_count(lvl), "n"), ("cs.cd", weapon_cooldown(w, lvl), "s")]
    if key == "nova":
        return [("cs.area", nova_radius(lvl), "px"), ("cs.freeze", nova_freeze(lvl), "s")]
    if key == "knives":
        return [("cs.knives", knife_count(lvl), "n"), ("cs.pierce", knife_pierce(lvl), "n")]
    if key == "quake":
        return [("cs.area", quake_radius(lvl), "px"), ("cs.stun", quake_stun(lvl), "s")]
    return [("cs.cd", weapon_cooldown(w, lvl), "s")]


def fmt_stat(v, kind):
    """Kart sayısı: adet tam sayı, saniye bir ondalık (tr virgüllü)."""
    if kind == "s":
        t = "%.2f" % v if v < 1.0 else "%.1f" % v
        t = t.replace(".", ",") if lang() == "tr" else t
        return t + L("cs.sec")
    if kind in ("n", "px"):
        return "%d" % int(round(v))
    if v >= 100:
        return fmt_num(int(round(v)))
    t = "%.1f" % v
    return t.replace(".", ",") if lang() == "tr" else t


def weapon_card_rows(p, w, lvl_to, bonus):
    """Kartın satırları: [(etiket, önce|None, sonra)] - en fazla 3 satır."""
    key = w["key"]
    lvl_from = lvl_to - 1
    cur_b = float(p.weapon_boost.get(key, 0.0))
    new_b = min(WEAPON_BOOST_CAP, cur_b + max(0.0, bonus))
    rows = []
    if w.get("dmg", 0) > 0:
        base_to = weapon_damage(p, w, lvl_to) / (1.0 + cur_b)
        after = base_to * (1.0 + new_b)
        before = weapon_damage(p, w, lvl_from) if lvl_from >= 1 else None
        rows.append((L("cs.dmg"), None if before is None else fmt_stat(before, "f"),
                     fmt_stat(after, "f")))
    old = dict((k, (v, kd)) for k, v, kd in weapon_stat_values(key, lvl_from))
    for k, v, kd in weapon_stat_values(key, lvl_to):
        b = old.get(k)
        rows.append((L(k), None if b is None else fmt_stat(b[0], kd), fmt_stat(v, kd)))
    return rows[:3]


def fmt_book_stat(v, kind):
    if kind == "int":
        return "%d" % int(round(v))
    if kind == "rate":
        t = "%.2f" % v
        t = t.replace(".", ",") if lang() == "tr" else t
        return t + L("cs.per_sec")
    return fmt_pct1(v)


def book_card_rows(p, ch):
    """Kitap kartının satırları: [(etiket, önce, sonra)] - en fazla 2 satır."""
    rows = []
    for stat, amt in ch.get("gains", ())[:2]:
        b, kind = p.book_stat_view(stat)
        a, _k = p.book_stat_view(stat, amt)
        rows.append((L("bs." + stat), fmt_book_stat(b, kind), fmt_book_stat(a, kind)))
    return rows


_LU_BG_CACHE = {}


def _lu_card_bg(w, h, tint, tier):
    """Kartın gövdesi: üstte kademenin rengine çalan, aşağı koyulaşan degrade."""
    ck = (w, h, tuple(int(c) for c in tint), tier)
    sfc = _LU_BG_CACHE.get(ck)
    if sfc is not None:
        return sfc
    if len(_LU_BG_CACHE) > 64:
        _LU_BG_CACHE.clear()
    sfc = pygame.Surface((w, h), pygame.SRCALPHA)
    sfc.fill((*mix_col(ui_warm(tint), (30, 22, 24), 0.80 - 0.05 * max(0, tier)), 248))
    # ince çapraz desen (kumaş/deri hissi)
    for x in range(-h, w, 14):
        pygame.draw.line(sfc, (255, 240, 220, 8), (x, h), (x + h, 0), 1)
    hand_mask(sfc, 14)
    _LU_BG_CACHE[ck] = sfc
    return sfc


def _sparkle(surf, x, y, r, col):
    """Dört köşeli küçük parıltı."""
    if r < 0.6:
        return
    pts = [(x, y - r), (x + r * 0.28, y - r * 0.28), (x + r, y), (x + r * 0.28, y + r * 0.28),
           (x, y + r), (x - r * 0.28, y + r * 0.28), (x - r, y), (x - r * 0.28, y - r * 0.28)]
    poly_aa(surf, pts, col)


def draw_levelup_card(surf, r2, ch, run, t, hover):
    """Tek bir seviye kartını çizer (tasarımı)."""
    if ch["kind"] == "evo":
        draw_evo_card(surf, r2, ch, run, t, hover)
        return
    p = run.player
    is_weapon = ch["kind"] == "weapon"
    rare_book = (not is_weapon) and ch.get("rare")
    col = tuple(ch["color"])
    # normal kitap kartları da kademe taşır (nadir kitaplar taşımaz)
    tier = ch.get("rarity")
    tier_i = int(tier or 0)
    tiered = tier is not None
    band_col = rarity_color(tier_i) if tiered else (GOLD if rare_book else col)

    # ---- dış ışık ----
    if tiered and tier_i >= 1:
        pass
    elif hover:
        pass
    surf.blit(_panel_shadow(r2.w, r2.h, 18), (r2.x - 6, r2.y - 2))
    surf.blit(_lu_card_bg(r2.w, r2.h, band_col if (tiered and tier_i >= 1) else col, tier_i),
              r2.topleft)

    # ---- arkada dönen ışınlar (Epik / Efsanevi) ----
    ecx, ecy = r2.centerx, r2.y + 88
    if tiered and tier_i >= 3:
        prev = surf.get_clip()
        surf.set_clip(r2.inflate(-6, -6).clip(prev) if prev else r2.inflate(-6, -6))
        n_ray = 10 if tier_i == 4 else 7
        for i in range(n_ray):
            a = t * (0.5 if tier_i == 4 else 0.3) + i * math.tau / n_ray
            pts = [(ecx, ecy),
                   (ecx + math.cos(a - 0.07) * 150, ecy + math.sin(a - 0.07) * 150),
                   (ecx + math.cos(a + 0.07) * 150, ecy + math.sin(a + 0.07) * 150)]
            rs = pygame.Surface((r2.w, r2.h), pygame.SRCALPHA)
            pygame.draw.polygon(rs, (*band_col, 22 if tier_i == 3 else 30),
                                [(x - r2.x, y - r2.y) for x, y in pts])
            surf.blit(rs, r2.topleft)
        surf.set_clip(prev)

    # ---- kenar ----
    edge = (band_col if (tiered and tier_i >= 1) else
            scale_col(band_col, 0.62) if tiered else (GOLD_DIM if rare_book else PANEL_EDGE))
    if hover:
        edge = lighten(edge if edge != PANEL_EDGE else col, 0.25)
    pulse = 0.5 + 0.5 * math.sin(t * 4.0 + r2.x * 0.02)
    ew = 3 + (1 if (tiered and tier_i >= 3 and pulse > 0.5) else 0)
    ink_frame(surf, r2, edge, 18, ew)
    ink_frame(surf, r2.inflate(-10, -10), scale_col(edge, 0.45), 14, 1)

    # ---- üst şerit: kademe / kitap ----
    band = pygame.Rect(r2.x + 3, r2.y + 3, r2.w - 6, 30)
    pygame.draw.rect(surf, scale_col(band_col, 0.55), band, border_top_left_radius=15,
                     border_top_right_radius=15)
    pygame.draw.rect(surf, band_col, band.inflate(0, -6).move(0, -3),
                     border_top_left_radius=14, border_top_right_radius=14)
    if tiered:
        btxt = rarity_name(tier_i)
    elif rare_book:
        btxt = L("lu.rare_trial") if ch.get("trial") else L("lu.rare_book")
    else:
        btxt = L("lu.new_book") if ch.get("new") else L("lu.book")
    tc = (28, 20, 21) if sum(band_col) > 360 else WHITE
    draw_text(surf, btxt, (band.centerx, band.centery - 2), 15, tc, bold=True,
              center=True, shadow=False)
    tw_ = text_width(btxt, 15, True)
    for s_ in (-1, 1):
        gx = band.centerx + s_ * (tw_ / 2 + 14)
        _sparkle(surf, gx, band.centery - 2, 4.5 + (1.5 if tier_i >= 3 else 0), tc)

    # ---- arma ----
    if is_weapon:
        draw_weapon_emblem(surf, ecx, ecy, 92 if hover else 86, ch["w"], t)
    else:
        draw_book(surf, ecx, ecy - 2, 88 if hover else 82, ch["book"], t)

    # ---- ad + seviye hapı ----
    draw_text(surf, ch["name"], (r2.centerx, r2.y + 152), 19, TEXT, bold=True, center=True)
    if is_weapon:
        pill = L("lu.new_weapon") if ch["new"] else L("lu.lvl_up", ch["lvl"] - 1, ch["lvl"])
    else:
        mx = ch.get("max", BOOK_MAX_LEVEL)
        if ch.get("new"):
            pill = L("lu.new_book_pill")
        else:
            pill = L("lu.lvl_up", ch["lvl"] - 1, ch["lvl"])
        if not rare_book:
            pill += "  /" + str(mx)
    pw_ = text_width(pill, 11, True) + 18
    pr_ = pygame.Rect(0, 0, pw_, 18)
    pr_.center = (r2.centerx, r2.y + 174)
    pygame.draw.rect(surf, (23, 17, 18), pr_, border_radius=9)
    ink_frame(surf, pr_, scale_col(band_col, 0.8), 9, 1)
    draw_text(surf, pill, pr_.center, 11, lighten(band_col, 0.2), bold=True, center=True,
              shadow=False)

    # ---- satırlar ----
    box = pygame.Rect(r2.x + 14, r2.y + 190, r2.w - 28, 94)
    pygame.draw.rect(surf, (20, 15, 15), box, border_radius=10)
    ink_frame(surf, box, scale_col(band_col, 0.35), 10, 1)
    if is_weapon:
        rows = weapon_card_rows(p, ch["w"], ch["lvl"], ch.get("boost", 0.0))
        if not rows:
            rows = [(L("cs.level"), None, str(ch["lvl"]))]
        up_col = lighten(rarity_color(tier_i), 0.15) if tier_i >= 1 else GREEN
        y = box.y + 9
        for lbl, before, after in rows:
            draw_text(surf, lbl, (box.x + 10, y), 13, (176, 182, 204), shadow=False)
            xr = box.right - 10
            draw_text(surf, after, (xr, y - 1), 15, up_col, bold=True, right=True, shadow=False)
            xr -= text_width(after, 15, True) + 6
            # yeni silahta satırların yanında "YENİ" yazmaz - üstteki "YENİ
            # SİLAH" hapı yeter.
            if before is not None:
                draw_text(surf, "→", (xr, y), 13, (120, 126, 150), right=True, shadow=False)
                xr -= text_width("→", 13) + 5
                draw_text(surf, before, (xr, y), 13, (140, 146, 170), right=True, shadow=False)
            y += 27
        b = float(ch.get("boost", 0.0))
        if b > 0:
            left = WEAPON_BOOST_CAP - float(p.weapon_boost.get(ch["key"], 0.0))
            gain = max(0.0, min(b, left))
            btxt = (L("lu.rarity_bonus", fmt_pct1(gain)) if gain > 0
                    else L("ui.boost_capped"))
            draw_text(surf, btxt, (r2.centerx, box.bottom + 12), 12,
                      lighten(rarity_color(tier_i), 0.1), bold=True, center=True, shadow=False)
    elif ch.get("gains"):
        # kitap: nadirliğe göre kazanç, "önce -> sonra" satırları
        rows = book_card_rows(p, ch)
        up_col = lighten(rarity_color(tier_i), 0.15) if tier_i >= 1 else GREEN
        y = box.y + 9 + (14 if len(rows) == 1 else 0)
        for lbl, before, after in rows:
            draw_text(surf, lbl, (box.x + 10, y), 13, (176, 182, 204), shadow=False)
            xr = box.right - 10
            draw_text(surf, after, (xr, y - 1), 15, up_col, bold=True, right=True, shadow=False)
            xr -= text_width(after, 15, True) + 6
            draw_text(surf, "→", (xr, y), 13, (120, 126, 150), right=True, shadow=False)
            xr -= text_width("→", 13) + 5
            draw_text(surf, before, (xr, y), 13, (140, 146, 170), right=True, shadow=False)
            y += 27
        for i, ln in enumerate(wrap_text(ch["desc"], 11, box.w - 18)[:1]):
            draw_text(surf, ln, (box.centerx, box.bottom - 16), 11, (150, 156, 180),
                      center=True, shadow=False)
        draw_text(surf, L("lu.book_note"), (r2.centerx, box.bottom + 12), 11,
                  lighten(rarity_color(tier_i), 0.1) if tier_i >= 1 else (170, 176, 196),
                  bold=True, center=True, shadow=False)
    else:
        for i, ln in enumerate(wrap_text(ch["desc"], 13, box.w - 18)[:4]):
            draw_text(surf, ln, (box.centerx, box.y + 18 + i * 20), 13, (196, 200, 220),
                      center=True, shadow=False)

    # ---- Efsanevi: kayan parıltı + yıldızcıklar ----
    if tiered and tier_i >= 4:
        prev = surf.get_clip()
        surf.set_clip(r2.inflate(-4, -4).clip(prev) if prev else r2.inflate(-4, -4))
        ph = (t * 0.45 + r2.x * 0.001) % 1.6
        sx = r2.x - 80 + ph * (r2.w + 160) / 1.2
        sh = pygame.Surface((r2.w, r2.h), pygame.SRCALPHA)
        pygame.draw.polygon(sh, (255, 244, 200, 34),
                            [(sx - r2.x, 0), (sx - r2.x + 34, 0),
                             (sx - r2.x - 60, r2.h), (sx - r2.x - 94, r2.h)])
        surf.blit(sh, r2.topleft)
        surf.set_clip(prev)
        for i in range(7):
            ph2 = (t * 0.6 + i * 0.37) % 1.0
            sx2 = r2.x + 20 + ((i * 53) % (r2.w - 40))
            sy2 = r2.y + 40 + ((i * 97) % 140)
            _sparkle(surf, sx2, sy2, 4.0 * math.sin(ph2 * math.pi), (255, 240, 180))

    # ---- seç düğmesi ----
    if hover:
        br = pygame.Rect(r2.x + 18, r2.bottom - 44, r2.w - 36, 32)
        pygame.draw.rect(surf, band_col if tiered and tier_i >= 1 else col, br, border_radius=10)
        draw_text(surf, L("ui.pick"), br.center, 16, (21, 15, 16), bold=True, center=True,
                  shadow=False)
    elif not is_weapon and not rare_book and ch.get("new"):
        draw_text(surf, L("lu.book_slot", p.normal_book_count() + 1, slot_max(p, 'b')),
                  (r2.centerx, r2.bottom - 28), 11, TEXT_DIM, center=True, shadow=False)
    elif rare_book:
        draw_text(surf, L("lu.rare_slot"), (r2.centerx, r2.bottom - 28), 11, GOLD_DIM,
                  center=True, shadow=False)


# ---- lanetli sandık - "oyun hep aynı akmasın" ----
# Haritanın rastgele bir yerinde bir mağara ağzı belirir; önünde zincirli,
# rünleri yanan bir sandık durur:
# * büyük ödül + lanet: ödül hemen verilir; karşılığında yeni bir düşman türü
#   (bölünen, ölü çağırıcı, hayalet) ya da bir genel lanet (kudurma, kalabalık)
#   koşunun sonuna kadar bütün dalgalara karışır.
# * zar at: ya ödül iki katı + lanet, ya da yalnızca lanet. Şans, kazanma
#   olasılığını artırır.
# * kan bedeli: lanetsiz ödül, ama azami canın bir kısmı gider.
CURSE_COLOR = (178, 92, 255)
CURSE_COLOR2 = (236, 196, 255)
CURSE_RED = (255, 76, 110)
# mağara duyurulmadan haritanın uzak bir köşesine yerleşir.
CURSED_FIRST_WAVE = 2           # (kadar) ilk mağaranın dalgası
CURSED_RESPAWN_WAVES = 5        # (kadar) kullanıldıktan kaç dalga sonra yenisi
# "lanetli sandık oyun boyunca yalnız 3 kez çıksın: 1. başta, 2. ilk patrondan
# sonra, 3. cehennem kapısı açılınca".
CURSED_MAX = 3
CURSED_MIN_LIFE = 45.0          # bulunmamış mağara en az bu kadar yerinde kalır
CURSED_EVERY = CURSED_RESPAWN_WAVES       # (eski ad)
CURSED_EVERY_HELL = CURSED_RESPAWN_WAVES  # (eski ad)
# Mağarada şans daha çok işler: teklif kademesi bu şansla çekilir.
CAVE_LUCK_MULT = 1.5
CAVE_LUCK_BASE = 0.25
CURSE_SCORE_PER = 0.25          # her kabul edilen lanetin skor payı
CURSE_SCORE_MAX = 1.50          # skor payının tavanı (x2,5)
CURSE_SPAWN_BASE = 0.10         # lanetli türün doğumlardaki payı (ilk lanet)
CURSE_SPAWN_PER = 0.06          # her ek lanet seviyesinde
CURSE_SPAWN_MAX = 0.34
CURSE_FRENZY_SPD = 0.12         # kudurma: lanet seviyesi başına yaratık hızı
CURSE_SWARM_CAP = 0.15          # kalabalık: lanet seviyesi başına kalabalık tavanı
CURSE_TRAP_BASE = 8             # tuzak dalgasının taban yaratık sayısı
# Yaratık türleri (ENEMY_DEFS'te de var) ve genel lanetler
CURSE_KINDS = ("splitter", "necro", "ghost")
CURSE_DEFS = {
    "splitter": dict(icon="skull", color=(124, 232, 120)),
    "necro":    dict(icon="skull", color=(150, 255, 196)),
    "ghost":    dict(icon="ghost", color=(196, 208, 255)),
    "frenzy":   dict(icon="flame", color=(255, 120, 90)),
    "swarm":    dict(icon="orbit", color=(255, 196, 96)),
}
# Ödüller: (anahtar, ikon, renk). Değerler cursed_reward_values'ta.
CURSE_REWARDS = ("power", "fortune", "arsenal", "treasure", "fortress", "edge")
CURSE_REWARD_ICONS = {"power": ("sword", (255, 120, 110)), "fortune": ("horseshoe", GREEN),
                      "arsenal": ("star", (150, 200, 255)), "treasure": ("coin", GOLD),
                      "fortress": ("shield", (170, 186, 220)), "edge": ("target", (255, 214, 120))}
# Kademe çarpanı (şans): ödülün büyüklüğü - Yaygın x1 .. Efsanevi x1,8
CURSE_TIER_MULT = (1.0, 1.15, 1.3, 1.5, 1.8)
BLOOD_PRICE = 0.30              # kan bedeli: azami canın gidecek payı
GAMBLE_WIN = 0.55               # zar at: taban kazanma olasılığı ...
GAMBLE_WIN_LUCK = 0.15          # ... şansın her %100'ü için ek
GAMBLE_WIN_MAX = 0.85
# ölü çağırıcı
NECRO_KEEP = 290
NECRO_CD = 5.5
NECRO_RADIUS = 330
NECRO_MAX_RAISE = 3
CORPSE_LIFE = 12.0
# hayalet
GHOST_SOLID_T = 2.4             # görünür (vurulabilir) süre
GHOST_PHASE_T = 1.1             # dokunulmaz süre
RAISED_COLOR = (214, 210, 186)

# hazine goblini: arada bir ortaya çıkıp oyuncudan kaçan, sırtında çuval
# taşıyan bir yaratık. Vurmaz; GOBLIN_LIFE saniye içinde yakalanmazsa kaçar.
GOBLIN_MIN_WAVE = 3
GOBLIN_CHANCE = 0.18            # dalga başına goblin olasılığı (3. dalgadan)
GOBLIN_LIFE = 22.0              # yakalanmazsa kaçtığı süre
GOBLIN_COLOR = (120, 210, 90)


def curse_spawn_chance(curses):
    """Bir doğumun lanetli türden olma olasılığı (yalnızca yaratık lanetleri)."""
    n = sum(int(curses.get(k, 0)) for k in CURSE_KINDS)
    if n <= 0:
        return 0.0
    return min(CURSE_SPAWN_MAX, CURSE_SPAWN_BASE + CURSE_SPAWN_PER * (n - 1))


def pick_curse_kind(curses, rnd=random):
    kinds = [k for k in CURSE_KINDS if curses.get(k, 0) > 0]
    if not kinds:
        return None
    return rnd.choices(kinds, weights=[int(curses[k]) for k in kinds], k=1)[0]


def cursed_reward_values(key, tier, wave):
    """Ödülün sayıları (kademe çarpanı uygulanmış)."""
    m = CURSE_TIER_MULT[clamp(int(tier), 0, len(CURSE_TIER_MULT) - 1)]
    if key == "power":
        return dict(levels=int(round(5 * m)), hp=int(100 * m), dmg=0.50 * m)
    if key == "fortune":
        return dict(levels=int(round(3 * m)), luck=0.12 * m)   # 0.25 -> 0.12
    if key == "arsenal":
        return dict(wlevels=int(round(2 * m)), boost=0.10 * m)
    if key == "treasure":
        return dict(gold=int((600 + 120 * max(1, int(wave))) * m * GOLD_TRIM), coin=0.25 * m)
    if key == "fortress":
        return dict(hp=int(250 * m), armor=0.08 * m, shields=int(round(2 * m)))
    if key == "edge":
        return dict(crit=0.12 * m, critd=0.50 * m, aspd=0.15 * m)
    return {}


def cursed_reward_lines(key, vals):
    """Ödülün kartta görünen satırları."""
    out = []
    if vals.get("levels"):
        out.append(L("cu.r_levels", vals["levels"]))
    if vals.get("wlevels"):
        out.append(L("cu.r_wlevels", vals["wlevels"]))
    if vals.get("hp"):
        out.append(L("cu.r_hp", vals["hp"]))
    if vals.get("dmg"):
        out.append(L("cu.r_dmg", fmt_pct1(vals["dmg"])))
    if vals.get("luck"):
        out.append(L("cu.r_luck", fmt_pct1(vals["luck"])))
    if vals.get("boost"):
        out.append(L("cu.r_boost", fmt_pct1(vals["boost"])))
    if vals.get("gold"):
        out.append(L("cu.r_gold", fmt_num(vals["gold"])))
    if vals.get("coin"):
        out.append(L("cu.r_coin", fmt_pct1(vals["coin"])))
    if vals.get("armor"):
        out.append(L("cu.r_armor", fmt_pct1(vals["armor"])))
    if vals.get("shields"):
        out.append(L("cu.r_shields", vals["shields"]))
    if vals.get("crit"):
        out.append(L("cu.r_crit", fmt_pct1(vals["crit"])))
    if vals.get("critd"):
        out.append(L("cu.r_critd", fmt_pct1(vals["critd"])))
    if vals.get("aspd"):
        out.append(L("cu.r_aspd", fmt_pct1(vals["aspd"])))
    return out


class CursedShrine:
    """Lanetli sandık: kayalık bir mağara ağzı ve önünde zincirli sandık."""

    def __init__(self, x, y):
        self.x, self.y = x, y
        self.r = 64
        self.t = random.uniform(0, 10)
        self.alive = True
        self.opened = False         # teklifler bir kez açıldı mı (kapak açık)
        self.used = False           # bir teklif kabul edildi: çöküyor
        self.discovered = False     # oyuncu ekranında gördü mü
        self.die_t = 0.0
        self.lid = 0.0              # kapak açıklığı 0..1
        rnd = random.Random(int(x * 7 + y * 13))
        # mağara kemerinin taşları (sabit desen)
        self.stones = []
        for i in range(11):
            a = math.pi + i * math.pi / 10
            rr = 66 + rnd.uniform(-5, 6)
            self.stones.append((a, rr, rnd.uniform(12, 18), rnd.uniform(0.75, 1.15)))
        self.cracks = [(rnd.uniform(-0.9, 0.9), rnd.uniform(0.2, 1.0)) for _ in range(6)]
        self.motes = [(rnd.uniform(-50, 50), rnd.uniform(0, 1), rnd.uniform(0.5, 1.2)) for _ in range(10)]

    def in_range(self, p):
        return (not self.used) and dist(self.x, self.y + 30, p.x, p.y) < 92

    def update(self, dt):
        self.t += dt
        target = 1.0 if self.opened else 0.0
        self.lid += (target - self.lid) * min(1.0, dt * 6)
        if self.used:
            self.die_t += dt
            if self.die_t > 1.6:
                self.alive = False

    def draw(self, surf, t):
        x, y = self.x, self.y
        fade = 1.0 - clamp(self.die_t / 1.6, 0.0, 1.0)
        sink = 26 * (1.0 - fade)
        pulse = 0.5 + 0.5 * math.sin(self.t * 2.2)
        # zemin: yanan çatlaklar + mor sis
        blit_disc(surf, x, y + 34, 120, CURSE_COLOR, int((26 + 16 * pulse) * fade))
        for (dx, k) in self.cracks:
            ex = x + dx * 120
            ey = y + 40 + k * 46
            thick_line(surf, (x + dx * 30, y + 38), (ex, ey), 2.0,
                       scale_col(CURSE_COLOR, (0.45 + 0.4 * pulse) * fade + 0.1))
        # mağara ağzı: karanlık boşluk + taş kemer
        cave = pygame.Rect(0, 0, 112, 128)
        cave.midbottom = (int(x), int(y + 30 + sink))
        pygame.draw.ellipse(surf, (8, 4, 14), cave)
        pygame.draw.rect(surf, (8, 4, 14), (cave.x, cave.centery, cave.w, cave.h // 2))
        # içerideki dönen sis ve kırmızı gözler
        for i in range(3):
            a = self.t * (0.8 + i * 0.3) + i * 2.1
            add_glow(surf, x + math.cos(a) * 18, y - 18 + math.sin(a) * 10 + sink,
                     30 - i * 6, CURSE_COLOR, (0.22 + 0.10 * pulse) * fade)
        blink = (self.t % 4.2) < 0.15
        if not blink and fade > 0.3:
            for s_ in (-1, 1):
                ex_, ey_ = x + s_ * 13, y - 26 + sink
                add_glow(surf, ex_, ey_, 10, CURSE_RED, 0.8 * fade)
                circle_aa(surf, ex_, ey_, 3.0, (255, 120, 140))
        for (a, rr, sz, k) in self.stones:
            sx = x + math.cos(a) * rr * 0.92
            sy = y - 22 + math.sin(a) * rr * 1.05 + sink
            pts = [(sx + math.cos(a + j * math.tau / 5 + k) * sz * (0.8 + 0.2 * (j % 2)),
                    sy + math.sin(a + j * math.tau / 5 + k) * sz * 0.85)
                   for j in range(5)]
            poly_aa(surf, [(px, py + 2) for px, py in pts], OUTLINE)
            poly_aa(surf, pts, scale_col((92, 84, 104), 0.7 + 0.3 * fade))
            poly_aa(surf, poly_inset(pts, 0.55, dx=-2, dy=-2), (122, 112, 136))
        # kemerin tepesinde kafatası taşı
        kx, ky = x, y - 92 + sink
        circle_aa(surf, kx, ky, 12, (210, 204, 190))
        pygame.draw.rect(surf, (210, 204, 190), (int(kx - 6), int(ky + 6), 12, 8))
        for s_ in (-1, 1):
            circle_aa(surf, kx + s_ * 4.5, ky - 1, 3.2, (30, 10, 30))
            add_glow(surf, kx + s_ * 4.5, ky - 1, 7, CURSE_COLOR, 0.6 * pulse * fade)
        # sandık: koyu ahşap, mor rünler, çapraz zincir
        cw, chh = 58, 34
        cx_, cy_ = x, y + 36 + sink
        body = pygame.Rect(0, 0, cw, chh)
        body.center = (int(cx_), int(cy_))
        surf.blit(shadow_sprite(cw + 16), (body.x - 8, body.bottom - 8))
        pygame.draw.rect(surf, OUTLINE, body.inflate(4, 4), border_radius=6)
        pygame.draw.rect(surf, (74, 44, 52), body, border_radius=5)
        pygame.draw.rect(surf, (104, 64, 70), body.inflate(-8, -10), border_radius=4)
        for i in range(3):
            rx_ = body.x + 12 + i * 17
            rc = scale_col(CURSE_COLOR, 0.5 + 0.5 * math.sin(self.t * 3 + i))
            pygame.draw.line(surf, rc, (rx_, body.y + 12), (rx_ + 4, body.y + 22), 2)
            pygame.draw.line(surf, rc, (rx_ + 4, body.y + 12), (rx_, body.y + 22), 2)
        # kapak (açılınca yukarı kalkar, içinden ışık taşar)
        lid_h = 14
        lift = self.lid * 16
        lid = pygame.Rect(body.x - 2, body.y - lid_h - lift, cw + 4, lid_h)
        if self.lid > 0.05:
            add_glow(surf, cx_, body.y - 4, 46, CURSE_COLOR2, 0.8 * self.lid * fade)
            for i in range(4):
                a = -math.pi / 2 + (i - 1.5) * 0.35
                taper_line(surf, [(cx_, body.y), (cx_ + math.cos(a) * 70, body.y + math.sin(a) * 70)],
                           6 * self.lid, 0.5, scale_col(CURSE_COLOR2, 0.7 * fade))
        pygame.draw.rect(surf, OUTLINE, lid.inflate(4, 4), border_radius=6)
        pygame.draw.rect(surf, (88, 52, 60), lid, border_radius=5)
        pygame.draw.line(surf, (190, 160, 110), (lid.x + 4, lid.bottom - 3), (lid.right - 4, lid.bottom - 3), 2)
        # zincirler
        if not self.opened:
            for s_ in (-1, 1):
                for j in range(6):
                    k_ = j / 5.0
                    lx_ = body.centerx + s_ * (-cw / 2 + k_ * cw)
                    ly_ = body.y - 6 + k_ * (chh + 4)
                    pygame.draw.ellipse(surf, (150, 150, 168), (int(lx_ - 4), int(ly_ - 3), 8, 6), 2)
            circle_aa(surf, body.centerx, body.centery - 2, 6, (190, 170, 110))
            circle_aa(surf, body.centerx, body.centery - 1, 2, (40, 30, 30))
        # yükselen ruh zerreleri
        for (dx, ph0, sp) in self.motes:
            ph = (self.t * 0.35 * sp + ph0) % 1.0
            mx = x + dx + math.sin(self.t * 2 + dx) * 6
            my = y + 30 - ph * 140 + sink
            circle_aa(surf, mx, my, max(1.0, 2.6 * (1 - ph) * fade), CURSE_COLOR2)
        add_glow(surf, x, y, 110, CURSE_COLOR, (0.10 + 0.06 * pulse) * fade)

    def draw_prompt(self, surf, t, p):
        if self.used:
            return
        d = dist(self.x, self.y + 30, p.x, p.y)
        a = clamp((260 - d) / 120.0, 0.0, 1.0)
        if a <= 0:
            return
        txt = L("cu.prompt", key_label("use"))
        y = self.y - 128 + math.sin(t * 3) * 3
        w_ = text_width(txt, 15, True) + 26
        r_ = pygame.Rect(0, 0, w_, 26)
        r_.center = (int(self.x), int(y))
        bg = pygame.Surface(r_.size, pygame.SRCALPHA)
        pygame.draw.rect(bg, (24, 10, 34, int(220 * a)), bg.get_rect(), border_radius=12)
        pygame.draw.rect(bg, (*CURSE_COLOR, int(255 * a)), bg.get_rect(), width=2, border_radius=12)
        surf.blit(bg, r_.topleft)
        draw_text(surf, txt, r_.center, 15, CURSE_COLOR2, bold=True, center=True,
                  shadow=False, alpha=int(255 * a))


class CurseOverlay:
    """Lanetli sandığın teklif ekranı."""

    def __init__(self):
        self.cards = []
        self.btn_leave = pygame.Rect(0, 0, 0, 0)

    def rebuild(self, offers):
        n = max(1, len(offers))
        cw, chh, gap = 288, 360, 26
        x0 = VIRTUAL_W / 2 - (n * cw + (n - 1) * gap) / 2
        top = VIRTUAL_H / 2 - chh / 2 + 6
        self.cards = [(pygame.Rect(x0 + i * (cw + gap), top, cw, chh), o, i)
                      for i, o in enumerate(offers)]
        self.btn_leave = pygame.Rect(0, 0, 260, 44)
        self.btn_leave.midtop = (VIRTUAL_W / 2, top + chh + 18)

    def draw_and_handle(self, surf, run, mouse_pos, clicked, t):
        ov = pygame.Surface((VIRTUAL_W, VIRTUAL_H), pygame.SRCALPHA)
        ov.fill((14, 4, 22, 214))
        surf.blit(ov, (0, 0))
        add_glow(surf, VIRTUAL_W / 2, 90, 380, CURSE_COLOR, 0.25)
        top = self.cards[0][0].y if self.cards else 180
        title = L("cu.title")
        draw_text(surf, title, (VIRTUAL_W / 2, top - 92), 42, CURSE_COLOR2, bold=True, center=True)
        # damlayan harfler: başlığın altından süzülen mor damlalar
        tw_ = text_width(title, 42, True)
        for i in range(9):
            dx = -tw_ / 2 + (i + 0.5) * tw_ / 9
            ph = (t * 0.5 + i * 0.29) % 1.0
            circle_aa(surf, VIRTUAL_W / 2 + dx, top - 72 + ph * 26, 2.6 * (1 - ph), CURSE_COLOR)
        draw_text(surf, L("cu.sub"), (VIRTUAL_W / 2, top - 46), 15, (210, 190, 230), center=True)
        bonus = run.curse_score_bonus
        cl = run.player.eff_luck() * CAVE_LUCK_MULT + CAVE_LUCK_BASE
        draw_text(surf, L("cu.score_now", fmt_pct1(bonus)) + "   •   "
                  + L("cu.luck_line", fmt_pct1(cl)), (VIRTUAL_W / 2, top - 24), 12,
                  (176, 150, 210), center=True, shadow=False)
        result = None
        for rect, o, i in self.cards:
            hov = rect.collidepoint(mouse_pos)
            r2 = rect.move(0, math.sin(t * 2.6 + i) * 3 - (6 if hov else 0))
            self._card(surf, r2, o, run, t, hov)
            if hov and clicked:
                result = ("pick", i)
        hl = self.btn_leave.collidepoint(mouse_pos)
        panel(surf, self.btn_leave, bg=(40, 30, 50) if hl else (24, 20, 32),
              edge=lighten(CURSE_COLOR, 0.2) if hl else (90, 70, 110), alpha=240, radius=12, edge_w=2)
        draw_text(surf, L("cu.leave"), self.btn_leave.center, 17, TEXT, bold=True, center=True)
        draw_text(surf, L("cu.once"), (self.btn_leave.centerx, self.btn_leave.bottom + 12), 12,
                  (255, 120, 140), center=True)
        if hl and clicked and result is None:
            result = ("leave", None)
        return result

    def _card(self, surf, r2, o, run, t, hov):
        tier = int(o.get("tier", 0))
        rc = rarity_color(tier)
        kind = o["kind"]
        acc = {"pair": CURSE_COLOR, "gamble": (255, 196, 96), "blood": CURSE_RED}[kind]
        surf.blit(_panel_shadow(r2.w, r2.h, 18), (r2.x - 6, r2.y - 2))
        surf.blit(_lu_card_bg(r2.w, r2.h, acc, tier), r2.topleft)
        ink_frame(surf, r2, lighten(acc, 0.25) if hov else acc, 18, 3)
        # üst şerit: tür + kademe
        band = pygame.Rect(r2.x + 3, r2.y + 3, r2.w - 6, 30)
        pygame.draw.rect(surf, scale_col(acc, 0.55), band, border_top_left_radius=15,
                         border_top_right_radius=15)
        pygame.draw.rect(surf, acc, band.inflate(0, -6).move(0, -3),
                         border_top_left_radius=14, border_top_right_radius=14)
        draw_text(surf, L("cu.k_" + kind), (band.centerx, band.centery - 2), 15,
                  (16, 8, 22), bold=True, center=True, shadow=False)
        # kademe hapı
        rn = rarity_name(tier)
        pw_ = text_width(rn, 10, True) + 14
        pr_ = pygame.Rect(0, 0, pw_, 17)
        pr_.center = (r2.centerx, r2.y + 46)
        pygame.draw.rect(surf, rc, pr_, border_radius=8)
        draw_text(surf, rn, pr_.center, 10, (23, 17, 18), bold=True, center=True, shadow=False)
        # ödül simgesi
        ic, icol = CURSE_REWARD_ICONS.get(o["reward"], ("star", GOLD))
        add_glow(surf, r2.centerx, r2.y + 92, 44, icol, 0.30)
        pygame.draw.circle(surf, (14, 10, 22), (r2.centerx, r2.y + 92), 30)
        pygame.draw.circle(surf, icol, (r2.centerx, r2.y + 92), 30, 2)
        draw_icon(surf, r2.centerx, r2.y + 92, ic, icol, 18)
        draw_text(surf, L("cu.rw_" + o["reward"]), (r2.centerx, r2.y + 136), 18, TEXT,
                  bold=True, center=True)
        # ödül satırları (yeşil)
        y = r2.y + 156
        mult = 2 if kind == "gamble" else 1
        for ln in o["lines"][:4]:
            draw_text(surf, ("+ " if not ln.startswith("+") else "") + ln, (r2.x + 22, y), 13,
                      GREEN, bold=True, shadow=False)
            y += 19
        if kind == "gamble":
            draw_text(surf, L("cu.gamble_win", fmt_pct1(o["win"]), mult), (r2.x + 22, y + 2), 12,
                      (255, 214, 120), bold=True, shadow=False)
            y += 19
        # bedel (kırmızı)
        y = max(y + 6, r2.y + 250)
        pygame.draw.line(surf, scale_col(CURSE_RED, 0.6), (r2.x + 18, y - 6), (r2.right - 18, y - 6), 1)
        if kind == "blood":
            draw_text(surf, L("cu.blood_cost", fmt_pct1(BLOOD_PRICE)), (r2.x + 22, y), 13,
                      CURSE_RED, bold=True, shadow=False)
            draw_text(surf, L("cu.no_curse"), (r2.x + 22, y + 20), 11, (200, 170, 190),
                      shadow=False)
        else:
            cd = CURSE_DEFS.get(o["curse"], {})
            cc = cd.get("color", CURSE_RED)
            draw_icon(surf, r2.x + 30, y + 8, cd.get("icon", "skull"), cc, 8)
            draw_text(surf, L("cu.c_" + o["curse"]), (r2.x + 44, y), 13, CURSE_RED, bold=True,
                      shadow=False)
            for j, ln in enumerate(wrap_text(L("cu.cd_" + o["curse"]), 11, r2.w - 44)[:2]):
                draw_text(surf, ln, (r2.x + 22, y + 19 + j * 14), 11, (214, 180, 200), shadow=False)
            draw_text(surf, L("cu.score_plus", fmt_pct1(CURSE_SCORE_PER)), (r2.centerx, r2.bottom - 52),
                      12, (255, 214, 120), bold=True, center=True, shadow=False)
        if hov:
            br = pygame.Rect(r2.x + 18, r2.bottom - 40, r2.w - 36, 30)
            pygame.draw.rect(surf, acc, br, border_radius=10)
            draw_text(surf, L("cu.accept"), br.center, 15, (14, 8, 20), bold=True, center=True,
                      shadow=False)


class LevelUpOverlay:
    """Seviye atlama ekranı (yeniden tasarım)."""

    def __init__(self):
        self.cards = []
        self.btn_reroll = pygame.Rect(0, 0, 0, 0)
        self.btn_skip = pygame.Rect(0, 0, 0, 0)
        self.toast = ""
        self.toast_t = 0.0
        self.hand_sig = None        # elin imzası: değişince giriş animasyonu baştan
        self.enter_t0 = None
        self._prev_keys = {}

    def rebuild(self, choices):
        self.cards = []
        n = max(1, len(choices))
        card_w, card_h = 272, 356
        gap = 26
        total_w = n * card_w + (n - 1) * gap
        start_x = VIRTUAL_W / 2 - total_w / 2
        top = VIRTUAL_H / 2 - card_h / 2 - 8
        for i, ch in enumerate(choices):
            rect = pygame.Rect(start_x + i * (card_w + gap), top, card_w, card_h)
            self.cards.append((rect, ch, i))
        bw, bh = 236, 46
        by = top + card_h + 20
        self.btn_reroll = pygame.Rect(VIRTUAL_W / 2 - bw - 12, by, bw, bh)
        self.btn_skip = pygame.Rect(VIRTUAL_W / 2 + 12, by, bw, bh)
        sig = tuple((c.get("kind"), c.get("key"), c.get("rarity")) for c in choices)
        if sig != self.hand_sig:
            self.hand_sig = sig
            self.enter_t0 = None    # bir sonraki çizimde başlar

    def _key_edge(self, keycode):
        """Tuşa bu karede yeni mi basıldı?"""
        try:
            down = bool(pygame.key.get_pressed()[keycode])
        except Exception:
            return False
        was = self._prev_keys.get(keycode, False)
        self._prev_keys[keycode] = down
        return down and not was

    def _draw_action(self, surf, rect, label, free_left, cost, gold, mouse_pos, base_col,
                     icon="reroll", hotkey=None):
        """Alttaki yenile / pas geç düğmesi (simge + bedel)."""
        hover = rect.collidepoint(mouse_pos)
        afford = cost <= gold
        col = base_col if afford else (96, 78, 86)
        panel(surf, rect, bg=(68, 50, 51) if (hover and afford) else (39, 28, 29),
              edge=lighten(col, 0.25) if hover else col, alpha=244, radius=14, edge_w=2)
        # simge dairesi
        ix, iy = rect.x + 26, rect.centery
        pygame.draw.circle(surf, scale_col(col, 0.35), (ix, iy), 15)
        pygame.draw.circle(surf, col, (ix, iy), 15, 2)
        ic = lighten(col, 0.4)
        if icon == "reroll":
            rr = pygame.Rect(0, 0, 18, 18)
            rr.center = (ix, iy)
            pygame.draw.arc(surf, ic, rr, 0.3, math.pi * 1.6, 3)
            poly_aa(surf, [(ix + 9, iy - 1), (ix + 4, iy - 6), (ix + 11, iy - 7)], ic)
        else:
            for dx in (-5, 2):
                poly_aa(surf, [(ix + dx - 3, iy - 6), (ix + dx + 4, iy), (ix + dx - 3, iy + 6)], ic)
        txt = label + (f"  [{hotkey}]" if hotkey else "")
        draw_text(surf, txt, (rect.x + 50, rect.y + 6), 17,
                  TEXT if afford else (150, 130, 140), bold=True)
        if free_left > 0:
            sub = L("lu.free_left", free_left)
            scol = GREEN
            draw_text(surf, sub, (rect.x + 50, rect.bottom - 20), 12, scol, bold=True, shadow=False)
        elif cost <= 0:
            draw_text(surf, L("lu.free"), (rect.x + 50, rect.bottom - 20), 12, GREEN, bold=True,
                      shadow=False)
        else:
            scol = GOLD if afford else (190, 120, 120)
            draw_coin_label(surf, rect.x + 50 + coin_label_width(fmt_num(cost), 13, 6) / 2,
                            rect.bottom - 13, fmt_num(cost), scol, 13, icon_r=6)
        return hover and afford

    _DIM = None
    _TITLE_ART = None

    @classmethod
    def _dim_layer(cls):
        """Karartma: ortası biraz açık, kenarlara doğru koyulaşan vinyet."""
        if cls._DIM is None:
            d = pygame.Surface((VIRTUAL_W, VIRTUAL_H), pygame.SRCALPHA)
            d.fill((5, 6, 14, 196))
            for k in range(16):
                pygame.draw.rect(d, (2, 2, 8, 9), d.get_rect().inflate(-k * 34, -k * 20),
                                 width=18, border_radius=80)
            cls._DIM = d
        return cls._DIM

    @classmethod
    def _title_art(cls):
        """Başlığın arkasındaki kızıl kurdele + iki yanda altın defne dalları."""
        if cls._TITLE_ART is None:
            w, h = 760, 120
            a = pygame.Surface((w, h), pygame.SRCALPHA)
            cx, cy = w / 2, h / 2
            rw, rh = 250, 26
            gold, dgold = (232, 186, 90), (150, 112, 50)
            # kurdelenin katlanan uçları
            for sgn in (-1, 1):
                x0 = cx + sgn * (rw - 6)
                tail = [(x0, cy - rh + 10), (x0 + sgn * 64, cy - rh + 10), (x0 + sgn * 46, cy + 4),
                        (x0 + sgn * 64, cy + rh + 4), (x0, cy + rh + 4)]
                pygame.draw.polygon(a, (96, 22, 30), tail)
                pygame.draw.polygon(a, dgold, tail, 2)
            band = [(cx - rw, cy - rh), (cx + rw, cy - rh), (cx + rw - 10, cy + rh),
                    (cx - rw + 10, cy + rh)]
            pygame.draw.polygon(a, (150, 34, 44), band)
            pygame.draw.polygon(a, (186, 52, 60), [(cx - rw, cy - rh), (cx + rw, cy - rh),
                                                   (cx + rw - 3, cy - rh + 9), (cx - rw + 3, cy - rh + 9)])
            pygame.draw.polygon(a, gold, band, 3)
            pygame.draw.line(a, dgold, (cx - rw + 14, cy + rh - 6), (cx + rw - 14, cy + rh - 6), 1)
            # defne dalları
            for sgn in (-1, 1):
                bx = cx + sgn * (rw + 74)
                for i in range(7):
                    ang = math.radians(200 + i * 22) if sgn < 0 else math.radians(-20 - i * 22)
                    px_ = bx + math.cos(ang) * 30 * sgn * -1
                    py_ = cy + math.sin(ang) * 30
                    leaf = pygame.Surface((22, 10), pygame.SRCALPHA)
                    pygame.draw.ellipse(leaf, gold, leaf.get_rect())
                    pygame.draw.line(leaf, dgold, (2, 5), (20, 5), 1)
                    rl = pygame.transform.rotate(leaf, -math.degrees(ang) + 90 * sgn)
                    a.blit(rl, rl.get_rect(center=(px_, py_)))
                pygame.draw.arc(a, dgold, pygame.Rect(bx - 32, cy - 32, 64, 64),
                                math.radians(100) if sgn > 0 else math.radians(260 - 180),
                                math.radians(260) if sgn > 0 else math.radians(440 - 180), 2)
            cls._TITLE_ART = a
        return cls._TITLE_ART

    def _backdrop(self, surf, t):
        surf.blit(self._dim_layer(), (0, 0))
        cx, cy = VIRTUAL_W / 2, 92
        # yavaş dönen altın ışınlar
        rays = pygame.Surface((VIRTUAL_W, VIRTUAL_H), pygame.SRCALPHA)
        for i in range(14):
            a = t * 0.12 + i * math.tau / 14
            pts = [(cx, cy), (cx + math.cos(a - 0.05) * 900, cy + math.sin(a - 0.05) * 900),
                   (cx + math.cos(a + 0.05) * 900, cy + math.sin(a + 0.05) * 900)]
            pygame.draw.polygon(rays, (255, 214, 120, 9), pts)
        surf.blit(rays, (0, 0))
        add_glow(surf, cx, cy, 260, GOLD, 0.30)
        # yükselen kıvılcımlar
        for i in range(26):
            ph = (t * (0.08 + (i % 5) * 0.015) + i * 0.137) % 1.0
            x = (i * 97.3) % VIRTUAL_W
            y = VIRTUAL_H - ph * (VIRTUAL_H + 40)
            r = 1.0 + (i % 3) * 0.7
            circle_aa(surf, x + math.sin(t + i) * 8, y, r,
                      mix_col(GOLD, (200, 210, 255), (i % 4) / 4.0))

    def draw_and_handle(self, surf, run, mouse_pos, clicked, t):
        self._backdrop(surf, t)
        if self.enter_t0 is None:
            self.enter_t0 = t
            sfx("levelup", 0.35, 0.2)
        top = self.cards[0][0].y if self.cards else VIRTUAL_H / 2 - 156
        p = run.player
        # ---- başlık + seviye rozeti ----
        legend = any(c.get("legend") for c in (run.levelup_choices or ()))
        title = L("ui.legend_hand") if legend else L("ui.levelup")
        pop = ease_out_cubic(clamp((t - self.enter_t0) / 0.35, 0.0, 1.0))
        if legend:
            add_glow(surf, VIRTUAL_W / 2, VIRTUAL_H / 2, 520, LEGEND_COLOR2, 0.16)
        tsz = int(38 + 6 * (1.0 - pop))
        add_glow(surf, VIRTUAL_W / 2, top - 112, 170, GOLD, 0.22)
        # kurdele + defne, dönen kesikli ışık halkası
        art = self._title_art()
        if pop < 1.0:
            sc_ = 0.7 + 0.3 * pop
            art = pygame.transform.smoothscale(art, (int(art.get_width() * sc_),
                                                     int(art.get_height() * sc_)))
        surf.blit(art, art.get_rect(center=(VIRTUAL_W / 2, top - 112)))
        for i in range(24):
            a_ = t * 0.6 + i * math.tau / 24
            rx_, ry_ = 420, 64
            circle_aa(surf, VIRTUAL_W / 2 + math.cos(a_) * rx_, top - 112 + math.sin(a_) * ry_,
                      1.6 + 0.8 * math.sin(t * 3 + i), mix_col(GOLD, (255, 250, 220), (i % 3) / 3.0))
        if legend:
            tsz = int(tsz * 0.78)
        draw_text(surf, title, (VIRTUAL_W / 2, top - 112), tsz,
                  LEGEND_COLOR if legend else (255, 232, 150), bold=True, center=True)
        lvl_txt = L("lu.level_badge", run.levelup_hand_level())
        lw_ = text_width(lvl_txt, 13, True) + 26
        lr = pygame.Rect(0, 0, lw_, 22)
        lr.center = (VIRTUAL_W / 2, top - 80)
        pygame.draw.rect(surf, (36, 26, 56), lr, border_radius=11)
        ink_frame(surf, lr, PURPLE, 11, 2)
        draw_text(surf, lvl_txt, lr.center, 13, lighten(PURPLE, 0.35), bold=True, center=True,
                  shadow=False)
        # ---- yuva çipleri ----
        n_w = len(p.weapons)
        n_b = p.normal_book_count()
        n_r = p.rare_book_count()
        chips = [("sword", L("lu.chip_w", n_w, slot_max(p, 'w')), (150, 200, 255), n_w >= slot_max(p, 'w')),
                 ("book", L("lu.chip_b", n_b, slot_max(p, 'b')), (150, 230, 170), n_b >= slot_max(p, 'b')),
                 ("star", L("lu.chip_r", n_r, slot_max(p, 'r')), GOLD, n_r >= slot_max(p, 'r'))]
        widths = [text_width(c[1], 12, True) + 34 for c in chips]
        x = VIRTUAL_W / 2 - (sum(widths) + 10 * (len(chips) - 1)) / 2
        for (ic, txt, ccol, full), w_ in zip(chips, widths):
            cr = pygame.Rect(int(x), int(top - 58), int(w_), 22)
            cs = pygame.Surface(cr.size, pygame.SRCALPHA)
            pygame.draw.rect(cs, (*ccol, 40 if not full else 70), cs.get_rect(), border_radius=11)
            pygame.draw.rect(cs, (*ccol, 170), cs.get_rect(), width=1, border_radius=11)
            surf.blit(cs, cr.topleft)
            draw_icon(surf, cr.x + 13, cr.centery, ic, ccol, 6)
            draw_text(surf, txt, (cr.x + 24, cr.y + 4), 12, ccol, bold=True, shadow=False)
            x += w_ + 10
        if n_r >= slot_max(p, 'r'):
            hint = L("lu.hint_rare_full")
        elif n_w >= slot_max(p, 'w') and n_b >= slot_max(p, 'b'):
            hint = L("lu.hint_full")
        else:
            nxt = RARE_BOOK_EVERY - (run.levelup_hand_level() % RARE_BOOK_EVERY)
            hint = (L("lu.hint_rare_now") if nxt == RARE_BOOK_EVERY
                    else L("lu.hint_rare_in", BOOK_MAX_LEVEL, nxt))
        draw_text(surf, hint, (VIRTUAL_W / 2, top - 27), 12, (150, 156, 184), center=True,
                  shadow=False)
        # altın + şans (sağ üstte, kartların üstüne binmeden)
        luck_tip_rect = None
        gx = VIRTUAL_W / 2 + 380
        draw_coin_label(surf, gx, top - 70, fmt_num(run.gold_wallet), GOLD, 17, icon_r=8)
        if p.eff_luck() > 0:
            ltxt = L("ui.luck_label", fmt_pct1(p.eff_luck()))
            lx = gx - text_width(ltxt, 15, True) / 2
            draw_icon(surf, lx - 12, top - 38, "horseshoe", GREEN, 7)
            draw_text(surf, ltxt, (lx, top - 46), 15, GREEN, bold=True, shadow=False)
            luck_tip_rect = pygame.Rect(lx - 22, top - 49, text_width(ltxt, 15, True) + 28, 22)

        # ---- kartlar: sırayla süzülerek gelir ----
        result = None
        if self.cards:                 # kartların altında yumuşak zemin parıltısı
            fy = self.cards[0][0].bottom + 18
            add_glow(surf, VIRTUAL_W / 2, fy, 360, (120, 110, 200), 0.16)
            add_glow(surf, VIRTUAL_W / 2, fy, 160, GOLD, 0.10 + 0.04 * math.sin(t * 2))
        for rect, ch, idx in self.cards:
            k = ease_out_cubic(clamp((t - self.enter_t0 - 0.07 * idx) / 0.34, 0.0, 1.0))
            hover = rect.collidepoint(mouse_pos) and k > 0.95
            bob = math.sin(t * 3 + rect.x * 0.01) * 3 - (6 if hover else 0)
            r2 = rect.move(0, bob + (1.0 - k) * 90)
            if k < 1.0:
                add_glow(surf, r2.centerx, r2.centery, 160 * (1.0 - k) + 40,
                         rarity_color(int(ch.get("rarity") or 0)) if ch.get("rarity") is not None
                         else tuple(ch["color"]), 0.5 * (1.0 - k))
            draw_levelup_card(surf, r2, ch, run, t, hover)
            # tuş rozeti
            kb = pygame.Rect(r2.x + 10, r2.bottom - 30, 22, 20)
            pygame.draw.rect(surf, (23, 17, 18), kb, border_radius=6)
            ink_frame(surf, kb, (90, 96, 130), 6, 1)
            draw_text(surf, str(idx + 1), kb.center, 12, (200, 206, 230), bold=True, center=True,
                      shadow=False)
            if hover and clicked:
                result = ("pick", idx)
        for i, kc in enumerate((pygame.K_1, pygame.K_2, pygame.K_3)):
            if self._key_edge(kc) and i < len(self.cards) and result is None:
                result = ("pick", i)

        # ---- yenile / pas geç ----
        rc, sc = run.reroll_cost(), run.skip_cost()
        hov_r = self._draw_action(surf, self.btn_reroll, L("ui.reroll"),
                                  run.rerolls_left_free(), rc, run.gold_wallet,
                                  mouse_pos, (86, 150, 206), icon="reroll", hotkey="R")
        hov_s = self._draw_action(surf, self.btn_skip, L("ui.skip"),
                                  run.skips_left_free(), sc, run.gold_wallet,
                                  mouse_pos, (170, 130, 80), icon="skip")
        if clicked and result is None:
            if hov_r:
                result = ("reroll", None)
            elif hov_s:
                result = ("skip", None)
        if self._key_edge(pygame.K_r) and result is None and rc <= run.gold_wallet:
            result = ("reroll", None)

        # ---- şans ipucu ----
        if luck_tip_rect is not None and luck_tip_rect.collidepoint(mouse_pos):
            lines = wrap_text(L("ui.luck_tip"), 12, 300)[:4]
            tr_ = pygame.Rect(0, 0, 324, 16 + 17 * len(lines))
            tr_.midtop = (luck_tip_rect.centerx, luck_tip_rect.bottom + 6)
            tr_.right = min(tr_.right, VIRTUAL_W - 8)
            panel(surf, tr_, bg=(16, 22, 20), edge=GREEN, alpha=248, radius=8, edge_w=1)
            for i, ln in enumerate(lines):
                draw_text(surf, ln, (tr_.x + 12, tr_.y + 8 + i * 17), 12, TEXT,
                          shadow=False)

        # ---- kısa bilgi yazısı (yetersiz altın vb.) ----
        if self.toast_t > 0:
            self.toast_t = max(0.0, self.toast_t - 1 / 60.0)
            draw_text(surf, self.toast, (VIRTUAL_W / 2, self.btn_skip.bottom + 14), 15,
                      (240, 200, 120), bold=True, center=True)
        return result

    def say(self, msg):
        self.toast = msg
        self.toast_t = 1.6


def draw_restart_hold(surf, k, t):
    """Oyunda R basılı tutulurken ekranın üstünde dolan halka."""
    k = clamp(k, 0.0, 1.0)
    cx, cy = VIRTUAL_W / 2, 132
    txt = L("dr.restarting")
    w_ = text_width(txt, 15, True) + 64
    r = pygame.Rect(0, 0, int(w_), 40)
    r.center = (int(cx), int(cy))
    panel(surf, r, bg=(30, 20, 18), edge=(230, 150, 90), alpha=230, radius=14, edge_w=2)
    ix, iy = r.x + 22, r.centery
    pygame.draw.circle(surf, (60, 40, 30), (ix, iy), 12, 3)
    rr = pygame.Rect(0, 0, 26, 26)
    rr.center = (ix, iy)
    if k > 0.01:
        pygame.draw.arc(surf, (255, 190, 110), rr, math.pi / 2, math.pi / 2 + math.tau * k, 4)
    draw_text(surf, txt, (r.x + 42, r.y + 11), 15, (255, 214, 160), bold=True, shadow=False)
    fill = pygame.Rect(r.x + 4, r.bottom - 6, int((r.w - 8) * k), 3)
    pygame.draw.rect(surf, (255, 170, 90), fill, border_radius=2)


def draw_quest_strip(surf, run, rect, t):
    """Tüccar ekranındaki koşu görevleri listesi (dikey liste)."""
    qs = getattr(run, "quests", None) or []
    if not qs:
        return
    panel(surf, rect, bg=(22, 18, 24), edge=(120, 92, 70), alpha=232, radius=12, edge_w=2)
    draw_text(surf, L("q.title"), (rect.x + 16, rect.y + 9), 13, GOLD, bold=True, shadow=False)
    rh = (rect.h - 34) / max(1, len(qs))
    for i, q in enumerate(qs):
        y = rect.y + 30 + i * rh
        col = QUEST_TIER_COLORS[q["tier"]]
        ic, icol, _g = QUEST_DEFS.get(q["key"], ("star", GOLD, ()))
        row = pygame.Rect(rect.x + 10, int(y), rect.w - 20, int(rh - 4))
        bs = pygame.Surface(row.size, pygame.SRCALPHA)
        pygame.draw.rect(bs, (*col, 28), bs.get_rect(), border_radius=8)
        surf.blit(bs, row.topleft)
        draw_icon(surf, row.x + 14, row.centery, ic, icol, 7)
        tn = L("q.tier%d" % q["tier"])
        draw_text(surf, tn, (row.x + 30, row.centery - 7), 11, col, bold=True, shadow=False)
        draw_text(surf, L("q." + q["key"], q["goal"]), (row.x + 100, row.centery - 8), 13, TEXT, bold=True,
                  shadow=False)
        gt = "+%d" % QUEST_GEMS[q["tier"]]
        draw_coin_label(surf, row.right - 12 - coin_label_width(gt, 13, 6) / 2, row.centery, gt, GEM_COLOR,
                        13, icon="gem", icon_r=6, shadow=False)


def draw_quest_hud(surf, run, x, y, t):
    """Oyun içinde küçük görev kutusu: üç görev, ilerleme çubuklarıyla."""
    qs = getattr(run, "quests", None) or []
    if not qs:
        return 0
    w_, rh = 214, 22
    h_ = 22 + rh * len(qs)
    r = pygame.Rect(int(x), int(y), w_, h_)
    fl = clamp(getattr(run, "quest_flash", 0.0) / 2.4, 0.0, 1.0)
    bg = pygame.Surface(r.size, pygame.SRCALPHA)
    pygame.draw.rect(bg, (28, 20, 21, 150), bg.get_rect(), border_radius=9)
    pygame.draw.rect(bg, (*mix_col((80, 90, 130), GOLD, fl), 170), bg.get_rect(), width=1, border_radius=9)
    surf.blit(bg, r.topleft)
    if fl > 0:
        add_glow(surf, r.centerx, r.centery, r.w * 0.6, GOLD, 0.25 * fl)
    draw_text(surf, L("q.title"), (r.x + 8, r.y + 4), 10, (200, 190, 150), bold=True, shadow=False)
    for i, q in enumerate(qs):
        yy = r.y + 20 + i * rh
        col = QUEST_TIER_COLORS[q["tier"]]
        cur = min(q["goal"], run.quest_value(q["key"]))
        k = cur / max(1, q["goal"])
        done = q["done"]
        tc = (150, 230, 160) if done else (214, 218, 236)
        txt = L("q." + q["key"], q["goal"])
        if text_width(txt, 11, True) > w_ - 70:
            while txt and text_width(txt + "…", 11, True) > w_ - 70:
                txt = txt[:-1]
            txt += "…"
        draw_text(surf, txt, (r.x + 8, yy), 11, tc, bold=True, shadow=False)
        if done:
            gt = "+%d" % QUEST_GEMS[q["tier"]]
            draw_text(surf, gt, (r.right - 8, yy), 11, GEM_COLOR, bold=True, right=True, shadow=False)
            cx_ = r.right - 16 - text_width(gt, 11, True)
            pygame.draw.lines(surf, GREEN, False, [(cx_ - 7, yy + 6), (cx_ - 4, yy + 10), (cx_ + 2, yy + 2)], 2)
        else:
            draw_text(surf, "%s/%s" % (fmt_num(cur), fmt_num(q["goal"])), (r.right - 8, yy), 10,
                      (170, 176, 200), right=True, shadow=False)
        bar = pygame.Rect(r.x + 8, yy + 15, w_ - 16, 3)
        pygame.draw.rect(surf, (59, 43, 45), bar, border_radius=2)
        if k > 0:
            pygame.draw.rect(surf, GREEN if done else col, (bar.x, bar.y, max(2, int(bar.w * k)), 3),
                             border_radius=2)
    return h_


# harita seçimi - manzara kartları + yakınlaşan ayrıntı penceresi. oyna'ya
# basınca dört büyük kart çıkar; her kartın üstünde o haritanın elle çizilmiş
# manzarası ve içinde dolaşan kendi yaratıkları var.
_MAP_SCENES = {}
MS_CARD_SCENE = (272, 236)       # kart manzarasının boyu
MS_BIG_SCENE = (440, 236)        # ayrıntı penceresindeki manzara
MS_ZOOM_TIME = 0.26              # kartın büyüme / küçülme süresi (sn)
MS_BOSS_PORTRAIT = 112           # ayrıntı penceresindeki patron portresi (px)
# Kartlarda dolaşan üç yaratık (arena türü; haritada o haritanın karşılığı
# çizilir)
MS_SCENE_KINDS = ("red", "yellow", "tank")
MS_BEST_KINDS = ("red", "blue", "yellow", "tank", "sprinter", "brute",
                 "elite", "bomber", "healer", "wizard", "stinger")


def _vgrad(surf, rect, top, bot):
    """Dikey renk geçişi (satır satır; yalnız önbelleğe çizerken kullanılır)."""
    x, y, w, h = [int(v) for v in rect]
    for i in range(max(1, h)):
        pygame.draw.line(surf, mix_col(top, bot, i / max(1, h - 1)), (x, y + i), (x + w - 1, y + i))


def _alpha_poly(surf, pts, col, a):
    """Saydam çokgen (sis, ışık huzmesi, kuzey ışığı)."""
    xs = [p[0] for p in pts]
    ys = [p[1] for p in pts]
    x0, y0 = int(min(xs)) - 1, int(min(ys)) - 1
    w, h = int(max(xs)) - x0 + 2, int(max(ys)) - y0 + 2
    if w <= 0 or h <= 0:
        return
    lay = pygame.Surface((w, h), pygame.SRCALPHA)
    pygame.draw.polygon(lay, (col[0], col[1], col[2], int(a)), [(px - x0, py - y0) for px, py in pts])
    surf.blit(lay, (x0, y0))


def _ridge(w, base, amp, n, rng, sharp=True):
    """Dağ / tepe sırtı noktaları (soldan sağa)."""
    pts = []
    for i in range(n + 1):
        x = w * i / n
        if sharp:
            y = base - amp * (0.35 + 0.65 * rng.random()) * (1 if i % 2 else 0.45)
        else:
            y = base - amp * (0.5 + 0.5 * math.sin(i * 1.3 + rng.random()))
        pts.append((x, y))
    return pts


def _pine(surf, x, y, hgt, col, snow=None):
    """Kat kat çam ağacı; snow verilirse dalların üstü karlı."""
    trunk = pygame.Rect(0, 0, max(2, int(hgt * 0.10)), int(hgt * 0.18))
    trunk.midtop = (int(x), int(y - hgt * 0.18))
    pygame.draw.rect(surf, (52, 36, 30), trunk)
    for k in range(3):
        top = y - hgt * (1.0 - k * 0.24)
        half = hgt * (0.20 + k * 0.08)
        bot = y - hgt * (0.46 - k * 0.20)
        tri = [(x, top), (x - half, bot), (x + half, bot)]
        pygame.draw.polygon(surf, col, tri)
        if snow:
            pygame.draw.polygon(surf, snow, [(x, top), (x - half * 0.45, top + (bot - top) * 0.45),
                                             (x + half * 0.45, top + (bot - top) * 0.45)])


def _scene_stone(s, w, h, rng):
    hz = int(h * 0.52)
    _vgrad(s, (0, 0, w, hz), (20, 22, 52), (214, 120, 84))
    for _ in range(26):
        s.set_at((rng.randrange(w), rng.randrange(max(1, int(hz * 0.55)))), (210, 210, 236))
    add_glow(s, w * 0.5, hz, w * 0.40, (255, 160, 90), 0.40)
    # kolezyum duvarı: iki kat kemer
    wt, wb = int(h * 0.20), hz + int(h * 0.05)
    pygame.draw.rect(s, (74, 66, 86), (0, wt, w, wb - wt))
    pygame.draw.rect(s, (104, 94, 118), (0, wt - 4, w, 6))
    for (y0, y1, n, lit) in ((wt + h * 0.035, wt + h * 0.135, 10, (60, 44, 52)),
                             (wt + h * 0.16, wb - h * 0.015, 8, (150, 90, 64))):
        aw = w / n
        for i in range(n):
            ax = i * aw + aw * 0.2
            r_ = pygame.Rect(int(ax), int(y0 + (y1 - y0) * 0.30), int(aw * 0.6), int((y1 - y0) * 0.70))
            pygame.draw.rect(s, lit, r_)
            pygame.draw.ellipse(s, lit, (r_.x, int(y0), r_.w, int((y1 - y0) * 0.62)))
        pygame.draw.line(s, (96, 86, 108), (0, int(y1) + 2), (w, int(y1) + 2), 2)
    # sancaklar
    for i in range(4):
        bx = w * (0.16 + i * 0.23)
        ban = [(bx - 7, wt + 2), (bx + 7, wt + 2), (bx + 7, wt + h * 0.13), (bx, wt + h * 0.11),
               (bx - 7, wt + h * 0.13)]
        pygame.draw.polygon(s, (170, 40, 46) if i % 2 == 0 else (60, 70, 160), ban)
        pygame.draw.polygon(s, OUTLINE, ban, 1)
    # zemin: perspektifli taş döşeme
    _vgrad(s, (0, wb, w, h - wb), (104, 98, 118), (58, 56, 72))
    vx, vy = w * 0.5, wb - h * 0.55
    for i in range(-9, 10):
        xb = w * 0.5 + i * w * 0.12
        k_ = (wb - vy) / (h - vy)
        xt = vx + (xb - vx) * k_
        pygame.draw.line(s, (78, 74, 92), (xt, wb), (xb, h), 1)
    yy, step = wb + 4, 5.0
    while yy < h:
        pygame.draw.line(s, (78, 74, 92), (0, int(yy)), (w, int(yy)), 1)
        yy += step
        step *= 1.32
    er = pygame.Rect(0, 0, int(w * 0.50), int(h * 0.16))
    er.center = (int(w * 0.5), int(wb + (h - wb) * 0.55))
    pygame.draw.ellipse(s, (140, 128, 160), er, 3)
    pygame.draw.ellipse(s, (120, 110, 140), er.inflate(-int(w * 0.16), -int(h * 0.05)), 2)
    # yan sütunlar
    for px in (int(w * 0.05), int(w * 0.95)):
        col_r = pygame.Rect(0, 0, int(w * 0.075), int(h * 0.62))
        col_r.midbottom = (px, int(h * 0.96))
        pygame.draw.rect(s, OUTLINE, col_r.inflate(4, 4))
        pygame.draw.rect(s, (128, 120, 146), col_r)
        pygame.draw.rect(s, (156, 148, 176), (col_r.x + 3, col_r.y, 4, col_r.h))
        cap = pygame.Rect(0, 0, col_r.w + 12, 8)
        cap.midbottom = (px, col_r.y + 2)
        pygame.draw.rect(s, (150, 140, 170), cap)
        bowl = pygame.Rect(0, 0, col_r.w + 6, 9)
        bowl.midbottom = (px, cap.y + 2)
        pygame.draw.rect(s, (70, 50, 40), bowl, border_radius=3)


def _scene_frost(s, w, h, rng):
    hz = int(h * 0.60)
    _vgrad(s, (0, 0, w, hz), (8, 14, 40), (64, 112, 156))
    for _ in range(40):
        s.set_at((rng.randrange(w), rng.randrange(max(1, int(hz * 0.7)))), (220, 236, 255))
    # kuzey ışığı
    for band, (col, a, base, amp) in enumerate((((90, 255, 180), 60, 0.20, 0.07),
                                                ((120, 200, 255), 48, 0.28, 0.06))):
        top, bot = [], []
        for i in range(25):
            x = w * i / 24
            yc = h * base + math.sin(i * 0.55 + band * 1.7) * h * amp
            top.append((x, yc - h * 0.05))
            bot.append((x, yc + h * 0.04 + math.sin(i * 1.3) * h * 0.012))
        _alpha_poly(s, top + bot[::-1], col, a)
    # uzak ve yakın dağlar (karlı tepeler)
    for (base, amp, n, col, cap) in ((hz + 2, h * 0.30, 9, (78, 104, 148), (226, 236, 250)),
                                      (hz + 6, h * 0.20, 7, (52, 72, 112), (206, 222, 244))):
        pts = _ridge(w, base, amp, n, rng)
        pygame.draw.polygon(s, col, [(0, base)] + pts + [(w, base)])
        for i in range(1, len(pts) - 1, 2):
            px_, py_ = pts[i]
            lx, ly = pts[i - 1]
            rx, ry = pts[i + 1]
            k = 0.32
            pygame.draw.polygon(s, cap, [(px_, py_), (px_ + (lx - px_) * k, py_ + (ly - py_) * k),
                                         (px_ + (rx - px_) * k, py_ + (ry - py_) * k)])
    # kar ovası + donmuş göl
    _vgrad(s, (0, hz, w, h - hz), (214, 230, 246), (160, 188, 222))
    lake = pygame.Rect(0, 0, int(w * 0.62), int(h * 0.16))
    lake.center = (int(w * 0.52), int(hz + (h - hz) * 0.42))
    pygame.draw.ellipse(s, (120, 186, 226), lake)
    pygame.draw.ellipse(s, (170, 222, 248), lake.inflate(-int(w * 0.10), -int(h * 0.05)))
    for _ in range(5):
        cx_ = lake.x + rng.randrange(lake.w)
        cy_ = lake.y + lake.h // 2 + rng.randrange(-lake.h // 4, lake.h // 4 + 1)
        pygame.draw.line(s, (236, 248, 255), (cx_, cy_), (cx_ + rng.randrange(-16, 17), cy_ + rng.randrange(-4, 5)), 1)
    # çamlar
    for i in range(7):
        side = i % 2
        x = (w * (0.02 + 0.07 * i) if side == 0 else w * (0.98 - 0.07 * i))
        _pine(s, x, hz + h * (0.06 + 0.03 * (i % 3)), h * (0.26 + 0.05 * (i % 2)), (30, 70, 64), (236, 244, 252))


def _scene_jungle(s, w, h, rng):
    _vgrad(s, (0, 0, w, h), (22, 54, 40), (8, 24, 16))
    # ışık huzmeleri
    for i in range(3):
        x0 = w * (0.25 + 0.25 * i)
        _alpha_poly(s, [(x0, 0), (x0 + w * 0.06, 0), (x0 + w * 0.20, h), (x0 + w * 0.08, h)], (220, 255, 170), 22)
    # uzaktaki tapınak (basamaklı)
    base_y = h * 0.62
    for k in range(5):
        tw, th_ = w * (0.42 - k * 0.07), h * 0.065
        r_ = pygame.Rect(0, 0, int(tw), int(th_))
        r_.midbottom = (int(w * 0.5), int(base_y - k * th_))
        pygame.draw.rect(s, (64, 86, 70) if k % 2 == 0 else (74, 98, 78), r_)
        pygame.draw.line(s, (50, 120, 60), r_.topleft, r_.topright, 2)
    door = pygame.Rect(0, 0, int(w * 0.06), int(h * 0.09))
    door.midbottom = (int(w * 0.5), int(base_y))
    pygame.draw.rect(s, (16, 22, 18), door)
    # sis
    _alpha_poly(s, [(0, h * 0.50), (w, h * 0.46), (w, h * 0.70), (0, h * 0.72)], (150, 190, 160), 46)
    # arka ağaçlar
    for i in range(6):
        x = w * (0.05 + 0.18 * i) + rng.randrange(-8, 9)
        tw_ = max(4, int(w * 0.03))
        pygame.draw.rect(s, (40, 30, 24), (int(x), 0, tw_, int(h * 0.74)))
        for k in range(4):
            circle_aa(s, x + tw_ / 2 + rng.randrange(-22, 23), rng.randrange(0, int(h * 0.20)),
                      w * (0.07 + 0.03 * rng.random()), (26, 76 + rng.randrange(30), 40))
    # zemin
    _vgrad(s, (0, int(h * 0.70), w, int(h * 0.30) + 1), (30, 70, 36), (16, 40, 22))
    # eğreltiotları
    for i in range(9):
        fx0 = w * (0.04 + 0.12 * i) + rng.randrange(-6, 7)
        fy0 = h * (0.86 + 0.08 * rng.random())
        for k in range(5):
            a = math.pi * (1.15 + 0.175 * k)
            ln = h * (0.10 + 0.03 * rng.random())
            tip = (fx0 + math.cos(a) * ln, fy0 + math.sin(a) * ln)
            pygame.draw.line(s, (60, 150, 70), (fx0, fy0), tip, 3)
            pygame.draw.line(s, (90, 190, 90), (fx0, fy0), tip, 1)
    # ön ağaçlar ve sarmaşıklar
    for x in (int(w * 0.03), int(w * 0.93)):
        pygame.draw.rect(s, (54, 38, 28), (x - 8, 0, 18, h))
        pygame.draw.line(s, (78, 56, 40), (x - 4, 0), (x - 4, h), 2)
    for i in range(5):
        x0 = w * (0.12 + 0.19 * i)
        ln = h * (0.25 + 0.20 * rng.random())
        pts = [(x0 + math.sin(k * 0.8 + i) * 5, ln * k / 8) for k in range(9)]
        pygame.draw.lines(s, (40, 110, 50), False, pts, 2)
        for k in range(2, 9, 2):
            px_, py_ = pts[k]
            pygame.draw.ellipse(s, (70, 160, 70), (int(px_ - 4), int(py_ - 2), 8, 5))


def _scene_desert(s, w, h, rng):
    hz = int(h * 0.58)
    _vgrad(s, (0, 0, w, hz), (62, 28, 72), (252, 156, 84))
    sx_, sy_ = w * 0.72, hz - h * 0.14
    add_glow(s, sx_, sy_, h * 0.45, (255, 170, 90), 0.55)
    circle_aa(s, sx_, sy_, h * 0.11, (255, 214, 140))
    # piramitler
    for (px_, pw, ph) in ((0.30, 0.34, 0.26), (0.52, 0.22, 0.17), (0.12, 0.16, 0.11)):
        cx_ = w * px_
        top = (cx_, hz - h * ph)
        lft, rgt = (cx_ - w * pw / 2, hz + 2), (cx_ + w * pw / 2, hz + 2)
        mid = (cx_ + w * pw * 0.12, hz + 2)
        pygame.draw.polygon(s, (226, 162, 96), [top, lft, mid])
        pygame.draw.polygon(s, (164, 102, 64), [top, mid, rgt])
        for k in range(1, 5):
            yk = top[1] + (hz - top[1]) * k / 5
            hw = (w * pw / 2) * k / 5
            pygame.draw.line(s, (150, 96, 58), (cx_ - hw, yk), (cx_ + hw, yk), 1)
    # kum tepeleri (üç kat)
    for i, col in enumerate(((206, 118, 66), (224, 146, 80), (238, 176, 104))):
        base = hz + (h - hz) * (0.10 + 0.32 * i)
        pts = [(0, h)]
        for k in range(31):
            x = w * k / 30
            pts.append((x, base + math.sin(k * 0.42 + i * 1.9) * h * 0.035 + math.sin(k * 0.17 + i) * h * 0.02))
        pts.append((w, h))
        pygame.draw.polygon(s, col, pts)
        pygame.draw.lines(s, lighten(col, 0.18), False, pts[1:-1], 2)
    # kaktüsler
    for (cx_, cy_, ch) in ((0.84, 0.80, 0.22), (0.08, 0.86, 0.16)):
        x, y, hh = w * cx_, h * cy_, h * ch
        pygame.draw.rect(s, (52, 120, 64), (int(x - 5), int(y - hh), 10, int(hh)), border_radius=5)
        pygame.draw.rect(s, (52, 120, 64), (int(x - 15), int(y - hh * 0.70), 8, int(hh * 0.34)), border_radius=4)
        pygame.draw.rect(s, (52, 120, 64), (int(x - 15), int(y - hh * 0.42), 12, 7), border_radius=3)
        pygame.draw.rect(s, (52, 120, 64), (int(x + 7), int(y - hh * 0.82), 8, int(hh * 0.30)), border_radius=4)
        pygame.draw.rect(s, (52, 120, 64), (int(x + 3), int(y - hh * 0.58), 12, 7), border_radius=3)


_SCENE_PAINTERS = {"stone": _scene_stone, "frost": _scene_frost,
                   "jungle": _scene_jungle, "desert": _scene_desert}


def map_scene(theme, w, h):
    """Haritanın elle çizilmiş manzarası (önbellekli, durağan katman)."""
    key = (theme, int(w), int(h))
    img = _MAP_SCENES.get(key)
    if img is None:
        img = pygame.Surface((int(w), int(h)))
        _SCENE_PAINTERS.get(theme, _scene_stone)(img, int(w), int(h), random.Random(sum(map(ord, theme)) * 131))
        _MAP_SCENES[key] = img
    return img


_MS_ENEMIES = {}


def ms_creature(theme, kind, slot=0):
    """Ekranda gösterilen (oyuna girmeyen) bir yaratık örneği - önbellekli."""
    key = (theme, kind, slot)
    e = _MS_ENEMIES.get(key)
    if e is None:
        mv = map_variant(theme, kind) if theme != "stone" else None
        e = (Enemy(None, 0, 0, 1.0, 1.0, wave=5, variant=mv) if mv
             else Enemy(kind, 0, 0, 1.0, 1.0, wave=5))
        e.spawn_t = 9.0
        e.shoot_cd = 2.0
        e.walk = (slot * 1.7 + len(kind)) * 0.9
        _MS_ENEMIES[key] = e
    return e


def ms_creature_name(theme, kind):
    """Yaratığın adı güncel dilde (önbellekteki örneğin adı eski dilde kalabilir)."""
    mv = map_variant(theme, kind) if theme != "stone" else None
    if mv:
        return LX("en." + mv, MAP_ENEMIES[mv]["name"])
    return LX("en." + kind, kind)


def ms_draw_creature(surf, theme, kind, x, y, r, t, face=(1.0, 0.2), slot=0, walk_speed=3.0):
    """Gösterim yaratığını çizer."""
    e = ms_creature(theme, kind, slot)
    e.face_x, e.face_y = face
    e.walk = t * walk_speed + slot * 1.3
    e.hit_flash = 0.0
    e.x, e.y, e.radius = x, y, r
    e.draw(surf, t)


def draw_map_scene(surf, rect, theme, t, creatures=True):
    """Manzara + canlı katman (kar / ateşböceği / kum / meşale) + dolaşan yaratıklar."""
    rect = pygame.Rect(rect)
    img = _MAP_SCENES.get((theme, rect.w, rect.h))
    if img is None:
        pygame.draw.rect(surf, (24, 28, 42), rect)
        draw_text(surf, "...", rect.center, 18, TEXT_DIM, center=True)
        return
    surf.blit(img, rect.topleft)
    prev = surf.get_clip()
    surf.set_clip(rect)
    w, h = rect.w, rect.h
    if theme == "frost":
        for k in range(26):
            sp = 0.06 + (k % 5) * 0.025
            ph = (t * sp + k * 0.137) % 1.0
            x = rect.x + (k * 53 + math.sin(t * 0.8 + k) * 10) % w
            circle_aa(surf, x, rect.y + ph * h, 1.2 + (k % 3) * 0.5, WHITE)
    elif theme == "jungle":
        for k in range(16):
            a_ = 0.5 + 0.5 * math.sin(t * 2.6 + k * 1.7)
            x = rect.x + (k * 61) % w + math.sin(t * 0.6 + k) * 12
            y = rect.y + h * 0.25 + (k * 37) % int(h * 0.65) + math.cos(t * 0.5 + k) * 8
            if a_ > 0.25:
                add_glow(surf, x, y, 7, (200, 255, 110), 0.35 * a_)
                circle_aa(surf, x, y, 1.2 + a_, (230, 255, 150))
    elif theme == "desert":
        for k in range(12):
            ph = (t * (0.35 + (k % 4) * 0.08) + k * 0.21) % 1.0
            x = rect.x + (ph * 1.4 - 0.2) * w
            y = rect.y + h * 0.55 + (k * 23) % int(h * 0.42)
            pygame.draw.line(surf, (250, 214, 150), (x, y), (x + 12 + (k % 3) * 6, y), 1)
    else:
        for px in (rect.x + int(w * 0.05), rect.x + int(w * 0.95)):
            fy = rect.y + int(h * 0.96) - int(h * 0.62) - 16
            fl = 0.6 + 0.4 * math.sin(t * 9 + px)
            add_glow(surf, px, fy, 20 + 6 * fl, (255, 150, 60), 0.55)
            pygame.draw.polygon(surf, (255, 170, 70), [(px - 6, fy + 6), (px, fy - 10 - 4 * fl), (px + 6, fy + 6)])
            pygame.draw.polygon(surf, (255, 236, 160), [(px - 3, fy + 5), (px, fy - 3 - 2 * fl), (px + 3, fy + 5)])
    if creatures:
        r = h * 0.072
        spots = ((0.26, 0.80, 1.0), (0.52, 0.70, -1.0), (0.76, 0.84, 1.0))
        for i, kind in enumerate(MS_SCENE_KINDS):
            fx_, fy_, dirx = spots[i]
            sway = math.sin(t * 0.7 + i * 2.1) * w * 0.05
            x = rect.x + w * fx_ + sway
            y = rect.y + h * fy_ + math.sin(t * 1.9 + i) * 1.5
            rr = r * (1.35 if kind == "tank" else 1.0)
            vx = math.cos(t * 0.7 + i * 2.1) * dirx
            face = (1.0 if vx >= 0 else -1.0, 0.25)
            ms_draw_creature(surf, theme, kind, x, y, rr, t, face=face, slot=i)
    surf.set_clip(prev)


_MS_BOSS_CACHE = {}


def ms_boss_portrait(theme, kind, size, t, refresh=True):
    """Patron portresi: gerçek Boss çizimi küçük bir yüzeye. refresh=False iken (ve önbellekte varsa) eski kare kullanılır: pencere beş patronu sırayla, karede bir tane yeniler."""
    key = (theme, kind, size)
    ent = _MS_BOSS_CACHE.get(key)
    frame = int(t * 12)
    if ent is not None and (ent[0] == frame or not refresh):
        return ent[1]
    b = ent[2] if ent is not None else None
    if b is None:
        b = Boss(kind, 0, 0, 1.0, 1.0, 10, hellish=False, theme=None if theme == "stone" else theme)
        b.spawn_t = 9.0
        # portre boyunda doğrudan çizilir (büyük çizip küçültmek pahalıydı)
        b.radius = BOSS_DEFS[kind]["radius"] * size / 210.0
    img = pygame.Surface((size, size), pygame.SRCALPHA)
    b.x, b.y = size / 2.0, size / 2.0 + 3
    b.face_x, b.face_y = 0.35, 0.94
    b.gait = t * 2.0
    global _GLOW_ON_ALPHA
    _GLOW_ON_ALPHA = True
    try:
        b.draw(img, t, hud=False)
    finally:
        _GLOW_ON_ALPHA = False
    _MS_BOSS_CACHE[key] = (frame, img, b)
    return img


def ms_boss_name(theme, kind):
    if theme == "stone":
        return BOSS_DEFS[kind]["name"]
    return map_boss_name(theme, kind, BOSS_DEFS[kind]["name"])


def ms_weapons_for(theme):
    """Bu haritada açılan silahlar: [(silah, başarım ya da None)]."""
    out = []
    if theme == "stone":
        for w in BOSS_WEAPONS:
            reqs = weapon_reqs(w)
            if reqs and all(rq.get("kind") == "stat" for rq in reqs):
                out.append((w, None))
        return out
    for a in MAP_ACHS:
        if a["map"] != theme:
            continue
        w = next((w for w in BOSS_WEAPONS for rq in weapon_reqs(w)
                  if rq.get("kind") == "ach" and rq.get("ach") == a["id"]), None)
        out.append((w, a))
    return out


def ms_records(save, theme):
    """Ayrıntı penceresindeki rekor kutuları: [(etiket, değer)]."""
    st = save.data.get("stats", {}) or {}

    def g(k):
        try:
            return st.get(k, 0) or 0
        except Exception:
            return 0
    if theme == "frost":
        return [(L("ms.r_wave"), fmt_num(int(g("best_frost_wave")))),
                (L("ms.r_kills"), fmt_num(int(g("frost_kills")))),
                (L("ms.r_bosses"), fmt_num(int(g("frost_bosses"))))]
    if theme == "jungle":
        return [(L("ms.r_time"), fmt_time(float(g("best_jungle_time")))),
                (L("ms.r_kills"), fmt_num(int(g("jungle_kills")))),
                (L("ms.r_bosses"), fmt_num(int(g("jungle_bosses"))))]
    if theme == "desert":
        return [(L("ms.r_wave"), fmt_num(int(g("best_desert_wave")))),
                (L("ms.r_kills"), fmt_num(int(g("desert_kills")))),
                (L("ms.r_dashes"), fmt_num(int(g("desert_dashes"))))]
    return [(L("ms.r_score"), fmt_num(int(g("best_score")))),
            (L("ms.r_wave"), fmt_num(int(g("best_wave")))),
            (L("ms.r_kills"), fmt_num(int(g("total_kills"))))]


def ms_fit(text, size, max_w, bold=False):
    """Metni genişliğe sığdır (gerekirse küçült, en son '...' ile kes)."""
    text = TRX(text)
    sz = size
    while sz > 9 and text_width(text, sz, bold) > max_w:
        sz -= 1
    if text_width(text, sz, bold) <= max_w:
        return text, sz
    while text and text_width(text + "…", sz, bold) > max_w:
        text = text[:-1]
    return text + "…", sz


# Haritanın artıları / eksileri (metin anahtarları)
MAP_PROS = {
    "stone": ("ms.world_on", "ms.hell_on"),
    "frost": ("ms.frost_p", "ms.ach_n"),
    "jungle": ("ms.jungle_p", "ms.ach_n"),
    "desert": ("ms.desert_p", "ms.ach_n"),
}
MAP_CONS = {
    "stone": ("ms.no_ach",),
    "frost": ("ms.frost_c", "ms.no_hell", "ms.world_off"),
    "jungle": ("ms.jungle_c", "ms.no_hell", "ms.world_off"),
    "desert": ("ms.desert_c", "ms.no_hell", "ms.world_off"),
}


def _ms_rule_lines(theme):
    out = []
    for k_ in MAP_PROS[theme]:
        txt = L(k_, sum(1 for a in MAP_ACHS if a["map"] == theme)) if k_ == "ms.ach_n" else L(k_)
        out.append((True, txt))
    for k_ in MAP_CONS[theme]:
        out.append((False, L(k_)))
    return out


_MS_CACHE = {}
_MS_CARDS = {}


def _ms_arrow(good):
    """Artı (yeşil, yukarı) / eksi (kırmızı, aşağı) üçgeni - bir kez çizilir."""
    key = ("arrow", good)
    img = _MS_CACHE.get(key)
    if img is None:
        img = pygame.Surface((12, 12), pygame.SRCALPHA)
        if good:
            poly_aa(img, [(1, 9), (6, 3), (11, 9)], GREEN)
        else:
            poly_aa(img, [(1, 3), (11, 3), (6, 9)], (255, 120, 120))
        _MS_CACHE[key] = img
    return img


_MS_EMB = {}


def ms_weapon_emblem(surf, cx, cy, h, w, locked):
    """Küçük silah arması: bir kez çizilip saklanır (arma çizimi ağır"""
    key = (w["key"], int(h), bool(locked))
    img = _MS_EMB.get(key)
    if img is None:
        size = int(h * 2.2) + 4
        img = pygame.Surface((size, size), pygame.SRCALPHA)
        global _GLOW_ON_ALPHA
        _GLOW_ON_ALPHA = True
        try:
            draw_weapon_emblem(img, size / 2.0, size / 2.0, h, w, 0.0, locked=locked)
        finally:
            _GLOW_ON_ALPHA = False
        _MS_EMB[key] = img
    if surf is not None:
        surf.blit(img, (int(cx - img.get_width() / 2), int(cy - img.get_height() / 2)))


def _ms_dim(alpha):
    """Tam ekran karartma (tek renk + yüzey saydamlığı: hızlı blit)."""
    img = _MS_CACHE.get("dim")
    if img is None:
        img = pygame.Surface((VIRTUAL_W, VIRTUAL_H))
        img.fill((17, 12, 12))
        _MS_CACHE["dim"] = img
    img.set_alpha(int(clamp(alpha, 0, 255)))
    return img


def _ms_backdrop(app):
    """Menü zemini + koyu örtü, birlikte bir kez hazırlanır."""
    base = app.bg.static_frame()
    ent = _MS_CACHE.get("backdrop")
    if ent is None or ent[0] is not base:
        img = base.copy()
        ov = pygame.Surface((VIRTUAL_W, VIRTUAL_H), pygame.SRCALPHA)
        ov.fill((6, 8, 16, 150))
        img.blit(ov, (0, 0))
        ent = (base, img)
        _MS_CACHE["backdrop"] = ent
    return ent[1]


def _ms_draw_rules(canvas, x, y, theme, size=12, step=19, max_w=260):
    for good, txt in _ms_rule_lines(theme):
        canvas.blit(_ms_arrow(good), (x - 1, y))
        txt, sz = ms_fit(txt, size, max_w, True)
        draw_text(canvas, txt, (x + 16, y), sz, (170, 240, 180) if good else (255, 170, 170),
                  bold=True, shadow=False)
        y += step
    return y


def _ms_card_rect(i):
    cw, gap = 292, 16
    x0 = VIRTUAL_W / 2 - (4 * cw + 3 * gap) / 2
    return pygame.Rect(int(x0 + i * (cw + gap)), 84, cw, 528)


MS_WIN_RECT = pygame.Rect(22, 50, VIRTUAL_W - 44, 662)


def _ms_badge_items(theme, save):
    """Kartın altındaki rozetler: başarım / silah ilerlemesi ya da dünya sıralaması."""
    col = MAP_THEME_COLOR.get(theme, GOLD)
    if theme == "stone":
        return [(L("ms.badge_world"), GOLD), (L("ms.badge_hell"), (255, 130, 80))]
    achs = [a for a in MAP_ACHS if a["map"] == theme]
    got = sum(1 for a in achs if a["id"] in save.data.get("achievements", {}))
    ws = [w for w, _ in ms_weapons_for(theme) if w is not None]
    own = sum(1 for w in ws if save.owns_weapon(w["key"]))
    return [(L("ms.ach_done", got, len(achs)), GOLD if got == len(achs) else lighten(col, 0.2)),
            (L("ms.weap_done", own, len(ws)), GREEN if own == len(ws) else lighten(col, 0.2))]


def _ms_draw_badges(canvas, items, rr):
    x = rr.x + 12
    avail = rr.w - 24 - 8 * (len(items) - 1) - 20 * len(items)
    sz = 11
    while sz > 9 and sum(text_width(tx, sz, True) for tx, _ in items) > avail:
        sz -= 1
    for txt, c_ in items:
        if sum(text_width(tx, sz, True) for tx, _ in items) > avail:
            txt, sz = ms_fit(txt, sz, avail // len(items), True)
        bw_ = text_width(txt, sz, True) + 20
        br = pygame.Rect(x, rr.bottom - 32, bw_, 22)
        pygame.draw.rect(canvas, (26, 19, 19), br, border_radius=11)
        ink_frame(canvas, br, c_, 11, 1)
        draw_text(canvas, txt, br.center, sz, c_, bold=True, center=True, shadow=False)
        x = br.right + 8


MS_STRIP_KINDS = ("red", "blue", "sprinter", "brute", "bomber")


def _ms_card_layer(app, theme, size, on, hov):
    """Kartın durağan katmanı (panel, ad, kurallar, rozetler, şerit çerçeveleri)."""
    items = _ms_badge_items(theme, app.save)
    key = (theme, size, on, hov, lang(), tuple(items))
    img = _MS_CARDS.get(key)
    if img is not None:
        return img
    if len(_MS_CARDS) > 64:
        _MS_CARDS.clear()
    w, h = size
    col = MAP_THEME_COLOR.get(theme, GOLD)
    img = pygame.Surface((w + 24, h + 26), pygame.SRCALPHA)
    rr = pygame.Rect(12, 6, w, h)                 # panel gölgesi için pay
    panel(img, rr, bg=(48, 35, 36) if on else (35, 25, 26), alpha=248, radius=16,
          edge=col if on else (lighten(col, 0.1) if hov else scale_col(col, 0.5)), edge_w=3 if on else 2)
    y = rr.y + 10 + MS_CARD_SCENE[1] + 10
    draw_icon(img, rr.x + 22, y + 11, MAP_THEME_ICON.get(theme, "star"), col, 9)
    nm, nsz = ms_fit(L("map.%s.name" % theme), 19, rr.w - 50, True)
    draw_text(img, nm, (rr.x + 38, y), nsz, lighten(col, 0.25), bold=True)
    y += 28
    for ln in wrap_text(L("ms.tag.%s" % theme), 11, rr.w - 28)[:2]:
        draw_text(img, ln, (rr.x + 14, y), 11, TEXT_DIM, shadow=False)
        y += 15
    y = rr.y + MS_CARD_SCENE[1] + 84
    pygame.draw.line(img, scale_col(col, 0.45), (rr.x + 14, y - 6), (rr.right - 14, y - 6), 1)
    _ms_draw_rules(img, rr.x + 16, y, theme, size=12, step=19, max_w=rr.w - 48)
    sy = rr.bottom - 74
    for k in range(len(MS_STRIP_KINDS)):
        cx_ = rr.x + 34 + k * 56
        pygame.draw.circle(img, (50, 37, 38), (cx_, sy), 22)
        pygame.draw.circle(img, scale_col(col, 0.55), (cx_, sy), 22, 1)
    _ms_draw_badges(img, items, rr)
    _MS_CARDS[key] = img
    return img


def _ms_draw_card(app, canvas, i, theme, mouse_pos, t, sel, alpha_hover=True):
    r = _ms_card_rect(i)
    col = MAP_THEME_COLOR.get(theme, GOLD)
    hov = r.collidepoint(mouse_pos) and alpha_hover
    on = theme == sel
    rr = r.move(0, -5 if (hov or on) else 0)
    canvas.blit(_ms_card_layer(app, theme, r.size, on, hov), (rr.x - 12, rr.y - 6))
    # hareketli katman: manzara, havası ve içinde dolaşan yaratıklar
    sr = pygame.Rect(rr.x + 10, rr.y + 10, MS_CARD_SCENE[0], MS_CARD_SCENE[1])
    draw_map_scene(canvas, sr, theme, t + i * 3.1)
    ink_frame(canvas, sr, col, 6, 2)
    if theme == "stone":
        nt = L("ms.normal")
        nr = pygame.Rect(0, 0, text_width(nt, 10, True) + 16, 18)
        nr.topright = (sr.right - 6, sr.y + 6)
        pygame.draw.rect(canvas, (20, 16, 8), nr, border_radius=9)
        ink_frame(canvas, nr, GOLD, 9, 1)
        draw_text(canvas, nt, nr.center, 10, GOLD, bold=True, center=True, shadow=False)
    if hov:
        hr_ = pygame.Rect(sr.x, sr.bottom - 26, sr.w, 26)
        canvas.blit(_ms_hint_band(hr_.size), hr_.topleft)
        draw_text(canvas, L("ms.tap"), hr_.center, 12, WHITE, bold=True, center=True, shadow=False)
    sy = rr.bottom - 74
    for k, kind in enumerate(MS_STRIP_KINDS):
        ms_draw_creature(canvas, theme, kind, rr.x + 34 + k * 56, sy, 11, t + k, face=(0.9, 0.45),
                         slot=10 + k)
    return r, hov


def _ms_draw_lock(canvas, r, theme, t):
    """Kilitli harita kartının örtüsü: karartma, kilit ve açılma şartı."""
    sh = pygame.Surface(r.size, pygame.SRCALPHA)
    pygame.draw.rect(sh, (19, 14, 14, 190), sh.get_rect(), border_radius=16)
    canvas.blit(sh, r.topleft)
    cy = r.y + MS_CARD_SCENE[1] * 0.5 + 6
    draw_padlock(canvas, r.centerx, cy, 22, (226, 226, 236))
    draw_text(canvas, L("ms.locked"), (r.centerx, cy + 44), 22, (255, 210, 120), bold=True,
              center=True)
    yy = cy + 72
    for ln in wrap_text(map_lock_text(theme), 13, r.w - 36)[:3]:
        draw_text(canvas, ln, (r.centerx, yy), 13, TEXT, center=True, shadow=False)
        yy += 18


def _ms_hint_band(size):
    img = _MS_CACHE.get(("hint", size))
    if img is None:
        img = pygame.Surface(size, pygame.SRCALPHA)
        img.fill((0, 0, 0, 150))
        _MS_CACHE[("hint", size)] = img
    return img


def _ms_detail_layout():
    """Ayrıntı penceresinin ölçüleri: durağan ve canlı katman aynı yerleri kullanır."""
    wr = MS_WIN_RECT
    lx = wr.x + 20
    sr = pygame.Rect(lx, wr.y + 18, MS_BIG_SCENE[0], MS_BIG_SCENE[1])
    rx = sr.right + 22
    rw = wr.right - 20 - rx
    cy0 = wr.y + 40
    cw_ = rw / 6.0
    cells = []
    for j, kind in enumerate(MS_BEST_KINDS):
        row, cidx = divmod(j, 6)
        off = (cw_ / 2) if row == 1 else 0
        cells.append((kind, pygame.Rect(int(rx + off + cidx * cw_) + 3, int(cy0 + row * 86), int(cw_) - 6, 80)))
    hint_y = cy0 + 2 * 86
    boss_y = hint_y + 48
    bw = (rw - 4 * 8) / 5.0
    bosses = [(kind, pygame.Rect(int(rx + j * (bw + 8)), int(boss_y), int(bw), 128))
              for j, kind in enumerate(BOSS_ORDER)]
    return dict(wr=wr, lx=lx, sr=sr, rx=rx, rw=rw, cells=cells, hint_y=hint_y,
                boss_head_y=hint_y + 24, bosses=bosses, weap_y=boss_y + 140,
                bb=pygame.Rect(lx, wr.bottom - 62, 150, 46),
                bs=pygame.Rect(lx + 162, wr.bottom - 62, sr.w - 162, 46))


def _ms_head(img, x, y, title, sub, col, max_w):
    draw_text(img, title, (x, y), 15, lighten(col, 0.25), bold=True, shadow=False)
    if sub:
        tw = text_width(title, 15, True)
        sub, ssz = ms_fit(sub, 11, max_w - tw - 24)
        draw_text(img, sub, (x + tw + 14, y + 3), ssz, TEXT_DIM, shadow=False)


def _ms_detail_static(app, theme):
    """Ayrıntı penceresinin durağan katmanı: zemin, karartma, pencere, bütün yazılar, rekorlar"""
    key = ("detail", theme, lang(), getattr(app, "_ms_zoom_t0", 0.0))
    img = _MS_CACHE.get(key)
    if img is not None:
        return img
    for old in [k_ for k_ in _MS_CACHE if isinstance(k_, tuple) and k_[0] == "detail"]:
        del _MS_CACHE[old]
    save = app.save
    col = MAP_THEME_COLOR.get(theme, GOLD)
    lay = _ms_detail_layout()
    wr, lx, sr, rx, rw = lay["wr"], lay["lx"], lay["sr"], lay["rx"], lay["rw"]
    img = _ms_backdrop(app).copy()
    img.blit(_ms_dim(170), (0, 0))
    panel(img, wr, bg=(32, 23, 24), edge=col, alpha=252, radius=18, edge_w=3)
    # ---- sol sütun: ad, slogan, kurallar, not, rekorlar ----
    y = sr.bottom + 10
    draw_icon(img, lx + 12, y + 15, MAP_THEME_ICON.get(theme, "star"), col, 11)
    nm, nsz = ms_fit(L("map.%s.name" % theme), 26, sr.w - 40, True)
    draw_text(img, nm, (lx + 30, y), nsz, lighten(col, 0.25), bold=True)
    y += 34
    for ln in wrap_text(L("ms.tag.%s" % theme), 13, sr.w)[:2]:
        draw_text(img, ln, (lx, y), 13, TEXT_DIM, shadow=False)
        y += 17
    y += 5
    draw_text(img, L("ms.rules"), (lx, y), 13, GOLD, bold=True, shadow=False)
    y += 21
    y = _ms_draw_rules(img, lx + 2, y, theme, size=13, step=20, max_w=sr.w - 24)
    info = L("ms.stone_note") if theme == "stone" else L("ms.same")
    for ln in wrap_text(info, 12, sr.w)[:2]:
        draw_text(img, ln, (lx, y + 3), 12, (200, 206, 226), shadow=False)
        y += 16
    ry = wr.bottom - 62 - 74
    draw_text(img, L("ms.record"), (lx, ry), 12, GOLD, bold=True, shadow=False)
    tiles = ms_records(save, theme)
    tw_ = (sr.w - 8 * (len(tiles) - 1)) / float(len(tiles))
    for j, (lab, val) in enumerate(tiles):
        tr_ = pygame.Rect(int(lx + j * (tw_ + 8)), ry + 18, int(tw_), 48)
        pygame.draw.rect(img, (48, 35, 36), tr_, border_radius=9)
        ink_frame(img, tr_, scale_col(col, 0.55), 9, 1)
        draw_text(img, val, (tr_.centerx, tr_.y + 16), 18, WHITE, bold=True, center=True, shadow=False)
        lab, lsz = ms_fit(lab, 11, tr_.w - 8)
        draw_text(img, lab, (tr_.centerx, tr_.y + 36), lsz, TEXT_DIM, center=True, shadow=False)
    # ---- sağ sütun: yaratıklar (hücre + ad) ----
    _ms_head(img, rx, wr.y + 16, L("ms.creatures"),
             L("ms.creatures_sub") if theme != "stone" else L("ms.creatures_stone"), col, rw)
    for kind, cr in lay["cells"]:
        pygame.draw.rect(img, (55, 40, 41), cr, border_radius=10)
        ink_frame(img, cr, scale_col(col, 0.55), 10, 1)
        nm, sz = ms_fit(ms_creature_name(theme, kind), 11, cr.w - 8, True)
        draw_text(img, nm, (cr.centerx, cr.bottom - 13), sz, TEXT, bold=True, center=True, shadow=False)
    # ---- patronlar (hücre + ad) ----
    _ms_head(img, rx, lay["boss_head_y"], L("ms.bosses"),
             L("ms.boss_waves") + ("  -  " + L("ms.hell_bosses") if theme == "stone" else ""), col, rw)
    for kind, cr in lay["bosses"]:
        pygame.draw.rect(img, (46, 33, 34), cr, border_radius=10)
        ink_frame(img, cr, scale_col(col, 0.5), 10, 1)
        nm, sz = ms_fit(ms_boss_name(theme, kind), 11, cr.w - 8, True)
        draw_text(img, nm, (cr.centerx, cr.bottom - 14), sz, GOLD, bold=True, center=True, shadow=False)
    # ---- açılan silahlar ----
    y = lay["weap_y"]
    _ms_head(img, rx, y, L("ms.weapons"), L("ms.stone_weapons") if theme == "stone" else "", col, rw)
    y += 22
    items = ms_weapons_for(theme)
    if theme == "stone":
        colw = (rw - 10) / 2.0
        for j, (w, _a) in enumerate(items[:8]):
            cidx, row = divmod(j, 4)
            cr = pygame.Rect(int(rx + cidx * (colw + 10)), int(y + row * 36), int(colw), 32)
            own = save.owns_weapon(w["key"])
            pygame.draw.rect(img, (50, 37, 38) if not own else (22, 40, 30), cr, border_radius=8)
            ink_frame(img, cr, GREEN if own else (93, 68, 70), 8, 1)
            ms_weapon_emblem(img, cr.x + 18, cr.centery, 24, w, not own)
            nm, sz = ms_fit(w_name(w), 12, colw * 0.62, True)
            draw_text(img, nm, (cr.x + 36, cr.y + 3), sz, tuple(w["color"]) if own else TEXT, bold=True,
                      shadow=False)
            bar = pygame.Rect(int(cr.right - colw * 0.24 - 8), cr.y + 20, int(colw * 0.24), 6)
            if own:
                draw_text(img, L("ms.owned"), (cr.x + 36, cr.y + 17), 10, GREEN, shadow=False)
                draw_bar(img, bar, 1.0, GREEN, bg=(26, 19, 19), border=(88, 65, 67), radius=3)
            else:
                rq = next((q for q in weapon_reqs(w) if not book_req_state(save, q)[2]), None)
                if rq is not None:
                    rc, rn, _d, rt = book_req_state(save, rq)
                    rt = req_text(rq) or rt
                    rt, rsz = ms_fit(rt, 10, colw * 0.62 - 44)
                    draw_text(img, rt, (cr.x + 36, cr.y + 17), rsz, TEXT_DIM, shadow=False)
                    draw_text(img, "%s / %s" % (fmt_num(min(rc, rn)), fmt_num(rn)), (bar.centerx, cr.y + 10),
                              10, TEXT_DIM, bold=True, center=True, shadow=False)
                draw_bar(img, bar, weapon_frac(save, w), col, bg=(26, 19, 19), border=(88, 65, 67), radius=3)
    else:
        for j, (w, a) in enumerate(items[:5]):
            cr = pygame.Rect(int(rx), int(y + j * 34), int(rw), 31)
            done = a["id"] in save.data.get("achievements", {})
            pygame.draw.rect(img, (50, 37, 38) if not done else (22, 40, 30), cr, border_radius=8)
            ink_frame(img, cr, GREEN if done else (93, 68, 70), 8, 1)
            draw_icon(img, cr.x + 16, cr.centery, a.get("icon", "star"), GOLD if done else col, 8)
            nm, sz = ms_fit(ach_name(a), 12, rw * 0.22, True)
            draw_text(img, nm, (cr.x + 32, cr.y + 3), sz, GOLD if done else TEXT, bold=True, shadow=False)
            ds, dsz = ms_fit(ach_desc(a), 10, rw * 0.40)
            draw_text(img, ds, (cr.x + 32, cr.y + 17), dsz, TEXT_DIM, shadow=False)
            tr_ = a["track"]
            cur = min(ach_stat_value(save, tr_["stat"]), tr_["need"])
            bar = pygame.Rect(int(cr.x + rw * 0.47), cr.y + 19, int(rw * 0.17), 6)
            draw_bar(img, bar, 1.0 if done else cur / max(1, tr_["need"]), GREEN if done else col,
                     bg=(26, 19, 19), border=(88, 65, 67), radius=3)
            draw_text(img, ("%s / %s" % (fmt_num(cur), fmt_num(tr_["need"]))) if not done else L("ms.done"),
                      (bar.centerx, cr.y + 10), 10, GREEN if done else TEXT_DIM, bold=True, center=True,
                      shadow=False)
            if w is not None:
                own = save.owns_weapon(w["key"])
                ex = int(cr.x + rw * 0.70)
                ms_weapon_emblem(img, ex, cr.centery, 24, w, not own)
                wn, wsz = ms_fit(("→ " if not own else "") + w_name(w), 12, rw * 0.27, True)
                draw_text(img, wn, (ex + 18, cr.y + 3), wsz, tuple(w["color"]) if own else (196, 202, 222),
                          bold=True, shadow=False)
                draw_text(img, L("ms.unlocks") if not own else L("ms.owned"), (ex + 18, cr.y + 17), 10,
                          GREEN if own else TEXT_DIM, shadow=False)
    _MS_CACHE[key] = img
    return img


def _ms_draw_detail(app, canvas, theme, mouse_pos, clicked, t, k):
    """Ayrıntı penceresi (açık): durağan katman + canlı katman."""
    col = MAP_THEME_COLOR.get(theme, GOLD)
    lay = _ms_detail_layout()
    canvas.blit(_ms_detail_static(app, theme), (0, 0))
    result = None
    sr = lay["sr"]
    draw_map_scene(canvas, sr, theme, t)
    ink_frame(canvas, sr, col, 8, 2)
    # yaratıklar (üstüne gelinen hücre parlar, satırda ne yaptığı yazar)
    hov_kind = None
    for j, (kind, cr) in enumerate(lay["cells"]):
        if cr.collidepoint(mouse_pos):
            hov_kind = kind
            ink_frame(canvas, cr, col, 10, 2)
        rr_ = 15 if kind not in ("tank", "elite") else 19
        ms_draw_creature(canvas, theme, kind, cr.centerx, cr.y + 32, rr_, t + j * 0.7,
                         face=(math.cos(t * 0.5 + j), 0.6), slot=20 + j, walk_speed=2.4)
    hov_boss = None
    for kind, cr in lay["bosses"]:
        if cr.collidepoint(mouse_pos):
            hov_boss = kind
            ink_frame(canvas, cr, col, 10, 2)
    if hov_boss:
        # patronun üstüne gelince bu haritadaki yetenekleri yazar
        sk = boss_skill_set(hov_boss, theme if theme != "stone" else None, False)
        ln = "%s: %s" % (ms_boss_name(theme, hov_boss),
                          ", ".join(TRX(BOSS_SKILL_LABELS.get(k, k)) for k in sk))
        hov_kind = hov_boss
    elif hov_kind:
        ln = "%s: %s" % (ms_creature_name(theme, hov_kind), L("ms.role.%s" % hov_kind))
    else:
        ln = L("ms.hover_hint")
    ln, lsz = ms_fit(ln, 12, lay["rw"])
    draw_text(canvas, ln, (lay["rx"], lay["hint_y"]), lsz, (226, 214, 160) if hov_kind else TEXT_DIM,
              bold=bool(hov_kind), shadow=False)
    # patronlar: karede en çok biri yenilenir
    slot = int(t * 60) % len(lay["bosses"])
    for j, (kind, cr) in enumerate(lay["bosses"]):
        img = ms_boss_portrait(theme, kind, MS_BOSS_PORTRAIT, t, refresh=(j == slot))
        canvas.blit(img, (cr.centerx - MS_BOSS_PORTRAIT // 2, cr.y - 6))
    # düğmeler
    for rect, label, c_, kind in ((lay["bb"], L("ui.back"), (100, 106, 140), "back"),
                                 (lay["bs"], L("ms.start", L("map.%s.short" % theme)), (56, 132, 88), "start")):
        hov = rect.collidepoint(mouse_pos)
        face = key_button(canvas, rect, c_, hov, rad=12)
        lab, lsz = ms_fit(label, 19, rect.w - 16, True)
        draw_text(canvas, lab, face.center, lsz, WHITE, bold=True, center=True)
        if hov and clicked and k >= 1.0:
            result = kind
    return result


def draw_map_select(app, canvas, mouse_pos, clicked, t):
    """Harita seçim ekranı."""
    sel = app.selected_map()
    result = None
    zoom = getattr(app, "_ms_zoom", None)
    zk = app.ms_zoom_k() if zoom else 0.0
    full = zoom is not None and zk >= 1.0
    if not full:
        canvas.blit(_ms_backdrop(app), (0, 0))
        draw_text(canvas, L("ms.title"), (VIRTUAL_W / 2, 30), 32, GOLD, bold=True, center=True)
        draw_text(canvas, L("ms.sub"), (VIRTUAL_W / 2, 60), 13, TEXT_DIM, center=True, shadow=False)
        for i, th in enumerate(MAP_THEMES):
            r, hov = _ms_draw_card(app, canvas, i, th, mouse_pos, t, sel, alpha_hover=zoom is None)
            locked = not map_unlocked(app.save, th)
            if locked:
                _ms_draw_lock(canvas, r, th, t)
            if zoom is None and hov and clicked:
                if locked:
                    app._ms_lock_msg = (map_lock_text(th), app.t + 2.4)
                    sfx("error", 0.6, 0.0)
                else:
                    app.set_selected_map(th)
                    app.ms_open_zoom(th, i)
                    sfx("click", 0.6, 0.0)
                clicked = False
        msg = getattr(app, "_ms_lock_msg", None)
        if msg and app.t < msg[1]:
            mr = pygame.Rect(0, 0, text_width(msg[0], 16, True) + 60, 40)
            mr.center = (VIRTUAL_W / 2, 610)
            panel(canvas, mr, bg=(46, 22, 26), edge=(220, 90, 90), alpha=245, radius=10, edge_w=2)
            draw_padlock(canvas, mr.x + 22, mr.centery, 8, (255, 170, 160))
            draw_text(canvas, msg[0], (mr.centerx + 10, mr.centery), 16, (255, 200, 190),
                      bold=True, center=True, shadow=False)
        # alt düğmeler
        bb = pygame.Rect(VIRTUAL_W / 2 - 330, 640, 300, 46)
        bs = pygame.Rect(VIRTUAL_W / 2 + 30, 640, 300, 46)
        rows = [(bb, L("ui.back"), (110, 116, 150), "back"),
                (bs, L("ms.start", L("map.%s.short" % sel)), (60, 130, 90), "start")]
        if coop_available():
            # 2 kişilik (beta) - yalnız Taş Meydan'da oynanır
            bc = pygame.Rect(VIRTUAL_W / 2 + 350, 640, 230, 46)
            rows.append((bc, L("coop.ms_btn"), (96, 70, 150), "coop"))
        for rect, label, c_, kind in rows:
            hov = rect.collidepoint(mouse_pos) and zoom is None
            panel(canvas, rect, bg=lighten(c_, 0.15) if hov else c_, edge=lighten(c_, 0.4), alpha=250,
                  radius=12, edge_w=2)
            lab, lsz = ms_fit(label, 19, rect.w - 16, True)
            draw_text(canvas, lab, rect.center, lsz, WHITE, bold=True, center=True)
            if hov and clicked and result is None:
                result = (kind, sel)
    if zoom is not None:
        e = ease_out_cubic(zk)
        if not full:
            # büyüme animasyonu: kart dikdörtgeninden pencereye. Pencerenin
            # durağan katmanı ilk karede hazırlanır ki açılış sonunda
            # takılmasın.
            if getattr(app, "_ms_zoom_dir", 1) > 0:
                _ms_detail_static(app, zoom)
            canvas.blit(_ms_dim(170 * e), (0, 0))
            a = app._ms_zoom_from
            b = MS_WIN_RECT
            rr = pygame.Rect(int(a.x + (b.x - a.x) * e), int(a.y + (b.y - a.y) * e),
                             int(a.w + (b.w - a.w) * e), int(a.h + (b.h - a.h) * e))
            col = MAP_THEME_COLOR.get(zoom, GOLD)
            pygame.draw.rect(canvas, (13, 15, 26), rr, border_radius=18)
            ink_frame(canvas, rr, col, 18, 3)
            img = _MAP_SCENES.get((zoom, MS_CARD_SCENE[0], MS_CARD_SCENE[1]))
            if img is not None:
                sw = int(MS_CARD_SCENE[0] + (MS_BIG_SCENE[0] - MS_CARD_SCENE[0]) * e)
                shh = int(MS_CARD_SCENE[1] + (MS_BIG_SCENE[1] - MS_CARD_SCENE[1]) * e)
                canvas.blit(pygame.transform.scale(img, (sw, shh)), (rr.x + 10 + int(10 * e), rr.y + 10 + int(8 * e)))
        else:
            act = _ms_draw_detail(app, canvas, zoom, mouse_pos, clicked, t, zk)
            if act == "start":
                result = ("start", zoom)
            elif act == "back":
                app.ms_close_zoom()
            elif clicked and not MS_WIN_RECT.collidepoint(mouse_pos):
                app.ms_close_zoom()
    return result


# gezgin tüccar - koşu boyunca haritada durur, yemin satar
MERCHANT_COLOR = (255, 196, 110)
MERCHANT_CLOAK = (74, 58, 120)
MERCHANT_CLOAK2 = (104, 84, 158)


def draw_merchant_figure(surf, x, y, s, t, blink_seed=0.0, talking=False):
    """Kapüşonlu, gözleri parlayan, sırtında dolu bir çantayla gezgin tüccar."""
    breath = math.sin(t * 2.2) * 1.5 * s
    # gölge
    sh = pygame.Surface((int(70 * s), int(18 * s)), pygame.SRCALPHA)
    pygame.draw.ellipse(sh, (0, 0, 0, 80), sh.get_rect())
    surf.blit(sh, (int(x - 35 * s), int(y - 9 * s)))
    # sırt çantası (arkada): kahverengi heybe, üstünde rulo ve tencere
    bx, by = x + 16 * s, y - 50 * s + breath
    bag = pygame.Rect(0, 0, int(34 * s), int(40 * s))
    bag.center = (int(bx), int(by))
    pygame.draw.rect(surf, OUTLINE, bag.inflate(int(4 * s), int(4 * s)), border_radius=int(8 * s))
    pygame.draw.rect(surf, (120, 82, 50), bag, border_radius=int(8 * s))
    pygame.draw.rect(surf, (150, 104, 64), bag.inflate(int(-10 * s), int(-14 * s)), border_radius=int(5 * s))
    pygame.draw.line(surf, (90, 60, 34), (bag.x + 4 * s, bag.centery), (bag.right - 4 * s, bag.centery),
                     max(1, int(2 * s)))
    roll = pygame.Rect(0, 0, int(38 * s), int(11 * s))
    roll.midbottom = (bag.centerx, bag.top + int(3 * s))
    pygame.draw.rect(surf, OUTLINE, roll.inflate(int(3 * s), int(3 * s)), border_radius=int(5 * s))
    pygame.draw.rect(surf, (200, 70, 70), roll, border_radius=int(5 * s))
    pygame.draw.line(surf, (240, 210, 120), (roll.centerx, roll.top), (roll.centerx, roll.bottom),
                     max(1, int(2 * s)))
    circle_aa(surf, bag.right - 2 * s, bag.bottom - 8 * s, 6 * s, (90, 96, 110))
    # pelerin (gövde): yukarı daralan, dalgalı etekli koni
    sway = math.sin(t * 1.6) * 2.0 * s
    body = [(x - 24 * s + sway, y - 2 * s), (x + 24 * s + sway, y - 2 * s),
            (x + 13 * s, y - 52 * s + breath), (x - 13 * s, y - 52 * s + breath)]
    poly_aa(surf, [(px, py + 2 * s) for px, py in body], OUTLINE)
    poly_aa(surf, body, MERCHANT_CLOAK)
    poly_aa(surf, [(x - 24 * s + sway, y - 2 * s), (x - 4 * s + sway, y - 2 * s),
                   (x - 3 * s, y - 52 * s + breath), (x - 13 * s, y - 52 * s + breath)], MERCHANT_CLOAK2)
    # etekteki altın şerit
    pygame.draw.line(surf, MERCHANT_COLOR, (x - 22 * s + sway, y - 7 * s), (x + 22 * s + sway, y - 7 * s),
                     max(1, int(2.5 * s)))
    # kemer + kese
    pygame.draw.line(surf, (60, 40, 26), (x - 15 * s, y - 30 * s + breath), (x + 15 * s, y - 30 * s + breath),
                     max(1, int(3 * s)))
    circle_aa(surf, x + 9 * s, y - 24 * s + breath, 5 * s, MERCHANT_COLOR)
    circle_aa(surf, x + 9 * s, y - 25 * s + breath, 2 * s, (150, 110, 40))
    # kapüşon: yuvarlak, sivri uçlu
    hx, hy = x, y - 64 * s + breath
    hood = [(hx - 19 * s, hy + 12 * s), (hx - 17 * s, hy - 6 * s), (hx - 6 * s, hy - 18 * s),
            (hx + 4 * s, hy - 24 * s), (hx + 8 * s, hy - 16 * s), (hx + 18 * s, hy - 4 * s),
            (hx + 19 * s, hy + 12 * s)]
    poly_aa(surf, [(px, py + 2 * s) for px, py in hood], OUTLINE)
    poly_aa(surf, hood, MERCHANT_CLOAK2)
    # karanlık yüz boşluğu
    face = pygame.Rect(0, 0, int(26 * s), int(22 * s))
    face.center = (int(hx), int(hy + 2 * s))
    pygame.draw.ellipse(surf, (14, 10, 22), face)
    # parlayan gözler (arada bir kırpar)
    blink = ((t + blink_seed) % 3.7) < 0.12
    for sx_ in (-1, 1):
        ex, ey = hx + sx_ * 6 * s, hy + 1 * s
        if blink:
            pygame.draw.line(surf, MERCHANT_COLOR, (ex - 3 * s, ey), (ex + 3 * s, ey), max(1, int(2 * s)))
        else:
            add_glow(surf, ex, ey, 9 * s, MERCHANT_COLOR, 0.6)
            circle_aa(surf, ex, ey, 2.8 * s, (255, 236, 170))
    # konuşurken ağzın yerinde küçük bir ışık
    if talking and int(t * 8) % 2 == 0:
        circle_aa(surf, hx, hy + 8 * s, 1.6 * s, (255, 210, 140))
    # asa + fener (önde)
    sx0, sy0 = x - 26 * s, y - 2 * s
    sx1, sy1 = x - 30 * s, y - 92 * s + breath
    thick_line(surf, (sx0, sy0), (sx1, sy1), 3.2 * s, (96, 66, 40))
    lx, ly = sx1 - 2 * s, sy1 + 10 * s + math.sin(t * 2.6) * 1.5 * s
    pygame.draw.line(surf, (60, 60, 70), (sx1, sy1), (lx, ly - 7 * s), max(1, int(1.5 * s)))
    flick = 0.85 + 0.15 * math.sin(t * 11 + 1.3) * math.sin(t * 7)
    add_glow(surf, lx, ly, 38 * s * flick, (255, 190, 100), 0.45)
    lan = pygame.Rect(0, 0, int(12 * s), int(15 * s))
    lan.center = (int(lx), int(ly))
    pygame.draw.rect(surf, OUTLINE, lan.inflate(int(3 * s), int(3 * s)), border_radius=int(3 * s))
    pygame.draw.rect(surf, (255, 214, 130), lan, border_radius=int(3 * s))
    pygame.draw.rect(surf, (120, 90, 40), lan, width=max(1, int(1.5 * s)), border_radius=int(3 * s))
    # el (asayı tutan)
    circle_aa(surf, x - 25 * s, y - 40 * s + breath, 5 * s, (226, 186, 150))


class Merchant:
    """Haritadaki gezgin tüccar: çizgili tenteli küçük bir tezgâh ve tüccar."""

    def __init__(self, x, y):
        self.x, self.y = x, y
        self.t = random.uniform(0, 10)
        self.done = False           # bu koşuda yemin edildi

    def in_range(self, p):
        return dist(self.x, self.y, p.x, p.y) < 96

    def update(self, dt):
        self.t += dt

    def draw(self, surf, t):
        x, y = self.x, self.y
        add_glow(surf, x, y - 30, 120, MERCHANT_COLOR, 0.14)
        # tezgÂH: tahta tezgâh + çizgili tente
        st = pygame.Rect(0, 0, 92, 30)
        st.midbottom = (int(x + 52), int(y))
        surf.blit(shadow_sprite(100), (st.x - 4, st.bottom - 10))
        for px_ in (st.x + 6, st.right - 10):
            pygame.draw.rect(surf, (90, 60, 34), (px_, st.y - 46, 5, 46))
        aw = [(st.x - 8, st.y - 44), (st.right + 8, st.y - 44), (st.right + 2, st.y - 62), (st.x - 2, st.y - 62)]
        poly_aa(surf, [(a, b + 2) for a, b in aw], OUTLINE)
        poly_aa(surf, aw, (232, 214, 190))
        for i in range(5):
            if i % 2 == 0:
                x0_ = st.x - 8 + i * (st.w + 16) / 5
                x1_ = st.x - 8 + (i + 1) * (st.w + 16) / 5
                poly_aa(surf, [(x0_, st.y - 44), (x1_, st.y - 44), (x1_ - 1, st.y - 62), (x0_ + 1, st.y - 62)],
                        (190, 70, 90))
        for i in range(6):     # tente saçağı
            cx_ = st.x - 4 + i * (st.w + 8) / 5
            circle_aa(surf, cx_, st.y - 42, 4, (190, 70, 90) if i % 2 == 0 else (232, 214, 190))
        pygame.draw.rect(surf, OUTLINE, st.inflate(4, 4), border_radius=4)
        pygame.draw.rect(surf, (138, 94, 56), st, border_radius=4)
        pygame.draw.line(surf, (104, 70, 40), (st.x + 3, st.y + 10), (st.right - 3, st.y + 10), 2)
        # tezgâhtaki mallar: iksirler ve bir mühür
        for i, col in enumerate(((255, 110, 110), (110, 225, 130), (150, 150, 255))):
            bx = st.x + 16 + i * 18
            pygame.draw.rect(surf, OUTLINE, (bx - 5, st.y - 14, 10, 14), border_radius=3)
            pygame.draw.rect(surf, col, (bx - 4, st.y - 12, 8, 11), border_radius=3)
            pygame.draw.rect(surf, (230, 230, 240), (bx - 2, st.y - 17, 4, 4))
            add_glow(surf, bx, st.y - 7, 10, col, 0.25 + 0.15 * math.sin(self.t * 3 + i))
        circle_aa(surf, st.right - 16, st.y - 6, 7, MERCHANT_COLOR)
        draw_icon(surf, st.right - 16, st.y - 6, "star", (120, 80, 30), 4)
        # tüccar
        draw_merchant_figure(surf, x, y, 1.0, self.t, x * 0.01)
        # konuşulmayı bekliyor: zıplayan "!"
        if not self.done:
            by = y - 128 + math.sin(self.t * 4) * 5
            add_glow(surf, x, by, 22, MERCHANT_COLOR, 0.5)
            pygame.draw.circle(surf, OUTLINE, (int(x), int(by)), 13)
            pygame.draw.circle(surf, MERCHANT_COLOR, (int(x), int(by)), 11)
            draw_text(surf, "!", (x, by - 1), 17, (60, 34, 10), bold=True, center=True, shadow=False)

    def draw_prompt(self, surf, t, p):
        d = dist(self.x, self.y, p.x, p.y)
        a = clamp((300 - d) / 120.0, 0.0, 1.0)
        if a <= 0:
            return
        txt = L("m.talk", key_label_short("use"))
        y = self.y - 160 + math.sin(t * 3) * 3
        w_ = text_width(txt, 15, True) + 28
        r_ = pygame.Rect(0, 0, int(w_), 28)
        r_.center = (int(self.x), int(y))
        bg = pygame.Surface(r_.size, pygame.SRCALPHA)
        pygame.draw.rect(bg, (40, 26, 14, int(230 * a)), bg.get_rect(), border_radius=13)
        pygame.draw.rect(bg, (*MERCHANT_COLOR, int(255 * a)), bg.get_rect(), width=2, border_radius=13)
        surf.blit(bg, r_.topleft)
        draw_text(surf, txt, r_.center, 15, (255, 236, 196), bold=True, center=True, shadow=False,
                  alpha=int(255 * a))


_CAVE_BG = [None]


def merchant_cave_bg():
    """Tüccarın mağarası (önbellekli): kaya duvarlar, sarkıtlar, sandıklar, halı, raf ve sıcak bir ışık havuzu."""
    if _CAVE_BG[0] is not None:
        return _CAVE_BG[0]
    W, H = VIRTUAL_W, VIRTUAL_H
    sfc = pygame.Surface((W, H))
    for yy in range(H):
        k = yy / H
        pygame.draw.line(sfc, mix_col((26, 18, 30), (44, 30, 26), k), (0, yy), (W, yy))
    rnd = random.Random(1907)
    # arka duvar taşları
    for _ in range(140):
        cx, cy = rnd.uniform(0, W), rnd.uniform(0, H * 0.75)
        r = rnd.uniform(18, 60)
        col = mix_col((52, 40, 50), (70, 54, 52), rnd.random())
        pts = [(cx + math.cos(a) * r * rnd.uniform(0.7, 1.1), cy + math.sin(a) * r * rnd.uniform(0.6, 0.9))
               for a in [i * math.tau / 7 + rnd.uniform(-0.2, 0.2) for i in range(7)]]
        pygame.draw.polygon(sfc, col, pts)
        pygame.draw.polygon(sfc, scale_col(col, 0.75), pts, 2)
    # zemin
    floor_y = int(H * 0.72)
    pygame.draw.rect(sfc, (40, 30, 28), (0, floor_y, W, H - floor_y))
    for _ in range(60):
        x0 = rnd.uniform(0, W)
        y0 = rnd.uniform(floor_y + 6, H)
        pygame.draw.ellipse(sfc, (52, 40, 36), (x0, y0, rnd.uniform(20, 70), rnd.uniform(5, 12)))
    # halı
    rug = pygame.Rect(0, 0, 560, 110)
    rug.center = (W // 2 - 40, floor_y + 70)
    pygame.draw.ellipse(sfc, (110, 34, 44), rug)
    pygame.draw.ellipse(sfc, (170, 120, 60), rug.inflate(-30, -20), 3)
    pygame.draw.ellipse(sfc, (140, 50, 60), rug.inflate(-80, -40))
    # yan kayalar (kemer) ve sarkıtlar
    for side in (-1, 1):
        base_x = 0 if side < 0 else W
        pts = [(base_x, 0)]
        for i in range(12):
            yy = i * H / 11
            xx = base_x - side * (120 + 60 * math.sin(i * 1.3) + rnd.uniform(0, 50))
            pts.append((xx, yy))
        pts.append((base_x, H))
        pygame.draw.polygon(sfc, (24, 16, 22), pts)
        pygame.draw.lines(sfc, (64, 48, 56), False, pts[1:-1], 4)
    for i in range(22):
        x0 = rnd.uniform(60, W - 60)
        ln = rnd.uniform(30, 110)
        wd = rnd.uniform(12, 26)
        pygame.draw.polygon(sfc, (30, 22, 28), [(x0 - wd, -5), (x0 + wd, -5), (x0 + rnd.uniform(-4, 4), ln)])
        pygame.draw.line(sfc, (70, 54, 60), (x0 - wd * 0.5, 0), (x0, ln * 0.8), 2)
    # sandıklar ve fıçılar
    for (cx, w_, h_) in ((150, 110, 70), (1090, 130, 80), (1180, 80, 56)):
        r = pygame.Rect(0, 0, w_, h_)
        r.midbottom = (cx, floor_y + 34)
        pygame.draw.rect(sfc, (10, 8, 10), r.inflate(6, 6), border_radius=6)
        pygame.draw.rect(sfc, (112, 76, 44), r, border_radius=6)
        pygame.draw.rect(sfc, (80, 52, 30), r, 3, border_radius=6)
        pygame.draw.line(sfc, (80, 52, 30), (r.x, r.centery), (r.right, r.centery), 3)
        pygame.draw.rect(sfc, (200, 170, 90), (r.centerx - 7, r.centery - 6, 14, 12), border_radius=3)
    for cx in (250, 1010):
        r = pygame.Rect(0, 0, 66, 84)
        r.midbottom = (cx, floor_y + 30)
        pygame.draw.ellipse(sfc, (10, 8, 10), r.inflate(6, 6))
        pygame.draw.ellipse(sfc, (124, 82, 48), r)
        for k in (0.28, 0.72):
            yy = r.y + r.h * k
            pygame.draw.line(sfc, (70, 70, 80), (r.x + 4, yy), (r.right - 4, yy), 4)
    # raf + iksirler
    shelf = pygame.Rect(860, 250, 230, 12)
    pygame.draw.rect(sfc, (96, 64, 38), shelf, border_radius=3)
    for i in range(6):
        col = ((255, 110, 110), (110, 225, 130), (150, 150, 255), (255, 210, 90), (220, 120, 255),
               (120, 220, 230))[i]
        bx = shelf.x + 18 + i * 36
        pygame.draw.rect(sfc, (10, 8, 10), (bx - 9, shelf.y - 34, 18, 34), border_radius=6)
        pygame.draw.rect(sfc, col, (bx - 7, shelf.y - 30, 14, 28), border_radius=6)
        pygame.draw.rect(sfc, (230, 230, 240), (bx - 3, shelf.y - 40, 6, 8))
    _CAVE_BG[0] = sfc
    return sfc


class MerchantOverlay(LevelUpOverlay):
    """Tüccarın mağarası."""

    def __init__(self):
        super().__init__()
        self.stage = "talk"
        self.t0 = None
        self.btn_a = pygame.Rect(0, 0, 0, 0)
        self.btn_b = pygame.Rect(0, 0, 0, 0)
        self.btn_c = pygame.Rect(0, 0, 0, 0)

    def reset(self):
        self.stage = "talk"
        self.t0 = None
        self.enter_t0 = None
        self.hand_sig = None
        self._prev_keys = {}

    def _scene(self, surf, t, dim=0):
        surf.blit(merchant_cave_bg(), (0, 0))
        # asılı fenerler (titreşen ışık)
        for i, (lx, ly) in enumerate(((300, 170), (980, 150), (640, 120))):
            flick = 0.85 + 0.15 * math.sin(t * 9 + i * 2.1) * math.sin(t * 5.3 + i)
            pygame.draw.line(surf, (70, 60, 60), (lx, 0), (lx, ly - 12), 2)
            add_glow(surf, lx, ly, 150 * flick, (255, 176, 90), 0.32)
            r = pygame.Rect(0, 0, 22, 28)
            r.center = (lx, ly)
            pygame.draw.rect(surf, OUTLINE, r.inflate(4, 4), border_radius=5)
            pygame.draw.rect(surf, (255, 214, 130), r, border_radius=5)
            pygame.draw.rect(surf, (120, 90, 40), r, 2, border_radius=5)
        # süzülen toz
        for i in range(24):
            ph = (t * (0.03 + (i % 4) * 0.01) + i * 0.173) % 1.0
            x = (i * 151.7) % VIRTUAL_W + math.sin(t * 0.7 + i) * 14
            y = VIRTUAL_H * 0.8 - ph * VIRTUAL_H * 0.75
            circle_aa(surf, x, y, 1.2 + (i % 3) * 0.5, (255, 214, 150))
        if dim:
            ov = pygame.Surface((VIRTUAL_W, VIRTUAL_H), pygame.SRCALPHA)
            ov.fill((6, 4, 10, dim))
            surf.blit(ov, (0, 0))

    def _button(self, surf, rect, label, sub, col, mouse_pos, icon, hotkey=None):
        hover = rect.collidepoint(mouse_pos)
        panel(surf, rect, bg=(48, 36, 30) if hover else (28, 22, 20),
              edge=lighten(col, 0.25) if hover else col, alpha=244, radius=14, edge_w=2)
        ix, iy = rect.x + 26, rect.centery
        pygame.draw.circle(surf, scale_col(col, 0.35), (ix, iy), 15)
        pygame.draw.circle(surf, col, (ix, iy), 15, 2)
        draw_icon(surf, ix, iy, icon, lighten(col, 0.4), 8)
        txt = label + (f"  [{hotkey}]" if hotkey else "")
        draw_text(surf, txt, (rect.x + 50, rect.y + 6), 16, TEXT, bold=True)
        if sub:
            draw_text(surf, sub, (rect.x + 50, rect.bottom - 20), 12, lighten(col, 0.35), bold=True,
                      shadow=False)
        return hover

    def _oath_card(self, surf, r2, key, t, hover, tier=0):
        _k, icon, col = OATH_BY_KEY[key]
        rc = rarity_color(tier)
        surf.blit(_panel_shadow(r2.w, r2.h, 18), (r2.x - 6, r2.y - 2))
        surf.blit(_lu_card_bg(r2.w, r2.h, col, 1), r2.topleft)
        prev = surf.get_clip()
        surf.set_clip(r2.inflate(-6, -6).clip(prev) if prev else r2.inflate(-6, -6))
        ecx, ecy = r2.centerx, r2.y + 90
        rs = pygame.Surface((r2.w, r2.h), pygame.SRCALPHA)
        for i in range(8):
            a = t * 0.35 + i * math.tau / 8
            pts = [(ecx - r2.x, ecy - r2.y),
                   (ecx - r2.x + math.cos(a - 0.08) * 140, ecy - r2.y + math.sin(a - 0.08) * 140),
                   (ecx - r2.x + math.cos(a + 0.08) * 140, ecy - r2.y + math.sin(a + 0.08) * 140)]
            pygame.draw.polygon(rs, (*col, 18), pts)
        surf.blit(rs, r2.topleft)
        surf.set_clip(prev)
        edge = lighten(rc if tier else col, 0.25) if hover else (rc if tier else col)
        ink_frame(surf, r2, edge, 18, 3 + (1 if tier >= 3 else 0))
        ink_frame(surf, r2.inflate(-10, -10), scale_col(edge, 0.45), 14, 1)
        # üst şerit: kademe (Yaygın .. Efsanevi) - tüccarın şansı çeker
        band = pygame.Rect(r2.x + 3, r2.y + 3, r2.w - 6, 30)
        pygame.draw.rect(surf, scale_col(rc, 0.55), band, border_top_left_radius=15,
                         border_top_right_radius=15)
        pygame.draw.rect(surf, rc, band.inflate(0, -6).move(0, -3),
                         border_top_left_radius=14, border_top_right_radius=14)
        tc = (28, 20, 21) if sum(rc) > 360 else WHITE
        draw_text(surf, rarity_name(tier), (band.centerx, band.centery - 2), 15, tc, bold=True,
                  center=True, shadow=False)
        tw_ = text_width(rarity_name(tier), 15, True)
        for s_ in (-1, 1):
            _sparkle(surf, band.centerx + s_ * (tw_ / 2 + 14), band.centery - 2, 4.5 + (1.5 if tier >= 3 else 0), tc)
        pulse = 0.5 + 0.5 * math.sin(t * 3.0 + r2.x * 0.01)
        add_glow(surf, ecx, ecy, 58, col, 0.22 + 0.10 * pulse)
        pygame.draw.circle(surf, (26, 19, 19), (ecx, ecy), 40)
        pygame.draw.circle(surf, col, (ecx, ecy), 40, 3)
        for i in range(12):
            a = -t * 0.8 + i * math.tau / 12
            circle_aa(surf, ecx + math.cos(a) * 48, ecy + math.sin(a) * 48, 2.0, lighten(col, 0.3))
        draw_icon(surf, ecx, ecy, icon, lighten(col, 0.15), 22 if hover else 20)
        draw_text(surf, L("oath." + key + ".name"), (r2.centerx, r2.y + 150), 17, lighten(col, 0.2),
                  bold=True, center=True)
        y = r2.y + 170
        for j, (lbl, txt, bgc, fgc, edc, up) in enumerate((
                (L("dr.power"), oath_up_text(key, tier), (10, 26, 16), lighten(GREEN, 0.2), GREEN, True),
                (L("dr.price"), L("oath." + key + ".down"), (30, 10, 14), (255, 150, 150), RED, False))):
            box = pygame.Rect(r2.x + 14, y + j * 66, r2.w - 28, 60)
            pygame.draw.rect(surf, bgc, box, border_radius=10)
            ink_frame(surf, box, scale_col(edc, 0.6), 10, 1)
            tri = ([(box.x + 10, box.y + 15), (box.x + 15, box.y + 8), (box.x + 20, box.y + 15)] if up else
                   [(box.x + 10, box.y + 8), (box.x + 20, box.y + 8), (box.x + 15, box.y + 15)])
            poly_aa(surf, tri, edc if up else (255, 120, 120))
            draw_text(surf, lbl, (box.x + 26, box.y + 6), 11, edc if up else (255, 120, 120), bold=True,
                      shadow=False)
            for k_, ln in enumerate(wrap_text(txt, 15, box.w - 20, True)[:2]):
                draw_text(surf, ln, (box.x + 10, box.y + 22 + k_ * 18), 15, fgc, bold=True, shadow=False)
        if hover:
            br = pygame.Rect(r2.x + 40, r2.bottom - 40, r2.w - 80, 28)
            pygame.draw.rect(surf, col, br, border_radius=10)
            draw_text(surf, L("dr.swear"), br.center, 14, tc, bold=True, center=True, shadow=False)

    def _bubble(self, surf, rect, text, t):
        """Konuşma balonu + daktilo efekti."""
        panel(surf, rect, bg=(250, 240, 220), edge=(120, 84, 50), alpha=246, radius=18, edge_w=3)
        tail = [(rect.x + 4, rect.bottom - 70), (rect.x - 34, rect.bottom - 30), (rect.x + 6, rect.bottom - 38)]
        poly_aa(surf, tail, (120, 84, 50))
        poly_aa(surf, [(rect.x + 7, rect.bottom - 66), (rect.x - 26, rect.bottom - 32),
                       (rect.x + 9, rect.bottom - 41)], (250, 240, 220))
        draw_text(surf, L("m.name"), (rect.x + 22, rect.y + 14), 15, (150, 90, 30), bold=True, shadow=False)
        n = int(max(0.0, t) * 55)
        shown = text[:n]
        y = rect.y + 42
        for ln in wrap_text(shown, 16, rect.w - 44)[:6]:
            draw_text(surf, ln, (rect.x + 22, y), 16, (46, 32, 26), shadow=False)
            y += 23
        return n >= len(text)

    def draw_and_handle(self, surf, run, mouse_pos, clicked, t):
        if self.t0 is None:
            self.t0 = t
            sfx("magnet", 0.5, 0.0)
        result = None
        hand = list(getattr(run, "merchant_hand", []) or [])
        sworn = getattr(run, "oath", None)
        if self.stage == "talk":
            self._scene(surf, t)
            draw_merchant_figure(surf, 330, 560, 3.0, t, 0.0, talking=True)
            br = pygame.Rect(560, 120, 620, 190)
            if sworn:
                txt = L("m.sworn", L("oath.%s.name" % sworn), rarity_name(getattr(run, "oath_tier", 0)))
            else:
                txt = L("m.greet")
            done = self._bubble(surf, br, txt, t - self.t0 - 0.25)
            draw_quest_strip(surf, run, pygame.Rect(560, 326, 620, 124), t)
            if not sworn:
                lt = L("m.luck", fmt_pct1(run.merchant_luck()))
                draw_text(surf, lt, (870, 302), 11, (120, 90, 60), center=True, shadow=False)
            self.btn_a = pygame.Rect(560, 470, 300, 50)
            self.btn_b = pygame.Rect(880, 470, 300, 50)
            if sworn:
                ha = self._button(surf, self.btn_a, L("m.ok"), L("m.one_oath"), MERCHANT_COLOR,
                                  mouse_pos, "star", hotkey=key_label_short("use"))
            else:
                ha = self._button(surf, self.btn_a, L("m.see_oaths"), L("m.see_oaths_sub"), MERCHANT_COLOR,
                                  mouse_pos, "star", hotkey=key_label_short("use"))
            hb = self._button(surf, self.btn_b, L("m.later"), L("m.later_sub"), (150, 160, 190),
                              mouse_pos, "cross", hotkey="ESC")
            use_edge = False
            for kc in key_codes("use") + [pygame.K_RETURN]:
                use_edge = self._key_edge(kc) or use_edge
            if (clicked and ha) or (use_edge and t - self.t0 > 0.3):
                if not done:
                    self.t0 -= 99.0          # önce yazıyı bitir
                elif sworn:
                    result = ("close", None)
                else:
                    self.stage = "oaths"
                    self.enter_t0 = None
                    sfx("click", 0.6, 0.0)
            elif clicked and hb:
                result = ("close", None)
            return result
        # ---- yeminler ----
        self._scene(surf, t, dim=120)
        draw_merchant_figure(surf, 120, 700, 1.9, t, 0.0)
        if self.enter_t0 is None:
            self.enter_t0 = t
            sfx("levelup", 0.3, 0.2)
        draw_text(surf, L("dr.title_oath"), (VIRTUAL_W / 2, 60), 38, GOLD, bold=True, center=True)
        draw_text(surf, L("dr.sub_oath"), (VIRTUAL_W / 2, 98), 14, (226, 214, 196), center=True, shadow=False)
        n = max(1, len(hand))
        cw, chh, gap = 272, 344, 26
        x0 = VIRTUAL_W / 2 - (n * cw + (n - 1) * gap) / 2
        top = 130
        self.cards = [(pygame.Rect(int(x0 + i * (cw + gap)), top, cw, chh), kt, i) for i, kt in enumerate(hand)]
        for rect, (key, tier), i in self.cards:
            k = ease_out_cubic(clamp((t - self.enter_t0 - 0.08 * i) / 0.36, 0.0, 1.0))
            hover = rect.collidepoint(mouse_pos) and k > 0.95
            bob = math.sin(t * 3 + rect.x * 0.01) * 3 - (6 if hover else 0)
            r2 = rect.move(0, bob + (1.0 - k) * 100)
            self._oath_card(surf, r2, key, t, hover, tier)
            kb = pygame.Rect(r2.x + 10, r2.bottom - 30, 22, 20)
            pygame.draw.rect(surf, (23, 17, 18), kb, border_radius=6)
            ink_frame(surf, kb, (90, 96, 130), 6, 1)
            draw_text(surf, str(i + 1), kb.center, 12, (200, 206, 230), bold=True, center=True, shadow=False)
            if hover and clicked:
                result = ("oath", (key, tier))
        for i, kc in enumerate((pygame.K_1, pygame.K_2, pygame.K_3)):
            if self._key_edge(kc) and i < len(self.cards) and result is None:
                result = ("oath", self.cards[i][1])
        bw, bg_ = 250, 16
        bx0 = VIRTUAL_W / 2 - (3 * bw + 2 * bg_) / 2
        by = top + chh + 22
        self.btn_a = pygame.Rect(bx0, by, bw, 46)
        self.btn_c = pygame.Rect(bx0 + bw + bg_, by, bw, 46)
        self.btn_b = pygame.Rect(bx0 + 2 * (bw + bg_), by, bw, 46)
        ha = self._button(surf, self.btn_a, L("m.later"), L("m.later_sub"), (150, 160, 190),
                          mouse_pos, "cross")
        # yenile: altınla, koşuda en çok 3 kez
        left = run.merchant_reroll_left() if hasattr(run, "merchant_reroll_left") else 0
        price = run.merchant_reroll_price() if left else 0
        gold = int(getattr(run, "gold_wallet", 0))
        can = left > 0 and gold >= price
        if left <= 0:
            sub = L("m.reroll_none")
        elif gold < price:
            sub = L("m.reroll_poor", fmt_num(price))
        else:
            sub = L("m.reroll_sub", fmt_num(price), left)
        hc = self._button(surf, self.btn_c, L("m.reroll"), sub, GOLD if can else (110, 110, 120),
                          mouse_pos, "coin", hotkey="R")
        hb = self._button(surf, self.btn_b, L("m.back"), "", (150, 160, 190), mouse_pos, "dash")
        reroll_key = self._key_edge(pygame.K_r)
        if result is None and ((clicked and hc) or reroll_key):
            if can:
                result = ("reroll", None)
                self.enter_t0 = None          # kartlar yeniden dağıtılsın
            else:
                sfx("error", 0.6, 0.0)
        elif result is None and clicked:
            if ha:
                result = ("close", None)
            elif hb:
                self.stage = "talk"
                self.t0 = t - 99.0
        return result


# oyun-içi market ekranı

class RunShopOverlay:
    """Oyun-içi market ekranı."""

    COLS = 5
    ROWS = 2

    def __init__(self):
        self.tab = next(iter(SHOP_CATS))
        self.page = 0

    # ---- yardımcılar ----
    @staticmethod
    def _hellish(run, tab):
        """Market kızıl temaya bürünsün mü?"""
        return run.biome == "hell" or tab == "hell"

    def _draw_backdrop(self, surf, hellish, t):
        overlay = pygame.Surface((VIRTUAL_W, VIRTUAL_H), pygame.SRCALPHA)
        if hellish:
            # kızıl degrade + alttan yükselen kor parıltısı
            for y in range(0, VIRTUAL_H, 4):
                k = y / VIRTUAL_H
                pygame.draw.rect(overlay, (int(26 + 34 * k), int(6 + 8 * k), int(8 + 6 * k), 232),
                                 pygame.Rect(0, y, VIRTUAL_W, 4))
            glow = pygame.Surface((VIRTUAL_W, 220), pygame.SRCALPHA)
            for i in range(220):
                a = int(46 * (i / 219.0) ** 2 * (0.75 + 0.25 * math.sin(t * 1.4)))
                pygame.draw.line(glow, (255, 96, 36, a), (0, i), (VIRTUAL_W, i))
            overlay.blit(glow, (0, VIRTUAL_H - 220))
        else:
            pygame.draw.rect(overlay, (5, 6, 12, 205), overlay.get_rect())
        surf.blit(overlay, (0, 0))
        if hellish:
            # havada süzülen kıvılcımlar
            for i in range(46):
                ph = (t * 0.30 + i * 0.0217) % 1.0
                ex = (i * 197 + math.sin(t * 0.7 + i) * 40) % VIRTUAL_W
                ey = VIRTUAL_H - ph * (VIRTUAL_H + 60)
                blit_disc(surf, ex, ey, 1.4 + 2.2 * (1 - ph),
                          (255, 170 - (int(60 * ph) // 24) * 24, 70), int(210 * (1 - ph)))

    def _draw_header(self, surf, run, hellish, t):
        if hellish:
            title, tcol = L("ui.hell_market"), (255, 132, 56)
            pulse = 0.55 + 0.45 * math.sin(t * 2.6)
            add_glow(surf, VIRTUAL_W / 2, 48, 210, (255, 90, 40), 0.18 + 0.10 * pulse)
            # başlığın iki yanında alev dilleri
            for sgn in (-1, 1):
                bx = VIRTUAL_W / 2 + sgn * 168
                for i in range(3):
                    h = 22 + 12 * math.sin(t * 7 + i * 1.5 + (0 if sgn > 0 else 2.0))
                    pygame.draw.polygon(surf, (255, 150 - i * 26, 50),
                                        [(bx + i * 9 * sgn, 60), (bx + 4 * sgn + i * 9 * sgn, 60 - h),
                                         (bx + 9 * sgn + i * 9 * sgn, 60)])
        else:
            title, tcol = L("ui.market"), GOLD
        draw_text(surf, title, (VIRTUAL_W / 2, 22), 32, tcol, bold=True, center=True)
        # başlığın altında iki yana açılan ince ayraç
        for sgn in (-1, 1):
            x0 = VIRTUAL_W / 2 + sgn * 108
            taper_line(surf, [(x0, 58), (x0 + sgn * 150, 58)], 2.4, 0.6,
                       scale_col(tcol, 0.85))
            circle_aa(surf, x0 + sgn * 154, 58, 2.5, tcol)
        # altın kesesi: fiyatlarla aynı dilde bir pastil
        purse_txt = fmt_num(run.gold_wallet)
        purse = pygame.Rect(0, 0, int(coin_label_width(purse_txt, 20, 9)) + 32, 32)
        purse.center = (VIRTUAL_W / 2, 58)
        pss = pygame.Surface(purse.size, pygame.SRCALPHA)
        pygame.draw.rect(pss, (19, 14, 14, 210), pss.get_rect(), border_radius=16)
        surf.blit(pss, purse.topleft)
        ink_frame(surf, purse, GOLD, 16, 2)
        draw_coin_label(surf, purse.centerx, purse.centery, purse_txt, GOLD, 20,
                        icon_r=9)

    def _draw_tabs(self, surf, run, mouse_pos, clicked, hellish, t):
        tabs = [(k, LX("cat." + k, v)) for k, v in SHOP_CATS.items()]
        tab_w, tab_h, tab_gap = 118, 30, 7
        total_tw = len(tabs) * tab_w + (len(tabs) - 1) * tab_gap
        tx0 = VIRTUAL_W / 2 - total_tw / 2
        ty = 102
        counts = {}
        for it in run.shop_offers:
            counts[it["cat"]] = counts.get(it["cat"], 0) + 1
        for i, (key, label) in enumerate(tabs):
            r = pygame.Rect(tx0 + i * (tab_w + tab_gap), ty, tab_w, tab_h)
            active = (self.tab == key)
            hover = r.collidepoint(mouse_pos)
            is_hell_tab = (key == "hell")
            # cehennem sekmesi 2. haritada erişilebilir; arenada kilitli
            # görünür
            locked = is_hell_tab and run.biome != "hell"
            if is_hell_tab:
                base = (128, 40, 18) if active else ((72, 26, 16) if hover else (44, 18, 14))
                edge = (255, 120, 50) if (active or hover) else (128, 58, 34)
            else:
                base = (90, 70, 30) if active else ((75, 54, 56) if hover else (50, 37, 38))
                edge = GOLD if active else PANEL_EDGE
            if locked:
                base, edge = (30, 20, 22), (92, 54, 44)
            pygame.draw.rect(surf, base, r, border_radius=8)
            ink_frame(surf, r, edge, 8, 2)
            if is_hell_tab and not locked:
                add_glow(surf, r.centerx, r.centery, 34, (255, 110, 50),
                         0.20 + 0.10 * math.sin(t * 3))
                draw_icon(surf, r.x + 15, r.centery, "flame", (255, 150, 60), 8)
            if active:
                # etkin sekmenin altında ince bir vurgu çizgisi
                pygame.draw.rect(surf, edge, (r.x + 10, r.bottom - 4, r.w - 20, 3),
                                 border_radius=2)
            txt_col = TEXT if active else (TEXT_DIM if not locked else (120, 86, 80))
            draw_text(surf, label, (r.centerx + (6 if is_hell_tab else 0), r.centery - 3),
                      12, txt_col, bold=active, center=True, shadow=False)
            n_cat = counts.get(key, 0)
            if n_cat and not locked:
                # Sayı rozeti etkin olmayan sekmelerde de okunmalı: sekmenin
                # kendi kenar rengi koyu olduğu için sabit bir soluk ton.
                draw_text(surf, str(n_cat), (r.right - 13, r.y + 3), 9,
                          lighten(edge, 0.35) if active else (128, 134, 162),
                          bold=True, center=True, shadow=False)
            if clicked and hover:
                if self.tab != key:
                    self.page = 0
                self.tab = key
                sfx("click", 0.5, 0.0)

    # Kademe rozetleri: eşyanın hangi kuşaktan olduğunu tek bakışta verir.
    TIER_BADGE = {1: ("I", (150, 186, 220)), 2: ("II", (150, 220, 170)),
                  3: ("III", (200, 160, 245)), 4: ("IV", (245, 205, 110)),
                  5: ("V", (255, 130, 70))}

    def _draw_card(self, surf, run, item, rect, mouse_pos, clicked, hellish, t, i):
        """Tek bir market kartı."""
        p = run.player
        unlocked = shop_item_unlocked(item, run.waves.wave, run.biome)
        hover = rect.collidepoint(mouse_pos) and unlocked
        lvl = p.shop_levels.get(item["key"], 0)
        maxed = lvl >= item.get("max", 999)
        cost = shop_item_cost(item, lvl)
        affordable = unlocked and not maxed and run.gold_wallet >= cost
        is_hell_item = bool(item.get("hell_only"))
        col = tuple(item["color"])
        pulse = 0.5 + 0.5 * math.sin(t * 3.0 + i * 0.8)

        # Hover'da kart hafifçe yukarı kalkar - listenin canlı durması için.
        if hover:
            rect = rect.move(0, -4)

        # ---- zemin: düz dolgu, mürekkep kontur, sert gölge ----
        if not unlocked:
            fill = (34, 24, 26) if is_hell_item else (36, 29, 30)
        elif is_hell_item:
            fill = (84, 30, 22) if hover else (58, 22, 18)
        else:
            fill = mix_col(col, (40, 31, 32), 0.72) if hover else (46, 35, 36)
        surf.blit(hand_shadow(rect.w, rect.h, 16), (rect.x + 4, rect.y + 5))
        surf.blit(hand_card(rect.w, rect.h, fill, rad=16, alpha=248), rect.topleft)

        # ---- çerçeve ----
        if not unlocked:
            edge_col = (58, 40, 40) if is_hell_item else (86, 64, 66)
        elif maxed:
            edge_col = GREEN
        elif item.get("legendary"):
            edge_col = GOLD
        elif affordable:
            edge_col = lighten(col, 0.22) if hover else col
        else:
            edge_col = scale_col(col, 0.45)
        ink_frame(surf, rect, edge_col, 16, 3 if hover or maxed else 2)

        # ---- üst şerit: kategori + kademe rozeti ----
        strip = pygame.Surface((rect.w - 22, 4), pygame.SRCALPHA)
        pygame.draw.rect(strip, (*edge_col, 210), strip.get_rect(), border_radius=2)
        surf.blit(strip, (rect.x + 11, rect.y + 8))
        badge, bcol = self.TIER_BADGE.get(item.get("tier", 1), ("I", TEXT_DIM))
        draw_text(surf, LX("cat." + item["cat"], SHOP_CATS.get(item["cat"], "")), (rect.x + 13, rect.y + 16), 9,
                  scale_col(edge_col, 0.95) if unlocked else (124, 105, 106),
                  bold=True, shadow=False)
        draw_text(surf, badge, (rect.right - 20, rect.y + 15), 11,
                  bcol if unlocked else (124, 105, 106), bold=True, center=True,
                  shadow=False)

        if is_hell_item and unlocked:
            # ergimiş kenar: kartın alt kenarında akkor bir şerit + kıvılcımlar
            molten = pygame.Surface((rect.w - 12, 5), pygame.SRCALPHA)
            for xx in range(molten.get_width()):
                k = 0.5 + 0.5 * math.sin(t * 3 + xx * 0.08 + i)
                pygame.draw.line(molten, (255, int(110 + 90 * k), 50, 190),
                                 (xx, 0), (xx, 5))
            surf.blit(molten, (rect.x + 6, rect.bottom - 8))
            for e in range(3):
                ph = (t * 0.9 + e * 0.33 + i * 0.2) % 1.0
                ex = rect.x + 16 + ((e * 73 + i * 37) % max(1, rect.w - 32))
                ey = rect.bottom - 10 - ph * 40
                blit_disc(surf, ex, ey, max(1.0, 2.6 * (1 - ph)), (255, 190, 90),
                          int(190 * (1 - ph)))

        # ---- madalyon + simge ----
        icon_col = col if unlocked else (106, 89, 90)
        icx, icy = rect.centerx, rect.y + 52
        if unlocked and not maxed:
            add_glow(surf, icx, icy, 34, icon_col, 0.24 + 0.14 * pulse)
        # madalyonun bütün katmanları aynı merkezde. Ayrı bir siyah taban
        # dairesine de gerek yok: degradenin kenarı zaten koyu.
        disc_grad(surf, icx, icy, 25, scale_col(icon_col, 0.50), (15, 16, 25), 9)
        ring_aa(surf, icx, icy, 25, icon_col, 2)
        # dönen kertikler - silah armalarıyla aynı dil
        if unlocked:
            for k_ in range(10):
                a = t * 0.5 + k_ * math.tau / 10
                thick_line(surf, (icx + math.cos(a) * 28, icy + math.sin(a) * 28),
                           (icx + math.cos(a) * (31 + 2 * pulse),
                            icy + math.sin(a) * (31 + 2 * pulse)),
                           1.2, scale_col(icon_col, 0.40 + 0.40 * pulse))
        draw_icon(surf, icx, icy, item["icon"] if unlocked else "shield",
                  lighten(icon_col, 0.25) if unlocked else icon_col,
                  19 if unlocked else 15)

        # ---- ad ----
        draw_text(surf, shop_name(item), (rect.centerx, rect.y + 88), 15,
                  TEXT if unlocked else TEXT_DIM, bold=True, center=True)
        if item.get("cursed"):
            draw_text(surf, L("ui.cursed"), (rect.centerx, rect.y + 105), 9, (235, 90, 110),
                      bold=True, center=True, shadow=False)
        elif item.get("legendary"):
            draw_text(surf, L("ui.legendary"), (rect.centerx, rect.y + 105), 9, GOLD,
                      bold=True, center=True, shadow=False)

        if not unlocked:
            if is_hell_item:
                draw_text(surf, L("ui.hell_only"), (rect.centerx, rect.y + 126), 12,
                          (255, 150, 90), center=True, shadow=False)
            else:
                need_wave = TIER_UNLOCK_WAVE.get(item["tier"], 0)
                draw_text(surf, L("ui.wave_unlock", need_wave), (rect.centerx, rect.y + 126),
                          12, GOLD_DIM, center=True, shadow=False)
            return

        # ---- açıklama ----
        off = 12 if (item.get("cursed") or item.get("legendary")) else 0
        for j, ln in enumerate(wrap_text(shop_desc(item), 11, rect.w - 26)[:3]):
            draw_text(surf, ln, (rect.centerx, rect.y + 110 + off + j * 14), 11,
                      TEXT_DIM, center=True, shadow=False)

        # ---- seviye göstergesi: tavanı olanlarda boncuk, sonsuzlarda sayı ----
        if not item.get("instant"):
            if item.get("endless"):
                draw_text(surf, L("ui.level_nocap", lvl),
                          (rect.centerx, rect.y + 168), 11, (206, 186, 126),
                          bold=True, center=True, shadow=False)
            else:
                mx = int(item.get("max", 1))
                pip_r, gap_p = 4, 11
                total = mx * gap_p - (gap_p - pip_r * 2)
                px0 = rect.centerx - total / 2 + pip_r
                for j in range(mx):
                    pc = col if j < lvl else (52, 54, 72)
                    circle_aa(surf, px0 + j * gap_p, rect.y + 166, pip_r, pc)
                    if j < lvl:
                        circle_aa(surf, px0 + j * gap_p - 1, rect.y + 165, pip_r * 0.45,
                                  lighten(col, 0.6))
                draw_text(surf, f"{lvl}/{mx}", (rect.centerx, rect.y + 176), 9,
                          TEXT_DIM, center=True, shadow=False)

        # ---- alt: fiyat pastili / maksimum mührü ----
        if maxed:
            mr = pygame.Rect(rect.x + 30, rect.y + 198, rect.w - 60, 24)
            pygame.draw.rect(surf, (18, 40, 26), mr, border_radius=12)
            ink_frame(surf, mr, GREEN, 12, 2)
            draw_text(surf, L("ui.maxed"), mr.center, 12, GREEN, bold=True, center=True,
                      shadow=False)
        else:
            pcol = GOLD if affordable else (122, 98, 62)
            cost_txt = fmt_num(cost)
            # Pastil, içindeki "sikke + sayı" bloğunun gerçek genişliğine göre
            # kurulur; blok da pastilin tam ortasına oturur.
            block_w = coin_label_width(cost_txt, 17, 8)
            pill = pygame.Rect(0, 0, int(block_w) + 26, 26)
            pill.center = (rect.centerx, rect.y + 212)
            ps = pygame.Surface(pill.size, pygame.SRCALPHA)
            pygame.draw.rect(ps, (19, 14, 14, 190), ps.get_rect(), border_radius=13)
            surf.blit(ps, pill.topleft)
            ink_frame(surf, pill, pcol if affordable else scale_col(pcol, 0.7), 13, 2)
            draw_coin_label(surf, pill.centerx, pill.centery, cost_txt, pcol, 17,
                            icon_r=8)
            if hover and affordable:
                draw_text(surf, L("ui.buy"), (rect.centerx, rect.y + 190), 10,
                          lighten(col, 0.35), bold=True, center=True, shadow=False)
            elif not affordable:
                draw_text(surf, L("ui.no_gold"), (rect.centerx, rect.y + 190), 9,
                          (150, 110, 90), center=True, shadow=False)
            if hover and clicked and affordable:
                run.buy_shop_item(item["key"])

    # ---- ana çizim ----
    def draw_and_handle(self, surf, run, mouse_pos, clicked, t):
        hellish = self._hellish(run, self.tab)
        self._draw_backdrop(surf, hellish, t)
        self._draw_header(surf, run, hellish, t)
        self._draw_tabs(surf, run, mouse_pos, clicked, hellish, t)

        offers = [it for it in run.shop_offers if it["cat"] == self.tab]
        per_page = self.COLS * self.ROWS
        pages = max(1, (len(offers) + per_page - 1) // per_page)
        self.page = clamp(self.page, 0, pages - 1)
        shown = offers[self.page * per_page:(self.page + 1) * per_page]

        card_w, card_h = 216, 232
        gap_x, gap_y = 12, 10
        total_w = self.COLS * card_w + (self.COLS - 1) * gap_x
        start_x = VIRTUAL_W / 2 - total_w / 2
        start_y = 138

        for i, item in enumerate(shown):
            col_i, row = i % self.COLS, i // self.COLS
            rect = pygame.Rect(start_x + col_i * (card_w + gap_x),
                               start_y + row * (card_h + gap_y), card_w, card_h)
            self._draw_card(surf, run, item, rect, mouse_pos, clicked, hellish, t, i)

        if not offers:
            draw_text(surf, L("ui.cat_empty"),
                      (VIRTUAL_W / 2, start_y + 90), 18, TEXT_DIM, center=True)

        # ---- sayfa okları (bir kategoride 10'dan fazla eşya varsa) ----
        if pages > 1:
            py = VIRTUAL_H - 92
            for dx in (-1, 1):
                br = pygame.Rect(int(VIRTUAL_W / 2 + dx * 118 - 20), py, 40, 30)
                can = (self.page > 0) if dx < 0 else (self.page < pages - 1)
                hov = br.collidepoint(mouse_pos) and can
                bcol = ((96, 36, 20) if hellish else (82, 59, 61)) if hov else (
                    (52, 22, 16) if hellish else (53, 38, 39))
                pygame.draw.rect(surf, bcol, br, border_radius=8)
                ink_frame(surf, br, (255, 120, 50) if hellish else PANEL_EDGE, 8, 2)
                # Ok işareti yazı tipine bağlı kalmasın diye üçgen çiziliyor.
                acol = TEXT if can else (96, 90, 104)
                pygame.draw.polygon(surf, acol, [
                    (br.centerx + dx * 7, br.centery),
                    (br.centerx - dx * 5, br.centery - 8),
                    (br.centerx - dx * 5, br.centery + 8)])
                if hov and clicked:
                    self.page = clamp(self.page + dx, 0, pages - 1)
                    sfx("click", 0.5, 0.0)
            draw_text(surf, L("ui.page", self.page + 1, pages), (VIRTUAL_W / 2, py + 6), 15,
                      (255, 170, 110) if hellish else TEXT, bold=True, center=True)

        btn = Button((VIRTUAL_W / 2 - 130, VIRTUAL_H - 50, 260, 38), L("ui.close_b"), None,
                     color=(104, 44, 26) if hellish else (115, 86, 88),
                     hover_color=(150, 66, 36) if hellish else (95, 105, 140))
        btn.update(mouse_pos, 1 / 60)
        btn.draw(surf)
        return btn.rect.collidepoint(mouse_pos) and clicked


