class HouseAd:
    LENGTH = 30.0
    SCENES = ((0.0, "intro"), (3.5, "fight"), (11.0, "arsenal"), (17.5, "books"),
              (22.5, "style"), (26.5, "outro"))
    WIPE = 0.32

    def __init__(self, save):
        self.save = save
        self.t = 0.0
        self.frame = pygame.Surface((VIRTUAL_W, VIRTUAL_H)).convert()
        self._bg = {}
        self.runs = {}
        self.ai = {}
        self._sfx_marks = set()
        try:
            self.skin_id = save.equipped_skin_id()
        except Exception:
            self.skin_id = "default"
        floor_surface("arena")           # zemin ilk kez burada çizilsin (sahne ortasında takılmasın)
        # İki koşu baştan kurulur ve giriş sahnesi sürerken arkada ısınır:
        # sahne açıldığında ekran zaten kalabalık olsun.
        self._make_run("fight", weapons={}, books={"r_dmg": 3, "r_aspd": 2}, wave=6, crowd=34)
        self._make_run("arsenal", weapons={"axe": 5, "pentagram": 5, "whip": 4, "tornado": 4},
                       books={"r_dmg": 4, "r_crit": 3, "r_vamp": 2}, wave=9, crowd=46)

    def scene(self, t=None):
        t = self.t if t is None else t
        name, start, end = "intro", 0.0, self.LENGTH
        for i, (st, nm) in enumerate(self.SCENES):
            if t >= st:
                name, start = nm, st
                end = self.SCENES[i + 1][0] if i + 1 < len(self.SCENES) else self.LENGTH
        return name, t - start, end - start

    def _make_run(self, key, weapons, books, wave, crowd):
        sb = _AdSave(self.save.data)
        run = RunState(sb, self.skin_id, "normal", ach=_AdAch())
        p = run.player
        p.no_stats = True                # gerçek kayda dash sayılmasın
        p.weapons = dict(weapons)
        p.books = dict(books)
        p.level = 6 + len(weapons) * 3
        run.waves.wave = wave
        for _ in range(crowd // 2):
            self._spawn(run)
        self.runs[key] = run
        self.ai[key] = {"ang": random.uniform(0, math.tau), "cx": p.x, "cy": p.y,
                        "bonk": 0.6, "dash": 1.8, "crowd": crowd}
        for _ in range(45):              # yarım saniyelik ısınma
            self._step(key, 1 / 90.0)

    def _spawn(self, run):
        x, y = run.near_camera_point()
        kind = random.choice(("red", "red", "blue", "yellow", "tank", "sprinter", "brute"))
        run.enemies.append(Enemy(kind, x, y, run.wave_hp_mult(run.waves.wave), 1.0,
                                 wave=run.waves.wave))

    def _step(self, key, dt):
        """Otomatik pilot: düşmanların çevresinde dolanır, en yakına ateş eder"""
        run, ai = self.runs[key], self.ai[key]
        p = run.player
        p.hp = p.max_hp
        run.pending_levelups = 0
        run.levelup_choices = []
        run.want_open_shop = False
        while len(run.enemies) < ai["crowd"]:
            self._spawn(run)
        ai["ang"] += dt * 0.55
        tx = ai["cx"] + math.cos(ai["ang"]) * 210
        ty = ai["cy"] + math.sin(ai["ang"]) * 130
        mx, my = tx - p.x, ty - p.y
        near, nd, close = None, 1e9, 0
        for e in run.enemies:
            if not e.alive:
                continue
            d = (e.x - p.x) ** 2 + (e.y - p.y) ** 2
            if d < nd:
                near, nd = e, d
            if d < 150 * 150:
                close += 1
                if d < 95 * 95:              # çok yakına geleni savuştur
                    k = 1.0 / max(20.0, math.sqrt(d))
                    mx -= (e.x - p.x) * k * 160
                    my -= (e.y - p.y) * k * 160
        ln = math.hypot(mx, my) or 1.0
        mx, my = mx / ln, my / ln
        inp = {"left": max(0.0, -mx), "right": max(0.0, mx), "up": max(0.0, -my),
               "down": max(0.0, my), "mouse_down": near is not None, "use_pressed": False}
        if near is not None:
            inp["aim_x"], inp["aim_y"] = near.x, near.y
        ai["bonk"] -= dt
        ai["dash"] -= dt
        inp["bonk_pressed"] = close >= 4 and ai["bonk"] <= 0
        if inp["bonk_pressed"]:
            ai["bonk"] = 1.6
        inp["dash_pressed"] = close >= 7 and ai["dash"] <= 0
        if inp["dash_pressed"]:
            ai["dash"] = 2.4
        run.update(dt, inp)

    def update(self, dt):
        self.t = min(self.LENGTH, self.t + dt)
        name, st, _ln = self.scene()
        dt = min(dt, 1 / 30.0)
        if name in ("intro", "fight"):
            self._step("fight", dt)
        if name in ("fight", "arsenal") or (name == "intro" and self.t > 2.0):
            self._step("arsenal", dt)
        # sahneye özel ses vuruşları (her biri bir kez)
        for mark, at, snd in (("bonk", 1.1, "bonk"), ("lvl", 19.6, "levelup"),
                              ("buy", 27.0, "buy")):
            if self.t >= at and mark not in self._sfx_marks:
                self._sfx_marks.add(mark)
                sfx(snd, 0.8, 0.0)

    def _grad(self, key, top, bot):
        img = self._bg.get(key)
        if img is None:
            img = pygame.Surface((VIRTUAL_W, VIRTUAL_H)).convert()
            for y in range(VIRTUAL_H):
                pygame.draw.line(img, mix_col(top, bot, y / VIRTUAL_H), (0, y), (VIRTUAL_W, y))
            self._bg[key] = img
        return img

    def _rays(self, surf, cx, cy, t, col, n=18, alpha=40, rlen=900):
        lay = self._bg.get("rays_lay")
        if lay is None:
            lay = self._bg["rays_lay"] = pygame.Surface((VIRTUAL_W, VIRTUAL_H), pygame.SRCALPHA)
        lay.fill((0, 0, 0, 0))
        for i in range(n):
            a = t * 0.25 + i * math.tau / n
            w = 0.05
            pygame.draw.polygon(lay, (*col, alpha), [(cx, cy),
                                (cx + math.cos(a - w) * rlen, cy + math.sin(a - w) * rlen),
                                (cx + math.cos(a + w) * rlen, cy + math.sin(a + w) * rlen)])
        surf.blit(lay, (0, 0))

    def _caption(self, surf, text, sub, st, y=600, col=(255, 214, 120), x0=0):
        """Alt yazı şeridi: soldan kayarak girer."""
        k = ease_out_cubic(min(1.0, st / 0.45))
        tw = max(text_width(text, 40, True), text_width(sub, 22, True) if sub else 0) + 90
        x = x0 - tw + (tw + 60) * k
        h = 98 if sub else 70
        bar = pygame.Surface((int(tw), h), pygame.SRCALPHA)
        bar.fill((23, 17, 18, 215))
        surf.blit(bar, (int(x), y))
        pygame.draw.rect(surf, col, pygame.Rect(int(x + tw - 10), y, 10, h))
        draw_text(surf, text, (int(x) + 30, y + 10), 40, col, bold=True)
        if sub:
            draw_text(surf, sub, (int(x) + 32, y + 60), 22, (236, 232, 244), bold=True)

    def _run_shot(self, surf, key, zoom):
        """Gerçek koşuyu çizer; hafif bir 'kamera yaklaşması' ile."""
        run = self.runs[key]
        draw_run(self.frame, run, self.t + 100.0)
        if zoom <= 1.001:
            surf.blit(self.frame, (0, 0))
            return
        w, h = int(VIRTUAL_W / zoom), int(VIRTUAL_H / zoom)
        px, py = run.world_to_screen(run.player.x, run.player.y)
        x = int(clamp(px - w / 2, 0, VIRTUAL_W - w))
        y = int(clamp(py - h / 2, 0, VIRTUAL_H - h))
        sub = self.frame.subsurface(pygame.Rect(x, y, w, h))
        surf.blit(pygame.transform.smoothscale(sub, (VIRTUAL_W, VIRTUAL_H)), (0, 0))

    def render(self):
        """Şu anki sahneyi self.frame boyutunda bir yüzeye çizer ve döndürür."""
        out = self._bg.get("out")
        if out is None:
            out = self._bg["out"] = pygame.Surface((VIRTUAL_W, VIRTUAL_H)).convert()
        name, st, ln = self.scene()
        getattr(self, "_s_" + name)(out, st, ln)
        # sahne geçişi: çapraz altın perde
        if st < self.WIPE and self.t > self.WIPE:
            k = st / self.WIPE
            x0 = -200 + (VIRTUAL_W + 400) * k
            pygame.draw.polygon(out, (236, 186, 92), [(x0, 0), (x0 + 260, 0), (x0 + 60, VIRTUAL_H),
                                                     (x0 - 200, VIRTUAL_H)])
            pygame.draw.polygon(out, (255, 240, 200), [(x0 + 200, 0), (x0 + 260, 0),
                                                      (x0 + 60, VIRTUAL_H), (x0, VIRTUAL_H)])
        # sinema bantları
        pygame.draw.rect(out, (0, 0, 0), pygame.Rect(0, 0, VIRTUAL_W, 18))
        pygame.draw.rect(out, (0, 0, 0), pygame.Rect(0, VIRTUAL_H - 18, VIRTUAL_W, 18))
        return out

    def _s_intro(self, surf, st, ln):
        surf.blit(self._grad("intro", (54, 30, 80), (12, 8, 24)), (0, 0))
        cx, cy = VIRTUAL_W / 2, VIRTUAL_H / 2 - 30
        self._rays(surf, cx, cy, self.t, (236, 186, 92), alpha=34)
        add_glow(surf, cx, cy, 460, (210, 150, 60), 0.35)
        k = min(1.0, st / 0.7)
        bounce = 1.0 + 0.10 * math.sin(min(1.0, k) * math.pi) * (1 - k)
        logo = brand_scaled("logo", w=820)
        if logo is not None:
            s_ = (0.55 + 0.45 * ease_out_cubic(k)) * bounce
            img = pygame.transform.smoothscale(logo, (int(logo.get_width() * s_),
                                                      int(logo.get_height() * s_)))
            surf.blit(img, (cx - img.get_width() / 2, cy - img.get_height() / 2))
        if st > 1.1:                       # bonk dalgası
            q = min(1.0, (st - 1.1) / 0.6)
            ring_aa(surf, cx, cy, 120 + 520 * q, (255, 230, 170), max(1, int(10 * (1 - q))))
        if st > 1.5:
            a = int(255 * min(1.0, (st - 1.5) / 0.4))
            draw_text(surf, L("ad.tag"), (cx, cy + 210), 30, (255, 236, 182), bold=True,
                      center=True, alpha=a)

    def _s_fight(self, surf, st, ln):
        self._run_shot(surf, "fight", 1.0 + 0.10 * (st / ln))
        if st < ln / 2:
            self._caption(surf, L("ad.fight1"), L("ad.fight1s"), st)
        else:
            self._caption(surf, L("ad.fight2"), L("ad.fight2s"), st - ln / 2, col=(140, 230, 170))

    def _s_arsenal(self, surf, st, ln):
        self._run_shot(surf, "arsenal", 1.04)
        # soldan akan silah geçidi
        side = pygame.Surface((300, VIRTUAL_H), pygame.SRCALPHA)
        side.fill((10, 8, 18, 210))
        surf.blit(side, (0, 0))
        pygame.draw.rect(surf, (238, 150, 100), pygame.Rect(298, 0, 3, VIRTUAL_H))
        step = 118
        off = (st * 140) % (step * len(BOSS_WEAPONS))
        prev = surf.get_clip()
        surf.set_clip(pygame.Rect(0, 128, 298, VIRTUAL_H - 146))
        for i in range(len(BOSS_WEAPONS) + 6):
            w = BOSS_WEAPONS[i % len(BOSS_WEAPONS)]
            y = 196 + i * step - off
            if y < 70 or y > VIRTUAL_H + 60:
                continue
            draw_weapon_emblem(surf, 92, y, 84, w, self.t, locked=False, glow=True)
            draw_text(surf, w_name(w), (150, y - 16), 20, tuple(w["color"]), bold=True)
            draw_text(surf, L("ui.passive") if w.get("passive") else L("ad.active"),
                      (150, y + 10), 13, TEXT_DIM, bold=True)
        surf.set_clip(prev)
        draw_text(surf, L("ui.codex"), (150, 52), 34, (238, 150, 100), bold=True, center=True)
        draw_text(surf, L("ad.n_weapons", len(BOSS_WEAPONS)), (150, 94), 18, TEXT, bold=True,
                  center=True)
        pygame.draw.line(surf, (110, 70, 50), (24, 120), (274, 120), 2)
        self._caption(surf, L("ad.arsenal"), L("ad.arsenal_s"), st, y=590, x0=301)

    def _s_books(self, surf, st, ln):
        surf.blit(self._grad("books", (44, 28, 22), (14, 10, 12)), (0, 0))
        # raf tahtaları
        for sy in (250, 470):
            pygame.draw.rect(surf, (92, 60, 36), pygame.Rect(0, sy, VIRTUAL_W, 22))
            pygame.draw.rect(surf, (128, 86, 52), pygame.Rect(0, sy, VIRTUAL_W, 5))
            pygame.draw.rect(surf, (30, 20, 14), pygame.Rect(0, sy + 22, VIRTUAL_W, 10))
        books = [b for b in BOOKS][:22]
        if st < 2.2:
            # kitaplar rafa dizilir
            for i, bk in enumerate(books):
                row, col = divmod(i, 11)
                k = ease_out_cubic(clamp((st - i * 0.06) / 0.5, 0.0, 1.0))
                x = 90 + col * 110
                y = (176 if row == 0 else 396) - (1 - k) * 260
                if k > 0:
                    draw_book(surf, x, y, 120, bk, self.t, locked=False, glow=k >= 1.0)
            draw_text(surf, L("ui.books"), (VIRTUAL_W / 2, 560), 44, (196, 150, 255), bold=True,
                      center=True)
            draw_text(surf, L("ad.n_books", len(BOOKS)), (VIRTUAL_W / 2, 612), 24, TEXT, bold=True,
                      center=True)
        else:
            # seviye atladın: üç kart gelir, biri seçilir
            q = st - 2.2
            dim = pygame.Surface((VIRTUAL_W, VIRTUAL_H), pygame.SRCALPHA)
            dim.fill((8, 6, 14, 190))
            surf.blit(dim, (0, 0))
            draw_text(surf, L("ad.levelup"), (VIRTUAL_W / 2, 92), 52, GOLD, bold=True, center=True)
            picks = [BOOK_BY_KEY.get(k) for k in ("r_dmg", "r_crit", "r_vamp")]
            for i, bk in enumerate(p for p in picks if p):
                k = ease_out_cubic(clamp((q - i * 0.15) / 0.45, 0.0, 1.0))
                cx = VIRTUAL_W / 2 + (i - 1) * 320
                r = pygame.Rect(0, 0, 270, 360)
                r.center = (int(cx), int(370 + (1 - k) * 420))
                chosen = i == 1 and q > 1.4
                if chosen:
                    add_glow(surf, r.centerx, r.centery, 260, GOLD, 0.35)
                    r = r.inflate(18, 18)
                panel(surf, r, bg=(30, 24, 44), edge=GOLD if chosen else (120, 100, 170),
                      alpha=250, radius=18, edge_w=4 if chosen else 2)
                draw_book(surf, r.centerx, r.y + 120, 150, bk, self.t)
                draw_text(surf, bk_name(bk), (r.centerx, r.y + 230), 24, TEXT, bold=True, center=True)
                for j, lnx in enumerate(wrap_text(bk_desc(bk), 15, r.w - 30)[:3]):
                    draw_text(surf, lnx, (r.centerx, r.y + 266 + j * 20), 15, TEXT_DIM, center=True)
                if chosen:
                    draw_text(surf, L("ad.picked"), (r.centerx, r.bottom - 28), 18, GREEN,
                              bold=True, center=True)
            self._caption(surf, L("ad.books"), L("ad.books_s"), q, y=596, col=(196, 150, 255))

    def _s_style(self, surf, st, ln):
        surf.blit(self._grad("style", (24, 30, 60), (10, 10, 22)), (0, 0))
        self._rays(surf, VIRTUAL_W / 2, 330, self.t, (120, 160, 255), alpha=22)
        sk_list = [s for s in SKINS if not s.get("premium")][2:7] + \
                  [s for s in SKINS if s.get("premium")][:3]
        n = len(sk_list)
        # döner geçit
        for i, sk in enumerate(sk_list):
            a = st * 0.9 + i * math.tau / n
            depth = (math.sin(a) + 1) / 2          # 0 arka, 1 ön
            x = VIRTUAL_W / 2 + math.cos(a) * 420
            y = 300 + depth * 70
            r = int(22 + 26 * depth)
            add_glow(surf, x, y, r * 3, sk["color"], 0.12 + 0.2 * depth)
            surf.blit(shadow_sprite(r * 2 + 10), (int(x - r - 5), int(y + r - 4)))
            draw_skin_preview(surf, sk, x, y, self.t, r=r)
            if depth > 0.8:
                draw_text(surf, skin_name(sk), (x, y + r + 22), 22, sk["color"], bold=True,
                          center=True)
                if sk.get("premium"):
                    draw_text(surf, L("ui.premium"), (x, y - r - 30), 15, PURPLE, bold=True,
                              center=True)
        # pet'ler önde koşturur
        for i, pet in enumerate(PETS[:5]):
            x = (st * 160 + i * 230) % (VIRTUAL_W + 200) - 100
            draw_pet(surf, pet["kind"], x, 470 + math.sin(self.t * 8 + i) * 4, 16, self.t, face=1,
                     moving=True, col=pet["color"], acc=pet["accent"])
        self._caption(surf, L("ad.style"), L("ad.style_s"), st, y=560, col=(130, 200, 255))

    def _s_outro(self, surf, st, ln):
        surf.blit(self._grad("intro", (54, 30, 80), (12, 8, 24)), (0, 0))
        cx, cy = VIRTUAL_W / 2, 270
        self._rays(surf, cx, cy, self.t, (236, 186, 92), alpha=40)
        add_glow(surf, cx, cy, 480, (210, 150, 60), 0.32)
        logo = brand_scaled("logo", w=760)
        if logo is not None:
            surf.blit(logo, (cx - logo.get_width() / 2, cy - logo.get_height() / 2))
        k = 0.5 + 0.5 * math.sin(self.t * 5)
        b = pygame.Rect(0, 0, 420, 86)
        b.center = (int(cx), 520)
        add_glow(surf, b.centerx, b.centery, 260, GREEN, 0.18 + 0.12 * k)
        surf.blit(_button_body(b.w, b.h, (60, 150, 92), k, 22), b.topleft)
        pygame.draw.rect(surf, (190, 255, 210), b, width=3, border_radius=22)
        draw_text(surf, L("ad.play_now"), b.center, int(40 + 3 * k), WHITE, bold=True, center=True)
        draw_text(surf, L("ad.outro_s"), (cx, 610), 22, (236, 222, 196), bold=True, center=True)
        if NEW_YEAR_THEME:
            for i in range(40):
                x = (i * 131.3 + math.sin(self.t + i) * 20) % VIRTUAL_W
                y = (self.t * (40 + i % 5 * 12) + i * 57) % VIRTUAL_H
                blit_disc(surf, x, y, 2 + i % 3, (255, 255, 255), 200)


# ---- oyun turu - 90 saniyelik tanıtım filmi ----
# Ödüllü reklamın içeriği: izleyen hem oyunu öğrenir hem elmas kazanır.
def draw_stamp(surf, text, st, col, y=360, life=2.2):
    """Ekranın ortasına 'pat' diye inen büyük yazı şeridi (yeni rekor! gibi). st"""
    if st < 0 or st > life:
        return
    k = ease_out_cubic(min(1.0, st / 0.25))
    size = int(64 + 40 * (1 - k))
    a = min(1.0, (life - st) / 0.4)
    band = pygame.Surface((VIRTUAL_W, 118), pygame.SRCALPHA)
    band.fill((8, 6, 14, int(200 * a * k)))
    surf.blit(band, (0, int(y - 59)))
    for sgn in (-1, 1):
        pygame.draw.line(surf, scale_col(col, 0.7 * a + 0.1), (0, int(y + sgn * 59)),
                         (VIRTUAL_W, int(y + sgn * 59)), 2)
    add_glow(surf, VIRTUAL_W / 2, y, 260, col, 0.25 * k)
    draw_text(surf, text, (VIRTUAL_W / 2, y), size, col, bold=True, center=True,
              alpha=int(255 * a))


def _tc(tr, en, es=None, de=None, ru=None):
    """Tur yazıları oyuncunun dilinde (5 dil; eksik dil İngilizceye düşer)."""
    lg = lang()
    if lg == "tr":
        return tr
    return {"es": es, "de": de, "ru": ru}.get(lg) or en


def tour_kill_boss(b, fx):
    """Turda patronu tek vuruşta devirir."""
    if not b.alive:
        return
    b.intake_budget = 1e18
    b.armor = 0.0
    b.take_damage(b.hp + 50, True, fx)


class _TourPilot:
    """Turun savaş sahnelerini oynayan otomatik pilot."""

    AIM_W = 15.0          # yay sertliği (rad/sn): büyük = daha çevik el
    AIM_ZETA = 0.62       # sönüm: < 1 hafif taşma demek

    def __init__(self, run, crowd=0):
        self.run = run
        p = run.player
        self.cx, self.cy = p.x, p.y
        self.ang = random.uniform(0, math.tau)
        self.bonk, self.dash = 0.5, 1.6
        self.crowd = crowd
        self.target = None
        self.use = False
        self.keep_hp = True
        self.cur = [VIRTUAL_W / 2 + 90.0, VIRTUAL_H / 2 - 30.0]   # ekrandaki imleç
        self.vel = [0.0, 0.0]
        self.aim = tuple(self.cur)
        self.tgt = None           # nişan alınan yaratık
        self.react = 0.0          # yeni hedefe dönmeden önceki tepki süresi
        self.recheck = 0.0
        self.move = (0.0, 0.0)
        self.move_t = 0.0
        self.nt = random.uniform(0.0, 100.0)

    def spawn(self):
        run = self.run
        x, y = run.near_camera_point()
        w = run.waves.wave
        if run.biome == "hell":
            run.enemies.append(Enemy(None, x, y, run.wave_hp_mult(w), 1.0, wave=w,
                                     variant=hell_pick_kind(w), biome="hell"))
        else:
            kind = random.choice(("red", "red", "blue", "yellow", "tank", "sprinter", "brute"))
            run.enemies.append(Enemy(kind, x, y, run.wave_hp_mult(w), 1.0, wave=w))

    def _aim_update(self, dt, cands, p):
        run = self.run
        if self.tgt is not None and (not getattr(self.tgt, "alive", False) or self.tgt not in cands):
            self.tgt = None
            self.react = random.uniform(0.12, 0.30)
        self.react -= dt
        self.recheck -= dt
        if cands and self.react <= 0:
            by_d = sorted(cands, key=lambda e: (e.x - p.x) ** 2 + (e.y - p.y) ** 2)
            if self.tgt is None:
                # çoğu zaman en yakını, bazen ikinci en yakını (insan seçimi)
                self.tgt = by_d[0] if (len(by_d) < 2 or random.random() < 0.75) else by_d[1]
            elif self.recheck <= 0:
                self.recheck = random.uniform(0.45, 0.9)
                cur_d = math.hypot(self.tgt.x - p.x, self.tgt.y - p.y)
                near = by_d[0]
                if near is not self.tgt and math.hypot(near.x - p.x, near.y - p.y) < cur_d * 0.55:
                    self.tgt = None                      # daha yakın tehdit: tepkiyle dön
                    self.react = random.uniform(0.10, 0.22)
        # hedef noktası (ekranda)
        if self.tgt is not None:
            gx, gy = run.world_to_screen(self.tgt.x, self.tgt.y)
        else:
            # hedef yokken el, gidilen yöne doğru gevşekçe durur
            px, py = run.world_to_screen(p.x, p.y)
            gx = px + self.move[0] * 150 + 60
            gy = py + self.move[1] * 110 - 20
        self.nt += dt
        jx = (math.sin(self.nt * 2.3) + 0.6 * math.sin(self.nt * 5.7 + 1.1)) * 3.2
        jy = (math.sin(self.nt * 2.9 + 0.7) + 0.6 * math.sin(self.nt * 6.1 + 2.0)) * 3.2
        gx, gy = gx + jx, gy + jy
        w, z = self.AIM_W, self.AIM_ZETA
        h = 1.0 / 240.0
        n = max(1, int(math.ceil(dt / h)))
        h = dt / n
        for _ in range(n):           # yayı küçük adımlarla çöz (kararlı)
            ax = w * w * (gx - self.cur[0]) - 2 * z * w * self.vel[0]
            ay = w * w * (gy - self.cur[1]) - 2 * z * w * self.vel[1]
            self.vel[0] += ax * h
            self.vel[1] += ay * h
            self.cur[0] += self.vel[0] * h
            self.cur[1] += self.vel[1] * h
        self.cur[0] = clamp(self.cur[0], 20, VIRTUAL_W - 20)
        self.cur[1] = clamp(self.cur[1], 90, VIRTUAL_H - 20)
        self.aim = (self.cur[0], self.cur[1])
        if self.tgt is None:
            return False
        tx, ty = run.world_to_screen(self.tgt.x, self.tgt.y)
        return math.hypot(tx - self.cur[0], ty - self.cur[1]) < 140

    def step(self, dt):
        run = self.run
        p = run.player
        if self.keep_hp and p.alive:
            p.hp = p.max_hp
        run.pending_levelups = 0
        run.levelup_choices = []
        run.want_open_shop = False
        run.cheat_flag = ""             # tur dalga atlıyor; koşu denetimi sussun
        run.integrity_timer = 99.0
        while len(run.enemies) < self.crowd:
            self.spawn()
        self.ang += dt * 0.55
        if self.target is not None:
            tx, ty = self.target
        else:
            tx = self.cx + math.cos(self.ang) * 230
            ty = self.cy + math.sin(self.ang) * 140
        mx, my = tx - p.x, ty - p.y
        cands = [e for e in run.enemies if e.alive] + [b for b in run.bosses if b.alive]
        close = 0
        for e in cands:
            d = (e.x - p.x) ** 2 + (e.y - p.y) ** 2
            if d < 150 * 150:
                close += 1
                if d < 95 * 95 and self.target is None:
                    k = 1.0 / max(20.0, math.sqrt(d))
                    mx -= (e.x - p.x) * k * 160
                    my -= (e.y - p.y) * k * 160
        ln = math.hypot(mx, my)
        # klavye gibi: 8 yön, yön kısa aralıklarla güncellenir
        self.move_t -= dt
        if self.move_t <= 0 or (ln < 10 and self.target is not None):
            if ln < 10 and self.target is not None:
                self.move = (0.0, 0.0)
            else:
                a = math.atan2(my, mx)
                a = round(a / (math.pi / 4)) * (math.pi / 4)
                self.move = (round(math.cos(a), 3), round(math.sin(a), 3))
            self.move_t = random.uniform(0.10, 0.22)
        mvx, mvy = self.move
        on_target = self._aim_update(dt, cands, p)
        inp = {"left": 1.0 if mvx < -0.3 else 0.0, "right": 1.0 if mvx > 0.3 else 0.0,
               "up": 1.0 if mvy < -0.3 else 0.0, "down": 1.0 if mvy > 0.3 else 0.0,
               "mouse_down": bool(cands) and (on_target or close >= 3),
               "use_pressed": self.use,
               "aim_sx": self.cur[0], "aim_sy": self.cur[1]}
        self.bonk -= dt
        self.dash -= dt
        inp["bonk_pressed"] = close >= 4 and self.bonk <= 0
        if inp["bonk_pressed"]:
            self.bonk = random.uniform(1.3, 1.9)
        inp["dash_pressed"] = close >= 7 and self.dash <= 0 and self.target is None
        if inp["dash_pressed"]:
            self.dash = random.uniform(2.0, 2.8)
        run.update(dt, inp)


class _ForcedRarity:
    """Turda (gösteri) sandık / mağara kademesini sırayla sabitler."""

    def __init__(self, seq):
        self.seq = list(seq)

    def __enter__(self):
        g = globals()
        self.orig = g["roll_rarity"]
        seq = self.seq

        def fake(luck, rnd=random):
            return seq.pop(0) if seq else 0
        g["roll_rarity"] = fake
        return self

    def __exit__(self, *_a):
        globals()["roll_rarity"] = self.orig
        return False


class GameTour:
    """oyun turu - 2 dakikalık tanıtım + öğretici."""
    # (ad, süre, geçiş) - geçiş: "wipe" altın perde, "flash" beyaz çakma, ""
    # yok
    SCENES = (
        ("intro", 4.0, ""), ("hook", 6.0, "flash"), ("basics", 6.0, "wipe"),
        ("levelup", 10.0, ""), ("luck", 7.0, "wipe"), ("arsenal", 8.0, "flash"),
        ("books", 6.0, "wipe"), ("market", 4.0, "wipe"), ("boss", 6.0, "wipe"),
        ("chest", 6.0, ""), ("cave", 8.0, "wipe"), ("hell", 7.0, "wipe"),
        ("dragon", 5.5, "flash"), ("power", 6.0, "flash"), ("record", 4.5, "wipe"),
        ("worldlb", 6.0, "wipe"), ("mastery", 5.0, "wipe"), ("skins", 5.0, "wipe"),
        ("pets", 4.0, "wipe"), ("outro", 6.0, "flash"),
    )
    LENGTH = sum(d for _n, d, _w in SCENES)
    PLAY_SCENES = ("hook", "basics", "arsenal", "boss", "chest", "cave", "hell", "dragon",
                   "power")
    NAME = "Kanka"
    WEAPONS = ("tesla", "tornado", "beam", "pentagram")

    def __init__(self, real_app):
        self.sh = sh = App(shadow_of=real_app)
        sh.splash_t = 99.0
        self.t = 0.0
        self.scene_i = -1
        self.prev = -1.0
        self.clicks = []
        self.pilot = None
        self.music = [(0.0, "menu")]     # MP4 aracı için müzik geçişleri
        self.cut_times = []              # MP4 müziği: sahne kesmeleri
        self.hits = []                   # MP4 müziği: vurgu anları
        self.flags = set()
        self._bg = None
        self._setup_save()
        acc = 0.0
        for _nm, dur, cut in self.SCENES:
            if cut:
                self.cut_times.append((acc, cut))
            acc += dur
        # Filmdeki mağaza "açık" görünsün (gölge oyun; gerçek satın alma yok).
        sh.purchase.enabled = True
        sh.purchase.api_url = "tour"
        sh.purchase._catalog_at = time.time() + 10 ** 6
        sh.purchase.catalog = {str(CUSTOM_PET_PRODUCT_ID): {"price": 15900}}
        sh.build_menu_buttons()
        # Arena ve cehennem zeminleri ilk kez çizilirken ~0.5 sn sürüyor:
        # filmin ortasında takılmasın diye şimdi hazırlanır.
        for biome in ("arena", "hell"):
            try:
                floor_surface(biome)
            except Exception:
                pass
        world_surface()
        self._grad_bg()

    def _setup_save(self):
        """Vitrin kaydı: bir kısmı açık, bir kısmı kilitli, öğretici."""
        d = self.sh.save.data
        d["tainted"] = False
        d["taint_reasons"] = []
        d["board_banned"] = False
        d["ban_reasons"] = []
        d["books_owned"] = [b["key"] for b in BOOKS if not b.get("rare")][:12] + \
            ["r_echo", "r_killheal", "r_poison"]
        d["books_muted"] = []
        d["weapons_owned"] = ["axe", "book", "pentagram", "whip", "tornado", "tesla", "beam"]
        d["weapons_muted"] = []
        d["stats"] = {"runs": 9, "best_score": 21450, "total_kills": 940, "total_time": 3100.0,
                      "bosses": 2, "best_wave": 8, "total_shots": 6200, "total_lifesteal": 0.0,
                      "total_gold": 3800, "best_run_gold": 820, "best_run_dashes": 22,
                      "best_combo": 24, "best_run_kills": 160, "total_dashes": 160,
                      "total_bonks": 40, "total_bonk_hits": 150}
        d["achievements"] = {a["id"]: "24.12.2026" for a in ACHIEVEMENTS[:6]}
        d["skins_owned"] = ["default", "ranger", "crimson", "royal", "inferno"]
        d["equipped_skin"] = "inferno"
        d["cosmetics_owned"] = ["pet_dragon"]
        d.setdefault("equipped_cosmetics", {})
        d["equipped_cosmetics"] = {"hat": None, "eyewear": None, "cape": None, "pet": "pet_dragon"}
        d["gems"] = d["gems_earned"] = 2640
        d["gems_spent"] = 0
        d["mastery"] = {"m_dmg": 3, "m_hp": 2, "m_luck": 2, "m_wmute": 1}
        d["rewards"] = {"pid": self.sh.save.profile_id()}
        self.sh.selected_skin = "inferno"
        self.sh.diff = "normal"
        self.sh.online.world_scores = self._world_rows()

    def _world_rows(self):
        names = ("Kanka", "ZeyNo", "BonkUstası", "Ayaz_41", "KralMert", "Efe_TR", "Duru",
                 "Selin07", "Ozi", "Kuzey")
        rows = []
        score = 152340
        for i, nm in enumerate(names):
            rows.append({"name": nm, "score": score, "wave": max(12, 41 - i * 3),
                         "kills": 5200 - i * 430, "diff": "kabus" if i in (0, 3, 6) else "normal",
                         "run_time": 1500 - i * 80})
            score = int(score * (0.86 if i else 0.79))
        return rows

    def _scene(self):
        t = self.t
        acc = 0.0
        for i, (nm, dur, wipe) in enumerate(self.SCENES):
            if t < acc + dur or i == len(self.SCENES) - 1:
                return i, nm, t - acc, dur, wipe
            acc += dur

    def at(self, st, x):
        """Bu karede x saniyesi geçildi mi?"""
        return self.prev < x <= st

    def hit(self, st, x):
        """Tek seferlik vurgu: MP4 müziğine 'çarpma' olarak da yazılır."""
        if self.at(st, x):
            self.hits.append(self.t)
            return True
        return False

    def path(self, keys, st):
        if st <= keys[0][0]:
            return keys[0][1]
        for (t0, p0), (t1, p1) in zip(keys, keys[1:]):
            if t0 <= st <= t1:
                k = (st - t0) / max(1e-6, t1 - t0)
                k = k * k * (3 - 2 * k)
                return (p0[0] + (p1[0] - p0[0]) * k, p0[1] + (p1[1] - p0[1]) * k)
        return keys[-1][1]

    def click(self, pos):
        self.clicks.append((pos, self.t))
        sfx("click", 0.6, 0.0)

    def cap(self, text, sub, st, dur, y=600, col=(255, 214, 120), x0=0):
        """Alt yazı şeridi: soldan kayarak girer, sağa doğru söner."""
        if st < 0 or st > dur:
            return
        c = self.sh.display.canvas
        k = min(ease_out_cubic(st / 0.4), ease_out_cubic((dur - st) / 0.3))
        ts, ss = 38, 21

        def width():
            return max(text_width(text, ts, True), text_width(sub, ss, True) if sub else 0) + 90
        while ts > 20 and width() > VIRTUAL_W - 30:
            ts -= 2
            ss = max(13, ss - 1)
        tw = width()
        x = x0 - tw + (tw + 50) * k
        sub_y = y + 9 + ts + 11
        h = (sub_y + ss + 15 - y) if sub else ts + 28
        bar = pygame.Surface((int(tw), h), pygame.SRCALPHA)
        bar.fill((23, 17, 18, 222))
        c.blit(bar, (int(x), y))
        pygame.draw.rect(c, col, pygame.Rect(int(x + tw - 10), y, 10, h))
        draw_text(c, text, (int(x) + 30, y + 9), ts, col, bold=True)
        if sub:
            draw_text(c, sub, (int(x) + 32, sub_y), ss, (236, 232, 244), bold=True)

    def stamp(self, text, st, col, y=150, life=2.2):
        draw_stamp(self.sh.display.canvas, text, st, col, y, life=life)

    def cursor(self, pos, kind="ui"):
        draw_cursor(self.sh.display.canvas, pos, kind, self.sh.t, hot=(kind == "aim"))

    def update(self, dt):
        dt = min(dt, 1 / 20.0)
        self.t = min(self.LENGTH, self.t + dt)
        self.sh.t += dt
        i, name, st, dur, cut = self._scene()
        first = i != self.scene_i
        if first:
            self.scene_i = i
            self.prev = -1.0
        getattr(self, "_s_" + name)(st, dt, first)
        c = self.sh.display.canvas
        for (pos, t0) in self.clicks:
            k = (self.t - t0) / 0.45
            if 0 <= k <= 1:
                ring_aa(c, pos[0], pos[1], 8 + 34 * k, (255, 236, 170), max(1, int(5 * (1 - k))))
        if name in self.PLAY_SCENES:
            logo = brand_scaled("logo", h=54)
            if logo is not None:
                c.blit(logo, (VIRTUAL_W - logo.get_width() - 16, VIRTUAL_H - logo.get_height() - 12))
        if cut == "wipe" and st < 0.32 and self.t > 0.5:
            k = st / 0.32
            x0 = -260 + (VIRTUAL_W + 520) * k
            pygame.draw.polygon(c, (236, 186, 92), [(x0, 0), (x0 + 300, 0), (x0 + 80, VIRTUAL_H),
                                                   (x0 - 220, VIRTUAL_H)])
            pygame.draw.polygon(c, (255, 242, 205), [(x0 + 230, 0), (x0 + 300, 0),
                                                    (x0 + 80, VIRTUAL_H), (x0 + 10, VIRTUAL_H)])
        elif cut == "flash" and st < 0.22 and self.t > 0.5:
            fl = pygame.Surface((VIRTUAL_W, VIRTUAL_H))
            fl.fill((255, 250, 235))
            fl.set_alpha(int(235 * (1.0 - st / 0.22) ** 1.6))
            c.blit(fl, (0, 0))
        self.prev = st

    def render(self):
        return self.sh.display.canvas

    def close(self):
        """Tur kapanırken gölge oyunun çaldırdığı savaş müziğini geri al."""
        try:
            audio.set_music("menu")
        except Exception:
            pass

    # yardımcılar
    def _fresh_run(self, wave, weapons, level, crowd, books=None, hell=False):
        """Sahne için yeni bir koşu: silahlar, kitaplar (seviye, kademe), dalga."""
        sh = self.sh
        sh.start_run()
        run = sh.run
        # filmde hep taş arena; başlangıç seçimi, görev ve sunak yok
        run.set_map_theme("stone")
        run.merchant = None
        run.quests = []
        run.ach = None                  # filmde başarım bildirimi çıkmasın
        p = run.player
        p.no_stats = True
        # Filmde kahraman hasar almaz: ekranda "ölmek üzere" can çubuğu
        # olmasın.
        p.take_damage = lambda *a, **k: 0
        p.weapons = dict(weapons)
        for k in p.weapons:
            p.weapon_timers[k] = 0.0
        for bk, (lv, tier) in (books or {}).items():
            for _ in range(lv):
                p.take_book(bk, tier)
        p.level = level
        if hell:
            run.waves.wave = HELL_PORTAL_WAVE
            run.enter_hell()
        if wave > 1:
            run.waves._begin_wave(wave, run.score)
        run.waves.announce_timer = 0.0
        self.pilot = _TourPilot(run, crowd=crowd)
        sh.state = STATE_PLAY
        if not self.music or self.music[-1][1] != "battle":
            self.music.append((self.t, "battle"))
        return run

    def _spawn_ring(self, run, n, rmin=150, rmax=380):
        """Yaratıkları oyuncunun çevresine dizer: aksiyon anında başlasın."""
        p = run.player
        w = run.waves.wave
        for _ in range(n):
            a = random.uniform(0, math.tau)
            d = random.uniform(rmin, rmax)
            x = clamp(p.x + math.cos(a) * d, ARENA_RECT.left + 40, ARENA_RECT.right - 40)
            y = clamp(p.y + math.sin(a) * d * 0.75, ARENA_RECT.top + 40, ARENA_RECT.bottom - 40)
            if run.biome == "hell":
                run.enemies.append(Enemy(None, x, y, run.wave_hp_mult(w), 1.0, wave=w,
                                         variant=hell_pick_kind(w), biome="hell"))
            else:
                kind = random.choice(("red", "red", "blue", "yellow", "tank", "sprinter", "brute"))
                run.enemies.append(Enemy(kind, x, y, run.wave_hp_mult(w), 1.0, wave=w))

    def _big_bonk(self, run):
        p = run.player
        p.bonk_cd = 0.0
        try:
            run.do_bonk()
        except Exception:
            pass
        run.fx.shake(12, 0.35)

    def _play(self, dt, step=True):
        sh = self.sh
        if step and self.pilot is not None and sh.state == STATE_PLAY:
            self.pilot.step(dt)
        if sh.state == STATE_PLAY and sh.run.game_over:
            sh.run.run_is_clean = lambda: True
            sh.update_play(0.0, _NoKeys(), self.pilot.aim, False, False, False)
            return
        sh._draw_run_frame(sh.display.canvas, aim_pos=self.pilot.aim,
                           offset=sh.run.fx.get_shake_offset())
        self.cursor(self.pilot.aim, "aim")

    def _grad_bg(self):
        if self._bg is None:
            self._bg = pygame.Surface((VIRTUAL_W, VIRTUAL_H)).convert()
            for y in range(VIRTUAL_H):
                pygame.draw.line(self._bg, mix_col((54, 30, 80), (10, 6, 20), y / VIRTUAL_H),
                                 (0, y), (VIRTUAL_W, y))
        return self._bg

    def _rays(self, c, cx, cy, st, alpha=30):
        lay = pygame.Surface((VIRTUAL_W, VIRTUAL_H), pygame.SRCALPHA)
        for i in range(22):
            a = st * 0.22 + i * math.tau / 22
            pygame.draw.polygon(lay, (236, 186, 92, alpha),
                                [(cx, cy), (cx + math.cos(a - .05) * 1000, cy + math.sin(a - .05) * 1000),
                                 (cx + math.cos(a + .05) * 1000, cy + math.sin(a + .05) * 1000)])
        c.blit(lay, (0, 0))

    # sahneler
    def _s_intro(self, st, dt, first):
        c = self.sh.display.canvas
        c.blit(self._grad_bg(), (0, 0))
        cx, cy = VIRTUAL_W / 2, VIRTUAL_H / 2 - 30
        self._rays(c, cx, cy, st)
        add_glow(c, cx, cy, 480, (210, 150, 60), 0.30)
        if st < 1.4:
            badge = brand_scaled("badge", h=260)
            if badge is not None:
                k = ease_out_cubic(st / 0.55)
                s_ = 0.3 + 0.7 * k + 0.08 * math.sin(min(1.0, st / 0.55) * math.pi)
                img = pygame.transform.smoothscale(badge, (int(260 * s_), int(260 * s_)))
                c.blit(img, (cx - img.get_width() / 2, cy - img.get_height() / 2))
            if st > 0.5:
                q = min(1.0, (st - 0.5) / 0.6)
                ring_aa(c, cx, cy, 140 + 500 * q, (255, 230, 170), max(1, int(12 * (1 - q))))
            if self.hit(st, 0.5):
                sfx("bonk", 1.0, 0.0)
        else:
            logo = brand_scaled("logo", w=880)
            if logo is not None:
                k = ease_out_cubic((st - 1.4) / 0.5)
                s_ = 0.8 + 0.2 * k
                img = pygame.transform.smoothscale(logo, (int(logo.get_width() * s_),
                                                          int(logo.get_height() * s_)))
                img.set_alpha(int(255 * k))
                c.blit(img, (cx - img.get_width() / 2, cy - img.get_height() / 2))
            if st > 2.2:
                a = int(255 * min(1.0, (st - 2.2) / 0.4))
                draw_text(c, _tc("Oyunu 2 dakikada öğren!", "Learn the game in 2 minutes!",
                                 "¡Aprende el juego en 2 minutos!", "Lerne das Spiel in 2 Minuten!",
                                 "Изучи игру за 2 минуты!"),
                          (cx, cy + 210), 32, (255, 236, 182), bold=True, center=True, alpha=a)

