def snow_lane_scale(y):
    return 0.62 + 0.48 * clamp((y - SNOW_LANE_TOP) / float(SNOW_LANE_BOT - SNOW_LANE_TOP), 0.0, 1.0)


class _SnowTarget:
    def __init__(self, kind, y, speed, hp, value, fly, rnd):
        self.kind, self.hp, self.value, self.fly = kind, hp, value, fly
        self.dir = rnd.choice((-1, 1))
        self.y0 = y
        self.x = -60 if self.dir > 0 else VIRTUAL_W + 60
        self.y = y
        self.speed = speed
        self.t = rnd.uniform(0, 5)
        self.alive = True
        self.hit_flash = 0.0
        try:
            self.e = Enemy(kind if kind != "goblin" else "goblin", self.x, y, 1.0, 1.0, wave=1)
        except Exception:
            self.e = Enemy("red", self.x, y, 1.0, 1.0, wave=1)
        self.base_r = self.e.radius
        self.e.spawn_t = 5.0

    def update(self, dt):
        self.t += dt
        self.x += self.dir * self.speed * dt
        self.y = self.y0 + (math.sin(self.t * 3.0) * 26 if self.fly else 0.0)
        if self.hit_flash > 0:
            self.hit_flash -= dt
        if (self.dir > 0 and self.x > VIRTUAL_W + 80) or (self.dir < 0 and self.x < -80):
            self.alive = False

    def radius(self):
        return self.base_r * snow_lane_scale(self.y0) * 1.25

    def draw(self, surf, t):
        e = self.e
        e.x, e.y = self.x, self.y - (40 if self.fly else 0)
        e.radius = self.radius()
        e.face_x, e.face_y = float(self.dir), 0.25
        e.walk = self.t * (8.0 if not self.fly else 5.0)
        e.hit_flash = 0.08 if self.hit_flash > 0 else 0.0
        if self.fly:
            surf.blit(shadow_sprite(int(e.radius * 2)), (int(self.x - e.radius), int(self.y + e.radius * 0.6)))
        if self.kind == "goblin":
            add_glow(surf, e.x, e.y, e.radius * 2.4, GOLD, 0.35 + 0.15 * math.sin(t * 8))
        e.draw(surf, t)


class _SnowBall:
    def __init__(self, x0, y0, x1, y1):
        self.x0, self.y0, self.x1, self.y1 = x0, y0, x1, y1
        d = math.hypot(x1 - x0, y1 - y0)
        self.dur = 0.20 + d / 1700.0
        self.h = 40 + d * 0.22
        self.t = 0.0
        self.done = False

    def pos(self):
        k = clamp(self.t / self.dur, 0.0, 1.0)
        x = self.x0 + (self.x1 - self.x0) * k
        y = self.y0 + (self.y1 - self.y0) * k - math.sin(k * math.pi) * self.h
        return x, y, k


# ---- iletişim / destek penceresi ----
# Hesap ekranının sağ üstündeki "İLETİŞİM" düğmesiyle açılır.
CONTACT_MIN = 10
CONTACT_MAX = 1500


def _wrap_chars(text, size, max_w):
    """Paragrafları koruyarak sarar; boşluksuz çok uzun sözcüğü harf harf böler."""
    out = []
    for para in str(text).split("\n"):
        line = ""
        for word in para.split(" "):
            cand = (line + " " + word) if line else word
            if text_width(cand, size) <= max_w:
                line = cand
                continue
            if line:
                out.append(line)
            line = ""
            while text_width(word, size) > max_w:
                k = len(word)
                while k > 1 and text_width(word[:k], size) > max_w:
                    k -= 1
                out.append(word[:k])
                word = word[k:]
            line = word
        out.append(line)
    return out


class ContactForm:
    KINDS = (("sorun", "contact.k_bug", (236, 104, 100)),
             ("oneri", "contact.k_idea", (110, 210, 140)),
             ("diger", "contact.k_other", (120, 160, 240)))

    def __init__(self, app):
        self.app = app
        acc = app.account
        a = acc.account or {}
        self.kind = "sorun"
        self.email = str(a.get("email") or "") if acc.logged_in() else ""
        self.msg = ""
        self.focus = "msg"
        self.status = ""
        self.status_ok = False
        self.busy = False
        self.done_t = None
        self.t = 0.0
        self.caret = 0.0
        self.closed = False

    # ---- klavye ----
    def _paste(self):
        txt = ""
        try:
            if not pygame.scrap.get_init():
                pygame.scrap.init()
            txt = pygame.scrap.get_text() or ""
        except Exception:
            try:
                raw = pygame.scrap.get("text/plain;charset=utf-8") or pygame.scrap.get(pygame.SCRAP_TEXT)
                if raw:
                    txt = raw.decode("utf-8", "ignore").replace("\x00", "")
            except Exception:
                txt = ""
        return txt.replace("\r\n", "\n").replace("\r", "\n")

    def _add(self, txt):
        if self.focus == "email":
            txt = "".join(ch for ch in txt if not ch.isspace())
            self.email = (self.email + txt)[:120]
        else:
            txt = "".join(ch for ch in txt if ch == "\n" or ch.isprintable())
            self.msg = (self.msg + txt)[:CONTACT_MAX]

    def handle_key(self, event):
        if self.busy or self.done_t is not None:
            return
        mods = pygame.key.get_mods()
        ctrl = bool(mods & (pygame.KMOD_CTRL | pygame.KMOD_META))
        if event.key == pygame.K_TAB:
            self.focus = "email" if self.focus == "msg" else "msg"
        elif event.key == pygame.K_BACKSPACE:
            if self.focus == "email":
                self.email = self.email[:-1]
            elif ctrl:
                self.msg = self.msg.rstrip()
                cut = max(self.msg.rfind(" "), self.msg.rfind("\n"))
                self.msg = self.msg[:cut + 1] if cut >= 0 else ""
            else:
                self.msg = self.msg[:-1]
        elif event.key in (pygame.K_RETURN, pygame.K_KP_ENTER):
            if self.focus == "msg" and not ctrl:
                if self.msg.count("\n") < 30:
                    self._add("\n")
            else:
                self.submit()
        elif event.key == pygame.K_v and ctrl:
            self._add(self._paste())
        else:
            ch = event.unicode
            if ch and ch.isprintable() and not ctrl:
                self._add(ch)
        self.status = "" if not self.busy else self.status
        self.caret = 0.0

    # ---- gönderim ----
    def submit(self):
        if self.busy or self.done_t is not None:
            return
        msg = self.msg.strip()
        if len(msg) < CONTACT_MIN:
            self.status, self.status_ok = L("contact.short", CONTACT_MIN), False
            return
        em = self.email.strip()
        if em and not email_ok(em):
            self.status, self.status_ok = L("ui.acc_bad_email"), False
            self.focus = "email"
            return
        acc = self.app.account
        if not getattr(acc, "base_url", ""):
            self.status, self.status_ok = L("contact.no_server"), False
            return
        payload = {"kind": self.kind, "message": msg, "email": em.lower(), "version": GAME_VERSION}
        if acc.logged_in() and acc.token:
            payload["token"] = acc.token
            payload["device"] = device_id()
            payload["device_legacy"] = device_id_legacy()
        self.busy = True
        self.status, self.status_ok = L("contact.sending"), True
        sfx("click", 0.7, 0.0)

        async def worker():
            try:
                res = await acc._post("/contact", payload, timeout=40)
                if res.get("success"):
                    self.status, self.status_ok = L("contact.sent"), True
                    self.done_t = 0.0
                    sfx("buy", 0.9, 0.0)
                else:
                    self.status, self.status_ok = str(res.get("error") or L("ui.acc_neterr")), False
            except Exception as e:
                self.status, self.status_ok = acc._err_text(e), False
            finally:
                self.busy = False
        spawn(worker)

    def close(self):
        self.closed = True

    # ---- çizim ----
    def update(self, canvas, dt, mouse_pos, clicked):
        """Pencereyi çizer; kapanması gerekiyorsa True döner."""
        self.t += dt
        self.caret += dt
        if self.done_t is not None:
            self.done_t += dt
            if self.done_t > 2.2:
                return True
        if self.closed:
            return True
        k = ease_out_cubic(clamp(self.t / 0.22, 0.0, 1.0))
        dim = pygame.Surface((VIRTUAL_W, VIRTUAL_H), pygame.SRCALPHA)
        dim.fill((4, 5, 12, int(190 * k)))
        canvas.blit(dim, (0, 0))
        R = pygame.Rect(0, 0, 720, 560)
        R.center = (VIRTUAL_W / 2, VIRTUAL_H / 2 + int((1 - k) * 30))
        add_glow(canvas, R.centerx, R.y + 30, 360, (90, 140, 255), 0.14)
        panel(canvas, R, bg=(39, 28, 29), edge=(96, 140, 230), alpha=250, radius=18, edge_w=2)
        cx = R.centerx
        draw_icon(canvas, R.x + 40, R.y + 34, "mail", GOLD, 14)
        draw_text(canvas, L("contact.title"), (R.x + 64, R.y + 18), 28, GOLD, bold=True)
        for i, ln in enumerate(wrap_text(L("contact.sub"), 13, R.w - 90)[:2]):
            draw_text(canvas, ln, (R.x + 40, R.y + 58 + i * 17), 13, TEXT_DIM, shadow=False)
        # kapat (X)
        xb = pygame.Rect(R.right - 48, R.y + 14, 34, 34)
        xh = xb.collidepoint(mouse_pos)
        pygame.draw.rect(canvas, (60, 40, 50) if xh else (55, 40, 41), xb, border_radius=8)
        pygame.draw.line(canvas, TEXT, (xb.x + 10, xb.y + 10), (xb.right - 10, xb.bottom - 10), 2)
        pygame.draw.line(canvas, TEXT, (xb.right - 10, xb.y + 10), (xb.x + 10, xb.bottom - 10), 2)
        if clicked and xh:
            sfx("click", 0.5, 0.0)
            return True
        # tür seçimi
        y = R.y + 104
        draw_text(canvas, L("contact.kind"), (R.x + 40, y), 11, TEXT_DIM, bold=True, shadow=False)
        x = R.x + 40
        for key, lab, col in self.KINDS:
            txt = L(lab)
            w = text_width(txt, 14, True) + 34
            chip = pygame.Rect(x, y + 18, w, 32)
            sel = self.kind == key
            hov = chip.collidepoint(mouse_pos)
            pygame.draw.rect(canvas, scale_col(col, 0.42) if sel else ((64, 46, 48) if hov else (48, 35, 36)),
                             chip, border_radius=16)
            ink_frame(canvas, chip, col if sel or hov else (120, 87, 90), 16, 2)
            draw_text(canvas, txt, chip.center, 14, WHITE if sel else (200, 206, 226), bold=True, center=True,
                      shadow=False)
            if clicked and hov and not self.busy:
                self.kind = key
                sfx("click", 0.5, 0.0)
            x += w + 10
        # e-posta
        y += 64
        er = pygame.Rect(R.x + 40, y, R.w - 80, 46)
        self._box(canvas, er, L("contact.email"), "email", mouse_pos, clicked)
        em = self.email or ""
        if not em and self.focus != "email":
            draw_text(canvas, L("contact.email_hint"), (er.x + 14, er.y + 22), 13, (92, 98, 124), shadow=False)
        shown = em
        while shown and text_width(shown, 15) > er.w - 28:
            shown = shown[1:]
        draw_text(canvas, shown, (er.x + 14, er.y + 22), 15, TEXT, shadow=False)
        if self.focus == "email" and (self.caret % 1.0) < 0.55:
            ccx = er.x + 14 + text_width(shown, 15)
            pygame.draw.line(canvas, CYAN, (ccx + 1, er.y + 22), (ccx + 1, er.y + 39), 2)
        # mesaj
        y += 60
        mr = pygame.Rect(R.x + 40, y, R.w - 80, 214)
        self._box(canvas, mr, L("contact.msg"), "msg", mouse_pos, clicked)
        lines = _wrap_chars(self.msg, 15, mr.w - 30)
        max_lines = (mr.h - 34) // 19
        view = lines[-max_lines:]
        if not self.msg and self.focus != "msg":
            draw_text(canvas, L("contact.msg_hint"), (mr.x + 14, mr.y + 24), 13, (92, 98, 124), shadow=False)
        for i, ln in enumerate(view):
            draw_text(canvas, ln, (mr.x + 14, mr.y + 24 + i * 19), 15, TEXT, shadow=False)
        if self.focus == "msg" and (self.caret % 1.0) < 0.55:
            last = view[-1] if view else ""
            ccx = mr.x + 14 + text_width(last, 15)
            ccy = mr.y + 24 + (len(view) - 1 if view else 0) * 19
            pygame.draw.line(canvas, CYAN, (ccx + 1, ccy), (ccx + 1, ccy + 17), 2)
        n = len(self.msg)
        draw_text(canvas, "%d / %d" % (n, CONTACT_MAX), (mr.right - 12, mr.bottom - 18), 11,
                  (255, 150, 140) if n >= CONTACT_MAX else TEXT_DIM, right=True, shadow=False)
        # alt bilgi + durum
        y = mr.bottom + 10
        draw_text(canvas, L("contact.note", GAME_VERSION), (R.x + 40, y), 11, (130, 138, 168), shadow=False)
        if self.status:
            draw_text(canvas, self.status, (cx, R.bottom - 82), 13,
                      GREEN if self.status_ok else (255, 150, 140), bold=True, center=True, shadow=False)
        # düğmeler
        b1 = Button((cx - 230, R.bottom - 62, 220, 46), L("contact.send") if not self.busy else L("ui.acc_working"),
                    self.submit, color=(54, 120, 84), hover_color=(74, 160, 110),
                    enabled=not self.busy and self.done_t is None, text_size=20)
        b2 = Button((cx + 10, R.bottom - 62, 220, 46), L("ui.back"), self.close, text_size=20)
        for b in (b1, b2):
            b.update(mouse_pos, dt)
            b.draw(canvas)
            if clicked:
                b.click(mouse_pos)
        return self.closed

    def _box(self, canvas, rect, label, key, mouse_pos, clicked):
        focused = self.focus == key
        hov = rect.collidepoint(mouse_pos)
        panel(canvas, rect, bg=(57, 41, 43) if (focused or hov) else (41, 30, 31),
              edge=CYAN if focused else PANEL_EDGE, alpha=242, radius=9, edge_w=2)
        draw_text(canvas, label, (rect.x + 14, rect.y + 6), 10, TEXT_DIM, shadow=False)
        # Gizli kutu tek satırlıdır: satır sonları orada boşluk görünür
        # (uzunluk aynı kalır, silme doğru harfe düşer).
        if clicked and hov and not self.busy:
            self.focus = key
            sfx("click", 0.4, 0.0)
        val = self.email if key == "email" else self.msg.replace("\n", " ")
        touch_text_field(rect, "c_" + key, val, focused=(self.focus == key), label=label)


# video reklam: mağazadaki ödüllü reklam 90 saniyelik tanıtım filmini oynatır:
#     EvolveArena_reklam.mp4 (görüntü, 960x540 @30)
#     EvolveArena_reklam.ogg (ses)
AD_VIDEO_FILE = "EvolveArena_reklam.mp4"
AD_AUDIO_FILE = "EvolveArena_reklam.ogg"


def _ad_asset(name, want_dir=False):
    dirs = []
    if getattr(sys, "frozen", False):
        dirs.append(os.path.dirname(os.path.abspath(sys.executable)))
    mp = getattr(sys, "_MEIPASS", None)
    if mp:
        dirs.append(mp)
    try:
        dirs.append(os.path.dirname(os.path.abspath(__file__)))
    except Exception:
        pass
    dirs.append(os.getcwd())
    for d in list(dirs):
        dirs.append(os.path.join(d, "assets"))
    for d in dirs:
        pth = os.path.join(d, name)
        if os.path.isdir(pth) if want_dir else os.path.isfile(pth):
            return pth
    return None


class VideoAd:
    """MP4'ü kare kare çözüp ses dosyasıyla eş zamanlı oynatır."""
    W, H = 960, 540

    def __init__(self, path, audio_path=None, music_vol=0.5):
        self.path = path
        self.fps = 30.0
        self.LENGTH = 90.0
        self.backend = None
        self.cap = None
        self.proc = None
        self.av_iter = None
        self.idx = -1
        self.t = 0.0
        self.surf = pygame.Surface((self.W, self.H)).convert()
        self.surf.fill((0, 0, 0))
        self.audio_ok = False
        self._open()
        if self.backend is None:
            raise RuntimeError("video çözücü yok (opencv-python / av / ffmpeg)")
        if audio_path:
            try:
                pygame.mixer.music.load(audio_path)
                vol = clamp(float(music_vol) * 1.5 + 0.15, 0.2, 1.0)
                pygame.mixer.music.set_volume(vol)
                pygame.mixer.music.play()
                self.audio_ok = True
            except Exception:
                self.audio_ok = False
        try:
            audio.set_music(None)          # oyunun kendi müziği reklam boyunca susar
        except Exception:
            pass

    def _open(self):
        try:
            import cv2                     # noqa: F401
            cap = cv2.VideoCapture(self.path)
            if cap is not None and cap.isOpened():
                self.cv2 = cv2
                self.cap = cap
                self.backend = "cv2"
                self.fps = float(cap.get(cv2.CAP_PROP_FPS) or 30.0) or 30.0
                n = float(cap.get(cv2.CAP_PROP_FRAME_COUNT) or 0)
                if n > 0:
                    self.LENGTH = n / self.fps
                return
        except Exception:
            pass
        try:
            import av                      # noqa: F401
            cont = av.open(self.path)
            st = cont.streams.video[0]
            self.av = cont
            self.av_iter = cont.decode(st)
            self.fps = float(st.average_rate or 30)
            if st.duration and st.time_base:
                self.LENGTH = float(st.duration * st.time_base)
            self.backend = "av"
            return
        except Exception:
            pass
        try:
            import shutil
            import subprocess
            exe = shutil.which("ffmpeg")
            if not exe:
                for nm in ("ffmpeg.exe", "ffmpeg"):
                    cand = _ad_asset(nm)
                    if cand:
                        exe = cand
                        break
            if exe:
                flags = 0x08000000 if sys.platform.startswith("win") else 0   # CREATE_NO_WINDOW
                self.proc = subprocess.Popen(
                    [exe, "-loglevel", "error", "-i", self.path, "-vf", "scale=%d:%d" % (self.W, self.H),
                     "-f", "rawvideo", "-pix_fmt", "rgb24", "-"],
                    stdout=subprocess.PIPE, stderr=subprocess.DEVNULL, creationflags=flags)
                self.backend = "ffmpeg"
        except Exception:
            self.proc = None

    def _read_one(self):
        try:
            if self.backend == "cv2":
                ok, frame = self.cap.read()
                if not ok:
                    return None
                if frame.shape[1] != self.W or frame.shape[0] != self.H:
                    frame = self.cv2.resize(frame, (self.W, self.H))
                rgb = self.cv2.cvtColor(frame, self.cv2.COLOR_BGR2RGB)
                return pygame.image.frombuffer(rgb.tobytes(), (self.W, self.H), "RGB")
            if self.backend == "av":
                fr = next(self.av_iter)
                img = fr.to_ndarray(format="rgb24", width=self.W, height=self.H)
                return pygame.image.frombuffer(img.tobytes(), (self.W, self.H), "RGB")
            if self.backend == "ffmpeg":
                n = self.W * self.H * 3
                buf = self.proc.stdout.read(n)
                if len(buf) < n:
                    return None
                return pygame.image.frombuffer(buf, (self.W, self.H), "RGB")
        except Exception:
            return None
        return None

    def _skip_one(self):
        if self.backend == "cv2":
            try:
                return bool(self.cap.grab())
            except Exception:
                return False
        return self._read_one() is not None

    def update(self, dt):
        self.t += dt
        clock = self.t
        if self.audio_ok:
            try:
                ms = pygame.mixer.music.get_pos()
                if ms >= 0:
                    clock = ms / 1000.0
            except Exception:
                pass
        want = int(clock * self.fps)
        # geride kaldıysa kareleri çözmeden atla (son kareyi çöz)
        while self.idx < want - 1:
            if not self._skip_one():
                return
            self.idx += 1
        if self.idx < want:
            fr = self._read_one()
            if fr is not None:
                self.surf.blit(fr, (0, 0))
                self.idx += 1

    def render(self):
        return self.surf

    def close(self):
        try:
            if self.cap is not None:
                self.cap.release()
        except Exception:
            pass
        try:
            if self.proc is not None:
                self.proc.kill()
        except Exception:
            pass
        try:
            if self.audio_ok:
                pygame.mixer.music.stop()
                pygame.mixer.music.unload()
        except Exception:
            pass
        try:
            audio.set_music("menu")
        except Exception:
            pass


class WebVideoAd:
    """Tarayıcı / telefon: tanıtım filmi sayfadaki bir <video> öğesinde oynar (tuvalin üstünde"""
    W, H = 960, 540

    def __init__(self, url):
        self.url = url
        self.LENGTH = 90.0
        self.t = 0.0
        self.muted = False
        self.failed = False
        self.surf = pygame.Surface((self.W, self.H)).convert()
        self.surf.fill((0, 0, 0))
        if not web_call("adStart", url, default=0):
            raise RuntimeError("video açılamadı")
        try:
            audio.set_music(None)
        except Exception:
            pass

    def place(self, rect):
        web_call("adSetRect", int(rect.x), int(rect.y), int(rect.w), int(rect.h))

    def update(self, dt):
        raw = web_call("adTime", default=-1)
        try:
            d = json.loads(str(raw)) if raw not in (-1, None, "") else None
        except Exception:
            d = None
        if d:
            self.t = float(d.get("t") or 0)
            if d.get("d") and float(d["d"]) > 5:
                self.LENGTH = min(120.0, float(d["d"]))
            self.muted = bool(d.get("m"))
            self.failed = bool(d.get("err"))

    def render(self):
        return self.surf          # görüntüyü üstteki <video> gösteriyor

    def close(self):
        web_call("adStop")
        try:
            audio.set_music("menu")
        except Exception:
            pass


def make_house_ad(app):
    """Mağaza reklamı: önce 90 sn'lik video, olmazsa oyun turu."""
    if IS_WEB:
        try:
            return WebVideoAd(WEB_AD_URL)
        except Exception as e:
            print("Web reklam filmi açılamadı:", e)
    vp = _ad_asset(AD_VIDEO_FILE)
    if vp:
        try:
            vol = (app.save.data.get("settings") or {}).get("music_vol", 0.5)
            return VideoAd(vp, _ad_asset(AD_AUDIO_FILE), vol)
        except Exception as e:
            print("Video reklam açılamadı, oyun turu oynatılıyor:", e)
    return GameTour(app)


class SnowEvent:
    """Kartopu Savaşı mini oyunu (durum makinesi + çizim)."""

    def __init__(self, app):
        self.app = app
        self.rnd = random.Random()
        self.stage = "intro"          # intro | wait | count | play | claim | result
        self.err = ""
        self.ticket = None
        self.reset()
        self._bg = None

    def reset(self):
        self.targets, self.balls, self.fx = [], [], []
        self.hits = 0
        self.gems = 0
        self.throws = 0
        self.time_left = SNOW_TIME
        self.spawn_cd = 0.4
        self.throw_cd = 0.0
        self.px = VIRTUAL_W / 2
        self.combo = 0
        self.combo_t = 0.0
        self.count_t = 3.0
        self.result_amount = None
        self.t = 0.0

    # ---- haklar ----
    def plays_left(self):
        return self.app.rewards.snow_left()

    # ---- akış ----
    def start(self):
        if self.plays_left() <= 0:
            self.err = L("snow.no_plays")
            return
        self.err = ""
        self.reset()
        self.stage = "wait"

        def done(ok, err):
            if ok:
                self.stage = "count"
                self.count_t = 3.0
                sfx("click", 0.8, 0.0)
            else:
                self.stage = "intro"
                self.err = err or L("ui.acc_neterr")
        self.app.rewards.begin_snow(done)

    def finish(self):
        self.stage = "claim"
        reward = min(SNOW_MAX_GEMS, self.gems)

        def done(amount, err):
            self.result_amount = int(amount)
            self.err = err or ""
            self.stage = "result"
            if amount > 0:
                sfx("levelup", 0.9, 0.0)
        self.app.rewards.finish_snow(reward, done)

    # ---- oyun ----
    def _spawn(self):
        names = [k[0] for k in SNOW_KINDS]
        weights = [k[1] for k in SNOW_KINDS]
        kind = self.rnd.choices(names, weights=weights, k=1)[0]
        _k, _w, sp, hp, val, fly = [k for k in SNOW_KINDS if k[0] == kind][0]
        y = self.rnd.uniform(SNOW_LANE_TOP + 10, SNOW_LANE_BOT - 10)
        sc = snow_lane_scale(y)
        speed = self.rnd.uniform(*sp) * (0.75 + 0.35 * sc) * (1.0 + 0.35 * (1 - self.time_left / SNOW_TIME))
        self.targets.append(_SnowTarget(kind, y, speed, hp, val, fly, self.rnd))

    def throw(self, mx, my):
        if self.throw_cd > 0 or self.stage != "play":
            return
        self.throw_cd = SNOW_THROW_CD
        my = clamp(my, SNOW_LANE_TOP - 60, SNOW_LANE_BOT + 40)
        self.balls.append(_SnowBall(self.px + 18, 618, mx, my))
        self.throws += 1
        sfx("shoot_a", 0.4, 0.05)

    def _land(self, b):
        hit_any = False
        for tg in sorted(self.targets, key=lambda q: -q.y):
            if not tg.alive:
                continue
            ty_ = tg.y - (40 if tg.fly else 0)
            if math.hypot(tg.x - b.x1, ty_ - b.y1) < SNOW_HIT_R * snow_lane_scale(tg.y0) + tg.radius() * 0.5:
                tg.hp -= 1
                tg.hit_flash = 0.15
                hit_any = True
                if tg.hp <= 0:
                    tg.alive = False
                    self.hits += 1
                    self.combo += 1
                    self.combo_t = 1.4
                    self.gems += tg.value
                    self.fx.append(["pop", tg.x, ty_, 0.0, tg.value])
                    sfx("coin", 0.8, 0.0)
                else:
                    sfx("hit", 0.6, 0.0)
                break
        self.fx.append(["splat", b.x1, b.y1, 0.0, 0])
        if not hit_any:
            self.combo = 0

    def update(self, dt, mouse_pos, clicked, keys):
        self.t += dt
        if self.stage == "count":
            self.count_t -= dt
            if self.count_t <= 0:
                self.stage = "play"
                sfx("warn", 0.7, 0.0)
        if self.stage == "play":
            self.time_left -= dt
            if keys[pygame.K_a] or keys[pygame.K_LEFT]:
                self.px -= 420 * dt
            if keys[pygame.K_d] or keys[pygame.K_RIGHT]:
                self.px += 420 * dt
            self.px = clamp(self.px, 90, VIRTUAL_W - 90)
            self.throw_cd = max(0.0, self.throw_cd - dt)
            if clicked or pygame.mouse.get_pressed()[0]:
                self.throw(*mouse_pos)
            self.spawn_cd -= dt
            if self.spawn_cd <= 0:
                self._spawn()
                frac = 1 - self.time_left / SNOW_TIME
                self.spawn_cd = self.rnd.uniform(0.42, 0.62) * (1.0 - 0.35 * frac)
            if self.combo_t > 0:
                self.combo_t -= dt
                if self.combo_t <= 0:
                    self.combo = 0
            if self.time_left <= 0:
                self.time_left = 0.0
                self.finish()
        for tg in self.targets:
            tg.update(dt)
        self.targets = [q for q in self.targets if q.alive]
        for b in self.balls:
            b.t += dt
            if b.t >= b.dur and not b.done:
                b.done = True
                self._land(b)
        self.balls = [b for b in self.balls if not b.done]
        for f in self.fx:
            f[3] += dt
        self.fx = [f for f in self.fx if f[3] < 0.9]

    # ---- çizim ----
    def _backdrop(self):
        if self._bg is not None:
            return self._bg
        W, H = VIRTUAL_W, VIRTUAL_H
        s = pygame.Surface((W, H)).convert()
        for y in range(H):
            k = y / (H - 1)
            if y < 300:
                c = mix_col((40, 34, 90), (150, 110, 170), y / 300.0)
            else:
                c = mix_col((214, 226, 246), (170, 186, 220), (y - 300) / float(H - 300))
            pygame.draw.line(s, c, (0, y), (W, y))
        rnd = random.Random(77)
        for i in range(80):
            pygame.draw.circle(s, (255, 255, 240), (rnd.randint(0, W), rnd.randint(0, 180)), rnd.choice((1, 1, 2)))
        add_glow(s, W * 0.78, 90, 140, (255, 240, 200), 0.35)
        pygame.draw.circle(s, (250, 246, 230), (int(W * 0.78), 90), 34)
        # uzak dağlar
        for layer, (col, base, amp) in enumerate((((96, 92, 150), 250, 90), ((120, 120, 176), 280, 60))):
            pts = [(0, H)]
            x = 0
            while x <= W + 60:
                pts.append((x, base - amp * abs(math.sin(x * 0.006 + layer * 1.7)) - rnd.uniform(0, 18)))
                x += 60
            pts.append((W, H))
            pygame.draw.polygon(s, col, pts)
            for px_, py_ in pts[1:-1]:
                if py_ < base - amp * 0.55:
                    pygame.draw.polygon(s, (236, 240, 252), [(px_, py_), (px_ - 22, py_ + 26), (px_ + 22, py_ + 26)])
        # kar zemini
        pygame.draw.rect(s, (226, 236, 250), (0, 290, W, H - 290))
        for i in range(14):
            yy = 300 + i * i * 2.6
            pygame.draw.line(s, (204, 216, 238), (0, yy), (W, yy), 1)
        # köy evleri (arka sıra)
        for i, hx in enumerate((120, 330, 560, 820, 1060)):
            hw, hh = 120 + (i % 2) * 30, 70 + (i % 3) * 10
            base_y = 292
            body = pygame.Rect(hx - hw // 2, base_y - hh, hw, hh)
            pygame.draw.rect(s, (110, 70, 60) if i % 2 else (90, 74, 110), body)
            roof = [(body.x - 12, body.y + 4), (body.centerx, body.y - 46), (body.right + 12, body.y + 4)]
            pygame.draw.polygon(s, (240, 246, 255), roof)
            pygame.draw.polygon(s, (200, 214, 236), roof, 3)
            for wx in (body.x + 20, body.right - 44):
                w = pygame.Rect(wx, body.y + 22, 24, 22)
                add_glow(s, w.centerx, w.centery, 30, (255, 200, 110), 0.35)
                pygame.draw.rect(s, (255, 214, 120), w)
                pygame.draw.line(s, (110, 70, 50), (w.centerx, w.y), (w.centerx, w.bottom), 2)
            pygame.draw.rect(s, (70, 44, 34), (body.centerx - 10, body.bottom - 30, 20, 30))
        # çamlar
        for i in range(16):
            tx = (i * 89 + 30) % W
            ty = 300 + (i % 3) * 6
            for k, w in enumerate((40, 32, 22)):
                pts = [(tx - w, ty - k * 26), (tx, ty - 40 - k * 26), (tx + w, ty - k * 26)]
                pygame.draw.polygon(s, (36, 86, 74), pts)
                pygame.draw.polygon(s, (240, 246, 255), [(tx - w * 0.5, ty - k * 26 - 18), (tx, ty - 40 - k * 26),
                                                         (tx + w * 0.4, ty - k * 26 - 22)])
        # ön plan kar duvarları (siper)
        for (fx_, fy_, fw) in ((200, 600, 170), (VIRTUAL_W - 200, 600, 170)):
            r = pygame.Rect(fx_ - fw // 2, fy_ - 40, fw, 60)
            pygame.draw.ellipse(s, (190, 204, 230), r.move(0, 8))
            pygame.draw.ellipse(s, (246, 250, 255), r)
            for j in range(5):
                pygame.draw.circle(s, (232, 240, 252), (r.x + 20 + j * 32, r.y + 8), 18)
        self._bg = s
        return s

    def draw(self, canvas, mouse_pos, t):
        canvas.blit(self._backdrop(), (0, 0))
        # yaratıklar (uzaktan yakına)
        for tg in sorted(self.targets, key=lambda q: q.y):
            tg.draw(canvas, t)
        # kar topları (düz iki daire yerine ince kenarlık + sıkışmış kar
        # benekleri - "dandik" görünen yuvarlak piksel yerine biraz doku)
        for b in self.balls:
            x, y, k = b.pos()
            gx = b.x0 + (b.x1 - b.x0) * k
            gy = b.y0 + (b.y1 - b.y0) * k
            canvas.blit(shadow_sprite(14), (int(gx - 7), int(gy - 2)))
            circle_aa(canvas, x, y, 8, (196, 210, 236))
            circle_aa(canvas, x - 1.5, y - 1.5, 6.5, WHITE)
            ring_aa(canvas, x, y, 8, (170, 190, 222), 1)
            for sx, sy in ((-2.6, 1.8), (2.2, 2.6), (0.4, -2.4)):
                circle_aa(canvas, x + sx, y + sy, 0.9, (205, 216, 238))
        # efektler
        for kind, x, y, age, val in self.fx:
            k = age / 0.9
            if kind == "splat":
                for i in range(7):
                    a = i * math.tau / 7
                    blit_disc(canvas, x + math.cos(a) * (6 + 26 * k), y + math.sin(a) * (4 + 14 * k),
                              4 * (1 - k) + 1, WHITE, int(230 * (1 - k)))
            else:
                draw_text(canvas, "+%d" % val, (x, y - 30 - 40 * k), int(22 + 6 * (1 - k)),
                          GOLD if val > 1 else (130, 220, 255), bold=True, center=True)
                draw_icon(canvas, x + 26, y - 30 - 40 * k, "gem", GEM_COLOR, 7)
        # oyuncu (kendi skini, bereli)
        sk = get_skin(self.app.save.data.get("equipped_skin", "default"))
        py_ = 640
        canvas.blit(shadow_sprite(60), (int(self.px - 30), int(py_ + 18)))
        draw_skin_preview(canvas, sk, self.px, py_, t, r=26, weapon=False)
        pygame.draw.rect(canvas, (220, 40, 50), (int(self.px - 20), int(py_ - 30), 40, 12), border_radius=6)
        circle_aa(canvas, self.px, py_ - 36, 6, WHITE)
        if self.stage == "play":
            # nişan çizgisi
            mx, my = mouse_pos
            my = clamp(my, SNOW_LANE_TOP - 60, SNOW_LANE_BOT + 40)
            for i in range(10):
                k = i / 9.0
                d = math.hypot(mx - self.px, my - 618)
                hh = 40 + d * 0.22
                x = self.px + 18 + (mx - self.px - 18) * k
                y = 618 + (my - 618) * k - math.sin(k * math.pi) * hh
                blit_disc(canvas, x, y, 2.4, WHITE, 120)
            ring_aa(canvas, mx, my, 16 + 2 * math.sin(t * 8), (255, 255, 255), 2)
            ring_aa(canvas, mx, my, 4, (255, 120, 120), 2)
        self._hud(canvas, t)

    def _hud(self, canvas, t):
        # süre
        cx = VIRTUAL_W / 2
        frac = clamp(self.time_left / SNOW_TIME, 0.0, 1.0)
        panel(canvas, pygame.Rect(cx - 110, 12, 220, 70), bg=(48, 35, 36), edge=(160, 200, 255), alpha=220, radius=16)
        col = (255, 120, 110) if self.time_left < 6 else (200, 230, 255)
        draw_text(canvas, "%d" % int(math.ceil(self.time_left)), (cx, 40), 36, col, bold=True, center=True)
        draw_bar(canvas, pygame.Rect(cx - 90, 64, 180, 8), frac, col, radius=4)
        # isabet / elmas
        panel(canvas, pygame.Rect(20, 14, 210, 64), bg=(48, 35, 36), edge=GEM_COLOR, alpha=220, radius=14)
        draw_icon(canvas, 48, 46, "gem", GEM_COLOR, 13)
        draw_text(canvas, str(min(self.gems, SNOW_MAX_GEMS)), (74, 26), 30, GEM_COLOR, bold=True)
        draw_text(canvas, L("snow.hits", self.hits), (150, 50), 11, (190, 200, 230), shadow=False)
        if self.combo >= 3 and self.combo_t > 0:
            draw_text(canvas, L("snow.combo", self.combo), (cx, 108), 22, GOLD, bold=True, center=True)
        draw_text(canvas, L("snow.left", self.plays_left()), (VIRTUAL_W - 24, 28), 13, (220, 230, 255),
                  bold=True, right=True)
        if self.stage == "count":
            n = int(math.ceil(self.count_t))
            k = self.count_t - math.floor(self.count_t)
            draw_text(canvas, str(n) if n > 0 else L("snow.go"), (cx, 330), int(90 + 40 * k), WHITE,
                      bold=True, center=True)
            draw_text(canvas, L("snow.how"), (cx, 410), 16, (104, 76, 78), bold=True, center=True, shadow=False)

    # ---- giriş / sonuç pencereleri ----
    def draw_intro(self, canvas, mouse_pos, clicked, dt, t):
        canvas.blit(self._backdrop(), (0, 0))
        dim = pygame.Surface((VIRTUAL_W, VIRTUAL_H), pygame.SRCALPHA)
        dim.fill((10, 12, 30, 150))
        canvas.blit(dim, (0, 0))
        R = pygame.Rect(0, 0, 620, 520)
        R.center = (VIRTUAL_W / 2, VIRTUAL_H / 2)
        add_glow(canvas, R.centerx, R.y + 90, 300, (180, 220, 255), 0.22)
        panel(canvas, R, bg=(20, 26, 52), edge=(180, 220, 255), alpha=245, radius=20, edge_w=3)
        # Kollar + dal uçları, yuvarlatılmış silindir şapka + bant, saçaklı
        # sarkan atkı ucu, kaş ve gülümseme eklendi.)
        mx, my = R.centerx, R.y + 172
        # ---- kollar: orta küreden iki yana, dal uçlu ----
        arm_y = my - 52
        for sgn in (-1, 1):
            ex, ey = mx + sgn * 56, arm_y - 18
            pygame.draw.line(canvas, (92, 62, 40), (mx + sgn * 25, arm_y - 2), (ex, ey), 3)
            for a in (-0.55, 0.0, 0.55):
                tx = ex + sgn * math.cos(a) * 15
                ty = ey - 11 - math.sin(a) * 7
                pygame.draw.line(canvas, (92, 62, 40), (ex, ey), (tx, ty), 2)
        # ---- gövde: üç küre (gölge + üst parlama ile hacimli) ----
        for (oy, rr) in ((0, 38), (-52, 28), (-94, 20)):
            circle_aa(canvas, mx + 2, my + oy + 3, rr, (170, 186, 220))
            circle_aa(canvas, mx, my + oy, rr, (246, 250, 255))
            circle_aa(canvas, mx - rr * 0.34, my + oy - rr * 0.38, rr * 0.4, (255, 255, 255))
        for oy in (-40, -58, -70):
            circle_aa(canvas, mx, my + oy + 10, 3.2, (40, 40, 50))
        # ---- yüz: kömür gözler, kaş, gülümseme ----
        circle_aa(canvas, mx - 7, my - 98, 3, (30, 30, 36))
        circle_aa(canvas, mx + 7, my - 98, 3, (30, 30, 36))
        for sgn in (-1, 1):
            pygame.draw.line(canvas, (30, 30, 36),
                             (mx + sgn * 11, my - 104), (mx + sgn * 4, my - 106), 2)
        for dx in (-9, -4.5, 0, 4.5, 9):
            sy = (my - 86) + 3 * (1 - (dx / 9.0) ** 2)
            circle_aa(canvas, mx + dx, sy, 1.6, (40, 40, 50))
        # havuç burun
        poly_aa(canvas, [(mx, my - 93), (mx, my - 87), (mx + 22, my - 90)], (240, 130, 50))
        # ---- atkı: saran bant + sarkan, saçaklı bir uç ----
        tail = [(mx + 13, my - 77), (mx + 33, my - 50), (mx + 23, my - 45), (mx + 5, my - 72)]
        poly_aa(canvas, tail, (196, 32, 42))
        for k in range(3):
            fx0 = mx + 22 + k * 4
            pygame.draw.line(canvas, (150, 20, 30), (fx0, my - 50 + k * 2),
                             (fx0 - 3, my - 42 + k * 2), 2)
        pygame.draw.rect(canvas, (220, 40, 50), (mx - 24, my - 82, 48, 11), border_radius=5)
        # ---- şapka: oval kenarlık + yuvarlatılmış silindir + bant ----
        brim = pygame.Rect(mx - 25, my - 124, 50, 11)
        pygame.draw.ellipse(canvas, (22, 22, 28), brim)
        pygame.draw.ellipse(canvas, (44, 44, 52), brim.inflate(-6, -5))
        pygame.draw.rect(canvas, (28, 28, 34), (mx - 15, my - 147, 30, 28), border_radius=7)
        pygame.draw.rect(canvas, (220, 40, 50), (mx - 15, my - 128, 30, 6))
        draw_text(canvas, L("snow.title"), (R.centerx, R.y + 240), 32, (220, 240, 255), bold=True, center=True)
        yy = R.y + 282
        for ln in wrap_text(L("snow.desc", SNOW_TIME, SNOW_DAILY), 14, R.w - 80)[:4]:
            draw_text(canvas, ln, (R.centerx, yy), 14, (196, 210, 240), center=True, shadow=False)
            yy += 20
        left = self.plays_left()
        draw_text(canvas, L("snow.left", left), (R.centerx, R.y + 376), 16,
                  GREEN if left > 0 else (255, 150, 150), bold=True, center=True)
        if self.err:
            for i, ln in enumerate(wrap_text(self.err, 12, R.w - 80)[:2]):
                draw_text(canvas, ln, (R.centerx, R.y + 402 + i * 16), 12, (255, 160, 160), center=True,
                          shadow=False)
        busy = self.stage == "wait"
        b1 = Button((R.centerx - 230, R.bottom - 74, 220, 52),
                    L("ui.acc_working") if busy else L("snow.start"), self.start,
                    color=(60, 130, 90), hover_color=(80, 170, 115), enabled=(left > 0 and not busy))
        b2 = Button((R.centerx + 10, R.bottom - 74, 220, 52), L("ui.back"), self.app._snow_leave)
        for b in (b1, b2):
            b.update(mouse_pos, dt)
            b.draw(canvas)
            if clicked:
                b.click(mouse_pos)

    def draw_result(self, canvas, mouse_pos, clicked, dt, t):
        dim = pygame.Surface((VIRTUAL_W, VIRTUAL_H), pygame.SRCALPHA)
        dim.fill((37, 27, 28, 170))
        canvas.blit(dim, (0, 0))
        R = pygame.Rect(0, 0, 560, 400)
        R.center = (VIRTUAL_W / 2, VIRTUAL_H / 2)
        panel(canvas, R, bg=(62, 45, 46), edge=GEM_COLOR, alpha=248, radius=20, edge_w=3)
        draw_text(canvas, L("snow.over"), (R.centerx, R.y + 40), 30, (220, 240, 255), bold=True, center=True)
        draw_text(canvas, L("snow.hits", self.hits), (R.centerx, R.y + 92), 18, (196, 210, 240), center=True)
        if self.stage == "claim":
            for k in range(10):
                a = t * 3.4 + k * math.tau / 10
                al = 0.15 + 0.85 * ((k / 10.0 + t * 0.6) % 1.0)
                blit_disc(canvas, R.centerx + math.cos(a) * 26, R.y + 170 + math.sin(a) * 26,
                          1.5 + 2.2 * al, GEM_COLOR, int(230 * al))
            return
        amt = int(self.result_amount or 0)
        add_glow(canvas, R.centerx, R.y + 170, 160, GEM_COLOR, 0.30)
        draw_icon(canvas, R.centerx - 70, R.y + 170, "gem", GEM_COLOR, 26)
        draw_text(canvas, "+%d" % amt, (R.centerx + 20, R.y + 170), 54, GEM_COLOR, bold=True, center=True)
        if self.gems > SNOW_MAX_GEMS:
            draw_text(canvas, L("snow.cap", SNOW_MAX_GEMS), (R.centerx, R.y + 214), 11, (190, 200, 230),
                      center=True, shadow=False)
        if self.err:
            for i, ln in enumerate(wrap_text(self.err, 12, R.w - 60)[:2]):
                draw_text(canvas, ln, (R.centerx, R.y + 236 + i * 16), 12, (255, 160, 160), center=True,
                          shadow=False)
        left = self.plays_left()
        draw_text(canvas, L("snow.left", left), (R.centerx, R.y + 276), 14, (200, 220, 255), bold=True,
                  center=True)
        b1 = Button((R.centerx - 230, R.bottom - 74, 220, 52), L("snow.again"), self.start,
                    color=(60, 130, 90), hover_color=(80, 170, 115), enabled=left > 0)
        b2 = Button((R.centerx + 10, R.bottom - 74, 220, 52), L("ui.main_menu"), self.app._snow_leave)
        for b in (b1, b2):
            b.update(mouse_pos, dt)
            b.draw(canvas)
            if clicked:
                b.click(mouse_pos)


# dokunmatik kontroller (telefon / tablet):
# * menüler: dokun-bırak = tıklama (parmak kaydıysa tıklama sayılmaz), parmakla
#   sürükleyince listeler kayar ve bırakınca süzülerek durur.
# * oyun: sol yarıda nereye basarsan orada yüzen joystick çıkar.
# * yazı: iPhone klavyesi yalnızca bir dokunuşun içinde açılabilir.
RUN_OVERLAY_STATES = None          # aşağıda, durum sabitlerinden sonra doldurulur

STRINGS.update({
    "touch.dash": _T("DASH", "DASH", "DASH", "DASH", "РЫВОК"),
    "touch.bonk": _T("BONK", "BONK", "BONK", "BONK", "БОНК"),
})

# Telefonda tuş adları yerine düğme adları yazar ("[E] ile konuş" -> "[E]").
MOBILE_KEY_LABELS = {
    "use": "E", "dash": "DASH", "bonk": "BONK", "shop": "$", "map": "MAP",
    "stats": "⋮", "restart": "-", "fire": "OTO",
}

TOUCH_TAP_SLOP = 16          # bu kadar pikselden az kayan dokunuş = tıklama
JOY_RADIUS = 86
JOY_DEAD = 10
AUTO_AIM_RANGE = 560         # otomatik nişanın düşman arama yarıçapı (dünya px)
TOUCH_BTNS = {
    # ad: (merkez x, merkez y, yarıçap) - sağ kenara göre (ekran genişliği
    # değişebilir)
    "dash":  (VIRTUAL_W - 104, 600, 62),
    "bonk":  (VIRTUAL_W - 228, 652, 46),
    "use":   (VIRTUAL_W - 220, 522, 42),
    "shop":  (VIRTUAL_W - 66, 462, 32),
    "pause": (VIRTUAL_W // 2 - 178, 38, 26),
}

_TEXT_ZONES = []             # bu karede çizilen metin kutuları


def touch_text_field(rect, key, text, focused=False, secret=False, numeric=False,
                     label=""):
    """Bir metin kutusunu dokunmatik klavyeye tanıtır (yalnız mobil)."""
    if not MOBILE:
        return
    _TEXT_ZONES.append({"x": int(rect.x), "y": int(rect.y), "w": int(rect.w), "h": int(rect.h),
                        "k": "text", "id": str(key), "v": str(text or ""),
                        "pw": 1 if secret else 0, "num": 1 if numeric else 0,
                        "f": 1 if focused else 0, "label": str(label or "")})


_LINK_URLS = set()           # bu karede dokunuşa bağlanan bağlantılar
_LINK_URLS_PREV = set()      # bir önceki karede yayınlananlar


def touch_link(rect, url):
    """Düğmeyi bir bağlantıya bağlar: telefonda sayfa dokunuş anında açılır (iPhone başka türlü yeni sekmeye izin vermiyor)."""
    if not MOBILE or not url:
        return
    _LINK_URLS.add(str(url))
    _TEXT_ZONES.append({"x": int(rect.x), "y": int(rect.y), "w": int(rect.w), "h": int(rect.h),
                        "k": "url", "id": "url", "v": str(url), "pw": 0, "num": 0, "f": 0,
                        "label": ""})


WEB_AD_URL = "reklam.mp4"     # oyun sayfasının yanında


def touch_ad_zone(rect, kind="ad"):
    """Reklam düğmesi: telefonda film dokunuş anında (sesli) başlasın."""
    if not (MOBILE and IS_WEB):
        return
    _TEXT_ZONES.append({"x": int(rect.x), "y": int(rect.y), "w": int(rect.w), "h": int(rect.h),
                        "k": kind, "id": kind, "v": WEB_AD_URL, "pw": 0, "num": 0, "f": 0,
                        "label": ""})


def run_use_available(run):
    """'E' tuşunun şu an bir işe yarayıp yaramadığı (düğme o zaman görünür)."""
    try:
        p = run.player
        if not p.alive:
            return False
        if run.hell_portal is not None and run.hell_portal.in_range(p):
            return True
        m = getattr(run, "merchant", None)
        if m is not None and not run.merchant_open and m.in_range(p):
            return True
        sh = getattr(run, "cursed_shrine", None)
        if sh is not None and sh.alive and not sh.used and sh.in_range(p):
            return True
    except Exception:
        pass
    return False


class TouchUI:
    def __init__(self, app):
        self.app = app
        self.fingers = {}          # parmak kimliği -> bilgi
        self.pointer = (VIRTUAL_W / 2, VIRTUAL_H / 2)
        self._click = False
        self._wheel = 0.0
        self.fling = 0.0           # bırakınca süzülme hızı (tekerlek birimi / sn)
        self.menu_down = False
        self.pressed = set()       # bu karede basılan oyun düğmeleri
        self.btn_flash = {}
        self.last_move = (1.0, 0.0)
        self.aim_target = None
        # klavye
        self.kb_seq = -1
        self.kb_key = ""
        self.kb_last = ""
        self.kb_open = False
        self.kb_enter = 0
        self.kb_label = ""
        self.kb_secret = False
        self.kb_grace = 0
        self._kb_text = ""
        self._zones_pub = ""
        self.hidden_seen = 0
        self.state_prev = None

    # ---- koordinat ----
    @staticmethod
    def _vpos(ev):
        # Parmak konumu tuvalin tamamına göre (0-1) gelir; oyun koordinatı
        # güvenli alana göredir (çentik payı düşülür, eksi olabilir).
        return (clamp(float(ev.x), 0.0, 1.0) * SCREEN_W - SAFE_X,
                clamp(float(ev.y), 0.0, 1.0) * VIRTUAL_H)

    @staticmethod
    def _in_btn(name, pos):
        bx, by, br = TOUCH_BTNS[name]
        return (pos[0] - bx) ** 2 + (pos[1] - by) ** 2 <= (br + 16) ** 2

    def _play_role(self, pos):
        app = self.app
        run = app.run
        if self._in_btn("pause", pos):
            return "btn:pause"
        if run is not None:
            if stats_button_rect().inflate(16, 16).collidepoint(pos):
                return "hud"
            if run.show_stats:
                return "hud"
            if minimap_rect().inflate(10, 10).collidepoint(pos) or run.show_map:
                return "btn:map"
            if self._in_btn("dash", pos):
                return "btn:dash"
            if self._in_btn("bonk", pos):
                return "btn:bonk"
            if self._in_btn("shop", pos):
                return "btn:shop"
            if self._in_btn("use", pos) and run_use_available(run):
                return "btn:use"
        if pos[0] < VIRTUAL_W * 0.47:
            return "move"
        return "aim"

    # ---- olaylar ----
    def filter_events(self, events):
        """Ham olayları işler; oyunun geri kalanına gidecek listeyi döndürür."""
        out = []
        playing = self.app.state == STATE_PLAY
        for ev in events:
            et = ev.type
            if et == pygame.FINGERDOWN:
                pos = self._vpos(ev)
                role = self._play_role(pos) if playing else "menu"
                self.fingers[ev.finger_id] = {"pos": pos, "start": pos, "t0": time.time(),
                                              "role": role, "moved": 0.0, "origin": pos,
                                              "last": pos}
                if role.startswith("btn:"):
                    self.pressed.add(role[4:])
                    self.btn_flash[role[4:]] = 0.18
                if role == "menu":
                    self.pointer = pos
                    self.fling = 0.0
            elif et == pygame.FINGERMOTION:
                f = self.fingers.get(ev.finger_id)
                if f is None:
                    continue
                pos = self._vpos(ev)
                lx, ly = f["last"]
                f["moved"] = max(f["moved"], math.hypot(pos[0] - f["start"][0], pos[1] - f["start"][1]))
                if f["role"] == "menu":
                    self.pointer = pos
                    if f["moved"] > TOUCH_TAP_SLOP:
                        dy = pos[1] - ly
                        self._wheel += dy / 46.0
                        dtt = max(1e-3, time.time() - f.get("tm", f["t0"]))
                        self.fling = self.fling * 0.5 + (dy / 46.0) / dtt * 0.5
                        f["tm"] = time.time()
                elif f["role"] == "move":
                    # Parmak halkanın dışına çıkarsa joystick onu izler.
                    ox, oy = f["origin"]
                    d = math.hypot(pos[0] - ox, pos[1] - oy)
                    if d > JOY_RADIUS:
                        k = (d - JOY_RADIUS) / d
                        f["origin"] = (ox + (pos[0] - ox) * k, oy + (pos[1] - oy) * k)
                f["pos"] = pos
                f["last"] = pos
            elif et == pygame.FINGERUP:
                f = self.fingers.pop(ev.finger_id, None)
                if f is None:
                    continue
                pos = self._vpos(ev)
                if f["role"] in ("menu", "hud"):
                    if f["moved"] <= TOUCH_TAP_SLOP:
                        self.pointer = pos
                        self._click = True
                    elif f["role"] == "menu" and time.time() - f.get("tm", 0) > 0.12:
                        self.fling = 0.0       # parmak durup bırakıldı: süzülme yok
            elif et in (pygame.MOUSEBUTTONDOWN, pygame.MOUSEBUTTONUP, pygame.MOUSEMOTION):
                if getattr(ev, "touch", False):
                    continue                    # dokunuştan türetilmiş: yukarıda işlendi
                if et == pygame.MOUSEBUTTONDOWN and ev.button == 1:
                    # Gerçek fare (tablete takılı) - tıklama gibi davran.
                    self.pointer = (float(ev.pos[0]), float(ev.pos[1]))
                    self._click = True
                elif et == pygame.MOUSEMOTION:
                    self.pointer = (float(ev.pos[0]), float(ev.pos[1]))
            elif et in (pygame.KEYDOWN, pygame.KEYUP, pygame.TEXTINPUT, pygame.TEXTEDITING):
                if self.kb_open:
                    continue                    # yazı gizli kutudan geliyor
                out.append(ev)
            else:
                out.append(ev)
        out.extend(self._kb_events())
        self.menu_down = any(f["role"] == "menu" for f in self.fingers.values())
        return out

    def take_click(self):
        c, self._click = self._click, False
        return c

    def take_wheel(self, dt):
        w, self._wheel = self._wheel, 0.0
        if not self.menu_down and abs(self.fling) > 0.05:
            w += self.fling * dt
            self.fling *= max(0.0, 1.0 - dt * 4.0)
        elif not self.menu_down:
            self.fling = 0.0
        return w

    def reset_play(self):
        """Durum değişince oyundaki parmak rolleri sıfırlanır."""
        for f in self.fingers.values():
            f["role"] = "menu" if self.app.state != STATE_PLAY else f["role"]
        self.pressed.clear()

    # ---- oyun girdisi ----
    def play_input(self, run):
        """(hareket, nişan ekranı, ateş, basılan düğmeler) döndürür."""
        mx = my = 0.0
        aim = None
        for f in self.fingers.values():
            if f["role"] == "move":
                ox, oy = f["origin"]
                dx, dy = f["pos"][0] - ox, f["pos"][1] - oy
                d = math.hypot(dx, dy)
                if d > JOY_DEAD:
                    mx, my = dx / d, dy / d
            elif f["role"] == "aim":
                aim = f["pos"]
        if abs(mx) + abs(my) > 0:
            self.last_move = (mx, my)
        fire = aim is not None
        self.aim_target = None
        if aim is None:
            tgt = self._auto_target(run) if CFG.get("auto_aim", True) else None
            p = run.player
            if tgt is not None:
                aim = run.world_to_screen(tgt.x, tgt.y)
                self.aim_target = tgt
                fire = True
            else:
                sx, sy = run.world_to_screen(p.x, p.y)
                aim = (sx + self.last_move[0] * 120, sy + self.last_move[1] * 120)
        pressed, self.pressed = self.pressed, set()
        return (mx, my), aim, fire, pressed

    @staticmethod
    def _auto_target(run):
        p = run.player
        best, bd = None, AUTO_AIM_RANGE * AUTO_AIM_RANGE
        cam = run.cam_rect()
        view = pygame.Rect(cam.x - 40, cam.y - 40, cam.w + 80, cam.h + 80)
        for group in (getattr(run, "bosses", None) or [], run.enemies):
            for e in group:
                if not getattr(e, "alive", True):
                    continue
                if getattr(e, "invisible", False) or getattr(e, "invis_t", 0) > 0:
                    continue
                if not view.collidepoint(e.x, e.y):
                    continue
                d = (e.x - p.x) ** 2 + (e.y - p.y) ** 2
                if d < bd:
                    best, bd = e, d
        return best

    # ---- klavye köprüsü ----
    def _kb_events(self):
        if not IS_WEB:
            return []
        raw = web_call("kbPoll", self.kb_seq, default="")
        if not raw:
            return []
        try:
            d = json.loads(str(raw))
        except Exception:
            return []
        self.kb_seq = int(d.get("seq", self.kb_seq))
        evs = []
        key = str(d.get("key") or "")
        val = str(d.get("val") or "")
        if not d.get("open"):
            self.kb_open = False
            self.kb_key = ""
            return evs
        if not self.kb_open or key != self.kb_key:
            # yeni odak: kutunun o anki metniyle başlar
            self.kb_open = True
            self.kb_key = key
            self.kb_last = val
            self.kb_enter = int(d.get("enter", 0))
            self.kb_grace = 2
            return evs
        old = self.kb_last
        n = 0
        while n < len(old) and n < len(val) and old[n] == val[n]:
            n += 1
        for _ in range(len(old) - n):
            evs.append(pygame.event.Event(pygame.KEYDOWN, key=pygame.K_BACKSPACE, unicode="",
                                          mod=0, scancode=0))
        for ch in val[n:]:
            if ch == "\n":
                continue
            evs.append(pygame.event.Event(pygame.KEYDOWN, key=0, unicode=ch, mod=0, scancode=0))
        self.kb_last = val
        ent = int(d.get("enter", 0))
        if ent != self.kb_enter:
            for _ in range(max(0, ent - self.kb_enter)):
                evs.append(pygame.event.Event(pygame.KEYDOWN, key=pygame.K_RETURN, unicode="\r",
                                              mod=0, scancode=0))
            self.kb_enter = ent
        return evs

    def end_frame(self):
        """Karenin sonunda: metin kutularını sayfaya bildir, klavyeyi eşitle."""
        zones = [z for z in _TEXT_ZONES if z["k"] == "text"]
        allz = list(_TEXT_ZONES)
        _TEXT_ZONES.clear()
        _LINK_URLS_PREV.clear()
        _LINK_URLS_PREV.update(_LINK_URLS)
        _LINK_URLS.clear()
        if not IS_WEB:
            return
        pub = json.dumps([{k: z[k] for k in ("x", "y", "w", "h", "k", "id", "v", "pw", "num")}
                          for z in allz], ensure_ascii=False)
        if pub != self._zones_pub:
            self._zones_pub = pub
            web_call("setZones", pub)
        self.kb_label = ""
        if not self.kb_open:
            return
        if self.kb_grace > 0:
            # Bu karede yeni bir kutuya dokunuldu; oyunun odağı bir sonraki
            # karede yetişir. O zamana kadar karar verme.
            self.kb_grace -= 1
            for z in zones:
                if z["id"] == self.kb_key:
                    self._kb_text = z["v"]
                    self.kb_label = z.get("label") or ""
                    self.kb_secret = bool(z["pw"])
            return
        cur = None
        for z in zones:
            if z["f"]:
                cur = z
                break
        if cur is None:
            web_call("kbClose")          # metin kutusu ekrandan gitti
            self.kb_open = False
            self.kb_key = ""
            return
        self.kb_label = cur.get("label") or ""
        self.kb_secret = bool(cur["pw"])
        if cur["id"] != self.kb_key:
            # Oyun odağı başka kutuya geçirdi (ör. Enter -> sonraki kutu):
            # klavye açık kalır, gizli kutu yeni alanın metnini alır.
            self.kb_key = cur["id"]
            self.kb_last = cur["v"]
            web_call("kbRetarget", cur["id"], cur["v"], cur["pw"], cur["num"])
        elif cur["v"] != self.kb_last:
            # Oyun yazılanı kabul etmedi / kısalttı: gizli kutuyu düzelt.
            self.kb_last = cur["v"]
            web_call("kbSet", cur["v"])
        self._kb_text = cur["v"]

    def poll_hidden(self):
        """Uygulama arka plana gittiyse True (oyun duraklatılır)."""
        if not IS_WEB:
            return False
        n = int(web_call("hiddenCount", default=0) or 0)
        if n != self.hidden_seen:
            self.hidden_seen = n
            return True
        return False

    # ---- çizim ----
    def draw_play(self, canvas, run, t):
        for k in list(self.btn_flash):
            self.btn_flash[k] -= 1 / 60
            if self.btn_flash[k] <= 0:
                del self.btn_flash[k]
        p = run.player
        # joystick
        joy = None
        for f in self.fingers.values():
            if f["role"] == "move":
                joy = f
                break
        if joy is not None:
            ox, oy = joy["origin"]
            dx, dy = joy["pos"][0] - ox, joy["pos"][1] - oy
            d = math.hypot(dx, dy)
            if d > JOY_RADIUS:
                dx, dy = dx / d * JOY_RADIUS, dy / d * JOY_RADIUS
            blit_disc(canvas, ox, oy, JOY_RADIUS, (20, 24, 40), 120)
            pygame.draw.circle(canvas, (150, 170, 230), (int(ox), int(oy)), JOY_RADIUS, 2)
            blit_disc(canvas, ox + dx, oy + dy, 36, (200, 215, 255), 170)
            pygame.draw.circle(canvas, (255, 255, 255), (int(ox + dx), int(oy + dy)), 36, 2)
        else:
            hx, hy = 170, 574
            blit_disc(canvas, hx, hy, 70, (20, 24, 40), 55)
            pygame.draw.circle(canvas, (120, 130, 170), (hx, hy), 70, 2)
            blit_disc(canvas, hx, hy, 28, (150, 160, 200), 60)
        # nişan: otomatik hedefin üstünde küçük işaret
        if self.aim_target is not None and getattr(self.aim_target, "alive", False):
            sx, sy = run.world_to_screen(self.aim_target.x, self.aim_target.y)
            rr = 22 + 3 * math.sin(t * 8)
            pygame.draw.circle(canvas, (255, 120, 90), (int(sx), int(sy)), int(rr), 2)
        # düğmeler
        self._btn(canvas, "dash", "dash", L("touch.dash"), (130, 225, 210),
                  (p.dash_cd_timer, p.eff_dash_cd()), t)
        if getattr(p, "titan_smash", 0):
            cd = (max(p.bonk_timer, 0.0), p.eff_bonk_cd())
        else:
            cd = (p.bonk_timer, p.eff_bonk_cd())
        self._btn(canvas, "bonk", "fist", L("touch.bonk"), (245, 150, 80), cd, t)
        self._btn(canvas, "shop", "coin", "", GOLD, None, t)
        if run_use_available(run):
            self._btn(canvas, "use", None, "E", (255, 220, 120), None, t, pulse=True)
        self._btn(canvas, "pause", None, "II", (200, 205, 230), None, t)
        # skin yeteneği (otomatik): dash'in üstünde küçük süre halkası
        ult = getattr(p, "ult", None)
        if ult:
            try:
                rem, tot = p.ult_timer, p.ult_cd
                cx, cy = TOUCH_BTNS["dash"][0], 498
                frac = 0.0 if tot <= 0 else clamp(rem / tot, 0.0, 1.0)
                col = tuple(ult.get("color", GOLD))
                blit_disc(canvas, cx, cy, 24, (12, 14, 24), 170)
                pygame.draw.circle(canvas, scale_col(col, 0.4), (cx, cy), 24, 2)
                self._ring(canvas, cx, cy, 24, 1.0 - frac, col)
                draw_icon(canvas, cx, cy, ult.get("icon", "star"),
                          col if frac <= 0.001 else scale_col(col, 0.6), 11)
            except Exception:
                pass

    @staticmethod
    def _ring(canvas, cx, cy, r, frac, col):
        """Dolu kısmı frac olan halka (saat yönünde, tepeden)."""
        if frac <= 0:
            return
        n = max(2, int(36 * frac))
        pts = []
        for i in range(n + 1):
            a = -math.pi / 2 + 2 * math.pi * frac * i / n
            pts.append((cx + math.cos(a) * r, cy + math.sin(a) * r))
        if len(pts) >= 2:
            pygame.draw.lines(canvas, col, False, pts, 4)

    _BTN_CACHE = {}

    def _btn(self, canvas, name, icon, label, col, cd, t, pulse=False):
        """Düğme görüntüsü önbellekten gelir (durum + bekleme dilimine göre); her karede onlarca çizim yerine tek blit."""
        bx, by, br = TOUCH_BTNS[name]
        remain, total = (cd if cd else (0.0, 0.0))
        ready = remain <= 0.001 or total <= 0
        held = any(f["role"] == "btn:" + name for f in self.fingers.values())
        flash = bool(self.btn_flash.get(name))
        step = 0 if ready else int(24 * clamp(remain / max(1e-4, total), 0.0, 1.0)) + 1
        num = int(math.ceil(remain)) if (not ready and total > 0 and remain >= 0.95) else 0
        ph = int((math.sin(t * 7) + 1) * 2) if pulse else 0
        key = (name, icon, label, col, step, num, held, flash, ph)
        img = TouchUI._BTN_CACHE.get(key)
        if img is None:
            if len(TouchUI._BTN_CACHE) > 600:
                TouchUI._BTN_CACHE.clear()
            pad = br + 26
            img = pygame.Surface((pad * 2, pad * 2), pygame.SRCALPHA)
            global _GLOW_ON_ALPHA
            _GLOW_ON_ALPHA = True
            try:
                rem = (step - 1) / 24.0 * total if step else 0.0
                self._btn_draw(img, pad, pad, br, icon, label, col, (rem, total) if step else None,
                               t, held, flash, pulse, ph, num)
            finally:
                _GLOW_ON_ALPHA = False
            img = mob_rle(img)
            TouchUI._BTN_CACHE[key] = img
        canvas.blit(img, (bx - img.get_width() // 2, by - img.get_height() // 2))

    def _btn_draw(self, canvas, bx, by, br, icon, label, col, cd, t, held, flash, pulse, ph, num):
        remain, total = (cd if cd else (0.0, 0.0))
        ready = remain <= 0.001 or total <= 0
        k = 0.93 if held else 1.0
        if pulse:
            k *= 1.0 + 0.06 * (ph / 2.0 - 1.0)
        r = int(br * k)
        blit_disc(canvas, bx, by, r, (12, 14, 24), 175)
        if flash:
            blit_disc(canvas, bx, by, r, col, 90)
        edge = col if ready else scale_col(col, 0.45)
        pygame.draw.circle(canvas, edge, (bx, by), r, 3)
        if not ready:
            self._ring(canvas, bx, by, r - 5, 1.0 - clamp(remain / max(1e-4, total), 0.0, 1.0), col)
        if icon:
            draw_icon(canvas, bx, by - (8 if label else 0), icon,
                      col if ready else scale_col(col, 0.55), max(10, int(r * 0.36)))
        if label:
            ly = by + (r * 0.42 if icon else -2)
            draw_text(canvas, label, (bx, ly), 15 if icon else 22, WHITE if ready else TEXT_DIM,
                      bold=True, center=True, tiny=True)
        if num:
            draw_text(canvas, "%d" % num, (bx + r * 0.62, by - r * 0.7), 14,
                      WHITE, bold=True, center=True, tiny=True)

    def draw_keyboard_bar(self, canvas):
        """Klavye açıkken ekranın üstünde yazılan metin görünür (telefon klavyesi ekranın alt yarısını kapatır)."""
        if not self.kb_open:
            return
        txt = getattr(self, "_kb_text", "")
        shown = ("•" * len(txt)) if self.kb_secret else txt
        bar = pygame.Rect(140, 8, VIRTUAL_W - 280, 74)
        panel(canvas, bar, bg=(44, 32, 33), edge=CYAN, alpha=246, radius=14, edge_w=2)
        if self.kb_label:
            draw_text(canvas, self.kb_label, (bar.x + 18, bar.y + 6), 14, TEXT_DIM, shadow=False)
        while shown and text_width(shown, 26) > bar.w - 60:
            shown = shown[1:]
        draw_text(canvas, shown, (bar.x + 18, bar.y + 28), 26, WHITE, shadow=False)
        if (time.time() % 1.0) < 0.55:
            cx = bar.x + 20 + text_width(shown, 26)
            pygame.draw.line(canvas, CYAN, (cx, bar.y + 30), (cx, bar.y + 62), 3)


# ---- 2 kişilik (beta) ----
# Bir oyuncu oda kurar (sağda 6 karakterlik oda kodu görünür), arkadaşı kodu
# yazıp kendi skiniyle katılır, ev sahibi başlat'a basar:
# * Bütün oyun (yaratıklar, patronlar, silahlar, düşenler) oda kuranın
#   bilgisayarında işler (CoopRunState).
# * Her oyuncunun kendi seviyesi, tecrübesi, altını, marketi, silahları ve
#   kitapları var - sınır kişi başı 2 silah, 2 kitap, 1 nadir kitap.
# * mağara ve yemin ortaktır: biri seçer, ödülü de bedeli de ikisine birden
#   işler (ör. ikisine de +1000 altın, ikisine de -%12 hız).
# * Seviye / market / tüccar / mağara pencereleri oyunu durdurmaz; pencereyi
#   açan oyuncu en çok COOP_MENU_SHIELD saniye hasar almaz.
# * Ölen oyuncu arkadaşını izler; ikisi de ölünce koşu biter.
# * Oyun tek kişilikten çok daha zor (COOP_* çarpanları).
try:
    import socket as _socket
    import zlib as _zlib
    import queue as _queue
    import ssl as _ssl
    import collections
except Exception:            # (web sürümünde 2 kişilik zaten kapalı)
    _socket = _zlib = _queue = _ssl = collections = None

COOP_SLOTS = (2, 2, 1)            # kişi başı: silah, normal kitap, nadir kitap
COOP_ENEMY_HP = 1.75              # yaratık canı
COOP_ENEMY_DMG = 1.15             # yaratık hasarı
COOP_SPAWN_RATE = 1.6             # doğum sıklığı
COOP_CAP_MULT = 1.4               # aynı anda yaşayan yaratık tavanı
COOP_CAP_MAX = 240
COOP_BOSS_HP = 1.25               # patron canı (iki oyuncunun toplam gücü üstüne)
COOP_MENU_SHIELD = 4.0            # pencere açıkken en çok bu kadar sn hasar yok
COOP_SNAP_HZ = 15.0               # ev sahibi -> konuk anlık görüntü sıklığı
COOP_INPUT_HZ = 30.0              # konuk -> ev sahibi girdi sıklığı
COOP_MAX_RAW = 2 * 1024 * 1024    # açılmış bir mesajın en büyük boyu
COOP_MAX_IN = 120 * 1024          # gelen tek bir websocket mesajının sınırı
COOP_RECONNECT_FOR = 20.0         # kopunca bu kadar sn yeniden denenir
COOP_PART = 48 * 1024             # büyük mesaj bu boyda parçalara bölünür (sunucu sınırı 96 KB)
COOP_INTERP_MIN = 0.07            # konuk: çizim gecikmesi tamponu (sn) alt/üst sınır
COOP_INTERP_MAX = 0.45
COOP_PROTO = 2
COOP_CODE_ALPH = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789"


def coop_available():
    """2 kişilik bu cihazda açık mı?"""
    return not IS_WEB and not MOBILE


class CoopWS:
    """Küçük websocket istemcisi (RFC 6455): yalnızca standart kütüphane."""

    GUID = b"258EAFA5-E914-47DA-95CA-C5AB0DC85B11"
    CHUNK = 16384

    def __init__(self, url, timeout=12.0):
        u = urllib.parse.urlsplit(url)
        if u.scheme not in ("ws", "wss"):
            raise ValueError("ws/wss bekleniyor")
        self.secure = u.scheme == "wss"
        host = u.hostname or ""
        port = u.port or (443 if self.secure else 80)
        path = (u.path or "/") + ("?" + u.query if u.query else "")
        sock = _socket.create_connection((host, port), timeout=timeout)
        try:
            sock.setsockopt(_socket.IPPROTO_TCP, _socket.TCP_NODELAY, 1)
        except Exception:
            pass
        if self.secure:
            sock = make_ssl_context().wrap_socket(sock, server_hostname=host)
        self.sock = sock
        key = base64.b64encode(os.urandom(16)).decode("ascii")
        hostpart = host if (port in (80, 443)) else "%s:%d" % (host, port)
        req = ("GET %s HTTP/1.1\r\nHost: %s\r\nUpgrade: websocket\r\nConnection: Upgrade\r\n"
               "Sec-WebSocket-Key: %s\r\nSec-WebSocket-Version: 13\r\n"
               "User-Agent: EvolveArena/%s\r\n\r\n") % (path, hostpart, key, GAME_VERSION)
        sock.sendall(req.encode("ascii"))
        head = b""
        while b"\r\n\r\n" not in head:
            chunk = sock.recv(4096)
            if not chunk:
                raise ConnectionError("el sıkışma kesildi")
            head += chunk
            if len(head) > 16384:
                raise ConnectionError("el sıkışma çok uzun")
        hdr, rest = head.split(b"\r\n\r\n", 1)
        lines = hdr.decode("latin-1").split("\r\n")
        if not lines or " 101 " not in (lines[0] + " "):
            raise ConnectionError("sunucu bağlantıyı reddetti")
        want = base64.b64encode(hashlib.sha1(key.encode("ascii") + self.GUID).digest()).decode("ascii")
        got = ""
        for ln in lines[1:]:
            if ":" in ln:
                k, v = ln.split(":", 1)
                if k.strip().lower() == "sec-websocket-accept":
                    got = v.strip()
        if not hmac.compare_digest(got, want):
            raise ConnectionError("el sıkışma doğrulanamadı")
        self.buf = bytearray(rest)
        self.q = _queue.Queue()
        self.outq = collections.deque()   # çerçevelenmiş, sıradaki gönderimler
        self.out_n = 0                    # kuyrukta + yarım kalan bayt
        self._nlock = threading.Lock()
        self._cur = None                  # SSL yeniden denemesi için aynı parça
        self.alive = True
        self.reason = ""
        self.last_rx = time.time()
        self._frag_op, self._frag = None, bytearray()
        try:
            self._wr, self._ww = _socket.socketpair()
            self._wr.setblocking(False)
            self._ww.setblocking(False)
        except Exception:
            self._wr = self._ww = None
        sock.setblocking(False)
        self.th = threading.Thread(target=self._io, daemon=True)
        self.th.start()

    # ---- G/Ç döngüsü ----
    def _io(self):
        import select as _select
        sock = self.sock
        try:
            if self.buf:
                self._parse()
            while self.alive:
                rl = [sock] + ([self._wr] if self._wr is not None else [])
                wl = [sock] if (self._cur is not None or self.outq) else []
                pend = self.secure and sock.pending() > 0
                r, w, _ = _select.select(rl, wl, [], 0 if pend else 0.05)
                if self._wr is not None and self._wr in r:
                    try:
                        while self._wr.recv(4096):
                            pass
                    except (BlockingIOError, InterruptedError, OSError):
                        pass
                if sock in r or pend:
                    self._read_some()
                    self._parse()
                if sock in w:
                    self._write_some()
                if time.time() - self.last_rx > 75.0:
                    raise ConnectionError("zaman aşımı")
        except Exception as e:
            self.reason = self.reason or str(e)[:80]
        self.alive = False
        self.q.put(("closed", self.reason))
        for s_ in (self.sock, self._wr, self._ww):
            try:
                if s_ is not None:
                    s_.close()
            except Exception:
                pass

    def _read_some(self):
        for _ in range(64):
            try:
                chunk = self.sock.recv(65536)
            except (BlockingIOError, InterruptedError):
                return
            except _ssl.SSLWantReadError:
                return
            except _ssl.SSLWantWriteError:
                return
            if not chunk:
                raise ConnectionError("bağlantı kapandı")
            self.buf += chunk
            self.last_rx = time.time()
            if len(self.buf) > 4 * COOP_MAX_IN:
                return                    # önce çözülsün

    def _write_some(self):
        for _ in range(16):
            if self._cur is None:
                if not self.outq:
                    return
                frame = self.outq[0]
                if len(frame) <= self.CHUNK:
                    self.outq.popleft()
                    self._cur = frame
                else:
                    self._cur = frame[:self.CHUNK]
                    self.outq[0] = frame[self.CHUNK:]
            try:
                n = self.sock.send(self._cur)
            except (BlockingIOError, InterruptedError, _ssl.SSLWantWriteError, _ssl.SSLWantReadError):
                return                    # aynı parça sonra yeniden denenir
            if n <= 0:
                return
            with self._nlock:
                self.out_n -= n
            self._cur = self._cur[n:] if n < len(self._cur) else None

    def _parse(self):
        buf = self.buf
        while True:
            if len(buf) < 2:
                return
            b0, b1 = buf[0], buf[1]
            fin = b0 & 0x80
            op = b0 & 0x0F
            masked = b1 & 0x80
            n = b1 & 0x7F
            i = 2
            if n == 126:
                if len(buf) < 4:
                    return
                n = int.from_bytes(buf[2:4], "big")
                i = 4
            elif n == 127:
                if len(buf) < 10:
                    return
                n = int.from_bytes(buf[2:10], "big")
                i = 10
            if n > COOP_MAX_IN:
                raise ConnectionError("mesaj çok büyük")
            mask = None
            if masked:
                if len(buf) < i + 4:
                    return
                mask = bytes(buf[i:i + 4])
                i += 4
            if len(buf) < i + n:
                return
            data = bytes(buf[i:i + n])
            del buf[:i + n]
            if mask:
                data = _ws_mask(data, mask)
            if op == 0x8:
                self.reason = "kapandı"
                raise ConnectionError("kapandı")
            if op == 0x9:
                self._queue_frame(0xA, data)
                continue
            if op == 0xA:
                continue
            if op in (0x1, 0x2):
                if fin:
                    self.q.put(("t" if op == 1 else "b", data))
                else:
                    self._frag_op, self._frag = op, bytearray(data)
            elif op == 0x0 and self._frag_op is not None:
                self._frag += data
                if len(self._frag) > COOP_MAX_IN:
                    raise ConnectionError("mesaj çok büyük")
                if fin:
                    self.q.put(("t" if self._frag_op == 1 else "b", bytes(self._frag)))
                    self._frag_op, self._frag = None, bytearray()

    # ---- yazma (yalnız kuyruğa koyar) ----
    def _queue_frame(self, op, data):
        n = len(data)
        head = bytearray([0x80 | op])
        if n < 126:
            head.append(0x80 | n)
        elif n < 65536:
            head.append(0x80 | 126)
            head += n.to_bytes(2, "big")
        else:
            head.append(0x80 | 127)
            head += n.to_bytes(8, "big")
        mask = os.urandom(4)
        head += mask
        frame = bytes(head) + (_ws_mask(data, mask) if n else b"")
        with self._nlock:
            self.out_n += len(frame)
        self.outq.append(frame)
        if self._ww is not None:
            try:
                self._ww.send(b"x")
            except Exception:
                pass

    def pending(self):
        """Henüz hatta çıkmamış bayt (yerel gönderme birikmesi)."""
        return max(0, self.out_n)

    def send(self, data):
        if not self.alive:
            return False
        if self.out_n > 4 * 1024 * 1024:
            # hat tamamen tıkandı: bağlantı ölü sayılır (yeniden bağlanılır)
            self.alive = False
            self.reason = "gönderme tıkandı"
            return False
        if isinstance(data, str):
            self._queue_frame(0x1, data.encode("utf-8"))
        else:
            self._queue_frame(0x2, bytes(data))
        return True

    def close(self):
        if self.alive:
            try:
                self._queue_frame(0x8, b"\x03\xe8")
                t_end = time.time() + 0.3
                while (self.outq or self._cur is not None) and time.time() < t_end and self.th.is_alive():
                    time.sleep(0.01)
            except Exception:
                pass
        self.alive = False
        if self._ww is not None:
            try:
                self._ww.send(b"x")
            except Exception:
                pass


def _ws_mask(data, mask):
    """Büyük websocket gövdesini hızlı maskeler (int xor ile)."""
    n = len(data)
    m = int.from_bytes((mask * (n // 4 + 1))[:n], "big")
    return (int.from_bytes(data, "big") ^ m).to_bytes(n, "big")


class CoopLink:
    """Oda kurma / katılma + websocket bağlantısı + mesaj kodlama."""

    def __init__(self, app):
        self.app = app
        self.role = None             # "host" | "guest"
        self.state = "idle"          # idle | busy | lobby | error | closed
        self.error = ""
        self.code = ""
        self.key = ""
        self.host_name = ""
        self.guest_name = ""
        self.peer_on = False
        self.ws = None
        self.inbox = []              # (tür, veri) - ana döngü boşaltır
        self._lock = threading.Lock()
        self._comp = None
        self._dec = None
        self.lost_t = None           # bağlantının koptuğu an (yeniden deneme için)
        self.bytes_in = 0
        self.bytes_out = 0
        self.closed_by_user = False
        self.stream_bad = False      # sıkıştırma akışı koptu: tam görüntü gerek
        self._part = None            # parçalı mesajın açılmış kısmı
        self.down_since = None       # odaya en son ne zamandan beri ulaşamıyoruz
        self.room_gone = False       # sunucu: oda yok / kapandı
        self.rtt_srv = 0.0           # sunucuya gidiş-dönüş (sn)
        self._ping_t = 0.0
        self._ping_sent = 0.0

    # ---- http ----
    def _auth_payload(self, **extra):
        acc = self.app.account
        p = {"token": acc.token, "device": device_id(), "device_legacy": device_id_legacy(),
             "ver": GAME_VERSION}
        p.update(extra)
        return p

    def _http(self, path, payload, timeout=25):
        data = json.dumps(payload).encode("utf-8")
        req = urllib.request.Request(ONLINE_API_URL + path, data=data,
                                     headers={"Content-Type": "application/json",
                                              "Accept": "application/json"}, method="POST")
        try:
            with urllib.request.urlopen(req, timeout=timeout) as r:
                return json.loads(r.read(64 * 1024).decode("utf-8") or "{}")
        except urllib.error.HTTPError as e:
            try:
                body = json.loads(e.read(16 * 1024).decode("utf-8") or "{}")
            except Exception:
                body = {}
            return {"success": False, "error": str(body.get("error") or "sunucu hatası %d" % e.code)}

    def _ws_url(self):
        base = ONLINE_API_URL
        if base.startswith("https://"):
            base = "wss://" + base[len("https://"):]
        elif base.startswith("http://"):
            base = "ws://" + base[len("http://"):]
        return base + "/coop/ws?" + urllib.parse.urlencode({"code": self.code, "key": self.key})

    def _bg(self, fn, *a):
        self.state = "busy"
        self.error = ""

        def run():
            try:
                fn(*a)
            except Exception as e:
                self.state = "error"
                self.error = "%s (%s)" % (L("coop.err_net"), net_error_kind(e))
        threading.Thread(target=run, daemon=True).start()

    def create(self):
        self.role = "host"
        self._bg(self._do_create)

    def join(self, code):
        self.role = "guest"
        self._bg(self._do_join, code)

    def _wake(self):
        # Render'ın uyuyan sunucusu ilk istekte ~1 dk uyanır: önce durum ucu.
        try:
            req = urllib.request.Request(ONLINE_API_URL + "/auth/status", headers={"Accept": "application/json"})
            with urllib.request.urlopen(req, timeout=60) as r:
                r.read(2048)
        except Exception:
            pass

    def _do_create(self):
        self._wake()
        res = self._http("/coop/create", self._auth_payload())
        if not res.get("success"):
            self.state, self.error = "error", str(res.get("error") or L("coop.err_net"))
            return
        self.code = str(res.get("code") or "")[:6]
        self.key = str(res.get("key") or "")[:64]
        self.host_name = str(res.get("name") or "")[:14]
        self._connect()

    def _do_join(self, code):
        self._wake()
        res = self._http("/coop/join", self._auth_payload(code=code))
        if not res.get("success"):
            self.state, self.error = "error", str(res.get("error") or L("coop.err_net"))
            return
        self.code = str(res.get("code") or "")[:6]
        self.key = str(res.get("key") or "")[:64]
        self.host_name = str(res.get("host") or "")[:14]
        self.guest_name = str(res.get("name") or "")[:14]
        self._connect()

    def _connect(self):
        ws = CoopWS(self._ws_url())
        with self._lock:
            old, self.ws = self.ws, ws
        if old is not None:
            old.close()
        self._comp = None
        self._dec = None
        self._part = None
        self.lost_t = None
        self.state = "lobby"

    def reconnect(self):
        """Kopan bağlantıyı aynı biletle yeniden kurmayı dener (arka planda)."""
        if self.state == "busy" or not self.key:
            return

        def run():
            try:
                self._connect()
            except Exception:
                self.state = "lobby"     # yeniden denenecek
        self.state = "busy"
        threading.Thread(target=run, daemon=True).start()

    def leave(self):
        """Odadan çık (ev sahibiyse oda kapanır)."""
        self.closed_by_user = True
        code, key = self.code, self.key
        ws = self.ws
        if ws is not None:
            try:
                self.send({"t": "bye"})
            except Exception:
                pass
            self.ws = None
            ws.close()
        self.state = "closed"
        if code and key:
            def run():
                try:
                    self._http("/coop/leave", {"code": code, "key": key}, timeout=10)
                except Exception:
                    pass
            threading.Thread(target=run, daemon=True).start()

    # ---- mesajlar ----
    def connected(self):
        return self.ws is not None and self.ws.alive

    def send(self, obj, stream=False):
        ws = self.ws
        if ws is None or not ws.alive:
            return False
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        if stream:
            new = self._comp is None
            if new:
                self._comp = _zlib.compressobj(6)
            body = self._comp.compress(raw) + self._comp.flush(_zlib.Z_SYNC_FLUSH)
            parts = [body[i:i + COOP_PART] for i in range(0, len(body), COOP_PART)] or [b""]
            ok = True
            for j, part in enumerate(parts):
                last = j == len(parts) - 1
                if j == 0 and new:
                    head = b"K" if last else b"k"
                else:
                    head = b"Z" if last else b"z"
                self.bytes_out += len(part) + 1
                ok = ws.send(head + part) and ok
            if not ok:
                self._comp = None        # yarım kalan akış: sonraki mesaj baştan
            return ok
        data = b"J" + raw
        self.bytes_out += len(data)
        return ws.send(data)

    def pending(self):
        ws = self.ws
        return ws.pending() if ws is not None and ws.alive else 0

    def ping_tick(self, dt):
        """Sunucuya 3 sn'de bir 'ping' (gecikme ölçümü + canlı tutma)."""
        self._ping_t -= dt
        if self._ping_t <= 0 and self.connected():
            self._ping_t = 3.0
            self._ping_sent = time.time()
            try:
                self.ws.send("ping")
            except Exception:
                pass

    def reset_stream(self):
        """Karşı taraf yeniden bağlandı: sıkıştırma akışı baştan başlasın."""
        self._comp = None

    def poll(self):
        """Gelen mesajları çözer."""
        out = []
        ws = self.ws
        if ws is None:
            return out
        for _ in range(400):
            try:
                kind, data = ws.q.get_nowait()
            except _queue.Empty:
                break
            if kind == "closed":
                if self.ws is ws:
                    self.lost_t = time.time()
                out.append(("closed", data))
                continue
            self.bytes_in += len(data)
            if kind == "t":
                try:
                    msg = json.loads(data.decode("utf-8")[:8192])
                except Exception:
                    continue
                if isinstance(msg, dict) and msg.get("t") == "srv":
                    ev = msg.get("ev")
                    if ev == "pong" and self._ping_sent:
                        self.rtt_srv = max(0.0, min(9.0, time.time() - self._ping_sent))
                        self._ping_sent = 0.0
                        continue
                    if ev == "hello":
                        self.down_since = None
                        self.room_gone = False
                    elif ev == "closed":
                        self.room_gone = True
                    out.append(("srv", msg))
                continue
            msg = self._decode(data)
            if isinstance(msg, dict):
                out.append(("msg", msg))
        return out

    def _decode(self, data):
        if not data:
            return None
        head, body = data[:1], data[1:]
        try:
            if head == b"J":
                raw = body
            elif head in (b"K", b"Z", b"k", b"z"):
                if head in (b"K", b"k"):
                    self._dec = _zlib.decompressobj()
                    self._part = None
                    self.stream_bad = False
                elif self._dec is None or self.stream_bad:
                    # akışın ortası: başı kaybolmuşsa çözülemez, tam görüntü
                    # beklenir
                    self.stream_bad = True
                    return None
                room = COOP_MAX_RAW - (len(self._part) if self._part else 0)
                raw = self._dec.decompress(body, max(1, room))
                if self._dec.unconsumed_tail:
                    raise ValueError("çok büyük")      # zip bombası / bozuk akış
                if head in (b"k", b"z"):
                    self._part = (self._part or b"") + raw
                    return None
                if self._part is not None:
                    raw, self._part = self._part + raw, None
            else:
                return None
            if len(raw) > COOP_MAX_RAW:
                return None
            return json.loads(raw.decode("utf-8"))
        except Exception:
            if head != b"J":
                self._dec = None
                self._part = None
                self.stream_bad = True
            return None

