class App:
    def __init__(self, shadow_of=None):
        # gölge kip: shadow_of verilirse bu App gerçek oyunun yanında çalışan
        # ikinci bir örnektir.
        self.shadow = shadow_of is not None
        if not self.shadow:
            pygame.init()
            self.save = SaveManager()
            MASTERY_SAVE[0] = self.save      # Player ustalığı buradan okur
            global audio
            audio = AudioManager(self.save.data["settings"])
            self.steam = SteamBridge()
        else:
            self.save = _AdSave(shadow_of.save.data)
            self.steam = _NullSteam()
        self.ach = AchievementManager(self.save, self.steam)
        # Eski kayıtlarda hak edilmiş ama hiç açılmamış başarımları aç.
        self.ach.check_stats()
        if not self.shadow:
            self.display = Display(self.save)
            # windows imleci gizli: oyun kendi nişangahını/okunu çiziyor.
            # Sistem imleci açık kalsaydı nişangahın yanında ikinci bir ok
            # görünürdü.
            try:
                pygame.mouse.set_visible(False)
            except Exception:
                pass
        else:
            self.display = _TourDisplay()
        self.clock = pygame.time.Clock()
        self.bg = Background()
        self.t = 0.0
        self.state = STATE_MENU
        self.prev_state = STATE_MENU
        self.run = None
        self.levelup_ui = LevelUpOverlay()
        self.curse_ui = CurseOverlay()
        self.merchant_ui = MerchantOverlay()
        self.restart_hold = 0.0         # oyunda R basılı tutma süresi
        self.restart_armed = False
        self.shop_ui = RunShopOverlay()
        # L ile açılan sol alt sohbet/komut kutusu (hile kodu da buradan).
        self.chat = ChatConsole()
        self.online = OnlineClient(ONLINE_API_URL) if not self.shadow else _TourOnline()
        # ---- hesap ----
        self.account = (AccountClient(ONLINE_API_URL, self.save) if not self.shadow
                        else _TourAccount())
        self.key_waiting = None       # tuş atama: hangi eylem tuş bekliyor
        self.key_error = ""           # "bu tuş zaten kullanılıyor" gibi
        self.login_mode = "in"        # "in" = giriş, "up" = kayıt
        self.login_fields = {"user": "", "password": "", "email": "", "newpw": "", "code": ""}
        self.login_focus = "user"     # odaklı kutu
        self.contact = None           # iletişim penceresi (ContactForm)
        self.login_caret = 0.0
        self.running = True
        self.name_input = self.save.data.get("settings", {}).get("player_name", "")
        self.pending_board_rank = -1
        self.online_submit_status = None
        self.selected_skin = self.save.equipped_skin_id()
        self.diff = self.save.data.get("settings", {}).get("difficulty", "normal")
        self.show_fps = CFG["fps"]
        self.fps_smpl = 60.0
        self.ach_scroll = 0.0
        self.ach_filter = "all"       # all | got | locked | near
        self.ach_detail = None        # tıklanan başarımın anahtarı (detay penceresi)
        self.ach_detail_t = 0.0       # detay penceresi açılma animasyonu (0..1)
        self.skin_scroll = 0.0
        self.detail_skin_id = None
        self.cosmetic_scroll = 0.0
        self.cosmetic_tab = "hat"
        self.book_scroll = 0.0
        self.book_filter = "all"      # all | owned | locked
        self.book_detail = None       # tıklanan kitabın anahtarı (okuma penceresi)
        self.book_detail_t = 0.0      # okuma penceresi açılma animasyonu (0..1)
        self.book_toast = ""          # "kapatıldı / açıldı" bildirimi
        self.book_toast_t = 0.0
        # ---- silahlık ekranı ----
        self.weapon_scroll = 0.0
        self.weapon_filter = "all"    # all | owned | locked | muted
        self.weapon_detail = None     # açılan silahın anahtarı
        self.weapon_detail_t = 0.0
        self.weapon_toast = ""
        self.weapon_toast_t = 0.0
        self.gem_card_anim = 0.0      # elmas marketi kartı hover animasyonu
        self.gem_card_was_hover = False
        self.purchase = PurchaseBridge(self.steam, self.account,
                                       api_url="" if self.shadow else PURCHASE_API_URL)
        self.gem_msg = None           # satın alma sonucu bildirimi
        self.gem_msg_timer = 0.0
        self.gem_msg_ok = True
        self.store_tab = "free"       # mağaza sekmesi: free | gems | skins | pets
        # ---- ücretsiz elmas (reklam + günlük hediye) ----
