def _app_coop_play(self, dt, keys, mouse_pos, mouse_down, bonk_pressed, dash_pressed,
                   use_pressed, clicked, stats_pressed):
    """2 kişilikte update_play: girdi toplanır, oturum işler, çizilir."""
    run = self.run
    co = self.coop
    btn = stats_button_rect()
    over_ui = btn.collidepoint(mouse_pos)
    if stats_pressed or (clicked and over_ui):
        run.show_stats = not run.show_stats
        sfx("click", 0.5, 0.0)
    if over_ui:
        mouse_down = False
    inp = self.gather_input(keys)
    inp["mouse_down"] = mouse_down and not self.chat.open
    inp["bonk_pressed"] = bonk_pressed
    inp["dash_pressed"] = dash_pressed
    inp["use_pressed"] = use_pressed
    if self.pad.ok:
        rx, ry = self.pad.right_stick()
        if abs(rx) + abs(ry) > 0.02:
            psx, psy = run.world_to_screen(run.player.x, run.player.y)
            l = math.hypot(rx, ry) or 1.0
            mouse_pos = (psx + rx / l * PAD_AIM_RADIUS, psy + ry / l * PAD_AIM_RADIUS)
    ax, ay = run.screen_to_world(mouse_pos[0], mouse_pos[1])
    inp["aim_x"], inp["aim_y"] = ax, ay
    if self.chat.open:
        inp = {"aim_x": ax, "aim_y": ay}
    co.tick(dt, inp)
    if self.state != STATE_PLAY or self.run is not run:
        return
    offset = run.fx.get_shake_offset()
    canvas = self.display.canvas
    self._draw_run_frame(canvas, aim_pos=mouse_pos, offset=offset)
    _draw_coop_overlay(canvas, run, co, self.t)
    # pencereler (oyun durmaz)
    if run.want_open_shop:
        run.want_open_shop = False
        run.open_shop()
        self.state = STATE_RUN_SHOP
        return
    if run.player.alive and run.pending_levelups > 0:
        if not run.levelup_choices and not run.is_guest:
            run.start_levelup_choice()
            if not run.levelup_choices:
                run.pending_levelups = 0
        if run.levelup_choices:
            self.state = STATE_LEVELUP
            return
    mine = 1 if run.is_guest else 0
    if run.player.alive and run.curse_offers and run.curse_owner == mine:
        self.state = STATE_CURSE
        return
    if run.player.alive and run.merchant_open:
        self.merchant_ui.reset()
        self.state = STATE_MERCHANT


def _app_coop_overlay_tick(self, dt):
    """Seviye / market / tüccar / mağara / mola pencereleri açıkken de koşu işler (2 kişilikte oyun durmaz)."""
    co = self.coop
    if co is None or co.phase != "play" or self.run is not co.run:
        return
    menu = self.state in (STATE_LEVELUP, STATE_RUN_SHOP, STATE_MERCHANT, STATE_CURSE)
    run = self.run
    co.tick(dt, {"aim_x": run.player.x, "aim_y": run.player.y - 1}, menu=menu)
    if co.phase == "end":
        self.state = STATE_COOP_END


